1	sqlserver	execute	Kill sleeping sessions with open transactions idle beyond threshold	{"sql": "DECLARE @session_id INT;\\nDECLARE session_cursor CURSOR FOR\\n  SELECT session_id FROM sys.dm_exec_sessions\\n  WHERE status = 'sleeping'\\n    AND open_transaction_count > 0\\n    AND is_user_process = 1\\n    AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > @threshold_minutes;\\nOPEN session_cursor;\\nFETCH NEXT FROM session_cursor INTO @session_id;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  EXEC('KILL ' + @session_id);\\n  FETCH NEXT FROM session_cursor INTO @session_id;\\nEND;\\nCLOSE session_cursor;\\nDEALLOCATE session_cursor;", "parameters": ["threshold_minutes"], "description": "Iterates through sleeping sessions with open transactions idle longer than the threshold and kills each one."}	null	medium	t	f	00:01:00	2026-02-24 13:10:27.094602
