79	sqlserver	execute	Bring offline databases back online	{"sql": "-- For each database in OFFLINE or RECOVERY_PENDING state:\\nALTER DATABASE [$(database_name)] SET ONLINE;\\n\\n-- To generate statements for all affected databases:\\nSELECT 'ALTER DATABASE [' + name + '] SET ONLINE;' AS fix_sql\\nFROM sys.databases\\nWHERE state_desc NOT IN ('ONLINE') AND database_id > 4;", "parameters": ["database_name"], "description": "Brings each non-online user database back online after storage reconnection. SQL Server will run recovery on each database."}	{"sql": "ALTER DATABASE [$(database_name)] SET OFFLINE;", "description": "Take database offline again if errors occur during recovery."}	medium	t	t	00:15:00	2026-02-24 13:10:27.102971
80	sqlserver	execute	Check I/O stalls after storage reconnection	{"sql": "SELECT DB_NAME(database_id) AS db_name,\\n       file_id,\\n       io_stall_read_ms / NULLIF(num_of_reads, 0) AS avg_read_stall_ms,\\n       io_stall_write_ms / NULLIF(num_of_writes, 0) AS avg_write_stall_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL)\\nWHERE (io_stall_read_ms / NULLIF(num_of_reads, 0) > 50\\n   OR  io_stall_write_ms / NULLIF(num_of_writes, 0) > 50)\\nORDER BY io_stall_read_ms DESC;", "parameters": [], "description": "Measures post-reconnection I/O stall latency to confirm the storage path is performing normally."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.102972
