84	sqlserver	execute	Resume AG data movement on disconnected databases	{"sql": "-- Resume data movement on the secondary replica for all suspended databases:\\nSELECT 'ALTER DATABASE [' + db_name + '] SET HADR RESUME;' AS fix_sql\\nFROM (\\n  SELECT DB_NAME(database_id) AS db_name\\n  FROM sys.dm_hadr_database_replica_states\\n  WHERE is_suspended = 1\\n) t;\\n\\n-- Execute for each database:\\nALTER DATABASE [$(database_name)] SET HADR RESUME;", "parameters": ["database_name"], "description": "Resumes HADR synchronization on databases that were suspended due to the network outage."}	{"sql": "ALTER DATABASE [$(database_name)] SET HADR SUSPEND;", "description": "Suspend HADR if resuming causes unexpected issues."}	medium	t	t	00:05:00	2026-02-24 13:10:27.102975
