85	sqlserver	configure	Tune cluster heartbeat timeout to tolerate transient network blips	{"sql": "-- Run in PowerShell on the cluster:\\n-- (Get-Cluster).SameSubnetDelay = 1000        -- ms between heartbeats (default 1000)\\n-- (Get-Cluster).SameSubnetThreshold = 10      -- missed heartbeats before failover (default 5)\\n-- (Get-Cluster).CrossSubnetDelay = 1000\\n-- (Get-Cluster).CrossSubnetThreshold = 10\\n\\n-- View current settings:\\n-- Get-Cluster | Select-Object SameSubnetDelay, SameSubnetThreshold, CrossSubnetDelay, CrossSubnetThreshold", "parameters": [], "description": "Increases the cluster heartbeat missed-count threshold to tolerate brief network blips without triggering a failover. Setting threshold to 10 allows ~10 seconds of network loss before failover."}	{"sql": "-- (Get-Cluster).SameSubnetThreshold = 5\\n-- (Get-Cluster).CrossSubnetThreshold = 5", "description": "Revert heartbeat threshold back to the default value of 5."}	medium	t	t	00:05:00	2026-02-24 13:10:27.102975
86	sqlserver	verify	Verify all AG replicas are connected and synchronizing	{"sql": "SELECT ag.name AS ag_name,\\n       ar.replica_server_name,\\n       ars.connected_state_desc,\\n       ars.synchronization_health_desc,\\n       ars.role_desc,\\n       drs.synchronization_state_desc,\\n       drs.log_send_queue_size,\\n       drs.redo_queue_size\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ars.replica_id = drs.replica_id\\nORDER BY ag.name, ar.replica_server_name;", "parameters": [], "description": "Confirms all AG replicas are CONNECTED and HEALTHY, and database-level synchronization queues are draining."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.102976
87	sqlserver	execute	Document current configuration values before changes	{"sql": "SELECT name, CAST(value AS bigint) AS configured_value, CAST(value_in_use AS bigint) AS running_value,\\n       CAST(minimum AS bigint) AS min_val, CAST(maximum AS bigint) AS max_val,\\n       description, is_dynamic, is_advanced\\nFROM sys.configurations\\nORDER BY name;", "parameters": [], "description": "Captures a full snapshot of all configuration values before any changes are made."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.102977
88	sqlserver	configure	Set max server memory to safe value leaving OS headroom	{"sql": "-- Safe formula: total_RAM_MB minus 10% or 4096 MB, whichever is larger\\n-- For a 64 GB server: 65536 - 4096 = 61440 MB\\nEXEC sp_configure 'show advanced options', 1;\\nRECONFIGURE;\\nEXEC sp_configure 'max server memory (MB)', $(safe_max_memory_mb);\\nRECONFIGURE;", "parameters": ["safe_max_memory_mb"], "description": "Sets max server memory to leave adequate memory for the OS, preventing memory pressure that causes crashes."}	{"sql": "EXEC sp_configure 'max server memory (MB)', $(original_value);\\nRECONFIGURE;", "description": "Restore the original max server memory value."}	medium	t	t	00:01:00	2026-02-24 13:10:27.102978
89	sqlserver	configure	Reset max degree of parallelism to a safe value	{"sql": "-- Recommended: min(8, number_of_logical_cores / 2) or follow NUMA topology\\n-- Safe default for most servers: MAXDOP = 8\\nEXEC sp_configure 'max degree of parallelism', $(safe_maxdop);\\nRECONFIGURE;", "parameters": ["safe_maxdop"], "description": "Sets MAXDOP to prevent runaway parallelism from consuming all CPU cores on large NUMA servers."}	{"sql": "EXEC sp_configure 'max degree of parallelism', $(original_value);\\nRECONFIGURE;", "description": "Restore original MAXDOP value."}	low	t	t	00:01:00	2026-02-24 13:10:27.102978
