124	sqlserver	verify	Verify no file locking errors in subsequent scheduled backup runs	{"sql": "SELECT TOP 5 j.name, h.run_date, h.run_status, h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE j.name LIKE '%backup%'\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day,-3,GETDATE()),112))\\nORDER BY h.run_date DESC, h.run_time DESC;\\n\\nEXEC sp_readerrorlog 0, 1, N'operating system error 32';\\nEXEC sp_readerrorlog 0, 1, N'operating system error 33';", "parameters": [], "description": "Checks recent backup job history and error log for OS error 32 (sharing violation) or 33 (lock violation) messages."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.103005
