130	sqlserver	execute	Identify stale backup credentials and proxy accounts	{"sql": "-- Check SQL Server credential objects:\\nSELECT credential_id, name, credential_identity, create_date, modify_date\\nFROM sys.credentials\\nWHERE name LIKE '%backup%' OR name LIKE '%storage%' OR name LIKE '%blob%'\\nORDER BY modify_date;\\n\\n-- Check SQL Agent proxy accounts:\\nSELECT p.proxy_id, p.name, p.credential_id, p.enabled,\\n       c.credential_identity, c.modify_date AS credential_last_updated\\nFROM msdb.dbo.sysproxies p\\nJOIN sys.credentials c ON p.credential_id = c.credential_id\\nORDER BY c.modify_date;", "parameters": [], "description": "Lists all credential and proxy objects related to backup operations with their last modification dates."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.103009
