173	sqlserver	configure	Configure backup job to stripe across multiple files to reduce per-file transfer risk	{"sql": "-- Modify the backup to stripe across multiple smaller files\\n-- Reduces impact of any single network cut during transfer\\nBACKUP DATABASE [@database_name]\\nTO DISK = N'@backup_path_1',\\n   DISK = N'@backup_path_2',\\n   DISK = N'@backup_path_3',\\n   DISK = N'@backup_path_4'\\nWITH CHECKSUM, COMPRESSION, STATS = 10;", "parameters": ["@database_name", "@backup_path_1", "@backup_path_2", "@backup_path_3", "@backup_path_4"], "description": "Striping the backup across multiple files improves throughput and means a network cut only invalidates one stripe — which SQL Server can detect via CHECKSUM rather than silently truncating the whole backup."}	{"sql": "-- Revert backup job to single file target by updating the job step command\\n-- Use SSMS Job Step editor or sp_update_jobstep to restore original command", "description": "Reverts the backup job step to single-file destination if striping causes issues."}	low	t	t	00:05:00	2026-02-24 13:10:27.115329
175	sqlserver	execute	Create Database Master Key on DR server if missing	{"sql": "-- Run on DR/validation server\\nIF NOT EXISTS (SELECT 1 FROM sys.symmetric_keys WHERE name = '##MS_DatabaseMasterKey##')\\nBEGIN\\n  CREATE MASTER KEY ENCRYPTION BY PASSWORD = N'@dr_master_key_password';\\nEND;", "parameters": ["@dr_master_key_password"], "description": "The DR server must have a Database Master Key in master before importing a certificate."}	{"sql": "DROP MASTER KEY;", "description": "Removes the master key from the DR server master database. Only execute if the import must be fully rolled back and no other certificates depend on this key."}	medium	t	t	00:01:00	2026-02-24 13:10:27.115331
