179	sqlserver	execute	Confirm version mismatch details for all affected databases	{"sql": "-- Run on the RESTORE TARGET server\\nSELECT bs.database_name,\\n  bs.software_major_version  AS backup_major,\\n  bs.software_minor_version  AS backup_minor,\\n  bs.software_build_version  AS backup_build,\\n  bs.backup_finish_date,\\n  SERVERPROPERTY('ProductMajorVersion') AS target_major,\\n  SERVERPROPERTY('ProductVersion')      AS target_version,\\n  SERVERPROPERTY('ProductLevel')        AS target_sp\\nFROM msdb.dbo.backupset bs\\nWHERE CAST(bs.software_major_version AS INT) >\\n      CAST(SERVERPROPERTY('ProductMajorVersion') AS INT)\\n  AND bs.backup_finish_date > DATEADD(day, -30, GETDATE())\\nORDER BY bs.backup_finish_date DESC;", "parameters": [], "description": "Lists all recent backups that cannot be restored on this server due to version incompatibility."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115335
