187	sqlserver	configure	Create SQL Agent maintenance job to purge old backup files from validation server	{"sql": "-- Use Maintenance Plan or custom job with EXEC master.sys.xp_delete_files\\n-- or SQL Server Maintenance Plan Cleanup Task\\n-- Example using sp_delete_backuphistory on a schedule:\\nEXEC msdb.dbo.sp_add_job\\n    @job_name = N'Purge Validation Server Backup History';\\n\\nEXEC msdb.dbo.sp_add_jobstep\\n    @job_name = N'Purge Validation Server Backup History',\\n    @step_name = N'Delete old backup history',\\n    @command = N'EXEC msdb.dbo.sp_delete_backuphistory @oldest_date = DATEADD(day, -14, GETDATE());';\\n\\nEXEC msdb.dbo.sp_add_schedule\\n    @schedule_name = N'Daily 1AM Cleanup',\\n    @freq_type = 4,\\n    @freq_interval = 1,\\n    @active_start_time = 10000;\\n\\nEXEC msdb.dbo.sp_attach_schedule\\n    @job_name = N'Purge Validation Server Backup History',\\n    @schedule_name = N'Daily 1AM Cleanup';\\n\\nEXEC msdb.dbo.sp_add_jobserver\\n    @job_name = N'Purge Validation Server Backup History';", "parameters": [], "description": "Automates daily msdb history cleanup on the validation server. Combine with OS-level file deletion via Maintenance Plan Cleanup Task for .bak files."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = N'Purge Validation Server Backup History';", "description": "Removes the cleanup job."}	low	t	t	00:05:00	2026-02-24 13:10:27.115344
188	sqlserver	execute	Enable backup compression server-wide	{"sql": "EXEC sp_configure 'backup compression default', 1;\\nRECONFIGURE;\\n\\n-- Verify\\nSELECT name, value_in_use\\nFROM sys.configurations\\nWHERE name = 'backup compression default';", "parameters": [], "description": "Enables backup compression by default, typically reducing backup size by 40-70% and improving throughput when network bandwidth is the bottleneck."}	{"sql": "EXEC sp_configure 'backup compression default', 0;\\nRECONFIGURE;", "description": "Disables backup compression default."}	low	t	t	00:01:00	2026-02-24 13:10:27.115345
189	sqlserver	configure	Configure MAXTRANSFERSIZE and BUFFERCOUNT to maximize backup throughput	{"sql": "-- Example backup command with tuned throughput parameters\\n-- MAXTRANSFERSIZE: 65536 (default) to 4194304 (4MB, maximum)\\n-- BUFFERCOUNT: calculated as (available_memory_mb / maxtransfersize_mb) -- typically 15-30\\nBACKUP DATABASE [@database_name]\\nTO DISK = N'@backup_path'\\nWITH COMPRESSION,\\n     MAXTRANSFERSIZE = 4194304,\\n     BUFFERCOUNT = 24,\\n     STATS = 10;", "parameters": ["@database_name", "@backup_path"], "description": "Larger MAXTRANSFERSIZE and increased BUFFERCOUNT reduce overhead per I/O operation, improving backup throughput for large databases."}	{"sql": "-- Revert to defaults by removing MAXTRANSFERSIZE and BUFFERCOUNT parameters from backup command", "description": "Remove MAXTRANSFERSIZE and BUFFERCOUNT from backup command to use defaults."}	low	f	t	00:05:00	2026-02-24 13:10:27.115347
190	sqlserver	configure	Reschedule backup jobs to low-traffic window if compression alone is insufficient	{"sql": "-- Identify current backup job schedule\\nSELECT j.name, s.active_start_time, s.freq_type, s.freq_interval\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nWHERE j.name LIKE '%backup%' OR j.name LIKE '%Backup%';\\n\\n-- Update schedule to 2AM (20000 in HHMMSS format)\\nEXEC msdb.dbo.sp_update_schedule\\n  @name = N'@backup_schedule_name',\\n  @active_start_time = 20000;", "parameters": ["@backup_schedule_name"], "description": "Moves the backup window to off-peak hours where network bandwidth competition is lower."}	{"sql": "EXEC msdb.dbo.sp_update_schedule\\n  @name = N'@backup_schedule_name',\\n  @active_start_time = @original_start_time;", "description": "Reverts the backup schedule to the original start time."}	low	t	t	00:05:00	2026-02-24 13:10:27.115348
191	sqlserver	verify	Verify improved backup throughput after changes	{"sql": "-- After next backup completes, compare throughput\\nSELECT TOP 5\\n  bs.database_name,\\n  bs.backup_start_date, bs.backup_finish_date,\\n  DATEDIFF(second, bs.backup_start_date, bs.backup_finish_date) AS duration_sec,\\n  CAST(bs.compressed_backup_size / 1048576.0 AS decimal(18,2)) AS compressed_mb,\\n  CAST(bs.compressed_backup_size / 1048576.0\\n    / NULLIF(DATEDIFF(second, bs.backup_start_date, bs.backup_finish_date), 0)\\n    AS decimal(10,2)) AS throughput_mb_sec\\nFROM msdb.dbo.backupset bs\\nWHERE bs.backup_finish_date > DATEADD(hour, -6, GETDATE())\\nORDER BY bs.backup_finish_date DESC;", "parameters": [], "description": "Compares throughput of the most recent backup against the pre-change baseline from detection."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115349
192	sqlserver	execute	Capture details of the stuck backup session before killing	{"sql": "SELECT r.session_id,\\n  r.command,\\n  r.status,\\n  r.start_time,\\n  DATEDIFF(minute, r.start_time, GETDATE()) AS running_minutes,\\n  r.percent_complete,\\n  r.estimated_completion_time / 60000.0 AS est_remaining_min,\\n  DB_NAME(r.database_id) AS database_name,\\n  s.login_name,\\n  s.program_name,\\n  s.host_name,\\n  t.text AS current_sql\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.command LIKE 'BACKUP%'\\n  AND DATEDIFF(minute, r.start_time, GETDATE()) > 60;", "parameters": [], "description": "Captures session_id, percent_complete, and SQL text of all backup sessions running more than 60 minutes. Record these before killing."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.11535
193	sqlserver	execute	Check for blocking waits on the stuck backup session	{"sql": "SELECT r.session_id,\\n  r.wait_type,\\n  r.wait_time / 1000.0 AS wait_sec,\\n  r.blocking_session_id,\\n  r.last_wait_type\\nFROM sys.dm_exec_requests r\\nWHERE r.command LIKE 'BACKUP%'\\n  AND DATEDIFF(minute, r.start_time, GETDATE()) > 60;", "parameters": [], "description": "Checks if the backup is stuck due to a blocking session or an I/O wait. If blocking_session_id is non-zero, the blocker should be investigated first."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115351
