200	sqlserver	configure	Update AG backup preference to Primary if secondary lag is unresolvable in the backup window	{"sql": "-- Update the AG to prefer backups on the primary\\nALTER AVAILABILITY GROUP [@ag_name]\\n  MODIFY REPLICA ON N'@secondary_replica_name'\\n  WITH (BACKUP_PRIORITY = 0); -- 0 = never backup from this replica\\n\\n-- OR change the AG-level preference\\nALTER AVAILABILITY GROUP [@ag_name]\\n  SET (AUTOMATED_BACKUP_PREFERENCE = PRIMARY);", "parameters": ["@ag_name", "@secondary_replica_name"], "description": "Sets the AG backup preference to PRIMARY so backup jobs will always execute on the primary replica regardless of secondary lag."}	{"sql": "ALTER AVAILABILITY GROUP [@ag_name]\\n  SET (AUTOMATED_BACKUP_PREFERENCE = SECONDARY_ONLY);\\nALTER AVAILABILITY GROUP [@ag_name]\\n  MODIFY REPLICA ON N'@secondary_replica_name'\\n  WITH (BACKUP_PRIORITY = 50);", "description": "Reverts backup preference to secondary and restores default backup priority on the secondary replica."}	medium	t	t	00:05:00	2026-02-24 13:10:27.115368
201	sqlserver	execute	Resume redo on secondary if redo thread was stopped (Case A)	{"sql": "-- Run on secondary replica\\nALTER DATABASE [@database_name] SET HADR RESUME;\\n\\n-- Monitor redo recovery progress\\nSELECT DB_NAME(database_id) AS db, redo_queue_size, redo_rate,\\n  CAST(redo_queue_size / NULLIF(redo_rate, 0) / 60.0 AS decimal(10,1)) AS est_catchup_min\\nFROM sys.dm_hadr_database_replica_states\\nWHERE is_local = 1 AND is_primary_replica = 0;", "parameters": ["@database_name"], "description": "Resumes log redo on the secondary if it was suspended. Monitors catchup progress."}	{"sql": "ALTER DATABASE [@database_name] SET HADR SUSPEND;", "description": "Re-suspends the secondary if resume causes issues."}	low	f	t	00:05:00	2026-02-24 13:10:27.115369
202	sqlserver	verify	Verify replica lag is within acceptable RPO threshold	{"sql": "SELECT\\n  ag.name, ar.replica_server_name,\\n  DB_NAME(drs.database_id) AS database_name,\\n  DATEDIFF(second, drs.last_commit_time, GETDATE()) AS lag_seconds,\\n  drs.synchronization_state_desc,\\n  drs.redo_queue_size AS redo_queue_kb\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_local = 1\\n  AND drs.is_primary_replica = 0;", "parameters": [], "description": "Confirms replica lag is now within the RPO threshold and synchronization_state_desc = 'SYNCHRONIZED'."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115371
