223	sqlserver	verify	Verify backup target accessible and gaps closed	{"sql": "-- Confirm recent successful backups\\nSELECT database_name,\\n  MAX(backup_finish_date) AS last_backup,\\n  DATEDIFF(hour, MAX(backup_finish_date), GETDATE()) AS hours_since_last,\\n  physical_device_name\\nFROM msdb.dbo.backupset bs\\nJOIN msdb.dbo.backupmediafamily bmf ON bs.media_set_id = bmf.media_set_id\\nWHERE backup_finish_date > DATEADD(hour, -2, GETDATE())\\nGROUP BY database_name, physical_device_name\\nORDER BY last_backup DESC;", "parameters": [], "description": "Confirms successful backups have written to the storage target within the last 2 hours and RPO gaps are closed."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115394
224	sqlserver	verify	Confirm log chain break and identify affected databases	{"sql": "WITH log_chain AS (\\n  SELECT database_name, first_lsn, last_lsn, backup_start_date,\\n    LAG(last_lsn) OVER (PARTITION BY database_name ORDER BY backup_start_date) AS prev_last_lsn\\n  FROM msdb.dbo.backupset\\n  WHERE type = 'L' AND backup_start_date > DATEADD(day, -7, GETDATE())\\n)\\nSELECT database_name,\\n  backup_start_date AS gap_at,\\n  prev_last_lsn AS expected_first_lsn,\\n  first_lsn AS actual_first_lsn\\nFROM log_chain\\nWHERE prev_last_lsn IS NOT NULL\\n  AND first_lsn != prev_last_lsn\\nORDER BY database_name, backup_start_date;", "parameters": [], "description": "Identifies which databases have LSN discontinuities and when the break occurred."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115395
226	sqlserver	execute	Resume scheduled log backup jobs	{"sql": "-- Verify log backup jobs are enabled and running\\nSELECT j.name, j.enabled, h.run_date, h.run_status\\nFROM msdb.dbo.sysjobs j\\nLEFT JOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\n  AND h.step_id = 0\\nWHERE j.name LIKE '%log backup%'\\nORDER BY h.run_date DESC;\\n\\n-- If log backup job is not running, start it:\\nEXEC msdb.dbo.sp_start_job @job_name = N'<log_backup_job_name>';", "parameters": ["log_backup_job_name"], "description": "Ensures log backup jobs are running regularly to maintain the new log chain."}	null	low	t	f	00:05:00	2026-02-24 13:10:27.115397
227	sqlserver	configure	Restrict permissions to prevent manual backup file deletion	{"sql": "-- Audit who deleted the log file (check security event log or file audit):\\n-- Enable file system auditing on the backup target directory\\n\\n-- Revoke direct filesystem access from SQL Server service account on backup share\\n-- Grant only the backup agent service account write access\\n-- This is an OS-level configuration, not T-SQL.\\n\\n-- Optionally, implement a Maintenance Cleanup Task with a minimum retention:\\nEXEC msdb.dbo.sp_add_jobstep\\n  @job_id = <cleanup_job_id>,\\n  @step_name = N'Enforce log retention',\\n  @command = N'-- Delete log backups older than 72 hours only\\nDELETE FROM msdb.dbo.backupset\\nWHERE type = ''L''\\n  AND backup_finish_date < DATEADD(hour, -72, GETDATE())\\n  AND database_name = ''<database_name>'';';", "parameters": ["cleanup_job_id", "database_name"], "description": "Implements access controls and retention policy to prevent accidental deletion of log backup files below the minimum retention period."}	null	low	t	t	00:05:00	2026-02-24 13:10:27.115398
228	sqlserver	verify	Verify new log chain is intact	{"sql": "WITH log_chain AS (\\n  SELECT database_name, first_lsn, last_lsn, backup_start_date,\\n    LAG(last_lsn) OVER (PARTITION BY database_name ORDER BY backup_start_date) AS prev_last_lsn\\n  FROM msdb.dbo.backupset\\n  WHERE type IN ('D', 'L')\\n    AND backup_start_date > DATEADD(hour, -4, GETDATE())\\n)\\nSELECT database_name,\\n  COUNT(*) AS backup_count,\\n  SUM(CASE WHEN prev_last_lsn IS NOT NULL AND first_lsn != prev_last_lsn THEN 1 ELSE 0 END) AS gaps\\nFROM log_chain\\nGROUP BY database_name\\nHAVING SUM(CASE WHEN prev_last_lsn IS NOT NULL AND first_lsn != prev_last_lsn THEN 1 ELSE 0 END) = 0;", "parameters": [], "description": "Confirms the new backup chain has no LSN gaps. Expected: all databases show gaps = 0."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115399
229	sqlserver	verify	Assess transaction log sizes and disk space before changing recovery model	{"sql": "-- Check current log file sizes and free space\\nSELECT db.name, mf.name AS log_file,\\n  CAST(mf.size * 8.0 / 1024 AS decimal(10,2)) AS size_mb,\\n  CAST(FILEPROPERTY(mf.name, 'SpaceUsed') * 8.0 / 1024 AS decimal(10,2)) AS used_mb,\\n  db.recovery_model_desc\\nFROM sys.master_files mf\\nJOIN sys.databases db ON mf.database_id = db.database_id\\nWHERE mf.type = 1  -- log files\\n  AND db.recovery_model_desc = 'SIMPLE'\\n  AND db.database_id > 4;\\n\\n-- Check disk free space\\nEXEC xp_fixeddrives;", "parameters": [], "description": "Confirms current log file sizes and available disk space to ensure FULL recovery mode can be sustained."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.1154
259	sqlserver	execute	Capture current startup parameters and configuration baseline	{"sql": "-- Capture current startup parameters logged at startup\\nEXEC sp_readerrorlog 0, 1, N'Registry startup parameters';\\n\\n-- Capture all non-default sp_configure values\\nSELECT name, CAST(value AS BIGINT) AS configured_value,\\n  CAST(value_in_use AS BIGINT) AS running_value,\\n  is_dynamic, is_advanced\\nFROM sys.configurations\\nWHERE CAST(value AS BIGINT) <> CAST(value_in_use AS BIGINT)\\n  OR is_advanced = 1\\nORDER BY name;", "parameters": [], "description": "Captures the current state of startup parameters and sp_configure before making any changes. Save this output as your rollback reference."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115401
230	sqlserver	configure	Switch databases to FULL recovery model	{"sql": "-- Switch each affected database to FULL recovery\\n-- Replace <database_name> with actual database name\\nALTER DATABASE [<database_name>] SET RECOVERY FULL;\\n\\n-- Verify the change:\\nSELECT name, recovery_model_desc\\nFROM sys.databases\\nWHERE name = '<database_name>';", "parameters": ["database_name"], "description": "Changes the recovery model from SIMPLE to FULL. Must be done for each database identified in step 1. Run for each database individually."}	{"sql": "-- Revert to SIMPLE if log growth becomes unmanageable before backup schedule is set up\\nALTER DATABASE [<database_name>] SET RECOVERY SIMPLE;", "description": "Revert to SIMPLE recovery if log growth causes disk space issues before log backups can be configured."}	medium	t	t	00:01:00	2026-02-24 13:10:27.115402
233	sqlserver	verify	Verify FULL recovery model and log chain established	{"sql": "-- Confirm recovery model\\nSELECT name, recovery_model_desc, log_reuse_wait_desc\\nFROM sys.databases\\nWHERE database_id > 4 AND state_desc = 'ONLINE'\\nORDER BY name;\\n\\n-- Confirm log chain is established\\nSELECT database_name, type_desc,\\n  COUNT(*) AS backup_count,\\n  MIN(backup_start_date) AS chain_start,\\n  MAX(backup_finish_date) AS chain_end\\nFROM msdb.dbo.backupset\\nWHERE backup_start_date > DATEADD(hour, -2, GETDATE())\\nGROUP BY database_name, type_desc\\nORDER BY database_name, type_desc;", "parameters": [], "description": "Confirms databases are in FULL recovery model and have both a full backup and at least one log backup recorded within the last 2 hours."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115435
