234	sqlserver	verify	Assess log corruption severity and database accessibility	{"sql": "-- Check database and log file state\\nSELECT db.name, db.state_desc, db.log_reuse_wait_desc,\\n  mf.name AS log_file, mf.state_desc AS file_state\\nFROM sys.databases db\\nJOIN sys.master_files mf ON db.database_id = mf.database_id\\nWHERE mf.type = 1;\\n\\n-- Check error log for corruption messages\\nEXEC sp_readerrorlog 0, 1, N'corrupt';\\nEXEC sp_readerrorlog 0, 1, N'9002';\\nEXEC sp_readerrorlog 0, 1, N'823';\\nEXEC sp_readerrorlog 0, 1, N'824';", "parameters": [], "description": "Identifies the database state and severity of corruption. Error 823/824 = I/O error; 9002 = log full; state RECOVERY_PENDING or SUSPECT indicates severe corruption."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115437
239	sqlserver	verify	Measure clock drift between servers	{"sql": "-- Check SQL Server system time\\nSELECT @@SERVERNAME AS server_name,\\n  GETDATE() AS sql_server_time,\\n  GETUTCDATE() AS sql_server_utc;\\n\\n-- Check backup metadata timestamps vs actual server time\\nSELECT TOP 10 server_name, database_name,\\n  backup_start_date, backup_finish_date,\\n  DATEDIFF(second, backup_start_date, backup_finish_date) AS duration_sec\\nFROM msdb.dbo.backupset\\nWHERE backup_finish_date > DATEADD(day, -1, GETDATE())\\n  AND server_name != @@SERVERNAME\\nORDER BY backup_finish_date DESC;\\n\\n-- On each server, run via PowerShell to check NTP status:\\n-- w32tm /query /status", "parameters": [], "description": "Measures the clock difference between the SQL Server and backup server using backup metadata timestamps and current server time."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115467
240	sqlserver	configure	Force NTP resync on drifted servers	{"sql": "-- Run on each drifted server via PowerShell or Command Prompt:\\n-- w32tm /resync /force\\n-- w32tm /query /status\\n\\n-- Verify NTP sync source:\\n-- w32tm /query /source\\n\\n-- If W32tm is not configured, point to an NTP server:\\n-- w32tm /config /manualpeerlist:\\"time.windows.com\\" /syncfromflags:manual /reliable:YES /update\\n-- net stop w32tm && net start w32tm\\n-- w32tm /resync", "parameters": [], "description": "Forces immediate NTP resynchronization on the SQL Server and backup server. This is an OS-level operation, not T-SQL."}	null	low	t	t	00:05:00	2026-02-24 13:10:27.11547
241	sqlserver	execute	Remap PITR target time to correct LSN using drift offset	{"sql": "-- Find the LSN corresponding to the PITR target time, adjusted for drift\\n-- If target time is '2026-02-24 14:00:00' and server B was 10 minutes ahead,\\n-- the actual target on server A is '2026-02-24 13:50:00'\\n\\nDECLARE @target_time_adjusted datetime = DATEADD(MINUTE, -@drift_offset_minutes, @desired_pitr_time);\\n\\n-- Find the backup LSN that contains the adjusted target time\\nSELECT database_name, first_lsn, last_lsn,\\n  backup_start_date, backup_finish_date, type_desc\\nFROM msdb.dbo.backupset\\nWHERE database_name = '<database_name>'\\n  AND backup_start_date <= @target_time_adjusted\\n  AND backup_finish_date >= @target_time_adjusted\\n  AND type = 'L'\\nORDER BY backup_start_date;\\n\\n-- Use this LSN with RESTORE LOG ... STOPATLSN = <lsn>", "parameters": ["drift_offset_minutes", "desired_pitr_time", "database_name"], "description": "Calculates the correct LSN for the desired point-in-time by adjusting for the known clock drift offset."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115471
243	sqlserver	verify	Verify clocks are synchronized across servers	{"sql": "-- Verify SQL Server time is consistent with expected time\\nSELECT @@SERVERNAME, GETDATE() AS server_time, GETUTCDATE() AS utc_time;\\n\\n-- Verify recent backup timestamps look correct\\nSELECT TOP 5 server_name, database_name,\\n  backup_start_date, backup_finish_date,\\n  DATEDIFF(second, backup_start_date, backup_finish_date) AS duration_sec\\nFROM msdb.dbo.backupset\\nWHERE backup_finish_date > DATEADD(hour, -1, GETDATE())\\nORDER BY backup_finish_date DESC;", "parameters": [], "description": "Confirms server time is accurate and recent backup metadata timestamps align with expected real-world times."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115473
244	sqlserver	verify	Confirm which databases lack a valid full backup base	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  MAX(CASE WHEN bs.type = 'D' THEN bs.backup_finish_date END) AS last_full_backup,\\n  MAX(CASE WHEN bs.type = 'L' THEN bs.backup_finish_date END) AS last_log_backup,\\n  DATEDIFF(day, MAX(CASE WHEN bs.type = 'D' THEN bs.backup_finish_date END), GETDATE()) AS days_since_full,\\n  CAST(SUM(mf.size) * 8.0 / 1024 / 1024 AS decimal(10,2)) AS db_size_gb\\nFROM sys.databases d\\nLEFT JOIN msdb.dbo.backupset bs ON d.name = bs.database_name\\nLEFT JOIN sys.master_files mf ON d.database_id = mf.database_id AND mf.type = 0\\nWHERE d.database_id > 4 AND d.state_desc = 'ONLINE'\\nGROUP BY d.name, d.recovery_model_desc\\nHAVING MAX(CASE WHEN bs.type = 'D' THEN bs.backup_finish_date END) IS NULL\\n  OR DATEDIFF(day, MAX(CASE WHEN bs.type = 'D' THEN bs.backup_finish_date END), GETDATE()) > @max_full_age_days\\nORDER BY days_since_full DESC;", "parameters": ["max_full_age_days"], "description": "Identifies databases without a recent full backup and their current size, to plan backup execution order."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115475
458	sqlserver	verify	Confirm all connections use TLS 1.2 or higher after restart	{"sql": "SELECT c.protocol_type, c.encrypt_option, c.protocol_version,\\n  COUNT(*) AS connection_count\\nFROM sys.dm_exec_connections c\\nWHERE c.encrypt_option = 'TRUE'\\nGROUP BY c.protocol_type, c.encrypt_option, c.protocol_version;", "parameters": [], "description": "After OS restart, verifies all encrypted connections are using TLS 1.2 (protocol_version = 0x04000000) or higher."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115478
246	sqlserver	configure	Implement full backup retention policy to prevent premature deletion	{"sql": "-- Check current maintenance plan or cleanup task settings\\nSELECT j.name, js.command\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE j.name LIKE '%cleanup%' OR j.name LIKE '%maintenance%' OR j.name LIKE '%delete%'\\nORDER BY j.name;\\n\\n-- If using Maintenance Cleanup Task, ensure full backup retention is at minimum:\\n-- FULL backups: retain at least (log_retention_hours / 24) + 1 days\\n-- Example: if retaining 72 hours of logs, retain full backups for at least 4 days\\n\\n-- If using custom cleanup, update the threshold:\\n-- Replace any DELETE FROM backupset WHERE type='D' AND backup_finish_date < DATEADD(day,-X)\\n-- Ensure X >= (log_retention_days + 1)", "parameters": [], "description": "Reviews and updates backup cleanup jobs to ensure full backups are retained long enough to serve as the base for the retained log backup window."}	null	low	t	t	00:05:00	2026-02-24 13:10:27.115479
247	sqlserver	instruct	Add full backup age monitoring alert	{"sql": null, "parameters": [], "description": "Create a SQL Agent job that runs daily and alerts if any production database lacks a full backup within the retention threshold: (1) Query msdb.dbo.backupset for databases where last full backup age exceeds the policy maximum. (2) Send an email via Database Mail to the DBA team. (3) The alert job should fire before the log retention window expires — if full backups must be kept 7 days, alert at 5 days to allow remediation time. (4) Integrate with your monitoring platform (SCOM, Datadog, Zabbix) via the same query as a custom metric."}	null	low	f	t	2 days	2026-02-24 13:10:27.11548
