276	sqlserver	execute	Export configuration from each secondary replica for comparison	{"sql": "-- Run on each SECONDARY replica\\nSELECT\\n  SERVERPROPERTY('ServerName') AS server_name,\\n  'SECONDARY' AS replica_role,\\n  name AS config_name,\\n  CAST(value_in_use AS BIGINT) AS running_value\\nFROM sys.configurations\\nWHERE name IN (\\n  'max degree of parallelism',\\n  'cost threshold for parallelism',\\n  'max server memory (MB)',\\n  'min server memory (MB)',\\n  'max worker threads',\\n  'optimize for ad hoc workloads',\\n  'backup compression default',\\n  'blocked process threshold (s)'\\n)\\nORDER BY name;", "parameters": [], "description": "Captures each secondary replica's configuration for diff against the primary baseline."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115487
253	sqlserver	verify	Verify new fork log chain is intact and PITR is operational	{"sql": "WITH new_chain AS (\\n  SELECT database_name, type_desc, first_recovery_fork_guid,\\n    first_lsn, last_lsn, backup_start_date,\\n    LAG(last_lsn) OVER (PARTITION BY database_name ORDER BY backup_start_date) AS prev_last_lsn\\n  FROM msdb.dbo.backupset\\n  WHERE backup_start_date > DATEADD(hour, -4, GETDATE())\\n    AND type IN ('D', 'L')\\n)\\nSELECT database_name,\\n  COUNT(*) AS total_backups,\\n  SUM(CASE WHEN prev_last_lsn IS NOT NULL AND first_lsn != prev_last_lsn THEN 1 ELSE 0 END) AS chain_gaps\\nFROM new_chain\\nGROUP BY database_name\\nHAVING COUNT(*) > 1\\nORDER BY database_name;", "parameters": [], "description": "Confirms that the new recovery fork has at least a full backup + one log backup with no LSN gaps, establishing a clean PITR chain on the new timeline."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115488
254	sqlserver	verify	Assess current retention window and storage requirements	{"sql": "-- Current log backup retention window\\nSELECT database_name,\\n  MIN(backup_start_date) AS oldest_log_backup,\\n  MAX(backup_start_date) AS newest_log_backup,\\n  DATEDIFF(hour, MIN(backup_start_date), MAX(backup_start_date)) AS retention_hours,\\n  COUNT(*) AS log_backup_count,\\n  AVG(backup_size / 1048576.0) AS avg_backup_size_mb,\\n  SUM(backup_size / 1073741824.0) AS total_size_gb\\nFROM msdb.dbo.backupset\\nWHERE type = 'L'\\nGROUP BY database_name\\nORDER BY database_name;\\n\\n-- Check free space on backup target\\nEXEC xp_fixeddrives;", "parameters": [], "description": "Measures current retention window, backup frequency, average backup size, and available storage to plan the retention extension."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115489
257	sqlserver	execute	Retain any existing log backups that fall within the new window	{"sql": "-- Check if any log backups were recently deleted that should now be retained\\n-- This query shows gaps in the log chain that indicate deleted backups\\nWITH log_chain AS (\\n  SELECT database_name, first_lsn, last_lsn, backup_start_date,\\n    LAG(last_lsn) OVER (PARTITION BY database_name ORDER BY backup_start_date) AS prev_last_lsn\\n  FROM msdb.dbo.backupset\\n  WHERE type = 'L' AND backup_start_date > DATEADD(day, -@new_retention_days, GETDATE())\\n)\\nSELECT database_name, backup_start_date, first_lsn, prev_last_lsn\\nFROM log_chain\\nWHERE prev_last_lsn IS NOT NULL AND first_lsn != prev_last_lsn\\nORDER BY database_name, backup_start_date;\\n\\n-- If chain is broken due to deleted backups, a new full backup is required:\\n-- (See RC01 resolution path for chain rebuild procedure)", "parameters": ["new_retention_days"], "description": "Checks whether log backups already deleted within the new retention window have created chain gaps. If so, a new full backup must be taken to reset the chain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115493
