325	sqlserver	execute	Calculate safe production values based on server hardware	{"sql": "SELECT\\n  si.physical_memory_kb / 1024 AS physical_memory_mb,\\n  si.cpu_count AS logical_cpus,\\n  si.hyperthread_ratio,\\n  si.cpu_count / NULLIF(si.hyperthread_ratio, 0) AS physical_cores,\\n  (SELECT COUNT(DISTINCT parent_node_id)\\n   FROM sys.dm_os_schedulers\\n   WHERE status = 'VISIBLE ONLINE') AS numa_nodes,\\n  -- Recommended max memory: leave 10% or 2-4 GB for OS\\n  si.physical_memory_kb / 1024\\n    - CASE\\n        WHEN si.physical_memory_kb / 1024 < 4096 THEN 1024\\n        WHEN si.physical_memory_kb / 1024 < 16384 THEN 2048\\n        WHEN si.physical_memory_kb / 1024 < 65536 THEN 4096\\n        ELSE CAST(si.physical_memory_kb / 1024 * 0.1 AS INT)\\n      END AS recommended_max_memory_mb,\\n  -- Recommended MAXDOP: min(logical_cpus/numa_nodes, 8)\\n  CASE\\n    WHEN si.cpu_count / NULLIF(\\n      (SELECT COUNT(DISTINCT parent_node_id) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE'), 0) > 8\\n    THEN 8\\n    ELSE si.cpu_count / NULLIF(\\n      (SELECT COUNT(DISTINCT parent_node_id) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE'), 0)\\n  END AS recommended_maxdop\\nFROM sys.dm_os_sys_info si;", "parameters": [], "description": "Calculates hardware-appropriate values for max server memory and MAXDOP before applying."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115594
32006	mariadb	verify	mysql_verify_maintenance_within_resources	{"sql": "SELECT TABLE_NAME, DATA_FREE FROM information_schema.TABLES WHERE TABLE_SCHEMA = 'schema_name' AND TABLE_NAME = 'table_name';\\nSHOW GLOBAL STATUS LIKE 'Threads_running';", "parameters": null, "description": "Confirm maintenance completed without exceeding resource limits."}	\N	low	f	t	1 minute	2026-05-11 22:17:39.229791
326	sqlserver	configure	Apply safe values for the three most dangerous defaults	{"sql": "EXEC sp_configure 'show advanced options', 1;\\nRECONFIGURE;\\n\\n-- 1. Set max server memory (CRITICAL: prevents OS memory starvation)\\n-- Replace <recommended_max_memory_mb> with value from step 1\\nEXEC sp_configure 'max server memory (MB)', <recommended_max_memory_mb>;\\nRECONFIGURE;\\n\\n-- 2. Set MAXDOP (prevents runaway parallelism)\\n-- Replace <recommended_maxdop> with value from step 1\\nEXEC sp_configure 'max degree of parallelism', <recommended_maxdop>;\\nRECONFIGURE;\\n\\n-- 3. Set cost threshold for parallelism (reduces inappropriate parallelism for small queries)\\n-- 50 is a widely accepted OLTP baseline; use 25 for mixed workload\\nEXEC sp_configure 'cost threshold for parallelism', 50;\\nRECONFIGURE;\\n\\nEXEC sp_configure 'show advanced options', 0;\\nRECONFIGURE;", "parameters": ["recommended_max_memory_mb", "recommended_maxdop"], "description": "Applies the three most critical configuration corrections from dangerous defaults."}	{"sql": "EXEC sp_configure 'show advanced options', 1;\\nRECONFIGURE;\\nEXEC sp_configure 'max server memory (MB)', 2147483647;\\nRECONFIGURE;\\nEXEC sp_configure 'max degree of parallelism', 0;\\nRECONFIGURE;\\nEXEC sp_configure 'cost threshold for parallelism', 5;\\nRECONFIGURE;\\nEXEC sp_configure 'show advanced options', 0;\\nRECONFIGURE;", "description": "Restore all three parameters to their (dangerous) factory defaults."}	medium	t	t	00:05:00	2026-02-24 13:10:27.115595
