338	sqlserver	verify	Verify parallelism configuration matches workload requirements	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'cost threshold for parallelism') AS ctp,\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS logical_cpus,\\n  (SELECT COUNT(DISTINCT parent_node_id) FROM sys.dm_os_schedulers\\n   WHERE status = 'VISIBLE ONLINE') AS numa_nodes,\\n  -- MAXDOP should be <= logical_cpus/numa_nodes and <= 8 for OLTP\\n  CASE\\n    WHEN (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n          WHERE name = 'max degree of parallelism') = 0\\n      THEN 'WARN: unlimited MAXDOP'\\n    WHEN (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n          WHERE name = 'cost threshold for parallelism') < 25\\n      THEN 'WARN: CTP below 25 (suitable for OLAP only)'\\n    ELSE 'OK'\\n  END AS assessment;", "parameters": [], "description": "Confirms MAXDOP and CTP are set to workload-appropriate values and no longer at the misconfigured values."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115629
339	sqlserver	execute	Assess severity of memory overallocation	{"sql": "SELECT\\n  c.value_in_use AS max_server_memory_configured_mb,\\n  si.physical_memory_kb / 1024 AS physical_memory_mb,\\n  CAST(c.value_in_use AS BIGINT) - (si.physical_memory_kb / 1024) AS overallocation_mb,\\n  -- Current memory consumption\\n  (SELECT cntr_value / 1024\\n   FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)'\\n     AND object_name LIKE '%Memory Manager%') AS sql_total_mb,\\n  (SELECT cntr_value / 1024\\n   FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Target Server Memory (KB)'\\n     AND object_name LIKE '%Memory Manager%') AS sql_target_mb,\\n  -- OS pressure indicators\\n  sm.total_physical_memory_kb / 1024 AS os_total_memory_mb,\\n  sm.available_physical_memory_kb / 1024 AS os_available_mb,\\n  sm.system_memory_state_desc,\\n  pm.process_physical_memory_low,\\n  pm.process_virtual_memory_low,\\n  -- Recommended max memory (leave 10% or min 4GB for OS)\\n  si.physical_memory_kb / 1024\\n    - CASE\\n        WHEN si.physical_memory_kb / 1024 < 16384 THEN 2048\\n        WHEN si.physical_memory_kb / 1024 < 65536 THEN 4096\\n        ELSE CAST(si.physical_memory_kb / 1024 * 0.1 AS INT)\\n      END AS recommended_max_mb\\nFROM sys.configurations c\\nCROSS JOIN sys.dm_os_sys_info si\\nCROSS JOIN sys.dm_os_sys_memory sm\\nCROSS JOIN sys.dm_os_process_memory pm\\nWHERE c.name = 'max server memory (MB)';", "parameters": [], "description": "Quantifies the overallocation and determines the recommended safe max server memory value."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115667
