341	sqlserver	execute	Monitor memory pressure relief	{"sql": "-- Poll every 30 seconds to watch memory stabilize\\nSELECT\\n  GETDATE() AS sample_time,\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)'\\n     AND object_name LIKE '%Memory Manager%') AS sql_total_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page Life Expectancy'\\n     AND object_name LIKE '%Buffer Manager%'\\n     AND instance_name = '') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending'\\n     AND object_name LIKE '%Memory Manager%') AS grants_pending,\\n  sm.available_physical_memory_kb / 1024 AS os_available_mb,\\n  sm.system_memory_state_desc\\nFROM sys.dm_os_sys_memory sm;", "parameters": [], "description": "Monitors the memory recovery after the max server memory reduction. Run repeatedly until stabilized."}	null	low	f	t	00:15:00	2026-02-24 13:10:27.115669
