344	sqlserver	execute	Export authoritative configuration from the primary AG replica	{"sql": "-- Run on PRIMARY replica\\nSELECT\\n  SERVERPROPERTY('ServerName') AS server_name,\\n  ar.role_desc AS replica_role,\\n  c.name AS config_name,\\n  CAST(c.value_in_use AS BIGINT) AS running_value,\\n  c.is_dynamic\\nFROM sys.configurations c\\nCROSS JOIN sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nWHERE ars.is_local = 1\\n  AND c.name IN (\\n    'max degree of parallelism',\\n    'cost threshold for parallelism',\\n    'max server memory (MB)',\\n    'min server memory (MB)',\\n    'max worker threads',\\n    'optimize for ad hoc workloads',\\n    'backup compression default',\\n    'blocked process threshold (s)',\\n    'remote admin connections'\\n  )\\nORDER BY c.name;", "parameters": [], "description": "Exports the primary replica's current configuration as the target state for all secondary replicas."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115671
345	sqlserver	execute	Identify configuration differences on each secondary replica	{"sql": "-- Run on each SECONDARY replica and compare to primary output\\nSELECT\\n  SERVERPROPERTY('ServerName') AS server_name,\\n  c.name AS config_name,\\n  CAST(c.value_in_use AS BIGINT) AS secondary_value,\\n  -- Compare against primary: replace <primary_value> with actual values from step 1\\n  -- CASE WHEN CAST(c.value_in_use AS BIGINT) <> <primary_value> THEN 'MISMATCH' ELSE 'MATCH' END AS status\\n  c.is_dynamic\\nFROM sys.configurations c\\nWHERE c.name IN (\\n  'max degree of parallelism',\\n  'cost threshold for parallelism',\\n  'max server memory (MB)',\\n  'min server memory (MB)',\\n  'max worker threads',\\n  'optimize for ad hoc workloads',\\n  'backup compression default',\\n  'blocked process threshold (s)'\\n)\\nORDER BY c.name;", "parameters": [], "description": "Captures each secondary replica's configuration for diff against the primary."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115672
346	sqlserver	configure	Apply primary configuration to out-of-sync secondary replicas	{"sql": "-- Run on each SECONDARY replica that has a mismatch\\nEXEC sp_configure 'show advanced options', 1;\\nRECONFIGURE;\\n\\n-- Apply each mismatched parameter to match primary\\n-- (Replace with specific parameter/value pairs from the diff in step 2)\\n-- Example:\\n-- EXEC sp_configure 'max degree of parallelism', <primary_maxdop>;\\n-- RECONFIGURE;\\n-- EXEC sp_configure 'cost threshold for parallelism', <primary_ctp>;\\n-- RECONFIGURE;\\n-- EXEC sp_configure 'optimize for ad hoc workloads', <primary_value>;\\n-- RECONFIGURE;\\n\\nEXEC sp_configure 'show advanced options', 0;\\nRECONFIGURE;", "parameters": [], "description": "Synchronizes the identified mismatched parameters on each secondary replica to match the primary."}	{"sql": "EXEC sp_configure 'show advanced options', 1;\\nRECONFIGURE;\\n-- Restore each parameter to its previous secondary-specific value\\n-- EXEC sp_configure '<parameter>', <previous_secondary_value>;\\n-- RECONFIGURE;\\nEXEC sp_configure 'show advanced options', 0;\\nRECONFIGURE;", "description": "Restore secondary replica to its pre-sync configuration if the change causes issues."}	medium	t	t	00:30:00	2026-02-24 13:10:27.115672
32008	mariadb	configure	mysql_serialize_maintenance_jobs	{"sql": "-- Stagger events with adequate gaps:\\n-- 1 AM: Backup\\nALTER EVENT nightly_backup ON SCHEDULE EVERY 1 DAY STARTS CURRENT_DATE + INTERVAL 1 HOUR;\\n-- 3 AM: Integrity check (weekly)\\nALTER EVENT weekly_integrity_check ON SCHEDULE EVERY 1 WEEK STARTS CURRENT_DATE + INTERVAL 6 DAY + INTERVAL 3 HOUR;\\n-- 5 AM: OPTIMIZE (weekly)\\nALTER EVENT weekly_optimize ON SCHEDULE EVERY 1 WEEK STARTS CURRENT_DATE + INTERVAL 6 DAY + INTERVAL 5 HOUR;", "parameters": null, "description": "Reschedule maintenance jobs to run sequentially with adequate time gaps, preventing resource contention."}	\N	low	t	t	5 minutes	2026-05-11 22:17:39.229791
347	sqlserver	instruct	Create AG configuration synchronization monitoring and process	{"sql": null, "parameters": [], "description": "Prevent future AG configuration drift: (1) Create a configuration comparison script that runs on all AG replicas (via EXECUTE AT linked server or via a central management server) and alerts on differences. (2) Add configuration synchronization to the AG failover runbook: after any planned failover, verify configuration on the new primary. (3) Establish a process that any sp_configure change on the primary is simultaneously applied to all secondaries in the same change window. (4) Use Central Management Servers (CMS) to execute configuration queries across all AG nodes simultaneously. (5) Add a monthly task to audit AG replica configurations using this step's comparison queries."}	null	low	f	t	04:00:00	2026-02-24 13:10:27.115673
