349	sqlserver	execute	Script all cascade delete foreign keys for review	{"sql": "SELECT\\n  'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(fk.parent_object_id)) + '.' + QUOTENAME(OBJECT_NAME(fk.parent_object_id))\\n    + ' DROP CONSTRAINT ' + QUOTENAME(fk.name) + ';' AS drop_statement,\\n  'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(fk.parent_object_id)) + '.' + QUOTENAME(OBJECT_NAME(fk.parent_object_id))\\n    + ' ADD CONSTRAINT ' + QUOTENAME(fk.name)\\n    + ' FOREIGN KEY (' + COL_NAME(fkc.parent_object_id, fkc.parent_column_id) + ')'\\n    + ' REFERENCES ' + QUOTENAME(OBJECT_SCHEMA_NAME(fk.referenced_object_id)) + '.' + QUOTENAME(OBJECT_NAME(fk.referenced_object_id))\\n    + ' (' + COL_NAME(fkc.referenced_object_id, fkc.referenced_column_id) + ')'\\n    + ' ON DELETE NO ACTION ON UPDATE NO ACTION;' AS recreate_no_action,\\n  fk.name AS fk_name,\\n  fk.delete_referential_action_desc\\nFROM sys.foreign_keys fk\\nJOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id\\nWHERE fk.delete_referential_action_desc = 'CASCADE'\\nORDER BY OBJECT_NAME(fk.parent_object_id);", "parameters": [], "description": "Generates DROP and recreate-as-NO-ACTION scripts for every cascade delete FK. DBA must review each one before executing."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.115675
