391	sqlserver	verify	Verify all AG nodes are at the same version and AG is healthy	{"sql": "-- Run on each node and compare\\nSELECT @@SERVERNAME AS server_name,\\n  SERVERPROPERTY('ProductVersion') AS version,\\n  SERVERPROPERTY('ProductLevel') AS level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level;\\n\\n-- Check AG health from primary\\nSELECT ag.name, ars.role_desc, ars.connected_state_desc,\\n  ars.synchronization_health_desc\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id;", "parameters": [], "description": "Confirms all nodes report identical version/CU and the AG is fully healthy."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.13674
392	sqlserver	execute	Attempt to resume suspended AG databases	{"sql": "-- Try resuming first — if the log gap is bridgeable, this is sufficient\\nALTER DATABASE [@database_name] SET HADR RESUME;", "parameters": ["@database_name"], "description": "Attempts to resume data movement. SQL Server will automatically start replaying the log gap if it is within the available log retention."}	{"sql": "ALTER DATABASE [@database_name] SET HADR SUSPEND;", "description": "Suspend data movement if resumption causes unexpected issues."}	medium	t	t	00:05:00	2026-02-24 13:10:27.13674
394	sqlserver	verify	Verify AG database is synchronized after rejoin	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  drs.database_id, DB_NAME(drs.database_id) AS database_name,\\n  drs.synchronization_state_desc, drs.synchronization_health_desc,\\n  drs.log_send_queue_size AS send_queue_kb,\\n  drs.redo_queue_size AS redo_queue_kb,\\n  drs.is_suspended, drs.suspend_reason_desc\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_local = 1\\nORDER BY ag.name, database_name;", "parameters": [], "description": "Confirms the AG database is SYNCHRONIZED (or SYNCHRONIZING if still catching up) with no suspension."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136742
395	sqlserver	execute	Script missing filegroups from the primary	{"sql": "-- Run on primary to generate ADD FILEGROUP scripts for all non-PRIMARY filegroups\\nSELECT\\n  'ALTER DATABASE ' + QUOTENAME(DB_NAME()) + ' ADD FILEGROUP ' + QUOTENAME(fg.name)\\n  + CASE WHEN fg.type_desc = 'MEMORY_OPTIMIZED_DATA' THEN ' CONTAINS MEMORY_OPTIMIZED_DATA' ELSE '' END\\n  + ';' AS add_filegroup_ddl,\\n  'ALTER DATABASE ' + QUOTENAME(DB_NAME()) + ' ADD FILE (NAME = ' + QUOTENAME(df.name)\\n  + ', FILENAME = ''' + df.physical_name + ''', SIZE = '\\n  + CAST(CAST(df.size * 8.0 / 1024 AS int) AS varchar) + 'MB) TO FILEGROUP '\\n  + QUOTENAME(fg.name) + ';' AS add_file_ddl\\nFROM sys.filegroups fg\\nJOIN sys.database_files df ON fg.data_space_id = df.data_space_id\\nWHERE fg.name != 'PRIMARY'\\nORDER BY fg.name;", "parameters": [], "description": "Generates ADD FILEGROUP and ADD FILE scripts from the primary database to be executed on the diverged replica."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136742
402	sqlserver	verify	Verify AG endpoint certificate is valid and replication resumed	{"sql": "-- Check certificate validity\\nSELECT c.name, c.expiry_date, c.start_date,\\n  CASE WHEN c.expiry_date < GETDATE() THEN 'EXPIRED'\\n       WHEN c.expiry_date < DATEADD(DAY, 30, GETDATE()) THEN 'EXPIRING SOON'\\n       ELSE 'VALID' END AS cert_status\\nFROM sys.certificates c\\nJOIN sys.database_mirroring_endpoints dbme ON c.certificate_id = dbme.certificate_id\\n\\n-- Check AG replica connectivity\\nSELECT ar.replica_server_name, ars.connected_state_desc, ars.synchronization_health_desc\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id;", "parameters": [], "description": "Confirms the endpoint certificate is valid and all AG replicas are connected and healthy."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136747
