405	sqlserver	verify	Verify AG endpoint URLs match actual endpoint ports and replicas reconnect	{"sql": "-- Confirm endpoint URL port matches local endpoint port\\nSELECT ar.replica_server_name, ar.endpoint_url,\\n  e.name AS local_endpoint_name, te.port AS local_port,\\n  ars.connected_state_desc\\nFROM sys.availability_replicas ar\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nCROSS JOIN sys.endpoints e\\nJOIN sys.tcp_endpoints te ON e.endpoint_id = te.endpoint_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE e.type = 4;", "parameters": [], "description": "Confirms endpoint URL port matches local_port and all replicas show connected_state_desc = 'CONNECTED'."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136749
406	sqlserver	execute	Set consistent read-only connection settings on all AG replicas	{"sql": "-- Execute on primary for each replica\\n-- Adjust settings to match your intended AG topology\\n\\n-- For a read-scale secondary (allows read-intent connections):\\nALTER AVAILABILITY GROUP [@ag_name]\\n  MODIFY REPLICA ON N'@secondary_replica_name' WITH (\\n    PRIMARY_ROLE (ALLOW_CONNECTIONS = ALL),\\n    SECONDARY_ROLE (ALLOW_CONNECTIONS = READ_ONLY)\\n  );\\n\\n-- For a non-readable secondary (hot standby only):\\n-- ALTER AVAILABILITY GROUP [@ag_name]\\n--   MODIFY REPLICA ON N'@secondary_replica_name' WITH (\\n--     SECONDARY_ROLE (ALLOW_CONNECTIONS = NO)\\n--   );", "parameters": ["@ag_name", "@secondary_replica_name"], "description": "Sets the primary and secondary role connection policies for each replica to match the agreed topology."}	{"sql": "ALTER AVAILABILITY GROUP [@ag_name]\\n  MODIFY REPLICA ON N'@secondary_replica_name' WITH (\\n    PRIMARY_ROLE (ALLOW_CONNECTIONS = @previous_primary_policy),\\n    SECONDARY_ROLE (ALLOW_CONNECTIONS = @previous_secondary_policy)\\n  );", "description": "Revert connection policies to previous values if the change causes application issues."}	medium	t	t	00:01:00	2026-02-24 13:10:27.13675
