489	sqlserver	execute	Transfer schema ownership to dbo	{"sql": "-- Run within the target database; once per schema with an inappropriate owner\\nUSE [<database_name>];\\nALTER AUTHORIZATION ON SCHEMA::[<schema_name>] TO dbo;", "parameters": ["database_name", "schema_name"], "description": "Transfers schema ownership to dbo, eliminating the user-owned schema that granted implicit DDL control."}	{"sql": "USE [<database_name>];\\nALTER AUTHORIZATION ON SCHEMA::[<schema_name>] TO [<original_owner>];", "description": "Restores the original schema owner if cross-schema chaining breaks."}	medium	t	t	00:01:00	2026-02-24 13:10:27.136802
490	sqlserver	verify	Verify no non-standard database or schema owners remain	{"sql": "-- Check database ownership\\nSELECT d.name AS database_name, SUSER_SNAME(d.owner_sid) AS owner_login\\nFROM sys.databases d\\nJOIN sys.server_principals p ON d.owner_sid = p.sid\\nWHERE d.database_id > 4\\n  AND p.name NOT IN ('sa')\\n  AND p.type_desc NOT LIKE '%SERVICE%';\\n\\n-- Check schema ownership within each affected database\\nSELECT s.name AS schema_name, dp.name AS owner_name\\nFROM sys.schemas s\\nJOIN sys.database_principals dp ON s.principal_id = dp.principal_id\\nWHERE dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'db_owner');", "parameters": [], "description": "Confirms all databases are owned by sa and all schemas are owned by dbo or expected system principals."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136803
481	sqlserver	execute	Map full nested role inheritance chains to understand scope	{"sql": "WITH role_tree AS (\\n  SELECT rm.member_principal_id, rm.role_principal_id, 1 AS depth,\\n    CAST(dp.name AS NVARCHAR(MAX)) AS chain\\n  FROM sys.database_role_members rm\\n  JOIN sys.database_principals dp ON rm.role_principal_id = dp.principal_id\\n  UNION ALL\\n  SELECT rt.member_principal_id, rm2.role_principal_id, rt.depth + 1,\\n    rt.chain + N' -> ' + dp2.name\\n  FROM role_tree rt\\n  JOIN sys.database_role_members rm2 ON rt.role_principal_id = rm2.member_principal_id\\n  JOIN sys.database_principals dp2 ON rm2.role_principal_id = dp2.principal_id\\n  WHERE rt.depth < 5\\n)\\nSELECT u.name AS user_name, u.type_desc,\\n  r.name AS effective_role, rt.chain, rt.depth\\nFROM role_tree rt\\nJOIN sys.database_principals u ON rt.member_principal_id = u.principal_id\\nJOIN sys.database_principals r ON rt.role_principal_id = r.principal_id\\nWHERE r.name IN ('db_owner', 'db_securityadmin', 'db_accessadmin')\\n  AND rt.depth > 1\\nORDER BY rt.depth DESC, u.name;", "parameters": [], "description": "Maps all users who inherit elevated roles through nested role chains, showing the full chain path."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136797
660	sqlserver	execute	Delete confirmed orphaned partial files via xp_cmdshell or file system	{"sql": "EXEC xp_cmdshell 'del /f \\"@partial_file_path\\"';", "parameters": ["partial_file_path"], "description": "Removes the identified partial files. Prefer doing this via the OS directly or an SSIS task. xp_cmdshell is an alternative if enabled. Run file deletions one at a time to avoid accidental mass deletion."}	null	medium	t	f	00:15:00	2026-02-24 13:10:27.136798
483	sqlserver	verify	Confirm no users retain elevated permissions through nested role chains	{"sql": "WITH role_tree AS (\\n  SELECT rm.member_principal_id, rm.role_principal_id, 1 AS depth,\\n    CAST(dp.name AS NVARCHAR(MAX)) AS chain\\n  FROM sys.database_role_members rm\\n  JOIN sys.database_principals dp ON rm.role_principal_id = dp.principal_id\\n  UNION ALL\\n  SELECT rt.member_principal_id, rm2.role_principal_id, rt.depth + 1,\\n    rt.chain + N' -> ' + dp2.name\\n  FROM role_tree rt\\n  JOIN sys.database_role_members rm2 ON rt.role_principal_id = rm2.member_principal_id\\n  JOIN sys.database_principals dp2 ON rm2.role_principal_id = dp2.principal_id\\n  WHERE rt.depth < 5\\n)\\nSELECT u.name AS user_name, r.name AS effective_role, rt.chain, rt.depth\\nFROM role_tree rt\\nJOIN sys.database_principals u ON rt.member_principal_id = u.principal_id\\nJOIN sys.database_principals r ON rt.role_principal_id = r.principal_id\\nWHERE r.name IN ('db_owner', 'db_securityadmin', 'db_accessadmin')\\n  AND rt.depth > 1\\nORDER BY rt.depth DESC;", "parameters": [], "description": "Re-runs the inheritance detection query. Zero rows expected after breaking all unauthorized nested role chains."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136799
485	sqlserver	execute	Grant minimum required permissions to service accounts	{"sql": "-- Backup agent accounts typically need VIEW SERVER STATE + specific db permissions\\n-- Monitoring accounts typically need VIEW SERVER STATE + VIEW DATABASE STATE\\n-- Adjust per functional requirements\\n\\n-- Example for a monitoring account:\\nGRANT VIEW SERVER STATE TO N'<monitoring_account>';\\nGRANT VIEW ANY DATABASE TO N'<monitoring_account>';\\n\\n-- Example for a backup account (if using custom backup solution):\\nGRANT ALTER ANY DATABASE TO N'<backup_account>';\\nGRANT VIEW SERVER STATE TO N'<backup_account>';", "parameters": ["monitoring_account", "backup_account"], "description": "Grants only the server-level permissions actually needed. Database-level permissions should be granted within each database using USE [db]; GRANT ... syntax."}	{"sql": "REVOKE VIEW SERVER STATE FROM N'<account>';\\nREVOKE VIEW ANY DATABASE FROM N'<account>';", "description": "Revoke granted permissions if they are found to be incorrect."}	medium	t	t	00:15:00	2026-02-24 13:10:27.1368
486	sqlserver	instruct	Instruct operations team to update service account documentation	{"sql": null, "parameters": [], "description": "Update the service account registry/CMDB: (1) Document each service account's owner, purpose, and minimum required permissions. (2) Set a review cadence (quarterly) for service account privilege recertification. (3) Ensure provisioning runbooks specify least-privilege grants, not sysadmin. (4) Notify application/tool owners of the permission change and confirm functionality."}	null	low	f	t	3 days	2026-02-24 13:10:27.136801
487	sqlserver	verify	Verify no service accounts remain in sysadmin	{"sql": "SELECT p.name AS login_name, p.type_desc, r.name AS role_name\\nFROM sys.server_principals p\\nJOIN sys.server_role_members rm ON p.principal_id = rm.member_principal_id\\nJOIN sys.server_principals r ON rm.role_principal_id = r.principal_id\\nWHERE r.name = 'sysadmin'\\n  AND (p.name LIKE '%svc%' OR p.name LIKE '%service%' OR p.name LIKE '%app%'\\n    OR p.name LIKE '%agent%' OR p.name LIKE '%monitor%' OR p.name LIKE '%backup%')\\nORDER BY p.name;", "parameters": [], "description": "Re-runs the detection query to confirm all service accounts have been removed from sysadmin."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136801
488	sqlserver	execute	Transfer database ownership to sa or dedicated DBA account	{"sql": "-- Run once per database that has an inappropriate owner\\nALTER AUTHORIZATION ON DATABASE::[<database_name>] TO sa;", "parameters": ["database_name"], "description": "Changes the database owner to sa, which is the standard for production databases. Alternatively, use a dedicated DBA service account."}	{"sql": "ALTER AUTHORIZATION ON DATABASE::[<database_name>] TO [<original_owner>];", "description": "Restores the original database owner if issues arise."}	medium	t	t	00:01:00	2026-02-24 13:10:27.136802
491	sqlserver	instruct	Review each trigger with EXECUTE AS for legitimate business justification	{"sql": null, "parameters": [], "description": "For each trigger identified in detection: (1) Run SELECT OBJECT_DEFINITION(OBJECT_ID('<schema>.<trigger_name>')) to review the full trigger body. (2) Determine if the elevated principal in EXECUTE AS is necessary for the trigger's function. (3) Consult the application owner/developer. (4) Document whether each trigger is: (a) Legitimate and properly documented, (b) Unnecessary — can be rewritten without EXECUTE AS, or (c) Malicious/unauthorized — must be dropped immediately."}	null	low	f	t	04:00:00	2026-02-24 13:10:27.136804
494	sqlserver	verify	Verify no unauthorized EXECUTE AS triggers remain	{"sql": "SELECT OBJECT_SCHEMA_NAME(t.parent_id) AS schema_name,\\n  OBJECT_NAME(t.parent_id) AS table_name,\\n  t.name AS trigger_name,\\n  dp.name AS execute_as_user\\nFROM sys.triggers t\\nJOIN sys.sql_modules sm ON t.object_id = sm.object_id\\nLEFT JOIN sys.database_principals dp ON sm.execute_as_principal_id = dp.principal_id\\nWHERE sm.execute_as_principal_id IS NOT NULL\\n  AND sm.execute_as_principal_id != 0;", "parameters": [], "description": "Re-runs the detection query to confirm all EXECUTE AS triggers have been addressed."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136805
495	sqlserver	instruct	Review each procedure with EXECUTE AS for business justification	{"sql": null, "parameters": [], "description": "For each procedure found in detection: (1) Run SELECT OBJECT_DEFINITION(OBJECT_ID('<schema>.<proc_name>')) to get the full body. (2) Determine whether the EXECUTE AS principal actually needs elevated rights for the procedure's function. (3) Check if the procedure was created by a developer without security awareness vs. by a DBA with intent. (4) Classify as: Legitimate (documented, minimal elevation), Remediable (can use certificate signing instead), or Unauthorized (drop or rewrite)."}	null	low	f	t	04:00:00	2026-02-24 13:10:27.136806
497	sqlserver	verify	Verify no unreviewed EXECUTE AS procedures remain	{"sql": "SELECT OBJECT_SCHEMA_NAME(p.object_id) AS schema_name,\\n  p.name AS proc_name,\\n  dp.name AS execute_as_user\\nFROM sys.procedures p\\nJOIN sys.sql_modules sm ON p.object_id = sm.object_id\\nLEFT JOIN sys.database_principals dp ON sm.execute_as_principal_id = dp.principal_id\\nWHERE sm.execute_as_principal_id IS NOT NULL\\n  AND sm.execute_as_principal_id NOT IN (0, -2)\\nORDER BY schema_name, proc_name;", "parameters": [], "description": "Re-runs the detection query. Any remaining rows should only be procedures that have been reviewed and approved."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136807
498	sqlserver	instruct	Review each view grant with data owner for business justification	{"sql": null, "parameters": [], "description": "For each view with explicit SELECT grants identified in detection: (1) Run SELECT OBJECT_DEFINITION(OBJECT_ID('<schema>.<view_name>')) to understand what data is exposed. (2) Consult the data owner or application owner — was this access intentional? (3) Check if the view includes sensitive columns (PII, financial, credentials). (4) Determine appropriate access level: full SELECT, column-level SELECT on non-sensitive columns only, or no access."}	null	low	f	t	04:00:00	2026-02-24 13:10:27.136808
499	sqlserver	execute	Revoke unauthorized SELECT grants on sensitive views	{"sql": "USE [<database_name>];\\nREVOKE SELECT ON [<schema_name>].[<view_name>] FROM [<grantee>];", "parameters": ["database_name", "schema_name", "view_name", "grantee"], "description": "Revokes SELECT permission on a sensitive view from an unauthorized principal."}	{"sql": "USE [<database_name>];\\nGRANT SELECT ON [<schema_name>].[<view_name>] TO [<grantee>];", "description": "Re-grants SELECT if the revocation causes confirmed application breakage."}	medium	t	t	00:01:00	2026-02-24 13:10:27.136809
500	sqlserver	execute	Grant column-level SELECT where partial access is legitimate	{"sql": "-- If the user needs some columns but not sensitive ones, use column-level grants\\nUSE [<database_name>];\\nGRANT SELECT ON [<schema_name>].[<view_name>] ([<safe_column1>], [<safe_column2>]) TO [<grantee>];", "parameters": ["database_name", "schema_name", "view_name", "safe_column1", "safe_column2", "grantee"], "description": "Grants SELECT only on non-sensitive columns, providing legitimate access without exposing PII or sensitive data."}	{"sql": "USE [<database_name>];\\nREVOKE SELECT ON [<schema_name>].[<view_name>] ([<safe_column1>], [<safe_column2>]) FROM [<grantee>];", "description": "Revokes the column-level grant if incorrect."}	low	t	t	\N	2026-02-24 13:10:27.147565
511	sqlserver	verify	Verify no users retain GRANT WITH GRANT OPTION on server role ALTER	{"sql": "SELECT pr.name AS principal_name, pe.permission_name,\\n  pe.state_desc, pe2.name AS target_role\\nFROM sys.server_permissions pe\\nJOIN sys.server_principals pr ON pe.grantee_principal_id = pr.principal_id\\nLEFT JOIN sys.server_principals pe2 ON pe.major_id = pe2.principal_id\\nWHERE pe.state_desc = 'GRANT_WITH_GRANT_OPTION'\\n  AND pe.permission_name = 'ALTER'\\n  AND pe2.type = 'R'\\n  AND pr.name NOT IN ('sa')\\nORDER BY pr.name;", "parameters": [], "description": "Re-runs the detection query to confirm no non-sa principals retain delegation capability on server roles."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.148383
501	sqlserver	verify	Verify sensitive views no longer have unauthorized SELECT grants	{"sql": "SELECT v.name AS view_name, SCHEMA_NAME(v.schema_id) AS schema_name,\\n  dp_grantee.name AS grantee, pe.permission_name, pe.state_desc\\nFROM sys.views v\\nJOIN sys.database_permissions pe ON v.object_id = pe.major_id\\nJOIN sys.database_principals dp_grantee ON pe.grantee_principal_id = dp_grantee.principal_id\\nWHERE pe.permission_name = 'SELECT'\\n  AND pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND dp_grantee.name NOT IN ('dbo', 'rootcause', 'db_datareader')\\n  AND SCHEMA_NAME(v.schema_id) NOT IN ('sys', 'INFORMATION_SCHEMA');", "parameters": [], "description": "Re-runs the detection query to confirm only approved grants remain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.148373
502	sqlserver	instruct	Review each synonym grant for legitimate use and sensitivity of base object	{"sql": null, "parameters": [], "description": "For each synonym with grants identified in detection: (1) Confirm the base_object_name to understand what the synonym exposes. (2) Check whether the base object contains sensitive logic (privilege changes, data extraction, DDL). (3) Determine if the synonym was created as an approved access path or is an unauthorized alias. (4) Consult the application team — does any code rely on this synonym?"}	null	low	f	t	02:00:00	2026-02-24 13:10:27.148377
503	sqlserver	execute	Revoke permissions on unauthorized synonyms	{"sql": "USE [<database_name>];\\nREVOKE EXECUTE ON [<schema_name>].[<synonym_name>] FROM [<grantee>];\\n-- If SELECT was granted instead of EXECUTE:\\n-- REVOKE SELECT ON [<schema_name>].[<synonym_name>] FROM [<grantee>];", "parameters": ["database_name", "schema_name", "synonym_name", "grantee"], "description": "Revokes EXECUTE or SELECT on the synonym, preventing the grantee from invoking the privileged base object through the alias."}	{"sql": "USE [<database_name>];\\nGRANT EXECUTE ON [<schema_name>].[<synonym_name>] TO [<grantee>];", "description": "Re-grants the permission if revocation causes confirmed application breakage."}	medium	t	t	00:01:00	2026-02-24 13:10:27.148378
504	sqlserver	execute	Drop synonyms with no legitimate use	{"sql": "USE [<database_name>];\\nDROP SYNONYM [<schema_name>].[<synonym_name>];", "parameters": ["database_name", "schema_name", "synonym_name"], "description": "Drops the synonym entirely to eliminate the alias-based access path."}	{"sql": "USE [<database_name>];\\nCREATE SYNONYM [<schema_name>].[<synonym_name>] FOR [<base_object_name>];", "description": "Re-creates the synonym if removal causes application breakage."}	medium	t	t	00:01:00	2026-02-24 13:10:27.148378
505	sqlserver	verify	Verify no unauthorized synonym grants remain	{"sql": "SELECT s.name AS synonym_name, SCHEMA_NAME(s.schema_id) AS synonym_schema,\\n  s.base_object_name, pe.permission_name, dp.name AS grantee\\nFROM sys.synonyms s\\nJOIN sys.database_permissions pe ON s.object_id = pe.major_id\\nJOIN sys.database_principals dp ON pe.grantee_principal_id = dp.principal_id\\nWHERE pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\nORDER BY s.name;", "parameters": [], "description": "Re-runs the detection query to confirm all synonym grants have been addressed."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.148379
