507	sqlserver	configure	Modify audit specification to remove inappropriate principal scoping	{"sql": "-- Disable the current server audit specification\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>] WITH (STATE = OFF);\\n\\n-- Remove the principal-scoped audit action and replace with unscoped version\\n-- (covers ALL principals for that action)\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>]\\n  DROP (SCHEMA_OBJECT_ACCESS_GROUP);\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>]\\n  ADD (SCHEMA_OBJECT_ACCESS_GROUP);\\n\\n-- Re-enable the specification\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>] WITH (STATE = ON);", "parameters": ["spec_name"], "description": "Removes the principal-scoped audit action (which was only auditing a specific user) and re-adds the same action without scoping, so it covers all principals."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [<spec_name>] WITH (STATE = OFF);\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>]\\n  DROP (SCHEMA_OBJECT_ACCESS_GROUP);\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>]\\n  ADD (SCHEMA_OBJECT_ACCESS_GROUP BY [<original_principal>]);\\nALTER SERVER AUDIT SPECIFICATION [<spec_name>] WITH (STATE = ON);", "description": "Restores the original principal-scoped audit action if required."}	medium	t	t	00:15:00	2026-02-24 13:10:27.14838
508	sqlserver	verify	Verify audit specifications cover all principals without exemptions	{"sql": "SELECT sa.name AS audit_name, sas.name AS spec_name,\\n  sasd.audit_action_name, sasd.audited_principal_id,\\n  dp.name AS audited_principal\\nFROM sys.server_audits sa\\nJOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nJOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nLEFT JOIN sys.server_principals dp ON sasd.audited_principal_id = dp.principal_id\\nWHERE sasd.audited_principal_id != 0;", "parameters": [], "description": "Re-runs the detection query. Zero rows indicates no principal-scoped (potentially exempting) audit actions remain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.148381
