624	sqlserver	verify	Identify full backups held beyond retention due to dependent differentials	{"sql": "SELECT f.database_name, f.backup_finish_date AS full_backup_date, DATEDIFF(day, f.backup_finish_date, GETDATE()) AS full_age_days, MAX(d.backup_finish_date) AS latest_dependent_diff, DATEDIFF(day, MAX(d.backup_finish_date), GETDATE()) AS diff_age_days FROM msdb.dbo.backupset f JOIN msdb.dbo.backupset d ON d.database_backup_lsn BETWEEN f.first_lsn AND f.last_lsn AND d.database_name = f.database_name AND d.type = 'I' WHERE f.type = 'D' AND DATEDIFF(day, f.backup_finish_date, GETDATE()) > :retention_days GROUP BY f.database_name, f.backup_finish_date HAVING MAX(d.backup_finish_date) > DATEADD(day, -:retention_days, GETDATE()) ORDER BY f.database_name, f.backup_finish_date;", "parameters": ["retention_days"], "description": "Shows full backups that are beyond retention but still have recent differentials depending on them."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.162992
