685	sqlserver	execute	Update statistics on stale tables with FULLSCAN	{"sql": "DECLARE @schema NVARCHAR(128), @table NVARCHAR(128), @stats NVARCHAR(128), @sql NVARCHAR(500); DECLARE stats_cursor CURSOR FOR SELECT OBJECT_SCHEMA_NAME(s.object_id), OBJECT_NAME(s.object_id), s.name FROM sys.stats s CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > 0 AND sp.last_updated < DATEADD(day, -7, GETDATE()) AND CAST(100.0 * sp.modification_counter / NULLIF(sp.rows,0) AS decimal(5,1)) > 10; OPEN stats_cursor; FETCH NEXT FROM stats_cursor INTO @schema, @table, @stats; WHILE @@FETCH_STATUS = 0 BEGIN SET @sql = 'UPDATE STATISTICS [' + @schema + '].[' + @table + '] [' + @stats + '] WITH FULLSCAN'; EXEC(@sql); FETCH NEXT FROM stats_cursor INTO @schema, @table, @stats; END; CLOSE stats_cursor; DEALLOCATE stats_cursor;", "parameters": [], "description": "Iterates statistics objects that are stale (>7 days, >10% modified) and updates each with a full scan for accurate histograms."}	null	low	f	f	02:00:00	2026-02-24 13:10:27.163029
