708	sqlserver	execute	Update statistics on tables with row count discrepancies from bulk loads	{"sql": "DECLARE @schema NVARCHAR(128), @table NVARCHAR(128), @sql NVARCHAR(500); DECLARE cur CURSOR FOR SELECT DISTINCT OBJECT_SCHEMA_NAME(s.object_id), OBJECT_NAME(s.object_id) FROM sys.stats s CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp JOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1) WHERE ABS(p.rows - sp.rows) > 10000; OPEN cur; FETCH NEXT FROM cur INTO @schema, @table; WHILE @@FETCH_STATUS = 0 BEGIN SET @sql = 'UPDATE STATISTICS [' + @schema + '].[' + @table + '] WITH FULLSCAN'; EXEC(@sql); FETCH NEXT FROM cur INTO @schema, @table; END; CLOSE cur; DEALLOCATE cur;", "parameters": [], "description": "Runs FULLSCAN statistics update on all tables where the statistics row count differs from the actual partition row count by more than 10,000 rows, correcting bulk-load discrepancies."}	null	low	f	f	02:00:00	2026-02-24 13:10:27.169311
