713	sqlserver	configure	Create high-frequency statistics maintenance job for volatile tables	{"sql": "USE msdb; EXEC sp_add_job @job_name = N'High-Frequency Stats Refresh - Volatile Tables'; EXEC sp_add_jobstep @job_name = N'High-Frequency Stats Refresh - Volatile Tables', @step_name = N'Refresh volatile table stats', @command = N'DECLARE @schema NVARCHAR(128), @table NVARCHAR(128), @sql NVARCHAR(500); DECLARE cur CURSOR FOR SELECT DISTINCT OBJECT_SCHEMA_NAME(s.object_id), OBJECT_NAME(s.object_id) FROM sys.stats s CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > sp.rows * 0.5 AND sp.rows > 1000; OPEN cur; FETCH NEXT FROM cur INTO @schema, @table; WHILE @@FETCH_STATUS = 0 BEGIN SET @sql = ''UPDATE STATISTICS ['' + @schema + ''].['' + @table + ''] WITH SAMPLE 30 PERCENT''; EXEC(@sql); FETCH NEXT FROM cur INTO @schema, @table; END; CLOSE cur; DEALLOCATE cur;', @database_name = N'$(DB_NAME)'; EXEC sp_add_schedule @schedule_name = N'Every4Hours', @freq_type = 4, @freq_interval = 1, @freq_subday_type = 8, @freq_subday_interval = 4, @active_start_time = 0; EXEC sp_attach_schedule @job_name = N'High-Frequency Stats Refresh - Volatile Tables', @schedule_name = N'Every4Hours'; EXEC sp_add_jobserver @job_name = N'High-Frequency Stats Refresh - Volatile Tables';", "parameters": [], "description": "Creates a SQL Agent job that runs every 4 hours to refresh statistics on tables with modification counts exceeding 50% of row count, providing more frequent updates than the default auto-update threshold."}	{"sql": "USE msdb; EXEC sp_delete_job @job_name = N'High-Frequency Stats Refresh - Volatile Tables';", "description": "Remove the high-frequency job if it causes resource contention."}	medium	t	t	00:10:00	2026-02-24 13:10:27.169315
