760	sqlserver	verify	Confirm split rate and page density improvement	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name, OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, ips.avg_fragmentation_in_percent, ips.avg_page_space_used_in_percent, ips.page_count, i.fill_factor FROM sys.dm_db_index_physical_stats(DB_ID(), OBJECT_ID(:full_table_name), NULL, NULL, 'DETAILED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE ips.index_level = 0 ORDER BY ips.page_count DESC;", "parameters": ["full_table_name"], "description": "Checks fragmentation and page density. Healthy result: avg_fragmentation_in_percent < 5, avg_page_space_used_in_percent between 70-90% reflecting the new fillfactor."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.180175
767	sqlserver	verify	Identify low-density indexes and estimate compaction benefit	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name, OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, i.type_desc, CAST(ips.avg_page_space_used_in_percent AS decimal(5,1)) AS page_density_pct, ips.page_count, CAST(ips.page_count * 8.0 / 1024 AS decimal(10,1)) AS current_size_mb, CAST(ips.page_count * 8.0 / 1024 * ips.avg_page_space_used_in_percent / 100 AS decimal(10,1)) AS est_compacted_size_mb, ips.avg_fragmentation_in_percent FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE ips.avg_page_space_used_in_percent < 60 AND ips.page_count > 1000 AND ips.index_level = 0 ORDER BY ips.page_count DESC;", "parameters": [], "description": "Lists indexes with low page density and estimates the compacted size after rebuild. Large gaps between current_size_mb and est_compacted_size_mb indicate high buffer cache waste."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.182721
761	sqlserver	execute	Create index maintenance stored procedure	{"sql": "CREATE OR ALTER PROCEDURE dbo.usp_MaintainIndexes @DatabaseName NVARCHAR(128) = NULL, @ReorgThreshold FLOAT = 10, @RebuildThreshold FLOAT = 30, @MinPageCount INT = 1000, @MaxDOP INT = 4 AS BEGIN SET NOCOUNT ON; DECLARE @sql NVARCHAR(MAX); DECLARE @db NVARCHAR(128) = ISNULL(@DatabaseName, DB_NAME()); DECLARE @schema NVARCHAR(128), @table NVARCHAR(128), @index NVARCHAR(128), @frag FLOAT; DECLARE cur CURSOR FOR SELECT OBJECT_SCHEMA_NAME(ips.object_id, DB_ID(@db)), OBJECT_NAME(ips.object_id, DB_ID(@db)), i.name, ips.avg_fragmentation_in_percent FROM sys.dm_db_index_physical_stats(DB_ID(@db), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE ips.avg_fragmentation_in_percent >= @ReorgThreshold AND ips.page_count >= @MinPageCount AND i.type_desc IN ('CLUSTERED','NONCLUSTERED'); OPEN cur; FETCH NEXT FROM cur INTO @schema, @table, @index, @frag; WHILE @@FETCH_STATUS = 0 BEGIN IF @frag >= @RebuildThreshold SET @sql = N'ALTER INDEX [' + @index + N'] ON [' + @schema + N'].[' + @table + N'] REBUILD WITH (ONLINE=ON, MAXDOP=' + CAST(@MaxDOP AS NVARCHAR) + N', SORT_IN_TEMPDB=ON)'; ELSE SET @sql = N'ALTER INDEX [' + @index + N'] ON [' + @schema + N'].[' + @table + N'] REORGANIZE'; EXEC sp_executesql @sql; FETCH NEXT FROM cur INTO @schema, @table, @index, @frag; END; CLOSE cur; DEALLOCATE cur; END;", "parameters": [], "description": "Creates a stored procedure that evaluates fragmentation for all indexes and rebuilds (>30%) or reorganizes (10-30%) as appropriate. Skips small indexes (< min page count)."}	{"sql": "DROP PROCEDURE IF EXISTS dbo.usp_MaintainIndexes;", "description": "Removes the maintenance procedure."}	low	f	t	00:01:00	2026-02-24 13:10:27.180179
762	sqlserver	configure	Create SQL Agent job to run index maintenance nightly	{"sql": "USE msdb; EXEC dbo.sp_add_job @job_name = N'Index Maintenance - Nightly', @enabled = 1, @description = N'Rebuilds and reorganizes fragmented indexes nightly'; EXEC dbo.sp_add_jobstep @job_name = N'Index Maintenance - Nightly', @step_name = N'Run Index Maintenance', @subsystem = N'TSQL', @command = N'EXEC dbo.usp_MaintainIndexes @MaxDOP = :maxdop;', @database_name = N':target_database'; EXEC dbo.sp_add_schedule @schedule_name = N'Nightly 2AM', @freq_type = 4, @freq_interval = 1, @active_start_time = 20000; EXEC dbo.sp_attach_schedule @job_name = N'Index Maintenance - Nightly', @schedule_name = N'Nightly 2AM'; EXEC dbo.sp_add_jobserver @job_name = N'Index Maintenance - Nightly';", "parameters": ["maxdop", "target_database"], "description": "Creates a SQL Agent job that runs the index maintenance procedure nightly at 2:00 AM. Adjust schedule to fit maintenance window."}	{"sql": "USE msdb; EXEC dbo.sp_delete_job @job_name = N'Index Maintenance - Nightly';", "description": "Removes the SQL Agent job."}	low	f	t	\N	2026-02-24 13:10:27.18096
