7965	postgresql	execute	Drop orphaned replication slots	{"sql": "SELECT pg_drop_replication_slot(':slot_name');", "parameters": ["slot_name"], "description": "Drops the replication slot for the evicted node to release retained WAL"}	\N	medium	t	f	seconds	2026-02-25 08:59:43.77256
957	sqlserver	execute	Resume any suspended AG databases on the returning replica	{"sql": "-- Check for suspended databases on this replica\\nSELECT ar.replica_server_name, adc.database_name,\\n  drs.synchronization_state_desc, drs.synchronization_health_desc,\\n  drs.is_suspended, drs.suspend_reason_desc,\\n  drs.log_send_queue_size, drs.redo_queue_size\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_databases_cluster adc ON drs.group_database_id = adc.group_database_id\\nWHERE ar.replica_server_name = @@SERVERNAME\\nORDER BY drs.is_suspended DESC, adc.database_name;\\n\\n-- Resume suspended databases (run for each suspended database)\\n-- ALTER DATABASE [<database_name>] SET HADR RESUME;", "parameters": [], "description": "Identify and resume any AG databases that were suspended during shutdown; SQL Server usually auto-resumes but may need manual intervention if data movement was explicitly suspended"}	{"sql": "-- To suspend if resume causes unexpected issues:\\n-- ALTER DATABASE [<database_name>] SET HADR SUSPEND;"}	low	f	t	00:05:00	2026-02-24 13:10:27.204677
958	sqlserver	verify	Identify AG endpoint port and current connectivity status	{"sql": "SELECT ep.name, ep.state_desc, ep.port, ep.ip_address,\\n  ep.connection_auth_desc,\\n  ar.replica_server_name, ar.endpoint_url,\\n  drs.connected_state_desc, drs.synchronization_state_desc\\nFROM sys.database_mirroring_endpoints ep\\nCROSS JOIN sys.availability_replicas ar\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY drs.connected_state_desc, ar.replica_server_name", "parameters": [], "description": "Identify the endpoint port in use and which replicas are disconnected"}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204677
