996	sqlserver	verify	Confirm witness type and current state	{"sql": "SELECT c.cluster_name, c.quorum_type_desc, c.quorum_state_desc,\\n  cm.member_name, cm.member_type_desc, cm.member_state_desc,\\n  cm.number_of_quorum_votes\\nFROM sys.dm_hadr_cluster c\\nCROSS JOIN sys.dm_hadr_cluster_members cm\\nORDER BY cm.member_type_desc DESC, cm.member_name;", "parameters": [], "description": "Identify the quorum type (NODE_MAJORITY, NODE_AND_FILE_SHARE_MAJORITY, NODE_AND_CLOUD_WITNESS_MAJORITY, NODE_AND_DISK_MAJORITY) and confirm which member is the witness and its current state."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.20468
962	sqlserver	instruct	Diagnose and fix DNS record for the AG listener	{"sql": null, "parameters": ["listener_dns_name: the dns_name value from sys.availability_group_listeners", "domain: Active Directory DNS zone (e.g., corp.example.com)", "listener_ip: ip_address from sys.availability_group_listener_ip_addresses"], "description": "From any cluster node, run the following to diagnose DNS:\\n\\n  # Test if DNS name resolves\\n  Resolve-DnsName <listener_dns_name>\\n  nslookup <listener_dns_name>\\n\\n  # If DNS name does not resolve, register it:\\n  # Option 1 — Force WSFC to re-register the DNS record:\\n  Get-ClusterResource | Where ResourceType -eq 'Network Name' | Update-ClusterNetworkNameResource\\n\\n  # Option 2 — Manually add an A record in DNS (requires DNS Admin rights):\\n  Add-DnsServerResourceRecordA -Name <listener_dns_name> -ZoneName <domain> -IPv4Address <listener_ip>\\n\\n  # After adding record, flush DNS cache on all application servers:\\n  ipconfig /flushdns\\n\\n  # Verify resolution:\\n  Resolve-DnsName <listener_dns_name>"}	null	medium	t	t	00:30:00	2026-02-24 13:10:27.204681
963	sqlserver	verify	Confirm listener connectivity and AG health after DNS fix	{"sql": "SELECT l.dns_name, l.port,\\n  lip.state_desc AS ip_state, lip.ip_address,\\n  ags.synchronization_health_desc,\\n  ags.primary_replica\\nFROM sys.availability_group_listeners l\\nJOIN sys.availability_group_listener_ip_addresses lip ON l.listener_id = lip.listener_id\\nJOIN sys.dm_hadr_availability_group_states ags ON l.group_id = ags.group_id\\nORDER BY lip.state_desc", "parameters": [], "description": "Confirm the AG listener IP is ONLINE and the AG synchronization health is HEALTHY"}	null	low	f	t	00:05:00	2026-02-24 13:10:27.204681
964	sqlserver	verify	Confirm expired certificate and affected endpoints	{"sql": "SELECT ep.name AS endpoint_name, ep.state_desc, ep.port,\\n  ep.connection_auth_desc, ep.certificate_id,\\n  c.name AS cert_name, c.expiry_date, c.start_date,\\n  c.subject, c.thumbprint,\\n  CASE WHEN c.expiry_date < GETDATE() THEN 'EXPIRED'\\n       WHEN c.expiry_date < DATEADD(day, 30, GETDATE()) THEN 'EXPIRING_SOON'\\n       ELSE 'VALID' END AS cert_status\\nFROM sys.database_mirroring_endpoints ep\\nLEFT JOIN sys.certificates c ON ep.certificate_id = c.certificate_id\\nORDER BY c.expiry_date", "parameters": [], "description": "Identify which certificates are expired or expiring and which endpoints use them"}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204682
5475	postgresql	execute	Terminate idle-in-transaction sessions beyond threshold	{"sql": "SELECT pg_terminate_backend(pid)\\nFROM pg_stat_activity\\nWHERE state = 'idle in transaction'\\n  AND xact_start < now() - interval ':threshold_minutes minutes';", "parameters": ["threshold_minutes"], "description": "Terminates sessions stuck in idle-in-transaction state beyond the configured threshold"}	\N	medium	t	f	seconds	2026-02-25 08:59:43.77256
967	sqlserver	verify	Assess current cluster reconfiguration state	{"sql": "SELECT c.cluster_name, c.quorum_type_desc, c.quorum_state_desc,\\n  cm.member_name, cm.member_state_desc, cm.number_of_quorum_votes,\\n  ags.synchronization_health_desc, ags.primary_replica,\\n  ar.replica_server_name, ar.availability_mode_desc, ar.failover_mode_desc,\\n  drs.connected_state_desc, drs.synchronization_state_desc,\\n  drs.log_send_queue_size, drs.redo_queue_size\\nFROM sys.dm_hadr_cluster c\\nCROSS JOIN sys.dm_hadr_cluster_members cm\\nLEFT JOIN sys.dm_hadr_availability_group_states ags ON 1=1\\nLEFT JOIN sys.availability_replicas ar ON ags.group_id = ar.group_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY cm.member_state_desc, ar.replica_server_name", "parameters": [], "description": "Capture a full picture of cluster and AG state during reconfiguration to determine if action is needed"}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204684
32022	mariadb	configure	mysql_increase_log_capacity	{"sql": "-- MySQL 8.0.30+: Dynamic redo log sizing:\\nSET PERSIST innodb_redo_log_capacity = 2147483648;\\n-- = 2GB\\n\\n-- Pre-8.0.30: Requires restart:\\n-- innodb_log_file_size = 512M\\n-- innodb_log_files_in_group = 2\\n\\n-- For undo space issues:\\nSET GLOBAL innodb_undo_log_truncate = ON;\\nSET PERSIST innodb_undo_log_truncate = ON;", "parameters": {"innodb_redo_log_capacity": "2GB for heavy maintenance (MySQL 8.0.30+)", "innodb_undo_log_truncate": "ON to auto-reclaim undo space"}, "description": "Increase redo log capacity for large maintenance operations. Enable undo log truncation to manage undo tablespace growth."}	\N	medium	t	t	5 minutes (dynamic) or requires restart (pre-8.0.3	2026-05-11 22:17:39.229791
968	sqlserver	instruct	Wait for cluster stabilization or intervene if stalled	{"sql": null, "parameters": [], "description": "Reconfiguration (upgrades, node additions) is typically transient. Recommended approach:\\n\\n1. Wait 5-10 minutes after the maintenance operation completes for automatic stabilization\\n\\n2. If quorum is NORMAL but one node remains DOWN after 10 minutes, check on that node:\\n   Get-ClusterNode -Name <node_name>\\n   Get-Service ClusSvc -ComputerName <node_name>\\n\\n3. If AG replica shows NOT SYNCHRONIZING after node returns, check if data movement is suspended:\\n   SELECT is_suspended, suspend_reason_desc FROM sys.dm_hadr_database_replica_states\\n   WHERE replica_id IN (SELECT replica_id FROM sys.availability_replicas\\n                        WHERE replica_server_name = '<node_name>')\\n\\n4. If the cluster was reconfigured with quorum votes changed (node add/remove), verify vote counts:\\n   Get-ClusterNode | Select Name, NodeWeight"}	null	low	f	t	00:30:00	2026-02-24 13:10:27.204684
969	sqlserver	execute	Resume AG synchronization and verify healthy state	{"sql": "-- Resume any AG databases that may have been suspended during reconfiguration\\nSELECT adc.database_name, ar.replica_server_name,\\n  drs.is_suspended, drs.suspend_reason_desc,\\n  drs.synchronization_state_desc, drs.log_send_queue_size, drs.redo_queue_size,\\n  'ALTER DATABASE [' + adc.database_name + '] SET HADR RESUME;' AS resume_cmd\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_databases_cluster adc ON drs.group_database_id = adc.group_database_id\\nWHERE drs.is_suspended = 1\\nORDER BY ar.replica_server_name, adc.database_name;\\n\\n-- Overall AG health after stabilization:\\nSELECT ag.name, ags.synchronization_health_desc, ags.primary_replica\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id;", "parameters": [], "description": "Identify any suspended AG databases and generate resume commands; verify overall AG health is HEALTHY"}	{"sql": "-- Suspend data movement again if resumption triggers unexpected issues:\\n-- ALTER DATABASE [<database_name>] SET HADR SUSPEND;"}	low	f	t	00:05:00	2026-02-24 13:10:27.204685
970	sqlserver	verify	Confirm I/O stall and cluster health symptoms consistent with AV interference	{"sql": "-- Check I/O stall per file (high values suggest AV scanning)\\nSELECT DB_NAME(vfs.database_id) AS database_name,\\n  mf.physical_name, mf.type_desc,\\n  vfs.io_stall_read_ms, vfs.num_of_reads,\\n  CASE WHEN vfs.num_of_reads > 0\\n       THEN vfs.io_stall_read_ms / vfs.num_of_reads ELSE 0 END AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms, vfs.num_of_writes,\\n  CASE WHEN vfs.num_of_writes > 0\\n       THEN vfs.io_stall_write_ms / vfs.num_of_writes ELSE 0 END AS avg_write_stall_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id\\n  AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 0\\n  AND (vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 50\\n    OR vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 50)\\nORDER BY avg_write_stall_ms DESC, avg_read_stall_ms DESC", "parameters": [], "description": "Identify files with high per-operation I/O stall that may indicate AV real-time scanning interference"}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204686
972	sqlserver	verify	Verify I/O stall reduction and cluster stability after exclusions applied	{"sql": "-- Reset I/O stats baseline (clears cumulative counters since last restart)\\n-- DBCC SQLPERF('sys.dm_io_virtual_file_stats', CLEAR); -- requires SA, use with caution\\n\\n-- Check current I/O stall after exclusions (wait 5-10 minutes after applying exclusions)\\nSELECT\\n  (SELECT SUM(io_stall_read_ms + io_stall_write_ms) / NULLIF(SUM(num_of_reads + num_of_writes), 0)\\n   FROM sys.dm_io_virtual_file_stats(NULL, NULL)) AS avg_io_stall_ms,\\n  cm.member_name, cm.member_state_desc,\\n  drs.connected_state_desc, drs.synchronization_health_desc\\nFROM sys.dm_hadr_cluster_members cm\\nCROSS JOIN sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nWHERE cm.member_name = @@SERVERNAME\\n  AND ar.replica_server_name = @@SERVERNAME", "parameters": [], "description": "Confirm I/O stall has decreased and cluster/AG health metrics are within normal bounds after AV exclusions"}	null	low	f	t	00:30:00	2026-02-24 13:10:27.204687
973	sqlserver	verify	Assess VM and cluster node health baseline	{"sql": "SELECT\\n  (SELECT DATEDIFF(MINUTE, sqlserver_start_time, GETDATE()) FROM sys.dm_os_sys_info) AS uptime_minutes,\\n  (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0)\\n   FROM sys.dm_os_wait_stats) AS signal_wait_pct,\\n  (SELECT SUM(io_stall_read_ms + io_stall_write_ms) / NULLIF(SUM(num_of_reads + num_of_writes), 0)\\n   FROM sys.dm_io_virtual_file_stats(NULL, NULL)) AS avg_io_stall_ms,\\n  cm.member_name, cm.member_state_desc, cm.number_of_quorum_votes\\nFROM sys.dm_hadr_cluster_members cm\\nWHERE cm.member_name = @@SERVERNAME", "parameters": [], "description": "Capture signal wait percentage, average I/O stall, and cluster membership state to confirm VM-related resource contention before taking action."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204687
974	sqlserver	instruct	Delete or quiesce active VM snapshots	{"sql": null, "parameters": [], "description": "In the hypervisor management console, identify and delete any active snapshots on the SQL Server VM. VM snapshots cause redirect-on-write I/O and severe disk performance degradation. For VMware: vCenter -> VM -> Snapshots -> Delete All. For Hyper-V: Hyper-V Manager -> VM -> Checkpoints -> Delete. Coordinate with backup team to ensure snapshot is not from an active backup job."}	null	medium	t	f	00:30:00	2026-02-24 13:10:27.204688
975	sqlserver	instruct	Live migrate VM to healthy host or resolve host resource contention	{"sql": null, "parameters": [], "description": "If host resource contention persists after snapshot removal, perform a live migration (vMotion or Hyper-V Live Migration) to a host with sufficient CPU and memory headroom. Verify destination host has: (1) sufficient free CPU cores, (2) sufficient free RAM, (3) low storage I/O load. Alternatively, work with VM admin to evict competing VMs from current host. Avoid migrating during peak business hours."}	null	medium	t	t	00:30:00	2026-02-24 13:10:27.204689
6225	postgresql	verify	Verify ETL handles current volume without resource exhaustion	{"sql": "SELECT count(*) AS target_rows FROM @target_table;\\nSELECT jobid, status, return_message, end_time - start_time AS duration FROM cron.job_run_details WHERE command LIKE '%etl%' ORDER BY start_time DESC LIMIT 5;", "parameters": ["target_table"], "description": "Confirms ETL completes successfully with the increased data volume."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
1056	sqlserver	verify	Capture current timeout settings and recent sp_server_diagnostics timing	{"sql": "SELECT ag.name, ag.health_check_timeout, ag.failure_condition_level,\\n  ags.synchronization_health_desc,\\n  CASE WHEN ag.health_check_timeout < 30000 THEN 'AGGRESSIVE (<30s)'\\n    WHEN ag.health_check_timeout < 60000 THEN 'STANDARD (30-60s)'\\n    ELSE 'RELAXED (>60s)' END AS assessment\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id;\\n-- Check Windows Cluster lease timeout\\nSELECT * FROM sys.dm_hadr_cluster;", "parameters": [], "description": "Documents current timeout settings before modification and checks cluster configuration for context"}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204689
976	sqlserver	verify	Confirm cluster node health and AG synchronization restored	{"sql": "SELECT cm.member_name, cm.member_state_desc, cm.number_of_quorum_votes,\\n  ars.role_desc, ars.connected_state_desc, ars.synchronization_health_desc,\\n  (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0)\\n   FROM sys.dm_os_wait_stats) AS signal_wait_pct\\nFROM sys.dm_hadr_cluster_members cm\\nLEFT JOIN sys.availability_replicas ar ON ar.replica_server_name = cm.member_name\\nLEFT JOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE cm.member_name = @@SERVERNAME", "parameters": [], "description": "Verify the cluster node is ONLINE, quorum votes are restored, AG replica is CONNECTED and HEALTHY, and signal wait percentage has returned to baseline (< 10%)."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.20469
977	sqlserver	verify	Identify scope of metadata corruption	{"sql": "SELECT ag.name AS ag_name, ag.group_id,\\n  ar.replica_server_name, ar.replica_id,\\n  ags.primary_replica,\\n  ars.role_desc, ars.operational_state_desc,\\n  ars.connected_state_desc, ars.synchronization_health_desc,\\n  drs.database_id, DB_NAME(drs.database_id) AS db_name,\\n  drs.synchronization_state_desc, drs.is_suspended\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nLEFT JOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id\\nLEFT JOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY ag.name, ar.replica_server_name", "parameters": [], "description": "Identify which replicas show NULL operational state or DISCONNECTED state, and which databases are NOT SYNCHRONIZING, to scope the repair needed."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.20469
979	sqlserver	verify	Validate AG metadata consistency and synchronization	{"sql": "-- Wait 30 seconds for synchronization to begin, then check:\\nSELECT ar.replica_server_name,\\n  ars.role_desc, ars.operational_state_desc,\\n  ars.connected_state_desc, ars.synchronization_health_desc,\\n  drs.synchronization_state_desc,\\n  drs.log_send_queue_size, drs.redo_queue_size\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY ar.replica_server_name;", "parameters": [], "description": "Confirm the re-added replica shows CONNECTED state, ONLINE operational state, and databases are progressing toward SYNCHRONIZED state. Log send and redo queue sizes should be decreasing."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.204692
980	sqlserver	verify	Confirm failover threshold exhaustion and document current AG configuration	{"sql": "-- Check AG failover settings\\nSELECT ag.name, ag.failure_condition_level, ag.health_check_timeout,\\n  ar.replica_server_name, ar.failover_mode_desc, ar.availability_mode_desc,\\n  ars.role_desc, ars.synchronization_health_desc\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE ar.failover_mode_desc = 'AUTOMATIC';\\n\\n-- Check Windows event log for failover events via SQL\\nEXEC xp_readerrorlog 0, 1, N'failover', NULL, NULL, NULL, N'desc';", "parameters": [], "description": "Document the current failure condition level, health check timeout, and review error log for recent failover events to understand what triggered repeated failovers."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.204692
981	sqlserver	instruct	Reset WSFC cluster group failover threshold via PowerShell	{"sql": null, "parameters": ["AgName: partial name of the availability group to find the cluster group", "AG_Cluster_Group_Name: exact cluster group name from Get-ClusterGroup output"], "description": "Run the following PowerShell on any cluster node to reset the failover threshold for the AG cluster group. This clears the failover count without changing the configured maximum:\\n\\n# Find the AG cluster resource group name\\nGet-ClusterGroup | Where-Object {$_.Name -like '*<AgName>*'}\\n\\n# Reset the failover count (sets current count back to 0)\\n$group = Get-ClusterGroup -Name '<AG_Cluster_Group_Name>'\\n$group.FailoverCount = 0\\n\\n# Optionally increase the threshold period or max failovers:\\n# $group.FailoverPeriod = 6  # hours\\n# $group.FailoverThreshold = 3  # max failovers in period\\n\\nNote: If the cluster group is in a Failed state, also run:\\nStart-ClusterGroup -Name '<AG_Cluster_Group_Name>'"}	null	medium	t	t	00:05:00	2026-02-24 13:10:27.204693
1052	sqlserver	verify	Confirm AG replica connectivity restored	{"sql": "SELECT ar.replica_server_name, drs.connected_state_desc,\\n  ags.synchronization_health_desc\\nFROM sys.availability_replicas ar\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE ags.synchronization_health_desc = 'HEALTHY';", "parameters": [], "description": "Validates that all replicas show CONNECTED state and the AG reports HEALTHY synchronization after the certificate change"}	null	low	f	t	00:05:00	2026-02-24 13:10:27.204737
1010	sqlserver	verify	Identify the least-damaged replica and confirm recoverable state	{"sql": "SELECT ar.replica_server_name,\\n  ars.role_desc, ars.operational_state_desc,\\n  ars.connected_state_desc, ars.synchronization_health_desc,\\n  cm.member_state_desc AS cluster_state,\\n  CASE WHEN ars.operational_state_desc IS NULL OR ars.connected_state_desc = 'DISCONNECTED' OR cm.member_state_desc <> 'UP'\\n    THEN 'FAILED' ELSE 'OK' END AS health\\nFROM sys.availability_replicas ar\\nLEFT JOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_cluster_members cm ON ar.replica_server_name = cm.member_name\\nORDER BY ar.replica_server_name;", "parameters": [], "description": "Identify which replicas are failed vs. recoverable and determine which has the most current data."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204694
982	sqlserver	execute	Adjust AG failure condition level if needed	{"sql": "-- Optionally tune failure condition level if it was too sensitive\\n-- Level 1 = OnServerDown (least sensitive)\\n-- Level 2 = OnServerUnresponsive (default recommended)\\n-- Level 3 = OnCriticalServerErrors\\n-- Level 4 = OnModerateServerErrors  \\n-- Level 5 = OnAnyQualifiedFailureCondition (most sensitive)\\n-- Replace 'AgName' with actual AG name\\nALTER AVAILABILITY GROUP [AgName]\\n  SET (FAILURE_CONDITION_LEVEL = 3);\\n\\n-- Optionally increase health check timeout (default 30000ms)\\nALTER AVAILABILITY GROUP [AgName]\\n  SET (HEALTH_CHECK_TIMEOUT = 60000);", "parameters": ["AgName: availability group name", "FAILURE_CONDITION_LEVEL: choose 2-3 for most environments; avoid 4-5 in production", "HEALTH_CHECK_TIMEOUT: milliseconds; default 30000; increase to 60000 for cloud/VM environments"], "description": "If repeated failovers were caused by transient conditions (brief network blips, short OS pauses), increase the failure condition level or health check timeout to reduce false-positive failover triggering."}	{"sql": "-- Revert to default settings if behavior worsens\\nALTER AVAILABILITY GROUP [AgName]\\n  SET (FAILURE_CONDITION_LEVEL = 2, HEALTH_CHECK_TIMEOUT = 30000);"}	medium	t	t	00:01:00	2026-02-24 13:10:27.204694
983	sqlserver	verify	Confirm automatic failover is re-enabled and AG is healthy	{"sql": "SELECT ag.name, ag.failure_condition_level, ag.health_check_timeout,\\n  ar.replica_server_name, ar.failover_mode_desc,\\n  ars.role_desc, ars.synchronization_health_desc\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE ar.failover_mode_desc = 'AUTOMATIC'\\nORDER BY ag.name;", "parameters": [], "description": "Verify automatic failover replicas show HEALTHY synchronization health and AUTOMATIC failover mode is active. Confirm the cluster group is no longer in Failed state."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204695
984	sqlserver	verify	Assess current quorum state and voting members	{"sql": "SELECT c.cluster_name, c.quorum_type_desc, c.quorum_state_desc,\\n  cm.member_name, cm.member_type_desc, cm.member_state_desc,\\n  cm.number_of_quorum_votes\\nFROM sys.dm_hadr_cluster c\\nCROSS JOIN sys.dm_hadr_cluster_members cm\\nORDER BY cm.member_type_desc, cm.member_name;", "parameters": [], "description": "Identify which cluster members are OFFLINE or not voting, the quorum type, and current quorum state. This determines whether quorum can be recovered by bringing members back online versus requiring forced quorum."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204695
985	sqlserver	instruct	Attempt to restore quorum by bringing offline nodes or witness back online	{"sql": null, "parameters": ["NodeName: name of offline cluster node"], "description": "Primary recovery approach — avoid forced quorum if possible:\\n\\n1. If a witness (file share or cloud) is offline, restore it first as this is least disruptive:\\n   - For file share witness: ensure the file share server is running and the share is accessible\\n   - For cloud witness: verify Azure storage account and firewall rules\\n   - In Failover Cluster Manager: right-click cluster -> Properties -> Quorum -> Configure Cluster Quorum to re-point witness if needed\\n\\n2. If a cluster node is offline:\\n   - Start the Windows Server cluster service: Start-ClusterNode -Name <NodeName>\\n   - Or in Failover Cluster Manager: right-click node -> Start Cluster Service\\n\\n3. After bringing members online, verify quorum state recovers automatically within 30-60 seconds."}	null	medium	t	t	00:30:00	2026-02-24 13:10:27.204696
987	sqlserver	verify	Confirm quorum restored and AG automatic failover re-enabled	{"sql": "SELECT c.quorum_type_desc, c.quorum_state_desc,\\n  cm.member_name, cm.member_state_desc, cm.number_of_quorum_votes,\\n  ags.primary_replica, ags.synchronization_health_desc\\nFROM sys.dm_hadr_cluster c\\nCROSS JOIN sys.dm_hadr_cluster_members cm\\nCROSS JOIN sys.dm_hadr_availability_group_states ags\\nORDER BY cm.member_type_desc;", "parameters": [], "description": "Verify quorum_state_desc = 'NORMAL_QUORUM', all expected members show ONLINE state, and the AG shows a primary_replica with HEALTHY synchronization."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204697
988	sqlserver	verify	Diagnose synchronization lag root cause	{"sql": "SELECT ar.replica_server_name,\\n  drs.synchronization_state_desc, drs.is_suspended, drs.suspend_reason_desc,\\n  drs.log_send_queue_size / 1024.0 AS log_send_queue_mb,\\n  drs.log_send_rate / 1024.0 AS log_send_rate_mb_per_sec,\\n  drs.redo_queue_size / 1024.0 AS redo_queue_mb,\\n  drs.redo_rate / 1024.0 AS redo_rate_mb_per_sec,\\n  drs.last_sent_time, drs.last_received_time,\\n  drs.last_hardened_time, drs.last_redone_time,\\n  DATEDIFF(SECOND, drs.last_hardened_time, GETDATE()) AS seconds_since_hardened\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE ars.role_desc = 'SECONDARY'\\nORDER BY drs.log_send_queue_size DESC;", "parameters": [], "description": "Determine whether lag is caused by data movement suspension, log send queue backlog, or redo queue backlog, and identify send/redo rates to estimate time-to-synchronize."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204698
1011	sqlserver	instruct	Fix root cause on each failed node	{"sql": null, "parameters": [], "description": "On each failed node, remediate the underlying issue before attempting rejoin: (1) Disk full: free space on data/log/tempdb drives. (2) Config error: correct registry/SQL Server configuration and restart service. (3) OS failure: restore OS or VM snapshot. Validate the SQL Server service is RUNNING on each node before proceeding."}	null	medium	t	f	00:30:00	2026-02-24 13:10:27.204699
989	sqlserver	execute	Resume suspended data movement if applicable	{"sql": "-- If data movement is suspended (is_suspended = 1), resume it:\\n-- Option 1: Resume for a specific database on the secondary\\n-- Run on SECONDARY replica for each suspended database\\nALTER DATABASE [DatabaseName] SET HADR RESUME;\\n\\n-- Option 2: Resume all suspended databases from PRIMARY\\n-- Run on PRIMARY — replaces per-DB resume\\nALTER AVAILABILITY GROUP [AgName] RESUME;\\n\\n-- Verify suspension lifted:\\nSELECT DB_NAME(database_id), synchronization_state_desc, is_suspended, suspend_reason_desc\\nFROM sys.dm_hadr_database_replica_states\\nWHERE is_suspended = 1;", "parameters": ["DatabaseName: name of suspended AG database", "AgName: availability group name"], "description": "If synchronization was manually suspended or auto-suspended due to an error, resume data movement. This is the most common fix for NOT SYNCHRONIZING state."}	{"sql": "-- To re-suspend if resuming causes unexpected load:\\nALTER DATABASE [DatabaseName] SET HADR SUSPEND;"}	low	f	t	00:01:00	2026-02-24 13:10:27.204699
990	sqlserver	instruct	Address log send or redo queue backlog	{"sql": null, "parameters": [], "description": "If data movement is active but queue is large:\\n\\nFor large LOG_SEND_QUEUE (network bottleneck):\\n- Check network utilization between primary and secondary\\n- Verify AG endpoint compression is enabled: SELECT compression FROM sys.availability_replicas\\n- Enable compression if not set: ALTER AVAILABILITY GROUP [AgName] MODIFY REPLICA ON N'SecondaryServer' WITH (COMPRESSION = ON)\\n- Consider scheduling high-write workloads during off-peak hours\\n- Check for network QoS policies throttling replication traffic\\n\\nFor large REDO_QUEUE (secondary I/O bottleneck):\\n- Check I/O subsystem performance on secondary (disk latency)\\n- Ensure secondary storage is not overloaded by other workloads\\n- If secondary is used for read workloads, consider adding a read-only routing replica to distribute the load\\n- Allow the redo queue to drain naturally once I/O pressure is reduced"}	null	low	f	t	00:30:00	2026-02-24 13:10:27.2047
991	sqlserver	verify	Confirm secondary reached SYNCHRONIZED state	{"sql": "SELECT ar.replica_server_name,\\n  ars.role_desc, ars.synchronization_health_desc,\\n  drs.synchronization_state_desc, drs.is_suspended,\\n  drs.log_send_queue_size, drs.redo_queue_size\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE ars.role_desc = 'SECONDARY'\\nORDER BY ar.replica_server_name;", "parameters": [], "description": "Verify the secondary replica shows synchronization_state_desc = 'SYNCHRONIZED', is_suspended = 0, and both send and redo queues are near zero, indicating automatic failover eligibility is restored."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204701
992	sqlserver	verify	Confirm replicas are in synchronous-commit mode and synchronized	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ar.availability_mode_desc,\\n  ar.failover_mode_desc,\\n  ars.role_desc,\\n  ars.synchronization_health_desc,\\n  drs.synchronization_state_desc\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY ag.name, ars.role_desc DESC;", "parameters": [], "description": "Verify the replicas intended for automatic failover are in SYNCHRONOUS_COMMIT availability mode and SYNCHRONIZED synchronization state. Automatic failover requires both conditions."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204701
993	sqlserver	execute	Change availability mode to SYNCHRONOUS_COMMIT if needed	{"sql": "-- Only run if availability_mode_desc is ASYNCHRONOUS_COMMIT\\n-- Run on PRIMARY\\n-- Replace 'AgName' and 'SecondaryServerName' with actual values\\nALTER AVAILABILITY GROUP [AgName]\\n  MODIFY REPLICA ON N'SecondaryServerName'\\n  WITH (AVAILABILITY_MODE = SYNCHRONOUS_COMMIT);\\n\\n-- Wait for SYNCHRONIZED state before proceeding (check every 30s):\\nSELECT drs.synchronization_state_desc, drs.log_send_queue_size, drs.redo_queue_size\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nWHERE ar.replica_server_name = N'SecondaryServerName';", "parameters": ["AgName: availability group name", "SecondaryServerName: server name of the secondary replica"], "description": "Switch the target replica from ASYNCHRONOUS_COMMIT to SYNCHRONOUS_COMMIT mode, which is required for automatic failover. Wait for SYNCHRONIZED state before changing failover mode."}	{"sql": "-- Revert to async if synchronous mode causes unacceptable primary performance impact\\nALTER AVAILABILITY GROUP [AgName]\\n  MODIFY REPLICA ON N'SecondaryServerName'\\n  WITH (AVAILABILITY_MODE = ASYNCHRONOUS_COMMIT, FAILOVER_MODE = MANUAL);"}	medium	t	t	00:05:00	2026-02-24 13:10:27.204702
994	sqlserver	execute	Set failover mode to AUTOMATIC on both primary and secondary replicas	{"sql": "-- Run on PRIMARY — set AUTOMATIC failover on the secondary\\n-- Replace 'AgName', 'SecondaryServerName', and 'PrimaryServerName'\\nALTER AVAILABILITY GROUP [AgName]\\n  MODIFY REPLICA ON N'SecondaryServerName'\\n  WITH (FAILOVER_MODE = AUTOMATIC);\\n\\n-- Also set primary replica to AUTOMATIC (both sides must be AUTOMATIC)\\nALTER AVAILABILITY GROUP [AgName]\\n  MODIFY REPLICA ON N'PrimaryServerName'\\n  WITH (FAILOVER_MODE = AUTOMATIC);\\n\\n-- Verify the change took effect:\\nSELECT ar.replica_server_name, ar.failover_mode_desc, ar.availability_mode_desc\\nFROM sys.availability_replicas ar\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE ag.name = N'AgName';", "parameters": ["AgName: availability group name", "SecondaryServerName: server name of the secondary replica", "PrimaryServerName: server name of the current primary replica"], "description": "Enable automatic failover mode on both the primary and the designated secondary. Both replicas in a failover pair must be set to AUTOMATIC for automatic failover to work."}	{"sql": "-- Revert both replicas to MANUAL if automatic failover causes issues\\nALTER AVAILABILITY GROUP [AgName]\\n  MODIFY REPLICA ON N'SecondaryServerName'\\n  WITH (FAILOVER_MODE = MANUAL);\\nALTER AVAILABILITY GROUP [AgName]\\n  MODIFY REPLICA ON N'PrimaryServerName'\\n  WITH (FAILOVER_MODE = MANUAL);"}	medium	t	t	00:01:00	2026-02-24 13:10:27.204702
995	sqlserver	verify	Confirm automatic failover is active and AG is healthy	{"sql": "SELECT ag.name, ag.failure_condition_level, ag.health_check_timeout,\\n  ar.replica_server_name, ar.availability_mode_desc, ar.failover_mode_desc,\\n  ars.role_desc, ars.synchronization_health_desc,\\n  drs.synchronization_state_desc\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY ag.name, ars.role_desc DESC;", "parameters": [], "description": "Confirm both replicas show AUTOMATIC failover mode, SYNCHRONOUS_COMMIT availability mode, and synchronization_health_desc = 'HEALTHY'."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204703
5296	sqlserver	verify	Confirm hardened state	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'xp_cmdshell') AS xp_cmdshell,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'Ole Automation Procedures') AS ole_auto,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits;", "parameters": [], "description": "Verifies hardened state with active auditing."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.885526
1000	sqlserver	verify	Review current health check timeout and failure condition settings	{"sql": "SELECT ag.name,\\n  ag.health_check_timeout AS health_check_timeout_ms,\\n  ag.failure_condition_level,\\n  CASE ag.failure_condition_level\\n    WHEN 1 THEN 'OnServerDown'\\n    WHEN 2 THEN 'OnServerUnresponsive'\\n    WHEN 3 THEN 'OnCriticalServerErrors'\\n    WHEN 4 THEN 'OnModerateServerErrors'\\n    WHEN 5 THEN 'OnAnyQualifiedFailureCondition'\\n  END AS failure_condition_desc,\\n  ags.primary_replica,\\n  ags.synchronization_health_desc\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id;\\n\\n-- Also check for recent health-check-related errors in SQL log\\nEXEC xp_readerrorlog 0, 1, N'health', NULL, NULL, NULL, N'desc';", "parameters": [], "description": "Document the current health_check_timeout value and failure_condition_level. Default timeout is 30000ms (30 seconds). Review recent error log for health check-related entries."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204706
1001	sqlserver	execute	Adjust health check timeout to environment-appropriate value	{"sql": "-- Increase health check timeout for VM/cloud environments\\n-- Range: 15000ms to 4294967295ms; default 30000ms\\n-- Recommended for VM/cloud: 60000ms (60 seconds)\\n-- Replace 'AgName' with actual AG name\\nALTER AVAILABILITY GROUP [AgName]\\n  SET (HEALTH_CHECK_TIMEOUT = 60000);\\n\\n-- Optionally adjust failure condition level\\n-- Level 3 (OnCriticalServerErrors) is recommended for most environments\\n-- Reduces false positives from transient errors vs default Level 2\\nALTER AVAILABILITY GROUP [AgName]\\n  SET (FAILURE_CONDITION_LEVEL = 3);\\n\\n-- Verify the change:\\nSELECT name, health_check_timeout, failure_condition_level\\nFROM sys.availability_groups\\nWHERE name = N'AgName';", "parameters": ["AgName: availability group name", "HEALTH_CHECK_TIMEOUT: 60000 for VMs, 30000 for physical servers, 90000 for high-latency cloud", "FAILURE_CONDITION_LEVEL: 2 (default), 3 (recommended for most), 4-5 only for specific requirements"], "description": "Increase the health check timeout from the default 30 seconds to 60 seconds for virtualized environments, reducing false-positive failovers caused by transient VM pause events (vMotion, snapshot, host maintenance)."}	{"sql": "-- Revert to default if the new timeout causes unacceptably slow failure detection\\nALTER AVAILABILITY GROUP [AgName]\\n  SET (HEALTH_CHECK_TIMEOUT = 30000, FAILURE_CONDITION_LEVEL = 2);"}	low	f	t	00:01:00	2026-02-24 13:10:27.204706
