1029	sqlserver	execute	Identify and kill stuck HADR-related sessions	{"sql": "-- Identify sessions associated with stuck AG connections\\nSELECT s.session_id, s.login_name, s.program_name,\\n  s.status, s.last_request_start_time,\\n  DATEDIFF(MINUTE, s.last_request_start_time, GETDATE()) AS idle_minutes,\\n  c.client_net_address, c.connect_time\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.program_name LIKE '%Availability%'\\n  OR s.login_name LIKE '%SQL%Replication%'\\n  OR DATEDIFF(MINUTE, s.last_request_start_time, GETDATE()) > 60\\nORDER BY idle_minutes DESC;\\n\\n-- Kill specific stuck sessions (replace with actual session_id)\\n-- KILL <session_id>;", "parameters": [], "description": "Identify AG-related sessions stuck in connection timeout state and kill any that have been idle for more than 60 minutes."}	null	low	f	f	00:01:00	2026-02-24 13:10:27.204723
1030	sqlserver	execute	Adjust session timeout to accelerate reconnect detection	{"sql": "-- Reduce session_timeout on replicas to force faster detection of dead connections\\n-- Default is 10 seconds; reduce to 5 for faster recovery\\nALTER AVAILABILITY GROUP [<ag_name>]\\n  MODIFY REPLICA ON N'<replica_server_name>'\\n  WITH (SESSION_TIMEOUT = 5);\\n\\n-- Restore to default after reconnection is confirmed\\n-- ALTER AVAILABILITY GROUP [<ag_name>]\\n--   MODIFY REPLICA ON N'<replica_server_name>'\\n--   WITH (SESSION_TIMEOUT = 10);", "parameters": [{"name": "ag_name", "description": "Availability Group name"}, {"name": "replica_server_name", "description": "Name of the disconnected replica"}], "description": "Temporarily reduce session timeout to force AG to detect and drop stuck connections faster, triggering reconnect attempts."}	{"sql": "ALTER AVAILABILITY GROUP [<ag_name>]\\n  MODIFY REPLICA ON N'<replica_server_name>'\\n  WITH (SESSION_TIMEOUT = 10);"}	low	f	t	00:01:00	2026-02-24 13:10:27.204723
