1079	sqlserver	verify	Monitor AG for spurious failover events after recalibration	{"sql": "-- Check error log for failover and timeout events (last 24 hours)\\nDECLARE @since datetime = DATEADD(hour, -24, GETDATE());\\nCREATE TABLE #errorlog (LogDate datetime, ProcessInfo nvarchar(100), Text nvarchar(4000));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'HADR';\\nSELECT * FROM #errorlog\\nWHERE (Text LIKE '%failover%' OR Text LIKE '%timeout%' OR Text LIKE '%health%')\\n  AND LogDate >= @since\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog;", "parameters": [], "description": "Reviews SQL Server error log for HADR-related messages after the configuration change to confirm that spurious failover events have stopped"}	null	low	f	t	00:30:00	2026-02-24 13:10:27.204756
1080	sqlserver	verify	Confirm secondary replica connection policy and read-only state	{"sql": "SELECT ar.replica_server_name,\\n  ar.secondary_role_allow_connections_desc,\\n  ars.role_desc,\\n  d.name AS db_name, d.is_read_only, d.state_desc,\\n  CASE\\n    WHEN ars.role_desc = 'SECONDARY' AND ar.secondary_role_allow_connections_desc = 'NO'\\n      THEN 'SECONDARY_NO_CONNECTIONS'\\n    WHEN ars.role_desc = 'SECONDARY' AND ar.secondary_role_allow_connections_desc = 'READ_ONLY'\\n      THEN 'SECONDARY_READ_ONLY'\\n    WHEN ars.role_desc = 'SECONDARY' AND ar.secondary_role_allow_connections_desc = 'ALL'\\n      THEN 'SECONDARY_ALL_CONNECTIONS'\\n    ELSE 'PRIMARY'\\n    END AS connection_config\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nJOIN sys.dm_hadr_database_replica_states drs ON ars.replica_id = drs.replica_id\\nJOIN sys.databases d ON drs.database_id = d.database_id\\nWHERE ars.is_local = 1;", "parameters": [], "description": "Documents the current secondary connection policy and confirms which databases are in read-only state, establishing what the health check should expect on each replica type"}	null	low	f	t	00:01:00	2026-02-24 13:10:27.204756
