1527	sqlserver	execute	Create AG role monitoring job	{"sql": "USE msdb;\\nGO\\n\\n-- Create monitoring job\\nEXEC sp_add_job\\n  @job_name = N'AG Primary Role Monitor',\\n  @enabled = 1,\\n  @description = N'Detects AG role anomalies including dual-primary scenarios',\\n  @category_name = N'Database Maintenance';\\n\\nEXEC sp_add_jobstep\\n  @job_name = N'AG Primary Role Monitor',\\n  @step_name = N'Check AG role state',\\n  @command = N'\\nIF EXISTS (\\n  SELECT 1\\n  FROM sys.dm_hadr_availability_replica_states ars\\n  WHERE ars.is_local = 1\\n    AND ars.role_desc = ''PRIMARY''\\n    AND NOT EXISTS (\\n      SELECT 1 FROM sys.dm_hadr_availability_group_states ags\\n      WHERE ags.group_id = ars.group_id\\n        AND ags.primary_replica = @@SERVERNAME\\n    )\\n)\\nBEGIN\\n  RAISERROR (N''ALERT: AG role mismatch detected — local replica claims PRIMARY but cluster disagrees.'', 16, 1) WITH LOG;\\nEND\\n',\\n  @on_fail_action = 4,\\n  @on_fail_step_id = 0;\\n\\nEXEC sp_add_jobschedule\\n  @job_name = N'AG Primary Role Monitor',\\n  @name = N'Every 2 minutes',\\n  @freq_type = 4,\\n  @freq_interval = 1,\\n  @freq_subday_type = 4,\\n  @freq_subday_interval = 2;\\n\\nEXEC sp_add_jobserver\\n  @job_name = N'AG Primary Role Monitor',\\n  @server_name = N'(local)';\\nGO", "parameters": {"schedule_interval_minutes": 2}, "description": "Creates a SQL Server Agent job that runs every 2 minutes to check for AG role mismatches and logs an error when detected. The RAISERROR with log triggers WMI event-based alerts."}	{"sql": "USE msdb; EXEC sp_delete_job @job_name = N'AG Primary Role Monitor';", "description": "Remove monitoring job if deployment fails or conflicts."}	low	f	t	00:05:00	2026-02-24 13:10:27.264477
1528	sqlserver	configure	Create SQL Server Agent alert for role anomaly errors	{"sql": "USE msdb;\\nGO\\n\\nEXEC sp_add_alert\\n  @name = N'AG Role Anomaly Detected',\\n  @message_id = 0,\\n  @severity = 16,\\n  @enabled = 1,\\n  @delay_between_responses = 60,\\n  @notification_message = N'AG primary role mismatch detected. Investigate immediately to prevent split-brain data divergence.',\\n  @include_event_description_in = 1;\\n\\nEXEC sp_add_notification\\n  @alert_name = N'AG Role Anomaly Detected',\\n  @operator_name = N'DBA Team',\\n  @notification_method = 1;  -- 1=email, 2=pager, 4=netsend\\nGO", "parameters": {"operator_name": "DBA Team", "notification_method": "1 (email)"}, "description": "Wires a SQL Server Agent alert to the severity-16 errors raised by the monitoring job, routing notifications to the DBA Team operator via email. Replace 'DBA Team' with the actual operator name."}	{"sql": "USE msdb;\\nEXEC sp_delete_notification @alert_name = N'AG Role Anomaly Detected', @operator_name = N'DBA Team';\\nEXEC sp_delete_alert @name = N'AG Role Anomaly Detected';", "description": "Remove alert and notification if rollback is needed."}	low	f	t	00:05:00	2026-02-24 13:10:27.264477
1529	sqlserver	verify	Capture AG replica connectivity baseline and error log evidence	{"sql": "-- Current connectivity state\\nSELECT ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc,\\n  ars.last_connect_error_number,\\n  ars.last_connect_error_description,\\n  ars.last_connect_error_timestamp,\\n  drs.synchronization_state_desc,\\n  drs.last_hardened_time\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY ar.replica_server_name;\\n\\n-- Current session timeout (seconds)\\nSELECT ar.replica_server_name,\\n  ar.session_timeout\\nFROM sys.availability_replicas ar;", "parameters": {}, "description": "Document the current connectivity errors, last connection error timestamps, and session_timeout values for all replicas. Review SQL Server error log for repeated 'HADR_WORK_QUEUE' or 'The availability replica is in failed state' messages."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.264478
1531	sqlserver	configure	Increase AG session timeout to tolerate transient network events	{"sql": "-- Run on PRIMARY replica\\n-- Increase session_timeout from default 10s to 30s for each secondary\\n-- Replace 'SecondaryReplicaName' with actual replica names\\nALTER AVAILABILITY GROUP [<AGName>]\\n  MODIFY REPLICA ON N'<SecondaryReplicaName>'\\n  WITH (SESSION_TIMEOUT = 30);\\nGO\\n\\n-- Verify change applied\\nSELECT ar.replica_server_name, ar.session_timeout\\nFROM sys.availability_replicas ar;", "parameters": {"ag_name": "<AGName> — replace with actual availability group name", "default_session_timeout_seconds": 10, "recommended_session_timeout_seconds": 30}, "description": "Increase session_timeout from the default 10 seconds to 30 seconds per replica. This prevents an AG failover from triggering on brief network interruptions under 30 seconds. Must be run from the primary replica for each secondary."}	{"sql": "-- Revert to default 10-second timeout\\nALTER AVAILABILITY GROUP [<AGName>]\\n  MODIFY REPLICA ON N'<SecondaryReplicaName>'\\n  WITH (SESSION_TIMEOUT = 10);", "description": "Restore default session timeout if the change causes issues."}	medium	t	t	00:10:00	2026-02-24 13:10:27.26448
