1534	sqlserver	verify	Confirm cluster and AG connectivity restored	{"sql": "-- Confirm all cluster members are UP\\nSELECT cm.member_name, cm.member_state_desc, cm.number_of_quorum_votes,\\n  c.quorum_state_desc\\nFROM sys.dm_hadr_cluster_members cm\\nCROSS JOIN sys.dm_hadr_cluster c;\\n\\n-- Confirm AG replicas reconnected\\nSELECT ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc,\\n  ars.operational_state_desc,\\n  drs.synchronization_state_desc,\\n  drs.last_hardened_time\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nORDER BY ars.role_desc DESC;", "parameters": {}, "description": "All WSFC cluster members should show member_state_desc = 'UP' and quorum_state_desc = 'NORMAL_QUORUM'. All AG replicas should be CONNECTED and SYNCHRONIZED."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.264482
