1562	sqlserver	configure	Create replication error and long-running agent alerts	{"sql": "-- Alert: Replication agent failure (event ID 20575)\\nEXEC msdb.dbo.sp_add_alert\\n  @name = N'Replication: Agent Failure',\\n  @message_id = 20575,\\n  @severity = 0,\\n  @notification_message = N'A replication agent has failed. Review Replication Monitor.',\\n  @job_id = NULL;\\nEXEC msdb.dbo.sp_add_notification\\n  @alert_name = N'Replication: Agent Failure',\\n  @operator_name = N'DBA_Team',\\n  @notification_method = 1; -- 1=email\\n\\n-- Alert: Replication warning - subscriber not delivering (14151)\\nEXEC msdb.dbo.sp_add_alert\\n  @name = N'Replication: Subscriber Not Delivering',\\n  @message_id = 14151,\\n  @severity = 0,\\n  @notification_message = N'Subscriber is not delivering in a timely manner.',\\n  @job_id = NULL;\\nEXEC msdb.dbo.sp_add_notification\\n  @alert_name = N'Replication: Subscriber Not Delivering',\\n  @operator_name = N'DBA_Team',\\n  @notification_method = 1;\\n\\n-- Alert: Replication warning threshold (14150 - custom threshold breach)\\nEXEC msdb.dbo.sp_add_alert\\n  @name = N'Replication: Threshold Warning',\\n  @message_id = 14150,\\n  @severity = 0,\\n  @notification_message = N'A replication threshold has been exceeded.',\\n  @job_id = NULL;\\nEXEC msdb.dbo.sp_add_notification\\n  @alert_name = N'Replication: Threshold Warning',\\n  @operator_name = N'DBA_Team',\\n  @notification_method = 1;", "parameters": {"message_ids": "20575 (agent failure), 14151 (subscriber not delivering), 14150 (threshold breach)"}, "description": "Creates three critical replication alerts covering agent failure, delivery lag, and threshold breaches. These correspond to the most common replication warning events raised by the Replication Monitor internals."}	{"sql": "EXEC msdb.dbo.sp_delete_alert @name = N'Replication: Agent Failure';\\nEXEC msdb.dbo.sp_delete_alert @name = N'Replication: Subscriber Not Delivering';\\nEXEC msdb.dbo.sp_delete_alert @name = N'Replication: Threshold Warning';", "description": "Remove created alerts if a different alerting strategy is adopted."}	low	f	t	00:10:00	2026-02-24 13:10:27.27655
