1625	sqlserver	verify	Confirm replication is healthy and no new conflicts exist	{"sql": "-- Check distribution agent status (run on DISTRIBUTOR)\\nSELECT TOP 5\\n  da.name AS agent_name,\\n  da.subscriber_db,\\n  dh.runstatus,  -- 1=start,2=succeed,3=active,4=idle,5=retry,6=fail\\n  dh.time,\\n  dh.comments\\nFROM distribution.dbo.MSdistribution_agents da\\nJOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\nORDER BY dh.time DESC;\\n\\n-- Confirm no new duplicate key errors in last 15 minutes\\nSELECT COUNT(*) AS new_errors\\nFROM distribution.dbo.MSdistribution_history\\nWHERE error_id <> 0\\n  AND time > DATEADD(MINUTE, -15, GETDATE());", "parameters": {}, "description": "Verify the distribution agent is running cleanly (runstatus = 2 or 3) and no new duplicate key errors have appeared since the fix was applied."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.285649
1626	sqlserver	execute	Identify the missing row and retrieve its current state from publisher	{"sql": "-- Run on DISTRIBUTOR: find the failing command details\\nSELECT TOP 10\\n  dh.xact_seqno, dh.command_id, dh.agent_id,\\n  dh.comments, dh.time\\nFROM distribution.dbo.MSdistribution_history dh\\nWHERE dh.error_id <> 0\\n  AND (dh.comments LIKE '%Row not found%'\\n    OR dh.comments LIKE '%not find the row%'\\n    OR dh.comments LIKE '%0 row(s) affected%')\\nORDER BY dh.time DESC;\\n\\n-- Run on PUBLISHER: retrieve the current state of the row\\n-- Replace <schema>, <table>, <pk_column>, <pk_value> from the error message\\n-- SELECT * FROM <schema>.<table> WHERE <pk_column> = <pk_value>;", "parameters": {"distributor_db": "distribution"}, "description": "Locate the failing UPDATE command in distribution history and retrieve the current authoritative row state from the publisher."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.28565
1732	sqlserver	verify	Confirm job instance ended and next run is scheduled	{"sql": "SELECT j.name,\\n  ja.start_execution_date,\\n  ja.stop_execution_date,\\n  ja.next_scheduled_run_date,\\n  CASE WHEN ja.stop_execution_date IS NOT NULL THEN 'STOPPED'\\n       WHEN ja.start_execution_date IS NULL THEN 'IDLE'\\n       ELSE 'STILL RUNNING' END AS execution_state\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.name = @job_name;", "parameters": {"@job_name": "Job name"}, "description": "Confirm stop_execution_date is now populated and next_scheduled_run_date reflects the next expected run."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.292432
1627	sqlserver	execute	Insert the missing row on subscriber and restart distribution agent	{"sql": "-- Run on SUBSCRIBER: insert the missing row using publisher data\\n-- INSERT INTO <schema>.<table> (<col1>, <col2>, ...) VALUES (<val1>, <val2>, ...);\\n-- Use the values retrieved from the publisher in Step 1.\\n\\n-- After inserting, restart the distribution agent:\\nEXEC msdb.dbo.sp_start_job @job_name = N'<distribution_agent_job_name>';\\n\\n-- Alternatively, configure the distribution agent to use the 'compensate for errors'\\n-- subscriber update delivery option (sets @SubscriberUploadOption for resync):\\n-- EXEC sp_changesubscription\\n--   @rootcauseation = N'<rootcauseation>',\\n--   @article = N'all',\\n--   @subscriber = N'<subscriber>',\\n--   @destination_db = N'<subscriber_db>',\\n--   @property = N'sync_type',\\n--   @value = N'automatic';", "parameters": {"subscriber_action": "INSERT missing row from publisher state"}, "description": "Insert the publisher's authoritative row into the subscriber so the pending UPDATE can be applied, then restart the distribution agent to resume replication."}	{"sql": "-- If the inserted row is incorrect, delete it:\\n-- DELETE FROM <schema>.<table> WHERE <pk_column> = <pk_value>;", "description": "Remove the manually inserted row from the subscriber if the data was incorrect."}	medium	t	t	00:10:00	2026-02-24 13:10:27.285651
1628	sqlserver	verify	Confirm agent is processing and no further row-not-found errors	{"sql": "-- Check agent runstatus (2=succeed, 3=active are healthy)\\nSELECT TOP 5\\n  da.name, da.subscriber_db,\\n  dh.runstatus, dh.time, dh.comments\\nFROM distribution.dbo.MSdistribution_agents da\\nJOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\nORDER BY dh.time DESC;\\n\\n-- Check for new row-not-found errors\\nSELECT COUNT(*) AS errors_last_15min\\nFROM distribution.dbo.MSdistribution_history\\nWHERE error_id <> 0\\n  AND comments LIKE '%Row not found%'\\n  AND time > DATEADD(MINUTE, -15, GETDATE());", "parameters": {}, "description": "Verify the distribution agent has resumed successfully and is not generating new row-not-found errors."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.285651
1629	sqlserver	execute	Confirm the failing command is a DELETE and row is absent on subscriber	{"sql": "-- Run on DISTRIBUTOR: identify the failing command type\\nSELECT TOP 10\\n  dc.command, dc.command_id, dc.xact_seqno,\\n  dh.comments, dh.time\\nFROM distribution.dbo.MSdistribution_history dh\\nJOIN distribution.dbo.MSrepl_commands dc\\n  ON dh.xact_seqno = dc.xact_seqno\\nWHERE dh.error_id <> 0\\n  AND (dh.comments LIKE '%Row not found%'\\n    OR dh.comments LIKE '%not find the row%')\\nORDER BY dh.time DESC;\\n\\n-- Run on SUBSCRIBER: confirm row is absent\\n-- SELECT COUNT(*) FROM <schema>.<table> WHERE <pk_column> = <pk_value>;", "parameters": {}, "description": "Verify the failing command is a DELETE and confirm the target row does not exist on the subscriber, making the desired end state already achieved."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.285652
1630	sqlserver	configure	Configure distribution agent to skip row-not-found errors for DELETEs	{"sql": "-- Option A: Set distribution agent to use 'compensate for errors' mode\\n-- This skips DELETE commands that fail with row-not-found (error 20598)\\nEXEC distribution.dbo.sp_changesubscription\\n  @rootcauseation      = N'<rootcauseation_name>',\\n  @article          = N'all',\\n  @subscriber       = N'<subscriber_server>',\\n  @destination_db   = N'<subscriber_db>',\\n  @property         = N'SkipErrors',\\n  @value            = N'20598';\\n\\n-- Option B: Add skip error to distribution agent profile\\n-- Run on DISTRIBUTOR to add error 20598 to the agent skip list\\nEXEC distribution.dbo.sp_add_agent_parameter\\n  @profile_id     = <agent_profile_id>,  -- retrieve from MSagent_profiles\\n  @parameter_name = N'-SkipErrors',\\n  @parameter_value = N'20598';\\n\\n-- View agent profiles to find profile_id:\\n-- SELECT * FROM distribution.dbo.MSagent_profiles WHERE agent_type = 3;", "parameters": {"applies_to": "transactional replication distribution agent", "skip_error_code": "20598"}, "description": "Configure the distribution agent to skip error 20598 (row not found for DELETE), which is safe because the desired end state (row absent) is already met."}	{"sql": "-- Remove the SkipErrors setting to restore default strict behavior:\\nEXEC distribution.dbo.sp_changesubscription\\n  @rootcauseation    = N'<rootcauseation_name>',\\n  @article        = N'all',\\n  @subscriber     = N'<subscriber_server>',\\n  @destination_db = N'<subscriber_db>',\\n  @property       = N'SkipErrors',\\n  @value          = N'';", "description": "Remove the SkipErrors configuration if it is no longer needed or was set incorrectly."}	low	t	t	00:10:00	2026-02-24 13:10:27.285652
1631	sqlserver	verify	Restart agent and confirm replication resumes without errors	{"sql": "-- Restart the distribution agent job\\nEXEC msdb.dbo.sp_start_job @job_name = N'<distribution_agent_job_name>';\\n\\n-- Wait 2-3 minutes, then check status\\nSELECT TOP 5\\n  da.name, da.subscriber_db,\\n  dh.runstatus, dh.time, dh.comments,\\n  dh.delivered_commands\\nFROM distribution.dbo.MSdistribution_agents da\\nJOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\nORDER BY dh.time DESC;", "parameters": {}, "description": "Restart the distribution agent and verify it is running cleanly, advancing through commands without stopping on the previously failing DELETE."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.285653
1632	sqlserver	execute	Identify and kill long-running sessions on the secondary blocking redo	{"sql": "-- Run on the SECONDARY replica\\n-- Identify long-running queries (>300s) that may be holding version snapshots\\nSELECT\\n  r.session_id,\\n  DATEDIFF(SECOND, r.start_time, GETDATE()) AS duration_sec,\\n  r.command, r.status, r.wait_type,\\n  DB_NAME(r.database_id) AS database_name,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE DATEDIFF(SECOND, r.start_time, GETDATE()) > 300\\n  AND r.database_id > 4\\nORDER BY duration_sec DESC;\\n\\n-- Kill the most impactful long-running session (replace <session_id>)\\n-- KILL <session_id>;", "parameters": {"duration_threshold_seconds": 300}, "description": "On the secondary replica, identify queries running longer than 300 seconds that are holding version store snapshots and preventing redo thread progress, then terminate the worst offenders."}	null	medium	t	f	00:10:00	2026-02-24 13:10:27.285654
1639	sqlserver	execute	Terminate long-running snapshot transactions on the secondary	{"sql": "-- Run on SECONDARY: identify and kill long-running snapshot transactions\\nSELECT\\n  s.session_id,\\n  DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS age_sec,\\n  t.transaction_type,\\n  DB_NAME(dt.database_id)    AS database_name,\\n  s.login_name,\\n  s.program_name\\nFROM sys.dm_tran_active_snapshot_database_transactions ast\\nJOIN sys.dm_tran_active_transactions        t  ON ast.transaction_id = t.transaction_id\\nJOIN sys.dm_tran_session_transactions       st ON t.transaction_id   = st.transaction_id\\nJOIN sys.dm_exec_sessions                  s  ON st.session_id       = s.session_id\\nLEFT JOIN sys.dm_tran_database_transactions dt ON t.transaction_id   = dt.transaction_id\\nWHERE DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 600\\nORDER BY age_sec DESC;\\n\\n-- Kill the longest-running session (replace <session_id>):\\n-- KILL <session_id>;", "parameters": {"age_threshold_seconds": 600}, "description": "On the secondary replica, identify snapshot transactions older than 10 minutes and terminate them to allow the version store to be reclaimed by cleanup processes."}	null	medium	t	f	00:10:00	2026-02-24 13:10:27.285658
1633	sqlserver	configure	Set query governor or connection timeout on readable secondary to prevent future stalls	{"sql": "-- Option A: Set a query timeout at the database level using Resource Governor\\n-- Create a classifier function that routes secondary read workloads to a pool with a max execution time\\n-- This is environment-specific; consult Resource Governor documentation.\\n\\n-- Option B: Configure AG to allow redo thread to take priority using session_timeout\\n-- On PRIMARY: reduce secondary session timeout to force stalled reader reconnection\\nALTER AVAILABILITY GROUP [<ag_name>]\\n  MODIFY REPLICA ON N'<secondary_server>'\\n  WITH (SESSION_TIMEOUT = 30);  -- default is 10; lower value forces faster failover detection\\n\\n-- Option C: Use READ_ONLY_ROUTING_URL and application-side query timeout\\n-- Ensure application sets CommandTimeout <= 300 seconds for secondary reads\\n\\n-- Check current AG replica settings\\nSELECT\\n  ar.replica_server_name,\\n  ar.session_timeout,\\n  ar.secondary_role_allow_connections_desc,\\n  ar.read_only_routing_url\\nFROM sys.availability_replicas ar;", "parameters": {"recommended_query_timeout_seconds": 300, "recommended_session_timeout_seconds": 30}, "description": "Configure session timeout or Resource Governor policies to prevent future long-running read queries from stalling the AG redo thread on the secondary."}	{"sql": "-- Restore default session timeout if changed:\\nALTER AVAILABILITY GROUP [<ag_name>]\\n  MODIFY REPLICA ON N'<secondary_server>'\\n  WITH (SESSION_TIMEOUT = 10);", "description": "Restore the default AG session timeout if the modified value causes unintended failover behavior."}	medium	t	t	00:15:00	2026-02-24 13:10:27.285654
1634	sqlserver	verify	Confirm redo queue is draining and secondary is catching up	{"sql": "-- Run on PRIMARY: watch redo_queue_size decrease over 5 minutes\\nSELECT\\n  ar.replica_server_name,\\n  DB_NAME(drs.database_id)     AS database_name,\\n  drs.redo_queue_size,\\n  drs.redo_rate,\\n  drs.synchronization_state_desc,\\n  drs.last_redone_time,\\n  DATEDIFF(SECOND, drs.last_redone_time, GETDATE()) AS seconds_since_last_redo\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nWHERE drs.is_primary_replica = 0\\nORDER BY drs.redo_queue_size DESC;", "parameters": {"healthy_redo_queue_threshold_kb": 500}, "description": "Verify that redo_queue_size is decreasing and last_redone_time is updating, confirming the secondary redo thread has resumed normal operation."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.285655
1635	sqlserver	execute	Identify candidate key column on publisher and subscriber	{"sql": "-- Run on PUBLISHER: find candidate unique columns\\nSELECT\\n  c.name         AS column_name,\\n  t.name         AS data_type,\\n  c.is_nullable,\\n  c.is_identity\\nFROM sys.columns c\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nWHERE c.object_id = OBJECT_ID('<schema>.<table>')\\nORDER BY c.column_id;\\n\\n-- Check for existing unique indexes that could serve as PK\\nSELECT\\n  i.name        AS index_name,\\n  i.is_unique,\\n  i.is_primary_key,\\n  STRING_AGG(c.name, ', ') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_columns\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\nJOIN sys.columns c        ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nWHERE i.object_id = OBJECT_ID('<schema>.<table>')\\n  AND i.is_unique = 1\\nGROUP BY i.name, i.is_unique, i.is_primary_key;", "parameters": {}, "description": "Identify a suitable candidate key column (non-nullable, unique) that can be promoted to primary key, or determine if a surrogate identity column must be added."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.285655
1637	sqlserver	configure	Update replication article to recognize the new primary key	{"sql": "-- Refresh the article schema in the rootcauseation to pick up the new PK\\nEXEC sp_articlecolumn\\n  @rootcauseation = N'<rootcauseation_name>',\\n  @article     = N'<article_name>';\\n\\n-- Alternatively, drop and re-add the article with the correct schema_option\\n-- to include primary key replication (bit 0x0000000000000004):\\n-- EXEC sp_droparticle @rootcauseation = N'<pub>', @article = N'<article>';\\n-- EXEC sp_addarticle @rootcauseation = N'<pub>', @article = N'<article>',\\n--   @source_object = N'<table>', @schema_option = 0x000000000C034FD1;\\n\\n-- For merge replication: re-run snapshot agent after adding ROWGUIDCOL\\n-- EXEC sp_startmergerootcauseation_snapshot @rootcauseation = N'<rootcauseation_name>';", "parameters": {}, "description": "Refresh the replication article definition to include the new primary key constraint, ensuring the distribution or merge agent will use it for row identification."}	null	medium	t	t	00:15:00	2026-02-24 13:10:27.285657
1638	sqlserver	verify	Confirm replication applies UPDATE and DELETE operations successfully	{"sql": "-- Check for replication errors related to key or identity issues\\nSELECT TOP 10\\n  re.time, re.error_code, re.error_text\\nFROM distribution.dbo.MSrepl_errors re\\nWHERE re.time > DATEADD(MINUTE, -30, GETDATE())\\nORDER BY re.time DESC;\\n\\n-- Verify published table now has primary key on publisher and subscriber\\nSELECT\\n  'Publisher' AS node,\\n  OBJECTPROPERTY(OBJECT_ID('<schema>.<table>'), 'TableHasPrimaryKey') AS has_pk\\nUNION ALL\\n-- Run second SELECT on subscriber or via linked server\\nSELECT 'Subscriber', NULL;  -- replace NULL with linked server query if applicable", "parameters": {}, "description": "Verify no new identity or key-related replication errors appear, and that both publisher and subscriber report a primary key on the table."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.285657
1741	sqlserver	verify	Measure typical database recovery time after startup	{"sql": "-- Approximate recovery completion time from error log\\nEXEC sys.xp_readerrorlog 0, 1, N'Recovery completed', NULL, NULL, NULL, N'desc';\\n\\n-- Also check startup time vs current time\\nSELECT\\n  sqlserver_start_time,\\n  GETDATE() AS now,\\n  DATEDIFF(minute, sqlserver_start_time, GETDATE()) AS uptime_minutes\\nFROM sys.dm_os_sys_info;", "parameters": {}, "description": "Review the SQL Server error log for 'Recovery completed' messages on past startups to determine the worst-case time between SQL Server start and all databases becoming available."}	null	low	f	t	00:03:00	2026-02-24 13:10:27.292437
