31363	mariadb	diagnose	mysql_check_timeout_configuration	{"sql": "SELECT @@connect_timeout AS connect_timeout, @@wait_timeout AS wait_timeout, @@interactive_timeout AS interactive_timeout, @@net_read_timeout AS net_read_timeout, @@net_write_timeout AS net_write_timeout, @@lock_wait_timeout AS lock_wait_timeout;", "parameters": [], "description": "Review all timeout-related MySQL settings"}	\N	low	f	t	seconds	2026-05-11 22:17:39.229791
1730	sqlserver	verify	Assess running instance state and blocking	{"sql": "SELECT j.name AS job_name,\\n  ja.run_requested_date,\\n  DATEDIFF(minute, ja.run_requested_date, GETDATE()) AS running_minutes,\\n  r.session_id, r.status, r.wait_type,\\n  r.blocking_session_id,\\n  r.total_elapsed_time / 60000 AS elapsed_minutes,\\n  r.open_transaction_count,\\n  LEFT(t.text, 300) AS current_sql\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nJOIN sys.dm_exec_sessions s\\n  ON s.program_name LIKE '%Job 0x%'\\nJOIN sys.dm_exec_requests r ON r.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL\\n  AND j.name = @job_name;", "parameters": {"@job_name": "Job identified by detection"}, "description": "Determine whether the job is actively executing (status=running), blocked on another session, or simply a long-running but healthy process."}	null	low	f	t	00:03:00	2026-02-24 13:10:27.29243
1707	sqlserver	configure	Schedule frequent log backups and configure log space alerting	{"sql": "-- Verify a log backup job exists and its schedule\\nSELECT\\n  j.name AS job_name,\\n  j.enabled,\\n  sc.freq_type,\\n  sc.freq_interval,\\n  sc.freq_subday_type,\\n  sc.freq_subday_interval\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules sc ON jsc.schedule_id = sc.schedule_id\\nWHERE j.name LIKE '%log backup%' OR j.name LIKE '%transaction log%'\\nORDER BY j.name;\\n\\n-- Add alert for Error 9002 (log full) with immediate notification\\nEXEC msdb.dbo.sp_add_alert\\n  @name = N'Transaction Log Full - 9002',\\n  @message_id = 9002,\\n  @severity = 0,\\n  @enabled = 1,\\n  @delay_between_responses = 300,\\n  @notification_message = N'Transaction log full (9002). Immediate log backup required.';", "parameters": null, "description": "Ensure log backups run at least every 15-30 minutes for FULL recovery databases with high write volumes. Add an alert for error 9002 to notify DBAs immediately when the log fills in the future."}	{"sql": "EXEC msdb.dbo.sp_delete_alert @name = N'Transaction Log Full - 9002';", "description": "Remove the alert if it generates false positives."}	low	f	t	00:15:00	2026-02-24 13:10:27.292419
1708	sqlserver	verify	Identify the constraint, affected table, and violating data	{"sql": "-- Extract constraint name and table from error message\\nSELECT TOP 10\\n  j.name AS job_name,\\n  h.message,\\n  CASE\\n    WHEN h.message LIKE '%Msg 547,%' THEN 'FK or CHECK violation'\\n    WHEN h.message LIKE '%Msg 2627,%' THEN 'PK or UNIQUE violation'\\n    WHEN h.message LIKE '%Msg 2601,%' THEN 'UNIQUE INDEX violation'\\n    WHEN h.message LIKE '%Cannot insert the value NULL%' THEN 'NOT NULL violation'\\n    ELSE 'OTHER'\\n  END AS violation_type\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -3, GETDATE()), 112))\\n  AND (h.message LIKE '%Msg 547,%' OR h.message LIKE '%Msg 2627,%'\\n    OR h.message LIKE '%Msg 2601,%' OR h.message LIKE '%Cannot insert the value NULL%')\\nORDER BY h.run_date DESC, h.run_time DESC;\\n\\n-- Look up the constraint definition\\nSELECT\\n  cc.name AS constraint_name,\\n  OBJECT_NAME(cc.parent_object_id) AS table_name,\\n  cc.type_desc,\\n  cc.definition\\nFROM sys.check_constraints cc\\nWHERE cc.is_disabled = 0\\nUNION ALL\\nSELECT\\n  fk.name,\\n  OBJECT_NAME(fk.parent_object_id),\\n  'FOREIGN_KEY_CONSTRAINT',\\n  OBJECT_NAME(fk.referenced_object_id)\\nFROM sys.foreign_keys fk\\nWHERE fk.is_disabled = 0;", "parameters": null, "description": "Parse the error message to extract the constraint name and table. Look up the constraint definition to understand what data rule is being violated, then find the offending rows."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.29242
1715	sqlserver	execute	Start the SQL Server Agent service and set startup type to Automatic	{"sql": "-- Start the Agent service using T-SQL (SQL Server Configuration Manager preferred)\\n-- T-SQL cannot directly start Windows services; use xp_cmdshell or PowerShell\\n\\n-- Option A: Start via PowerShell (run on the SQL Server host)\\n-- Start-Service -Name 'SQLSERVERAGENT'\\n-- Set-Service  -Name 'SQLSERVERAGENT' -StartupType Automatic\\n\\n-- Option B: Start via xp_cmdshell (if enabled and authorized)\\n-- EXEC master..xp_cmdshell 'net start SQLSERVERAGENT';\\n\\n-- Option C: Start via SQL Server Configuration Manager (GUI)\\n-- SQL Server Configuration Manager > SQL Server Services >\\n--   Right-click SQL Server Agent > Start\\n--   Right-click SQL Server Agent > Properties > Start Mode = Automatic\\n\\n-- Confirm Agent started successfully\\nWAITFOR DELAY '00:00:10';\\nSELECT servicename, status_desc, startup_type_desc, last_startup_time\\nFROM sys.dm_server_services\\nWHERE servicename LIKE '%Agent%';", "parameters": null, "description": "Start the SQL Server Agent service using the appropriate method for the environment. Set startup type to Automatic to ensure it restarts after server reboots. Prefer SQL Server Configuration Manager over net start for named instances."}	{"sql": null, "description": "To stop the Agent service if it was started incorrectly: use SQL Server Configuration Manager or 'net stop SQLSERVERAGENT'. All running jobs will be cancelled."}	medium	t	t	00:05:00	2026-02-24 13:10:27.292424
1716	sqlserver	verify	Confirm jobs are executing and review any missed job runs	{"sql": "-- Verify Agent is running and connected\\nSELECT TOP 1\\n  session_id,\\n  agent_start_date,\\n  DATEDIFF(minute, agent_start_date, GETDATE()) AS uptime_minutes\\nFROM msdb.dbo.syssessions\\nORDER BY session_id DESC;\\n\\n-- Check for jobs that were scheduled to run while Agent was down\\nSELECT\\n  j.name AS job_name,\\n  j.enabled,\\n  jh.last_run_date,\\n  jh.last_run_time,\\n  jh.last_run_outcome,\\n  jh.next_run_date,\\n  jh.next_run_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysjobactivity jh ON j.job_id = jh.job_id\\nWHERE j.enabled = 1\\n  AND jh.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\nORDER BY jh.next_run_date, jh.next_run_time;\\n\\n-- Manually trigger any missed critical jobs\\n-- EXEC msdb.dbo.sp_start_job N'<MissedJobName>';", "parameters": null, "description": "Confirm the Agent session is active and identify jobs that missed their scheduled runs while the service was stopped. Manually trigger critical missed jobs (e.g., log backups, ETL jobs) as needed."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.292425
