1718	sqlserver	execute	Update schedule with valid future active_end_date and re-enable	{"sql": "USE msdb;\\nEXEC dbo.sp_update_schedule\\n  @schedule_id        = @schedule_id,\\n  @name               = @schedule_name,\\n  @enabled            = 1,\\n  @freq_type          = @freq_type,\\n  @freq_interval      = @freq_interval,\\n  @freq_subday_type   = @freq_subday_type,\\n  @freq_subday_interval = @freq_subday_interval,\\n  @freq_recurrence_factor = @freq_recurrence_factor,\\n  @active_start_date  = @new_start_date,\\n  @active_end_date    = 99991231,\\n  @active_start_time  = @active_start_time,\\n  @active_end_time    = @active_end_time;", "parameters": {"@freq_type": "Desired frequency: 1=one-time, 4=daily, 8=weekly, 16=monthly", "@schedule_id": "schedule_id from step 1", "@freq_interval": "Interval value appropriate for freq_type", "@schedule_name": "Existing schedule name", "@new_start_date": "Today or next desired run date as YYYYMMDD integer", "@freq_subday_type": "1=once, 2=seconds, 4=minutes, 8=hours", "@active_start_time": "Start time as HHMMSS integer", "@freq_subday_interval": "Subday interval count (0 for once-per-day)", "@freq_recurrence_factor": "Weeks/months between executions (0 for daily)"}, "description": "Update the schedule to use 99991231 (no end date) or a valid future end date, and set enabled=1. For a one-time schedule that should recur, change freq_type to 4 (Daily) or 8 (Weekly) with appropriate interval."}	{"sql": "USE msdb;\\nEXEC dbo.sp_update_schedule\\n  @schedule_id       = @schedule_id,\\n  @enabled           = 0,\\n  @active_end_date   = @original_active_end_date;", "description": "Disable the schedule and restore the original end date to return to pre-change state."}	low	t	t	00:02:00	2026-02-24 13:10:27.292426
1719	sqlserver	verify	Confirm next scheduled run date is now in the future	{"sql": "SELECT j.name AS job_name, ja.next_scheduled_run_date,\\n  CASE WHEN ja.next_scheduled_run_date > GETDATE() THEN 'SCHEDULED OK'\\n       WHEN ja.next_scheduled_run_date IS NULL THEN 'STILL UNSCHEDULED'\\n       ELSE 'NEXT RUN IN PAST' END AS status\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.name = @job_name;", "parameters": {"@job_name": "Name of the affected job"}, "description": "Confirm SQL Server Agent has computed a valid next_scheduled_run_date in the future for the job."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.292427
1720	sqlserver	verify	Confirm server UTC offset and compute corrected schedule time	{"sql": "SELECT\\n  SYSDATETIMEOFFSET() AS server_now_with_offset,\\n  DATEPART(TZOFFSET, SYSDATETIMEOFFSET()) AS utc_offset_minutes,\\n  -- Example: if intended time is 02:00 UTC and server is UTC-5,\\n  -- corrected local time = 02:00 - (-300 min) = 21:00 previous day\\n  -- Adjust @intended_utc_time by offset to get server local HHMMSS:\\n  (@intended_utc_time_hhmmss\\n    + (DATEPART(TZOFFSET, SYSDATETIMEOFFSET()) / 60) * 10000) AS corrected_local_time_approx;", "parameters": {"@intended_utc_time_hhmmss": "Intended run time in UTC as HHMMSS integer (e.g. 020000 for 02:00 UTC)"}, "description": "Calculate the corrected active_start_time by adjusting the intended UTC (or source-timezone) time by the server's UTC offset. The result is the HHMMSS integer to use in the schedule."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.292427
1722	sqlserver	verify	Confirm next_scheduled_run_date reflects corrected time	{"sql": "SELECT j.name, ja.next_scheduled_run_date,\\n  DATEPART(hour, ja.next_scheduled_run_date) AS scheduled_hour_local,\\n  DATEPART(minute, ja.next_scheduled_run_date) AS scheduled_minute_local\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.name = @job_name;", "parameters": {"@job_name": "Affected job name"}, "description": "Verify the Agent has recalculated next_scheduled_run_date and it matches the intended local run time."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.292428
1727	sqlserver	verify	Identify specific invalid parameter and correct value	{"sql": "SELECT j.name AS job_name, s.schedule_id, s.name AS schedule_name,\\n  s.freq_type, s.freq_interval, s.freq_subday_type,\\n  s.freq_subday_interval, s.freq_relative_interval,\\n  s.freq_recurrence_factor,\\n  s.active_start_date, s.active_end_date,\\n  s.active_start_time, s.active_end_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nWHERE j.name = @job_name;", "parameters": {"@job_name": "Affected job name"}, "description": "Retrieve full schedule parameters to identify exactly which value is invalid. Refer to detection query schedule_problem column for guidance on which parameter to fix."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.292428
1738	sqlserver	execute	Stagger overlapping job schedules to reduce peak concurrency	{"sql": "-- Identify jobs with overlapping schedule times\\nSELECT j.name AS job_name, s.active_start_time, s.freq_type,\\n  s.freq_subday_interval, s.freq_subday_type\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nWHERE j.enabled = 1 AND s.enabled = 1\\nORDER BY s.active_start_time;\\n\\n-- Update schedule start time to offset by N minutes for affected jobs:\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id       = @schedule_id,\\n  @active_start_time = @staggered_start_time;", "parameters": {"@schedule_id": "Schedule ID of the job to stagger", "@staggered_start_time": "New start time as HHMMSS with offset applied"}, "description": "Offset the active_start_time of jobs that collide at the same minute by 1-5 minutes each. This is the safest, lowest-risk approach to reducing concurrency."}	{"sql": "EXEC msdb.dbo.sp_update_schedule\\n  @schedule_id       = @schedule_id,\\n  @active_start_time = @original_start_time;", "description": "Restore original schedule start time."}	low	t	t	00:10:00	2026-02-24 13:10:27.292435
1728	sqlserver	execute	Update schedule with corrected parameter values	{"sql": "USE msdb;\\nEXEC dbo.sp_update_schedule\\n  @schedule_id              = @schedule_id,\\n  @freq_type                = @corrected_freq_type,\\n  @freq_interval            = @corrected_freq_interval,\\n  @freq_subday_type         = @corrected_freq_subday_type,\\n  @freq_subday_interval     = @corrected_freq_subday_interval,\\n  @freq_relative_interval   = @corrected_freq_relative_interval,\\n  @freq_recurrence_factor   = @corrected_freq_recurrence_factor,\\n  @active_start_date        = @corrected_active_start_date,\\n  @active_end_date          = @corrected_active_end_date,\\n  @active_start_time        = @active_start_time,\\n  @active_end_time          = @active_end_time,\\n  @enabled                  = 1;", "parameters": {"@schedule_id": "Schedule ID from step 1", "@corrected_freq_type": "Valid freq_type: 1,4,8,16,32,64,128", "@corrected_freq_interval": "Valid interval for freq_type (e.g., day bitmask for weekly)", "@corrected_active_end_date": "YYYYMMDD; use 99991231 for no end date", "@corrected_freq_subday_type": "1=once, 2=sec, 4=min, 8=hr", "@corrected_active_start_date": "YYYYMMDD; must be <= active_end_date", "@corrected_freq_subday_interval": "Must be >=1 when freq_subday_type is 2/4/8", "@corrected_freq_recurrence_factor": "Must be >=1 for freq_type 8/16/32", "@corrected_freq_relative_interval": "1=first, 2=second, 4=third, 8=fourth, 16=last (for freq_type=32)"}, "description": "Apply corrected values. Only supply parameters that differ from the existing valid values; sp_update_schedule preserves unspecified fields."}	{"sql": "USE msdb;\\nEXEC dbo.sp_update_schedule\\n  @schedule_id  = @schedule_id,\\n  @enabled      = 0;", "description": "Disable the schedule to prevent execution while the original parameters are investigated."}	low	t	t	00:03:00	2026-02-24 13:10:27.292429
1733	sqlserver	verify	Quantify worker thread headroom and identify top consumers	{"sql": "SELECT\\n  osi.max_workers_count,\\n  SUM(os.current_workers_count) AS current_workers,\\n  SUM(os.active_workers_count)  AS active_workers,\\n  osi.max_workers_count - SUM(os.current_workers_count) AS free_workers,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS user_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests) AS active_requests\\nFROM sys.dm_os_schedulers os\\nCROSS JOIN sys.dm_os_sys_info osi\\nWHERE os.status = 'VISIBLE ONLINE'\\nGROUP BY osi.max_workers_count;\\n\\n-- Top session consumers\\nSELECT TOP 20 s.session_id, s.program_name, s.login_name,\\n  s.status, r.wait_type, r.total_elapsed_time / 1000 AS elapsed_sec\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_exec_requests r ON r.session_id = s.session_id\\nWHERE s.is_user_process = 1\\nORDER BY r.total_elapsed_time DESC;", "parameters": {}, "description": "Measure free_workers headroom and identify which sessions are consuming threads to determine whether to kill sessions, increase max_worker_threads, or both."}	null	low	f	t	00:03:00	2026-02-24 13:10:27.292432
1734	sqlserver	execute	Kill idle/sleeping sessions to immediately free worker threads	{"sql": "-- Identify killable idle sessions (sleeping, no open transactions, idle >30 min)\\nSELECT s.session_id, s.login_name, s.program_name,\\n  s.last_request_end_time,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_minutes\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count = 0\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 30\\nORDER BY idle_minutes DESC;\\n\\n-- Kill each identified session (execute per session_id):\\n-- KILL @session_id;", "parameters": {"@session_id": "Session ID to kill, from the SELECT above"}, "description": "Terminate sleeping sessions with no open transactions that have been idle over 30 minutes. Each KILL immediately releases the worker thread back to the pool."}	null	medium	t	f	00:05:00	2026-02-24 13:10:27.292433
1736	sqlserver	verify	Confirm THREADPOOL waits cleared and Agent jobs executing	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'THREADPOOL';\\n\\nSELECT COUNT(*) AS running_agent_jobs\\nFROM msdb.dbo.sysjobactivity ja\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL;", "parameters": {}, "description": "Verify THREADPOOL wait_time_ms is no longer accumulating and that Agent jobs are now executing."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.292434
1737	sqlserver	verify	Identify which jobs are running concurrently and their subsystems	{"sql": "SELECT j.name AS job_name, js.subsystem,\\n  ja.start_execution_date,\\n  DATEDIFF(minute, ja.start_execution_date, GETDATE()) AS running_minutes,\\n  s.max_worker_threads AS subsystem_max,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobactivity ja2\\n   JOIN msdb.dbo.sysjobsteps js2 ON ja2.job_id = js2.job_id\\n     AND ja2.last_executed_step_id = js2.step_id\\n   WHERE ja2.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n     AND ja2.start_execution_date IS NOT NULL\\n     AND ja2.stop_execution_date IS NULL\\n     AND js2.subsystem = js.subsystem) AS active_in_subsystem\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js\\n  ON js.job_id = j.job_id AND js.step_id = ja.last_executed_step_id\\nJOIN msdb.dbo.syssubsystems s ON s.subsystem = js.subsystem\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL\\nORDER BY running_minutes DESC;", "parameters": {}, "description": "Identify which subsystem (TSQL, PowerShell, CmdExec, etc.) is saturated and how many jobs are concurrently active within it."}	null	low	f	t	00:03:00	2026-02-24 13:10:27.292435
5235	sqlserver	verify	Confirm keys are rotated and schedule is documented	{"sql": "SELECT d.name AS database_name,\\n  dek.key_algorithm, dek.key_length,\\n  dek.create_date, dek.regenerate_date,\\n  DATEDIFF(DAY, COALESCE(dek.regenerate_date, dek.create_date), GETDATE()) AS days_since_rotation\\nFROM sys.dm_database_encryption_keys dek\\nJOIN sys.databases d ON dek.database_id = d.database_id\\nWHERE dek.encryption_state = 3;", "parameters": [], "description": "Verifies TDE DEKs have been recently rotated."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.871464
1739	sqlserver	configure	Increase subsystem max_worker_threads if staggering is not sufficient	{"sql": "-- Review current subsystem limits\\nSELECT subsystem, max_worker_threads FROM msdb.dbo.syssubsystems;\\n\\n-- Increase for the saturated subsystem (requires sysadmin)\\nUPDATE msdb.dbo.syssubsystems\\nSET max_worker_threads = @new_thread_limit\\nWHERE subsystem = @subsystem_name;\\n\\n-- Restart Agent for change to take effect\\n-- EXEC msdb.dbo.sp_stop_job N'...' is not sufficient;\\n-- restart SQLSERVERAGENT service via SQL Server Configuration Manager", "parameters": {"@subsystem_name": "Subsystem name, e.g., 'CmdExec', 'PowerShell', 'TSQL'", "@new_thread_limit": "New maximum concurrent threads for this subsystem (e.g., 0 for unlimited, or a specific count)"}, "description": "Directly update the max_worker_threads value in syssubsystems for the saturated subsystem. A SQL Server Agent service restart is required for the change to take effect."}	{"sql": "UPDATE msdb.dbo.syssubsystems\\nSET max_worker_threads = @original_limit\\nWHERE subsystem = @subsystem_name;", "description": "Restore original subsystem thread limit and restart Agent service."}	medium	t	t	00:05:00	2026-02-24 13:10:27.292436
1740	sqlserver	verify	Confirm pending job now starts after schedule/limit change	{"sql": "SELECT j.name, ja.start_execution_date, ja.stop_execution_date,\\n  ja.next_scheduled_run_date\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.name = @job_name;", "parameters": {"@job_name": "The job that was failing to start"}, "description": "Confirm the previously blocked job now shows a start_execution_date at its next scheduled time."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.292437
