1742	sqlserver	execute	Add retry logic to job step and increase retry interval	{"sql": "USE msdb;\\n-- Increase retry attempts and interval on the first job step\\nEXEC dbo.sp_update_jobstep\\n  @job_name         = @job_name,\\n  @step_id          = 1,\\n  @retry_attempts   = 5,\\n  @retry_interval   = 10;  -- 10 minutes between retries\\n\\n-- Verify\\nSELECT step_name, retry_attempts, retry_interval\\nFROM msdb.dbo.sysjobsteps\\nWHERE job_id = (SELECT job_id FROM msdb.dbo.sysjobs WHERE name = @job_name)\\n  AND step_id = 1;", "parameters": {"@step_id": "Step ID that failed with database-not-available error (usually 1)", "@job_name": "Job name"}, "description": "Set retry_attempts=5 and retry_interval=10 (minutes) on the job's first step. With 5 retries at 10 minutes each, the job will keep trying for up to 50 minutes after initial failure, covering most startup recovery windows."}	{"sql": "USE msdb;\\nEXEC dbo.sp_update_jobstep\\n  @job_name       = @job_name,\\n  @step_id        = 1,\\n  @retry_attempts = @original_retry_attempts,\\n  @retry_interval = @original_retry_interval;", "description": "Restore original retry settings."}	low	f	t	00:02:00	2026-02-24 13:10:27.292438
1743	sqlserver	configure	Optionally add startup delay via SQL Server Agent startup job	{"sql": "-- Alternative: Schedule the job with a minimum delay after Agent starts\\n-- Change schedule from freq_type=64 (Agent start) to a time-based daily schedule\\n-- set to a time that is always after recovery completes.\\nUSE msdb;\\nEXEC dbo.sp_update_schedule\\n  @schedule_id    = @schedule_id,\\n  @freq_type      = 4,          -- Daily\\n  @freq_interval  = 1,\\n  @freq_subday_type = 1,        -- Once per day\\n  @active_start_time = @safe_start_time_hhmmss;  -- e.g., 060000 = 06:00", "parameters": {"@schedule_id": "Schedule ID of the Agent-start schedule", "@safe_start_time_hhmmss": "Daily start time as HHMMSS that is after typical recovery completes"}, "description": "If the job uses freq_type=64 (run at Agent start), convert it to a fixed daily time that occurs after recovery reliably completes. This is a permanent solution compared to relying on retries."}	{"sql": "USE msdb;\\nEXEC dbo.sp_update_schedule\\n  @schedule_id  = @schedule_id,\\n  @freq_type    = 64;", "description": "Restore schedule to Agent-start trigger if the fixed time is not acceptable."}	low	t	t	00:02:00	2026-02-24 13:10:27.292439
1744	sqlserver	verify	Check whether a disabled schedule still exists or was fully deleted	{"sql": "-- Check for disabled but still attached schedules\\nSELECT j.name AS job_name, s.schedule_id, s.name AS schedule_name,\\n  s.enabled AS schedule_enabled,\\n  s.freq_type, s.active_start_date, s.active_start_time,\\n  s.active_end_date\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nWHERE j.name = @job_name;\\n\\n-- Also check if orphaned schedules exist with similar name\\nSELECT schedule_id, name, enabled, freq_type,\\n  active_start_date, active_start_time\\nFROM msdb.dbo.sysschedules\\nWHERE name LIKE @schedule_name_pattern\\n  AND schedule_id NOT IN (\\n    SELECT schedule_id FROM msdb.dbo.sysjobschedules);", "parameters": {"@job_name": "Affected job name", "@schedule_name_pattern": "Partial schedule name to search orphaned schedules, e.g. '%JobName%'"}, "description": "Determine whether a disabled schedule is still attached (just needs re-enabling) or whether the schedule was fully deleted (requires creating a new one)."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.292439
1745	sqlserver	execute	Re-enable existing schedule or create and attach new schedule	{"sql": "USE msdb;\\n-- Option A: Re-enable a disabled but still-attached schedule\\nEXEC dbo.sp_update_schedule\\n  @schedule_id = @existing_schedule_id,\\n  @enabled     = 1;\\n\\n-- Option B: Create a new schedule and attach to job\\n-- (use when schedule was fully deleted)\\nDECLARE @new_schedule_id INT;\\nEXEC dbo.sp_add_schedule\\n  @schedule_name          = @new_schedule_name,\\n  @enabled                = 1,\\n  @freq_type              = @freq_type,\\n  @freq_interval          = @freq_interval,\\n  @freq_subday_type       = @freq_subday_type,\\n  @freq_subday_interval   = @freq_subday_interval,\\n  @freq_recurrence_factor = @freq_recurrence_factor,\\n  @active_start_date      = @active_start_date,\\n  @active_end_date        = 99991231,\\n  @active_start_time      = @active_start_time,\\n  @schedule_id            = @new_schedule_id OUTPUT;\\n\\nEXEC dbo.sp_attach_schedule\\n  @job_name    = @job_name,\\n  @schedule_id = @new_schedule_id;", "parameters": {"@job_name": "Job to attach new schedule to", "@freq_type": "4=daily, 8=weekly, 16=monthly, etc.", "@freq_interval": "Day interval or bitmask", "@freq_subday_type": "1=once, 4=minutes, 8=hours", "@active_start_date": "Start date as YYYYMMDD integer", "@active_start_time": "Start time as HHMMSS integer", "@new_schedule_name": "Descriptive name for new schedule (Option B)", "@existing_schedule_id": "schedule_id from step 1 (Option A only)", "@freq_subday_interval": "Subday interval count", "@freq_recurrence_factor": "Recurrence factor (1 for weekly/monthly)"}, "description": "Execute Option A if the schedule still exists (just disabled). Execute Option B if the schedule was fully deleted — create a new schedule with the confirmed parameters and attach it to the job."}	{"sql": "USE msdb;\\n-- Rollback Option A: disable the re-enabled schedule\\nEXEC dbo.sp_update_schedule @schedule_id = @existing_schedule_id, @enabled = 0;\\n-- Rollback Option B: detach and delete the new schedule\\nEXEC dbo.sp_detach_schedule @job_name = @job_name, @schedule_id = @new_schedule_id;\\nEXEC dbo.sp_delete_schedule @schedule_id = @new_schedule_id;", "description": "Undo the schedule change by disabling or removing the schedule."}	low	t	t	00:03:00	2026-02-24 13:10:27.29244
1746	sqlserver	verify	Confirm job now shows a valid next_scheduled_run_date	{"sql": "SELECT j.name, j.enabled, s.enabled AS schedule_enabled,\\n  ja.next_scheduled_run_date,\\n  CASE WHEN ja.next_scheduled_run_date > GETDATE() THEN 'SCHEDULED OK'\\n       ELSE 'STILL UNSCHEDULED' END AS status\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nJOIN msdb.dbo.sysjobactivity ja ON j.job_id = ja.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.name = @job_name;", "parameters": {"@job_name": "Job name"}, "description": "Confirm the job is enabled, the schedule is enabled, and next_scheduled_run_date is a valid future datetime."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.29244
