1784	sqlserver	verify	Confirm I/O stall reduction and improved job completion time	{"sql": "-- Re-check stall after changes (reset counters by restarting SQL Server or note cumulative nature)\\nSELECT d.name, mf.type_desc,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nORDER BY (vfs.io_stall_read_ms + vfs.io_stall_write_ms) DESC;\\n\\n-- Check recent job durations\\nSELECT TOP 5 j.name,\\n  ((h.run_duration / 10000)*3600 + ((h.run_duration%10000)/100)*60 + h.run_duration%100) AS duration_sec\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;", "parameters": {}, "description": "Verify that I/O stall values have dropped below 20 ms thresholds and that job run durations have improved."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.298774
1785	sqlserver	execute	Identify exact query and scan-prone columns from cached plan	{"sql": "SELECT TOP 10\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text,\\n  CAST(qp.query_plan AS nvarchar(max)) AS plan_xml\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE CAST(qp.query_plan AS nvarchar(max)) LIKE '%Table Scan%'\\nORDER BY avg_logical_reads DESC;", "parameters": {}, "description": "Retrieve the top table-scanning queries with their execution plans to identify the specific table and WHERE/JOIN columns that need indexing."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.298775
1786	sqlserver	configure	Create targeted covering index on scan-prone table	{"sql": "-- Replace schema, table, and column names based on findings from step 1\\nCREATE INDEX [IX_<table>_<col1>_<col2>]\\n  ON [<schema>].[<table>] ([<filter_col1>] ASC, [<filter_col2>] ASC)\\n  INCLUDE ([<included_col1>], [<included_col2>])\\n  WITH (ONLINE = ON,        -- minimize blocking on 2014+\\n        SORT_IN_TEMPDB = ON,\\n        FILLFACTOR = 80);\\n\\n-- Immediately invalidate the stale cached plan for the affected query\\nDBCC FREEPROCCACHE (plan_handle);  -- supply specific plan_handle from step 1 to be surgical", "parameters": {"table": "Target table name identified from the scan plan", "filter_col1": "Leading column(s) from WHERE or JOIN predicates", "filter_col2": "Secondary filter column(s)", "included_col1": "Columns required in SELECT list (to avoid key lookup)"}, "description": "Create a non-clustered covering index on the filtered/joined columns with included columns for the SELECT list, then flush the old plan so the new index is considered on next execution."}	{"sql": "DROP INDEX [IX_<table>_<col1>_<col2>] ON [<schema>].[<table>];", "description": "Drop the newly created index if it causes unexpected contention or space issues."}	medium	t	t	00:30:00	2026-02-24 13:10:27.298775
1787	sqlserver	verify	Confirm scan is replaced by seek in subsequent query execution	{"sql": "-- Re-run the identified query with SHOWPLAN to confirm seek\\nSET STATISTICS IO ON;\\n-- <paste the target query here>\\nSET STATISTICS IO OFF;\\n\\n-- Confirm no remaining Table Scan in cached plan\\nSELECT TOP 5\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  LEFT(st.text, 200) AS query_snippet\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE CAST(qp.query_plan AS nvarchar(max)) LIKE '%Table Scan%'\\nORDER BY avg_logical_reads DESC;", "parameters": {}, "description": "Verify that logical reads dropped and that the query plan no longer shows a Table Scan operator for the affected query."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.298776
1819	sqlserver	verify	Confirm next scheduled run times reflect correct local time	{"sql": "SELECT j.name AS job_name,\\n  msdb.dbo.agent_datetime(js2.next_run_date, js2.next_run_time) AS next_run_local,\\n  s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000'+CAST(s.active_start_time AS varchar(6)),6),5,0,':'),3,0,':') AS scheduled_start_fmt,\\n  SYSDATETIMEOFFSET() AS server_now_with_offset\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nLEFT JOIN msdb.dbo.sysjobschedules js2 ON j.job_id = js2.job_id AND js2.schedule_id = s.schedule_id\\nWHERE j.enabled = 1 AND s.enabled = 1\\nORDER BY next_run_local;", "parameters": {}, "description": "Verify that next_run_local matches the intended maintenance window for each job."}	null	low	f	t	\N	2026-02-24 13:10:27.305109
1794	sqlserver	execute	Identify schedule overlap between maintenance and production jobs	{"sql": "-- List all scheduled jobs with their next run time to find conflicts\\nSELECT j.name AS job_name,\\n  js.next_run_date, js.next_run_time,\\n  sc.freq_type, sc.active_start_time, sc.active_end_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules js ON j.job_id = js.job_id\\nJOIN msdb.dbo.sysschedules sc ON js.schedule_id = sc.schedule_id\\nWHERE j.enabled = 1\\nORDER BY js.next_run_date, js.next_run_time;\\n\\n-- Check which jobs are currently running\\nSELECT j.name, ja.start_execution_date,\\n  DATEDIFF(minute, ja.start_execution_date, GETDATE()) AS running_minutes\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions);", "parameters": {}, "description": "Display all enabled job schedules and currently running jobs to identify which maintenance jobs overlap with production Agent workloads."}	null	low	f	t	00:03:00	2026-02-24 13:10:27.305914
2275	sqlserver	verify	Confirm all risky features are disabled and CLR strict security is active	{"sql": "SELECT name,\\n  CAST(value_in_use AS INT) AS is_enabled,\\n  description\\nFROM sys.configurations\\nWHERE name IN (\\n  'xp_cmdshell',\\n  'clr enabled',\\n  'clr strict security',\\n  'Ole Automation Procedures',\\n  'Ad Hoc Distributed Queries',\\n  'Database Mail XPs'\\n);\\n\\n-- Verify no remaining UNSAFE assemblies\\nSELECT a.name, a.permission_set_desc\\nFROM sys.assemblies a\\nWHERE a.permission_set_desc IN ('EXTERNAL_ACCESS', 'UNSAFE')\\n  AND a.is_user_defined = 1;", "parameters": {}, "description": "Validates that xp_cmdshell and OLE Automation are 0, CLR strict security is 1, and no unaddressed UNSAFE assemblies remain."}	null	low	f	t	\N	2026-02-24 13:10:27.381956
3728	sqlserver	instruct	Refactor queries to reduce the number of sort operations	{"sql": null, "parameters": [], "description": "For each query with multiple sorts: (1) Consolidate multiple ORDER BY clauses into a single sort where possible. (2) Replace DISTINCT + ORDER BY with GROUP BY + ORDER BY on the same columns. (3) For window functions with different PARTITION BY/ORDER BY, align them to use the same sort order where possible. (4) Use indexes that provide pre-sorted data to eliminate explicit sort operators. (5) Apply OPTION (MIN_GRANT_PERCENT = 5, MAX_GRANT_PERCENT = 30) to cap total grant while ensuring adequate minimum."}	null	low	f	t	3 days	2026-02-24 13:10:27.336764
1788	sqlserver	execute	Generate ranked CREATE INDEX statements from missing index DMVs	{"sql": "SELECT TOP 10\\n  ROUND(gs.avg_user_impact * (gs.user_seeks + gs.user_scans), 0) AS improvement_score,\\n  gs.avg_user_impact,\\n  gs.user_seeks + gs.user_scans AS total_accesses,\\n  DB_NAME(d.database_id) AS database_name,\\n  OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  d.equality_columns, d.inequality_columns, d.included_columns,\\n  'CREATE INDEX [IX_' + OBJECT_NAME(d.object_id, d.database_id)\\n    + '_missing_' + CAST(d.index_handle AS varchar) + '] ON '\\n    + QUOTENAME(DB_NAME(d.database_id)) + '.'\\n    + QUOTENAME(OBJECT_SCHEMA_NAME(d.object_id, d.database_id)) + '.'\\n    + QUOTENAME(OBJECT_NAME(d.object_id, d.database_id))\\n    + ' (' + ISNULL(d.equality_columns, '') \\n    + CASE WHEN d.equality_columns IS NOT NULL AND d.inequality_columns IS NOT NULL THEN ', ' ELSE '' END\\n    + ISNULL(d.inequality_columns, '') + ')'\\n    + ISNULL(' INCLUDE (' + d.included_columns + ')', '') AS suggested_create_index\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nWHERE gs.avg_user_impact > 70\\n  AND (gs.user_seeks + gs.user_scans) > 100\\nORDER BY improvement_score DESC;", "parameters": {}, "description": "Generate ready-to-run CREATE INDEX scripts ranked by estimated improvement for the DBA to review before executing."}	null	low	f	t	00:03:00	2026-02-24 13:10:27.305901
1789	sqlserver	configure	Create the highest-impact missing index with ONLINE option	{"sql": "-- Execute the top-ranked statement from step 1, adding ONLINE = ON and SORT_IN_TEMPDB\\n-- Example (replace with actual column names from DMV output):\\nCREATE NONCLUSTERED INDEX [IX_<table>_missing_<handle>]\\n  ON [<db>].[<schema>].[<table>] (<equality_cols>, <inequality_cols>)\\n  INCLUDE (<included_cols>)\\n  WITH (ONLINE = ON, SORT_IN_TEMPDB = ON, FILLFACTOR = 80, STATISTICS_NORECOMPUTE = OFF);", "parameters": {"table": "Target table from DMV output", "equality_cols": "Equality predicate columns from d.equality_columns", "included_cols": "Non-key columns from d.included_columns", "inequality_cols": "Range predicate columns from d.inequality_columns"}, "description": "Execute the generated CREATE INDEX statement for the highest-scoring missing index candidate."}	{"sql": "DROP INDEX [IX_<table>_missing_<handle>] ON [<db>].[<schema>].[<table>];", "description": "Drop the new index if it introduces unexpected write overhead or DML blocking."}	medium	t	t	00:30:00	2026-02-24 13:10:27.305906
1790	sqlserver	verify	Verify index usage and confirm job step duration improvement	{"sql": "-- Confirm the new index is being used\\nSELECT i.name AS index_name,\\n  ius.user_seeks, ius.user_scans, ius.user_lookups, ius.user_updates,\\n  ius.last_user_seek\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE i.name LIKE 'IX_%missing%'\\n  AND ius.database_id = DB_ID();\\n\\n-- Check recent job durations\\nSELECT TOP 5 j.name,\\n  ((h.run_duration/10000)*3600 + ((h.run_duration%10000)/100)*60 + h.run_duration%100) AS duration_sec\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;", "parameters": {}, "description": "Confirm the new index accumulates user_seeks (not just scans) and that job step duration has decreased compared to historical baselines."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.305908
1791	sqlserver	configure	Increase linked server query and connection timeouts to prevent spurious failures	{"sql": "-- Adjust query timeout (seconds) for the specific linked server (0 = no timeout)\\nEXEC sp_serveroption @server = N'<linked_server_name>',\\n  @optname = N'query timeout', @optvalue = N'300';\\n\\n-- Adjust connection timeout\\nEXEC sp_serveroption @server = N'<linked_server_name>',\\n  @optname = N'connect timeout', @optvalue = N'30';\\n\\n-- Verify\\nSELECT name, query_timeout, connect_timeout\\nFROM sys.servers\\nWHERE is_linked = 1 AND name = N'<linked_server_name>';", "parameters": {"query timeout": "Maximum seconds to wait for a remote query result; 300 = 5 minutes", "connect timeout": "Maximum seconds for initial connection; 30 is a reasonable default", "linked_server_name": "Name of the linked server from sys.servers"}, "description": "Set realistic query and connection timeouts on the linked server definition to prevent premature failure during high-latency periods."}	{"sql": "EXEC sp_serveroption @server = N'<linked_server_name>',\\n  @optname = N'query timeout', @optvalue = N'0';\\nEXEC sp_serveroption @server = N'<linked_server_name>',\\n  @optname = N'connect timeout', @optvalue = N'0';", "description": "Revert timeouts to unlimited (0) which was the prior configuration."}	low	f	t	00:05:00	2026-02-24 13:10:27.305909
1793	sqlserver	verify	Confirm job completes within expected window and network wait times are reduced	{"sql": "-- Check OLEDB / NETWORKIO wait reductions\\nSELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('OLEDB', 'NETWORKIO', 'ASYNC_NETWORK_IO', 'PREEMPTIVE_OLEDBOPS');\\n\\n-- Confirm recent job run duration improved\\nSELECT TOP 5 j.name, h.run_status,\\n  ((h.run_duration/10000)*3600 + ((h.run_duration%10000)/100)*60 + h.run_duration%100) AS duration_sec,\\n  h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;", "parameters": {}, "description": "Verify that network-related wait types have decreased and the job now completes within the expected time window."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.305913
1795	sqlserver	configure	Reschedule maintenance jobs outside production window and optionally disable auto-update statistics on hot tables	{"sql": "-- Reschedule maintenance job to a non-overlapping window (e.g., 01:00 AM)\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = <maintenance_schedule_id>,\\n  @active_start_time = 010000,  -- 01:00 AM\\n  @active_end_time   = 040000;  -- complete by 04:00 AM\\n\\n-- Optionally disable auto-update stats on a high-churn table\\n-- to prevent mid-job SCH-M locks from auto-update\\nALTER DATABASE [<affected_db>] SET AUTO_UPDATE_STATISTICS OFF;\\n-- Compensate by adding manual UPDATE STATISTICS to the maintenance job\\n\\n-- Or use per-table override (finer control)\\nEXEC sys.sp_autostats N'<schema>.<table>', N'OFF';", "parameters": {"affected_db": "Database where auto-update stats is causing contention", "schema.table": "Fully qualified table name with high modification_counter", "maintenance_schedule_id": "Schedule ID from msdb.dbo.sysschedules for the maintenance job"}, "description": "Move the maintenance job schedule so it runs in a dedicated window that does not overlap with production Agent jobs. Disable auto-update statistics on specific tables if mid-execution updates cause SCH-M contention."}	{"sql": "-- Restore auto-update statistics\\nALTER DATABASE [<affected_db>] SET AUTO_UPDATE_STATISTICS ON;\\n-- Or per-table:\\nEXEC sys.sp_autostats N'<schema>.<table>', N'ON';\\n-- Revert schedule if needed:\\nEXEC msdb.dbo.sp_update_schedule @schedule_id = <maintenance_schedule_id>,\\n  @active_start_time = <original_start>, @active_end_time = <original_end>;", "description": "Re-enable auto-update statistics and restore the original maintenance job schedule."}	medium	t	t	00:10:00	2026-02-24 13:10:27.305915
6486	postgresql	execute	Measure index fragmentation	{"sql": "CREATE EXTENSION IF NOT EXISTS pgstattuple; SELECT * FROM pgstatindex('schema.index_name');", "parameters": ["schema", "index_name"], "description": "Use pgstattuple extension to measure index leaf page density and fragmentation level."}	\N	low	f	t	1-5 minutes	2026-02-25 08:59:43.77256
1797	sqlserver	configure	Add equally-sized tempdb data files to relieve GAM/SGAM allocation contention	{"sql": "-- Number of files should match number of CPU cores (up to 8)\\n-- All files must be equal size; place on fast local SSD\\nALTER DATABASE tempdb\\n  ADD FILE (NAME = N'tempdev2',\\n            FILENAME = N'<fast_path>\\tempdev2.ndf',\\n            SIZE = <size_mb>MB, FILEGROWTH = 256MB);\\n-- Repeat for tempdev3..tempdevN as needed\\n\\n-- Confirm current file count and sizes\\nSELECT name, physical_name, size * 8 / 1024 AS size_mb\\nFROM tempdb.sys.database_files;", "parameters": {"size_mb": "Set equal to the size of tempdev (existing primary file)", "fast_path": "Path to a fast local SSD volume"}, "description": "Add tempdb data files equal in number to the CPU core count (capped at 8) to eliminate round-robin allocation waits under heavy concurrent temp table workloads."}	{"sql": "ALTER DATABASE tempdb REMOVE FILE [tempdev2];\\n-- Removal takes effect after SQL Server restart for tempdb files.", "description": "Remove added tempdb file; takes effect after restart."}	medium	t	t	00:05:00	2026-02-24 13:10:27.305917
1798	sqlserver	configure	Increase memory grant or rewrite query to reduce spill-inducing sort/hash operations	{"sql": "-- Option A: Add MIN_GRANT_PERCENT hint to the spilling query to pre-allocate more memory\\n-- Modify the Agent job step T-SQL to include query hint:\\n-- SELECT ... FROM ... ORDER BY ... OPTION (MIN_GRANT_PERCENT = 25);\\n\\n-- Option B: Set Resource Governor min memory grant for the Agent pool\\nALTER RESOURCE POOL [AgentPool]\\n  WITH (MIN_MEMORY_PERCENT = 10, MAX_MEMORY_PERCENT = 60);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\n\\n-- Option C: If using large #temp tables, replace with indexed temp tables\\n-- Replace: SELECT ... INTO #t FROM large_table\\n-- With:    SELECT ... INTO #t FROM large_table;\\n--          CREATE INDEX IX_t_col ON #t (filter_col);", "parameters": {"AgentPool": "Resource Governor pool name assigned to Agent jobs", "MIN_GRANT_PERCENT": "Percentage of total server memory to reserve for this query's grant; start at 10-25"}, "description": "Apply a MIN_GRANT_PERCENT query hint to pre-allocate sufficient memory for sort/hash operations, or create an index on the temporary table to avoid full scans."}	{"sql": "-- Remove query hint from job step command:\\nEXEC msdb.dbo.sp_update_jobstep @job_name = N'<job>', @step_id = <id>,\\n  @command = N'<original_sql_without_hint>';\\n-- Revert Resource Governor pool:\\nALTER RESOURCE POOL [AgentPool] WITH (MIN_MEMORY_PERCENT = 0, MAX_MEMORY_PERCENT = 100);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "description": "Remove the query hint from the job step and revert Resource Governor memory settings."}	medium	t	t	00:10:00	2026-02-24 13:10:27.305919
1799	sqlserver	verify	Confirm tempdb spill waits reduced and job completes without tempdb exhaustion	{"sql": "-- Check for remaining spill-related waits\\nSELECT wait_type, wait_time_ms, waiting_tasks_count\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGELATCH_UP')\\nORDER BY wait_time_ms DESC;\\n\\n-- Confirm tempdb has adequate free space after job run\\nSELECT\\n  SUM(user_object_reserved_page_count) * 8 / 1024 AS user_objects_mb,\\n  SUM(internal_object_reserved_page_count) * 8 / 1024 AS internal_objects_mb,\\n  SUM(unallocated_extent_page_count) * 8 / 1024 AS free_space_mb\\nFROM sys.dm_db_file_space_usage\\nWHERE database_id = 2;", "parameters": {}, "description": "Verify that tempdb-related I/O latch waits have decreased and that free space in tempdb remains healthy after the job runs."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.30592
1800	sqlserver	execute	Identify idle or sleeping sessions consuming worker threads	{"sql": "-- Sessions sleeping > 30 minutes are candidates for termination\\nSELECT s.session_id, s.status, s.login_name, s.host_name,\\n  s.program_name, s.last_request_end_time,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  c.num_reads, c.num_writes\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 30\\n  AND s.session_id > 50  -- exclude system sessions\\nORDER BY idle_minutes DESC;\\n\\n-- Verify current worker saturation\\nSELECT max_workers_count,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers\\nFROM sys.dm_os_sys_info;", "parameters": {}, "description": "List long-idle sessions (> 30 minutes) that are holding worker threads without doing work, and confirm worker thread utilization."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.305922
3979	sqlserver	instruct	Rewrite non-SARGable predicates to enable index seeks	{"sql": null, "parameters": [], "description": "For each query with functions on indexed columns: (1) Replace WHERE YEAR(date_col) = 2024 with WHERE date_col >= '2024-01-01' AND date_col < '2025-01-01'. (2) Replace WHERE CONVERT(DATE, datetime_col) = '2024-01-15' with WHERE datetime_col >= '2024-01-15' AND datetime_col < '2024-01-16'. (3) Replace WHERE ISNULL(col, 'default') = 'value' with WHERE col = 'value'. (4) Replace WHERE UPPER(col) = 'VALUE' with case-insensitive collation or a persisted computed column. (5) Replace WHERE SUBSTRING(col, 1, 3) = 'ABC' with WHERE col LIKE 'ABC%'."}	null	low	f	t	\N	2026-02-24 13:10:27.603969
5712	postgresql	execute	Check autovacuum and autoanalyze status globally and per-table	{"sql": "SHOW autovacuum;\\nSHOW track_counts;\\n\\n-- Check per-table autovacuum overrides\\nSELECT c.relname, c.reloptions\\nFROM pg_class c\\nWHERE c.reloptions::text LIKE '%autovacuum_enabled=false%'\\n   OR c.reloptions::text LIKE '%autovacuum_enabled=off%';", "parameters": [], "description": "Checks whether autovacuum is enabled globally and identifies any tables with autovacuum explicitly disabled."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
1802	sqlserver	verify	Confirm THREADPOOL waits are eliminated and Agent jobs resume normal execution	{"sql": "-- THREADPOOL waits should be near zero\\nSELECT wait_type, wait_time_ms, waiting_tasks_count\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'THREADPOOL';\\n\\n-- Confirm worker headroom exists\\nSELECT max_workers_count,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  max_workers_count - (SELECT COUNT(*) FROM sys.dm_os_workers) AS available_workers\\nFROM sys.dm_os_sys_info;\\n\\n-- Confirm Agent sessions established\\nSELECT COUNT(*) AS agent_sessions\\nFROM sys.dm_exec_sessions\\nWHERE program_name LIKE 'SQLAgent%';", "parameters": {}, "description": "Verify THREADPOOL wait count has dropped, available workers exceed demand, and Agent sessions have successfully connected."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.305925
1803	sqlserver	execute	Update statistics on tables with high modification counts	{"sql": "-- Update statistics with fullscan on high-churn tables identified in detection\\nUPDATE STATISTICS [<schema>].[<table1>] WITH FULLSCAN;\\nUPDATE STATISTICS [<schema>].[<table2>] WITH FULLSCAN;\\n\\n-- Or update all statistics in the affected database (more thorough but slower)\\nEXEC sp_updatestats;\\n\\n-- Verify statistics are now fresh\\nSELECT o.name AS table_name, st.name AS stats_name,\\n  sp.last_updated, sp.rows, sp.modification_counter\\nFROM sys.stats st\\nJOIN sys.objects o ON st.object_id = o.object_id\\nCROSS APPLY sys.dm_db_stats_properties(st.object_id, st.stats_id) sp\\nWHERE o.name IN ('<table1>', '<table2>')\\nORDER BY sp.last_updated DESC;", "parameters": {"schema": "Schema of the high-churn tables", "table1": "First table with stale statistics from detection query", "table2": "Second table with stale statistics"}, "description": "Update statistics with FULLSCAN on all tables that have high modification_counter values relative to total rows, giving the optimizer accurate row count estimates."}	null	low	f	t	00:20:00	2026-02-24 13:10:27.305926
1804	sqlserver	configure	Flush the bad cached plan and optionally add OPTION(RECOMPILE) or join hint	{"sql": "-- Flush the specific bad plan from cache (surgical; get plan_handle from detection step 1)\\nDBCC FREEPROCCACHE (<plan_handle>);\\n\\n-- If plan remains bad after statistics update, add OPTION(RECOMPILE) to the query\\n-- in the Agent job step to force fresh plan on every execution:\\n-- SELECT ... FROM a JOIN b ON ... WHERE ... OPTION (RECOMPILE);\\n\\n-- For persistent join order problems, add explicit join hints (use with caution):\\n-- SELECT ... FROM a INNER HASH JOIN b ON ...  -- forces hash join\\n-- SELECT ... FROM a INNER LOOP JOIN b ON ...  -- forces nested loops\\n\\n-- Alternatively, enable the newer Cardinality Estimator if on legacy CE70:\\nALTER DATABASE [<affected_db>] SET COMPATIBILITY_LEVEL = 150;  -- SQL 2019 CE", "parameters": {"affected_db": "Database to upgrade compatibility level if using legacy CE", "plan_handle": "Specific plan handle from sys.dm_exec_query_stats for the bad plan"}, "description": "Remove the stale plan from cache so the optimizer recompiles using fresh statistics. Apply OPTION(RECOMPILE) to the job step query if plan sniffing is suspected, or add explicit join hints for persistent join order failures."}	{"sql": "-- Revert compatibility level if CE change caused regressions\\nALTER DATABASE [<affected_db>] SET COMPATIBILITY_LEVEL = <prior_level>;\\n-- Remove OPTION(RECOMPILE) from job step if overhead is unacceptable:\\nEXEC msdb.dbo.sp_update_jobstep @job_name = N'<job>', @step_id = <id>,\\n  @command = N'<original_sql_without_hint>';", "description": "Revert compatibility level and remove query hints if they caused unexpected regressions."}	medium	t	t	00:10:00	2026-02-24 13:10:27.305928
1805	sqlserver	verify	Confirm improved query plan and reduced job step elapsed time	{"sql": "-- Verify statistics are current\\nSELECT o.name, st.name, sp.last_updated, sp.modification_counter\\nFROM sys.stats st\\nJOIN sys.objects o ON st.object_id = o.object_id\\nCROSS APPLY sys.dm_db_stats_properties(st.object_id, st.stats_id) sp\\nWHERE sp.modification_counter > 0\\nORDER BY sp.last_updated DESC;\\n\\n-- Confirm elapsed time improvement in new plan\\nSELECT TOP 5\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  LEFT(st.text, 200) AS query_snippet\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nORDER BY avg_elapsed_ms DESC;", "parameters": {}, "description": "Verify that statistics have been updated recently and that the affected queries now show lower elapsed time and logical reads in the plan cache."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.30593
2070	sqlserver	execute	Disable auto-shrink on tempdb	{"sql": "ALTER DATABASE tempdb SET AUTO_SHRINK OFF;", "parameters": {}, "description": "Immediately disables the auto-shrink behaviour. This is a dynamic change that takes effect without restarting SQL Server. Tempdb will no longer shrink during operation, eliminating the fragmentation cycle."}	{"sql": "ALTER DATABASE tempdb SET AUTO_SHRINK ON;", "description": "Re-enable auto-shrink (not recommended — only if explicitly required by storage policy)."}	low	f	t	00:01:00	2026-02-24 13:10:27.305931
1806	sqlserver	configure	Increase retry limit and set timeout parameters on the affected job step	{"sql": "-- Increase retry attempts and delay on the failing step\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name   = N'<job_name>',\\n  @step_id    = <step_id>,\\n  @retry_attempts = 3,\\n  @retry_interval = 2;   -- minutes between retries\\n\\n-- For linked server steps: increase query timeout\\nEXEC sp_serveroption @server = N'<linked_server_name>',\\n  @optname = N'query timeout', @optvalue = N'600';  -- 10 minutes\\n\\n-- Verify step configuration\\nSELECT step_name, retry_attempts, retry_interval, subsystem\\nFROM msdb.dbo.sysjobsteps\\nWHERE job_id = (SELECT job_id FROM msdb.dbo.sysjobs WHERE name = N'<job_name>');", "parameters": {"step_id": "Step number of the external call step", "job_name": "Name of the Agent job with the slow external call step", "retry_attempts": "Number of retries; 3 is a reasonable default for transient failures", "retry_interval": "Minutes to wait between retries; use exponential backoff if needed"}, "description": "Configure retry attempts and interval on the job step so transient external failures recover automatically. Increase linked server query timeout to accommodate slow remote responses."}	{"sql": "EXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<job_name>',\\n  @step_id = <step_id>,\\n  @retry_attempts = 0,\\n  @retry_interval = 0;", "description": "Reset retry configuration to zero attempts."}	low	f	t	00:05:00	2026-02-24 13:10:27.305933
1814	sqlserver	verify	Confirm job completes before business hours after tuning	{"sql": "SELECT j.name AS job_name, h.run_date, h.run_time,\\n  STUFF(STUFF(RIGHT('000000'+CAST(h.run_time AS varchar(6)),6),5,0,':'),3,0,':') AS start_fmt,\\n  ((h.run_duration/10000)*3600 + ((h.run_duration%10000)/100)*60 + (h.run_duration%100)) AS duration_sec,\\n  DATEADD(second,\\n    ((h.run_duration/10000)*3600 + ((h.run_duration%10000)/100)*60 + (h.run_duration%100)),\\n    CAST(STUFF(STUFF(RIGHT('000000'+CAST(h.run_time AS varchar(6)),6),5,0,':'),3,0,':') AS time)\\n  ) AS approx_end_time\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0 AND h.run_status = 1\\n  AND h.run_date >= CONVERT(int,CONVERT(varchar(8),DATEADD(day,-3,GETDATE()),112))\\nORDER BY h.run_date DESC, duration_sec DESC;", "parameters": {}, "description": "After applying tuning changes, verify that recent runs finish before 07:00."}	null	low	f	t	\N	2026-02-24 13:10:27.309825
1870	sqlserver	verify	Run ETL job and review conversion error log	{"sql": "-- Execute updated ETL job\\nEXEC msdb.dbo.sp_start_job @job_name = N'YourETLJobName';\\nWAITFOR DELAY '00:00:30';\\n\\n-- Check job result\\nSELECT TOP 1 j.name, h.run_date, h.run_time,\\n  CASE h.run_status WHEN 1 THEN 'SUCCEEDED' ELSE 'FAILED' END AS status,\\n  LEFT(h.message, 500) AS message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = N'YourETLJobName' AND h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;\\n\\n-- Review any conversion errors logged\\nSELECT * FROM dbo.etl_conversion_errors\\nWHERE logged_at > DATEADD(HOUR, -1, GETDATE())\\nORDER BY logged_at DESC;\\n", "parameters": null, "description": "Executes the updated ETL job and checks both the job completion status and the conversion error log to verify the pipeline succeeds and the volume of skipped rows is within acceptable bounds."}	null	medium	t	f	\N	2026-02-24 13:10:27.31398
