1831	sqlserver	execute	Restart SQL Server Agent to reset internal job scheduler	{"sql": "-- Via SQL Server Configuration Manager (preferred) or:\\nEXEC xp_cmdshell 'net stop SQLSERVERAGENT';\\nWAITFOR DELAY '00:00:05';\\nEXEC xp_cmdshell 'net start SQLSERVERAGENT';", "parameters": {}, "description": "Restart Agent so its internal timer resets to the now-synchronized OS clock, correcting accumulated drift."}	null	medium	t	t	\N	2026-02-24 13:10:27.311182
1832	sqlserver	verify	Monitor job start times across next 3 scheduled runs for drift recurrence	{"sql": "SELECT j.name AS job_name, s.active_start_time AS scheduled_time,\\n  h.run_time AS actual_time,\\n  ABS(h.run_time - s.active_start_time) AS drift_hhmmss,\\n  h.run_date\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE h.step_id = 0 AND h.run_status = 1\\n  AND h.run_date >= CONVERT(int,CONVERT(varchar(8),DATEADD(day,-3,GETDATE()),112))\\nORDER BY h.run_date DESC, drift_hhmmss DESC;", "parameters": {}, "description": "After NTP sync and Agent restart, confirm actual run times match scheduled times within 1–2 minutes."}	null	low	f	t	\N	2026-02-24 13:10:27.311183
1833	sqlserver	verify	Identify all jobs sharing the same schedule start time	{"sql": "SELECT s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000'+CAST(s.active_start_time AS varchar(6)),6),5,0,':'),3,0,':') AS start_fmt,\\n  COUNT(*) AS job_count,\\n  STRING_AGG(j.name + ' (id:' + CAST(j.job_id AS varchar(36)) + ')', ' | ') AS jobs,\\n  STRING_AGG(CAST(s.schedule_id AS varchar(10)), ',') AS schedule_ids\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND s.freq_type IN (4, 8, 16, 32)\\nGROUP BY s.active_start_time\\nHAVING COUNT(*) >= 2\\nORDER BY job_count DESC, s.active_start_time;", "parameters": {}, "description": "List all concurrent schedule groups. Prioritize groups with 3+ jobs or groups containing resource-intensive jobs."}	null	low	f	t	\N	2026-02-24 13:10:27.311184
1834	sqlserver	execute	Assign independent schedules and offset start times	{"sql": "-- For jobs sharing a schedule_id, first detach and create individual schedules,\\n-- then stagger each by 10-minute increments.\\n-- Example: 3 jobs all starting at 22:00:00 → stagger to 22:00, 22:10, 22:20.\\n\\nDECLARE @job_name SYSNAME = N'<job_name_2nd>';\\nDECLARE @new_schedule_name NVARCHAR(128) = N'<job_name_2nd>_Staggered';\\nDECLARE @offset_start_time INT = 221000;  -- 22:10 (original + 10 min)\\n\\n-- Remove from shared schedule\\nEXEC msdb.dbo.sp_detach_schedule\\n  @job_name = @job_name,\\n  @schedule_name = N'<shared_schedule_name>',\\n  @delete_unused_schedule = 0;\\n\\n-- Add a new individual schedule with offset start time\\nEXEC msdb.dbo.sp_add_jobschedule\\n  @job_name         = @job_name,\\n  @name             = @new_schedule_name,\\n  @enabled          = 1,\\n  @freq_type        = 4,       -- Daily\\n  @freq_interval    = 1,\\n  @active_start_time = @offset_start_time,\\n  @active_end_time  = 235959;\\n\\n-- Repeat for each job that needs staggering (3rd job: 221500, etc.)", "parameters": {"job_name": "SYSNAME — job to stagger", "offset_start_time": "INT — new staggered start time in HHMMSS format", "shared_schedule_name": "SYSNAME — name of the original shared schedule"}, "description": "Detach jobs from the shared schedule and assign individual schedules with staggered start times (10-minute increments)."}	{"sql": "-- Re-attach the job to the original shared schedule and remove the staggered schedule.\\nEXEC msdb.dbo.sp_attach_schedule\\n  @job_name = N'<job_name>',\\n  @schedule_name = N'<shared_schedule_name>';\\n\\nEXEC msdb.dbo.sp_detach_schedule\\n  @job_name = N'<job_name>',\\n  @schedule_name = N'<job_name_2nd>_Staggered',\\n  @delete_unused_schedule = 1;", "description": "Re-attach to original schedule and delete the staggered schedule."}	low	t	t	\N	2026-02-24 13:10:27.311184
1835	sqlserver	verify	Confirm no schedule conflicts remain and run times are within window	{"sql": "-- Verify no two jobs share the exact same start time anymore\\nSELECT s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000'+CAST(s.active_start_time AS varchar(6)),6),5,0,':'),3,0,':') AS start_fmt,\\n  COUNT(*) AS job_count,\\n  STRING_AGG(j.name, ', ') AS jobs\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND s.freq_type IN (4, 8, 16, 32)\\nGROUP BY s.active_start_time\\nHAVING COUNT(*) > 1\\nORDER BY s.active_start_time;", "parameters": {}, "description": "Confirm that the result set is empty (no start times with multiple concurrent jobs) or reduced to an acceptable level."}	null	low	f	t	\N	2026-02-24 13:10:27.311185
1836	sqlserver	verify	Map full job dependency chain and measure parent job runtimes	{"sql": "-- Identify all parent-child relationships via sp_start_job\\nSELECT j.name AS parent_job,\\n  js.step_id, js.step_name,\\n  SUBSTRING(js.command,\\n    CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) + 1,\\n    CHARINDEX('''', js.command, CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) + 1)\\n    - CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) - 1\\n  ) AS child_job_name\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.enabled = 1 AND js.command LIKE '%sp_start_job%';\\n\\n-- Measure parent job P95 runtime\\nSELECT j.name AS job_name,\\n  MAX(((h.run_duration/10000)*3600 + ((h.run_duration%10000)/100)*60 + (h.run_duration%100))) AS max_duration_sec,\\n  AVG(((h.run_duration/10000)*3600 + ((h.run_duration%10000)/100)*60 + (h.run_duration%100))) AS avg_duration_sec\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0 AND h.run_status = 1\\n  AND h.run_date >= CONVERT(int,CONVERT(varchar(8),DATEADD(day,-30,GETDATE()),112))\\nGROUP BY j.name\\nORDER BY max_duration_sec DESC;", "parameters": {}, "description": "Build the full dependency map and quantify parent job worst-case runtimes to calculate safe buffer times for downstream schedules."}	null	low	f	t	\N	2026-02-24 13:10:27.311186
6487	postgresql	execute	Rebuild index concurrently	{"sql": "REINDEX INDEX CONCURRENTLY schema.index_name;", "parameters": ["schema", "index_name"], "description": "Rebuild the B-tree index to restore balanced structure and optimal page density."}	\N	low	t	t	5-60 minutes	2026-02-25 08:59:43.77256
1837	sqlserver	configure	Replace sp_start_job chain with independent schedule plus completion guard	{"sql": "-- Option A: Give downstream job an independent schedule with buffer start time.\\n-- Example: parent starts at 21:00, P95 = 90 min → child schedule = 23:00 (buffer: 30 min)\\nDECLARE @child_job SYSNAME = N'<child_job_name>';\\nDECLARE @buffered_start_time INT = 230000;  -- calculated buffer time\\n\\n-- Add independent schedule to the child job\\nEXEC msdb.dbo.sp_add_jobschedule\\n  @job_name         = @child_job,\\n  @name             = N'<child_job_name>_Independent',\\n  @enabled          = 1,\\n  @freq_type        = 4,\\n  @freq_interval    = 1,\\n  @active_start_time = @buffered_start_time,\\n  @active_end_time  = 235959;\\n\\n-- Option B (if strict ordering is required): Replace sp_start_job in parent's last step\\n-- with a WAITFOR + polling loop to confirm parent completion before proceeding.\\n-- Implement using a dedicated 'chain controller' job that polls sysjobhistory.", "parameters": {"child_job_name": "SYSNAME — dependent job to reschedule independently", "buffered_start_time": "INT — calculated safe start time in HHMMSS (parent_start + P95_runtime + buffer)"}, "description": "Assign the downstream job its own schedule at a time that safely follows the parent's worst-case completion, removing the direct sp_start_job dependency."}	{"sql": "-- Remove the independent schedule from the child job\\nEXEC msdb.dbo.sp_detach_schedule\\n  @job_name = N'<child_job_name>',\\n  @schedule_name = N'<child_job_name>_Independent',\\n  @delete_unused_schedule = 1;", "description": "Remove the independent schedule; the child job will revert to being triggered only via sp_start_job from the parent."}	medium	t	t	\N	2026-02-24 13:10:27.311186
1838	sqlserver	verify	Confirm child job execution times fall within maintenance window	{"sql": "SELECT j.name AS job_name,\\n  msdb.dbo.agent_datetime(jss.next_run_date, jss.next_run_time) AS next_run,\\n  s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000'+CAST(s.active_start_time AS varchar(6)),6),5,0,':'),3,0,':') AS start_fmt,\\n  CASE WHEN s.active_start_time BETWEEN 70000 AND 190000 THEN 'BUSINESS_HOURS - ALERT' ELSE 'OK' END AS window_check\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.name IN (\\n  SELECT SUBSTRING(js.command,\\n    CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) + 1,\\n    CHARINDEX('''', js.command, CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) + 1)\\n    - CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) - 1\\n  ) FROM msdb.dbo.sysjobsteps js WHERE js.command LIKE '%sp_start_job%'\\n)\\nORDER BY next_run;", "parameters": {}, "description": "Verify that all formerly-dependent jobs now show a next_run time in the maintenance window, not business hours."}	null	low	f	t	\N	2026-02-24 13:10:27.311187
