1839	sqlserver	verify	Audit jobs with no active window restriction	{"sql": "SELECT j.name AS job_name, s.schedule_id, s.name AS schedule_name,\\n  s.active_start_time, s.active_end_time,\\n  STUFF(STUFF(RIGHT('000000'+CAST(s.active_start_time AS varchar(6)),6),5,0,':'),3,0,':') AS start_fmt,\\n  STUFF(STUFF(RIGHT('000000'+CAST(s.active_end_time AS varchar(6)),6),5,0,':'),3,0,':') AS end_fmt,\\n  CASE WHEN s.active_start_time = 0 AND s.active_end_time = 235959\\n    THEN 'NO_WINDOW - NEEDS_FIX'\\n    ELSE 'HAS_WINDOW' END AS window_status\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id AND js.step_id = 1\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND (s.active_start_time = 0 AND s.active_end_time = 235959)\\n  AND (js.command LIKE '%REBUILD%' OR js.command LIKE '%BACKUP%'\\n    OR js.command LIKE '%DBCC%' OR js.command LIKE '%UPDATE STATISTICS%'\\n    OR js.command LIKE '%SHRINK%' OR js.command LIKE '%REORGANIZE%')\\nORDER BY j.name;", "parameters": {}, "description": "Identify all resource-intensive jobs running with no active_end_time restriction (24/7 window)."}	null	low	f	t	\N	2026-02-24 13:10:27.313959
1840	sqlserver	configure	Set active_start_time and active_end_time to enforce maintenance window	{"sql": "-- Set maintenance window boundaries on each affected schedule.\\n-- active_end_time restricts the LAST time the job can START (not finish).\\n-- Maintenance window: 22:00 to 05:00 → set active_start_time=220000, active_end_time=50000\\nDECLARE @schedule_id INT = <schedule_id>;\\n\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id       = @schedule_id,\\n  @active_start_time = 220000,  -- 22:00 - maintenance window opens\\n  @active_end_time   = 50000;   -- 05:00 - maintenance window closes (last start time)", "parameters": {"schedule_id": "INT — schedule to update", "active_end_time": "INT — maintenance window close time in HHMMSS (jobs will not start after this)", "active_start_time": "INT — maintenance window open time in HHMMSS"}, "description": "Apply maintenance window boundaries to all resource-intensive job schedules. The active_end_time prevents the schedule from triggering new starts after the window closes."}	{"sql": "EXEC msdb.dbo.sp_update_schedule\\n  @schedule_id       = <schedule_id>,\\n  @active_start_time = 0,\\n  @active_end_time   = 235959;", "description": "Remove window restriction by restoring full-day active times."}	low	t	t	\N	2026-02-24 13:10:27.313964
1842	sqlserver	execute	Create notification operator	{"sql": "USE msdb;\\nIF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysoperators WHERE name = 'DBA_Alerts')\\nBEGIN\\n  EXEC msdb.dbo.sp_add_operator\\n    @name = N'DBA_Alerts',\\n    @enabled = 1,\\n    @email_address = N'dba-team@example.com',  -- Replace with real address\\n    @weekday_pager_start_time = 80000,\\n    @weekday_pager_end_time = 180000,\\n    @saturday_pager_start_time = 80000,\\n    @saturday_pager_end_time = 120000,\\n    @sunday_pager_start_time = 0,\\n    @sunday_pager_end_time = 0;\\n  PRINT 'Operator DBA_Alerts created.';\\nEND\\nELSE\\n  PRINT 'Operator DBA_Alerts already exists.';\\n", "parameters": {"email_address": "dba-team@example.com", "operator_name": "DBA_Alerts"}, "description": "Creates a SQL Agent operator named DBA_Alerts with an email address for notifications. Replace the email address with the actual DBA distribution list before executing."}	{"sql": "EXEC msdb.dbo.sp_delete_operator @name = N'DBA_Alerts';", "description": "Removes the operator if it was created in error or if an incorrect email was used."}	low	f	t	\N	2026-02-24 13:10:27.313967
3744	sqlserver	verify	Verify page density and PLE improvement after index maintenance	{"sql": "SELECT\\n  (SELECT AVG(ips.avg_page_space_used_in_percent)\\n   FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') ips\\n   WHERE ips.page_count > 1000) AS avg_page_density_pct,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page Life Expectancy'\\n   AND object_name LIKE '%Buffer Manager%'\\n   AND instance_name = '') AS ple;", "parameters": [], "description": "Confirms average page density has improved and PLE has increased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.572398
1843	sqlserver	execute	Enable email notifications on existing critical jobs	{"sql": "USE msdb;\\n-- Enable email-on-failure for all currently enabled jobs that have no notification\\nDECLARE @op_id INT = (SELECT id FROM msdb.dbo.sysoperators WHERE name = 'DBA_Alerts');\\nIF @op_id IS NULL\\n  RAISERROR('Operator DBA_Alerts not found. Run step 1 first.', 16, 1);\\n\\nDECLARE @job_name NVARCHAR(128);\\nDECLARE job_cur CURSOR FOR\\n  SELECT name FROM msdb.dbo.sysjobs\\n  WHERE enabled = 1\\n    AND notify_level_email = 0\\n    AND (notify_email_operator_id = 0 OR notify_email_operator_id IS NULL);\\n\\nOPEN job_cur;\\nFETCH NEXT FROM job_cur INTO @job_name;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  EXEC msdb.dbo.sp_update_job\\n    @job_name = @job_name,\\n    @notify_level_email = 2,            -- 2 = On failure\\n    @notify_email_operator_name = N'DBA_Alerts';\\n  FETCH NEXT FROM job_cur INTO @job_name;\\nEND\\nCLOSE job_cur;\\nDEALLOCATE job_cur;\\nPRINT 'Email notifications applied to all enabled jobs lacking notification.';\\n", "parameters": {"notify_level": "2 (on failure)"}, "description": "Iterates all enabled Agent jobs with no email notification and enables failure alerting to the DBA_Alerts operator."}	{"sql": "-- Disable notifications on all jobs that were just updated (if needed)\\nDECLARE @job_name NVARCHAR(128);\\nDECLARE job_cur CURSOR FOR\\n  SELECT name FROM msdb.dbo.sysjobs WHERE enabled = 1;\\nOPEN job_cur;\\nFETCH NEXT FROM job_cur INTO @job_name;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  EXEC msdb.dbo.sp_update_job\\n    @job_name = @job_name,\\n    @notify_level_email = 0,\\n    @notify_email_operator_name = N'';\\n  FETCH NEXT FROM job_cur INTO @job_name;\\nEND\\nCLOSE job_cur;\\nDEALLOCATE job_cur;", "description": "Reverses email notification assignment across all enabled jobs."}	low	f	t	\N	2026-02-24 13:10:27.313968
1844	sqlserver	execute	Create peak-hour monitoring job	{"sql": "USE msdb;\\nIF EXISTS (SELECT 1 FROM msdb.dbo.sysjobs WHERE name = 'Monitor - Peak Hour Job Execution')\\n  EXEC msdb.dbo.sp_delete_job @job_name = N'Monitor - Peak Hour Job Execution', @delete_unused_schedule = 1;\\n\\nEXEC msdb.dbo.sp_add_job\\n  @job_name = N'Monitor - Peak Hour Job Execution',\\n  @enabled = 1,\\n  @description = N'Alerts DBA when any Agent job is executing during business hours (08:00-18:00 M-F)',\\n  @notify_level_email = 2,\\n  @notify_email_operator_name = N'DBA_Alerts';\\n\\nEXEC msdb.dbo.sp_add_jobstep\\n  @job_name = N'Monitor - Peak Hour Job Execution',\\n  @step_name = N'Check and alert on peak-hour jobs',\\n  @subsystem = N'TSQL',\\n  @command = N'\\nDECLARE @hour INT = DATEPART(HOUR, GETDATE());\\nDECLARE @dow  INT = DATEPART(WEEKDAY, GETDATE()); -- 1=Sun..7=Sat\\nDECLARE @peak_hour BIT = CASE WHEN @hour BETWEEN 8 AND 17 AND @dow BETWEEN 2 AND 6 THEN 1 ELSE 0 END;\\n\\nIF @peak_hour = 1\\nBEGIN\\n  DECLARE @running_jobs NVARCHAR(MAX) = N'''';\\n  SELECT @running_jobs = @running_jobs + j.name + CHAR(13) + CHAR(10)\\n  FROM msdb.dbo.sysjobactivity ja\\n  JOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\n  WHERE ja.start_execution_date IS NOT NULL\\n    AND ja.stop_execution_date IS NULL\\n    AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions);\\n\\n  IF LEN(@running_jobs) > 0\\n  BEGIN\\n    DECLARE @msg NVARCHAR(MAX) = N''Peak-hour job execution detected on '' + @@SERVERNAME +\\n      N'' at '' + CONVERT(NVARCHAR(20), GETDATE(), 120) + CHAR(13) + CHAR(10) +\\n      N''Running jobs:'' + CHAR(13) + CHAR(10) + @running_jobs;\\n    EXEC msdb.dbo.sp_send_dbmail\\n      @profile_name = N''Default'',         -- Replace with actual mail profile name\\n      @recipients   = N''dba-team@example.com'',\\n      @subject      = N''[ALERT] SQL Agent jobs running during peak hours on '' + @@SERVERNAME,\\n      @body         = @msg;\\n  END\\nEND',\\n  @on_success_action = 1,\\n  @on_fail_action = 2;\\n\\n-- Schedule: every 30 minutes\\nEXEC msdb.dbo.sp_add_schedule\\n  @schedule_name = N'Every30Min_Weekdays',\\n  @freq_type = 4,\\n  @freq_interval = 1,\\n  @freq_subday_type = 4,\\n  @freq_subday_interval = 30,\\n  @active_start_time = 80000,\\n  @active_end_time   = 180000;\\n\\nEXEC msdb.dbo.sp_attach_schedule\\n  @job_name = N'Monitor - Peak Hour Job Execution',\\n  @schedule_name = N'Every30Min_Weekdays';\\n\\nEXEC msdb.dbo.sp_add_jobserver\\n  @job_name = N'Monitor - Peak Hour Job Execution',\\n  @server_name = N'(LOCAL)';\\n\\nPRINT 'Peak-hour monitoring job created and scheduled.';\\n", "parameters": {"peak_hours": "08:00–18:00 Monday–Friday", "mail_profile": "Default", "schedule_interval_minutes": 30}, "description": "Creates an Agent job that runs every 30 minutes during business hours and sends an email alert when other Agent jobs are actively executing."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = N'Monitor - Peak Hour Job Execution', @delete_unused_schedule = 1;", "description": "Removes the monitoring job and its schedule."}	low	f	t	\N	2026-02-24 13:10:27.313969
1845	sqlserver	verify	Confirm operator, notifications, and monitoring job are active	{"sql": "-- Verify operator exists and is enabled\\nSELECT name, enabled, email_address\\nFROM msdb.dbo.sysoperators\\nWHERE name = 'DBA_Alerts';\\n\\n-- Verify jobs have notification configured\\nSELECT j.name AS job_name, j.enabled,\\n  j.notify_level_email,\\n  op.name AS notify_operator,\\n  op.email_address\\nFROM msdb.dbo.sysjobs j\\nLEFT JOIN msdb.dbo.sysoperators op ON j.notify_email_operator_id = op.id\\nWHERE j.enabled = 1\\nORDER BY j.notify_level_email DESC;\\n\\n-- Verify monitoring job is scheduled and enabled\\nSELECT j.name, j.enabled,\\n  s.name AS schedule_name, s.enabled AS schedule_enabled,\\n  s.freq_subday_interval, s.active_start_time, s.active_end_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.name = 'Monitor - Peak Hour Job Execution';\\n", "parameters": null, "description": "Confirms the operator is active, all enabled jobs have email notifications, and the peak-hour monitoring job is scheduled correctly."}	null	low	f	f	\N	2026-02-24 13:10:27.31397
1846	sqlserver	execute	Calculate safe scheduling intervals from duration history	{"sql": "-- Review before modifying schedules: identify jobs needing buffer adjustment\\nSELECT j.name AS job_name,\\n  j.job_id,\\n  COUNT(*) AS run_count,\\n  MIN(dur_sec) AS min_sec,\\n  MAX(dur_sec) AS max_sec,\\n  AVG(dur_sec) AS avg_sec,\\n  MAX(dur_sec) - MIN(dur_sec) AS range_sec,\\n  -- Recommended interval = max_duration * 1.25 (25% safety buffer)\\n  CAST(MAX(dur_sec) * 1.25 / 60 AS INT) AS recommended_interval_min,\\n  s.freq_subday_interval AS current_interval_min,\\n  s.freq_subday_type,\\n  s.active_start_time\\nFROM (\\n  SELECT h.job_id,\\n    ((h.run_duration / 10000) * 3600\\n     + ((h.run_duration % 10000) / 100) * 60\\n     + (h.run_duration % 100)) AS dur_sec\\n  FROM msdb.dbo.sysjobhistory h\\n  WHERE h.step_id = 0 AND h.run_status = 1\\n    AND h.run_date >= CONVERT(INT, CONVERT(VARCHAR(8), DATEADD(DAY, -30, GETDATE()), 112))\\n) sub\\nJOIN msdb.dbo.sysjobs j ON sub.job_id = j.job_id\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE s.freq_subday_type = 4  -- minute-based schedules\\nGROUP BY j.name, j.job_id, s.freq_subday_interval, s.freq_subday_type, s.active_start_time\\nHAVING COUNT(*) >= 5\\n  AND MAX(((sub.dur_sec))) > s.freq_subday_interval * 60 * 0.8\\nORDER BY (MAX(sub.dur_sec) - MIN(sub.dur_sec)) DESC;\\n", "parameters": {"safety_buffer_pct": 25, "history_window_days": 30}, "description": "Identifies jobs whose maximum recorded duration exceeds 80% of their current scheduling interval, flagging them as candidates for schedule adjustment. Review output before proceeding."}	null	low	f	f	\N	2026-02-24 13:10:27.313971
1852	sqlserver	configure	Configure WMI alert for AG role-change events to notify DBA	{"sql": "USE msdb;\\n-- Create a WMI alert that fires on availability replica state changes\\nIF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysalerts WHERE name = 'AG Role Change - Review Job Schedules')\\nBEGIN\\n  EXEC msdb.dbo.sp_add_alert\\n    @name = N'AG Role Change - Review Job Schedules',\\n    @wmi_namespace = N'\\\\\\\\.\\\\.\\\\root\\\\Microsoft\\\\SqlServer\\\\ServerEvents\\\\MSSQLSERVER',\\n    @wmi_query = N'SELECT * FROM HADR_AVAILABILITY_REPLICA_STATE_CHANGE',\\n    @enabled = 1,\\n    @delay_between_responses = 300,\\n    @notification_message = N'AG role change detected. Verify job schedules are correct on new primary: ' + @@SERVERNAME;\\n\\n  EXEC msdb.dbo.sp_add_notification\\n    @alert_name = N'AG Role Change - Review Job Schedules',\\n    @operator_name = N'DBA_Alerts',\\n    @notification_method = 1;\\n\\n  PRINT 'WMI alert for AG role change created.';\\nEND\\nELSE\\n  PRINT 'Alert already exists.';\\n", "parameters": {"instance_name": "MSSQLSERVER (replace with named instance if applicable)"}, "description": "Creates a WMI event alert that triggers whenever the AG replica changes role, immediately notifying the DBA to review job execution state on the new primary."}	{"sql": "EXEC msdb.dbo.sp_delete_alert @name = N'AG Role Change - Review Job Schedules';", "description": "Removes the WMI alert for AG role changes."}	low	f	t	\N	2026-02-24 13:10:27.313978
1847	sqlserver	configure	Update schedule intervals to include 25% duration buffer	{"sql": "-- Template: execute per job identified in step 1.\\n-- Replace @job_name and @new_interval_min with values from step 1 output.\\nDECLARE @job_name NVARCHAR(128) = N'YourJobNameHere';  -- Replace\\nDECLARE @new_interval_min INT = 60;                      -- Replace with recommended_interval_min\\n\\nDECLARE @schedule_id INT;\\nSELECT @schedule_id = s.schedule_id\\nFROM msdb.dbo.sysschedules s\\nJOIN msdb.dbo.sysjobschedules jss ON s.schedule_id = jss.schedule_id\\nJOIN msdb.dbo.sysjobs j ON jss.job_id = j.job_id\\nWHERE j.name = @job_name AND s.freq_subday_type = 4;\\n\\nIF @schedule_id IS NULL\\n  RAISERROR('No minute-based schedule found for job: %s', 16, 1, @job_name);\\n\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = @schedule_id,\\n  @freq_subday_interval = @new_interval_min;\\n\\nPRINT 'Schedule updated for: ' + @job_name;\\n", "parameters": {"job_name": "Replace per step 1 output", "new_interval_min": "recommended_interval_min from step 1"}, "description": "Extends the scheduling interval for a specific job to accommodate its maximum observed duration plus a 25% safety buffer. Run once per job identified in step 1."}	{"sql": "-- Restore original interval (record original value before running step 2)\\nDECLARE @schedule_id INT = <original_schedule_id>;\\nDECLARE @original_interval INT = <original_interval>;\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = @schedule_id,\\n  @freq_subday_interval = @original_interval;", "description": "Restores the original scheduling interval. Record the current values from step 1 before making changes."}	medium	t	t	\N	2026-02-24 13:10:27.313973
1848	sqlserver	execute	Add step-level timeout on job steps to cap maximum runtime	{"sql": "-- Set a command_execution_success_code and step timeout (via proxy or external monitor)\\n-- SQL Agent T-SQL steps do not support native timeouts, so implement via job step logic:\\n-- Wrap long-running step command with a KILL-based watchdog pattern.\\n\\n-- Alternative: Use sp_add_alert on performance condition to detect overlong jobs.\\n-- Create an alert that fires when a job has been running > threshold seconds:\\nUSE msdb;\\nIF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysalerts WHERE name = 'Job Running Too Long')\\nBEGIN\\n  EXEC msdb.dbo.sp_add_alert\\n    @name = N'Job Running Too Long',\\n    @message_id = 0,\\n    @severity = 0,\\n    @enabled = 1,\\n    @delay_between_responses = 600,  -- seconds between repeat notifications\\n    @notification_message = N'A SQL Agent job has been running longer than expected. Investigate sysjobactivity.',\\n    @job_name = N'';  -- Applies to all jobs; restrict by setting @job_id if needed\\n\\n  EXEC msdb.dbo.sp_add_notification\\n    @alert_name = N'Job Running Too Long',\\n    @operator_name = N'DBA_Alerts',\\n    @notification_method = 1;  -- 1 = email\\n\\n  PRINT 'Long-running job alert created.';\\nEND\\nELSE\\n  PRINT 'Alert already exists.';\\n\\n-- Also: set max_run_duration on individual job steps (0 = no limit; set in seconds)\\n-- This is done via sp_update_jobstep @job_id, @step_id, @command_execution_success_code\\n-- For SSIS steps, configure PackageParameters MaxConcurrentExecutables and timeout properties.\\n", "parameters": {"delay_between_responses_sec": 600}, "description": "Creates a SQL Agent alert for long-running jobs. For TSQL job steps, wraps execution with a duration check. Individual job step timeouts must be configured at the application or SSIS package level."}	{"sql": "EXEC msdb.dbo.sp_delete_alert @name = N'Job Running Too Long';", "description": "Removes the long-running job alert."}	low	f	t	\N	2026-02-24 13:10:27.313974
1849	sqlserver	verify	Confirm updated schedules and verify no overlapping executions	{"sql": "-- Verify no job's max duration now exceeds its schedule interval\\nSELECT j.name AS job_name,\\n  MAX(((h.run_duration / 10000) * 3600\\n    + ((h.run_duration % 10000) / 100) * 60\\n    + (h.run_duration % 100))) AS max_duration_sec,\\n  s.freq_subday_interval * 60 AS interval_sec,\\n  CASE WHEN MAX(((h.run_duration / 10000) * 3600\\n    + ((h.run_duration % 10000) / 100) * 60\\n    + (h.run_duration % 100))) < s.freq_subday_interval * 60\\n  THEN 'OK' ELSE 'STILL_AT_RISK' END AS status\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE h.step_id = 0 AND h.run_status = 1 AND s.freq_subday_type = 4\\n  AND h.run_date >= CONVERT(INT, CONVERT(VARCHAR(8), DATEADD(DAY, -30, GETDATE()), 112))\\nGROUP BY j.name, s.freq_subday_interval\\nORDER BY status DESC;\\n", "parameters": null, "description": "Confirms that updated schedule intervals now exceed each job's maximum observed duration. Any row returning STILL_AT_RISK requires further interval widening."}	null	low	f	f	\N	2026-02-24 13:10:27.313975
1850	sqlserver	verify	Confirm current node role and identify jobs that ran at wrong times	{"sql": "-- Confirm this node is the intended primary\\nSELECT\\n  @@SERVERNAME AS server_name,\\n  SERVERPROPERTY('IsClustered') AS is_clustered,\\n  SERVERPROPERTY('IsHadrEnabled') AS hadr_enabled,\\n  (SELECT TOP 1 role_desc\\n   FROM sys.dm_hadr_availability_replica_states\\n   WHERE is_local = 1) AS ag_role,\\n  (SELECT MAX(sqlserver_start_time) FROM sys.dm_os_sys_info) AS last_start;\\n\\n-- Find jobs that ran at unexpected times (> 1-hour drift from schedule)\\nSELECT j.name AS job_name,\\n  h.run_date, h.run_time AS actual_run_time,\\n  s.active_start_time AS scheduled_time,\\n  ABS(h.run_time - s.active_start_time) AS drift,\\n  h.run_status,\\n  CASE h.run_status WHEN 0 THEN 'FAILED' WHEN 1 THEN 'SUCCEEDED' ELSE 'OTHER' END AS status_desc\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE h.step_id = 0\\n  AND h.run_date >= CONVERT(INT, CONVERT(VARCHAR(8), DATEADD(DAY, -3, GETDATE()), 112))\\n  AND ABS(h.run_time - s.active_start_time) > 10000\\nORDER BY h.run_date DESC, drift DESC;\\n", "parameters": null, "description": "Confirms the node's current AG role and identifies which jobs experienced schedule drift after the failover event."}	null	low	f	f	\N	2026-02-24 13:10:27.313976
1851	sqlserver	configure	Add primary-role guard to all critical Agent job first steps	{"sql": "-- Prepend a primary-role check to critical job steps so jobs self-abort on replicas/standby nodes.\\n-- Template: run for each critical job that must only execute on the primary.\\nDECLARE @job_name NVARCHAR(128) = N'YourCriticalJobHere';  -- Replace per job\\nDECLARE @step_id   INT          = 1;                        -- First step (guard step)\\n\\nDECLARE @existing_cmd NVARCHAR(MAX);\\nSELECT @existing_cmd = command\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.name = @job_name AND js.step_id = @step_id;\\n\\nDECLARE @guard NVARCHAR(MAX) = N'\\n-- AG / FCI primary guard\\nIF SERVERPROPERTY(''IsHadrEnabled'') = 1\\nBEGIN\\n  IF NOT EXISTS (\\n    SELECT 1 FROM sys.dm_hadr_availability_replica_states\\n    WHERE is_local = 1 AND role_desc = ''PRIMARY''\\n  )\\n  BEGIN\\n    RAISERROR(''Not the AG primary — job execution skipped.'', 16, 1);\\n    RETURN;\\n  END\\nEND\\n-- FCI guard (no AG)\\nELSE IF SERVERPROPERTY(''IsClustered'') = 1\\nBEGIN\\n  -- Optionally check cluster resource ownership here\\n  -- For FCI, SQL Server only starts on the active node, so this is informational\\n  PRINT ''FCI active node confirmed.'';\\nEND\\n';\\n\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = @job_name,\\n  @step_id  = @step_id,\\n  @command  = @guard + @existing_cmd;\\n\\nPRINT 'Primary-role guard prepended to ' + @job_name + ' step ' + CAST(@step_id AS VARCHAR(5));\\n", "parameters": {"step_id": 1, "job_name": "Replace with each critical job name"}, "description": "Prepends an AG primary-role check to the first step of critical jobs. If executed on a replica, the step raises an error and the job stops without processing data."}	{"sql": "-- Restore original step command (save @existing_cmd value before running step 2)\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'YourCriticalJobHere',\\n  @step_id  = 1,\\n  @command  = N'<original command here>';", "description": "Restores the original job step command without the primary-role guard."}	medium	t	t	\N	2026-02-24 13:10:27.313977
1854	sqlserver	execute	Identify and rank concurrent job clusters for staggering	{"sql": "-- Identify all time slots with 3+ concurrent jobs and rank by estimated resource impact\\nSELECT\\n  s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000' + CAST(s.active_start_time AS VARCHAR(6)), 6), 5, 0, ':'), 3, 0, ':') AS start_time_fmt,\\n  COUNT(DISTINCT j.job_id) AS concurrent_jobs,\\n  STRING_AGG(j.name, ' | ') AS job_names,\\n  -- Approximate resource weight: jobs with many steps or long history rank higher\\n  SUM((\\n    SELECT COUNT(*) FROM msdb.dbo.sysjobsteps js2 WHERE js2.job_id = j.job_id\\n  )) AS total_steps\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND s.freq_type IN (4, 8, 16, 32)  -- daily, weekly, monthly, relative monthly\\nGROUP BY s.active_start_time\\nHAVING COUNT(DISTINCT j.job_id) >= 3\\nORDER BY concurrent_jobs DESC, s.active_start_time;\\n", "parameters": null, "description": "Lists all time slots where 3 or more enabled jobs share the same start time. Review output to determine staggering assignments before updating schedules."}	null	low	f	f	\N	2026-02-24 13:10:27.313981
