1855	sqlserver	configure	Update job schedules with staggered start times	{"sql": "-- Template: run for each job identified in step 1.\\n-- Assign a unique start time offset (original_time + N * 2 minutes per job in the cluster).\\n-- Example: 3 jobs at 02:00 → reassign to 02:00, 02:02, 02:04\\n\\n-- Step 1: Record current schedule for rollback\\nSELECT j.name, s.schedule_id, s.active_start_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.name IN ('JobA', 'JobB', 'JobC');  -- Replace with actual job names\\n\\n-- Step 2: Apply new staggered start times\\n-- NOTE: active_start_time format is HHMMSS as integer\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = <schedule_id_for_JobB>,  -- Replace\\n  @active_start_time = 20200;             -- 02:02:00\\n\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = <schedule_id_for_JobC>,  -- Replace\\n  @active_start_time = 20400;             -- 02:04:00\\n\\n-- Verify the cluster is now staggered\\nSELECT j.name,\\n  STUFF(STUFF(RIGHT('000000' + CAST(s.active_start_time AS VARCHAR(6)), 6), 5, 0, ':'), 3, 0, ':') AS new_start_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.name IN ('JobA', 'JobB', 'JobC');\\n", "parameters": {"time_format": "HHMMSS as integer (e.g., 20200 = 02:02:00)", "stagger_interval_minutes": 2}, "description": "Applies staggered start times to jobs within each concurrent cluster. Offset each job by 2 minutes relative to the cluster's original start time. Record original schedule IDs and times before updating."}	{"sql": "-- Restore original start times from pre-change records\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = <schedule_id_for_JobB>,\\n  @active_start_time = <original_start_time>;\\nEXEC msdb.dbo.sp_update_schedule\\n  @schedule_id = <schedule_id_for_JobC>,\\n  @active_start_time = <original_start_time>;", "description": "Restores original start times. Requires values recorded before step 2 was executed."}	medium	t	t	\N	2026-02-24 13:10:27.313982
1856	sqlserver	verify	Confirm no cluster of 3+ jobs shares the same start time	{"sql": "-- Verify no time slot still has 3+ concurrent jobs\\nSELECT\\n  STUFF(STUFF(RIGHT('000000' + CAST(s.active_start_time AS VARCHAR(6)), 6), 5, 0, ':'), 3, 0, ':') AS start_time_fmt,\\n  COUNT(DISTINCT j.job_id) AS concurrent_jobs,\\n  STRING_AGG(j.name, ' | ') AS job_names\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND s.freq_type IN (4, 8, 16, 32)\\nGROUP BY s.active_start_time\\nHAVING COUNT(DISTINCT j.job_id) >= 3\\nORDER BY concurrent_jobs DESC;\\n\\n-- If this returns 0 rows, the thundering herd has been resolved.\\n", "parameters": null, "description": "Re-runs the cluster detection query from step 1 to confirm that no time slot still has 3 or more concurrent jobs after staggering."}	null	low	f	f	\N	2026-02-24 13:10:27.313984
1857	sqlserver	execute	Identify specific schema mismatches between ETL logic and source	{"sql": "-- Retrieve failing ETL step commands and cross-reference with source schema\\n-- Step 1a: Extract the T-SQL from the failing job step\\nSELECT j.name AS job_name, js.step_id, js.step_name,\\n  js.subsystem,\\n  LEFT(js.command, 2000) AS step_command\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE j.name = N'YourETLJobName'  -- Replace with failing job name\\nORDER BY js.step_id;\\n\\n-- Step 1b: If a linked server is used, query the source table schema\\n-- Replace linked_server, source_db, source_schema, source_table with actual values\\nSELECT c.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH,\\n  c.NUMERIC_PRECISION, c.NUMERIC_SCALE, c.IS_NULLABLE\\nFROM [LinkedServerName].[source_db].INFORMATION_SCHEMA.COLUMNS c\\nWHERE c.TABLE_SCHEMA = 'source_schema'\\n  AND c.TABLE_NAME   = 'source_table'\\nORDER BY c.ORDINAL_POSITION;\\n\\n-- Step 1c: Compare to target table schema\\nSELECT c.name AS column_name, t.name AS data_type,\\n  c.max_length, c.precision, c.scale, c.is_nullable\\nFROM sys.columns c\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nWHERE OBJECT_NAME(c.object_id) = 'target_table_name'  -- Replace\\nORDER BY c.column_id;\\n", "parameters": {"job_name": "Replace with the failing job name", "source_table": "Replace with the source table name", "linked_server": "Replace with the linked server name"}, "description": "Extracts the ETL job step code and queries source and target schema side-by-side to identify column name, data type, or nullability mismatches."}	null	low	f	f	\N	2026-02-24 13:10:27.313985
1894	sqlserver	verify	Simulate re-run and confirm no duplicate key errors	{"sql": "-- Run the updated job step twice to confirm idempotency\\n-- Then check history shows both runs succeeded\\nSELECT TOP 5\\n  j.name AS job_name, h.run_date, h.run_time,\\n  CASE h.run_status WHEN 1 THEN 'SUCCESS' ELSE 'FAILED' END AS status,\\n  SUBSTRING(h.message, 1, 300) AS message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = '<job_name>'\\nORDER BY h.run_date DESC, h.run_time DESC;", "parameters": {"job_name": "Name of the ETL SQL Agent job"}, "description": "Execute the job twice in succession on the same source data. Confirm both runs show run_status = 1 with no duplicate key errors."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.323339
1859	sqlserver	verify	Run ETL job manually and confirm successful completion	{"sql": "-- Execute the job manually for testing\\nEXEC msdb.dbo.sp_start_job @job_name = N'YourETLJobName';  -- Replace\\n\\n-- Wait for completion, then check result\\nWAITFOR DELAY '00:00:30';  -- Adjust wait based on expected job duration\\n\\nSELECT TOP 1\\n  j.name AS job_name,\\n  h.run_date, h.run_time,\\n  CASE h.run_status\\n    WHEN 0 THEN 'FAILED'\\n    WHEN 1 THEN 'SUCCEEDED'\\n    WHEN 2 THEN 'RETRY'\\n    WHEN 3 THEN 'CANCELLED'\\n    ELSE 'UNKNOWN'\\n  END AS status,\\n  ((h.run_duration / 10000) * 3600\\n   + ((h.run_duration % 10000) / 100) * 60\\n   + (h.run_duration % 100)) AS duration_sec,\\n  LEFT(h.message, 500) AS message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = N'YourETLJobName'\\n  AND h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;\\n", "parameters": {"job_name": "Replace with ETL job name"}, "description": "Triggers a manual execution of the updated ETL job and inspects the resulting job history record for successful completion."}	null	medium	t	f	\N	2026-02-24 13:10:27.31802
1860	sqlserver	configure	Implement schema-drift detection monitoring job	{"sql": "-- Create a weekly schema-snapshot comparison job to detect future source drift\\nUSE msdb;\\nIF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysjobs WHERE name = 'Monitor - Source Schema Drift Detection')\\nBEGIN\\n  EXEC msdb.dbo.sp_add_job\\n    @job_name = N'Monitor - Source Schema Drift Detection',\\n    @enabled = 1,\\n    @description = N'Weekly check: compares source table schemas against ETL baseline snapshots',\\n    @notify_level_email = 2,\\n    @notify_email_operator_name = N'DBA_Alerts';\\n\\n  EXEC msdb.dbo.sp_add_jobstep\\n    @job_name = N'Monitor - Source Schema Drift Detection',\\n    @step_name = N'Detect schema drift',\\n    @subsystem = N'TSQL',\\n    @command = N'\\n-- Compare current source schema to a baseline snapshot stored in a monitoring table.\\n-- Populate dbo.schema_baseline on first run, then diff on subsequent runs.\\nIF OBJECT_ID(''dbo.schema_baseline'', ''U'') IS NULL\\nBEGIN\\n  CREATE TABLE dbo.schema_baseline (\\n    table_source NVARCHAR(200),\\n    column_name  NVARCHAR(128),\\n    data_type    NVARCHAR(128),\\n    max_length   INT,\\n    is_nullable  BIT,\\n    snapshot_date DATETIME DEFAULT GETDATE()\\n  );\\n  -- Populate with current source schema (adapt linked server query as needed)\\n  PRINT ''Schema baseline created. Re-run next week to detect drift.'';\\n  RETURN;\\nEND\\n\\n-- Check current source schema and alert on differences\\nSELECT ''DRIFT_DETECTED'' AS status,\\n  b.table_source, b.column_name,\\n  b.data_type AS baseline_type, b.max_length AS baseline_len,\\n  -- Current schema from linked server would be joined here\\n  b.snapshot_date\\nFROM dbo.schema_baseline b\\nWHERE b.snapshot_date < DATEADD(DAY, -6, GETDATE());\\n';\\n\\n  DECLARE @sched_id INT;\\n  EXEC msdb.dbo.sp_add_schedule\\n    @schedule_name = N'WeeklyMonday0700',\\n    @freq_type = 8, @freq_interval = 2,\\n    @freq_recurrence_factor = 1,\\n    @active_start_time = 70000;\\n  EXEC msdb.dbo.sp_attach_schedule\\n    @job_name = N'Monitor - Source Schema Drift Detection',\\n    @schedule_name = N'WeeklyMonday0700';\\n  EXEC msdb.dbo.sp_add_jobserver\\n    @job_name = N'Monitor - Source Schema Drift Detection',\\n    @server_name = N'(LOCAL)';\\n\\n  PRINT 'Schema drift monitoring job created.';\\nEND\\n", "parameters": {"schedule": "Weekly, Monday 07:00"}, "description": "Creates a weekly Agent job that compares source table schemas against a baseline snapshot and alerts on differences, providing early warning before the next ETL execution cycle."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = N'Monitor - Source Schema Drift Detection', @delete_unused_schedule = 1;\\nIF OBJECT_ID('dbo.schema_baseline', 'U') IS NOT NULL DROP TABLE dbo.schema_baseline;", "description": "Removes the monitoring job, its schedule, and the schema baseline table."}	low	f	t	00:05:00	2026-02-24 13:10:27.318395
1862	sqlserver	configure	Add pre-flight source availability check as a dedicated job step	{"sql": "USE msdb;\\n-- Insert a new step 1 (pre-flight check) before the main ETL step\\n-- Existing steps must have their sequence renumbered if needed.\\n\\n-- Option A: File-based ETL — check for file existence before proceeding\\nEXEC msdb.dbo.sp_add_jobstep\\n  @job_name  = N'YourETLJobName',   -- Replace\\n  @step_id   = 1,\\n  @step_name = N'Pre-flight: Verify source file exists',\\n  @subsystem = N'TSQL',\\n  @command   = N'\\nDECLARE @file_path NVARCHAR(500) = N''\\\\\\\\fileserver\\\\share\\\\input.csv'';  -- Replace\\nDECLARE @exists INT = 0;\\nEXEC master.dbo.xp_fileexist @file_path, @exists OUTPUT;\\nIF @exists = 0\\nBEGIN\\n  RAISERROR(''Pre-flight FAILED: Source file not found: %s'', 16, 1, @file_path);\\n  -- Job will fail here — no downstream steps will run\\nEND\\nELSE\\n  PRINT ''Pre-flight PASSED: Source file confirmed.'';\\n',\\n  @on_success_action = 3,  -- 3 = go to next step\\n  @on_fail_action    = 2;  -- 2 = quit job reporting failure\\n\\n-- Option B: Database-sourced ETL — check for rows in source table\\n-- Replace above command with:\\n/*\\nDECLARE @row_count INT;\\nSELECT @row_count = COUNT(*) FROM [LinkedServer].[db].[schema].[source_table]\\nWHERE load_date = CAST(GETDATE() AS DATE);  -- Adjust date filter\\nIF @row_count = 0\\n  RAISERROR(''Pre-flight FAILED: Source table has 0 rows for today.'', 16, 1);\\nELSE\\n  PRINT ''Pre-flight PASSED: '' + CAST(@row_count AS VARCHAR(20)) + '' source rows confirmed.''\\n*/\\n\\nPRINT 'Pre-flight step added to ETL job.';\\n", "parameters": {"job_name": "Replace with ETL job name", "file_path_or_table": "Replace with source file path or linked server table reference"}, "description": "Inserts a new first step in the ETL Agent job that checks source file or table availability. If the source is absent, the job fails immediately at step 1 with a clear error message, preventing execution of downstream transformation logic."}	{"sql": "EXEC msdb.dbo.sp_delete_jobstep\\n  @job_name = N'YourETLJobName',\\n  @step_id  = 1;", "description": "Removes the pre-flight check step. Note: renumber remaining steps manually if needed."}	low	f	t	\N	2026-02-24 13:10:27.318831
1863	sqlserver	verify	Re-run ETL job after source data is confirmed available	{"sql": "-- Confirm source is present, then execute the job\\n-- For file-based ETL:\\nDECLARE @file_path NVARCHAR(500) = N'\\\\\\\\fileserver\\\\share\\\\input.csv';  -- Replace\\nDECLARE @exists INT = 0;\\nEXEC master.dbo.xp_fileexist @file_path, @exists OUTPUT;\\nSELECT @exists AS file_exists, @file_path AS checked_path;\\n\\n-- Run job only after confirming source is present\\nEXEC msdb.dbo.sp_start_job @job_name = N'YourETLJobName';  -- Replace\\n\\nWAITFOR DELAY '00:00:30';\\n\\nSELECT TOP 1\\n  j.name, h.run_date, h.run_time,\\n  CASE h.run_status WHEN 1 THEN 'SUCCEEDED' WHEN 0 THEN 'FAILED' ELSE 'OTHER' END AS status,\\n  LEFT(h.message, 500) AS message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = N'YourETLJobName'\\n  AND h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;\\n", "parameters": {"job_name": "Replace with ETL job name"}, "description": "Verifies source data is present, executes the ETL job, and inspects the resulting job history status to confirm successful completion."}	null	medium	t	f	\N	2026-02-24 13:10:27.318833
1864	sqlserver	execute	Diagnose connection failure type	{"sql": "-- Test linked server connectivity\\nSELECT s.name, s.data_source, s.product, s.provider\\nFROM sys.servers s WHERE s.is_linked = 1;\\n\\n-- Test connection to linked server (generates error message on failure)\\n-- Replace 'LinkedServerName' with actual linked server name\\nBEGIN TRY\\n  EXEC ('SELECT 1') AT [LinkedServerName];\\n  SELECT 'CONNECTED' AS connectivity_status;\\nEND TRY\\nBEGIN CATCH\\n  SELECT\\n    'FAILED'          AS connectivity_status,\\n    ERROR_NUMBER()    AS error_number,\\n    ERROR_MESSAGE()   AS error_message,\\n    ERROR_SEVERITY()  AS severity;\\nEND CATCH;\\n\\n-- Check Windows Event Log for network errors via SQL Server Error Log\\nEXEC sys.sp_readerrorlog 0, 1, 'Login failed';\\nEXEC sys.sp_readerrorlog 0, 1, 'network';\\nEXEC sys.sp_readerrorlog 0, 1, 'timeout';\\n", "parameters": {"linked_server_name": "Replace with actual linked server name"}, "description": "Tests linked server connectivity and reads the SQL Server error log for network or authentication errors to determine the specific failure type (timeout, auth, firewall, DNS)."}	null	low	f	f	\N	2026-02-24 13:10:27.318833
1881	sqlserver	configure	Enable READ_COMMITTED_SNAPSHOT to eliminate reader-writer blocking	{"sql": "-- Enable RCSI on the target database (eliminates shared lock reader contention)\\n-- Requires brief exclusive access; run during a maintenance window\\nALTER DATABASE [target_database]\\nSET READ_COMMITTED_SNAPSHOT ON\\nWITH ROLLBACK AFTER 30 SECONDS;\\n\\n-- Verify setting\\nSELECT name, is_read_committed_snapshot_on\\nFROM sys.databases\\nWHERE name = '<target_database>';", "parameters": {"target_database": "Database containing the ETL target table"}, "description": "READ_COMMITTED_SNAPSHOT (RCSI) uses row versioning to allow readers and writers to proceed concurrently without shared locks, eliminating most ETL blocking scenarios."}	{"sql": "ALTER DATABASE [target_database] SET READ_COMMITTED_SNAPSHOT OFF WITH ROLLBACK AFTER 30 SECONDS;", "description": "Disable RCSI and revert to shared-lock read committed behavior."}	medium	t	t	00:20:00	2026-02-24 13:10:27.323331
1865	sqlserver	configure	Resolve connection failure and update linked server or SSIS connection settings	{"sql": "-- Fix A: Update linked server login mapping (credential expiry or rotation)\\nEXEC sys.sp_droplinkedsrvlogin @rmtsrvname = N'LinkedServerName', @locallogin = NULL;\\nEXEC sys.sp_addlinkedsrvlogin\\n  @rmtsrvname  = N'LinkedServerName',\\n  @useself     = 'FALSE',\\n  @locallogin  = NULL,\\n  @rmtuser     = N'etl_service_account',   -- Replace\\n  @rmtpassword = N'NewPassword123!';        -- Replace with actual new password\\n\\n-- Fix B: Increase linked server query timeout (for timeout-class failures)\\nEXEC sys.sp_serveroption\\n  @server  = N'LinkedServerName',\\n  @optname = N'query timeout',\\n  @optvalue = N'120';  -- seconds; adjust as needed\\n\\n-- Fix C: Increase connection timeout\\nEXEC sys.sp_serveroption\\n  @server  = N'LinkedServerName',\\n  @optname = N'connect timeout',\\n  @optvalue = N'30';\\n\\n-- Fix D: If provider options are the issue, reset OLE DB provider settings\\n-- EXEC sys.sp_MSset_oledb_prop N'SQLNCLI', N'AllowInProcess', 1;\\n\\nPRINT 'Linked server connection settings updated.';\\n", "parameters": {"password": "Replace with new password (use secure parameter passing)", "username": "Replace with service account name", "linked_server_name": "Replace with actual name"}, "description": "Applies the appropriate fix for the diagnosed connection issue: updates credentials for auth failures, increases timeouts for timeout failures, or adjusts provider settings. Only apply the fix that matches the error diagnosed in step 1."}	{"sql": "-- Restore previous login mapping\\nEXEC sys.sp_droplinkedsrvlogin @rmtsrvname = N'LinkedServerName', @locallogin = NULL;\\n-- Re-add with original credentials\\nEXEC sys.sp_addlinkedsrvlogin\\n  @rmtsrvname  = N'LinkedServerName',\\n  @useself     = 'FALSE',\\n  @locallogin  = NULL,\\n  @rmtuser     = N'<original_user>',\\n  @rmtpassword = N'<original_password>';", "description": "Restores the previous linked server login mapping if the credential update causes new issues."}	medium	t	t	\N	2026-02-24 13:10:27.318834
1866	sqlserver	execute	Add retry logic to ETL job for transient connection failures	{"sql": "-- Wrap the ETL step with retry logic for transient failures\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name  = N'YourETLJobName',\\n  @step_id   = 2,    -- Adjust to the main extraction step\\n  @retry_attempts  = 3,\\n  @retry_interval  = 5;  -- minutes between retries\\n\\n-- Verify retry settings applied\\nSELECT js.step_id, js.step_name,\\n  js.retry_attempts, js.retry_interval\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.name = N'YourETLJobName';\\n", "parameters": {"retry_attempts": 3, "retry_interval_minutes": 5}, "description": "Configures SQL Agent job step retry parameters so transient network errors (brief TCP resets, transient auth failures) are automatically retried up to 3 times with a 5-minute delay before the step is declared failed."}	{"sql": "EXEC msdb.dbo.sp_update_jobstep\\n  @job_name       = N'YourETLJobName',\\n  @step_id        = 2,\\n  @retry_attempts = 0,\\n  @retry_interval = 0;", "description": "Resets retry settings to zero if the retry behavior causes unintended side effects."}	low	f	t	\N	2026-02-24 13:10:27.318835
