1878	sqlserver	execute	Convert INSERT to MERGE for idempotent load	{"sql": "-- Replace raw INSERT with MERGE to handle duplicates on re-run\\nMERGE target_table AS tgt\\nUSING staging_table AS src\\n  ON tgt.pk_column = src.pk_column\\nWHEN MATCHED THEN\\n  UPDATE SET\\n    tgt.col1 = src.col1,\\n    tgt.col2 = src.col2\\nWHEN NOT MATCHED BY TARGET THEN\\n  INSERT (pk_column, col1, col2)\\n  VALUES (src.pk_column, src.col1, src.col2);", "parameters": {"pk_column": "Join key matching source to target", "target_table": "Destination table", "staging_table": "Source/staging table"}, "description": "Replace the failing INSERT with a MERGE statement so the ETL step is idempotent. Matched rows are updated; new rows are inserted. Eliminates PK/UK duplicate failures on retry."}	{"sql": "-- Revert to original INSERT if MERGE causes unintended updates\\n-- Restore from pre-load backup taken in preconditions\\nRESTORE DATABASE target_db FROM DISK = 'backup_path' WITH NORECOVERY;", "description": "Restore target table from backup if MERGE produces unintended data changes."}	medium	t	t	00:30:00	2026-02-24 13:10:27.323329
1879	sqlserver	verify	Re-run job and confirm successful completion	{"sql": "-- Confirm most recent run succeeded\\nSELECT TOP 1\\n  j.name AS job_name,\\n  h.run_date, h.run_time,\\n  CASE h.run_status WHEN 1 THEN 'SUCCESS' ELSE 'FAILED' END AS status,\\n  SUBSTRING(h.message, 1, 300) AS message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = '<job_name>'\\n  AND h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;", "parameters": {"job_name": "Name of the ETL SQL Agent job"}, "description": "Confirm the ETL job completed with run_status = 1 and no constraint violation messages."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.32333
1880	sqlserver	execute	Kill the blocking session (if safe to terminate)	{"sql": "-- Identify the head blocker\\nSELECT\\n  r.session_id AS blocked_session,\\n  r.blocking_session_id AS blocker_session,\\n  bs.login_name AS blocker_login,\\n  bs.program_name AS blocker_program,\\n  r.wait_time / 1000 AS wait_sec,\\n  SUBSTRING(bt.text, 1, 300) AS blocker_query\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions bs ON r.blocking_session_id = bs.session_id\\nCROSS APPLY sys.dm_exec_sql_text(bs.sql_handle) bt\\nWHERE r.blocking_session_id <> 0\\nORDER BY r.wait_time DESC;\\n\\n-- Kill head blocker after DBA review (replace SPID)\\n-- KILL <blocker_session_id>;", "parameters": {"blocker_session_id": "Session ID of the head blocker identified above"}, "description": "Surface blocker details and allow DBA to decide whether to KILL the head blocking session. Commented KILL must be run manually after review."}	null	medium	t	f	00:05:00	2026-02-24 13:10:27.323331
1883	sqlserver	execute	Free transaction log space or expand log file	{"sql": "-- Check log reuse wait reason\\nSELECT name, log_reuse_wait_desc,\\n  CAST(log_size_mb AS decimal(10,1)) AS log_size_mb,\\n  CAST(log_used_mb AS decimal(10,1)) AS log_used_mb\\nFROM sys.dm_db_log_space_usage AS lsu\\nCROSS JOIN sys.databases d\\nWHERE d.database_id = DB_ID();\\n\\n-- If log_reuse_wait_desc = LOG_BACKUP: run log backup\\nBACKUP LOG [target_database] TO DISK = 'NUL' WITH STATS = 10;\\n\\n-- If log file is at max size, expand it\\nALTER DATABASE [target_database]\\nMODIFY FILE (NAME = N'target_database_log', MAXSIZE = UNLIMITED);\\n\\n-- If in SIMPLE recovery and log full: shrink after checkpoint\\nCHECKPOINT;\\nDBCC SHRINKFILE (target_database_log, 512);", "parameters": {"target_database": "Database hosting the ETL target table", "target_database_log": "Logical name of the log file from sys.master_files"}, "description": "Resolves log-full condition (Msg 9002) that causes bulk load timeouts. Run log backup if in FULL/BULK_LOGGED recovery; expand or shrink log file as appropriate."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.323333
1884	sqlserver	configure	Increase query timeout on ETL job step or relax Resource Governor limits	{"sql": "-- Option A: Increase command timeout in job step (T-SQL job steps inherit server default)\\n-- Increase lock timeout for the session (milliseconds; -1 = wait forever)\\nSET LOCK_TIMEOUT 300000; -- 5 minutes\\n\\n-- Option B: Raise Resource Governor memory grant for bulk workload group\\nALTER WORKLOAD GROUP [etl_workload_group]\\nWITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25,\\n      REQUEST_MAX_CPU_TIME_SEC = 0);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\n\\n-- Option C: For SSIS/BCP, reduce batch size in the job step command\\n-- Example: add -b 5000 to bcp command to commit every 5000 rows\\n-- Update job step manually in SSMS or via sp_update_jobstep\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<job_name>',\\n  @step_id  = <step_id>,\\n  @command  = N'<updated_command_with_batch_size>';", "parameters": {"step_id": "Step number to update", "job_name": "SQL Agent job name", "etl_workload_group": "Resource Governor workload group used by the ETL session", "updated_command_with_batch_size": "Original command with -b or BatchSize parameter added"}, "description": "Addresses timeout by either increasing Resource Governor grant limits or breaking bulk load into smaller batches that commit within the timeout window."}	{"sql": "ALTER WORKLOAD GROUP [etl_workload_group]\\nWITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 10, REQUEST_MAX_CPU_TIME_SEC = 600);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "description": "Revert Resource Governor workload group to previous limits."}	medium	t	t	00:20:00	2026-02-24 13:10:27.323333
3845	sqlserver	verify	Identify tables with stale statistics driving unnecessary parallel plans	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows, sp.modification_counter,\\n  CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS pct_modified\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > sp.rows * 0.15\\n  AND sp.rows > 10000\\nORDER BY sp.modification_counter DESC;", "parameters": [], "description": "Identifies statistics with more than 15% modifications since last update, which can cause severe cardinality estimation errors."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579302
