1887	sqlserver	configure	Partition extraction into incremental time-window batches	{"sql": "-- Replace full-table extract with windowed loop\\n-- This pattern processes one hour (or configurable window) at a time\\nDECLARE @start datetime = '2026-02-24 00:00:00';\\nDECLARE @end   datetime = GETDATE();\\nDECLARE @batch_hours int = 1;\\nDECLARE @window_start datetime = @start;\\nDECLARE @window_end   datetime;\\n\\nWHILE @window_start < @end\\nBEGIN\\n  SET @window_end = DATEADD(HOUR, @batch_hours, @window_start);\\n  IF @window_end > @end SET @window_end = @end;\\n\\n  INSERT INTO staging_table (col1, col2, extract_ts)\\n  SELECT col1, col2, @window_start\\n  FROM source_table\\n  WHERE event_ts >= @window_start AND event_ts < @window_end;\\n\\n  SET @window_start = @window_end;\\nEND", "parameters": {"event_ts": "Timestamp column used to partition the extract range", "batch_hours": "Time window per loop iteration (tune based on row density)", "source_table": "Source table being extracted", "staging_table": "Intermediate staging table for the ETL load"}, "description": "Replace the single full-period extract with a loop over small time windows. Each iteration processes a bounded row set, preventing memory and tempdb exhaustion from volume spikes."}	{"sql": "-- Truncate staging table if partial load created inconsistency\\nTRUNCATE TABLE staging_table;", "description": "Clear staging table and revert to original full-period extract logic if windowed approach causes issues."}	medium	t	t	01:00:00	2026-02-24 13:10:27.323335
