1907	sqlserver	verify	Identify top growing tables and define retention boundaries	{"sql": "USE [<target_database>];\\nSELECT\\n  OBJECT_SCHEMA_NAME(p.object_id) + '.' + OBJECT_NAME(p.object_id) AS table_name,\\n  SUM(a.total_pages) * 8.0 / 1024 AS total_mb,\\n  p.rows AS row_count,\\n  c.name AS candidate_date_column\\nFROM sys.partitions p\\nJOIN sys.allocation_units a ON p.partition_id = a.container_id\\nJOIN sys.columns c ON p.object_id = c.object_id\\n  AND c.system_type_id IN (40, 41, 42, 43, 58, 61) -- date/datetime types\\nWHERE p.index_id IN (0, 1)\\nGROUP BY p.object_id, p.rows, c.name\\nHAVING SUM(a.total_pages) * 8.0 / 1024 > 500\\nORDER BY total_mb DESC;", "parameters": {"target_database": "Database name identified during detection"}, "description": "Identify the largest tables and confirm candidate date columns to base retention logic on. Review output with application owner to confirm retention period (e.g., 2 years)."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.32334
1896	sqlserver	execute	Add pre-load filter to quarantine invalid rows	{"sql": "-- Route invalid rows to a quarantine table instead of failing the load\\nIF OBJECT_ID('dbo.etl_rejected_rows', 'U') IS NULL\\n  CREATE TABLE dbo.etl_rejected_rows (\\n    job_name        nvarchar(128),\\n    run_date        datetime DEFAULT GETDATE(),\\n    rejection_reason nvarchar(500),\\n    row_data        nvarchar(max)\\n  );\\n\\n-- Insert rejected rows into quarantine\\nINSERT INTO dbo.etl_rejected_rows (job_name, rejection_reason, row_data)\\nSELECT '<job_name>',\\n  'CHECK constraint: <constraint_name>',\\n  (SELECT * FROM [dbo].[staging_table] AS s\\n   WHERE NOT (<check_expression>)\\n   FOR JSON PATH)\\n;\\n\\n-- Delete rejected rows from staging before load\\nDELETE FROM [dbo].[staging_table]\\nWHERE NOT (<check_expression>);\\n\\nPRINT 'Rejected rows quarantined. Proceeding with clean rows.';", "parameters": {"job_name": "SQL Agent job name for quarantine tracking", "staging_table": "Staging table being loaded", "constraint_name": "Name of the failing CHECK constraint", "check_expression": "Constraint condition expression"}, "description": "Quarantine rows that violate validation rules before load, allowing the ETL to proceed with valid records. Rejected rows are preserved for source-system remediation."}	{"sql": "-- Restore rejected rows from quarantine back to staging for reprocessing\\nINSERT INTO [dbo].[staging_table]\\nSELECT JSON columns ... FROM dbo.etl_rejected_rows\\nWHERE job_name = '<job_name>' AND run_date >= CAST(GETDATE() AS date);\\n-- Note: JSON reparsing is schema-specific; adapt to actual column list.", "description": "Restore quarantined rows to staging if the filter was too aggressive or the constraint is relaxed."}	medium	t	t	00:20:00	2026-02-24 13:10:27.323341
1897	sqlserver	verify	Confirm ETL load succeeds and rejected rows are documented	{"sql": "-- Confirm job succeeded\\nSELECT TOP 1\\n  j.name, h.run_date, h.run_time,\\n  CASE h.run_status WHEN 1 THEN 'SUCCESS' ELSE 'FAILED' END AS status\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = '<job_name>' AND h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;\\n\\n-- Review quarantined rows\\nSELECT job_name, run_date, rejection_reason, COUNT(*) AS rejected_count\\nFROM dbo.etl_rejected_rows\\nWHERE CAST(run_date AS date) = CAST(GETDATE() AS date)\\nGROUP BY job_name, run_date, rejection_reason;", "parameters": {"job_name": "Name of the ETL SQL Agent job"}, "description": "Confirm the load succeeded and review the rejection summary. Escalate to source system team if rejected_count is unexpectedly high."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.323342
