1903	sqlserver	verify	Confirm transformation completes with no memory grant failures	{"sql": "-- Confirm no pending memory grants or excessive spills\\nSELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NULL) AS pending_grants,\\n  ws.waiting_tasks_count AS resource_semaphore_waits,\\n  ws.wait_time_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'RESOURCE_SEMAPHORE';\\n\\n-- Confirm ETL job succeeded\\nSELECT TOP 1\\n  j.name, h.run_date,\\n  CASE h.run_status WHEN 1 THEN 'SUCCESS' ELSE 'FAILED' END AS status,\\n  SUBSTRING(h.message, 1, 200) AS message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE j.name = '<job_name>' AND h.step_id = 0\\nORDER BY h.run_date DESC, h.run_time DESC;", "parameters": {"job_name": "Name of the ETL SQL Agent job"}, "description": "Confirm pending_grants = 0 during the ETL window and job run_status = 1 with no memory error messages."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.323347
