1909	sqlserver	configure	Schedule recurring purge SQL Agent job	{"sql": "USE msdb;\\nEXEC dbo.sp_add_job\\n  @job_name = N'DataLifecycle_Purge_<table_name>';\\n\\nEXEC dbo.sp_add_jobstep\\n  @job_name = N'DataLifecycle_Purge_<table_name>',\\n  @step_name = N'Purge old rows',\\n  @command = N'\\nDECLARE @Cutoff DATE = DATEADD(year, -<retention_years>, GETDATE());\\nDECLARE @Rows INT = 1;\\nWHILE @Rows > 0\\nBEGIN\\n  DELETE TOP (5000) FROM [<schema>].[<table_name>]\\n  WHERE [<date_column>] < @Cutoff;\\n  SET @Rows = @@ROWCOUNT;\\n  WAITFOR DELAY ''00:00:01'';\\nEND',\\n  @database_name = N'<target_database>';\\n\\nEXEC dbo.sp_add_schedule\\n  @schedule_name = N'Weekly_Sunday_2AM',\\n  @freq_type = 8,\\n  @freq_interval = 1,\\n  @active_start_time = 020000;\\n\\nEXEC dbo.sp_attach_schedule\\n  @job_name = N'DataLifecycle_Purge_<table_name>',\\n  @schedule_name = N'Weekly_Sunday_2AM';\\n\\nEXEC dbo.sp_add_jobserver\\n  @job_name = N'DataLifecycle_Purge_<table_name>';", "parameters": {"schedule": "Adjust freq_type/freq_interval for daily if insert rate is high", "retention_years": "Agreed retention period"}, "description": "Create a SQL Agent job that runs weekly to delete rows older than the retention cutoff. Adjust schedule frequency based on insert rate."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = N'DataLifecycle_Purge_<table_name>';", "description": "Remove the scheduled purge job if the approach is changed."}	low	t	t	00:10:00	2026-02-24 13:10:27.323349
1910	sqlserver	verify	Assess fragmentation and statistics staleness before remediation	{"sql": "-- Fragmentation summary\\nSELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  CAST(ips.avg_fragmentation_in_percent AS decimal(5,1)) AS fragmentation_pct,\\n  ips.page_count,\\n  ips.page_count * 8.0 / 1024 AS size_mb,\\n  CASE\\n    WHEN ips.avg_fragmentation_in_percent > 30 THEN 'REBUILD'\\n    WHEN ips.avg_fragmentation_in_percent > 10 THEN 'REORGANIZE'\\n    ELSE 'SKIP'\\n  END AS recommended_action\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 1000 AND ips.index_id > 0\\nORDER BY ips.avg_fragmentation_in_percent DESC;", "parameters": {}, "description": "Quantify fragmentation and identify which indexes need rebuild vs reorganize. Results guide the maintenance job configuration."}	null	low	f	t	00:15:00	2026-02-24 13:10:27.32335
5728	postgresql	verify	Verify statistics remain current after data modifications	{"sql": "SELECT relname, reloptions\\nFROM pg_class\\nWHERE relname = '@table_name';\\n\\nSELECT schemaname, relname, n_mod_since_analyze, last_autoanalyze\\nFROM pg_stat_user_tables\\nWHERE relname = '@table_name';", "parameters": ["table_name"], "description": "Confirms the per-table settings are in place and monitors that autoanalyze fires more frequently."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
1911	sqlserver	execute	Perform immediate index rebuild and statistics update	{"sql": "-- Rebuild highly fragmented indexes (>30%) — run per database\\nDECLARE @sql NVARCHAR(MAX) = '';\\n\\nSELECT @sql += 'ALTER INDEX ' + QUOTENAME(i.name)\\n  + ' ON ' + QUOTENAME(OBJECT_SCHEMA_NAME(ips.object_id)) + '.' + QUOTENAME(OBJECT_NAME(ips.object_id))\\n  + ' REBUILD WITH (ONLINE = ON, FILLFACTOR = 80);' + CHAR(13)\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND ips.index_id > 0;\\n\\nPRINT @sql; -- Review before uncommenting EXEC\\n-- EXEC sp_executesql @sql;\\n\\n-- Update all stale statistics\\nEXEC sp_updatestats;", "parameters": {"ONLINE": "ON for Enterprise Edition; change to OFF for Standard Edition (requires exclusive lock)", "FILLFACTOR": "80 is a conservative default; adjust based on insert/update frequency"}, "description": "Generate and execute index rebuild statements for all highly fragmented indexes, then update all stale statistics. Review PRINT output before enabling EXEC."}	{"description": "Index rebuild is non-destructive and does not require rollback. If ONLINE=OFF rebuild caused blocking, restart SQL Server Agent or kill blocking sessions."}	medium	t	t	03:00:00	2026-02-24 13:10:27.32335
1912	sqlserver	configure	Deploy recurring index maintenance SQL Agent job	{"sql": "-- Option A: Ola Hallengren's IndexOptimize (recommended — download from ola.hallengren.com)\\n-- EXEC dbo.IndexOptimize\\n--   @Databases = 'USER_DATABASES',\\n--   @FragmentationLow = NULL,\\n--   @FragmentationMedium = 'INDEX_REORGANIZE',\\n--   @FragmentationHigh = 'INDEX_REBUILD_ONLINE,INDEX_REBUILD_OFFLINE',\\n--   @FragmentationLevel1 = 10,\\n--   @FragmentationLevel2 = 30,\\n--   @UpdateStatistics = 'ALL',\\n--   @OnlyModifiedStatistics = 'Y';\\n\\n-- Option B: Native T-SQL job step (attach to existing maintenance schedule)\\nUSE msdb;\\nEXEC dbo.sp_add_job @job_name = N'IndexMaintenance_Weekly';\\nEXEC dbo.sp_add_jobstep\\n  @job_name = N'IndexMaintenance_Weekly',\\n  @step_name = N'Rebuild and reorganize indexes',\\n  @command = N'EXEC sp_updatestats; -- full rebuild script generated in step 2',\\n  @database_name = N'master';\\nEXEC dbo.sp_add_schedule\\n  @schedule_name = N'Weekly_Saturday_1AM',\\n  @freq_type = 8, @freq_interval = 64,\\n  @active_start_time = 010000;\\nEXEC dbo.sp_attach_schedule\\n  @job_name = N'IndexMaintenance_Weekly',\\n  @schedule_name = N'Weekly_Saturday_1AM';\\nEXEC dbo.sp_add_jobserver @job_name = N'IndexMaintenance_Weekly';", "parameters": {"schedule": "Weekly for most workloads; nightly for high-write OLTP databases"}, "description": "Configure a weekly SQL Agent job to maintain indexes automatically. Ola Hallengren's IndexOptimize is the community-standard solution and preferred where installable."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = N'IndexMaintenance_Weekly';", "description": "Remove the job if an alternative maintenance solution is chosen."}	low	t	t	00:15:00	2026-02-24 13:10:27.323351
1925	sqlserver	verify	Diagnose backup job failure root cause	{"sql": "-- Get detailed error messages from the most recent failed backup job runs\\nSELECT TOP 50\\n  j.name AS job_name,\\n  h.run_date,\\n  h.run_time,\\n  CASE h.run_status\\n    WHEN 0 THEN 'Failed'\\n    WHEN 1 THEN 'Succeeded'\\n    WHEN 3 THEN 'Canceled'\\n  END AS status,\\n  h.step_id,\\n  h.step_name,\\n  h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day,-14,GETDATE()),112))\\n  AND (j.name LIKE '%backup%' OR j.name LIKE '%Backup%' OR j.name LIKE '%maintenance%')\\nORDER BY h.run_date DESC, h.run_time DESC, h.step_id;\\n\\n-- Also check SQL Server error log for backup errors\\nEXEC xp_readerrorlog 0, 1, 'BackupDiskFile', NULL, NULL, NULL, 'DESC';", "parameters": {}, "description": "Extract detailed error messages from SQL Agent history and error log. Common causes: disk full, permission denied, network path unavailable, database offline, or corrupt media."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.323359
