1954	sqlserver	configure	Re-implement bulk operation as a batched, throttled process	{"sql": "-- Batched INSERT with row-level throttling\\n-- Replace with your actual source and target tables\\nDECLARE @batch_size INT = 25000;\\nDECLARE @total_rows INT;\\nDECLARE @processed INT = 0;\\nDECLARE @batch_num INT = 0;\\n\\n-- Get total to process (for progress tracking)\\nSELECT @total_rows = COUNT(*) FROM [<source_table>];\\n\\nWHILE @processed < @total_rows\\nBEGIN\\n  SET @batch_num = @batch_num + 1;\\n\\n  INSERT INTO [<target_schema>].[<target_table>] (<columns>)\\n  SELECT TOP (@batch_size) <columns>\\n  FROM [<source_table>]\\n  WHERE <row_identifier> NOT IN (SELECT <row_identifier> FROM [<target_table>])\\n  ORDER BY <row_identifier>;\\n\\n  SET @processed = @processed + @@ROWCOUNT;\\n\\n  -- Log progress\\n  RAISERROR('Batch %d complete. Processed %d of %d rows (%.1f%%)',\\n    0, 1, @batch_num, @processed, @total_rows,\\n    CAST(@processed * 100.0 / NULLIF(@total_rows, 0) AS decimal(5,1)))\\n  WITH NOWAIT;\\n\\n  -- Throttle: pause between batches to reduce I/O pressure\\n  WAITFOR DELAY '00:00:02';\\n\\n  -- Commit is implicit per batch\\nEND;\\n\\nPRINT 'Load complete. Total rows: ' + CAST(@processed AS varchar(20));", "parameters": {"batch_size": "Rows per commit — 10,000 to 50,000 recommended", "throttle_delay": "Pause between batches — '00:00:01' to '00:00:05' depending on system load"}, "description": "Replaces the single large transaction with a loop of small committed batches. Each batch independently commits, allowing log space reuse and giving the DBA visibility into progress. The WAITFOR DELAY throttles I/O pressure between batches."}	{"sql": "-- Each batch is individually committed, so partial completion is easy to resume\\n-- Query the target table count vs source table count to determine restart point\\nSELECT\\n  (SELECT COUNT(*) FROM [<source_table>]) AS source_rows,\\n  (SELECT COUNT(*) FROM [<target_table>]) AS target_rows,\\n  (SELECT COUNT(*) FROM [<source_table>]) - (SELECT COUNT(*) FROM [<target_table>]) AS remaining;", "description": "Because each batch is committed separately, the operation can be resumed from where it stopped without re-processing already-loaded rows."}	low	t	t	\N	2026-02-24 13:10:27.332055
1979	sqlserver	execute	Rebuild indexes using SORT_IN_TEMPDB and ONLINE where available	{"sql": "-- Rebuild specific index using SORT_IN_TEMPDB to isolate sort space\\nALTER INDEX index_name ON schema_name.table_name\\nREBUILD WITH (\\n  SORT_IN_TEMPDB = ON,\\n  ONLINE = ON,        -- Enterprise Edition only\\n  FILLFACTOR = 80,\\n  MAXDOP = 4\\n);\\n\\n-- For all indexes on a table (use during scheduled maintenance window):\\nALTER INDEX ALL ON schema_name.table_name\\nREBUILD WITH (\\n  SORT_IN_TEMPDB = ON,\\n  ONLINE = ON,\\n  FILLFACTOR = 80,\\n  MAXDOP = 4\\n);", "parameters": {"maxdop": 4, "online": true, "fillfactor": 80, "sort_in_tempdb": true}, "description": "Rebuild fragmented indexes with SORT_IN_TEMPDB=ON to use tempdb for sort runs instead of the database data file, preventing unexpected data file growth."}	null	low	f	t	02:00:00	2026-02-24 13:10:27.332724
1955	sqlserver	instruct	Define and document the data retention policy for the largest tables	{"sql": "-- Identify candidate tables with their oldest and newest records\\n-- Run this in the context of each large database\\nSELECT\\n  OBJECT_SCHEMA_NAME(t.object_id) + '.' + t.name AS table_name,\\n  SUM(ps.row_count) AS total_rows,\\n  SUM(ps.used_page_count) * 8.0 / 1024 AS used_mb,\\n  -- Look for date-like column names that could drive archival\\n  STUFF((\\n    SELECT ', ' + c.name + ' (' + tp.name + ')'\\n    FROM sys.columns c\\n    JOIN sys.types tp ON c.user_type_id = tp.user_type_id\\n    WHERE c.object_id = t.object_id\\n      AND (c.name LIKE '%date%' OR c.name LIKE '%time%' OR c.name LIKE '%created%' OR c.name LIKE '%modified%')\\n      AND tp.name IN ('datetime', 'datetime2', 'date', 'smalldatetime')\\n    FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, '') AS date_columns\\nFROM sys.tables t\\nJOIN sys.dm_db_partition_stats ps ON t.object_id = ps.object_id AND ps.index_id IN (0,1)\\nGROUP BY t.object_id, t.name\\nHAVING SUM(ps.row_count) > 500000\\nORDER BY used_mb DESC;", "parameters": {}, "description": "Identifies which tables are candidates for archival and what date columns exist to drive retention policy. Document: online retention period, archive retention period, and purge eligibility for each table."}	null	low	f	t	00:30:00	2026-02-24 13:10:27.332728
1974	sqlserver	verify	Confirm spill reduction in tempdb and query execution	{"sql": "-- Check for remaining active spills\\nSELECT t.session_id,\\n  (t.internal_objects_alloc_page_count - t.internal_objects_dealloc_page_count) * 8 / 1024 AS current_spill_mb,\\n  r.command, r.wait_type\\nFROM sys.dm_db_task_space_usage t\\nJOIN sys.dm_exec_requests r ON t.session_id = r.session_id AND t.request_id = r.request_id\\nWHERE (t.internal_objects_alloc_page_count - t.internal_objects_dealloc_page_count) > 0\\nORDER BY current_spill_mb DESC;\\n\\n-- Check query stats for spill counts on recently executed queries\\nSELECT TOP 20\\n  qs.execution_count,\\n  qs.total_spills, qs.last_spills,\\n  SUBSTRING(st.text, 1, 200) AS query_snippet\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.last_spills > 0\\nORDER BY qs.total_spills DESC;", "parameters": {}, "description": "Verify that tempdb spill activity has decreased for targeted queries. Confirm no new spills from other sessions."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.336761
1957	sqlserver	configure	Schedule automated archival job and monitor primary table size reduction	{"sql": "-- Create a SQL Agent job to run archival weekly\\nUSE msdb;\\nEXEC sp_add_job @job_name = 'Weekly Data Archival - <DatabaseName>';\\nEXEC sp_add_jobstep\\n  @job_name = 'Weekly Data Archival - <DatabaseName>',\\n  @step_name = 'Archive records older than 2 years',\\n  @database_name = '<DatabaseName>',\\n  @command = N'EXEC [dbo].[usp_ArchiveOldData]\\n    @cutoff_date = DATEADD(year, -2, GETDATE()),\\n    @batch_size = 10000;';\\nEXEC sp_add_schedule\\n  @schedule_name = 'Weekly Sunday 1AM',\\n  @freq_type = 8,\\n  @freq_interval = 1,\\n  @active_start_time = 010000;\\nEXEC sp_attach_schedule\\n  @job_name = 'Weekly Data Archival - <DatabaseName>',\\n  @schedule_name = 'Weekly Sunday 1AM';\\nEXEC sp_add_jobserver\\n  @job_name = 'Weekly Data Archival - <DatabaseName>';\\n\\n-- After job runs, verify size reduction\\nSELECT\\n  OBJECT_SCHEMA_NAME(ps.object_id) + '.' + OBJECT_NAME(ps.object_id) AS table_name,\\n  SUM(ps.row_count) AS current_rows,\\n  SUM(ps.used_page_count) * 8.0 / 1024 AS current_used_mb\\nFROM sys.dm_db_partition_stats ps\\nWHERE OBJECT_NAME(ps.object_id) = '<table_name>'\\n  AND ps.index_id IN (0, 1)\\nGROUP BY ps.object_id;", "parameters": {"retention_years": "Online retention period — typically 1-3 years for operational data"}, "description": "Schedules the archival procedure to run automatically and provides verification queries to confirm primary table size is stabilizing."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = 'Weekly Data Archival - <DatabaseName>';", "description": "Disable or remove the job if the schedule needs adjustment."}	low	t	t	00:15:00	2026-02-24 13:10:27.333515
