1961	sqlserver	configure	Configure CDC cleanup retention and run immediate cleanup	{"sql": "-- Check current CDC cleanup settings\\nSELECT\\n  db.name AS database_name,\\n  cdc_enabled,\\n  retention_period,\\n  retention_period_units_desc\\nFROM sys.databases db\\nLEFT JOIN cdc.change_tables ct ON 1=1\\nWHERE cdc_enabled = 1;\\n\\n-- Configure CDC retention (in minutes — example: 3 days = 4320 minutes)\\n-- Run in each CDC-enabled database\\nEXEC sys.sp_cdc_change_job\\n  @job_type = 'cleanup',\\n  @retention = 4320;  -- 3 days in minutes; adjust to your retention policy\\n\\n-- Run CDC cleanup immediately (instead of waiting for the next scheduled run)\\nEXEC sys.sp_cdc_cleanup_change_table\\n  @capture_instance = 'all',\\n  @low_water_mark = NULL,\\n  @threshold = 5000;\\n\\n-- Verify CDC change table sizes after cleanup\\nSELECT\\n  ct.capture_instance,\\n  OBJECT_SCHEMA_NAME(ct.object_id) + '.' + OBJECT_NAME(ct.object_id) AS change_table,\\n  ps.row_count,\\n  SUM(ps.used_page_count) * 8.0 / 1024 AS used_mb\\nFROM cdc.change_tables ct\\nJOIN sys.dm_db_partition_stats ps ON ct.object_id = ps.object_id AND ps.index_id IN (0,1)\\nGROUP BY ct.capture_instance, ct.object_id, ps.row_count\\nORDER BY used_mb DESC;", "parameters": {"retention_minutes": "Retention in minutes — 4320 = 3 days, 10080 = 7 days, 43200 = 30 days"}, "description": "Adjusts the CDC cleanup job retention period and runs an immediate cleanup pass. The default SQL Server CDC retention is often too long (3 days is typical for most OLTP workloads; adjust to your requirements)."}	{"sql": "-- Increase retention if CDC consumers need more history\\nEXEC sys.sp_cdc_change_job @job_type = 'cleanup', @retention = <previous_retention>;", "description": "Restore previous retention setting if downstream CDC consumers require more history than the new retention window."}	medium	t	f	\N	2026-02-24 13:10:27.33408
1962	sqlserver	configure	Configure temporal table history retention using TEMPORAL_HISTORY_RETENTION	{"sql": "-- Enable temporal retention in the database (SQL Server 2016 SP1+)\\nALTER DATABASE [<db_name>]\\n  SET TEMPORAL_HISTORY_RETENTION ON;\\n\\n-- Set per-table retention period on each temporal table\\n-- Example: retain 1 year of history\\nALTER TABLE [<schema>].[<temporal_table>]\\n  SET (SYSTEM_VERSIONING = ON (\\n    HISTORY_RETENTION_PERIOD = 1 YEAR\\n  ));\\n\\n-- Verify retention settings\\nSELECT\\n  t.name AS table_name,\\n  t.temporal_type_desc,\\n  t.history_retention_period,\\n  t.history_retention_period_unit_desc,\\n  OBJECT_SCHEMA_NAME(t.history_table_id) + '.' + OBJECT_NAME(t.history_table_id) AS history_table\\nFROM sys.tables t\\nWHERE t.temporal_type = 2  -- SYSTEM_VERSIONED_TEMPORAL_TABLE\\nORDER BY t.name;\\n\\n-- History cleanup runs as a background task; check cleanup progress\\nSELECT * FROM sys.dm_db_temporal_history_cleanup;", "parameters": {"db_name": "Database containing temporal tables", "retention_unit": "DAY, WEEK, MONTH, or YEAR", "retention_period": "Number value for retention"}, "description": "Enables the built-in temporal history retention cleanup feature and sets appropriate retention periods per table. The cleanup agent runs automatically in the background once retention is configured."}	{"sql": "-- Remove retention period (unlimited history)\\nALTER TABLE [<schema>].[<temporal_table>]\\n  SET (SYSTEM_VERSIONING = ON (\\n    HISTORY_RETENTION_PERIOD = INFINITE\\n  ));", "description": "Set retention back to INFINITE if the retention window needs re-evaluation."}	low	t	t	\N	2026-02-24 13:10:27.334081
1969	sqlserver	execute	Reclaim free space and optionally rebuild LOB indexes	{"sql": "-- Reclaim freed pages from LOB segment\\nALTER INDEX ALL ON dbo.table_name REBUILD WITH (ONLINE = ON, DATA_COMPRESSION = ROW);\\n\\n-- If ONLINE rebuild not available (Enterprise required), use OFFLINE:\\n-- ALTER INDEX ALL ON dbo.table_name REBUILD WITH (DATA_COMPRESSION = ROW);", "parameters": {"online": true, "compression": "ROW"}, "description": "Rebuild indexes to compact LOB allocation units and optionally apply ROW compression to reduce in-row and overflow data. PAGE compression is not applied to LOB segments directly."}	{"sql": "ALTER INDEX ALL ON dbo.table_name REBUILD WITH (DATA_COMPRESSION = NONE);", "description": "Remove compression if application compatibility issues are found after rebuild."}	medium	t	t	01:00:00	2026-02-24 13:10:27.334763
1963	sqlserver	execute	Implement batched purge for custom audit and log tables without built-in retention	{"sql": "-- For custom audit/log tables without built-in retention, create a purge procedure\\n-- Run in the context of the database containing the audit table\\nCREATE OR ALTER PROCEDURE [dbo].[usp_PurgeAuditTable]\\n  @table_schema sysname,\\n  @table_name sysname,\\n  @date_column sysname,\\n  @retention_days INT,\\n  @batch_size INT = 10000\\nAS\\nBEGIN\\n  SET NOCOUNT ON;\\n  DECLARE @cutoff_date datetime2 = DATEADD(day, -@retention_days, GETDATE());\\n  DECLARE @rows_deleted INT = 1;\\n  DECLARE @total_deleted INT = 0;\\n  DECLARE @sql nvarchar(max);\\n\\n  WHILE @rows_deleted > 0\\n  BEGIN\\n    SET @sql = N'DELETE TOP (' + CAST(@batch_size AS nvarchar(10)) + N')\\n      FROM [' + @table_schema + N'].[' + @table_name + N']\\n      WHERE [' + @date_column + N'] < @cutoff';\\n\\n    EXEC sp_executesql @sql, N'@cutoff datetime2', @cutoff = @cutoff_date;\\n    SET @rows_deleted = @@ROWCOUNT;\\n    SET @total_deleted = @total_deleted + @rows_deleted;\\n\\n    WAITFOR DELAY '00:00:01';\\n  END;\\n\\n  RAISERROR('Purged %d rows from [%s].[%s] older than %d days',\\n    0, 1, @total_deleted, @table_schema, @table_name, @retention_days) WITH NOWAIT;\\nEND;\\n\\n-- Schedule via SQL Agent (example: daily at 3 AM)\\n-- EXEC [dbo].[usp_PurgeAuditTable]\\n--   @table_schema = 'dbo',\\n--   @table_name = 'AuditLog',\\n--   @date_column = 'created_at',\\n--   @retention_days = 90,\\n--   @batch_size = 10000;", "parameters": {"batch_size": "Rows per commit — 5,000 to 25,000", "retention_days": "Days of data to retain — typically 30-365 depending on compliance requirements"}, "description": "Generic parameterized purge procedure for any table with a date column. Uses batched deletes to avoid long-running transactions. Schedule via SQL Agent to run nightly."}	null	medium	t	f	\N	2026-02-24 13:10:27.335266
1964	sqlserver	execute	Clear ad-hoc single-use plans from the plan cache to recover memory	{"sql": "-- Quantify ad-hoc plan cache waste before clearing\\nSELECT\\n  objtype,\\n  COUNT(*) AS plan_count,\\n  SUM(size_in_bytes) / 1048576.0 AS cache_mb,\\n  AVG(usecounts) AS avg_use_count,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY cache_mb DESC;\\n\\n-- Remove only single-use ad-hoc plans (less aggressive than DBCC FREESYSTEMCACHE)\\nDBCC FREESYSTEMCACHE('SQL Plans') WITH MARK_IN_USE_FOR_REMOVAL;\\n\\n-- Alternative: flush entire plan cache (only if memory pressure is critical)\\n-- DBCC FREEPROCCACHE;  -- WARNING: causes plan recompilation storm on busy servers\\n\\n-- Verify reduction\\nSELECT objtype, COUNT(*) AS remaining_plans,\\n  SUM(size_in_bytes) / 1048576.0 AS remaining_mb\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY remaining_mb DESC;", "parameters": {}, "description": "Frees memory held by single-use ad-hoc plans. Uses the more targeted FREESYSTEMCACHE rather than FREEPROCCACHE to minimize performance impact from plan recompilation."}	null	medium	t	f	\N	2026-02-24 13:10:27.335269
4995	sqlserver	verify	Confirm assemblies are restricted to SAFE	{"sql": "SELECT a.name, a.permission_set_desc\\nFROM sys.assemblies a\\nWHERE a.is_user_defined = 1 AND a.permission_set_desc IN ('EXTERNAL_ACCESS', 'UNSAFE_ACCESS');\\n\\nSELECT CAST(value_in_use AS INT) AS strict_security\\nFROM sys.configurations WHERE name = 'clr strict security';", "parameters": [], "description": "Confirms no elevated assemblies remain and strict security is enabled."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801067
1965	sqlserver	configure	Enable Optimize for Ad-hoc Workloads and consider PARAMETERIZATION FORCED	{"sql": "-- Enable 'optimize for ad hoc workloads' to only cache full plans after second execution\\nEXEC sp_configure 'optimize for ad hoc workloads', 1;\\nRECONFIGURE;\\n\\n-- For databases with many ad-hoc queries, consider PARAMETERIZATION FORCED\\n-- This causes SQL Server to auto-parameterize most queries\\n-- CAUTION: test in non-production first — can affect some query plans negatively\\n-- ALTER DATABASE [<db_name>] SET PARAMETERIZATION FORCED;\\n\\n-- As a safer alternative, enable the database-level option only:\\nALTER DATABASE [<db_name>] SET PARAMETERIZATION SIMPLE;  -- Default; ensure it's not FORCED unintentionally\\n\\n-- Verify configuration\\nSELECT name, value_in_use FROM sys.configurations\\nWHERE name IN ('optimize for ad hoc workloads', 'max server memory (MB)');\\n\\nSELECT name, is_parameterization_forced\\nFROM sys.databases\\nWHERE database_id > 4;", "parameters": {"db_name": "Target database for PARAMETERIZATION setting"}, "description": "Enables 'optimize for ad hoc workloads' which stores only a stub on first execution, dramatically reducing plan cache memory for single-use queries without affecting reuse of repeated queries. PARAMETERIZATION FORCED is more aggressive and should be tested carefully."}	{"sql": "EXEC sp_configure 'optimize for ad hoc workloads', 0;\\nRECONFIGURE;\\nALTER DATABASE [<db_name>] SET PARAMETERIZATION SIMPLE;", "description": "Disable 'optimize for ad hoc workloads' and revert parameterization if query plan quality degrades."}	low	t	t	\N	2026-02-24 13:10:27.33527
2108	sqlserver	execute	Collect all SQL Server file paths for AV exclusion list	{"sql": "-- Get all data and log file paths\\nSELECT d.name AS database_name,\\n  mf.type_desc,\\n  mf.physical_name,\\n  mf.size * 8 / 1024 AS size_mb\\nFROM sys.master_files mf\\nJOIN sys.databases d ON mf.database_id = d.database_id\\nORDER BY d.name, mf.type_desc;\\n\\n-- Also get SQL Server binary and temp directories\\nSELECT\\n  SERVERPROPERTY('InstanceDefaultDataPath') AS default_data_path,\\n  SERVERPROPERTY('InstanceDefaultLogPath') AS default_log_path,\\n  SERVERPROPERTY('ErrorLogFileName') AS error_log_path;", "parameters": {}, "description": "Enumerate all database file paths to build a complete AV exclusion list. Include data files (.mdf, .ndf), log files (.ldf), backup paths, and the SQL Server binary directory."}	null	low	f	t	\N	2026-02-24 13:10:27.351078
1966	sqlserver	configure	Right-size Query Store and configure size-based cleanup and stale query purge	{"sql": "-- Configure Query Store for each database where it is enabled and oversized\\n-- Review current settings first\\nSELECT\\n  DB_NAME() AS db_name,\\n  desired_state_desc,\\n  actual_state_desc,\\n  current_storage_size_mb,\\n  max_storage_size_mb,\\n  stale_query_threshold_days,\\n  size_based_cleanup_mode_desc,\\n  query_capture_mode_desc\\nFROM sys.database_query_store_options;\\n\\n-- Reconfigure Query Store with appropriate limits\\nALTER DATABASE [<db_name>]\\nSET QUERY_STORE (\\n  MAX_STORAGE_SIZE_MB = 1024,          -- Reduce from default 1 GB if oversized; adjust per workload\\n  STALE_QUERY_THRESHOLD_DAYS = 30,     -- Remove queries not executed in 30 days\\n  SIZE_BASED_CLEANUP_MODE = AUTO,      -- Allow auto-cleanup when approaching max size\\n  QUERY_CAPTURE_MODE = AUTO,           -- Only capture statistically significant queries (SQL 2019+)\\n  DATA_FLUSH_INTERVAL_SECONDS = 900,   -- Flush to disk every 15 min (default)\\n  INTERVAL_LENGTH_MINUTES = 60         -- Aggregation interval\\n);\\n\\n-- Run manual cleanup to purge stale data immediately\\nEXEC sp_query_store_flush_db;  -- Flush pending in-memory data\\nEXEC sp_query_store_remove_stale_plan;\\n\\n-- Verify new size after cleanup\\nSELECT current_storage_size_mb, max_storage_size_mb,\\n  CAST(current_storage_size_mb * 100.0 / max_storage_size_mb AS decimal(5,1)) AS pct_used\\nFROM sys.database_query_store_options;", "parameters": {"db_name": "Database with Query Store enabled", "max_storage_size_mb": "1024 MB for most databases; increase to 2048-4096 for high-throughput OLTP systems", "stale_query_threshold_days": "Typically 30-90 days; shorter for high-churn workloads"}, "description": "Configures Query Store with a bounded max size, automatic size-based cleanup, and a stale query threshold. Also runs an immediate cleanup to purge old data. These settings prevent Query Store from growing unbounded and triggering automatic READ_ONLY mode."}	{"sql": "-- Restore previous Query Store settings\\nALTER DATABASE [<db_name>]\\nSET QUERY_STORE (\\n  MAX_STORAGE_SIZE_MB = <previous_max>,\\n  STALE_QUERY_THRESHOLD_DAYS = <previous_threshold>,\\n  SIZE_BASED_CLEANUP_MODE = <previous_mode>\\n);", "description": "Restore prior Query Store configuration if the new settings prematurely evict query plans needed for performance analysis."}	low	f	t	\N	2026-02-24 13:10:27.335271
1967	sqlserver	verify	Quantify LOB growth and identify archival candidates	{"sql": "SELECT OBJECT_SCHEMA_NAME(p.object_id) AS schema_name,\\n  OBJECT_NAME(p.object_id) AS table_name,\\n  p.rows,\\n  au.total_pages * 8 / 1024 AS lob_total_mb,\\n  au.used_pages * 8 / 1024 AS lob_used_mb,\\n  (au.total_pages - au.used_pages) * 8 / 1024 AS lob_free_mb\\nFROM sys.allocation_units au\\nJOIN sys.partitions p ON au.container_id = p.hobt_id\\nWHERE au.type_desc = 'LOB_DATA'\\n  AND au.total_pages > 1000\\nORDER BY au.total_pages DESC;", "parameters": {}, "description": "Confirm which tables hold the most LOB data and calculate free space within LOB segments to understand actual vs allocated usage."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.336754
1972	sqlserver	configure	Adjust max server memory to allow larger query memory grants	{"sql": "-- Check current max server memory\\nSELECT name, value_in_use\\nFROM sys.configurations\\nWHERE name = 'max server memory (MB)';\\n\\n-- Increase max server memory (reserve at least 10% or 4GB for OS)\\n-- Example: set to 80% of physical RAM\\nEXEC sp_configure 'show advanced options', 1; RECONFIGURE;\\nEXEC sp_configure 'max server memory (MB)', 49152; -- adjust for your server\\nRECONFIGURE WITH OVERRIDE;", "parameters": {"recommended_formula": "Physical RAM * 0.80, minimum OS reservation of 4GB or 10% whichever is greater"}, "description": "If max server memory is set too low, queries cannot receive adequate memory grants. Increase it while preserving headroom for the OS and other services."}	{"sql": "EXEC sp_configure 'max server memory (MB)', <previous_value>; RECONFIGURE WITH OVERRIDE;", "description": "Restore previous max server memory value if memory pressure on OS is observed."}	medium	t	t	00:05:00	2026-02-24 13:10:27.336759
1973	sqlserver	execute	Apply OPTION (MIN_GRANT_PERCENT) hint to chronic spilling queries	{"sql": "-- For identified chronic spilling queries, add a query hint to force a larger minimum memory grant\\n-- Example: force 10% of total server memory as minimum grant\\nSELECT col1, col2\\nFROM large_table\\nORDER BY col1\\nOPTION (MIN_GRANT_PERCENT = 10);\\n\\n-- Alternatively use a plan guide for queries that cannot be modified:\\nEXEC sp_create_plan_guide\\n  @name = N'PG_FixSpill_Query1',\\n  @stmt = N'<original query text>',\\n  @type = N'SQL',\\n  @hints = N'OPTION (MIN_GRANT_PERCENT = 10)';", "parameters": {"min_grant_percent": "5-25 depending on query complexity and available memory"}, "description": "For queries that still spill after statistics update, force a larger memory grant using the MIN_GRANT_PERCENT hint or a plan guide for queries in application code."}	{"sql": "-- Remove plan guide if applied\\nEXEC sp_control_plan_guide N'DROP', N'PG_FixSpill_Query1';", "description": "Drop the plan guide to restore default optimizer behavior."}	low	f	t	00:10:00	2026-02-24 13:10:27.33676
2060	sqlserver	verify	Confirm tempdb worktable allocations have decreased after refactoring	{"sql": "SELECT su.session_id, SUM(su.user_objects_alloc_page_count) * 8 / 1024 AS user_alloc_mb, SUM(su.internal_objects_alloc_page_count) * 8 / 1024 AS internal_alloc_mb FROM sys.dm_db_session_space_usage su WHERE su.session_id IN (SELECT DISTINCT session_id FROM sys.dm_exec_cursors(0) WHERE is_open = 1) GROUP BY su.session_id HAVING SUM(su.user_objects_alloc_page_count) + SUM(su.internal_objects_alloc_page_count) > 128 ORDER BY user_alloc_mb DESC;", "parameters": {}, "description": "Re-run detection queries to confirm cursor count and tempdb allocation from cursor sessions has dropped. Expect zero or near-zero results if cursors were eliminated."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.346004
1980	sqlserver	verify	Confirm index fragmentation reduced and no unexpected file growth	{"sql": "-- Verify fragmentation is resolved\\nSELECT OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 10\\n  AND ips.page_count > 1000\\nORDER BY ips.avg_fragmentation_in_percent DESC;\\n\\n-- Check for any auto-growth events during the maintenance window\\nDECLARE @tracefile nvarchar(260);\\nSELECT @tracefile = path FROM sys.traces WHERE is_default = 1;\\nSELECT DB_NAME(DatabaseID), FileName, COUNT(*) AS growth_events\\nFROM sys.fn_trace_gettable(@tracefile, DEFAULT)\\nWHERE EventClass IN (92, 93)\\n  AND StartTime > DATEADD(hour, -4, GETDATE())\\nGROUP BY DatabaseID, FileName;", "parameters": {}, "description": "Verify that fragmentation levels have dropped below the 10-30% threshold and that no unexpected auto-growth events occurred during the rebuild."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.336765
1981	sqlserver	verify	Diagnose the root cause of purge job failure	{"sql": "-- Get the last 10 runs of the failing job including step-level detail\\nSELECT j.name AS job_name,\\n  jh.step_id, jh.step_name,\\n  jh.run_status,\\n  jh.run_date, jh.run_time,\\n  jh.run_duration,\\n  jh.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory jh ON j.job_id = jh.job_id\\nWHERE (j.name LIKE '%purge%' OR j.name LIKE '%cleanup%'\\n    OR j.name LIKE '%archive%' OR j.name LIKE '%retention%')\\n  AND jh.run_date >= CONVERT(INT, CONVERT(VARCHAR(8), DATEADD(day, -30, GETDATE()), 112))\\nORDER BY jh.run_date DESC, jh.run_time DESC, jh.step_id;", "parameters": {}, "description": "Review job history at the step level to identify the specific error message and step that is failing. Common causes: permissions, object not found, timeout, deadlock."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.336766
1983	sqlserver	configure	Add SQL Agent alert for job failure notification	{"sql": "-- Create operator for alert notification (skip if operator already exists)\\nEXEC msdb.dbo.sp_add_operator\\n  @name = N'DBA Team',\\n  @email_address = N'dba-team@company.com';\\n\\n-- Add failure notification to the purge job\\nEXEC msdb.dbo.sp_update_job\\n  @job_name = N'YourPurgeJobName',\\n  @notify_level_email = 2,   -- notify on failure\\n  @notify_email_operator_name = N'DBA Team';\\n\\n-- Optionally enable the job if it was disabled\\nEXEC msdb.dbo.sp_update_job\\n  @job_name = N'YourPurgeJobName',\\n  @enabled = 1;", "parameters": {"operator_email": "dba-team@company.com", "notify_level_email": 2}, "description": "Configure the SQL Agent job to send an email alert on failure so the DBA team is notified immediately rather than discovering the failure days later via storage alerts."}	{"sql": "EXEC msdb.dbo.sp_update_job @job_name = N'YourPurgeJobName', @notify_level_email = 0;", "description": "Remove email notification if it causes alert fatigue."}	low	f	t	00:10:00	2026-02-24 13:10:27.336767
1984	sqlserver	verify	Identify long-running snapshot transactions holding version store	{"sql": "-- Find sessions with active snapshot transactions and their age\\nSELECT\\n  at.session_id,\\n  at.transaction_begin_time,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS age_minutes,\\n  DB_NAME(at.database_id) AS database_name,\\n  es.login_name, es.host_name, es.program_name,\\n  es.status,\\n  er.command, er.wait_type,\\n  SUBSTRING(st.text, 1, 200) AS query_snippet\\nFROM sys.dm_tran_active_snapshot_database_transactions at\\nJOIN sys.dm_exec_sessions es ON at.session_id = es.session_id\\nLEFT JOIN sys.dm_exec_requests er ON at.session_id = er.session_id\\nOUTER APPLY sys.dm_exec_sql_text(er.sql_handle) st\\nORDER BY at.transaction_begin_time;", "parameters": {}, "description": "Identify the oldest snapshot transactions that are preventing version store cleanup. These are the primary driver of tempdb version store growth."}	null	low	f	t	00:02:00	2026-02-24 13:10:27.336768
1993	sqlserver	verify	Assess current percentage growth impact and calculate fixed replacement	{"sql": "-- Show all files with percentage growth and calculate next growth event size\\nSELECT\\n  DB_NAME(database_id) AS database_name,\\n  name AS file_name,\\n  type_desc,\\n  size * 8 / 1024 AS current_size_mb,\\n  growth AS growth_pct,\\n  CAST(size * 8.0 / 1024 * growth / 100 AS DECIMAL(10,2)) AS next_growth_mb,\\n  CAST(size * 8.0 / 1024 * growth / 100 * 12 AS DECIMAL(10,2)) AS annual_growth_at_current_rate_mb\\nFROM sys.master_files\\nWHERE is_percent_growth = 1\\n  AND growth > 0\\nORDER BY next_growth_mb DESC;", "parameters": {}, "description": "Quantify the next expected growth event size and annual growth projection to determine appropriate fixed increment and whether pre-sizing is also needed."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.336774
1985	sqlserver	execute	Kill long-running idle snapshot transactions	{"sql": "-- Kill specific session(s) identified as holding the version store\\n-- Replace session_id with actual value from step 1\\nKILL 52;  -- example session_id\\n\\n-- To generate KILL statements for all snapshot sessions older than 60 minutes:\\nSELECT 'KILL ' + CAST(at.session_id AS VARCHAR) + ';'\\nFROM sys.dm_tran_active_snapshot_database_transactions at\\nJOIN sys.dm_exec_sessions es ON at.session_id = es.session_id\\nWHERE DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) > 60\\n  AND es.status = 'sleeping'\\nORDER BY at.transaction_begin_time;", "parameters": {}, "description": "Terminate the sessions holding long-running snapshot transactions. SQL Server's version store cleanup will reclaim the space within minutes after these sessions are killed."}	{"sql": "-- No rollback for KILL; the killed session's transaction is automatically rolled back by SQL Server", "description": "SQL Server automatically rolls back the killed session's uncommitted work. Application may need to retry its transaction."}	medium	t	f	00:02:00	2026-02-24 13:10:27.336769
1992	sqlserver	execute	Set growth increment to a reasonable fixed size	{"sql": "-- Set fixed growth increment (not percentage) as a safety net\\n-- Use 512MB-1024MB for large databases, 256MB for smaller databases\\nUSE [YourDatabase];\\n\\nALTER DATABASE [YourDatabase]\\nMODIFY FILE (\\n  NAME = N'YourLogicalFileName',\\n  FILEGROWTH = 512MB\\n);\\n\\nALTER DATABASE [YourDatabase]\\nMODIFY FILE (\\n  NAME = N'YourLogicalFileName_log',\\n  FILEGROWTH = 256MB\\n);", "parameters": {"log_filegrowth_mb": "256 for most workloads", "data_filegrowth_mb": "512 for databases > 10GB; 256 for databases < 10GB"}, "description": "Set a fixed, predictable growth increment as a safety net in case the pre-sized allocation is exhausted, replacing any percentage-based or very small fixed increments."}	{"sql": "-- Revert growth settings to previous values if needed\\nALTER DATABASE [YourDatabase] MODIFY FILE (NAME = N'YourLogicalFileName', FILEGROWTH = 10%);", "description": "Restore previous growth configuration if specific application requirements mandate percentage growth."}	low	f	t	00:02:00	2026-02-24 13:10:27.336769
1988	sqlserver	instruct	Refactor high-frequency temp table usage to table variables or CTEs	{"sql": "-- Identify queries creating the most temp tables\\nSELECT TOP 20\\n  qs.execution_count,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  SUBSTRING(st.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.text LIKE '%#%'   -- queries referencing temp tables\\nORDER BY qs.execution_count DESC;", "parameters": {}, "description": "Identify the most frequently executed queries that create temp tables. Review whether table variables or CTEs can replace the temp tables for small result sets (< ~10K rows) to eliminate catalog churn."}	null	low	f	t	02:00:00	2026-02-24 13:10:27.336771
1989	sqlserver	verify	Confirm temp object creation rate has decreased	{"sql": "-- Monitor temp table creation rate (snapshot twice, 60 seconds apart)\\nSELECT\\n  cntr_value AS temp_tables_creation_rate\\nFROM sys.dm_os_performance_counters\\nWHERE counter_name = 'Temp Tables Creation Rate'\\n  AND instance_name = '';\\n\\n-- Check current user temp objects\\nSELECT COUNT(*) AS user_temp_objects\\nFROM tempdb.sys.objects\\nWHERE is_ms_shipped = 0;\\n\\n-- Check tempdb allocation page waits\\nSELECT wait_type, waiting_tasks_count, wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_UP', 'PAGELATCH_EX', 'PAGEIOLATCH_UP')\\nORDER BY wait_time_ms DESC;", "parameters": {}, "description": "Verify that the temp table creation rate and PAGELATCH waits on tempdb have decreased after adding files and refactoring queries."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.336772
1990	sqlserver	verify	Calculate recommended file sizes based on growth history	{"sql": "-- Analyze auto-growth events over the past 30 days from default trace\\nDECLARE @tracefile nvarchar(260);\\nSELECT @tracefile = path FROM sys.traces WHERE is_default = 1;\\n\\nSELECT\\n  DB_NAME(e.DatabaseID) AS database_name,\\n  e.FileName,\\n  COUNT(*) AS growth_events_30d,\\n  SUM(e.IntegerData * 8.0 / 1024) AS total_growth_mb_30d,\\n  AVG(e.Duration / 1000) AS avg_growth_duration_ms,\\n  MAX(e.IntegerData * 8.0 / 1024) AS max_single_growth_mb\\nFROM sys.fn_trace_gettable(@tracefile, DEFAULT) e\\nWHERE e.EventClass IN (92, 93)\\n  AND e.StartTime > DATEADD(day, -30, GETDATE())\\nGROUP BY e.DatabaseID, e.FileName\\nORDER BY growth_events_30d DESC;\\n\\n-- Check current file sizes and free space\\nSELECT name, size * 8 / 1024 AS current_mb,\\n  FILEPROPERTY(name, 'SpaceUsed') * 8 / 1024 AS used_mb,\\n  (size - CAST(FILEPROPERTY(name, 'SpaceUsed') AS BIGINT)) * 8 / 1024 AS free_mb\\nFROM sys.database_files;", "parameters": {}, "description": "Calculate how much the database has grown over 30 days to determine the appropriate new pre-sized file target. Recommended target: current size + (30-day growth * 3) as a 90-day buffer."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.336773
1991	sqlserver	execute	Expand database files to pre-calculated target sizes	{"sql": "-- Pre-size data file to eliminate growth events\\n-- Replace YourDatabase, YourLogicalFileName, and target_size_mb with actual values\\nUSE [YourDatabase];\\n\\nALTER DATABASE [YourDatabase]\\nMODIFY FILE (\\n  NAME = N'YourLogicalFileName',\\n  SIZE = 20480MB   -- Set to current_used_mb + 90-day growth buffer\\n);\\n\\n-- Pre-size log file\\nALTER DATABASE [YourDatabase]\\nMODIFY FILE (\\n  NAME = N'YourLogicalFileName_log',\\n  SIZE = 4096MB    -- Set based on log usage pattern; typically 25-50% of data size\\n);", "parameters": {"log_size_guidance": "25-50% of data file size for most OLTP workloads", "target_size_calculation": "current_used_mb + (30d_growth_mb * 3) for 90-day buffer"}, "description": "Expand the data and log files to the pre-calculated target sizes in a single ALTER DATABASE operation to avoid multiple growth events."}	{"sql": "-- Files cannot be shrunk back to original size without risk of data corruption\\n-- Use DBCC SHRINKFILE only as last resort and rebuild indexes afterward\\n-- DBCC SHRINKFILE (N'YourLogicalFileName', target_size_mb);", "description": "File shrink is not recommended as it causes severe index fragmentation. Accept the larger allocation."}	low	f	f	00:30:00	2026-02-24 13:10:27.336773
