2014	sqlserver	configure	Create SQL Agent alerts for file-full and log-full error messages	{"sql": "USE [msdb];\\n-- Alert on error 1105: Could not allocate space (data file full)\\nEXEC sp_add_alert\\n  @name = N'Error 1105 - Data File Full',\\n  @message_id = 1105,\\n  @severity = 0,\\n  @enabled = 1,\\n  @delay_between_responses = 60,\\n  @notification_message = N'A data file is full. Immediate action required to prevent write failures.',\\n  @job_name = NULL;\\nEXEC sp_add_notification\\n  @alert_name = N'Error 1105 - Data File Full',\\n  @operator_name = N'<dba_operator_name>',\\n  @notification_method = 1;  -- email\\n\\n-- Alert on error 1101: Could not allocate space in filegroup\\nEXEC sp_add_alert\\n  @name = N'Error 1101 - Filegroup Full',\\n  @message_id = 1101,\\n  @severity = 0,\\n  @enabled = 1,\\n  @delay_between_responses = 60;\\nEXEC sp_add_notification\\n  @alert_name = N'Error 1101 - Filegroup Full',\\n  @operator_name = N'<dba_operator_name>',\\n  @notification_method = 1;\\n\\n-- Alert on error 9002: Transaction log full\\nEXEC sp_add_alert\\n  @name = N'Error 9002 - Log File Full',\\n  @message_id = 9002,\\n  @severity = 0,\\n  @enabled = 1,\\n  @delay_between_responses = 60;\\nEXEC sp_add_notification\\n  @alert_name = N'Error 9002 - Log File Full',\\n  @operator_name = N'<dba_operator_name>',\\n  @notification_method = 1;", "parameters": {"dba_operator_name": "Name of the SQL Agent operator to notify (must exist in msdb.dbo.sysoperators)"}, "description": "Creates SQL Agent alerts on the three critical file-space error messages. These fire when SQL Server has already failed to allocate space — they are last-resort alerts. The monitoring job in step 2 provides earlier warning."}	{"sql": "USE [msdb];\\nEXEC sp_delete_alert @name = N'Error 1105 - Data File Full';\\nEXEC sp_delete_alert @name = N'Error 1101 - Filegroup Full';\\nEXEC sp_delete_alert @name = N'Error 9002 - Log File Full';", "description": "Remove alerts if they generate false positives or are duplicated by an external monitoring system."}	low	f	t	\N	2026-02-24 13:10:27.339522
2015	sqlserver	configure	Create recurring job to report auto-growth events from default trace	{"sql": "USE [msdb];\\nEXEC sp_add_job\\n  @job_name = N'Auto-Growth Event Report',\\n  @enabled = 1,\\n  @description = N'Reports auto-growth events from the default trace and alerts if growth occurred in the last hour';\\n\\nEXEC sp_add_jobstep\\n  @job_name = N'Auto-Growth Event Report',\\n  @step_name = N'Check and report auto-growth',\\n  @database_name = N'master',\\n  @command = N'\\nDECLARE @body NVARCHAR(MAX);\\nDECLARE @count INT;\\n\\nSELECT @count = COUNT(*)\\nFROM sys.fn_trace_gettable(\\n  (SELECT REVERSE(SUBSTRING(REVERSE(path),\\n    CHARINDEX(CHAR(92), REVERSE(path)), 260)) + N''log.trc''\\n   FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name IN (''Data File Auto Grow'', ''Log File Auto Grow'')\\n  AND t.StartTime > DATEADD(hour, -1, GETDATE());\\n\\nIF @count > 0\\nBEGIN\\n  SELECT @body = CAST(@count AS NVARCHAR) + '' auto-growth events in last hour:'' + CHAR(13) +\\n    STRING_AGG(\\n      DB_NAME(t.DatabaseId) + '' | '' + t.FileName + '' | '' +\\n      CAST(t.IntegerData * 8 / 1024 AS NVARCHAR) + ''MB | '' +\\n      CAST(t.Duration / 1000 AS NVARCHAR) + ''ms'',\\n      CHAR(13))\\n  FROM sys.fn_trace_gettable(\\n    (SELECT REVERSE(SUBSTRING(REVERSE(path),\\n      CHARINDEX(CHAR(92), REVERSE(path)), 260)) + N''log.trc''\\n     FROM sys.traces WHERE is_default = 1), DEFAULT) t\\n  JOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\n  WHERE te.name IN (''Data File Auto Grow'', ''Log File Auto Grow'')\\n    AND t.StartTime > DATEADD(hour, -1, GETDATE());\\n\\n  EXEC msdb.dbo.sp_send_dbmail\\n    @profile_name = N''<mail_profile_name>'',\\n    @recipients = N''<dba_email>'',\\n    @subject = N''SQL Server Auto-Growth Alert'',\\n    @body = @body;\\nEND\\n';\\n\\nEXEC sp_add_schedule\\n  @schedule_name = N'Hourly',\\n  @freq_type = 4,\\n  @freq_interval = 1,\\n  @freq_subday_type = 8,\\n  @freq_subday_interval = 1;\\n\\nEXEC sp_attach_schedule\\n  @job_name = N'Auto-Growth Event Report',\\n  @schedule_name = N'Hourly';\\n\\nEXEC sp_add_jobserver\\n  @job_name = N'Auto-Growth Event Report';", "parameters": {"dba_email": "DBA team email address for notifications", "mail_profile_name": "Database Mail profile name (from sys.mail_profiles)"}, "description": "Creates an hourly SQL Agent job that scans the default trace for auto-growth events in the prior hour and emails the DBA team with a summary. This provides early warning before file space is exhausted."}	{"sql": "USE [msdb];\\nEXEC sp_delete_job @job_name = N'Auto-Growth Event Report';", "description": "Remove the monitoring job if it is replaced by a third-party monitoring solution."}	low	f	t	\N	2026-02-24 13:10:27.339523
