2783	sqlserver	configure	Enable Lock Pages in Memory to prevent buffer pool eviction	{"sql": "-- Lock Pages in Memory is a Windows privilege (not a T-SQL setting)\\n-- Grant via Local Security Policy: gpedit.msc > Computer Configuration >\\n-- Windows Settings > Security Settings > Local Policies > User Rights Assignment >\\n-- Lock pages in memory > Add SQL Server service account\\n\\n-- After granting the privilege and restarting SQL Server, verify it is active:\\nSELECT sql_memory_model_desc\\nFROM sys.dm_os_sys_info;\\n-- Expected: 'LOCK PAGES' when privilege is active\\n\\n-- Also enable via trace flag for older versions if needed:\\n-- DBCC TRACEON(845, -1);", "parameters": {"requirement": "SQL Server service account must be a Windows domain or local account (not NETWORK SERVICE) to receive the LPIM privilege", "restart_required": "Yes — privilege takes effect on next SQL Server service restart"}, "description": "Prevents Windows from paging SQL Server buffer pool pages to disk under system memory pressure by pinning them in physical RAM."}	{"sql": null, "description": "Revoke Lock Pages in Memory privilege via Local Security Policy and restart SQL Server service to revert."}	medium	t	t	00:15:00	2026-02-24 13:10:27.463953
2784	sqlserver	verify	Confirm page life expectancy and memory pressure resolution	{"sql": "-- Verify PLE is healthy (above 300 sec; above 1000 ideal for large servers)\\nSELECT\\n  cntr_value AS page_life_expectancy_sec\\nFROM sys.dm_os_performance_counters\\nWHERE counter_name = 'Page life expectancy'\\n  AND object_name LIKE '%Buffer Manager%';\\n\\n-- Verify OS memory state is no longer under pressure\\nSELECT\\n  total_physical_memory_kb / 1024 AS total_mb,\\n  available_physical_memory_kb / 1024 AS available_mb,\\n  system_memory_state_desc\\nFROM sys.dm_os_sys_memory;\\n\\n-- Verify no RESOURCE_SEMAPHORE waits accumulating\\nSELECT wait_type, waiting_tasks_count, wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('RESOURCE_SEMAPHORE', 'CMEMTHREAD', 'SOS_RESERVEDMEMBLOCKLIST')\\n  AND waiting_tasks_count > 0;", "parameters": {}, "description": "Confirms page life expectancy has recovered above 300 seconds, OS memory state is Normal, and memory-related waits have decreased significantly."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.463954
2785	sqlserver	execute	Rebuild or reorganize fragmented indexes based on fragmentation level	{"sql": "-- Rebuild indexes with fragmentation > 30% and > 1000 pages\\n-- (Generates REBUILD/REORGANIZE commands for manual review before execution)\\nDECLARE @sql NVARCHAR(MAX) = N'';\\n\\nSELECT @sql = @sql +\\n  CASE\\n    WHEN ips.avg_fragmentation_in_percent >= 30\\n    THEN N'ALTER INDEX ' + QUOTENAME(i.name) + N' ON ' +\\n         QUOTENAME(OBJECT_SCHEMA_NAME(ips.object_id)) + N'.' +\\n         QUOTENAME(OBJECT_NAME(ips.object_id)) +\\n         N' REBUILD WITH (ONLINE = ON, FILLFACTOR = 85, STATISTICS_NORECOMPUTE = OFF);' + CHAR(13)\\n    WHEN ips.avg_fragmentation_in_percent BETWEEN 10 AND 29\\n    THEN N'ALTER INDEX ' + QUOTENAME(i.name) + N' ON ' +\\n         QUOTENAME(OBJECT_SCHEMA_NAME(ips.object_id)) + N'.' +\\n         QUOTENAME(OBJECT_NAME(ips.object_id)) +\\n         N' REORGANIZE;' + CHAR(13)\\n    ELSE N''\\n  END\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 10\\n  AND ips.page_count > 1000\\n  AND i.index_id > 0\\n  AND OBJECTPROPERTY(ips.object_id, 'IsUserTable') = 1;\\n\\n-- Review @sql before executing:\\nPRINT @sql;\\n-- EXEC sp_executesql @sql;  -- Uncomment to execute", "parameters": {"online": "ON requires Enterprise Edition; use OFF on Standard Edition during off-hours", "fillfactor": "85 (leaves 15% free space per page to absorb future inserts without immediate page splits)"}, "description": "Generates and optionally executes REBUILD (>=30% fragmentation) or REORGANIZE (10-29%) commands for all qualifying indexes."}	null	medium	t	f	00:30:00	2026-02-24 13:10:27.463955
2786	sqlserver	configure	Schedule regular automated index maintenance	{"sql": "-- Create SQL Agent job for weekly index maintenance\\n-- (Simplified version; use Ola Hallengren's solution for production)\\nUSE msdb;\\n\\n-- Verify SQL Agent is running\\nSELECT name, enabled FROM sysjobs WHERE name = 'WeeklyIndexMaintenance';\\n\\n-- Key configuration: set FILLFACTOR in database default\\nEXEC sys.sp_configure 'fill factor (%)', 85;\\nRECONFIGURE;\\n\\n-- Alternatively, set per-index via ALTER INDEX REBUILD WITH (FILLFACTOR = 85)\\n-- For Ola Hallengren solution (recommended):\\n-- https://ola.hallengren.com/sql-server-index-and-statistics-maintenance.html\\n-- EXEC dbo.IndexOptimize\\n--   @Databases = 'USER_DATABASES',\\n--   @FragmentationLow = NULL,\\n--   @FragmentationMedium = 'INDEX_REORGANIZE',\\n--   @FragmentationHigh = 'INDEX_REBUILD_ONLINE,INDEX_REBUILD_OFFLINE',\\n--   @FragmentationLevel1 = 10,\\n--   @FragmentationLevel2 = 30,\\n--   @UpdateStatistics = 'ALL',\\n--   @OnlyModifiedStatistics = 'Y';", "parameters": {"schedule": "Weekly during off-peak hours; daily REORGANIZE pass for high-write tables", "fill_factor_pct": "85 for moderate insert workloads; 70-75 for high insert rate tables; 95-100 for read-only tables"}, "description": "Configures server-level fill factor and creates a scheduled maintenance job to prevent fragmentation from re-accumulating."}	{"sql": "EXEC sys.sp_configure 'fill factor (%)', 0;  -- 0 = 100%\\nRECONFIGURE;", "description": "Restores default fill factor (100%)."}	low	f	t	00:15:00	2026-02-24 13:10:27.463956
3683	sqlserver	verify	Verify background processes are not causing buffer pool pressure	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Checkpoint pages/sec') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Lazy writes/sec') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Free list stalls/sec') AS free_list_stalls_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Page life expectancy') AS ple;", "parameters": [], "description": "Confirms checkpoint activity is reduced, lazy writes are minimal, and free list stalls are zero."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.572369
2787	sqlserver	verify	Confirm fragmentation reduction and logical read improvement	{"sql": "-- Verify fragmentation levels have dropped below 10%\\nSELECT TOP 20\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.avg_page_space_used_in_percent\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 1000\\n  AND OBJECTPROPERTY(ips.object_id, 'IsUserTable') = 1\\nORDER BY ips.avg_fragmentation_in_percent DESC;\\n\\n-- Verify statistics were updated as part of rebuild\\nSELECT OBJECT_NAME(s.object_id) AS table_name, s.name, sp.last_updated\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE OBJECT_NAME(s.object_id) IN (SELECT DISTINCT OBJECT_NAME(object_id)\\n  FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED')\\n  WHERE page_count > 1000)\\nORDER BY sp.last_updated DESC;", "parameters": {}, "description": "Validates that fragmentation levels are below 10% on rebuilt indexes and statistics have been refreshed."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.463956
