2788	sqlserver	execute	Force ghost cleanup and verify no blocking transactions	{"sql": "-- Check for long-running transactions blocking ghost cleanup\\nSELECT TOP 5\\n  s.session_id,\\n  s.login_name,\\n  DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) AS age_sec,\\n  tat.name AS transaction_name\\nFROM sys.dm_tran_active_transactions tat\\nJOIN sys.dm_tran_session_transactions tst ON tat.transaction_id = tst.transaction_id\\nJOIN sys.dm_exec_sessions s ON tst.session_id = s.session_id\\nWHERE DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) > 300\\nORDER BY tat.transaction_begin_time;\\n\\n-- Force ghost cleanup (SQL Server 2016+ internal procedure)\\n-- This requests the ghost cleanup task to run immediately\\nEXEC sys.sp_execute_external_script -- Not applicable\\n-- Alternative: DBCC FORCEGHOSTCLEANUP (undocumented, use cautiously in dev/test)\\n-- Production approach: rebuild the affected index to force immediate ghost removal\\nALTER INDEX ALL ON dbo.HighGhostTable REBUILD WITH (ONLINE = ON);", "parameters": {"online": "ON requires Enterprise Edition; eliminates ghost records without blocking reads"}, "description": "Identifies blocking transactions that prevent ghost cleanup and forces immediate ghost record removal by rebuilding affected indexes."}	null	medium	t	f	01:00:00	2026-02-24 13:10:27.463957
2789	sqlserver	execute	Rebuild heaps with high forwarded record counts	{"sql": "-- Identify heaps (index_id = 0) with forwarded records\\nSELECT\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  ios.forwarded_fetch_count,\\n  p.rows\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.partitions p ON ios.object_id = p.object_id AND ios.index_id = p.index_id\\nWHERE ios.index_id = 0  -- heaps only\\n  AND ios.forwarded_fetch_count > 10000\\nORDER BY ios.forwarded_fetch_count DESC;\\n\\n-- Rebuild the heap to compact data and eliminate forward pointers\\n-- Replace 'HighForwardTable' with actual table name\\nALTER TABLE dbo.HighForwardTable REBUILD;\\n\\n-- After rebuild, verify forwarded_fetch_count resets\\nSELECT forwarded_fetch_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), OBJECT_ID('dbo.HighForwardTable'), 0, NULL)\\nWHERE index_id = 0;", "parameters": {}, "description": "Rebuilds heap tables to eliminate forward pointers created by row expansion (UPDATE adding bytes to a variable-length column that no longer fits on the original page)."}	null	medium	t	f	00:45:00	2026-02-24 13:10:27.463958
2790	sqlserver	instruct	Convert frequently-updated heaps to clustered tables to prevent recurrence	{"sql": null, "parameters": {"clustering_key": "Identity/sequence column preferred for INSERT-order locality and range scan efficiency", "online_rebuild": "Requires Enterprise Edition; Standard Edition requires offline conversion during maintenance window"}, "description": "For heap tables that consistently accumulate forwarded records due to UPDATE workloads expanding variable-length columns: add a clustered index on a monotonically increasing key (identity or sequence) to eliminate heap storage entirely. Forwarded records cannot exist in clustered tables. Steps: (1) Identify a suitable clustering key — usually the primary key or an identity column. (2) CREATE UNIQUE CLUSTERED INDEX CIX_TableName ON dbo.HighForwardTable (ID) WITH (ONLINE = ON) — this converts the heap to a B-tree clustered structure. (3) Drop the heap (implicit: once a clustered index exists, there is no heap). For tables that legitimately need heap storage (bulk insert targets), ensure FILLFACTOR is set low enough to absorb row growth without forwarding."}	null	medium	t	t	00:30:00	2026-02-24 13:10:27.463958
2791	sqlserver	verify	Confirm ghost records and forwarded records eliminated	{"sql": "SELECT\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.type_desc,\\n  ios.ghost_record_count,\\n  ios.forwarded_fetch_count,\\n  p.rows\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.partitions p ON ios.object_id = p.object_id AND ios.index_id = p.index_id\\nWHERE OBJECTPROPERTY(ios.object_id, 'IsUserTable') = 1\\n  AND (ios.ghost_record_count > 100 OR ios.forwarded_fetch_count > 1000)\\nORDER BY ios.ghost_record_count + ios.forwarded_fetch_count DESC;", "parameters": {}, "description": "Validates that ghost record and forwarded record counts on previously affected tables are now near zero."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.463959
2792	sqlserver	configure	Configure indirect checkpoint with appropriate target recovery time	{"sql": "-- SQL Server 2016+ default: indirect checkpoint with 60-second target\\n-- Older databases may use legacy automatic checkpoint (recovery interval in minutes)\\n\\n-- Check current per-database settings\\nSELECT name, target_recovery_time_in_seconds, recovery_model_desc\\nFROM sys.databases\\nWHERE database_id > 4;\\n\\n-- Set indirect checkpoint on databases still using legacy automatic checkpoint\\n-- (target_recovery_time_in_seconds = 0 means legacy mode)\\nDECLARE @db NVARCHAR(128) = N'YourDatabase';\\nDECLARE @sql NVARCHAR(512) = N'ALTER DATABASE ' + QUOTENAME(@db) +\\n  N' SET TARGET_RECOVERY_TIME = 60 SECONDS;';\\nEXEC sp_executesql @sql;\\n\\n-- Increase target recovery time to smooth checkpoint I/O if spikes are excessive\\n-- ALTER DATABASE [YourDatabase] SET TARGET_RECOVERY_TIME = 120 SECONDS;\\n\\n-- Verify change\\nSELECT name, target_recovery_time_in_seconds FROM sys.databases WHERE database_id > 4;", "parameters": {"trade_off": "Longer recovery time means more dirty pages at any given time; recovery after crash takes longer", "target_recovery_time_seconds": "60 (SQL Server 2016+ default); increase to 120-300 if checkpoint I/O spikes persist"}, "description": "Switches databases from legacy automatic checkpoint (trigger-based, bursty) to indirect checkpoint (continuous, smooth) which distributes dirty page flushing evenly."}	{"sql": "ALTER DATABASE [YourDatabase] SET TARGET_RECOVERY_TIME = 0;  -- Reverts to legacy automatic checkpoint", "description": "Reverts to legacy automatic checkpoint mode."}	low	f	t	00:05:00	2026-02-24 13:10:27.46396
5129	sqlserver	verify	Check Database Mail and Service Broker encryption settings	{"sql": "SELECT a.name AS account_name, s.servername, s.port, s.enable_ssl\\nFROM msdb.dbo.sysmail_account a\\nJOIN msdb.dbo.sysmail_server s ON a.account_id = s.account_id\\nWHERE s.enable_ssl = 0;\\n\\nSELECT name, encryption_algorithm_desc, is_encryption_enabled\\nFROM sys.service_broker_endpoints\\nWHERE is_encryption_enabled = 0 OR encryption_algorithm_desc IN ('NONE', 'RC4');", "parameters": [], "description": "Identifies Database Mail accounts without SSL and Service Broker endpoints with weak or no encryption."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.842847
