3060	sqlserver	execute	Pre-size log file and convert to fixed-MB autogrowth increment	{"sql": "-- Replace <DatabaseName>, <LogicalLogName>, <TargetSizeMB>, <GrowthIncrementMB>\\n-- with values derived from Step 1 analysis.\\n-- Rule: TargetSizeMB = peak_used_log_mb * 1.5 (150% of peak observed usage)\\n-- Rule: GrowthIncrementMB = TargetSizeMB * 0.1 (10% of pre-sized log as safety increment)\\n-- Minimum recommended GrowthIncrementMB: 256 MB for any production database.\\nUSE master;\\nALTER DATABASE [<DatabaseName>]\\n  MODIFY FILE (\\n    NAME = N'<LogicalLogName>',\\n    SIZE = <TargetSizeMB>MB,\\n    FILEGROWTH = <GrowthIncrementMB>MB\\n  );\\n-- Verify new settings:\\nSELECT logical_name, physical_name,\\n  size * 8 / 1024 AS size_mb,\\n  growth * 8 / 1024 AS growth_mb,\\n  is_percent_growth,\\n  max_size\\nFROM sys.master_files\\nWHERE database_id = DB_ID('<DatabaseName>') AND type = 1;", "parameters": {"DatabaseName": "Target database name", "TargetSizeMB": "150% of peak observed log used MB (minimum 512 MB for small databases)", "LogicalLogName": "Logical name of the log file from sys.master_files", "GrowthIncrementMB": "256-1024 MB fixed increment; avoid percent growth"}, "description": "Pre-allocates the log file to the target size immediately (SQL Server zeros the space synchronously — this operation may take several minutes for large sizes). Converts any percent-based autogrowth to a fixed MB increment to prevent exponential growth and unpredictable stall durations."}	{"sql": "-- Log files cannot be shrunk below current content, but growth settings can be reverted:\\nALTER DATABASE [<DatabaseName>]\\n  MODIFY FILE (\\n    NAME = N'<LogicalLogName>',\\n    FILEGROWTH = 1%  -- or previous growth setting\\n  );\\n-- Note: Shrinking a pre-allocated log file requires log activity to cease and\\n-- DBCC SHRINKFILE, which is generally discouraged in production.", "description": "Revert autogrowth setting to previous value. The pre-allocated disk space cannot be recovered without DBCC SHRINKFILE, which should only be done during a maintenance window."}	low	t	f	00:30:00	2026-02-24 13:10:27.50569
3062	sqlserver	verify	Identify the specific log truncation blocker for each affected database	{"sql": "-- Master diagnostic query: identify all affected databases and blocker type\\nSELECT d.name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS total_log_mb,\\n  ls.used_log_space_in_bytes / 1048576 AS used_log_mb,\\n  ls.used_log_space_in_percent,\\n  CASE d.log_reuse_wait_desc\\n    WHEN 'LOG_BACKUP'        THEN 'ACTION: Take transaction log backup immediately'\\n    WHEN 'ACTIVE_TRANSACTION' THEN 'ACTION: Identify and resolve long-running open transaction'\\n    WHEN 'REPLICATION'        THEN 'ACTION: Clear distribution queue or disable replication on this database'\\n    WHEN 'DATABASE_MIRRORING' THEN 'ACTION: Check mirroring send queue or failover readiness'\\n    WHEN 'AVAILABILITY_REPLICA' THEN 'ACTION: Check AG secondary redo lag or network'\\n    WHEN 'CHECKPOINT'         THEN 'ACTION: Issue manual CHECKPOINT; check if checkpoint is blocked'\\n    WHEN 'ACTIVE_BACKUP_OR_RESTORE' THEN 'INFO: Wait for backup/restore to complete'\\n    ELSE 'INVESTIGATE: ' + d.log_reuse_wait_desc\\n  END AS recommended_action\\nFROM sys.databases d\\nJOIN sys.dm_db_log_space_usage ls ON d.database_id = ls.database_id\\nWHERE d.database_id > 4\\n  AND d.log_reuse_wait_desc <> 'NOTHING'\\nORDER BY ls.used_log_space_in_percent DESC;", "parameters": {}, "description": "Classify each affected database by truncation blocker type. Proceed to the appropriate sub-action in the next step based on log_reuse_wait_desc."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.505693
3064	sqlserver	verify	Confirm log truncation has occurred and log space has been reclaimed	{"sql": "-- Verify log_reuse_wait_desc is now NOTHING and space is reclaimed\\nSELECT d.name, d.log_reuse_wait_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS total_log_mb,\\n  ls.used_log_space_in_bytes / 1048576 AS used_log_mb,\\n  ls.used_log_space_in_percent\\nFROM sys.databases d\\nJOIN sys.dm_db_log_space_usage ls ON d.database_id = ls.database_id\\nWHERE d.database_id > 4\\nORDER BY ls.used_log_space_in_percent DESC;\\n-- If log_reuse_wait_desc is NOTHING but used_log_mb is still high,\\n-- issue a manual checkpoint to trigger truncation:\\n-- USE [<DatabaseName>]; CHECKPOINT;\\n-- Note: space shows as available to VLFs but physical file does not shrink automatically.", "parameters": {}, "description": "Confirm that log_reuse_wait_desc has returned to NOTHING and that used_log_space_in_percent has decreased. A CHECKPOINT may be needed to trigger the actual truncation after the blocker is cleared."}	null	low	f	t	00:10:00	2026-02-24 13:10:27.505694
3065	sqlserver	verify	Characterize WRITELOG wait and log I/O subsystem performance	{"sql": "-- WRITELOG wait dominance\\nSELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'WRITELOG';\\n-- Log file physical I/O characteristics\\nSELECT d.name,\\n  mf.physical_name,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs.num_of_writes AS total_log_writes,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) AS avg_write_size_bytes,\\n  vfs.num_of_bytes_written / 1048576 AS total_log_mb_written\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nWHERE mf.type = 1 AND d.database_id > 4\\nORDER BY vfs.io_stall_write_ms DESC;\\n-- Check if log file is on the same volume as data files\\nSELECT type_desc, physical_name,\\n  LEFT(physical_name, 3) AS drive_letter\\nFROM sys.master_files\\nWHERE database_id > 4\\nORDER BY database_id, type_desc;", "parameters": {}, "description": "Determine avg_log_write_ms, total write throughput, and whether the log file shares storage with data files or OS. This guides whether the fix is storage isolation, disk upgrade, or workload reduction."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.505695
5881	postgresql	execute	Run initial comprehensive integrity check	{"sql": "CREATE EXTENSION IF NOT EXISTS amcheck;\\n\\n-- Check all B-tree indexes\\nSELECT c.relname AS index_name, bt_index_check(c.oid)\\nFROM pg_index i\\nJOIN pg_class c ON c.oid = i.indexrelid\\nWHERE i.indisvalid\\n  AND c.relam = (SELECT oid FROM pg_am WHERE amname = 'btree');", "parameters": [], "description": "Runs amcheck on all valid B-tree indexes to establish a clean integrity baseline."}	\N	low	f	t	5-60 minutes	2026-02-25 08:59:43.77256
3067	sqlserver	execute	Enable delayed durability as interim WRITELOG reduction measure	{"sql": "-- Enable delayed durability to reduce log flush frequency\\nALTER DATABASE [<DatabaseName>] SET DELAYED_DURABILITY = ALLOWED;\\n-- Monitor improvement after a representative workload period:\\nSELECT wait_type, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'WRITELOG';\\n-- Check that average write size increased (better batching):\\nSELECT d.name,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) AS avg_write_size_bytes\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nWHERE mf.type = 1 AND d.database_id > 4;", "parameters": {"DatabaseName": "Target user database"}, "description": "Delayed durability reduces the number of synchronous log flushes per second, directly reducing WRITELOG wait frequency. This is complementary to the storage fix and provides relief while storage changes are scheduled."}	{"sql": "ALTER DATABASE [<DatabaseName>] SET DELAYED_DURABILITY = DISABLED;", "description": "Immediately reverts to full synchronous durability. No restart required."}	medium	t	t	00:05:00	2026-02-24 13:10:27.505696
