3329	sqlserver	verify	Confirm prefix redundancy and capture usage baseline	{"sql": "WITH IndexKeys AS (\\n    SELECT i.object_id, i.index_id, i.name AS index_name,\\n           i.is_unique, i.is_primary_key, i.is_unique_constraint,\\n           STRING_AGG(CASE WHEN ic.is_included_column = 0\\n               THEN CAST(ic.column_id AS VARCHAR) END, ',')\\n               WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols,\\n           COUNT(CASE WHEN ic.is_included_column = 0 THEN 1 END) AS key_count\\n    FROM sys.indexes i\\n    JOIN sys.index_columns ic\\n        ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n    WHERE i.type IN (1, 2)\\n    GROUP BY i.object_id, i.index_id, i.name,\\n             i.is_unique, i.is_primary_key, i.is_unique_constraint\\n)\\nSELECT\\n    OBJECT_NAME(plain.object_id)          AS table_name,\\n    plain.index_name                       AS redundant_index,\\n    uniq.index_name                        AS unique_index,\\n    ISNULL(us.user_seeks,   0)             AS redundant_seeks,\\n    ISNULL(us.user_scans,   0)             AS redundant_scans,\\n    ISNULL(us.user_updates, 0)             AS redundant_writes,\\n    CASE WHEN uniq.is_primary_key = 1\\n         THEN 'Primary Key'\\n         WHEN uniq.is_unique_constraint = 1\\n         THEN 'Unique Constraint'\\n         ELSE 'Unique Index' END           AS unique_type\\nFROM IndexKeys plain\\nJOIN IndexKeys uniq\\n    ON  plain.object_id  = uniq.object_id\\n    AND plain.index_id  != uniq.index_id\\n    AND uniq.is_unique   = 1\\n    AND plain.is_unique  = 0\\n    AND plain.key_count <= uniq.key_count\\n    AND uniq.key_cols   LIKE plain.key_cols + '%'\\nLEFT JOIN sys.dm_db_index_usage_stats us\\n    ON  plain.object_id = us.object_id\\n    AND plain.index_id  = us.index_id\\n    AND us.database_id  = DB_ID()\\nORDER BY redundant_writes DESC;", "parameters": {}, "description": "Re-confirm prefix redundancy and record seeks/scans/writes to assess risk before dropping."}	null	low	f	t	\N	2026-02-24 13:10:27.53714
3330	sqlserver	verify	Check for explicit index hints referencing the redundant index	{"sql": "-- Search plan cache for queries hinting the redundant index by name\\nSELECT TOP 20\\n    qs.execution_count,\\n    qs.total_logical_reads,\\n    SUBSTRING(qt.text, (qs.statement_start_offset / 2) + 1,\\n        ((CASE qs.statement_end_offset\\n              WHEN -1 THEN DATALENGTH(qt.text)\\n              ELSE qs.statement_end_offset END\\n          - qs.statement_start_offset) / 2) + 1) AS statement_text,\\n    qp.query_plan\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle)  qt\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE CAST(qp.query_plan AS NVARCHAR(MAX))\\n      LIKE '%' + N'<replace_with_redundant_index_name>' + '%'\\nORDER BY qs.execution_count DESC;", "parameters": {"replace_with_redundant_index_name": "Name of the redundant prefix index identified in step 1"}, "description": "Scan the plan cache for any cached plans that explicitly reference the redundant index, indicating a WITH (INDEX=...) hint in application code."}	null	low	f	t	\N	2026-02-24 13:10:27.53714
3331	sqlserver	execute	Drop the redundant prefix index	{"sql": "-- Replace schema_name, table_name, and index_name with actual values\\nDROP INDEX [<redundant_index_name>] ON [<schema_name>].[<table_name>];", "parameters": {"table_name": "Table name", "schema_name": "Schema containing the table", "redundant_index_name": "Name of the redundant prefix index to drop"}, "description": "Drop the nonclustered prefix index. SQL Server will route all future seeks through the existing unique index, which already covers the same leading columns."}	{"sql": "-- Recreate the dropped index if rollback is needed\\n-- Replace placeholders with actual column names from detection output\\nCREATE INDEX [<redundant_index_name>]\\n    ON [<schema_name>].[<table_name>] (<leading_column_list>)\\n    WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);", "description": "Recreate the dropped index to restore prior state."}	medium	t	t	\N	2026-02-24 13:10:27.537141
3332	sqlserver	verify	Confirm index is removed and unique index still supports seeks	{"sql": "-- Confirm redundant index no longer exists\\nSELECT i.name, i.type_desc\\nFROM sys.indexes i\\nWHERE i.object_id = OBJECT_ID('<schema_name>.<table_name>')\\nORDER BY i.type, i.name;\\n\\n-- Confirm unique/PK index is still present and healthy\\nSELECT i.name, i.is_unique, i.is_primary_key, i.is_unique_constraint\\nFROM sys.indexes i\\nWHERE i.object_id = OBJECT_ID('<schema_name>.<table_name>')\\n  AND (i.is_unique = 1 OR i.is_primary_key = 1);", "parameters": {}, "description": "Verify the redundant index has been removed and the unique index remains intact."}	null	low	f	t	\N	2026-02-24 13:10:27.537142
3333	sqlserver	verify	Identify FK indexes to retain vs drop based on usage	{"sql": "WITH FKCols AS (\\n    SELECT fk.parent_object_id AS table_id, fk.name AS fk_name,\\n           fkc.parent_column_id AS col_id\\n    FROM sys.foreign_keys fk\\n    JOIN sys.foreign_key_columns fkc\\n        ON fk.object_id = fkc.constraint_object_id\\n    WHERE fkc.constraint_column_id = 1\\n),\\nFKIndexes AS (\\n    SELECT fk.table_id, fk.fk_name, i.index_id, i.name AS index_name,\\n           i.is_primary_key, i.is_unique_constraint, i.is_unique,\\n           (SELECT COUNT(*) FROM sys.index_columns ic2\\n            WHERE ic2.object_id = i.object_id\\n              AND ic2.index_id  = i.index_id\\n              AND ic2.is_included_column = 1) AS incl_count\\n    FROM FKCols fk\\n    JOIN sys.index_columns ic\\n        ON  fk.table_id   = ic.object_id\\n        AND fk.col_id     = ic.column_id\\n        AND ic.key_ordinal = 1\\n    JOIN sys.indexes i\\n        ON  ic.object_id = i.object_id\\n        AND ic.index_id  = i.index_id\\n    WHERE i.type > 0\\n)\\nSELECT\\n    OBJECT_NAME(fi.table_id)                          AS table_name,\\n    fi.fk_name,\\n    fi.index_name,\\n    fi.is_primary_key,\\n    fi.is_unique,\\n    fi.incl_count,\\n    ISNULL(ius.user_seeks,   0) + ISNULL(ius.user_scans, 0) AS reads,\\n    ISNULL(ius.user_updates, 0)                       AS writes,\\n    COUNT(*) OVER (PARTITION BY fi.table_id, fi.fk_name) AS competing_indexes,\\n    RANK()   OVER (PARTITION BY fi.table_id, fi.fk_name\\n                   ORDER BY ISNULL(ius.user_seeks,0)\\n                          + ISNULL(ius.user_scans,0) DESC,\\n                            fi.incl_count DESC)        AS keep_rank\\nFROM FKIndexes fi\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n    ON  fi.table_id    = ius.object_id\\n    AND fi.index_id    = ius.index_id\\n    AND ius.database_id = DB_ID()\\nWHERE (SELECT COUNT(*) FROM FKIndexes fi2\\n       WHERE fi2.table_id = fi.table_id\\n         AND fi2.fk_name  = fi.fk_name) > 1\\nORDER BY OBJECT_NAME(fi.table_id), fi.fk_name, keep_rank;", "parameters": {}, "description": "Rank competing FK-supporting indexes by reads and included columns to decide which to keep (keep_rank = 1) and which to drop."}	null	low	f	t	\N	2026-02-24 13:10:27.537142
3334	sqlserver	execute	Drop redundant FK-supporting index (keep_rank > 1)	{"sql": "-- Execute once per redundant index identified in step 1 (keep_rank > 1)\\n-- Replace placeholders with actual values\\nDROP INDEX [<redundant_fk_index_name>] ON [<schema_name>].[<table_name>];", "parameters": {"table_name": "Child table name", "schema_name": "Schema containing the table", "redundant_fk_index_name": "Name of the redundant FK-supporting index"}, "description": "Drop the lower-ranked duplicate FK-supporting index identified in the previous step."}	{"sql": "CREATE INDEX [<redundant_fk_index_name>]\\n    ON [<schema_name>].[<table_name>] (<fk_column_list>)\\n    WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);", "description": "Recreate the dropped FK-supporting index to restore prior state."}	medium	t	t	\N	2026-02-24 13:10:27.537143
3335	sqlserver	verify	Confirm FK validation still works after index removal	{"sql": "-- Validate that FK constraints still resolve correctly\\n-- Run a controlled INSERT that should pass FK validation\\nBEGIN TRAN;\\n    -- Insert a child row using a known valid parent key\\n    INSERT INTO [<schema_name>].[<table_name>] (<fk_column_name>)\\n    SELECT TOP 1 <parent_pk_column>\\n    FROM [<schema_name>].[<parent_table_name>];\\n\\n    -- Confirm row exists\\n    SELECT @@ROWCOUNT AS rows_inserted;\\nROLLBACK;  -- Always rollback the test insert\\n\\n-- Confirm the FK constraint is trusted\\nSELECT fk.name, fk.is_not_trusted, fk.is_disabled\\nFROM sys.foreign_keys fk\\nJOIN sys.tables t ON fk.parent_object_id = t.object_id\\nWHERE t.name = '<table_name>';", "parameters": {}, "description": "Verify FK constraint enforcement still works correctly with the retained index and that the constraint is not marked untrusted."}	null	low	f	t	\N	2026-02-24 13:10:27.537144
10505	postgresql	verify	Check server certificate file configuration	{"sql": "SELECT name, setting\\nFROM pg_settings\\nWHERE name IN ('ssl_cert_file', 'ssl_key_file', 'ssl_ca_file', 'ssl_crl_file')\\nORDER BY name;", "parameters": [], "description": "Lists configured certificate file paths"}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
3336	sqlserver	verify	Confirm manual index adds no distinct included columns	{"sql": "WITH IndexDetail AS (\\n    SELECT i.object_id, i.index_id, i.name AS index_name,\\n           i.is_primary_key, i.is_unique_constraint, i.is_unique,\\n           STRING_AGG(CASE WHEN ic.is_included_column = 0\\n               THEN CAST(ic.column_id AS VARCHAR) END, ',')\\n               WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols,\\n           STRING_AGG(CASE WHEN ic.is_included_column = 1\\n               THEN COL_NAME(ic.object_id, ic.column_id) END, ', ')\\n               WITHIN GROUP (ORDER BY ic.index_column_id) AS incl_cols\\n    FROM sys.indexes i\\n    JOIN sys.index_columns ic\\n        ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n    WHERE i.type IN (1, 2)\\n    GROUP BY i.object_id, i.index_id, i.name,\\n             i.is_primary_key, i.is_unique_constraint, i.is_unique\\n)\\nSELECT\\n    OBJECT_NAME(c.object_id)  AS table_name,\\n    c.index_name               AS constraint_index,\\n    CASE WHEN c.is_primary_key = 1 THEN 'PRIMARY KEY' ELSE 'UNIQUE CONSTRAINT' END AS constraint_kind,\\n    m.index_name               AS manual_index,\\n    ISNULL(m.incl_cols, 'none') AS manual_included_cols,\\n    ISNULL(um.user_seeks,   0) + ISNULL(um.user_scans, 0) AS manual_reads,\\n    ISNULL(um.user_updates, 0)                             AS manual_writes,\\n    ISNULL(uc.user_seeks,   0) + ISNULL(uc.user_scans, 0) AS constraint_reads\\nFROM IndexDetail c\\nJOIN IndexDetail m\\n    ON  c.object_id = m.object_id\\n    AND c.index_id != m.index_id\\n    AND c.key_cols  = m.key_cols\\n    AND (c.is_primary_key = 1 OR c.is_unique_constraint = 1)\\n    AND m.is_primary_key = 0\\n    AND m.is_unique_constraint = 0\\nLEFT JOIN sys.dm_db_index_usage_stats um\\n    ON  m.object_id  = um.object_id\\n    AND m.index_id   = um.index_id\\n    AND um.database_id = DB_ID()\\nLEFT JOIN sys.dm_db_index_usage_stats uc\\n    ON  c.object_id  = uc.object_id\\n    AND c.index_id   = uc.index_id\\n    AND uc.database_id = DB_ID()\\nORDER BY manual_writes DESC;", "parameters": {}, "description": "Show constraint vs manual index side-by-side with included columns. If manual_included_cols is 'none', the manual index is fully redundant."}	null	low	f	t	\N	2026-02-24 13:10:27.537144
3337	sqlserver	execute	Drop the redundant manual index	{"sql": "-- Replace placeholders with actual values from step 1\\nDROP INDEX [<manual_index_name>] ON [<schema_name>].[<table_name>];", "parameters": {"table_name": "Table name", "schema_name": "Schema of the table", "manual_index_name": "Name of the manually created redundant index"}, "description": "Drop the manual index that duplicates the constraint-created index. The optimizer will continue to use the PRIMARY KEY or UNIQUE constraint index for all seeks."}	{"sql": "CREATE INDEX [<manual_index_name>]\\n    ON [<schema_name>].[<table_name>] (<key_column_list>)\\n    WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);", "description": "Recreate the manually dropped index if rollback is needed."}	medium	t	t	\N	2026-02-24 13:10:27.537145
3338	sqlserver	verify	Verify constraint index still present and no seek regressions	{"sql": "-- Confirm manual index is gone and constraint index remains\\nSELECT i.name, i.type_desc, i.is_primary_key,\\n       i.is_unique_constraint, i.is_unique, i.is_disabled\\nFROM sys.indexes i\\nWHERE i.object_id = OBJECT_ID('<schema_name>.<table_name>')\\nORDER BY i.type, i.name;\\n\\n-- Monitor seek/scan counts on the constraint index after the change\\nSELECT i.name, us.user_seeks, us.user_scans,\\n       us.user_lookups, us.user_updates\\nFROM sys.dm_db_index_usage_stats us\\nJOIN sys.indexes i\\n    ON us.object_id = i.object_id AND us.index_id = i.index_id\\nWHERE us.database_id = DB_ID()\\n  AND us.object_id   = OBJECT_ID('<schema_name>.<table_name>')\\n  AND (i.is_primary_key = 1 OR i.is_unique_constraint = 1);", "parameters": {}, "description": "Confirm the manual index was removed and that the constraint index is healthy and accumulating seek usage."}	null	low	f	t	\N	2026-02-24 13:10:27.537146
3339	sqlserver	verify	Confirm exact key match and check size/usage of nonclustered duplicate	{"sql": "WITH IndexKeys AS (\\n    SELECT i.object_id, i.index_id, i.name AS index_name,\\n           i.type, i.type_desc, i.is_unique, i.is_primary_key,\\n           STRING_AGG(CASE WHEN ic.is_included_column = 0\\n               THEN CAST(ic.column_id AS VARCHAR) END, ',')\\n               WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols,\\n           STRING_AGG(CASE WHEN ic.is_included_column = 1\\n               THEN COL_NAME(ic.object_id, ic.column_id) END, ', ')\\n               WITHIN GROUP (ORDER BY ic.index_column_id) AS incl_cols\\n    FROM sys.indexes i\\n    JOIN sys.index_columns ic\\n        ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n    WHERE i.type IN (1, 2)\\n    GROUP BY i.object_id, i.index_id, i.name,\\n             i.type, i.type_desc, i.is_unique, i.is_primary_key\\n)\\nSELECT\\n    OBJECT_NAME(ci.object_id)           AS table_name,\\n    ci.index_name                        AS clustered_index,\\n    nci.index_name                       AS nonclustered_duplicate,\\n    ISNULL(nci.incl_cols, 'none')       AS nci_included_cols,\\n    ISNULL(un.user_seeks,   0) + ISNULL(un.user_scans, 0) AS nci_reads,\\n    ISNULL(un.user_updates, 0)          AS nci_writes,\\n    (SELECT SUM(au.used_pages) * 8 / 1024\\n     FROM sys.partitions p\\n     JOIN sys.allocation_units au\\n         ON p.partition_id = au.container_id\\n     WHERE p.object_id = nci.object_id\\n       AND p.index_id  = nci.index_id)  AS nci_size_mb\\nFROM IndexKeys ci\\nJOIN IndexKeys nci\\n    ON  ci.object_id = nci.object_id\\n    AND ci.type  = 1\\n    AND nci.type = 2\\n    AND ci.key_cols = nci.key_cols\\nLEFT JOIN sys.dm_db_index_usage_stats un\\n    ON  nci.object_id   = un.object_id\\n    AND nci.index_id    = un.index_id\\n    AND un.database_id  = DB_ID()\\nORDER BY nci_writes DESC;", "parameters": {}, "description": "Confirm exact key column match, check for included columns (none means fully redundant), and measure storage size and write overhead."}	null	low	f	t	\N	2026-02-24 13:10:27.537146
3340	sqlserver	execute	Drop nonclustered index duplicating clustered key	{"sql": "-- Replace placeholders with actual values\\nDROP INDEX [<nonclustered_index_name>] ON [<schema_name>].[<table_name>];", "parameters": {"table_name": "Table name", "schema_name": "Schema of the table", "nonclustered_index_name": "Name of the duplicate nonclustered index to drop"}, "description": "Remove the nonclustered index. Clustered index provides identical data ordering and all nonclustered indexes already embed the clustered key in their leaf rows."}	{"sql": "CREATE INDEX [<nonclustered_index_name>]\\n    ON [<schema_name>].[<table_name>] (<clustered_key_columns>)\\n    WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);", "description": "Recreate the nonclustered index using the original clustered key columns."}	medium	t	t	\N	2026-02-24 13:10:27.537147
3341	sqlserver	verify	Confirm clustered index health and freed space	{"sql": "-- Confirm nonclustered duplicate is gone\\nSELECT i.name, i.type_desc, i.is_primary_key, i.is_unique\\nFROM sys.indexes i\\nWHERE i.object_id = OBJECT_ID('<schema_name>.<table_name>')\\nORDER BY i.type, i.name;\\n\\n-- Check that the clustered index is healthy\\nSELECT index_type_desc, avg_fragmentation_in_percent,\\n       page_count, avg_page_space_used_in_percent\\nFROM sys.dm_db_index_physical_stats(\\n    DB_ID(), OBJECT_ID('<schema_name>.<table_name>'), 1, NULL, 'LIMITED'\\n);", "parameters": {}, "description": "Confirm removal of the nonclustered index and validate that the clustered index is intact and not fragmented."}	null	low	f	t	\N	2026-02-24 13:10:27.537147
3342	sqlserver	verify	Identify dominant vs minority values and estimate filtered index benefit	{"sql": "-- Get histogram distribution for the flag column\\nSELECT\\n    OBJECT_NAME(i.object_id)    AS table_name,\\n    i.name                       AS index_name,\\n    COL_NAME(ic.object_id, ic.column_id) AS leading_column,\\n    h.range_high_key             AS value,\\n    h.equal_rows,\\n    sp.total_rows,\\n    CAST(h.equal_rows AS FLOAT) / NULLIF(sp.total_rows, 0) * 100 AS pct_of_table\\nFROM sys.indexes i\\nJOIN sys.index_columns ic\\n    ON  i.object_id = ic.object_id\\n    AND i.index_id  = ic.index_id\\n    AND ic.key_ordinal = 1\\nCROSS APPLY sys.dm_db_stats_histogram(i.object_id, i.index_id) h\\nCROSS APPLY (\\n    SELECT SUM(rows) AS total_rows\\n    FROM sys.partitions\\n    WHERE object_id = i.object_id AND index_id IN (0, 1)\\n) sp\\nWHERE i.type = 2\\n  AND i.object_id = OBJECT_ID('<schema_name>.<table_name>')\\n  AND i.name      = '<low_selectivity_index_name>'\\nORDER BY h.equal_rows DESC;", "parameters": {}, "description": "Show the value distribution to confirm which value is dominant (high pct_of_table) and identify minority values suitable for a filtered index."}	null	low	f	t	\N	2026-02-24 13:10:27.537148
