3828	sqlserver	verify	Identify plans with high memory grant variance from parameter reuse	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.min_grant_kb / 1024 AS min_grant_mb,\\n  qs.max_grant_kb / 1024 AS max_grant_mb,\\n  qs.min_used_grant_kb / 1024 AS min_used_mb,\\n  qs.max_used_grant_kb / 1024 AS max_used_mb,\\n  CAST(qs.max_used_grant_kb AS FLOAT) / NULLIF(qs.max_grant_kb, 0) * 100 AS max_pct_used,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 10\\n  AND qs.max_grant_kb > 10240\\n  AND qs.max_grant_kb > qs.max_used_grant_kb * 3\\nORDER BY (qs.max_grant_kb - qs.max_used_grant_kb) * qs.execution_count DESC;", "parameters": [], "description": "Finds parameterized plans where the granted memory is consistently 3x or more the actual usage, indicating the cached plan's grant is wrong for most executions."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579292
3829	sqlserver	configure	Enable memory grant feedback and percentile-based adjustments	{"sql": "-- Enable memory grant feedback (batch mode: SQL 2017+, row mode: SQL 2019+)\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;\\n\\n-- Enable Query Store (required for persistent grant feedback in SQL 2022+)\\nALTER DATABASE CURRENT SET QUERY_STORE = ON;\\nALTER DATABASE CURRENT SET QUERY_STORE (OPERATION_MODE = READ_WRITE);", "parameters": [], "description": "Enables memory grant feedback which automatically adjusts grants based on actual usage over multiple executions. Query Store persists adjustments across plan evictions."}	{"sql": "ALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = OFF;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = OFF;", "description": "Disable memory grant feedback features."}	low	t	t	00:01:00	2026-02-24 13:10:27.579292
3830	sqlserver	execute	Add MAX_GRANT_PERCENT hints to worst offending queries	{"sql": "-- For the top overallocating queries, add query hint\\n-- Option A: Direct hint in the query\\n-- SELECT ... OPTION (MAX_GRANT_PERCENT = @max_pct);\\n\\n-- Option B: Plan guide for queries you cannot modify\\nEXEC sp_create_plan_guide\\n  @name = N'PG_limit_grant_@query_name',\\n  @stmt = N'@original_query_text',\\n  @type = N'SQL',\\n  @hints = N'OPTION (MAX_GRANT_PERCENT = @max_pct)';", "parameters": ["max_pct", "query_name", "original_query_text"], "description": "Applies MAX_GRANT_PERCENT hints to the worst offending queries. Direct hints for modifiable queries, plan guides for queries from applications or ORMs."}	{"sql": "EXEC sp_control_plan_guide @operation = N'DROP', @name = N'PG_limit_grant_@query_name';", "description": "Drop the plan guide to remove the memory grant cap."}	medium	t	t	00:05:00	2026-02-24 13:10:27.579293
