3925	sqlserver	instruct	Move tempdb to faster storage and optimize configuration	{"sql": null, "parameters": [], "description": "To improve tempdb IO performance: (1) Move tempdb to SSD/NVMe storage (requires SQL Server restart). (2) Add tempdb data files to match CPU count (up to 8). (3) Pre-size all tempdb files to avoid autogrowth. (4) Enable trace flag 1118 (SQL 2014 and earlier) for uniform extent allocation. (5) Consider enabling memory-optimized tempdb metadata (SQL 2019+): ALTER SERVER CONFIGURATION SET MEMORY_OPTIMIZED TEMPDB_METADATA = ON. Steps: ALTER DATABASE tempdb MODIFY FILE (NAME = 'tempdev', FILENAME = 'D:\\fast_ssd\\tempdb.mdf', SIZE = 4096MB);"}	null	medium	t	t	01:00:00	2026-02-24 13:10:27.579357
3835	sqlserver	verify	Assess columnstore rowgroup quality and grant overestimation	{"sql": "SELECT\\n  OBJECT_NAME(rg.object_id) AS table_name,\\n  i.name AS index_name,\\n  COUNT(*) AS total_rowgroups,\\n  SUM(CASE WHEN rg.state_desc = 'OPEN' THEN 1 ELSE 0 END) AS open_delta_groups,\\n  SUM(CASE WHEN rg.state_desc = 'COMPRESSED' AND rg.total_rows < 100000 THEN 1 ELSE 0 END) AS small_compressed,\\n  SUM(rg.total_rows) AS total_rows,\\n  SUM(rg.deleted_rows) AS deleted_rows,\\n  CAST(SUM(rg.deleted_rows) AS FLOAT) / NULLIF(SUM(rg.total_rows), 0) * 100 AS delete_pct\\nFROM sys.dm_db_column_store_row_group_physical_stats rg\\nJOIN sys.indexes i ON rg.object_id = i.object_id AND rg.index_id = i.index_id\\nGROUP BY rg.object_id, i.name\\nORDER BY SUM(rg.total_rows) DESC;", "parameters": [], "description": "Assesses columnstore index quality by checking for open delta stores, small compressed rowgroups, and high delete ratios — all of which affect batch mode estimation."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579297
3836	sqlserver	execute	Reorganize columnstore indexes to optimize rowgroup quality	{"sql": "-- Reorganize to merge small rowgroups and remove deleted rows\\nALTER INDEX [@index_name] ON [@schema_name].[@table_name] REORGANIZE\\n  WITH (COMPRESS_ALL_ROW_GROUPS = ON);\\n\\n-- For severely fragmented columnstores, full rebuild:\\n-- ALTER INDEX [@index_name] ON [@schema_name].[@table_name] REBUILD\\n--   WITH (ONLINE = ON);", "parameters": ["index_name", "schema_name", "table_name"], "description": "Reorganizes the columnstore index to merge small rowgroups, compress open delta stores, and remove deleted rows. This improves rowgroup quality and batch mode estimation accuracy."}	null	medium	t	f	00:30:00	2026-02-24 13:10:27.579298
3837	sqlserver	configure	Enable adaptive query processing for batch mode	{"sql": "-- Enable batch mode adaptive joins (SQL 2017+)\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_ADAPTIVE_JOINS = ON;\\n\\n-- Enable batch mode memory grant feedback (SQL 2017+)\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\n\\n-- Verify settings\\nSELECT name, value FROM sys.database_scoped_configurations\\nWHERE name IN ('BATCH_MODE_ADAPTIVE_JOINS', 'BATCH_MODE_MEMORY_GRANT_FEEDBACK');", "parameters": [], "description": "Enables adaptive query processing features that automatically adjust join types and memory grants for batch mode queries."}	{"sql": "ALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_ADAPTIVE_JOINS = OFF;\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = OFF;", "description": "Disable adaptive query processing features."}	low	t	t	00:01:00	2026-02-24 13:10:27.579298
3838	sqlserver	verify	Verify improved columnstore query memory grants	{"sql": "SELECT TOP 10\\n  qs.total_grant_kb / qs.execution_count / 1024 AS avg_grant_mb,\\n  qs.total_used_grant_kb / qs.execution_count / 1024 AS avg_used_mb,\\n  CAST(qs.total_used_grant_kb AS FLOAT) / NULLIF(qs.total_grant_kb, 0) * 100 AS utilization_pct,\\n  qs.total_spills / qs.execution_count AS avg_spills\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 3\\nORDER BY qs.total_grant_kb / qs.execution_count DESC;", "parameters": [], "description": "Checks that memory grant utilization has improved for columnstore queries after reorganization and adaptive processing."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579299
3839	sqlserver	verify	Assess current MAXDOP and CPU topology	{"sql": "SELECT\\n  cpu_count AS logical_cpus,\\n  hyperthread_ratio,\\n  cpu_count / hyperthread_ratio AS physical_cores,\\n  (SELECT COUNT(DISTINCT parent_node_id) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS numa_nodes,\\n  CAST(value_in_use AS INT) AS current_maxdop\\nFROM sys.dm_os_sys_info\\nCROSS JOIN sys.configurations\\nWHERE name = 'max degree of parallelism';\\n\\n-- Check CXPACKET wait proportion\\nSELECT\\n  wait_type,\\n  wait_time_ms / 1000 AS wait_sec,\\n  waiting_tasks_count,\\n  CAST(wait_time_ms AS FLOAT) / (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_time_ms > 0) * 100 AS pct_of_total\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT', 'CXSYNC_CONSUMER')\\n  AND wait_time_ms > 0\\nORDER BY wait_time_ms DESC;", "parameters": [], "description": "Captures CPU topology and current MAXDOP setting, plus CXPACKET wait statistics to quantify parallelism overhead."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579299
7862	postgresql	verify	Check for pg_hba.conf parse errors	{"sql": "SELECT line_number, error FROM pg_hba_file_rules WHERE error IS NOT NULL;", "parameters": [], "description": "Identifies corrupted or malformed entries in pg_hba.conf"}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
3840	sqlserver	configure	Set MAXDOP based on CPU topology	{"sql": "-- Set MAXDOP following Microsoft best practices:\\n-- Single NUMA node: MAXDOP = min(physical_cores, 8)\\n-- Multiple NUMA nodes: MAXDOP = physical_cores_per_numa_node\\nEXEC sp_configure 'max degree of parallelism', @recommended_maxdop;\\nRECONFIGURE;", "parameters": ["recommended_maxdop"], "description": "Sets MAXDOP to the recommended value based on CPU topology. For single NUMA: min(physical cores, 8). For multi-NUMA: physical cores per NUMA node."}	{"sql": "EXEC sp_configure 'max degree of parallelism', @original_maxdop;\\nRECONFIGURE;", "description": "Restore the original MAXDOP setting."}	medium	t	t	00:01:00	2026-02-24 13:10:27.5793
3841	sqlserver	verify	Verify reduced CXPACKET waits after MAXDOP adjustment	{"sql": "-- Clear wait stats to measure fresh\\n-- DBCC SQLPERF('sys.dm_os_wait_stats', CLEAR); -- uncomment to reset\\n\\n-- Check CXPACKET waits after workload period\\nSELECT\\n  wait_type,\\n  wait_time_ms / 1000 AS wait_sec,\\n  waiting_tasks_count,\\n  CAST(wait_time_ms AS FLOAT) / (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_time_ms > 0) * 100 AS pct_of_total\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT', 'CXSYNC_CONSUMER')\\n  AND wait_time_ms > 0\\nORDER BY wait_time_ms DESC;\\n\\n-- Verify current setting\\nSELECT name, CAST(value_in_use AS INT) AS value\\nFROM sys.configurations\\nWHERE name = 'max degree of parallelism';", "parameters": [], "description": "Monitors CXPACKET wait statistics after the MAXDOP change. Waits should decrease as a percentage of total waits."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579301
