3842	sqlserver	verify	Assess current cost threshold and plan cache distribution	{"sql": "SELECT name, CAST(value_in_use AS INT) AS current_value\\nFROM sys.configurations\\nWHERE name = 'cost threshold for parallelism';\\n\\n-- Check distribution of cached plan costs\\nSELECT\\n  CASE\\n    WHEN cp.usecounts > 0 AND qp.query_plan IS NOT NULL THEN\\n      CASE\\n        WHEN qp.query_plan.exist('//RelOp[@Parallel=\\"true\\" or @Parallel=\\"1\\"]') = 1 THEN 'Parallel'\\n        ELSE 'Serial'\\n      END\\n    ELSE 'Unknown'\\n  END AS plan_type,\\n  COUNT(*) AS plan_count,\\n  AVG(cp.usecounts) AS avg_use_count\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_query_plan(cp.plan_handle) qp\\nWHERE cp.objtype IN ('Adhoc', 'Prepared', 'Proc')\\n  AND cp.usecounts > 1\\nGROUP BY\\n  CASE\\n    WHEN cp.usecounts > 0 AND qp.query_plan IS NOT NULL THEN\\n      CASE\\n        WHEN qp.query_plan.exist('//RelOp[@Parallel=\\"true\\" or @Parallel=\\"1\\"]') = 1 THEN 'Parallel'\\n        ELSE 'Serial'\\n      END\\n    ELSE 'Unknown'\\n  END;", "parameters": [], "description": "Checks current cost threshold and the proportion of parallel vs serial plans in the plan cache."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579301
3926	sqlserver	verify	Verify improved tempdb latency after storage optimization	{"sql": "SELECT mf.physical_name,\\n  CASE WHEN vfs.num_of_reads > 0\\n    THEN vfs.io_stall_read_ms / vfs.num_of_reads ELSE 0 END AS avg_read_ms,\\n  CASE WHEN vfs.num_of_writes > 0\\n    THEN vfs.io_stall_write_ms / vfs.num_of_writes ELSE 0 END AS avg_write_ms\\nFROM sys.dm_io_virtual_file_stats(2, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id;", "parameters": [], "description": "Re-checks tempdb IO latency after storage optimization."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579357
3847	sqlserver	verify	Verify queries shifted from parallel to serial plans	{"sql": "-- Check CXPACKET waits trend\\nSELECT\\n  wait_type,\\n  wait_time_ms / 1000 AS wait_sec,\\n  CAST(wait_time_ms AS FLOAT) / (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_time_ms > 0) * 100 AS pct_of_total\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER')\\n  AND wait_time_ms > 0;\\n\\n-- Verify small queries now use serial plans in Query Store\\nSELECT TOP 10\\n  qsrs.avg_dop, qsrs.avg_rowcount,\\n  qsrs.count_executions,\\n  qsrs.avg_duration / 1000 AS avg_duration_ms\\nFROM sys.query_store_runtime_stats qsrs\\nJOIN sys.query_store_plan qsp ON qsrs.plan_id = qsp.plan_id\\nWHERE qsrs.avg_rowcount < 1000\\n  AND qsrs.count_executions > 10\\nORDER BY qsrs.avg_dop DESC;", "parameters": [], "description": "Checks that CXPACKET waits decreased and small queries (returning <1000 rows) now use serial plans."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579303
3848	sqlserver	verify	Assess CPU overcommit and signal wait pressure	{"sql": "SELECT\\n  os.cpu_count AS logical_cpus,\\n  os.hyperthread_ratio,\\n  CAST(value_in_use AS INT) AS current_maxdop,\\n  CAST((SELECT SUM(signal_wait_time_ms) FROM sys.dm_os_wait_stats) AS FLOAT) /\\n    NULLIF((SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats), 0) * 100 AS signal_wait_pct\\nFROM sys.dm_os_sys_info os\\nCROSS JOIN sys.configurations\\nWHERE name = 'max degree of parallelism';\\n\\nSELECT wait_type, wait_time_ms, waiting_tasks_count\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('SOS_SCHEDULER_YIELD', 'CXPACKET', 'THREADPOOL')\\n  AND wait_time_ms > 0\\nORDER BY wait_time_ms DESC;", "parameters": [], "description": "Checks CPU topology, current MAXDOP, and signal wait percentage. Signal waits >20% indicate CPU pressure from overcommit."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579304
3849	sqlserver	configure	Set MAXDOP to half the visible logical CPUs	{"sql": "-- In virtualized environments, set MAXDOP to half logical CPUs or 4, whichever is lower\\nEXEC sp_configure 'max degree of parallelism', @conservative_maxdop;\\nRECONFIGURE;", "parameters": ["conservative_maxdop"], "description": "Sets MAXDOP conservatively for virtualized environments. Typical recommendation: half the vCPUs or 4, whichever is lower. This accounts for CPU overcommit."}	{"sql": "EXEC sp_configure 'max degree of parallelism', @original_maxdop;\\nRECONFIGURE;", "description": "Restore original MAXDOP setting."}	medium	t	t	00:01:00	2026-02-24 13:10:27.579305
