3861	sqlserver	configure	Reduce MAXDOP and configure Resource Governor to limit thread consumption	{"sql": "-- Reduce global MAXDOP\\nEXEC sp_configure 'max degree of parallelism', @reduced_maxdop;\\nRECONFIGURE;\\n\\n-- Optionally, use Resource Governor to cap specific workloads\\nALTER WORKLOAD GROUP [default]\\n  WITH (MAX_DOP = @max_dop, GROUP_MAX_REQUESTS = @max_requests);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "parameters": ["reduced_maxdop", "max_dop", "max_requests"], "description": "Reduces MAXDOP to limit thread multiplication from nested parallel zones. Resource Governor provides per-workload thread limits."}	{"sql": "EXEC sp_configure 'max degree of parallelism', @original_maxdop;\\nRECONFIGURE;\\nALTER WORKLOAD GROUP [default] WITH (MAX_DOP = 0, GROUP_MAX_REQUESTS = 0);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "description": "Restore original MAXDOP and Resource Governor settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.57931
3862	sqlserver	verify	Verify thread pool stability	{"sql": "SELECT\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS current_workers,\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'THREADPOOL') AS threadpool_wait_ms,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests;", "parameters": [], "description": "Verifies thread pool is no longer exhausted and no requests are queuing."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579311
3863	sqlserver	verify	Assess plan cache pollution from single-use parallel plans	{"sql": "SELECT\\n  SUM(CASE WHEN cp.usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans,\\n  COUNT(*) AS total_plans,\\n  SUM(CASE WHEN cp.usecounts = 1 THEN cp.size_in_bytes ELSE 0 END) / 1048576 AS single_use_mb,\\n  SUM(cp.size_in_bytes) / 1048576 AS total_cache_mb\\nFROM sys.dm_exec_cached_plans cp\\nWHERE cp.objtype = 'Adhoc';", "parameters": [], "description": "Measures single-use plan pollution in the plan cache. High single-use percentage and MB indicates cache waste."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579312
