3902	sqlserver	verify	Assess memory pressure and thread creation impact	{"sql": "SELECT\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)' AND object_name LIKE '%Memory Manager%') AS server_memory_mb,\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Target Server Memory (KB)' AND object_name LIKE '%Memory Manager%') AS target_memory_mb,\\n  (SELECT physical_memory_kb / 1024 FROM sys.dm_os_sys_info) AS physical_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n     AND object_name LIKE '%Buffer Manager%') AS ple_seconds,\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'THREADPOOL') AS threadpool_wait_ms;", "parameters": [], "description": "Checks SQL Server memory consumption relative to physical memory, pending memory grants, and thread pool waits."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579342
3903	sqlserver	configure	Reduce max server memory and optimize memory consumers	{"sql": "-- Reserve memory for OS and thread stacks\\n-- Rule: physical_memory - 4GB (OS reserve) - max_worker_threads * 0.5MB\\nEXEC sp_configure 'max server memory (MB)', @new_max_memory;\\nRECONFIGURE;\\n\\n-- Reduce MAXDOP to decrease memory grant demand\\nEXEC sp_configure 'max degree of parallelism', @reduced_maxdop;\\nRECONFIGURE;", "parameters": ["new_max_memory", "reduced_maxdop"], "description": "Reduces max server memory to leave more OS memory available for thread stacks and other system needs. Also reduces MAXDOP to lower per-query memory grant demand."}	{"sql": "EXEC sp_configure 'max server memory (MB)', @original_max_memory;\\nEXEC sp_configure 'max degree of parallelism', @original_maxdop;\\nRECONFIGURE;", "description": "Restore original memory and MAXDOP settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.579342
3905	sqlserver	execute	Kill orphaned long-running queries	{"sql": "DECLARE @session_id INT;\\nDECLARE orphan_cursor CURSOR FOR\\n  SELECT r.session_id\\n  FROM sys.dm_exec_requests r\\n  JOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\n  WHERE r.session_id > 50\\n    AND DATEDIFF(MINUTE, r.start_time, GETDATE()) > @threshold_minutes\\n    AND s.is_user_process = 1;\\nOPEN orphan_cursor;\\nFETCH NEXT FROM orphan_cursor INTO @session_id;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  EXEC('KILL ' + @session_id);\\n  FETCH NEXT FROM orphan_cursor INTO @session_id;\\nEND;\\nCLOSE orphan_cursor;\\nDEALLOCATE orphan_cursor;", "parameters": ["threshold_minutes"], "description": "Kills user sessions with queries running longer than the threshold. DBA reviews the session list before executing."}	null	medium	t	f	00:01:00	2026-02-24 13:10:27.579343
3906	sqlserver	configure	Set query governor cost limit as safety net	{"sql": "-- Set query governor to prevent very expensive queries\\nEXEC sp_configure 'query governor cost limit', @cost_limit;\\nRECONFIGURE;\\n\\n-- For Resource Governor, set per-group request timeout\\nALTER WORKLOAD GROUP [default]\\n  WITH (REQUEST_MEMORY_GRANT_TIMEOUT_SEC = @timeout_seconds);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "parameters": ["cost_limit", "timeout_seconds"], "description": "Sets a query cost limit to prevent extremely expensive queries from running, and configures a memory grant timeout to prevent queries from holding resources indefinitely."}	{"sql": "EXEC sp_configure 'query governor cost limit', 0;\\nRECONFIGURE;\\nALTER WORKLOAD GROUP [default] WITH (REQUEST_MEMORY_GRANT_TIMEOUT_SEC = 0);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "description": "Remove query governor limit and memory grant timeout."}	medium	t	t	00:01:00	2026-02-24 13:10:27.579344
3907	sqlserver	verify	Verify thread pool recovered after orphan cleanup	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE session_id > 50 AND DATEDIFF(MINUTE, start_time, GETDATE()) > 30) AS long_running_queries,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests;", "parameters": [], "description": "Confirms orphaned queries are gone and thread pool has recovered."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579344
3908	sqlserver	verify	Assess deadlock frequency and impact on thread pool	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE wait_type LIKE 'LCK_%') AS threads_on_locks,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') AS total_x_lock_wait_ms;", "parameters": [], "description": "Checks how many threads are waiting on locks and the total exclusive lock wait time."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579345
3909	sqlserver	configure	Enable READ COMMITTED SNAPSHOT to eliminate reader-writer deadlocks	{"sql": "-- Enable RCSI (requires exclusive database access momentarily)\\nALTER DATABASE [@database_name] SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;\\n\\n-- Verify RCSI is enabled\\nSELECT name, is_read_committed_snapshot_on\\nFROM sys.databases\\nWHERE name = @database_name;", "parameters": ["database_name"], "description": "Enables READ_COMMITTED_SNAPSHOT isolation which uses row versioning instead of shared locks for reads. This eliminates all reader-writer deadlocks."}	{"sql": "ALTER DATABASE [@database_name] SET READ_COMMITTED_SNAPSHOT OFF WITH ROLLBACK IMMEDIATE;", "description": "Disable READ COMMITTED SNAPSHOT isolation."}	medium	t	t	00:01:00	2026-02-24 13:10:27.579346
3910	sqlserver	verify	Verify reduced deadlocks and lock waits	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE wait_type LIKE 'LCK_%') AS threads_on_locks,\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') AS total_x_lock_wait_ms,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests;", "parameters": [], "description": "Checks that lock waits have decreased after enabling RCSI."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579347
3914	sqlserver	verify	Quantify spill impact and memory grant shortfalls	{"sql": "SELECT TOP 15\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_grant_mb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_ideal_mb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_used_mb,\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Identifies spilling queries and compares granted memory to ideal and used memory. Grant below ideal indicates memory pressure."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579349
3915	sqlserver	execute	Update statistics and enable memory grant feedback	{"sql": "-- Update statistics on tables used by spilling queries\\nEXEC sp_updatestats;\\n\\n-- Enable memory grant feedback\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;", "parameters": [], "description": "Updates all stale statistics for better cardinality estimation. Enables memory grant feedback to auto-adjust grants based on actual usage."}	{"sql": "ALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = OFF;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = OFF;", "description": "Disable memory grant feedback."}	low	t	t	00:15:00	2026-02-24 13:10:27.57935
3916	sqlserver	verify	Verify reduced spill activity	{"sql": "SELECT TOP 10\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_grant_mb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_used_mb\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Checks that spill counts have decreased after statistics update and memory grant feedback."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.57935
3917	sqlserver	verify	Verify spills decreased after statistics update	{"sql": "SELECT TOP 10\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_grant_mb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_ideal_mb\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Checks that spills decreased and grants now match ideal requirements."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579351
3918	sqlserver	verify	Confirm data skew as the spill cause	{"sql": "SELECT TOP 10\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_grant_mb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_used_mb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_ideal_mb,\\n  CAST(qs.total_used_grant_kb AS FLOAT) / NULLIF(qs.total_grant_kb, 0) * 100 AS pct_grant_used\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_spills > 0\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND qs.total_grant_kb >= qs.total_ideal_grant_kb * 0.8\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Finds parallel queries that spill despite receiving adequate total memory grants. This pattern indicates per-thread overflow from data skew."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579352
3919	sqlserver	execute	Reduce DOP or force serial execution for skewed queries	{"sql": "-- Option A: Add MAXDOP hint to reduce parallel threads (concentrates memory)\\n-- SELECT ... OPTION (MAXDOP 2);\\n\\n-- Option B: Force serial for extremely skewed queries\\n-- SELECT ... OPTION (MAXDOP 1);\\n\\n-- Option C: Create plan guide for queries you cannot modify\\nEXEC sp_create_plan_guide\\n  @name = N'PG_reduce_dop_skewed',\\n  @stmt = N'@original_query_text',\\n  @type = N'SQL',\\n  @hints = N'OPTION (MAXDOP 2)';", "parameters": [], "description": "Reduces DOP for skewed queries to concentrate memory into fewer threads, or forces serial execution. Plan guides apply hints to queries that cannot be modified."}	{"sql": "EXEC sp_control_plan_guide @operation = N'DROP', @name = N'PG_reduce_dop_skewed';", "description": "Drop the plan guide to restore default parallelism."}	medium	t	t	00:05:00	2026-02-24 13:10:27.579352
3920	sqlserver	verify	Verify spills eliminated for skewed queries	{"sql": "SELECT TOP 10\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Checks that spills decreased and query performance improved."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579353
3921	sqlserver	verify	Check memory clerk fragmentation and grant shortfalls	{"sql": "SELECT TOP 10\\n  type, SUM(pages_kb) / 1024 AS total_mb\\nFROM sys.dm_os_memory_clerks\\nGROUP BY type\\nORDER BY SUM(pages_kb) DESC;\\n\\nSELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants\\n   WHERE granted_memory_kb < requested_memory_kb) AS reduced_grants;", "parameters": [], "description": "Shows memory distribution across clerks and checks for queries receiving less memory than requested."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579354
3922	sqlserver	configure	Optimize memory allocation to reduce fragmentation	{"sql": "-- Limit max memory grant per query to prevent large allocations\\nALTER WORKLOAD GROUP [default]\\n  WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = @max_grant_pct);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\n\\n-- Reduce MAXDOP to lower per-query memory demand\\nEXEC sp_configure 'max degree of parallelism', @reduced_maxdop;\\nRECONFIGURE;", "parameters": ["max_grant_pct", "reduced_maxdop"], "description": "Limits per-query memory grants to prevent any single query from fragmenting available memory. Lower MAXDOP reduces per-query memory requirements."}	{"sql": "ALTER WORKLOAD GROUP [default] WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\nEXEC sp_configure 'max degree of parallelism', @original_maxdop;\\nRECONFIGURE;", "description": "Restore default grant limits and MAXDOP."}	medium	t	t	00:01:00	2026-02-24 13:10:27.579354
3923	sqlserver	verify	Verify reduced grant shortfalls and spills	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE granted_memory_kb < requested_memory_kb) AS reduced_grants,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending;", "parameters": [], "description": "Checks that reduced grant count and pending grants have decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579355
4735	sqlserver	verify	Confirm orphan detection covers all databases	{"sql": "SELECT dp.name AS user_name, dp.type_desc, dp.create_date, dp.sid\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G') AND dp.sid IS NOT NULL AND dp.sid <> 0x00 AND LEN(dp.sid) > 0\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser');", "parameters": [], "description": "Shows orphaned users in the current database context."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.788694
3927	sqlserver	verify	Identify oversized data types in spilling queries	{"sql": "SELECT TOP 10\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_grant_mb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_used_mb,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 300) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_spills > 0\\n  AND (t.text LIKE '%VARCHAR(MAX)%' OR t.text LIKE '%NVARCHAR(MAX)%' OR t.text LIKE '%CHAR(8000)%')\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Identifies spilling queries that reference oversized data types."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579358
3929	sqlserver	verify	Assess memory pressure and grant shortfalls	{"sql": "SELECT\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)' AND object_name LIKE '%Memory Manager%') AS server_memory_mb,\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Target Server Memory (KB)' AND object_name LIKE '%Memory Manager%') AS target_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NULL) AS waiting_for_grant;", "parameters": [], "description": "Checks if the server is at memory target and if queries are waiting for or receiving reduced grants."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.579359
3930	sqlserver	configure	Reduce memory consumers and increase grant availability	{"sql": "-- Reduce MAXDOP to lower per-query memory demand\\nEXEC sp_configure 'max degree of parallelism', @reduced_maxdop;\\nRECONFIGURE;\\n\\n-- Limit individual query grants to prevent one query from starving others\\nALTER WORKLOAD GROUP [default]\\n  WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = @max_grant_pct);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\n\\n-- If server has additional RAM available, increase max memory\\n-- EXEC sp_configure 'max server memory (MB)', @increased_max_memory;\\n-- RECONFIGURE;", "parameters": ["reduced_maxdop", "max_grant_pct"], "description": "Reduces per-query memory demand and limits individual grants so more queries can receive adequate memory simultaneously."}	{"sql": "EXEC sp_configure 'max degree of parallelism', @original_maxdop;\\nRECONFIGURE;\\nALTER WORKLOAD GROUP [default] WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "description": "Restore original settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.57936
3931	sqlserver	verify	Verify grants no longer pending and spills decreased	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending;\\n\\nSELECT TOP 5\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_grant_mb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) / 1024 AS avg_ideal_mb\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Checks that no grants are pending and grant sizes are closer to ideal."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.57936
3932	sqlserver	execute	Add tempdb data files to match CPU count	{"sql": "-- Check current tempdb files vs CPU count\\nSELECT\\n  (SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type = 0) AS current_files,\\n  (SELECT COUNT(DISTINCT scheduler_id) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS cpu_count;\\n\\n-- Add tempdb data files (one per CPU up to 8, then add in groups of 4)\\n-- Example for adding files to reach 8:\\nALTER DATABASE tempdb ADD FILE (NAME = N'tempdev2', FILENAME = N'T:\\tempdb\\tempdev2.ndf', SIZE = 8192MB, FILEGROWTH = 1024MB);\\nALTER DATABASE tempdb ADD FILE (NAME = N'tempdev3', FILENAME = N'T:\\tempdb\\tempdev3.ndf', SIZE = 8192MB, FILEGROWTH = 1024MB);\\nALTER DATABASE tempdb ADD FILE (NAME = N'tempdev4', FILENAME = N'T:\\tempdb\\tempdev4.ndf', SIZE = 8192MB, FILEGROWTH = 1024MB);", "parameters": ["tempdb_file_path", "file_size_mb"], "description": "Adds tempdb data files so parallel spill writes distribute across multiple files. All files must be the same size for proportional fill to work correctly."}	{"sql": "-- Remove added tempdb files (requires restart)\\nALTER DATABASE tempdb REMOVE FILE tempdev4;\\nALTER DATABASE tempdb REMOVE FILE tempdev3;\\nALTER DATABASE tempdb REMOVE FILE tempdev2;\\n-- Note: files must be empty before removal; DBCC SHRINKFILE(tempdev4, EMPTYFILE) first", "description": "Remove the added tempdb data files after emptying them."}	medium	t	t	\N	2026-02-24 13:10:27.591071
3941	sqlserver	instruct	Evaluate hardware upgrade requirements based on bottleneck type	{"sql": null, "parameters": [], "description": "Based on detection findings: (1) If signal_wait_pct > 15%, CPU is the bottleneck - add cores or reduce MAXDOP. (2) If PLE < 300 seconds per 4GB RAM, memory is insufficient - add RAM. (3) If avg read/write latency > 20ms, storage is the bottleneck - migrate to SSD/NVMe or add I/O bandwidth. (4) If memory grants pending > 0, increase max server memory or reduce concurrent queries via Resource Governor."}	null	low	f	t	\N	2026-02-24 13:10:27.591076
3933	sqlserver	configure	Reduce spill frequency by increasing memory grants	{"sql": "-- Increase minimum memory per query for spill-prone workloads\\nEXEC sp_configure 'min memory per query (KB)', 2048;\\nRECONFIGURE;\\n\\n-- Enable memory grant feedback for adaptive grants (SQL Server 2019+)\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;", "parameters": [], "description": "Increases minimum memory per query to reduce spill likelihood and enables memory grant feedback for automatic adjustment."}	{"sql": "EXEC sp_configure 'min memory per query (KB)', 1024;\\nRECONFIGURE;\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = OFF;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = OFF;", "description": "Revert to default minimum memory per query and disable grant feedback."}	low	t	t	00:01:00	2026-02-24 13:10:27.591738
3934	sqlserver	verify	Verify reduced tempdb I/O contention and spill waits	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type = 0) AS tempdb_data_files,\\n  ws_page.wait_time_ms AS pagelatch_wait_ms,\\n  ws_page.waiting_tasks_count AS pagelatch_waits,\\n  ws_io.wait_time_ms AS pageiolatch_wait_ms,\\n  ws_io.waiting_tasks_count AS pageiolatch_waits\\nFROM sys.dm_os_wait_stats ws_page\\nCROSS JOIN sys.dm_os_wait_stats ws_io\\nWHERE ws_page.wait_type = 'PAGELATCH_UP'\\n  AND ws_io.wait_type = 'PAGEIOLATCH_SH';", "parameters": [], "description": "Confirms tempdb file count increased and PAGELATCH/PAGEIOLATCH waits have decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.591741
3946	sqlserver	execute	Update statistics on all tables involved in problematic joins	{"sql": "-- Update statistics with full scan on tables involved in expensive multi-join queries\\n-- Replace table names with actual tables from detection results\\nUPDATE STATISTICS [schema].[table1] WITH FULLSCAN;\\nUPDATE STATISTICS [schema].[table2] WITH FULLSCAN;\\nUPDATE STATISTICS [schema].[table3] WITH FULLSCAN;\\n\\n-- Create multi-column statistics for correlated join columns\\nCREATE STATISTICS [ST_table1_join_cols] ON [schema].[table1] (col1, col2)\\n  WITH FULLSCAN;", "parameters": ["table_names"], "description": "Updates statistics with full scan on join tables and creates multi-column statistics for correlated columns to improve cardinality estimates at join operators."}	{"sql": "DROP STATISTICS [schema].[table1].[ST_table1_join_cols];", "description": "Drop manually created multi-column statistics if they cause plan regression."}	low	t	t	\N	2026-02-24 13:10:27.594819
4507	sqlserver	verify	Check for audit crash evidence in the error log	{"sql": "SELECT sa.name, sa.is_state_enabled, sa.on_failure_desc,\\n  sa.modify_date,\\n  (SELECT sqlserver_start_time FROM sys.dm_os_sys_info) AS last_restart\\nFROM sys.server_audits sa\\nWHERE sa.is_state_enabled = 0;\\n\\nEXEC xp_readerrorlog 0, 1, N'audit';", "parameters": [], "description": "Identifies disabled audits and searches for crash-related audit messages in the error log."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.751025
3935	sqlserver	execute	Create top missing indexes with highest improvement measure	{"sql": "-- Generate CREATE INDEX statements from DMV recommendations\\n-- Review each before executing; do not blindly create all suggestions\\nSELECT\\n  'CREATE NONCLUSTERED INDEX [IX_' + OBJECT_NAME(mid.object_id) + '_' + REPLACE(REPLACE(ISNULL(mid.equality_columns,''), '[', ''), ']', '') + ']'\\n  + ' ON ' + mid.statement\\n  + ' (' + ISNULL(mid.equality_columns, '') + CASE WHEN mid.inequality_columns IS NOT NULL AND mid.equality_columns IS NOT NULL THEN ', ' ELSE '' END + ISNULL(mid.inequality_columns, '') + ')'\\n  + CASE WHEN mid.included_columns IS NOT NULL THEN ' INCLUDE (' + mid.included_columns + ')' ELSE '' END\\n  + ' WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);' AS create_index_statement,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) > 10000\\nORDER BY improvement_measure DESC;", "parameters": [], "description": "Generates CREATE INDEX statements for the most impactful missing indexes. DBA reviews each statement and executes selectively based on workload analysis."}	{"sql": "-- Drop the created index if it causes regression\\nDROP INDEX [IX_index_name] ON [schema].[table_name];", "description": "Drop the newly created index if it causes write performance degradation."}	medium	t	t	\N	2026-02-24 13:10:27.592484
3936	sqlserver	verify	Verify index usage and scan reduction	{"sql": "-- Check that new indexes are being used (seeks > 0)\\nSELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  ius.user_seeks, ius.user_scans, ius.user_lookups,\\n  ius.last_user_seek, ius.last_user_scan\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.name LIKE 'IX_%'\\n  AND ius.user_seeks > 0\\nORDER BY ius.user_seeks DESC;", "parameters": [], "description": "Confirms new indexes are being used for seeks and table scan counts have decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.593046
3937	sqlserver	execute	Update stale statistics with full or high sample rates	{"sql": "-- Update statistics with high modification counters\\nDECLARE @sql NVARCHAR(MAX) = N'';\\nSELECT @sql = @sql + 'UPDATE STATISTICS ' + QUOTENAME(OBJECT_SCHEMA_NAME(s.object_id)) + '.' + QUOTENAME(OBJECT_NAME(s.object_id)) + ' ' + QUOTENAME(s.name) + ' WITH SAMPLE 50 PERCENT;' + CHAR(10)\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 1000\\n  AND (sp.modification_counter > sp.rows * 0.20\\n    OR DATEDIFF(DAY, sp.last_updated, GETDATE()) > 7)\\nORDER BY sp.modification_counter DESC;\\nEXEC sp_executesql @sql;", "parameters": [], "description": "Updates all statistics with >20% modification or older than 7 days using 50% sample rate for better accuracy on large tables."}	null	low	f	t	\N	2026-02-24 13:10:27.593533
3938	sqlserver	configure	Enable auto-update statistics with async option	{"sql": "-- Ensure auto-update statistics is enabled\\nALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS ON;\\n\\n-- Enable async stats update to prevent query blocking during stats refresh\\nALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS_ASYNC ON;\\n\\n-- Enable incremental statistics for partitioned tables (2014+)\\nALTER DATABASE CURRENT SET AUTO_CREATE_STATISTICS ON;", "parameters": [], "description": "Enables auto-update with async option so queries are not blocked waiting for statistics refresh. Auto-create ensures new columns get statistics automatically."}	{"sql": "ALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS_ASYNC OFF;", "description": "Revert async stats update if synchronous behavior is preferred."}	low	f	t	00:01:00	2026-02-24 13:10:27.594035
3939	sqlserver	verify	Verify statistics are current and modification counters are low	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled,\\n  CAST(sp.rows_sampled AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS sample_pct,\\n  sp.modification_counter,\\n  DATEDIFF(MINUTE, sp.last_updated, GETDATE()) AS minutes_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 1000\\nORDER BY sp.modification_counter DESC;", "parameters": [], "description": "Confirms statistics are freshly updated with acceptable sample rates and low modification counters."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.594038
3940	sqlserver	configure	Optimize memory allocation to address buffer pool pressure	{"sql": "-- Set max server memory to leave room for OS (typically 10-20%)\\nDECLARE @total_memory_mb INT = (SELECT physical_memory_kb / 1024 FROM sys.dm_os_sys_info);\\nDECLARE @max_memory_mb INT = @total_memory_mb * 0.85;\\nEXEC sp_configure 'max server memory (MB)', @max_memory_mb;\\nRECONFIGURE;\\n\\n-- Enable lock pages in memory for consistent buffer pool (requires Windows privilege)\\n-- Set via Group Policy: Local Policies > User Rights Assignment > Lock pages in memory", "parameters": [], "description": "Sets max server memory to 85% of physical RAM to prevent OS memory pressure while maximizing buffer pool size."}	{"sql": "-- Revert to previous max memory setting\\nEXEC sp_configure 'max server memory (MB)', @previous_value;\\nRECONFIGURE;", "description": "Revert max server memory to previous value."}	low	t	t	00:01:00	2026-02-24 13:10:27.594038
3944	sqlserver	verify	Verify query performance improved after rewrites	{"sql": "SELECT TOP 20\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.execution_count,\\n  p.query_plan.value('count(//UserDefinedFunction)', 'int') AS udf_count,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert)', 'int') AS convert_warnings,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 10\\nORDER BY qs.total_worker_time DESC;", "parameters": [], "description": "Confirms rewritten queries show lower CPU time, fewer UDF calls, and no implicit conversion warnings in execution plans."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.594039
3945	sqlserver	verify	Verify fragmentation reduced and I/O improved	{"sql": "SELECT\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.avg_page_space_used_in_percent,\\n  ios.page_io_latch_wait_count,\\n  ios.page_io_latch_wait_in_ms\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON ips.object_id = ios.object_id AND ips.index_id = ios.index_id\\nWHERE ips.page_count > 1000 AND i.index_id > 0\\nORDER BY ips.avg_fragmentation_in_percent DESC;", "parameters": [], "description": "Confirms fragmentation is below thresholds and I/O wait times have decreased after index maintenance."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.59404
