3962	sqlserver	verify	Verify reduced compilation times and optimizer timeouts	{"sql": "SELECT TOP 15\\n  qs.sql_handle,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//StmtSimple[@StatementOptmEarlyAbortReason=\\"TimeOut\\"]') AS optimizer_timeout,\\n  p.query_plan.value('count(//RelOp)', 'int') AS plan_operator_count,\\n  qs.execution_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 5\\nORDER BY plan_operator_count DESC;\\n\\n-- Check plan cache efficiency\\nSELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE usecounts = 1) AS single_use_plans,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans) AS total_plans,\\n  (SELECT SUM(size_in_bytes)/1024/1024 FROM sys.dm_exec_cached_plans WHERE usecounts = 1) AS single_use_mb;", "parameters": [], "description": "Confirms optimizer timeouts eliminated, plan operator counts reduced, and single-use plan cache bloat decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.599071
3970	sqlserver	verify	Verify scans converted to seeks on indexed tables	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_seeks, ius.user_scans,\\n  CASE WHEN (ius.user_seeks + ius.user_scans) > 0\\n    THEN CAST(ius.user_seeks AS FLOAT) / (ius.user_seeks + ius.user_scans) * 100\\n    ELSE 0 END AS seek_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id IN (0, 1)\\n  AND (ius.user_seeks + ius.user_scans) > 100\\nORDER BY ius.user_scans DESC;", "parameters": [], "description": "Confirms tables that had full scans now show high seek percentages after index creation."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.601556
3963	sqlserver	configure	Set optimal MAXDOP and cost threshold for parallelism	{"sql": "-- Set MAXDOP based on CPU topology (NUMA nodes and cores)\\n-- For single NUMA: min(8, core_count)\\n-- For multi-NUMA: min(8, cores_per_NUMA)\\nDECLARE @cores_per_numa INT = (\\n  SELECT TOP 1 online_scheduler_count\\n  FROM sys.dm_os_nodes WHERE node_state_desc = 'ONLINE'\\n);\\nDECLARE @maxdop INT = CASE WHEN @cores_per_numa > 8 THEN 8 ELSE @cores_per_numa END;\\n\\nEXEC sp_configure 'max degree of parallelism', @maxdop;\\nRECONFIGURE;\\n\\n-- Raise cost threshold from default 5 to appropriate value\\nEXEC sp_configure 'cost threshold for parallelism', 50;\\nRECONFIGURE;", "parameters": [], "description": "Sets MAXDOP based on NUMA topology and raises cost threshold for parallelism from default 5 to 50, preventing cheap queries from going parallel unnecessarily."}	{"sql": "EXEC sp_configure 'max degree of parallelism', 0;\\nEXEC sp_configure 'cost threshold for parallelism', 5;\\nRECONFIGURE;", "description": "Revert MAXDOP and cost threshold to defaults."}	medium	t	t	00:01:00	2026-02-24 13:10:27.599073
3964	sqlserver	configure	Optimize database-level settings	{"sql": "-- Enable auto-update and auto-create statistics\\nALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS ON;\\nALTER DATABASE CURRENT SET AUTO_CREATE_STATISTICS ON;\\nALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS_ASYNC ON;\\n\\n-- Set compatibility level to current version for latest optimizer improvements\\nALTER DATABASE CURRENT SET COMPATIBILITY_LEVEL = 160;  -- SQL Server 2022\\n\\n-- Set page verify to CHECKSUM\\nALTER DATABASE CURRENT SET PAGE_VERIFY CHECKSUM;", "parameters": [], "description": "Ensures database-level settings are optimal for query performance: auto statistics, current compatibility level, and CHECKSUM page verification."}	{"sql": "ALTER DATABASE CURRENT SET COMPATIBILITY_LEVEL = @previous_level;\\nALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS_ASYNC OFF;", "description": "Revert compatibility level and async stats if issues arise."}	medium	t	t	00:01:00	2026-02-24 13:10:27.599074
3965	sqlserver	verify	Verify configuration changes applied correctly	{"sql": "SELECT c.name, c.value_in_use,\\n  CASE\\n    WHEN c.name = 'max degree of parallelism' AND c.value_in_use BETWEEN 1 AND 8 THEN 'OK'\\n    WHEN c.name = 'cost threshold for parallelism' AND c.value_in_use >= 25 THEN 'OK'\\n    WHEN c.name = 'max server memory (MB)' AND c.value_in_use < 2147483647 THEN 'OK'\\n    WHEN c.name = 'optimize for ad hoc workloads' AND c.value_in_use = 1 THEN 'OK'\\n    ELSE 'REVIEW'\\n  END AS status\\nFROM sys.configurations c\\nWHERE c.name IN ('max degree of parallelism', 'cost threshold for parallelism',\\n  'max server memory (MB)', 'optimize for ad hoc workloads');\\n\\nSELECT name, compatibility_level, is_auto_update_stats_on, is_auto_create_stats_on,\\n  is_auto_update_stats_async_on, page_verify_option_desc\\nFROM sys.databases WHERE database_id = DB_ID();", "parameters": [], "description": "Confirms all server and database configuration settings are set to optimal values."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.599075
3967	sqlserver	execute	Reduce unnecessary scans displacing cache	{"sql": "-- Identify and create indexes for the top queries causing physical reads\\nSELECT TOP 10\\n  qs.sql_handle,\\n  qs.total_physical_reads / NULLIF(qs.execution_count, 0) AS avg_phys_reads,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.execution_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_physical_reads > 10000\\nORDER BY qs.total_physical_reads DESC;\\n\\n-- Focus indexing effort on these queries to convert scans to seeks\\n-- Seeks touch fewer pages, reducing buffer pool churn", "parameters": [], "description": "Identifies the top queries causing physical reads (cache misses) and targets them for index creation or query optimization to reduce buffer pool displacement."}	null	low	t	t	\N	2026-02-24 13:10:27.600604
