3968	sqlserver	verify	Verify buffer cache hit ratio and PLE improved	{"sql": "SELECT\\n  CAST((SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Buffer cache hit ratio') AS FLOAT) /\\n  NULLIF((SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Buffer cache hit ratio base'), 0) * 100 AS cache_hit_ratio_pct,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page life expectancy') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page reads/sec') AS page_reads_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Lazy writes/sec') AS lazy_writes_per_sec;", "parameters": [], "description": "Confirms buffer cache hit ratio increased (target >99%), PLE improved, and physical page reads decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.600902
3969	sqlserver	execute	Create highest-impact missing indexes	{"sql": "-- Generate and execute CREATE INDEX from missing index DMVs\\n-- Prioritize by improvement_measure; review each before creating\\nSELECT\\n  'CREATE NONCLUSTERED INDEX [IX_' + REPLACE(REPLACE(OBJECT_NAME(mid.object_id), '[', ''), ']', '') + '_' + CAST(mig.index_group_handle AS VARCHAR) + ']'\\n  + ' ON ' + mid.statement\\n  + ' (' + ISNULL(mid.equality_columns, '') + CASE WHEN mid.inequality_columns IS NOT NULL AND mid.equality_columns IS NOT NULL THEN ', ' ELSE '' END + ISNULL(mid.inequality_columns, '') + ')'\\n  + CASE WHEN mid.included_columns IS NOT NULL THEN ' INCLUDE (' + mid.included_columns + ')' ELSE '' END\\n  + ' WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);' AS create_statement,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure,\\n  migs.user_seeks, migs.user_scans\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE mid.database_id = DB_ID()\\n  AND migs.user_seeks + migs.user_scans > 100\\nORDER BY improvement_measure DESC;", "parameters": [], "description": "Generates CREATE INDEX statements ranked by improvement measure. DBA reviews for overlapping indexes and executes the top recommendations."}	{"sql": "-- Drop specific index if it causes write regression\\nDROP INDEX [IX_index_name] ON [schema].[table];", "description": "Drop any newly created index that causes write performance degradation."}	medium	t	t	\N	2026-02-24 13:10:27.601237
3971	sqlserver	execute	Create filtered indexes for commonly queried values	{"sql": "-- Create filtered index for the most frequently queried low-cardinality values\\n-- Replace with actual table/column/value from detection results\\nCREATE NONCLUSTERED INDEX IX_table_status_active\\n  ON [schema].[table_name] (other_filter_col)\\n  INCLUDE (frequently_selected_columns)\\n  WHERE status = 'active'\\n  WITH (ONLINE = ON);\\n\\n-- For queries that need all values, create a covering index instead\\nCREATE NONCLUSTERED INDEX IX_table_covering\\n  ON [schema].[table_name] (low_card_col, secondary_col)\\n  INCLUDE (col1, col2, col3)\\n  WITH (ONLINE = ON);", "parameters": ["table_name", "filter_column", "filter_value", "include_columns"], "description": "Creates filtered indexes for specific frequently queried values of low-cardinality columns, or covering indexes that include all needed columns to avoid table access."}	{"sql": "DROP INDEX IX_table_status_active ON [schema].[table_name];\\nDROP INDEX IX_table_covering ON [schema].[table_name];", "description": "Drop the filtered or covering index if not used or causing write overhead."}	medium	t	t	\N	2026-02-24 13:10:27.601829
3973	sqlserver	execute	Create full-text index for substring search columns	{"sql": "-- Create full-text catalog and index\\nCREATE FULLTEXT CATALOG ft_catalog AS DEFAULT;\\n\\nCREATE FULLTEXT INDEX ON [schema].[table_name] (\\n  search_column LANGUAGE 1033\\n) KEY INDEX PK_table_name\\n  ON ft_catalog\\n  WITH (CHANGE_TRACKING AUTO);\\n\\n-- Rewrite queries to use CONTAINS or FREETEXT instead of LIKE\\n-- Before: SELECT * FROM table WHERE col LIKE '%search_term%'\\n-- After: SELECT * FROM table WHERE CONTAINS(col, '\\"search_term\\"')", "parameters": ["table_name", "search_column", "pk_index_name"], "description": "Creates a full-text index on columns that need substring search, enabling efficient word-based matching instead of character-by-character scanning."}	{"sql": "DROP FULLTEXT INDEX ON [schema].[table_name];\\nDROP FULLTEXT CATALOG ft_catalog;", "description": "Remove full-text index and catalog."}	medium	t	t	\N	2026-02-24 13:10:27.602395
3974	sqlserver	verify	Verify full-text queries replace LIKE scans	{"sql": "-- Verify full-text index is populated and active\\nSELECT\\n  OBJECT_NAME(object_id) AS table_name,\\n  is_enabled, change_tracking_state_desc,\\n  has_crawl_completed, crawl_type_desc\\nFROM sys.fulltext_indexes;\\n\\n-- Check that queries no longer use table scans for text search\\nSELECT TOP 10\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE t.text LIKE '%CONTAINS%' OR t.text LIKE '%FREETEXT%'\\nORDER BY qs.total_elapsed_time DESC;", "parameters": [], "description": "Confirms full-text index is populated and active, and text search queries now use CONTAINS/FREETEXT with significantly lower I/O."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.602664
