3993	sqlserver	execute	Identify and remove unused indexes on small tables	{"sql": "-- Identify unused nonclustered indexes on small tables\\nSELECT\\n  'DROP INDEX ' + QUOTENAME(i.name) + ' ON ' + QUOTENAME(OBJECT_SCHEMA_NAME(i.object_id)) + '.' + QUOTENAME(OBJECT_NAME(i.object_id)) + ';' AS drop_statement,\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  p.rows AS table_rows,\\n  ISNULL(ius.user_seeks, 0) AS seeks,\\n  ISNULL(ius.user_scans, 0) AS scans,\\n  ISNULL(ius.user_updates, 0) AS updates\\nFROM sys.indexes i\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id > 1\\n  AND p.rows < 5000\\n  AND (ius.user_seeks IS NULL OR ius.user_seeks = 0)\\n  AND (ius.user_scans IS NULL OR ius.user_scans = 0)\\n  AND i.is_primary_key = 0\\n  AND i.is_unique_constraint = 0\\nORDER BY ISNULL(ius.user_updates, 0) DESC;", "parameters": [], "description": "Generates DROP INDEX statements for unused nonclustered indexes on small tables. These indexes add write overhead without providing read benefit."}	{"sql": "-- Recreate dropped index if needed\\n-- Keep the original CREATE INDEX DDL before dropping", "description": "Recreate the index using the saved DDL statement."}	low	t	t	00:01:00	2026-02-24 13:10:27.607008
3994	sqlserver	verify	Verify small table access is efficient without removed indexes	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  ius.user_scans, ius.user_seeks,\\n  p.rows AS table_rows,\\n  (SELECT COUNT(*) FROM sys.indexes i2\\n   WHERE i2.object_id = ius.object_id AND i2.index_id > 1) AS remaining_nc_indexes\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id IN (0, 1)\\n  AND p.rows < 5000\\nORDER BY ius.user_scans DESC;", "parameters": [], "description": "Confirms small tables are accessed efficiently with scans and unused indexes have been removed."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.607011
3995	sqlserver	execute	Create index with correct leading column for query predicates	{"sql": "-- Create index with the query's WHERE clause column as the leading key\\n-- Replace with actual table/columns from detection results\\nCREATE NONCLUSTERED INDEX IX_table_correct_order\\n  ON [schema].[table_name] (where_clause_col, secondary_col)\\n  INCLUDE (select_columns)\\n  WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);\\n\\n-- Consider dropping the old composite index if it's now redundant\\n-- First verify it's not used by other queries\\nSELECT ius.user_seeks, ius.user_scans, ius.user_lookups\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE i.name = 'IX_old_composite_index' AND ius.database_id = DB_ID();", "parameters": ["table_name", "leading_column", "secondary_columns", "include_columns"], "description": "Creates a new index with the correct leading column that matches the most common WHERE clause predicate, enabling index seeks instead of scans on the composite index."}	{"sql": "DROP INDEX IX_table_correct_order ON [schema].[table_name];", "description": "Drop the new index if it duplicates existing coverage."}	medium	t	t	\N	2026-02-24 13:10:27.607503
3996	sqlserver	verify	Verify new index is used for seeks	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  ius.user_seeks, ius.user_scans,\\n  ius.last_user_seek, ius.last_user_scan\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.name LIKE 'IX_table_correct_order%'\\nORDER BY ius.user_seeks DESC;", "parameters": [], "description": "Confirms the new index is being used for seeks and the old composite index scan count has decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.607788
3997	sqlserver	execute	Create filtered index for NULL value access	{"sql": "-- Create filtered index for IS NULL queries\\nCREATE NONCLUSTERED INDEX IX_table_col_null\\n  ON [schema].[table_name] (nullable_col)\\n  INCLUDE (other_needed_columns)\\n  WHERE nullable_col IS NULL\\n  WITH (ONLINE = ON);\\n\\n-- For IS NOT NULL queries where NULLs are rare\\nCREATE NONCLUSTERED INDEX IX_table_col_not_null\\n  ON [schema].[table_name] (nullable_col)\\n  INCLUDE (other_needed_columns)\\n  WHERE nullable_col IS NOT NULL\\n  WITH (ONLINE = ON);", "parameters": ["table_name", "nullable_column", "include_columns"], "description": "Creates filtered indexes targeting NULL or NOT NULL values, enabling seeks for queries that filter on NULL conditions."}	{"sql": "DROP INDEX IX_table_col_null ON [schema].[table_name];\\nDROP INDEX IX_table_col_not_null ON [schema].[table_name];", "description": "Drop the filtered NULL indexes if not used."}	low	t	t	00:01:00	2026-02-24 13:10:27.607791
3998	sqlserver	verify	Verify NULL queries now use filtered index seeks	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.has_filter, i.filter_definition,\\n  ius.user_seeks, ius.user_scans,\\n  ius.last_user_seek\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.has_filter = 1\\nORDER BY ius.user_seeks DESC;", "parameters": [], "description": "Confirms filtered indexes are being used for seeks on NULL predicate queries."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.607792
