4008	sqlserver	configure	Upgrade compatibility level and enable CE feedback	{"sql": "-- Upgrade to latest compatibility level for improved CE\\nALTER DATABASE CURRENT SET COMPATIBILITY_LEVEL = 160;  -- SQL 2022\\n\\n-- Enable Query Store (required for CE feedback)\\nALTER DATABASE CURRENT SET QUERY_STORE = ON;\\nALTER DATABASE CURRENT SET QUERY_STORE (OPERATION_MODE = READ_WRITE);\\n\\n-- Enable CE feedback (SQL 2022+)\\nALTER DATABASE SCOPED CONFIGURATION SET CE_FEEDBACK = ON;\\n\\n-- Enable memory grant feedback for adaptive grants\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;", "parameters": [], "description": "Upgrades to the latest CE model and enables adaptive feedback mechanisms that automatically correct cardinality estimation errors over time."}	{"sql": "ALTER DATABASE SCOPED CONFIGURATION SET CE_FEEDBACK = OFF;\\nALTER DATABASE CURRENT SET COMPATIBILITY_LEVEL = @previous_level;", "description": "Revert compatibility level and disable CE feedback."}	medium	t	t	00:01:00	2026-02-24 13:10:27.610146
4009	sqlserver	verify	Verify CE improvements and reduced estimation errors	{"sql": "SELECT\\n  d.compatibility_level,\\n  d.is_query_store_on,\\n  (SELECT value FROM sys.database_scoped_configurations WHERE name = 'CE_FEEDBACK') AS ce_feedback,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_stats WHERE total_spills > 0) AS spilling_queries,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_stats\\n   WHERE total_grant_kb / NULLIF(execution_count, 0) > total_ideal_grant_kb / NULLIF(execution_count, 0) * 3\\n     AND execution_count > 5) AS overgranted_queries\\nFROM sys.databases d WHERE d.database_id = DB_ID();", "parameters": [], "description": "Confirms CE feedback is active and spill/overgrant counts are decreasing as the system learns optimal estimates."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.610147
4011	sqlserver	verify	Verify join query performance improved	{"sql": "SELECT TOP 15\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  p.query_plan.exist('//StmtSimple[@StatementOptmEarlyAbortReason=\\"TimeOut\\"]') AS optimizer_timeout,\\n  p.query_plan.value('count(//RelOp)', 'int') AS plan_operators,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 5\\nORDER BY avg_elapsed_ms DESC;", "parameters": [], "description": "Confirms multi-join queries show improved performance with no optimizer timeouts and reduced spill counts."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.610149
4012	sqlserver	execute	Apply appropriate parameter sniffing mitigation	{"sql": "-- Option 1: OPTIMIZE FOR UNKNOWN (median plan)\\nALTER PROCEDURE [schema].[proc_name]\\nAS\\n  SELECT ... FROM ... WHERE col = @param\\n  OPTION (OPTIMIZE FOR (@param UNKNOWN));\\n\\n-- Option 2: OPTION (RECOMPILE) for highly variable queries\\nALTER PROCEDURE [schema].[proc_name]\\nAS\\n  SELECT ... FROM ... WHERE col = @param\\n  OPTION (RECOMPILE);\\n\\n-- Option 3: Enable Parameter Sensitive Plan optimization (SQL 2022+)\\nALTER DATABASE SCOPED CONFIGURATION SET PARAMETER_SENSITIVE_PLAN_OPTIMIZATION = ON;", "parameters": ["procedure_name", "mitigation_strategy"], "description": "Applies the appropriate parameter sniffing mitigation: OPTIMIZE FOR UNKNOWN for median plans, RECOMPILE for highly variable queries, or PSP optimization for SQL 2022+."}	{"sql": "-- Revert procedure to original without hints\\nALTER PROCEDURE [schema].[proc_name]\\nAS\\n  SELECT ... FROM ... WHERE col = @param;", "description": "Remove query hints from the stored procedure."}	medium	t	t	\N	2026-02-24 13:10:27.610835
4013	sqlserver	verify	Verify execution time variance reduced	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(qs.objectid) AS proc_name,\\n  qs.execution_count,\\n  qs.min_elapsed_time / 1000 AS min_elapsed_ms,\\n  qs.max_elapsed_time / 1000 AS max_elapsed_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  CAST(qs.max_elapsed_time AS FLOAT) / NULLIF(qs.min_elapsed_time, 1) AS variance_ratio\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.execution_count > 10\\n  AND OBJECT_NAME(qs.objectid) IS NOT NULL\\nORDER BY variance_ratio DESC;", "parameters": [], "description": "Confirms execution time variance ratio has decreased significantly after parameter sniffing mitigation."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.611083
4014	sqlserver	execute	Rebuild heavily fragmented indexes	{"sql": "DECLARE @sql NVARCHAR(MAX) = N'';\\nSELECT @sql = @sql + 'ALTER INDEX ' + QUOTENAME(i.name) + ' ON ' + QUOTENAME(OBJECT_SCHEMA_NAME(ips.object_id)) + '.' + QUOTENAME(OBJECT_NAME(ips.object_id)) + ' REBUILD WITH (ONLINE = ON, SORT_IN_TEMPDB = ON, MAXDOP = 4);' + CHAR(10)\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND i.index_id > 0\\nORDER BY ips.page_count DESC;\\nEXEC sp_executesql @sql;", "parameters": [], "description": "Rebuilds all indexes with >30% fragmentation. Online rebuild allows concurrent DML. Statistics are automatically updated during rebuild."}	null	medium	t	t	\N	2026-02-24 13:10:27.611349
4015	sqlserver	execute	Comprehensive statistics update with appropriate sample rates	{"sql": "-- Update all statistics on user tables\\nEXEC sp_updatestats;\\n\\n-- For large tables, use higher sample rate\\nDECLARE @sql NVARCHAR(MAX) = N'';\\nSELECT @sql = @sql + 'UPDATE STATISTICS ' + QUOTENAME(OBJECT_SCHEMA_NAME(s.object_id)) + '.' + QUOTENAME(OBJECT_NAME(s.object_id)) + ' WITH SAMPLE 50 PERCENT;' + CHAR(10)\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 1000000\\n  AND CAST(sp.rows_sampled AS FLOAT) / NULLIF(sp.rows, 0) < 0.1\\nGROUP BY s.object_id;\\nEXEC sp_executesql @sql;", "parameters": [], "description": "Updates all statistics via sp_updatestats, then specifically targets large tables with low sample rates for a higher-quality sample."}	null	low	f	t	\N	2026-02-24 13:10:27.611352
