4176	sqlserver	verify	Verify sort count reduced and spills eliminated	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Sort\\"])', 'int') AS sort_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 1\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Confirms that sort count has decreased and spills are eliminated."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.611808
4019	sqlserver	verify	Check for plan regressions after compatibility level change	{"sql": "-- Find regressed queries comparing before/after compat level change\\nSELECT TOP 20\\n  qsq.query_id,\\n  qt.query_sql_text,\\n  COUNT(DISTINCT qsp.plan_id) AS plan_count,\\n  MIN(qsrs.avg_duration) / 1000.0 AS best_avg_ms,\\n  MAX(qsrs.avg_duration) / 1000.0 AS worst_avg_ms,\\n  MAX(qsrs.avg_duration) / NULLIF(MIN(qsrs.avg_duration), 0) AS regression_ratio\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nJOIN sys.query_store_query_text qt ON qsq.query_text_id = qt.query_text_id\\nWHERE qsrs.count_executions > 10\\nGROUP BY qsq.query_id, qt.query_sql_text\\nHAVING COUNT(DISTINCT qsp.plan_id) > 1\\n  AND MAX(qsrs.avg_duration) / NULLIF(MIN(qsrs.avg_duration), 0) > 2\\nORDER BY regression_ratio DESC;", "parameters": [], "description": "Identifies queries that regressed after the compatibility level change. Force the better plan for any significant regressions."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.611808
4020	sqlserver	configure	Set optimal cost parameters and remove incorrect overrides	{"sql": "-- Set cost threshold based on workload\\nEXEC sp_configure 'cost threshold for parallelism', 50;\\nRECONFIGURE;\\n\\n-- Set MAXDOP based on NUMA topology\\nDECLARE @cores INT = (SELECT TOP 1 online_scheduler_count FROM sys.dm_os_nodes WHERE node_state_desc = 'ONLINE');\\nEXEC sp_configure 'max degree of parallelism', CASE WHEN @cores > 8 THEN 8 ELSE @cores END;\\nRECONFIGURE;\\n\\n-- Remove forced legacy CE if inappropriate\\nALTER DATABASE SCOPED CONFIGURATION SET LEGACY_CARDINALITY_ESTIMATION = OFF;\\n\\n-- Enable optimizer hotfixes\\nALTER DATABASE SCOPED CONFIGURATION SET QUERY_OPTIMIZER_HOTFIXES = ON;\\n\\n-- Remove restrictive plan guides that may be outdated\\n-- SELECT * FROM sys.plan_guides WHERE is_disabled = 0;", "parameters": [], "description": "Sets optimal cost threshold, MAXDOP, and removes any database-scoped overrides that force legacy behavior or prevent optimizer improvements."}	{"sql": "EXEC sp_configure 'cost threshold for parallelism', 5;\\nEXEC sp_configure 'max degree of parallelism', 0;\\nRECONFIGURE;\\nALTER DATABASE SCOPED CONFIGURATION SET QUERY_OPTIMIZER_HOTFIXES = OFF;", "description": "Revert to default cost parameters."}	medium	t	t	00:01:00	2026-02-24 13:10:27.611809
