4032	sqlserver	execute	Create filtered indexes for common query patterns	{"sql": "-- Create filtered index for the most common subset queries\\n-- Replace with actual table/column/filter from detection results\\nCREATE NONCLUSTERED INDEX IX_table_active_records\\n  ON [schema].[table_name] (secondary_filter_col)\\n  INCLUDE (frequently_selected_columns)\\n  WHERE status = 'active'\\n  WITH (ONLINE = ON);\\n\\n-- Create filtered statistics for the subset\\nCREATE STATISTICS ST_table_active\\n  ON [schema].[table_name] (secondary_filter_col)\\n  WHERE status = 'active'\\n  WITH FULLSCAN;", "parameters": ["table_name", "filter_predicate", "key_columns", "include_columns"], "description": "Creates filtered indexes and statistics for frequently queried data subsets, enabling the optimizer to use highly selective access paths for these queries."}	{"sql": "DROP INDEX IX_table_active_records ON [schema].[table_name];\\nDROP STATISTICS [schema].[table_name].[ST_table_active];", "description": "Drop the filtered index and statistics."}	medium	t	t	\N	2026-02-24 13:10:27.615252
