4034	sqlserver	execute	Update statistics with FULLSCAN and create filtered stats	{"sql": "-- Update with FULLSCAN for maximum histogram resolution\\nUPDATE STATISTICS [schema].[table_name] WITH FULLSCAN;\\n\\n-- Create filtered statistics for commonly used IN clause value ranges\\nCREATE STATISTICS ST_table_frequent_values\\n  ON [schema].[table_name] (skewed_column)\\n  WHERE skewed_column IN ('value1', 'value2', 'value3')\\n  WITH FULLSCAN;\\n\\n-- For date-based skew, create statistics on recent date ranges\\nCREATE STATISTICS ST_table_recent_dates\\n  ON [schema].[table_name] (date_column)\\n  WHERE date_column >= DATEADD(MONTH, -3, GETDATE())\\n  WITH FULLSCAN;", "parameters": ["table_name", "skewed_column", "frequent_values"], "description": "Updates statistics with FULLSCAN for maximum histogram steps and creates filtered statistics for commonly queried value ranges with skewed distribution."}	{"sql": "DROP STATISTICS [schema].[table_name].[ST_table_frequent_values];\\nDROP STATISTICS [schema].[table_name].[ST_table_recent_dates];", "description": "Drop the filtered statistics."}	low	f	t	\N	2026-02-24 13:10:27.615962
4035	sqlserver	verify	Verify improved histogram coverage and query performance	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.has_filter, s.filter_definition,\\n  sp.rows, sp.steps AS histogram_steps,\\n  sp.rows_sampled,\\n  sp.last_updated\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\n  AND sp.rows > 10000\\nORDER BY sp.steps DESC;", "parameters": [], "description": "Confirms statistics have maximum histogram steps and filtered statistics exist for skewed value ranges."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.616253
4036	sqlserver	execute	Apply parameter sniffing mitigation to affected procedures	{"sql": "-- Option 1: OPTIMIZE FOR UNKNOWN (best for high-frequency procs)\\n-- Generates a plan based on average density, not sniffed values\\nALTER PROCEDURE [schema].[proc_name]\\n  @param1 INT,\\n  @param2 NVARCHAR(100)\\nAS\\nBEGIN\\n  SELECT cols FROM table\\n  WHERE col1 = @param1 AND col2 = @param2\\n  OPTION (OPTIMIZE FOR (@param1 UNKNOWN, @param2 UNKNOWN));\\nEND;\\n\\n-- Option 2: RECOMPILE (best for low-frequency, high-variance procs)\\n-- Compiles a new plan each time, always optimal for current parameters\\n-- ALTER PROCEDURE [schema].[proc_name] WITH RECOMPILE\\n\\n-- Option 3: Local variable copy (moderate mitigation)\\n-- DECLARE @local_param1 INT = @param1;\\n-- SELECT ... WHERE col1 = @local_param1;", "parameters": ["procedure_name", "parameter_names"], "description": "Modifies affected stored procedures with appropriate parameter sniffing mitigation. OPTIMIZE FOR UNKNOWN produces a median plan suitable for most parameter values."}	{"sql": "-- Revert to original procedure without hints\\nALTER PROCEDURE [schema].[proc_name]\\n  @param1 INT, @param2 NVARCHAR(100)\\nAS\\nBEGIN\\n  SELECT cols FROM table WHERE col1 = @param1 AND col2 = @param2;\\nEND;", "description": "Remove parameter sniffing mitigation hints."}	medium	t	t	\N	2026-02-24 13:10:27.616494
4037	sqlserver	verify	Verify consistent execution times across parameter values	{"sql": "SELECT\\n  OBJECT_NAME(qs.objectid) AS proc_name,\\n  qs.execution_count,\\n  qs.min_elapsed_time / 1000 AS min_ms,\\n  qs.max_elapsed_time / 1000 AS max_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_ms,\\n  CAST(qs.max_elapsed_time AS FLOAT) / NULLIF(qs.min_elapsed_time, 1) AS variance_ratio\\nFROM sys.dm_exec_query_stats qs\\nWHERE OBJECT_NAME(qs.objectid) IS NOT NULL\\n  AND qs.execution_count > 10\\nORDER BY variance_ratio DESC;", "parameters": [], "description": "Confirms execution time variance is significantly reduced after parameter sniffing mitigation."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.616758
4038	sqlserver	configure	Enable Parameter Sensitive Plan optimization or apply RECOMPILE	{"sql": "-- SQL Server 2022+: Enable PSP optimization\\nALTER DATABASE SCOPED CONFIGURATION SET PARAMETER_SENSITIVE_PLAN_OPTIMIZATION = ON;\\n\\n-- Enable Query Store for PSP persistence\\nALTER DATABASE CURRENT SET QUERY_STORE = ON;\\nALTER DATABASE CURRENT SET QUERY_STORE (OPERATION_MODE = READ_WRITE);\\n\\n-- For pre-2022: Use plan guide to add RECOMPILE without code changes\\nEXEC sp_create_plan_guide\\n  @name = N'PG_proc_recompile',\\n  @stmt = N'SELECT ... FROM ... WHERE col = @param',\\n  @type = N'OBJECT',\\n  @module_or_batch = N'[schema].[proc_name]',\\n  @hints = N'OPTION (RECOMPILE)';", "parameters": ["procedure_name"], "description": "Enables PSP optimization (SQL 2022+) for automatic multi-plan variants, or creates plan guides to add RECOMPILE hints without modifying stored procedure code."}	{"sql": "ALTER DATABASE SCOPED CONFIGURATION SET PARAMETER_SENSITIVE_PLAN_OPTIMIZATION = OFF;\\nEXEC sp_control_plan_guide @operation = N'DROP', @name = N'PG_proc_recompile';", "description": "Disable PSP optimization and drop plan guide."}	medium	t	t	00:01:00	2026-02-24 13:10:27.616761
4039	sqlserver	verify	Verify multiple plan variants or consistent recompilation	{"sql": "-- Check for multiple plan variants in Query Store (PSP)\\nSELECT\\n  OBJECT_NAME(qsq.object_id) AS proc_name,\\n  COUNT(DISTINCT qsp.plan_id) AS plan_variants,\\n  MIN(qsrs.avg_duration) / 1000.0 AS best_avg_ms,\\n  MAX(qsrs.avg_duration) / 1000.0 AS worst_avg_ms,\\n  SUM(qsrs.count_executions) AS total_execs\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nWHERE qsq.object_id > 0\\n  AND qsrs.count_executions > 5\\nGROUP BY qsq.object_id\\nORDER BY plan_variants DESC;", "parameters": [], "description": "Confirms PSP is generating multiple plan variants or RECOMPILE is producing consistent performance across parameter ranges."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.616762
4040	sqlserver	execute	Force the best plan variant in Query Store	{"sql": "-- Identify the best plan for the affected query\\nSELECT\\n  qsq.query_id,\\n  qsp.plan_id,\\n  qsrs.avg_duration / 1000.0 AS avg_duration_ms,\\n  qsrs.avg_logical_io_reads,\\n  qsrs.count_executions,\\n  CAST(qsp.query_plan AS XML).value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"])', 'int') AS nl_joins,\\n  CAST(qsp.query_plan AS XML).value('count(//RelOp[@PhysicalOp=\\"Hash Match\\"])', 'int') AS hash_joins\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nWHERE qsq.object_id = OBJECT_ID('[schema].[proc_name]')\\n  AND qsrs.count_executions > 5\\nORDER BY qsrs.avg_duration;\\n\\n-- Force the best plan\\nEXEC sp_query_store_force_plan @query_id = @best_query_id, @plan_id = @best_plan_id;", "parameters": ["query_id", "plan_id"], "description": "Identifies the best-performing plan variant from Query Store and forces it for consistent execution."}	{"sql": "EXEC sp_query_store_unforce_plan @query_id = @query_id, @plan_id = @plan_id;", "description": "Unforce the plan to let the optimizer choose freely."}	medium	t	t	00:01:00	2026-02-24 13:10:27.616762
4099	sqlserver	verify	Verify reduced per-row execution cost	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN qs.total_rows > 0\\n    THEN qs.total_logical_reads / qs.total_rows ELSE 0 END AS reads_per_row,\\n  p.query_plan.exist('//ScalarOperator/Subquery') AS has_scalar_subquery\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC;", "parameters": [], "description": "Confirms that reads_per_row has decreased dramatically and scalar subqueries are eliminated from the plan."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.630324
4042	sqlserver	execute	Create covering index to make seek path efficient for all selectivities	{"sql": "-- Create covering index that eliminates key lookups\\n-- This makes the seek plan efficient even for high-selectivity parameters\\nCREATE NONCLUSTERED INDEX IX_table_covering_seek\\n  ON [schema].[table_name] (filter_column)\\n  INCLUDE (all_selected_columns)\\n  WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);\\n\\n-- For low-frequency procedures, add RECOMPILE for per-execution optimization\\n-- ALTER PROCEDURE [schema].[proc_name]\\n-- AS ... OPTION (RECOMPILE);", "parameters": ["table_name", "filter_column", "include_columns"], "description": "Creates a covering index that makes the index seek path efficient by eliminating key lookups, reducing the cost difference between seek and scan paths."}	{"sql": "DROP INDEX IX_table_covering_seek ON [schema].[table_name];", "description": "Drop the covering index."}	medium	t	t	\N	2026-02-24 13:10:27.617461
4043	sqlserver	verify	Verify consistent performance across parameter values	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.min_logical_reads, qs.max_logical_reads,\\n  qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) AS reads_ratio,\\n  qs.min_elapsed_time / 1000 AS min_ms, qs.max_elapsed_time / 1000 AS max_ms,\\n  qs.execution_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 10\\nORDER BY qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) DESC;", "parameters": [], "description": "Confirms the reads ratio between best and worst executions has decreased significantly."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.617739
4044	sqlserver	configure	Enable memory grant feedback and Query Store	{"sql": "-- Enable Query Store for persistent feedback\\nALTER DATABASE CURRENT SET QUERY_STORE = ON;\\nALTER DATABASE CURRENT SET QUERY_STORE (OPERATION_MODE = READ_WRITE);\\n\\n-- Enable memory grant feedback\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;\\n\\n-- SQL 2022: Enable percentile-based feedback for variable workloads\\n-- ALTER DATABASE SCOPED CONFIGURATION SET MEMORY_GRANT_FEEDBACK_PERCENTILE_GRANT = ON;\\n\\n-- Increase min memory per query as safety net\\nEXEC sp_configure 'min memory per query (KB)', 2048;\\nRECONFIGURE;", "parameters": [], "description": "Enables all available memory grant feedback mechanisms to automatically learn correct grant sizes across diverse parameter values."}	{"sql": "ALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = OFF;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = OFF;\\nEXEC sp_configure 'min memory per query (KB)', 1024;\\nRECONFIGURE;", "description": "Disable memory grant feedback and revert min memory per query."}	low	t	t	00:01:00	2026-02-24 13:10:27.617742
4045	sqlserver	verify	Verify spill reduction over time	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  CASE WHEN qs.total_grant_kb > 0\\n    THEN CAST(qs.total_used_grant_kb AS FLOAT) / qs.total_grant_kb * 100\\n    ELSE 0 END AS grant_utilization_pct,\\n  qs.execution_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_grant_kb > 0\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Confirms spill counts trending to zero and grant utilization approaching 100% as feedback learns optimal sizes."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.617743
4046	sqlserver	execute	Create multi-column statistics for correlated predicate columns	{"sql": "-- Create multi-column statistics for correlated WHERE clause columns\\n-- Replace with actual table/columns from detection results\\nCREATE STATISTICS ST_table_correlated_cols\\n  ON [schema].[table_name] (date_column, status_column)\\n  WITH FULLSCAN;\\n\\nCREATE STATISTICS ST_table_correlated_cols2\\n  ON [schema].[table_name] (category_column, region_column)\\n  WITH FULLSCAN;\\n\\n-- Also update existing statistics for consistency\\nUPDATE STATISTICS [schema].[table_name] WITH FULLSCAN;", "parameters": ["table_name", "correlated_columns"], "description": "Creates multi-column statistics for column pairs where the values are correlated (e.g., date and status, where recent records are more likely to be 'active')."}	{"sql": "DROP STATISTICS [schema].[table_name].[ST_table_correlated_cols];\\nDROP STATISTICS [schema].[table_name].[ST_table_correlated_cols2];", "description": "Drop the multi-column statistics."}	low	f	t	\N	2026-02-24 13:10:27.618199
4047	sqlserver	verify	Verify improved estimation for correlated predicates	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 10\\n  AND t.text LIKE '%AND%AND%'\\nORDER BY avg_elapsed_ms DESC;", "parameters": [], "description": "Confirms queries with multiple AND predicates show improved performance and reduced spills after multi-column statistics creation."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.618451
4055	sqlserver	verify	Verify plan cache efficiency improved	{"sql": "SELECT\\n  COUNT(*) AS total_plans,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans,\\n  CAST(SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(COUNT(*), 0) * 100 AS single_use_pct,\\n  SUM(CASE WHEN usecounts = 1 THEN size_in_bytes ELSE 0 END) / 1024 / 1024 AS single_use_mb,\\n  SUM(size_in_bytes) / 1024 / 1024 AS total_cache_mb\\nFROM sys.dm_exec_cached_plans\\nWHERE cacheobjtype = 'Compiled Plan';", "parameters": [], "description": "Confirms single-use plan percentage and memory usage have decreased after enabling optimize for ad hoc workloads."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.619177
4048	sqlserver	configure	Adjust cost threshold and apply targeted MAXDOP hints	{"sql": "-- If expensive queries are running serial, lower cost threshold\\n-- Check current vs needed\\nSELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cost threshold for parallelism') AS current_threshold;\\n\\n-- Adjust based on workload (ensure expensive queries exceed threshold)\\nEXEC sp_configure 'cost threshold for parallelism', 25;\\nRECONFIGURE;\\n\\n-- For specific queries that need parallelism override\\n-- Use plan guide to add MAXDOP hint without code changes\\nEXEC sp_create_plan_guide\\n  @name = N'PG_force_parallel',\\n  @stmt = N'SELECT ... expensive query text ...',\\n  @type = N'SQL',\\n  @module_or_batch = NULL,\\n  @params = NULL,\\n  @hints = N'OPTION (MAXDOP 4)';", "parameters": [], "description": "Adjusts cost threshold to ensure expensive queries qualify for parallel execution and uses plan guides for targeted MAXDOP overrides."}	{"sql": "EXEC sp_configure 'cost threshold for parallelism', @previous_value;\\nRECONFIGURE;\\nEXEC sp_control_plan_guide @operation = N'DROP', @name = N'PG_force_parallel';", "description": "Revert cost threshold and drop plan guide."}	medium	t	t	00:01:00	2026-02-24 13:10:27.618454
