4104	sqlserver	instruct	Rewrite ORDER BY subquery as JOIN with sort column	{"sql": "-- BEFORE: ORDER BY correlated subquery\\n-- SELECT o.id, o.total\\n-- FROM orders o\\n-- ORDER BY (SELECT c.priority FROM customers c WHERE c.id = o.cust_id)\\n\\n-- AFTER: JOIN to get sort column, then ORDER BY the joined column\\nSELECT o.id, o.total\\nFROM orders o\\nLEFT JOIN customers c ON c.id = o.cust_id\\nORDER BY c.priority;\\n\\n-- For complex sort expressions, use CTE or derived table:\\nWITH order_with_sort AS (\\n  SELECT o.id, o.total, c.priority AS sort_col\\n  FROM orders o\\n  LEFT JOIN customers c ON c.id = o.cust_id\\n)\\nSELECT id, total\\nFROM order_with_sort\\nORDER BY sort_col;", "parameters": ["affected_queries"], "description": "Replace the correlated subquery in ORDER BY with a JOIN that brings the sort column into the main query, allowing the optimizer to plan the sort efficiently."}	null	medium	t	t	\N	2026-02-24 13:10:27.632231
