4106	sqlserver	instruct	Rewrite HAVING correlated subquery as JOIN or CTE	{"sql": "-- BEFORE: HAVING with correlated subquery\\n-- SELECT department_id, COUNT(*) AS emp_count\\n-- FROM employees e\\n-- GROUP BY department_id\\n-- HAVING COUNT(*) > (\\n--   SELECT AVG(dept_size) FROM (\\n--     SELECT COUNT(*) AS dept_size FROM employees GROUP BY department_id\\n--   ) avg_sizes\\n-- )\\n\\n-- AFTER: CTE with pre-computed threshold\\nWITH dept_counts AS (\\n  SELECT department_id, COUNT(*) AS emp_count\\n  FROM employees\\n  GROUP BY department_id\\n),\\navg_size AS (\\n  SELECT AVG(emp_count) AS avg_count FROM dept_counts\\n)\\nSELECT dc.department_id, dc.emp_count\\nFROM dept_counts dc\\nCROSS JOIN avg_size a\\nWHERE dc.emp_count > a.avg_count;", "parameters": ["affected_queries"], "description": "Replace HAVING correlated subqueries with CTEs or derived tables that pre-compute the comparison value, then join against the grouped result for filtering."}	null	medium	t	t	\N	2026-02-24 13:10:27.632833
