4116	sqlserver	instruct	Replace table variables with temp tables or add RECOMPILE	{"sql": "-- BEFORE: table variable with poor cardinality estimation\\n-- DECLARE @ids TABLE (id INT)\\n-- INSERT INTO @ids SELECT id FROM source WHERE condition\\n-- SELECT o.* FROM orders o\\n-- WHERE o.id IN (SELECT id FROM @ids)  -- estimated as 1 row\\n\\n-- AFTER Option A: temp table with statistics\\nCREATE TABLE #ids (id INT PRIMARY KEY);\\nINSERT INTO #ids SELECT id FROM source WHERE condition;\\nSELECT o.* FROM orders o\\nWHERE o.id IN (SELECT id FROM #ids);\\nDROP TABLE #ids;\\n\\n-- AFTER Option B: OPTION (RECOMPILE) for table variable deferred compile\\nDECLARE @ids TABLE (id INT PRIMARY KEY);\\nINSERT INTO @ids SELECT id FROM source WHERE condition;\\nSELECT o.* FROM orders o\\nWHERE o.id IN (SELECT id FROM @ids)\\nOPTION (RECOMPILE);  -- gets accurate cardinality at execution time\\n\\n-- SQL 2019+: enable table variable deferred compilation\\nALTER DATABASE SCOPED CONFIGURATION SET DEFERRED_COMPILATION_TV = ON;", "parameters": ["affected_procedures"], "description": "Replace table variables with temp tables when they hold more than ~100 rows. Temp tables maintain statistics that enable accurate cardinality estimation. Alternatively, use OPTION (RECOMPILE) or enable deferred compilation (SQL 2019+)."}	null	medium	t	t	\N	2026-02-24 13:10:27.637214
