4122	sqlserver	execute	Update statistics with full scan on affected tables	{"sql": "-- Update statistics on tables involved in correlated subqueries\\nUPDATE STATISTICS [schema].[outer_table] WITH FULLSCAN;\\nUPDATE STATISTICS [schema].[inner_table] WITH FULLSCAN;\\n\\n-- Enable auto-update with lower threshold for large tables\\nALTER DATABASE SCOPED CONFIGURATION SET AUTO_CREATE_STATISTICS = ON;\\n\\n-- For SQL 2016+: enable incremental statistics for partitioned tables\\n-- UPDATE STATISTICS [schema].[large_table] WITH FULLSCAN, INCREMENTAL = ON;\\n\\n-- Verify statistics are fresh:\\nSELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled,\\n  CAST(sp.rows_sampled * 100.0 / NULLIF(sp.rows, 0) AS DECIMAL(5,1)) AS sample_pct,\\n  sp.modification_counter\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE OBJECT_NAME(s.object_id) IN ('outer_table', 'inner_table')\\nORDER BY sp.last_updated DESC;", "parameters": ["outer_table", "inner_table"], "description": "Updates statistics with full scan to provide the optimizer with accurate data distribution information for cardinality estimation in correlated subqueries."}	null	low	f	t	\N	2026-02-24 13:10:27.638821
