4143	sqlserver	execute	Create filtered statistics for high-frequency values	{"sql": "-- Identify high-frequency values causing skew\\nSELECT TOP 10\\n  join_column, COUNT(*) AS frequency,\\n  CAST(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM [schema].[table_name]) AS DECIMAL(5,2)) AS pct\\nFROM [schema].[table_name]\\nGROUP BY join_column\\nORDER BY COUNT(*) DESC;\\n\\n-- Create filtered statistics for high-frequency values\\nCREATE STATISTICS ST_table_high_freq_value\\n  ON [schema].[table_name] (join_column)\\n  WHERE join_column = 'high_frequency_value'\\n  WITH FULLSCAN;\\n\\n-- Update all statistics with full scan\\nUPDATE STATISTICS [schema].[table_name] WITH FULLSCAN;\\n\\n-- Create multi-column statistics if correlated with other columns\\nCREATE STATISTICS ST_table_multi_col\\n  ON [schema].[table_name] (join_column, secondary_column)\\n  WITH FULLSCAN;", "parameters": ["table_name", "join_column", "high_frequency_values"], "description": "Creates filtered statistics for known high-frequency values and multi-column statistics to capture data distribution correlations that affect join cardinality estimates."}	{"sql": "DROP STATISTICS [schema].[table_name].ST_table_high_freq_value;\\nDROP STATISTICS [schema].[table_name].ST_table_multi_col;", "description": "Drop the created statistics."}	low	f	t	\N	2026-02-24 13:10:27.645197
