4149	sqlserver	execute	Create composite index with join columns as leading keys	{"sql": "-- Create composite index with correct key order\\n-- Join columns first, then filter columns\\nCREATE NONCLUSTERED INDEX IX_table_composite_join\\n  ON [schema].[table_name] (join_col1, join_col2, filter_col)\\n  INCLUDE (selected_columns)\\n  WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);\\n\\n-- If an existing index has wrong column order, drop and recreate:\\n-- DROP INDEX IX_table_old_index ON [schema].[table_name];\\n-- CREATE NONCLUSTERED INDEX IX_table_new_index\\n--   ON [schema].[table_name] (correct_leading_col, secondary_col)\\n--   INCLUDE (...);\\n\\n-- Verify the new index is used:\\nSELECT\\n  i.name AS index_name,\\n  STRING_AGG(COL_NAME(ic.object_id, ic.column_id), ', ')\\n    WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_columns\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\nWHERE i.object_id = OBJECT_ID('[schema].[table_name]')\\n  AND ic.is_included_column = 0\\nGROUP BY i.name;", "parameters": ["table_name", "join_columns", "filter_columns", "include_columns"], "description": "Creates a composite index where the join predicate columns are the leftmost keys, matching the order used in the ON clause."}	{"sql": "DROP INDEX IF EXISTS IX_table_composite_join ON [schema].[table_name];", "description": "Drop the created index."}	medium	t	t	\N	2026-02-24 13:10:27.648588
