4161	sqlserver	execute	Update statistics and create multi-column statistics for GROUP BY columns	{"sql": "-- Update statistics with full scan for accurate distinct counts\\nUPDATE STATISTICS [schema].[table_name] WITH FULLSCAN;\\n\\n-- Create multi-column statistics for GROUP BY column combinations\\nCREATE STATISTICS ST_table_group_cols\\n  ON [schema].[table_name] (group_col1, group_col2)\\n  WITH FULLSCAN;\\n\\n-- Enable memory grant feedback\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;\\n\\n-- SQL 2022: percentile-based feedback for variable cardinality\\n-- ALTER DATABASE SCOPED CONFIGURATION SET MEMORY_GRANT_FEEDBACK_PERCENTILE_GRANT = ON;", "parameters": ["table_name", "group_columns"], "description": "Updates statistics with full scan to provide accurate distinct value counts for GROUP BY columns. Creates multi-column statistics for correlated grouping columns."}	{"sql": "DROP STATISTICS [schema].[table_name].ST_table_group_cols;", "description": "Drop the created statistics."}	low	f	t	\N	2026-02-24 13:10:27.650326
