4153	sqlserver	configure	Configure parallelism to enable bitmap filters	{"sql": "-- Ensure parallelism is enabled (bitmap filters require parallel plans)\\nEXEC sp_configure 'max degree of parallelism', 4;  -- or appropriate value\\nRECONFIGURE;\\n\\n-- Set cost threshold to allow large queries to go parallel\\nEXEC sp_configure 'cost threshold for parallelism', 25;\\nRECONFIGURE;\\n\\n-- Enable batch mode on rowstore (SQL 2019+) for better bitmap usage\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_ON_ROWSTORE = ON;\\n\\n-- For specific queries, force parallelism if needed:\\n-- SELECT * FROM t1 INNER JOIN t2 ON t1.id = t2.ref_id\\n-- OPTION (QUERYTRACEON 8649);  -- force parallel plan\\n\\n-- Verify bitmap operators appear in plans:\\nSELECT TOP 5\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Bitmap\\"]') AS has_bitmap,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') = 1\\nORDER BY qs.total_logical_reads DESC;", "parameters": [], "description": "Configures parallelism settings to enable bitmap filters on hash joins. Bitmap filters are only available in parallel plans."}	{"sql": "EXEC sp_configure 'max degree of parallelism', 0;\\nEXEC sp_configure 'cost threshold for parallelism', 5;\\nRECONFIGURE;", "description": "Revert parallelism settings to defaults."}	low	t	t	00:01:00	2026-02-24 13:10:27.65069
4665	sqlserver	verify	Confirm broad rootcause grants are removed	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  CASE dp.class_desc WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id) ELSE DB_NAME() END AS scope\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'rootcause' AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc IN ('SCHEMA', 'DATABASE')\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE', 'ALTER', 'CONTROL', 'CREATE TABLE', 'ALTER ANY SCHEMA');", "parameters": [], "description": "Verifies no broad rootcause grants remain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.774948
4154	sqlserver	verify	Verify bitmap operators appear in hash join plans	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Bitmap\\"]') AS has_bitmap,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and @Parallel=\\"true\\"]') AS parallel_hash\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') = 1\\n  AND qs.execution_count > 1\\nORDER BY qs.total_logical_reads DESC;", "parameters": [], "description": "Confirms that bitmap operators appear in parallel hash join plans and probe-side reads have decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.650693
4155	sqlserver	configure	Set optimal MAXDOP and cost threshold values	{"sql": "-- Check current CPU configuration\\nSELECT\\n  cpu_count, scheduler_count,\\n  hyperthread_ratio,\\n  cpu_count / hyperthread_ratio AS physical_cores,\\n  numa_node_count\\nFROM sys.dm_os_sys_info;\\n\\n-- Set MAXDOP based on CPU layout:\\n-- Single NUMA node: min(8, physical_cores)\\n-- Multiple NUMA nodes: min(8, cores_per_numa_node)\\nEXEC sp_configure 'max degree of parallelism', 4;  -- adjust based on above\\nRECONFIGURE;\\n\\n-- Raise cost threshold (default 5 is too low for OLTP)\\nEXEC sp_configure 'cost threshold for parallelism', 50;\\nRECONFIGURE;\\n\\n-- Verify settings\\nSELECT name, value_in_use\\nFROM sys.configurations\\nWHERE name IN ('max degree of parallelism', 'cost threshold for parallelism');", "parameters": [], "description": "Sets MAXDOP to an appropriate value based on CPU topology and raises the cost threshold for parallelism to prevent small queries from going parallel unnecessarily."}	{"sql": "EXEC sp_configure 'max degree of parallelism', 0;\\nEXEC sp_configure 'cost threshold for parallelism', 5;\\nRECONFIGURE;", "description": "Revert to default settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.650694
4156	sqlserver	verify	Verify CXPACKET waits decreased	{"sql": "SELECT\\n  ws.wait_type,\\n  ws.waiting_tasks_count,\\n  ws.wait_time_ms,\\n  ws.wait_time_ms - ws.signal_wait_time_ms AS resource_wait_ms,\\n  CAST(ws.wait_time_ms AS FLOAT) /\\n    NULLIF((SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats\\n      WHERE wait_type NOT LIKE '%SLEEP%' AND wait_type NOT LIKE '%IDLE%'\\n      AND wait_type NOT LIKE '%BROKER%' AND wait_type NOT LIKE '%TIMER%'), 0) * 100 AS pct_of_total\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type IN ('CXPACKET', 'CXCONSUMER')\\nORDER BY ws.wait_time_ms DESC;", "parameters": [], "description": "Confirms that CXPACKET/CXCONSUMER waits have decreased as a percentage of total waits after the configuration change."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.650694
4157	sqlserver	configure	Enable memory grant feedback and update statistics	{"sql": "-- Enable Query Store (required for memory grant feedback)\\nALTER DATABASE CURRENT SET QUERY_STORE = ON;\\nALTER DATABASE CURRENT SET QUERY_STORE (OPERATION_MODE = READ_WRITE);\\n\\n-- Enable memory grant feedback\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;\\n\\n-- Update statistics on tables involved in sort spills\\nUPDATE STATISTICS [schema].[table_name] WITH FULLSCAN;\\n\\n-- Increase min memory per query if needed\\nEXEC sp_configure 'min memory per query (KB)', 2048;\\nRECONFIGURE;\\n\\n-- Check resource semaphore for memory grant contention\\nSELECT * FROM sys.dm_exec_query_resource_semaphores\\nWHERE resource_semaphore_id = 0;", "parameters": ["table_name"], "description": "Enables memory grant feedback to adaptively size grants, updates statistics for accurate estimates, and checks for memory grant contention."}	{"sql": "EXEC sp_configure 'min memory per query (KB)', 1024;\\nRECONFIGURE;", "description": "Revert min memory per query to default."}	low	t	t	\N	2026-02-24 13:10:27.651282
4158	sqlserver	verify	Verify sort spills eliminated	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Sort\\"]') AS has_sort\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Sort\\"]') = 1\\n  AND qs.execution_count > 1\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Confirms that sort spills have been eliminated and grants are closer to ideal values."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.651561
4159	sqlserver	instruct	Add pre-filtering predicates and restructure to reduce intermediate results	{"sql": "-- BEFORE: large intermediate result from unfiltered join\\n-- SELECT * FROM large_table1 l1\\n-- JOIN large_table2 l2 ON l1.id = l2.ref_id\\n-- ORDER BY l1.created_date\\n\\n-- AFTER: add WHERE predicates to reduce intermediate size\\nSELECT * FROM large_table1 l1\\nJOIN large_table2 l2 ON l1.id = l2.ref_id\\nWHERE l1.created_date >= DATEADD(month, -3, GETDATE())  -- filter early\\nORDER BY l1.created_date;\\n\\n-- Use TOP with ORDER BY to limit result set:\\nSELECT TOP 1000 * FROM large_table1 l1\\nJOIN large_table2 l2 ON l1.id = l2.ref_id\\nORDER BY l1.created_date DESC;\\n\\n-- For reporting queries, consider pagination:\\n-- WHERE l1.created_date BETWEEN @start AND @end\\n\\n-- Update statistics for accurate cardinality estimates\\nUPDATE STATISTICS [schema].[large_table1] WITH FULLSCAN;\\nUPDATE STATISTICS [schema].[large_table2] WITH FULLSCAN;", "parameters": ["affected_queries"], "description": "Add more selective WHERE predicates to reduce the intermediate result set size before sort/hash operations. Use TOP with ORDER BY for bounded results. Update statistics for accurate sizing."}	null	low	f	t	\N	2026-02-24 13:10:27.651813
4163	sqlserver	instruct	Optimize or eliminate DISTINCT operations	{"sql": "-- Pattern 1: DISTINCT used to deduplicate JOIN results\\n-- BEFORE: SELECT DISTINCT o.id, o.date FROM orders o JOIN items i ON o.id = i.order_id\\n-- AFTER: Use EXISTS instead of JOIN + DISTINCT\\nSELECT o.id, o.date FROM orders o\\nWHERE EXISTS (SELECT 1 FROM items i WHERE i.order_id = o.id);\\n\\n-- Pattern 2: DISTINCT on too many columns\\n-- BEFORE: SELECT DISTINCT col1, col2, col3, col4, col5, col6 FROM large_table\\n-- AFTER: GROUP BY with only needed columns\\nSELECT col1, col2, col3 FROM large_table\\nGROUP BY col1, col2, col3;\\n\\n-- Pattern 3: DISTINCT is unnecessary\\n-- BEFORE: SELECT DISTINCT id FROM table WHERE id = @param\\n-- AFTER: id is already unique (it's the PK)\\nSELECT id FROM table WHERE id = @param;\\n\\n-- Pattern 4: Use ROW_NUMBER for complex deduplication\\nSELECT * FROM (\\n  SELECT *, ROW_NUMBER() OVER (PARTITION BY key_col ORDER BY date DESC) AS rn\\n  FROM source_table\\n) x WHERE rn = 1;", "parameters": ["affected_queries"], "description": "Replace DISTINCT with EXISTS for join deduplication, GROUP BY for column reduction, or remove entirely when deduplication is unnecessary."}	null	low	f	t	\N	2026-02-24 13:10:27.652321
4687	sqlserver	verify	Confirm bulk rootcause grants are replaced	{"sql": "SELECT dp.permission_name, o.type_desc, COUNT(*) AS remaining_rootcause_grants\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'rootcause' AND dp.state_desc = 'GRANT' AND dp.class_desc = 'OBJECT_OR_COLUMN' AND o.is_ms_shipped = 0\\nGROUP BY dp.permission_name, o.type_desc HAVING COUNT(*) >= 5;", "parameters": [], "description": "Verifies no bulk rootcause grant patterns remain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.779461
4165	sqlserver	configure	Adjust Resource Governor and memory grant settings	{"sql": "-- Check current Resource Governor configuration\\nSELECT\\n  wg.name AS workload_group,\\n  wg.request_max_memory_grant_percent,\\n  rp.name AS resource_pool,\\n  rp.max_memory_percent,\\n  wgs.total_reduced_memgrant_count,\\n  wgs.total_memgrant_timeout_count\\nFROM sys.resource_governor_workload_groups wg\\nJOIN sys.resource_governor_resource_pools rp ON wg.pool_id = rp.pool_id\\nLEFT JOIN sys.dm_resource_governor_workload_groups wgs ON wg.group_id = wgs.group_id;\\n\\n-- Increase max memory grant percent if too restrictive\\nALTER WORKLOAD GROUP [default] WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\n\\n-- Increase min memory per query\\nEXEC sp_configure 'min memory per query (KB)', 2048;\\nRECONFIGURE;\\n\\n-- Enable memory grant feedback\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;", "parameters": [], "description": "Adjusts Resource Governor memory grant limits and enables memory grant feedback for adaptive sizing. Increases minimum memory per query for complex queries."}	{"sql": "ALTER WORKLOAD GROUP [default] WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\nEXEC sp_configure 'min memory per query (KB)', 1024;\\nRECONFIGURE;", "description": "Revert memory settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.652605
4166	sqlserver	verify	Verify grant-to-ideal ratio improved and spills eliminated	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  CASE WHEN qs.total_ideal_grant_kb > 0\\n    THEN CAST(qs.total_grant_kb AS FLOAT) / qs.total_ideal_grant_kb * 100 ELSE 100 END AS grant_pct_of_ideal,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.total_spills > 0\\nORDER BY (qs.total_ideal_grant_kb - qs.total_grant_kb) DESC;", "parameters": [], "description": "Confirms that memory grants are closer to ideal and spills have decreased."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.652606
4167	sqlserver	execute	Create index matching ORDER BY columns	{"sql": "-- Create index matching ORDER BY with filter columns as leading keys\\nCREATE NONCLUSTERED INDEX IX_table_order_by\\n  ON [schema].[table_name] (filter_column, order_by_column DESC)\\n  INCLUDE (selected_output_columns)\\n  WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);\\n\\n-- For queries with WHERE + ORDER BY, the index should be:\\n-- Key: (WHERE columns, ORDER BY columns)\\n-- Include: (SELECT columns not in key)\\n\\n-- Example:\\n-- Query: SELECT id, name, total FROM orders WHERE status = 'active' ORDER BY created_date DESC\\n-- Index: CREATE INDEX IX_orders_status_date ON orders (status, created_date DESC) INCLUDE (id, name, total);", "parameters": ["table_name", "filter_columns", "order_by_columns", "include_columns"], "description": "Creates a covering index with filter columns as leading keys followed by ORDER BY columns, enabling the optimizer to read data in the desired order without sorting."}	{"sql": "DROP INDEX IF EXISTS IX_table_order_by ON [schema].[table_name];", "description": "Drop the created index."}	medium	t	t	\N	2026-02-24 13:10:27.653055
