4169	sqlserver	execute	Create index matching window function sort requirements	{"sql": "-- Create index matching PARTITION BY + ORDER BY of window function\\n-- Query: SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY hire_date) AS rn\\n--        FROM employees WHERE status = 'active'\\n\\n-- Index: filter column first, then PARTITION BY, then ORDER BY\\nCREATE NONCLUSTERED INDEX IX_table_window_func\\n  ON [schema].[table_name] (filter_col, partition_col, order_col)\\n  INCLUDE (other_selected_columns)\\n  WITH (ONLINE = ON, SORT_IN_TEMPDB = ON);\\n\\n-- For multiple window functions with same PARTITION BY:\\n-- ROW_NUMBER() OVER (PARTITION BY dept ORDER BY date)\\n-- SUM(salary) OVER (PARTITION BY dept ORDER BY date)\\n-- Single index: (dept, date) covers both", "parameters": ["table_name", "partition_columns", "order_columns", "include_columns"], "description": "Creates covering indexes with columns ordered to match the PARTITION BY and ORDER BY requirements of window functions, eliminating explicit Sort operators."}	{"sql": "DROP INDEX IF EXISTS IX_table_window_func ON [schema].[table_name];", "description": "Drop the created index."}	medium	t	t	\N	2026-02-24 13:10:27.653549
4170	sqlserver	verify	Verify window function sort spills eliminated	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Sort\\"])', 'int') AS sort_ops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Window Spool\\" or @PhysicalOp=\\"Segment\\"])', 'int') AS window_ops\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE (p.query_plan.exist('//RelOp[@PhysicalOp=\\"Window Spool\\"]') = 1\\n    OR p.query_plan.exist('//RelOp[@PhysicalOp=\\"Segment\\"]') = 1)\\n  AND qs.execution_count > 1\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Confirms that sort operators before window functions are eliminated or reduced and spills are gone."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.653951
4171	sqlserver	configure	Adjust MAXDOP and cost threshold for parallel sort optimization	{"sql": "-- Reduce server MAXDOP if too high\\nEXEC sp_configure 'max degree of parallelism', 4;\\nRECONFIGURE;\\n\\n-- Raise cost threshold to prevent small queries from going parallel\\nEXEC sp_configure 'cost threshold for parallelism', 50;\\nRECONFIGURE;\\n\\n-- For specific queries, use query-level MAXDOP hint:\\n-- SELECT * FROM large_table ORDER BY col OPTION (MAXDOP 2);\\n\\n-- Enable memory grant feedback for adaptive sizing\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;", "parameters": [], "description": "Reduces MAXDOP to give each parallel thread more memory for sorting, and raises cost threshold to prevent small queries from incurring parallelism overhead."}	{"sql": "EXEC sp_configure 'max degree of parallelism', 0;\\nEXEC sp_configure 'cost threshold for parallelism', 5;\\nRECONFIGURE;", "description": "Revert to default settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.653954
4173	sqlserver	instruct	Restructure query to defer LOB column retrieval after sort	{"sql": "-- BEFORE: sorting with LOB columns included\\n-- SELECT id, name, description, large_blob_col\\n-- FROM large_table\\n-- ORDER BY created_date\\n\\n-- AFTER: sort only key columns, then join back for LOB\\nSELECT t.id, t.name, t.description, t.large_blob_col\\nFROM large_table t\\nINNER JOIN (\\n  SELECT TOP 100 id\\n  FROM large_table\\n  ORDER BY created_date DESC\\n) sorted ON sorted.id = t.id\\nORDER BY t.created_date DESC;\\n\\n-- Or use CTE for readability:\\nWITH sorted_ids AS (\\n  SELECT TOP 100 id, created_date\\n  FROM large_table\\n  ORDER BY created_date DESC\\n)\\nSELECT t.id, t.name, t.description, t.large_blob_col\\nFROM sorted_ids s\\nJOIN large_table t ON s.id = t.id\\nORDER BY s.created_date DESC;\\n\\n-- Also: avoid SELECT * when LOB columns are not needed\\n-- SELECT id, name, status FROM table ORDER BY date\\n-- (instead of SELECT * FROM table ORDER BY date)", "parameters": ["affected_queries"], "description": "Restructure queries to sort only the key columns in a subquery, then join back to retrieve LOB columns. Avoid SELECT * when LOB columns are not needed."}	null	low	f	t	\N	2026-02-24 13:10:27.654479
4174	sqlserver	verify	Verify reduced memory grants and eliminated spills	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\"]/@AvgRowSize)[1]', 'int') AS sort_avg_row_size\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Sort\\"]') = 1\\n  AND qs.execution_count > 1\\nORDER BY qs.total_grant_kb DESC;", "parameters": [], "description": "Confirms that sort average row size has decreased and spills are eliminated."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.654797
4175	sqlserver	instruct	Restructure queries to consolidate or eliminate redundant sorts	{"sql": "-- Pattern 1: window functions with different ORDER BY but same PARTITION BY\\n-- BEFORE: two sorts (one for each window function)\\n-- SELECT *, ROW_NUMBER() OVER (PARTITION BY dept ORDER BY hire_date) AS rn,\\n--          SUM(salary) OVER (PARTITION BY dept ORDER BY hire_date) AS running_total\\n-- Optimizer may already share the sort for these\\n\\n-- Pattern 2: subquery with ORDER BY followed by outer ORDER BY\\n-- BEFORE:\\n-- SELECT * FROM (SELECT *, ROW_NUMBER() OVER (ORDER BY date) AS rn FROM t) sub\\n-- ORDER BY sub.name  -- requires second sort\\n\\n-- AFTER: restructure to use single sort where possible\\n-- SELECT * FROM t ORDER BY name  -- if ROW_NUMBER is not needed\\n\\n-- Pattern 3: UNION ALL followed by ORDER BY\\n-- Consider using indexed views or pre-sorted inputs\\n\\n-- Enable memory grant feedback for accurate multi-sort sizing\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;", "parameters": ["affected_queries"], "description": "Restructure queries to minimize the number of distinct sort operations. Align window function PARTITION BY/ORDER BY clauses to share sorts where possible."}	null	low	f	t	\N	2026-02-24 13:10:27.655219
4177	sqlserver	instruct	Add selective predicates and create supporting indexes	{"sql": "-- BEFORE: sorting all rows from large table\\n-- SELECT * FROM audit_log ORDER BY created_date DESC\\n\\n-- AFTER: add date range predicate\\nSELECT * FROM audit_log\\nWHERE created_date >= DATEADD(day, -30, GETDATE())\\nORDER BY created_date DESC;\\n\\n-- BEFORE: no WHERE clause on join result\\n-- SELECT o.*, c.name FROM orders o JOIN customers c ON o.cust_id = c.id\\n-- ORDER BY o.total DESC\\n\\n-- AFTER: add business-relevant filter\\nSELECT o.*, c.name FROM orders o JOIN customers c ON o.cust_id = c.id\\nWHERE o.status = 'active' AND o.created_date >= '2024-01-01'\\nORDER BY o.total DESC;\\n\\n-- Create index to support the filter + sort\\nCREATE NONCLUSTERED INDEX IX_orders_status_date_total\\n  ON orders (status, created_date, total DESC)\\n  INCLUDE (cust_id)\\n  WITH (ONLINE = ON);", "parameters": ["affected_queries"], "description": "Add business-relevant WHERE predicates that reduce the result set before sorting. Create supporting indexes that cover both the filter and sort columns."}	{"sql": "DROP INDEX IF EXISTS IX_orders_status_date_total ON orders;", "description": "Drop the created index."}	low	f	t	\N	2026-02-24 13:10:27.655222
4179	sqlserver	configure	Enable memory grant feedback and optimize hash join configuration	{"sql": "-- Enable memory grant feedback\\nALTER DATABASE SCOPED CONFIGURATION SET BATCH_MODE_MEMORY_GRANT_FEEDBACK = ON;\\nALTER DATABASE SCOPED CONFIGURATION SET ROW_MODE_MEMORY_GRANT_FEEDBACK = ON;\\n\\n-- SQL 2022: percentile-based feedback\\n-- ALTER DATABASE SCOPED CONFIGURATION SET MEMORY_GRANT_FEEDBACK_PERCENTILE_GRANT = ON;\\n\\n-- Update statistics for accurate hash table sizing\\nUPDATE STATISTICS [schema].[build_side_table] WITH FULLSCAN;\\nUPDATE STATISTICS [schema].[probe_side_table] WITH FULLSCAN;\\n\\n-- Check and increase min memory per query if needed\\nEXEC sp_configure 'min memory per query (KB)', 2048;\\nRECONFIGURE;\\n\\n-- For specific queries, add pre-filtering to reduce build side:\\n-- SELECT * FROM small_table s INNER HASH JOIN large_table l ON s.id = l.ref_id\\n-- WHERE s.status = 'active'  -- reduces build side rows", "parameters": ["build_side_table", "probe_side_table"], "description": "Enables memory grant feedback for adaptive hash table sizing, updates statistics on tables involved in hash joins, and ensures minimum memory per query is adequate."}	{"sql": "EXEC sp_configure 'min memory per query (KB)', 1024;\\nRECONFIGURE;", "description": "Revert min memory per query to default."}	low	t	t	\N	2026-02-24 13:10:27.656194
4202	sqlserver	verify	Verify deadlock rate reduced to near-zero	{"sql": "-- Check deadlock counters\\nSELECT pc.cntr_value AS total_deadlocks_since_restart\\nFROM sys.dm_os_performance_counters pc\\nWHERE pc.object_name LIKE '%Locks%'\\n  AND pc.counter_name = 'Number of Deadlocks/sec'\\n  AND pc.instance_name = '_Total';\\n\\n-- Check for recent deadlocks in system_health\\nSELECT COUNT(*) AS deadlocks_last_hour\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_data\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address\\n  WHERE s.name = 'system_health' AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_data.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xed)\\nWHERE xed.value('(event/@timestamp)[1]', 'datetime2') > DATEADD(hour, -1, GETDATE());", "parameters": [], "description": "Confirms deadlock frequency has dropped to near-zero after implementing consistent lock ordering and retry logic."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.6636
4204	sqlserver	verify	Verify transaction log usage stays bounded during batched operation	{"sql": "-- Check current log space usage\\nSELECT\\n  DB_NAME() AS database_name,\\n  total_log_size_mb,\\n  used_log_space_mb,\\n  used_log_space_percentage\\nFROM sys.dm_db_log_space_usage;\\n\\n-- Check for any long-running transactions\\nSELECT COUNT(*) AS long_transactions\\nFROM sys.dm_tran_active_transactions tat\\nJOIN sys.dm_tran_session_transactions st ON tat.transaction_id = st.transaction_id\\nWHERE DATEDIFF(second, tat.transaction_begin_time, GETDATE()) > 60;\\n\\n-- Check log reuse wait\\nSELECT name, log_reuse_wait_desc\\nFROM sys.databases WHERE database_id = DB_ID();", "parameters": [], "description": "Confirms transaction log usage stays within bounds and no single transaction is running longer than expected during the batched operation."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.664484
4180	sqlserver	instruct	Replace UNION with UNION ALL or add pre-filtering to reduce deduplication volume	{"sql": "-- Pattern 1: Replace UNION with UNION ALL when duplicates are impossible\\n-- Each branch selects from mutually exclusive partitions\\n-- BEFORE:\\n-- SELECT id, name FROM active_customers\\n-- UNION\\n-- SELECT id, name FROM archived_customers\\n-- AFTER:\\nSELECT id, name FROM active_customers\\nUNION ALL\\nSELECT id, name FROM archived_customers;\\n\\n-- Pattern 2: When duplicates exist but are acceptable\\n-- BEFORE: SELECT product_id FROM order_items UNION SELECT product_id FROM wishlist_items\\n-- AFTER: Wrap in outer DISTINCT only if truly needed\\nSELECT DISTINCT product_id FROM (\\n  SELECT product_id FROM order_items\\n  UNION ALL\\n  SELECT product_id FROM wishlist_items\\n) combined;\\n\\n-- Pattern 3: Pre-filter branches to reduce deduplication volume\\nSELECT id, name FROM active_customers WHERE region = @region\\nUNION\\nSELECT id, name FROM archived_customers WHERE region = @region;", "parameters": ["query_text", "table_names"], "description": "Analyzes UNION queries to determine if UNION ALL is safe (mutually exclusive data, already unique keys, or duplicates acceptable). Pre-filtering reduces the combined row count before deduplication."}	{"sql": "-- Revert to original UNION query if result correctness is affected", "description": "Restore original UNION if UNION ALL produces incorrect results."}	low	f	t	\N	2026-02-24 13:10:27.656197
4181	sqlserver	verify	Verify deduplication spills eliminated after UNION ALL replacement	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@LogicalOp=\\"Distinct Sort\\"])', 'int') AS distinct_sort_ops,\\n  p.query_plan.value('count(//RelOp[@LogicalOp=\\"Union\\"])', 'int') AS union_ops,\\n  qs.execution_count\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 1\\n  AND p.query_plan.exist('//RelOp[@LogicalOp=\\"Union\\"]') = 1\\nORDER BY qs.total_spills DESC;", "parameters": [], "description": "Confirms spills eliminated for UNION queries and distinct sort operators are no longer present in the plan."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.657147
4182	sqlserver	configure	Set appropriate MAXDOP and configure Resource Governor memory limits	{"sql": "-- Set server-level MAXDOP (recommended: number of physical cores per NUMA node, max 8)\\nEXEC sp_configure 'max degree of parallelism', 4;\\nRECONFIGURE;\\n\\n-- Set cost threshold to prevent small queries from going parallel\\nEXEC sp_configure 'cost threshold for parallelism', 50;\\nRECONFIGURE;\\n\\n-- Optional: Database-scoped MAXDOP for specific databases\\nALTER DATABASE SCOPED CONFIGURATION SET MAXDOP = 4;\\n\\n-- Configure Resource Governor to cap memory grants per workload group\\nALTER WORKLOAD GROUP [default]\\n  WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25,\\n        REQUEST_MEMORY_GRANT_TIMEOUT_SEC = 60);\\nALTER RESOURCE GOVERNOR RECONFIGURE;\\n\\n-- For specific high-DOP queries, use query hint\\n-- SELECT ... FROM ... OPTION (MAXDOP 2, MAX_GRANT_PERCENT = 10);", "parameters": ["maxdop_value", "cost_threshold", "max_grant_percent"], "description": "Reduces MAXDOP to limit per-query thread count and memory fragmentation. Resource Governor caps per-request memory grants to prevent a single query from consuming all available grant memory."}	{"sql": "EXEC sp_configure 'max degree of parallelism', 0;\\nRECONFIGURE;\\nEXEC sp_configure 'cost threshold for parallelism', 5;\\nRECONFIGURE;\\nALTER WORKLOAD GROUP [default] WITH (REQUEST_MAX_MEMORY_GRANT_PERCENT = 25);\\nALTER RESOURCE GOVERNOR RECONFIGURE;", "description": "Restore original MAXDOP and cost threshold settings."}	medium	t	t	\N	2026-02-24 13:10:27.657572
