4210	sqlserver	configure	Convert maintenance operations to use ONLINE options and schedule off-peak	{"sql": "-- Convert index rebuilds to ONLINE mode\\nALTER INDEX ALL ON [schema].[table_name]\\n  REBUILD WITH (\\n    ONLINE = ON,\\n    SORT_IN_TEMPDB = ON,\\n    MAXDOP = 4,\\n    RESUMABLE = ON,  -- SQL 2017+: resume if interrupted\\n    MAX_DURATION = 60  -- minutes before auto-pause\\n  );\\n\\n-- For statistics updates, use async mode to avoid blocking\\nALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS_ASYNC ON;\\n\\n-- Use WAIT_AT_LOW_PRIORITY for schema change operations (SQL 2014+)\\nALTER INDEX IX_example ON [schema].[table_name]\\n  REBUILD WITH (\\n    ONLINE = ON (WAIT_AT_LOW_PRIORITY (MAX_DURATION = 1, ABORT_AFTER_WAIT = SELF))\\n  );\\n\\n-- Schedule DBCC CHECKDB during maintenance window\\n-- (No ONLINE option for CHECKDB, but snapshot-based by default)\\nDBCC CHECKDB ([database_name]) WITH NO_INFOMSGS, DATA_PURITY;", "parameters": ["table_name", "maintenance_window_start", "maintenance_window_end"], "description": "Configures maintenance operations to use ONLINE options that avoid blocking user transactions. RESUMABLE index rebuilds can be paused and resumed if they conflict with peak hours."}	{"sql": "-- Abort resumable index rebuild if causing issues\\nALTER INDEX IX_example ON [schema].[table_name] ABORT;", "description": "Abort any in-progress resumable index rebuild."}	medium	t	t	\N	2026-02-24 13:10:27.665917
4211	sqlserver	verify	Verify no user transactions blocked by maintenance operations	{"sql": "-- Check for any sessions blocked by maintenance commands\\nSELECT r.session_id AS blocked_session,\\n  r.blocking_session_id, r.wait_type, r.wait_time / 1000 AS wait_sec,\\n  r_maint.command AS blocker_command\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_requests r_maint ON r.blocking_session_id = r_maint.session_id\\nWHERE r_maint.command IN ('ALTER INDEX', 'DBCC', 'CREATE INDEX', 'UPDATE STATISTICS');\\n\\n-- Check for active online index operations\\nSELECT ior.index_id, ior.state_desc, ior.percent_complete\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ior\\nWHERE r.command = 'ALTER INDEX';", "parameters": [], "description": "Confirms no user transactions are blocked by maintenance operations and online index rebuilds are proceeding without contention."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.666405
