4302	sqlserver	verify	Verify default admin accounts are disabled	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.server_principals sp\\nWHERE sp.name IN (\\n  (SELECT name FROM sys.server_principals WHERE sid = 0x01),\\n  '##MS_PolicyEventProcessingLogin##',\\n  '##MS_PolicyTsqlExecutionLogin##'\\n)\\nUNION ALL\\nSELECT 'LOGIN_TRIGGER' AS name, 'CHECK' AS type_desc,\\n  CASE WHEN EXISTS (SELECT 1 FROM sys.server_triggers WHERE name = 'trg_restrict_network_logon' AND is_disabled = 0)\\n    THEN 0 ELSE 1 END AS is_disabled,\\n  NULL, NULL;", "parameters": [], "description": "Confirms default admin accounts are disabled and the network restriction login trigger is active."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.703168
4212	sqlserver	execute	Create SQL Agent job to kill idle sessions with open transactions	{"sql": "-- Create automated cleanup job for idle orphaned transactions\\nDECLARE @idle_threshold_minutes INT = 15;\\nDECLARE @session_id INT;\\nDECLARE @kill_cmd NVARCHAR(100);\\n\\nDECLARE idle_cursor CURSOR FOR\\n  SELECT s.session_id\\n  FROM sys.dm_exec_sessions s\\n  JOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\n  JOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\n  WHERE s.status = 'sleeping'\\n    AND s.is_user_process = 1\\n    AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > @idle_threshold_minutes\\n    AND s.open_transaction_count > 0\\n    AND (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = s.session_id) > 0;\\n\\nOPEN idle_cursor;\\nFETCH NEXT FROM idle_cursor INTO @session_id;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  SET @kill_cmd = 'KILL ' + CAST(@session_id AS NVARCHAR(10));\\n  EXEC sp_executesql @kill_cmd;\\n  FETCH NEXT FROM idle_cursor INTO @session_id;\\nEND;\\nCLOSE idle_cursor;\\nDEALLOCATE idle_cursor;\\n\\n-- Also configure Remote Query Timeout to prevent indefinite waits\\nEXEC sp_configure 'remote query timeout', 300; -- 5 minutes\\nRECONFIGURE;", "parameters": ["idle_threshold_minutes"], "description": "Creates a repeating SQL Agent job that identifies sessions idle for longer than the threshold with open transactions that are blocking other sessions, and terminates them automatically."}	{"sql": "-- Disable or delete the cleanup job\\n-- EXEC msdb.dbo.sp_update_job @job_name = 'Kill_Idle_Orphaned_Transactions', @enabled = 0;", "description": "Disable the automated cleanup job."}	medium	t	t	\N	2026-02-24 13:10:27.66685
4213	sqlserver	verify	Verify idle transaction cleanup is working and blocking is prevented	{"sql": "-- Check for any remaining idle transactions with blocking\\nSELECT COUNT(*) AS idle_blocking_sessions\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 15\\n  AND EXISTS (SELECT 1 FROM sys.dm_exec_requests r WHERE r.blocking_session_id = s.session_id);\\n\\n-- Verify cleanup job is running\\nSELECT j.name, ja.run_status, ja.start_execution_date\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobactivity ja ON j.job_id = ja.job_id\\nWHERE j.name LIKE '%Kill_Idle%'\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions);", "parameters": [], "description": "Confirms no idle sessions with open transactions are causing blocking, and the automated cleanup job is running on schedule."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.667197
4214	sqlserver	configure	Disable IMPLICIT_TRANSACTIONS and ensure connection pool resets state	{"sql": "-- Check and disable implicit transactions for affected sessions\\n-- This is typically set per-session by the driver/ORM\\n-- To fix globally for all new connections:\\n\\n-- Option 1: Logon trigger to reset session options\\nCREATE OR ALTER TRIGGER trg_reset_implicit_transactions\\nON ALL SERVER\\nFOR LOGON\\nAS\\nBEGIN\\n  SET IMPLICIT_TRANSACTIONS OFF;\\nEND;\\n\\n-- Option 2: For specific applications, add to connection string:\\n-- SQL Server: \\"Pooling=true;Connection Reset=true;\\"\\n-- JDBC: \\"sendStringParametersAsUnicode=false\\"\\n\\n-- Check which sessions currently have implicit transactions\\nSELECT s.session_id, s.program_name, s.host_name,\\n  s.open_transaction_count, s.status,\\n  CASE WHEN (s.transaction_isolation_level = 2\\n    AND s.open_transaction_count > 0\\n    AND s.status = 'sleeping')\\n    THEN 'LIKELY_IMPLICIT_TXN' ELSE 'OK' END AS diagnosis\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND s.status = 'sleeping';", "parameters": ["application_driver", "connection_string"], "description": "Disables IMPLICIT_TRANSACTIONS mode and configures connection pool to properly reset session state when connections are returned to the pool."}	{"sql": "DROP TRIGGER trg_reset_implicit_transactions ON ALL SERVER;", "description": "Remove the logon trigger if it causes issues."}	low	f	t	\N	2026-02-24 13:10:27.667513
4215	sqlserver	verify	Verify no sleeping sessions with orphaned implicit transactions	{"sql": "-- Check for sleeping sessions with open transactions\\nSELECT COUNT(*) AS orphaned_implicit_txns\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(second, s.last_request_end_time, GETDATE()) > 120;\\n\\n-- Verify logon trigger is active\\nSELECT name, is_disabled, create_date\\nFROM sys.server_triggers\\nWHERE name = 'trg_reset_implicit_transactions';", "parameters": [], "description": "Confirms no implicit transactions are left orphaned by ORM/driver connections."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.667802
