4228	sqlserver	execute	Restart distribution agent or remove defunct subscriber	{"sql": "-- Check distribution agent status\\nSELECT da.name AS agent_name, da.subscriber_db,\\n  dh.time AS last_history_time, dh.runstatus,\\n  CASE dh.runstatus\\n    WHEN 1 THEN 'Start' WHEN 2 THEN 'Succeed' WHEN 3 THEN 'InProgress'\\n    WHEN 4 THEN 'Idle' WHEN 5 THEN 'Retry' WHEN 6 THEN 'Fail'\\n  END AS status_desc,\\n  dh.comments\\nFROM distribution.dbo.MSdistribution_agents da\\nJOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\nWHERE dh.time = (SELECT MAX(time) FROM distribution.dbo.MSdistribution_history WHERE agent_id = da.id);\\n\\n-- If agent is failing, restart it\\n-- EXEC distribution.dbo.sp_MSstartdistribution_agent @publisher = N'primary', @publisher_db = N'db', @rootcauseation = N'pub';\\n\\n-- If subscriber is permanently gone, remove the subscription\\n-- EXEC sp_dropsubscription @rootcauseation = N'pub_name', @subscriber = N'subscriber_server', @article = N'all', @destination_db = N'sub_db';\\n\\n-- Check unreplicated transactions in distribution DB\\nSELECT publisher_database_id, COUNT(*) AS unreplicated_cmds\\nFROM distribution.dbo.MSrepl_commands\\nGROUP BY publisher_database_id;", "parameters": ["rootcauseation_name", "subscriber_server"], "description": "Diagnoses the replication agent failure and either restarts it or removes the defunct subscriber to unblock log truncation."}	null	medium	t	f	\N	2026-02-24 13:10:27.672451
