4301	sqlserver	execute	Disable unused default admin accounts	{"sql": "-- Disable sa if enabled\\nIF EXISTS (SELECT 1 FROM sys.server_principals WHERE sid = 0x01 AND is_disabled = 0)\\nBEGIN\\n  DECLARE @sa_name NVARCHAR(256) = (SELECT name FROM sys.server_principals WHERE sid = 0x01);\\n  EXEC('ALTER LOGIN [' + @sa_name + '] WITH PASSWORD = N''<generated-strong-random-password>''');\\n  EXEC('ALTER LOGIN [' + @sa_name + '] DISABLE');\\nEND\\n\\n-- Disable Policy-Based Management logins if PBM is not used\\n-- Only if you are certain PBM is not in use:\\n-- ALTER LOGIN [##MS_PolicyEventProcessingLogin##] DISABLE;\\n-- ALTER LOGIN [##MS_PolicyTsqlExecutionLogin##] DISABLE;\\n\\n-- Create logon trigger for network-based restriction\\nCREATE OR ALTER TRIGGER [trg_restrict_network_logon] ON ALL SERVER\\nFOR LOGON\\nAS\\nBEGIN\\n  -- Block sa-equivalent login (SID 0x01) from any network connection\\n  IF ORIGINAL_LOGIN() = (SELECT name FROM sys.server_principals WHERE sid = 0x01)\\n    AND EVENTDATA().value('(/EVENT_INSTANCE/ClientHost)[1]', 'varchar(50)') <> '<local machine>'\\n  BEGIN\\n    ROLLBACK;\\n  END\\nEND;", "parameters": [], "description": "Disables unused default admin accounts and creates a login trigger that prevents the sa account from connecting remotely, even if it were re-enabled."}	{"sql": "DROP TRIGGER [trg_restrict_network_logon] ON ALL SERVER;", "description": "Remove the login trigger if it causes connection issues."}	medium	t	t	\N	2026-02-24 13:10:27.702805
