4340	sqlserver	execute	Enable policy on interactive user logins with updated requirements	{"sql": "-- Enable CHECK_POLICY on all user (non-service) logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE user_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n    AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0)\\n    AND sp.name NOT LIKE '##%'\\n    AND sp.name NOT LIKE '%svc%'\\n    AND sp.name NOT LIKE '%service%';\\nOPEN user_cursor;\\nFETCH NEXT FROM user_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n    PRINT 'Policy enabled: ' + @login;\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'Needs password change: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM user_cursor INTO @login;\\nEND;\\nCLOSE user_cursor; DEALLOCATE user_cursor;\\n\\n-- Also enable on service accounts (without expiration)\\nDECLARE svc_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n    AND sl.is_policy_checked = 0 AND sp.name NOT LIKE '##%'\\n    AND (sp.name LIKE '%svc%' OR sp.name LIKE '%service%');\\nOPEN svc_cursor;\\nFETCH NEXT FROM svc_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'Needs password change: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM svc_cursor INTO @login;\\nEND;\\nCLOSE svc_cursor; DEALLOCATE svc_cursor;", "parameters": [], "description": "Enables CHECK_POLICY on user logins (with expiration) and service accounts (without expiration). Service accounts get policy but no forced rotation."}	null	medium	t	t	\N	2026-02-24 13:10:27.717641
4343	sqlserver	verify	Verify production policy applied and no weak passwords remain	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS no_policy_count,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND (PWDCOMPARE('', sl.password_hash) = 1\\n       OR PWDCOMPARE('password', sl.password_hash) = 1\\n       OR PWDCOMPARE(sp.name, sl.password_hash) = 1)) AS weak_password_count;", "parameters": [], "description": "Confirms all logins have policy enforcement and no common weak passwords remain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.718612
4344	sqlserver	execute	Standardize CHECK_POLICY and CHECK_EXPIRATION across all logins	{"sql": "-- Enable full policy on all SQL logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE std_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n    AND sp.name NOT LIKE '##%'\\n    AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0);\\nOPEN std_cursor;\\nFETCH NEXT FROM std_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n    PRINT 'Standardized: ' + @login;\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login + ' - ' + ERROR_MESSAGE();\\n  END CATCH\\n  FETCH NEXT FROM std_cursor INTO @login;\\nEND;\\nCLOSE std_cursor; DEALLOCATE std_cursor;", "parameters": [], "description": "Enables both CHECK_POLICY and CHECK_EXPIRATION on all SQL logins to create a uniform password policy standard."}	null	medium	t	t	\N	2026-02-24 13:10:27.718864
4345	sqlserver	verify	Verify consistent policy enforcement and identify stale passwords	{"sql": "SELECT\\n  COUNT(*) AS total_sql_logins,\\n  SUM(CASE WHEN sl.is_policy_checked = 1 AND sl.is_expiration_checked = 1 THEN 1 ELSE 0 END) AS fully_enforced,\\n  SUM(CASE WHEN sl.is_policy_checked = 0 THEN 1 ELSE 0 END) AS no_policy,\\n  SUM(CASE WHEN DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE()) > 365 THEN 1 ELSE 0 END) AS stale_passwords\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%';", "parameters": [], "description": "Confirms consistent policy enforcement and identifies logins with passwords older than 365 days."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.719103
4347	sqlserver	verify	Verify no common weak passwords and policy enabled	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND (PWDCOMPARE('', sl.password_hash) = 1\\n       OR PWDCOMPARE(sp.name, sl.password_hash) = 1\\n       OR PWDCOMPARE('password', sl.password_hash) = 1\\n       OR PWDCOMPARE('Password1', sl.password_hash) = 1)) AS weak_password_count,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS no_policy_count;", "parameters": [], "description": "Confirms no common weak passwords remain and all logins have password policy enforcement."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.719706
4349	sqlserver	verify	Verify audit active and policy enforcement complete	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('FAILED_LOGIN_GROUP', 'SUCCESSFUL_LOGIN_GROUP')) AS login_audit_actions,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS logins_without_policy;", "parameters": [], "description": "Confirms login audit is active and all SQL logins have policy enforcement enabled."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.720528
