4352	sqlserver	execute	Enable policy on batch-created logins and add prevention trigger	{"sql": "-- Step 1: Enable policy on all logins missing it\\nDECLARE @login NVARCHAR(256);\\nDECLARE batch_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n    AND sl.is_policy_checked = 0 AND sp.name NOT LIKE '##%';\\nOPEN batch_cursor;\\nFETCH NEXT FROM batch_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login + ' - needs password change';\\n  END CATCH\\n  FETCH NEXT FROM batch_cursor INTO @login;\\nEND;\\nCLOSE batch_cursor; DEALLOCATE batch_cursor;\\n\\n-- Step 2: Add DDL trigger to enforce CHECK_POLICY on new logins\\nCREATE OR ALTER TRIGGER [trg_enforce_password_policy] ON ALL SERVER\\nFOR CREATE_LOGIN\\nAS\\nBEGIN\\n  DECLARE @event XML = EVENTDATA();\\n  DECLARE @login_name NVARCHAR(256) = @event.value('(/EVENT_INSTANCE/ObjectName)[1]', 'NVARCHAR(256)');\\n  -- Allow system logins\\n  IF @login_name LIKE '##%' RETURN;\\n  -- Check if the newly created login has policy disabled\\n  IF EXISTS (\\n    SELECT 1 FROM sys.sql_logins sl\\n    JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n    WHERE sp.name = @login_name AND sl.is_policy_checked = 0\\n  )\\n  BEGIN\\n    ROLLBACK;\\n    RAISERROR('All SQL logins must be created with CHECK_POLICY = ON.', 16, 1);\\n  END\\nEND;", "parameters": [], "description": "Enables policy on all existing batch-created logins and creates a DDL trigger that prevents future logins from being created without CHECK_POLICY = ON."}	{"sql": "DROP TRIGGER [trg_enforce_password_policy] ON ALL SERVER;", "description": "Remove the DDL trigger if it interferes with legitimate login creation."}	medium	t	t	\N	2026-02-24 13:10:27.721463
4353	sqlserver	verify	Verify policy enforcement and trigger active	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS no_policy_count,\\n  (SELECT COUNT(*) FROM sys.server_triggers\\n   WHERE name = 'trg_enforce_password_policy' AND is_disabled = 0) AS trigger_active;", "parameters": [], "description": "Confirms all logins have policy enforcement and the prevention trigger is active."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.721708
4358	sqlserver	instruct	Enable Force Encryption in SQL Server Configuration Manager	{"sql": null, "parameters": ["certificate_thumbprint", "server_fqdn"], "description": "Enable Force Encryption for SQL Server: (1) Install a TLS certificate on the SQL Server host (from an internal CA or trusted CA). The certificate CN or SAN must match the SQL Server FQDN. (2) Open SQL Server Configuration Manager. (3) Right-click 'Protocols for MSSQLSERVER' > Properties. (4) On the Flags tab, set 'Force Encryption' to 'Yes'. (5) On the Certificate tab, select the installed certificate. (6) Restart SQL Server service for the change to take effect. (7) Verify clients can connect with encryption. Connection strings should include 'Encrypt=True;TrustServerCertificate=False'. After enabling, all connections -- including Windows Auth -- will be TLS-encrypted."}	null	medium	t	t	\N	2026-02-24 13:10:27.722437
4359	sqlserver	verify	Verify all connections are encrypted	{"sql": "SELECT\\n  c.auth_scheme,\\n  c.encrypt_option,\\n  COUNT(*) AS session_count,\\n  COUNT(DISTINCT s.login_name) AS distinct_logins\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY c.auth_scheme, c.encrypt_option\\nORDER BY c.auth_scheme, c.encrypt_option;", "parameters": [], "description": "Confirms all connections (both Windows Auth and SQL Auth) are encrypted after enabling Force Encryption."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.722656
4364	sqlserver	execute	Disable unnecessary remote features and create IP-restricting logon trigger	{"sql": "-- Step 1: Disable unnecessary remote access features\\nEXEC sp_configure 'remote access', 0; RECONFIGURE;\\nEXEC sp_configure 'remote admin connections', 0; RECONFIGURE;\\n\\n-- Step 2: Create logon trigger for IP-based restrictions\\nCREATE OR ALTER TRIGGER [trg_restrict_client_ip] ON ALL SERVER\\nFOR LOGON\\nAS\\nBEGIN\\n  DECLARE @client_ip NVARCHAR(50) = EVENTDATA().value('(/EVENT_INSTANCE/ClientHost)[1]', 'NVARCHAR(50)');\\n  DECLARE @login_name NVARCHAR(256) = ORIGINAL_LOGIN();\\n  -- Allow local connections and DAC\\n  IF @client_ip = '<local machine>' RETURN;\\n  IF @login_name LIKE 'NT %' RETURN;\\n  -- Allow trusted subnets (customize for your environment)\\n  IF @client_ip LIKE '10.0.1.%' RETURN; -- Application servers\\n  IF @client_ip LIKE '10.0.2.%' RETURN; -- DBA workstations\\n  -- Block all other remote connections\\n  ROLLBACK;\\nEND;", "parameters": ["trusted_subnets"], "description": "Disables unnecessary remote access features and creates a logon trigger that restricts connections to trusted IP ranges only."}	{"sql": "DROP TRIGGER [trg_restrict_client_ip] ON ALL SERVER;\\nEXEC sp_configure 'remote access', 1; RECONFIGURE;", "description": "Remove IP restriction trigger and re-enable remote access if needed."}	medium	t	t	\N	2026-02-24 13:10:27.724007
