4367	sqlserver	verify	Verify all LDAP linked servers use encryption	{"sql": "SELECT ls.name, ls.provider, ls.data_source,\\n  CASE WHEN ls.data_source LIKE 'LDAPS://%' THEN 'ENCRYPTED'\\n       WHEN ls.data_source LIKE 'LDAP://%' THEN 'UNENCRYPTED'\\n       ELSE 'N/A' END AS ldap_security,\\n  ll.uses_self_credential, ll.remote_name\\nFROM sys.servers ls\\nLEFT JOIN sys.linked_logins ll ON ls.server_id = ll.server_id\\nWHERE ls.is_linked = 1\\n  AND (ls.provider LIKE '%ADsDSOObject%'\\n    OR ls.data_source LIKE '%LDAP%');", "parameters": [], "description": "Confirms all LDAP linked servers use LDAPS encryption and Windows Auth passthrough (no stored credentials)."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.724741
4369	sqlserver	verify	Verify audit is capturing login events	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN (\\n       'SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP',\\n       'LOGIN_CHANGE_PASSWORD_GROUP', 'SERVER_PRINCIPAL_CHANGE_GROUP',\\n       'SERVER_ROLE_MEMBER_CHANGE_GROUP'\\n     )) AS login_audit_actions,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'default trace enabled') AS default_trace_on;", "parameters": [], "description": "Confirms the login audit is active and capturing all required event types."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.724743
4371	sqlserver	verify	Verify Mixed Mode hardening complete	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT is_disabled FROM sys.server_principals WHERE sid = 0x01) AS sa_disabled,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS sql_logins_no_policy,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits;", "parameters": [], "description": "Confirms Mixed Mode is hardened: sa disabled, all SQL logins have policy, audit is active."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.725444
4372	sqlserver	execute	Enable contained databases and migrate tenant logins	{"sql": "-- Step 1: Enable contained database authentication\\nEXEC sp_configure 'contained database authentication', 1;\\nRECONFIGURE;\\n\\n-- Step 2: Convert tenant databases to partially contained\\n-- ALTER DATABASE [TenantDB] SET CONTAINMENT = PARTIAL;\\n\\n-- Step 3: Create database-level users (no server login needed)\\n-- USE [TenantDB];\\n-- CREATE USER [tenant_user] WITH PASSWORD = N'<strong-password>';\\n-- ALTER ROLE [db_datareader] ADD MEMBER [tenant_user];\\n-- ALTER ROLE [db_datawriter] ADD MEMBER [tenant_user];\\n\\n-- Step 4: Secure all server-level SQL logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE tenant_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND sl.is_policy_checked = 0;\\nOPEN tenant_cursor;\\nFETCH NEXT FROM tenant_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM tenant_cursor INTO @login;\\nEND;\\nCLOSE tenant_cursor; DEALLOCATE tenant_cursor;", "parameters": ["tenant_database_name"], "description": "Enables contained database authentication for tenant isolation and secures all remaining server-level SQL logins with policy enforcement."}	null	medium	t	t	\N	2026-02-24 13:10:27.725687
4373	sqlserver	verify	Verify contained databases and SQL login security	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'contained database authentication') AS contained_auth_enabled,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS sql_logins_no_policy,\\n  (SELECT COUNT(*) FROM sys.databases WHERE containment_desc <> 'NONE') AS contained_dbs;", "parameters": [], "description": "Confirms contained database authentication is enabled and all SQL logins have policy enforcement."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.725917
4374	sqlserver	execute	Identify unused SQL logins and disable them	{"sql": "-- Step 1: Identify SQL logins with no active sessions\\nSELECT sp.name AS sql_login, sp.create_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name AND is_user_process = 1) AS active_sessions,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\nORDER BY active_sessions ASC;\\n\\n-- Step 2: Check for SQL logins that duplicate Windows logins\\nSELECT sp_sql.name AS sql_login,\\n  (SELECT TOP 1 sp_win.name FROM sys.server_principals sp_win\\n   WHERE sp_win.type IN ('U', 'G')\\n     AND sp_win.name LIKE '%' + sp_sql.name + '%') AS possible_windows_equivalent\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp_sql ON sl.principal_id = sp_sql.principal_id\\nWHERE sp_sql.is_disabled = 0 AND sp_sql.name NOT LIKE '##%' AND sp_sql.name <> 'sa';\\n\\n-- Step 3: Disable unused SQL logins\\n-- ALTER LOGIN [unused_login] DISABLE;", "parameters": [], "description": "Identifies SQL logins that have no active sessions or duplicate Windows logins, and provides commands to disable them."}	{"sql": "-- ALTER LOGIN [login_name] ENABLE;", "description": "Re-enable a login if disabling it affected application connectivity."}	medium	t	t	\N	2026-02-24 13:10:27.726146
