4376	sqlserver	execute	Disable stale SQL logins and prepare for Windows-only mode	{"sql": "-- Step 1: Identify SQL logins with no recent activity\\nSELECT sp.name, sp.create_date, sp.modify_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\nORDER BY sp.modify_date ASC;\\n\\n-- Step 2: Disable SQL logins with no recent sessions\\nDECLARE @login NVARCHAR(256);\\nDECLARE stale_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\n    AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL;\\nOPEN stale_cursor;\\nFETCH NEXT FROM stale_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling stale SQL login: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM stale_cursor INTO @login;\\nEND;\\nCLOSE stale_cursor; DEALLOCATE stale_cursor;\\n\\n-- Step 3: Disable sa\\nALTER LOGIN [sa] DISABLE;", "parameters": [], "description": "Disables SQL logins with no recent sessions, completing the migration to Windows Authentication."}	{"sql": "-- Re-enable a login if needed\\n-- ALTER LOGIN [login_name] ENABLE;", "description": "Re-enable SQL logins if the migration needs to be rolled back."}	medium	t	t	\N	2026-02-24 13:10:27.726637
4377	sqlserver	verify	Verify SQL login migration and assess readiness for Windows-only mode	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS remaining_active_sql_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G') AND is_disabled = 0) AS active_windows_logins;", "parameters": [], "description": "Shows remaining active SQL logins and Windows logins to assess readiness for switching to Windows-only mode."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.72693
4378	sqlserver	execute	Apply hardening controls to contractor SQL logins	{"sql": "-- Step 1: Identify contractor-pattern SQL logins\\nSELECT sp.name, sp.create_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE()) AS password_age_days\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\nORDER BY sp.create_date;\\n\\n-- Step 2: Enable policy and expiration on all SQL logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE contractor_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\n    AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0);\\nOPEN contractor_cursor;\\nFETCH NEXT FROM contractor_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login + ' - needs password change';\\n  END CATCH\\n  FETCH NEXT FROM contractor_cursor INTO @login;\\nEND;\\nCLOSE contractor_cursor; DEALLOCATE contractor_cursor;\\n\\n-- Step 3: Disable sa\\nIF EXISTS (SELECT 1 FROM sys.server_principals WHERE sid = 0x01 AND is_disabled = 0)\\n  ALTER LOGIN [sa] DISABLE;", "parameters": [], "description": "Enables password policy and expiration on all SQL logins, ensuring contractor accounts have enforced password rotation and complexity."}	null	medium	t	t	\N	2026-02-24 13:10:27.727202
4379	sqlserver	verify	Verify contractor login hardening	{"sql": "SELECT sp.name, sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  LOGINPROPERTY(sp.name, 'DaysUntilExpiration') AS days_until_expiry\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa';", "parameters": [], "description": "Shows all active SQL logins with their policy enforcement and password expiration status."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.72753
4380	sqlserver	execute	Disable dev-pattern logins and apply production security baseline	{"sql": "-- Step 1: Disable dev-pattern SQL logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE dev_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND (sp.name LIKE '%dev%' OR sp.name LIKE '%debug%' OR sp.name LIKE '%local%'\\n      OR sp.name LIKE '%test%' OR sp.name LIKE '%staging%' OR sp.name LIKE '%qa%');\\nOPEN dev_cursor;\\nFETCH NEXT FROM dev_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling dev login: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM dev_cursor INTO @login;\\nEND;\\nCLOSE dev_cursor; DEALLOCATE dev_cursor;\\n\\n-- Step 2: Enable policy on all remaining logins\\nDECLARE prod_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0);\\nOPEN prod_cursor;\\nFETCH NEXT FROM prod_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM prod_cursor INTO @login;\\nEND;\\nCLOSE prod_cursor; DEALLOCATE prod_cursor;\\n\\n-- Step 3: Disable sa\\nALTER LOGIN [sa] DISABLE;", "parameters": [], "description": "Disables SQL logins matching development naming patterns and applies production-grade password policy to all remaining logins."}	null	medium	t	t	\N	2026-02-24 13:10:27.727834
4381	sqlserver	verify	Verify dev logins disabled and production baseline applied	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND (sp.name LIKE '%dev%' OR sp.name LIKE '%test%' OR sp.name LIKE '%qa%'\\n       OR sp.name LIKE '%staging%' OR sp.name LIKE '%debug%')) AS remaining_dev_logins,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS no_policy_count;", "parameters": [], "description": "Confirms all dev-pattern logins are disabled and all remaining logins have policy enforcement."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.728117
4462	sqlserver	execute	Reset sa password, enforce policy, and disable the account	{"sql": "ALTER LOGIN [sa] WITH PASSWORD = N'$(GENERATE_STRONG_PASSWORD)', CHECK_POLICY = ON, CHECK_EXPIRATION = ON;\\nALTER LOGIN [sa] DISABLE;", "parameters": ["GENERATE_STRONG_PASSWORD"], "description": "Sets a strong password on sa (for break-glass purposes) and disables the account. The password should be stored in a secure vault."}	{"sql": "ALTER LOGIN [sa] ENABLE;", "description": "Re-enables sa if emergency access is needed before the documented recovery procedure is in place."}	medium	t	t	00:01:00	2026-02-24 13:10:27.750991
4382	sqlserver	execute	Apply post-installation hardening checklist	{"sql": "-- Step 1: Secure sa account\\nALTER LOGIN [sa] WITH PASSWORD = N'<generated-strong-random-password>';\\nALTER LOGIN [sa] DISABLE;\\n\\n-- Step 2: Check if Mixed Mode is actually needed\\nSELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\n     AND sp.is_disabled = 0) AS non_default_sql_logins;\\n\\n-- If no non-default SQL logins exist, Mixed Mode is unnecessary\\n-- Switch to Windows-only: EXEC xp_instance_regwrite ... N'LoginMode', REG_DWORD, 1;\\n\\n-- Step 3: Enable policy on all SQL logins that exist\\nDECLARE @login NVARCHAR(256);\\nDECLARE post_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0);\\nOPEN post_cursor;\\nFETCH NEXT FROM post_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM post_cursor INTO @login;\\nEND;\\nCLOSE post_cursor; DEALLOCATE post_cursor;", "parameters": [], "description": "Applies post-installation hardening: secures sa, assesses whether Mixed Mode is needed, and enables policy on all SQL logins."}	null	medium	t	t	\N	2026-02-24 13:10:27.72849
4383	sqlserver	verify	Verify hardening applied	{"sql": "SELECT\\n  (SELECT is_disabled FROM sys.server_principals WHERE sid = 0x01) AS sa_disabled,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_policy_checked = 0) AS no_policy_count,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only;", "parameters": [], "description": "Confirms sa is disabled and all SQL logins have policy enforcement."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.728864
4386	sqlserver	verify	Verify service account security posture	{"sql": "SELECT sp.name, sp.type_desc,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) AS password_age_days\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa';", "parameters": [], "description": "Shows the security posture of all remaining SQL Auth accounts including policy enforcement and password age."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.729813
4387	sqlserver	execute	Assess SQL Auth usage and harden or eliminate	{"sql": "-- Step 1: Check if any SQL Auth sessions are active\\nSELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(DISTINCT login_name) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND login_name IN (SELECT sp.name FROM sys.sql_logins sl\\n       JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id)) AS sql_auth_active_users,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS total_active_sql_logins;\\n\\n-- Step 2: If no SQL Auth sessions, all SQL logins can be disabled\\n-- Step 3: Disable unused SQL logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE unused_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND NOT EXISTS (\\n      SELECT 1 FROM sys.dm_exec_sessions s\\n      WHERE s.login_name = sp.name AND s.is_user_process = 1\\n    );\\nOPEN unused_cursor;\\nFETCH NEXT FROM unused_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling unused SQL login: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM unused_cursor INTO @login;\\nEND;\\nCLOSE unused_cursor; DEALLOCATE unused_cursor;", "parameters": [], "description": "Assesses actual SQL Auth usage and disables unused SQL logins. If no SQL logins are actively used, the instance can be switched to Windows-only mode."}	null	medium	t	t	\N	2026-02-24 13:10:27.73024
4388	sqlserver	verify	Verify SQL login reduction and policy compliance	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS remaining_sql_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G') AND is_disabled = 0) AS windows_logins;", "parameters": [], "description": "Shows the current state of SQL vs Windows logins to track progress toward Windows-only mode."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.730618
4392	sqlserver	verify	Verify Kerberos authentication is working and SQL Auth is minimized	{"sql": "SELECT\\n  auth_scheme,\\n  COUNT(*) AS connection_count,\\n  COUNT(DISTINCT s.login_name) AS distinct_logins\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1 AND c.parent_connection_id IS NULL\\nGROUP BY auth_scheme\\nORDER BY connection_count DESC;", "parameters": [], "description": "Shows the distribution of authentication methods. Kerberos should be the dominant method with minimal SQL Auth usage."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.734133
4394	sqlserver	verify	Verify SQL Auth sessions reduced after migration	{"sql": "SELECT\\n  SUM(CASE WHEN c.auth_scheme = 'SQL' THEN 1 ELSE 0 END) AS sql_auth_sessions,\\n  SUM(CASE WHEN c.auth_scheme IN ('KERBEROS', 'NTLM') THEN 1 ELSE 0 END) AS windows_auth_sessions,\\n  COUNT(*) AS total_sessions,\\n  ROUND(SUM(CASE WHEN c.auth_scheme = 'SQL' THEN 1.0 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100, 1) AS pct_sql_auth\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1 AND c.parent_connection_id IS NULL;", "parameters": [], "description": "Shows the ratio of SQL Auth to Windows Auth sessions. The percentage of SQL Auth should decrease after migration."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.734885
4396	sqlserver	verify	Verify compliance audit is active and scanning	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications WHERE is_state_enabled = 1) AS active_specs,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND DATEDIFF(DAY, sp.create_date, GETDATE()) < 90) AS recent_sql_logins;", "parameters": [], "description": "Confirms compliance audit is running and shows any recently created SQL logins that need review."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.735572
32351	mariadb	verify	mysql_verify_parallel_workers_reducing_lag	{"sql": "SELECT WORKER_ID, SERVICE_STATE, LAST_ERROR_MESSAGE, LAST_APPLIED_TRANSACTION\\nFROM performance_schema.replication_applier_status_by_worker;\\nSHOW REPLICA STATUS\\\\G\\nSELECT CHANNEL_NAME, LAST_ERROR_NUMBER, LAST_ERROR_MESSAGE\\nFROM performance_schema.replication_applier_status_by_coordinator;", "parameters": null, "description": "Confirm all parallel workers are active and replication lag is trending toward zero."}	\N	low	f	t	15 minutes	2026-05-11 22:17:39.229791
4398	sqlserver	verify	Verify audit is active and dormancy report is functional	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP')) AS login_audit_actions,\\n  (SELECT COUNT(*) FROM sys.server_principals sp\\n   WHERE sp.type IN ('S', 'U', 'G') AND sp.is_disabled = 0\\n     AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n     AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL) AS dormant_candidates;", "parameters": [], "description": "Confirms login audit is active and reports the number of potentially dormant accounts."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.736375
4399	sqlserver	execute	Disable accounts with no recent activity and old modification dates	{"sql": "-- Step 1: Identify dormant accounts (no sessions, old modify date)\\nSELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_dormant,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND sp.name NOT LIKE '%svc%' AND sp.name NOT LIKE '%service%' AND sp.name NOT LIKE '%app%'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n  AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180\\nORDER BY sp.modify_date ASC;\\n\\n-- Step 2: Disable dormant accounts\\nDECLARE @login NVARCHAR(256);\\nDECLARE dorm_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.server_principals sp\\n  WHERE sp.type IN ('S', 'U')\\n    AND sp.is_disabled = 0\\n    AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n    AND sp.name <> 'sa'\\n    AND sp.name NOT LIKE '%svc%' AND sp.name NOT LIKE '%service%'\\n    AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n    AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180;\\nOPEN dorm_cursor;\\nFETCH NEXT FROM dorm_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling dormant account: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM dorm_cursor INTO @login;\\nEND;\\nCLOSE dorm_cursor; DEALLOCATE dorm_cursor;", "parameters": [], "description": "Identifies accounts with no sessions and no activity for 180+ days (excluding service accounts), then disables them."}	{"sql": "-- Re-enable if an account was incorrectly disabled\\n-- ALTER LOGIN [login_name] ENABLE;", "description": "Re-enable accounts that were incorrectly identified as dormant."}	med