4400	sqlserver	verify	Verify dormant accounts disabled	{"sql": "SELECT COUNT(*) AS remaining_dormant\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND sp.name NOT LIKE '%svc%' AND sp.name NOT LIKE '%service%'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n  AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180;", "parameters": [], "description": "Confirms all dormant non-service accounts have been disabled."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.737262
4401	sqlserver	execute	Identify and disable orphaned service accounts	{"sql": "-- Step 1: Identify service accounts with no recent activity\\nSELECT sp.name, sp.type_desc, sp.create_date,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name AND is_user_process = 1) AS active_sessions\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (sp.name LIKE '%svc%' OR sp.name LIKE '%service%' OR sp.name LIKE '%app%'\\n    OR sp.name LIKE '%job%' OR sp.name LIKE '%batch%' OR sp.name LIKE '%etl%'\\n    OR sp.name LIKE '%agent%' OR sp.name LIKE '%daemon%')\\n  AND (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name AND is_user_process = 1) = 0\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 365\\nORDER BY sp.create_date ASC;\\n\\n-- Step 2: Disable orphaned service accounts\\n-- Review each account before disabling\\n-- ALTER LOGIN [orphaned_svc_account] DISABLE;", "parameters": [], "description": "Identifies service-pattern accounts older than 365 days with no active sessions. These are candidates for orphaned service accounts from decommissioned applications."}	{"sql": "-- Re-enable if an account was still needed\\n-- ALTER LOGIN [service_account] ENABLE;", "description": "Re-enable a service account if disabling it disrupts a previously unknown dependency."}	medium	t	t	\N	2026-02-24 13:10:27.737606
4464	sqlserver	verify	Confirm sa is disabled and no recovery accounts remain	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.server_principals sp\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.name NOT LIKE '##%'\\n  AND IS_SRVROLEMEMBER('sysadmin', sp.name) = 1\\nORDER BY sp.name;", "parameters": [], "description": "Confirms only legitimate sysadmin logins remain, sa is disabled, and all recovery artifacts are removed."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.750992
4403	sqlserver	execute	Disable stale contractor accounts and enforce expiration on active ones	{"sql": "-- Step 1: Disable contractor-pattern accounts with no recent activity\\nDECLARE @login NVARCHAR(256);\\nDECLARE contractor_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.server_principals sp\\n  WHERE sp.type IN ('S', 'U')\\n    AND sp.is_disabled = 0\\n    AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n    AND (sp.name LIKE '%contractor%' OR sp.name LIKE '%vendor%' OR sp.name LIKE '%extern%'\\n      OR sp.name LIKE '%consult%' OR sp.name LIKE '%partner%' OR sp.name LIKE '%guest%'\\n      OR sp.name LIKE '%temp_%')\\n    AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n    AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 90;\\nOPEN contractor_cursor;\\nFETCH NEXT FROM contractor_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling stale contractor: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM contractor_cursor INTO @login;\\nEND;\\nCLOSE contractor_cursor; DEALLOCATE contractor_cursor;\\n\\n-- Step 2: Enable expiration on remaining active contractor accounts\\nDECLARE active_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND sl.is_expiration_checked = 0;\\nOPEN active_cursor;\\nFETCH NEXT FROM active_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM active_cursor INTO @login;\\nEND;\\nCLOSE active_cursor; DEALLOCATE active_cursor;", "parameters": [], "description": "Disables stale contractor accounts and enables password expiration on all remaining SQL logins to ensure automatic credential expiry."}	null	medium	t	t	\N	2026-02-24 13:10:27.738532
4404	sqlserver	verify	Verify stale contractor accounts disabled and expiration enforced	{"sql": "SELECT sp.name, sp.is_disabled,\\n  CASE WHEN sp.type = 'S' THEN sl.is_expiration_checked ELSE NULL END AS has_expiration,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.server_principals sp\\nLEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n  AND (sp.name LIKE '%contractor%' OR sp.name LIKE '%vendor%' OR sp.name LIKE '%extern%'\\n    OR sp.name LIKE '%consult%' OR sp.name LIKE '%partner%' OR sp.name LIKE '%guest%');", "parameters": [], "description": "Shows the status of all contractor-pattern accounts to verify stale ones are disabled and active ones have expiration."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.738876
4405	sqlserver	execute	Disable project-pattern logins and enforce expiration on temporary accounts	{"sql": "-- Step 1: Disable project-pattern logins with no recent activity\\nDECLARE @login NVARCHAR(256);\\nDECLARE proj_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.server_principals sp\\n  LEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\n  WHERE sp.type IN ('S', 'U')\\n    AND sp.is_disabled = 0\\n    AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n    AND (sp.name LIKE '%proj%' OR sp.name LIKE '%project%' OR sp.name LIKE '%migration%'\\n      OR sp.name LIKE '%temp%' OR sp.name LIKE '%tmp%' OR sp.name LIKE '%pilot%'\\n      OR sp.name LIKE '%poc%' OR sp.name LIKE '%trial%' OR sp.name LIKE '%phase%')\\n    AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL;\\nOPEN proj_cursor;\\nFETCH NEXT FROM proj_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling project login: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM proj_cursor INTO @login;\\nEND;\\nCLOSE proj_cursor; DEALLOCATE proj_cursor;\\n\\n-- Step 2: Enforce expiration on all SQL logins without it\\nDECLARE exp_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n    AND sl.is_expiration_checked = 0;\\nOPEN exp_cursor;\\nFETCH NEXT FROM exp_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login;\\n  END CATCH\\n  FETCH NEXT FROM exp_cursor INTO @login;\\nEND;\\nCLOSE exp_cursor; DEALLOCATE exp_cursor;", "parameters": [], "description": "Disables project-pattern logins with no activity and enforces password expiration on all remaining SQL logins."}	null	medium	t	t	\N	2026-02-24 13:10:27.739233
4406	sqlserver	verify	Verify project accounts disabled and expiration enforced	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals sp\\n   WHERE sp.type IN ('S', 'U') AND sp.is_disabled = 0\\n     AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n     AND (sp.name LIKE '%proj%' OR sp.name LIKE '%temp%' OR sp.name LIKE '%poc%'\\n       OR sp.name LIKE '%pilot%' OR sp.name LIKE '%migration%')\\n     AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL) AS remaining_project_logins,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%'\\n     AND sl.is_expiration_checked = 0) AS no_expiration_count;", "parameters": [], "description": "Confirms all project-pattern logins are disabled and all remaining logins have expiration enforcement."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.739645
4963	sqlserver	instruct	Restrict database creation to DBA team only	{"sql": null, "parameters": [], "description": "Prevent tenants from creating databases on the shared instance: (1) Remove tenant logins from the dbcreator server role: ALTER SERVER ROLE [dbcreator] DROP MEMBER [TenantLogin]. (2) Revoke CREATE ANY DATABASE from non-DBA logins. (3) Implement a DDL trigger to log and optionally block CREATE DATABASE events. (4) Establish a request process for new databases that includes DBA review."}	null	low	f	t	04:00:00	2026-02-24 13:10:27.801049
4408	sqlserver	execute	Create DDL trigger to block dev/test account creation in production	{"sql": "-- Prevent future dev/test account creation in production\\nIF EXISTS (SELECT 1 FROM sys.server_triggers WHERE name = 'trg_BlockDevTestLogins')\\n  DROP TRIGGER trg_BlockDevTestLogins ON ALL SERVER;\\nGO\\nCREATE TRIGGER trg_BlockDevTestLogins\\nON ALL SERVER\\nFOR CREATE_LOGIN\\nAS\\nBEGIN\\n  DECLARE @login_name NVARCHAR(256);\\n  SET @login_name = EVENTDATA().value('(/EVENT_INSTANCE/ObjectName)[1]', 'NVARCHAR(256)');\\n  IF @login_name LIKE '%test%' OR @login_name LIKE '%dev%' OR @login_name LIKE '%debug%'\\n    OR @login_name LIKE '%qa%' OR @login_name LIKE '%staging%' OR @login_name LIKE '%demo%'\\n    OR @login_name LIKE '%sample%' OR @login_name LIKE '%sandbox%'\\n  BEGIN\\n    PRINT 'BLOCKED: Dev/test-pattern login creation is not allowed in production. Login: ' + @login_name;\\n    ROLLBACK;\\n  END\\nEND;", "parameters": [], "description": "Creates a server-level DDL trigger that blocks creation of logins with dev/test naming patterns in production. This prevents future environment migration from reintroducing the problem."}	{"sql": "DROP TRIGGER trg_BlockDevTestLogins ON ALL SERVER;", "description": "Remove the DDL trigger if it blocks legitimate account creation."}	medium	t	t	\N	2026-02-24 13:10:27.740125
