4468	sqlserver	verify	Check existing audit and policy infrastructure	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications WHERE is_state_enabled = 1) AS active_specs,\\n  (SELECT COUNT(*) FROM msdb.dbo.syspolicy_policies WHERE is_enabled = 1) AS active_policies;", "parameters": [], "description": "Determines if audit and policy infrastructure already exists that can be extended."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.750996
4469	sqlserver	execute	Create server audit and specification for configuration change detection	{"sql": "-- Create or reuse existing audit\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'SecurityConfigAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [SecurityConfigAudit]\\n  TO FILE (FILEPATH = @audit_file_path, MAXSIZE = 50 MB, MAX_ROLLOVER_FILES = 20)\\n  WITH (ON_FAILURE = CONTINUE);\\nEND;\\n\\nALTER SERVER AUDIT [SecurityConfigAudit] WITH (STATE = ON);\\n\\nCREATE SERVER AUDIT SPECIFICATION [ConfigDriftDetection]\\nFOR SERVER AUDIT [SecurityConfigAudit]\\nADD (SERVER_OBJECT_CHANGE_GROUP),\\nADD (SERVER_STATE_CHANGE_GROUP),\\nADD (SERVER_PERMISSION_CHANGE_GROUP),\\nADD (SERVER_ROLE_MEMBER_CHANGE_GROUP),\\nADD (SERVER_PRINCIPAL_CHANGE_GROUP),\\nADD (AUDIT_CHANGE_GROUP)\\nWITH (STATE = ON);", "parameters": ["audit_file_path"], "description": "Creates an audit specification that captures all server-level configuration changes, permission changes, and role membership changes."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [ConfigDriftDetection] WITH (STATE = OFF);\\nDROP SERVER AUDIT SPECIFICATION [ConfigDriftDetection];\\nALTER SERVER AUDIT [SecurityConfigAudit] WITH (STATE = OFF);\\nDROP SERVER AUDIT [SecurityConfigAudit];", "description": "Removes the audit infrastructure if causing issues."}	low	t	t	00:05:00	2026-02-24 13:10:27.750996
4472	sqlserver	verify	Confirm no audits exist and identify SQL Server edition capabilities	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits) AS audit_count,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications) AS spec_count,\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('EngineEdition') AS engine_edition;", "parameters": [], "description": "Verifies that no audit infrastructure exists and confirms the SQL Server edition supports auditing."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.750998
4489	sqlserver	configure	Optimize audit settings for minimal performance impact and re-enable	{"sql": "ALTER SERVER AUDIT [@audit_name] WITH (\\n  QUEUE_DELAY = 1000,\\n  STATE = OFF\\n);\\n\\n-- Increase file settings if too small\\nALTER SERVER AUDIT [@audit_name]\\nTO FILE (MAXSIZE = 100 MB, MAX_ROLLOVER_FILES = 50);\\n\\nALTER SERVER AUDIT [@audit_name] WITH (STATE = ON);", "parameters": ["audit_name"], "description": "Sets the queue delay to 1000ms (batches writes for efficiency), increases file size limits to reduce rollover frequency, and re-enables the audit."}	{"sql": "ALTER SERVER AUDIT [@audit_name] WITH (STATE = OFF);", "description": "Disables the audit if performance impact is still unacceptable."}	low	t	t	00:01:00	2026-02-24 13:10:27.751013
4473	sqlserver	execute	Create the server audit and server-level audit specification	{"sql": "CREATE SERVER AUDIT [PrimaryAudit]\\nTO FILE (FILEPATH = @audit_file_path, MAXSIZE = 100 MB, MAX_ROLLOVER_FILES = 50, RESERVE_DISK_SPACE = OFF)\\nWITH (QUEUE_DELAY = 1000, ON_FAILURE = CONTINUE);\\n\\nALTER SERVER AUDIT [PrimaryAudit] WITH (STATE = ON);\\n\\nCREATE SERVER AUDIT SPECIFICATION [ServerAuditSpec]\\nFOR SERVER AUDIT [PrimaryAudit]\\nADD (FAILED_LOGIN_GROUP),\\nADD (SUCCESSFUL_LOGIN_GROUP),\\nADD (SERVER_ROLE_MEMBER_CHANGE_GROUP),\\nADD (SERVER_PERMISSION_CHANGE_GROUP),\\nADD (SERVER_PRINCIPAL_CHANGE_GROUP),\\nADD (AUDIT_CHANGE_GROUP),\\nADD (SERVER_OBJECT_CHANGE_GROUP),\\nADD (DATABASE_CHANGE_GROUP)\\nWITH (STATE = ON);", "parameters": ["audit_file_path"], "description": "Creates a file-based audit with a comprehensive server-level specification capturing login events, role changes, permission changes, and configuration changes."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [ServerAuditSpec] WITH (STATE = OFF);\\nDROP SERVER AUDIT SPECIFICATION [ServerAuditSpec];\\nALTER SERVER AUDIT [PrimaryAudit] WITH (STATE = OFF);\\nDROP SERVER AUDIT [PrimaryAudit];", "description": "Removes all audit infrastructure if performance issues arise."}	low	t	t	00:05:00	2026-02-24 13:10:27.750999
4474	sqlserver	verify	Confirm audit is active and capturing events	{"sql": "SELECT sa.name AS audit_name, sa.is_state_enabled AS audit_enabled,\\n  sa.type_desc AS destination,\\n  sas.name AS spec_name, sas.is_state_enabled AS spec_enabled,\\n  COUNT(sasd.audit_action_id) AS action_groups\\nFROM sys.server_audits sa\\nJOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nJOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nWHERE sa.name = 'PrimaryAudit'\\nGROUP BY sa.name, sa.is_state_enabled, sa.type_desc, sas.name, sas.is_state_enabled;\\n\\nSELECT TOP 5 event_time, action_id, server_principal_name, statement\\nFROM sys.fn_get_audit_file(@audit_file_path + '*', DEFAULT, DEFAULT)\\nORDER BY event_time DESC;", "parameters": ["audit_file_path"], "description": "Verifies the audit is enabled and already capturing events."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.751
4475	sqlserver	verify	Identify audits without specifications	{"sql": "SELECT sa.name AS audit_name, sa.is_state_enabled,\\n  sa.type_desc AS destination,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas WHERE sas.audit_guid = sa.audit_guid AND sas.is_state_enabled = 1) AS active_server_specs,\\n  (SELECT COUNT(*) FROM sys.database_audit_specifications das WHERE das.audit_guid = sa.audit_guid AND das.is_state_enabled = 1) AS active_db_specs\\nFROM sys.server_audits sa;", "parameters": [], "description": "Finds audits that are running but have no active specifications capturing events."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.751001
