4477	sqlserver	verify	Confirm specification is active and linked to the audit	{"sql": "SELECT sa.name AS audit_name, sa.is_state_enabled,\\n  sas.name AS spec_name, sas.is_state_enabled AS spec_enabled,\\n  sasd.audit_action_name\\nFROM sys.server_audits sa\\nJOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nJOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nWHERE sas.is_state_enabled = 1;", "parameters": [], "description": "Verifies the audit specification is enabled and the action groups are properly configured."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.751002
4478	sqlserver	verify	Check which critical action groups are missing	{"sql": "SELECT action_name AS required_group,\\n  CASE WHEN EXISTS (\\n    SELECT 1 FROM sys.server_audit_specification_details sasd\\n    JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n    WHERE sas.is_state_enabled = 1 AND sasd.audit_action_name = da.action_name\\n  ) THEN 'PRESENT' ELSE 'MISSING' END AS status\\nFROM (\\n  VALUES ('FAILED_LOGIN_GROUP'), ('SUCCESSFUL_LOGIN_GROUP'),\\n    ('SERVER_ROLE_MEMBER_CHANGE_GROUP'), ('DATABASE_PERMISSION_CHANGE_GROUP'),\\n    ('SCHEMA_OBJECT_ACCESS_GROUP'), ('AUDIT_CHANGE_GROUP'),\\n    ('SERVER_PERMISSION_CHANGE_GROUP'), ('SERVER_PRINCIPAL_CHANGE_GROUP')\\n) da(action_name);", "parameters": [], "description": "Identifies which critical audit action groups are missing from the current specification."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.751003
