4588	sqlserver	verify	Analyze login failure patterns for connection pool behavior	{"sql": "CREATE TABLE #LoginFailures (LogDate DATETIME, ProcessInfo VARCHAR(50), Text NVARCHAR(MAX));\\nINSERT INTO #LoginFailures EXEC xp_readerrorlog 0, 1, N'Login failed';\\nSELECT\\n  SUBSTRING(Text, CHARINDEX('[CLIENT:', Text) + 8,\\n    CHARINDEX(']', Text, CHARINDEX('[CLIENT:', Text)) - CHARINDEX('[CLIENT:', Text) - 8) AS client_ip,\\n  COUNT(*) AS failure_count,\\n  MIN(LogDate) AS first_failure, MAX(LogDate) AS last_failure,\\n  DATEDIFF(SECOND, MIN(LogDate), MAX(LogDate)) AS span_seconds\\nFROM #LoginFailures\\nWHERE LogDate > DATEADD(HOUR, -24, GETDATE()) AND Text LIKE '%[CLIENT:%'\\nGROUP BY SUBSTRING(Text, CHARINDEX('[CLIENT:', Text) + 8,\\n  CHARINDEX(']', Text, CHARINDEX('[CLIENT:', Text)) - CHARINDEX('[CLIENT:', Text) - 8)\\nHAVING COUNT(*) > 5 ORDER BY failure_count DESC;\\nDROP TABLE #LoginFailures;", "parameters": [], "description": "Identifies rapid login failure bursts from the same source, which indicate connection pool retry behavior."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.751071
