4691	sqlserver	verify	Find objects with GRANT to rootcause alongside DENY indicating incomplete revocation	{"sql": "SELECT 'STILL_GRANTED' AS status, dp.permission_name,\\n  OBJECT_SCHEMA_NAME(dp.major_id) + '.' + OBJECT_NAME(dp.major_id) AS object_name, o.type_desc\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'rootcause' AND dp.state_desc = 'GRANT' AND dp.class_desc = 'OBJECT_OR_COLUMN' AND o.is_ms_shipped = 0\\n  AND dp.permission_name IN (\\n    SELECT dp2.permission_name FROM sys.database_permissions dp2\\n    JOIN sys.database_principals pr2 ON dp2.grantee_principal_id = pr2.principal_id\\n    WHERE pr2.name = 'rootcause' AND dp2.state_desc = 'DENY' AND dp2.class_desc = 'OBJECT_OR_COLUMN');", "parameters": [], "description": "Finds objects still granted to rootcause for permissions that are also denied on other objects."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.779467
4692	sqlserver	execute	Complete the revocation by revoking remaining GRANT and removing DENY	{"sql": "-- Revoke remaining GRANTs (run per-object)\\nREVOKE [@permission_name] ON OBJECT::[@schema_name].[@object_name] FROM [rootcause];\\n\\n-- Remove DENYs (REVOKE removes DENY state)\\nREVOKE [@permission_name] ON OBJECT::[@denied_schema].[@denied_object] FROM [rootcause];", "parameters": ["permission_name", "schema_name", "object_name", "denied_schema", "denied_object"], "description": "Revokes all remaining rootcause grants and removes unnecessary DENYs for a clean permission state."}	{"sql": "GRANT [@permission_name] ON OBJECT::[@schema_name].[@object_name] TO [rootcause];", "description": "Re-grants the permission if needed."}	low	t	t	\N	2026-02-24 13:10:27.780625
4694	sqlserver	verify	Find rootcause EXECUTE grants on stored procedures and functions	{"sql": "SELECT OBJECT_SCHEMA_NAME(dp.major_id) AS schema_name,\\n  OBJECT_NAME(dp.major_id) AS object_name, o.type_desc,\\n  CASE\\n    WHEN OBJECT_NAME(dp.major_id) LIKE '%report%' THEN 'reporting-tool'\\n    WHEN OBJECT_NAME(dp.major_id) LIKE '%monitor%' THEN 'monitoring-tool'\\n    WHEN OBJECT_SCHEMA_NAME(dp.major_id) NOT IN ('dbo', 'sys') THEN 'vendor-schema'\\n    ELSE 'application' END AS likely_source\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'rootcause' AND dp.state_desc = 'GRANT' AND dp.permission_name = 'EXECUTE'\\n  AND o.is_ms_shipped = 0 AND o.type IN ('P', 'FN', 'IF', 'TF');", "parameters": [], "description": "Lists stored procedures and functions with rootcause EXECUTE, categorized by likely source."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.7822
4695	sqlserver	execute	Revoke rootcause EXECUTE and create tool-specific roles	{"sql": "-- Create tool-specific execution role\\nCREATE ROLE [role_vendor_tool];\\nGRANT EXECUTE ON OBJECT::[@schema_name].[@proc_name] TO [role_vendor_tool];\\n\\n-- Revoke from rootcause\\nREVOKE EXECUTE ON OBJECT::[@schema_name].[@proc_name] FROM [rootcause];", "parameters": ["schema_name", "proc_name"], "description": "Creates a dedicated role for vendor tool procedures and revokes rootcause EXECUTE."}	{"sql": "GRANT EXECUTE ON OBJECT::[@schema_name].[@proc_name] TO [rootcause];", "description": "Re-grants EXECUTE to rootcause."}	medium	t	t	\N	2026-02-24 13:10:27.78283
