4711	sqlserver	verify	Assess SQL Authentication dependency	{"sql": "SELECT\\n  SUM(CASE WHEN sp.type = 'S' THEN 1 ELSE 0 END) AS sql_logins,\\n  SUM(CASE WHEN sp.type = 'U' THEN 1 ELSE 0 END) AS windows_logins,\\n  SUM(CASE WHEN sp.type = 'G' THEN 1 ELSE 0 END) AS windows_groups,\\n  CAST(SUM(CASE WHEN sp.type = 'S' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) AS DECIMAL(5,1)) AS pct_sql_auth\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G') AND sp.name NOT LIKE '##%' AND sp.name NOT IN ('sa') AND sp.is_disabled = 0;", "parameters": [], "description": "Shows the current proportion of SQL vs Windows authentication."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.784935
4724	sqlserver	verify	Identify shared accounts with multi-host sessions	{"sql": "SELECT s.login_name,\\n  COUNT(*) AS total_sessions,\\n  COUNT(DISTINCT s.host_name) AS distinct_hosts,\\n  COUNT(DISTINCT s.program_name) AS distinct_programs,\\n  STRING_AGG(DISTINCT s.host_name, ', ') AS host_list\\nFROM sys.dm_exec_sessions s\\nJOIN sys.server_principals sp ON s.login_name = sp.name\\nWHERE s.is_user_process = 1 AND sp.type_desc = 'SQL_LOGIN' AND sp.name NOT LIKE '##%'\\nGROUP BY s.login_name\\nHAVING COUNT(DISTINCT s.host_name) > 1;", "parameters": [], "description": "Finds SQL logins with concurrent sessions from multiple hosts, indicating shared usage."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.787325
4697	sqlserver	verify	Find emergency-level rootcause grants	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  CASE dp.class_desc\\n    WHEN 'DATABASE' THEN DB_NAME()\\n    WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id)\\n    ELSE OBJECT_SCHEMA_NAME(dp.major_id) + '.' + OBJECT_NAME(dp.major_id) END AS scope,\\n  CASE\\n    WHEN dp.permission_name IN ('ALTER', 'CONTROL', 'ALTER ANY SCHEMA', 'ALTER ANY USER') THEN 'EMERGENCY_LEVEL'\\n    WHEN dp.permission_name IN ('INSERT', 'UPDATE', 'DELETE') AND dp.class_desc = 'SCHEMA' THEN 'EMERGENCY_LEVEL'\\n    ELSE 'ELEVATED' END AS risk_classification\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'rootcause' AND dp.state_desc = 'GRANT'\\n  AND dp.permission_name IN ('ALTER', 'CONTROL', 'ALTER ANY SCHEMA', 'ALTER ANY USER', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE')\\n  AND (dp.class_desc IN ('DATABASE', 'SCHEMA') OR (dp.class_desc = 'OBJECT_OR_COLUMN' AND dp.permission_name IN ('ALTER', 'CONTROL')));", "parameters": [], "description": "Lists emergency-level rootcause grants that should never persist in production."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.783129
4698	sqlserver	execute	Revoke all emergency-level rootcause grants	{"sql": "-- Revoke emergency rootcause grants (run per-scope)\\nREVOKE ALTER ON DATABASE::[@database_name] FROM [rootcause];\\nREVOKE CONTROL ON DATABASE::[@database_name] FROM [rootcause];\\nREVOKE ALTER ANY SCHEMA FROM [rootcause];\\nREVOKE ALTER ANY USER FROM [rootcause];\\n\\n-- Revoke schema-level DML from rootcause\\nREVOKE INSERT ON SCHEMA::[@schema_name] FROM [rootcause];\\nREVOKE UPDATE ON SCHEMA::[@schema_name] FROM [rootcause];\\nREVOKE DELETE ON SCHEMA::[@schema_name] FROM [rootcause];", "parameters": ["database_name", "schema_name"], "description": "Revokes all emergency-level rootcause grants immediately."}	null	medium	t	t	\N	2026-02-24 13:10:27.783551
