4727	sqlserver	verify	Find orphaned users with role memberships across databases	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  dr.name AS role_name, dp.create_date, dp.modify_date,\\n  CASE WHEN sp.sid IS NULL THEN 'ORPHANED' ELSE 'MAPPED' END AS mapping_status\\nFROM sys.database_principals dp\\nJOIN sys.database_role_members drm ON dp.principal_id = drm.member_principal_id\\nJOIN sys.database_principals dr ON drm.role_principal_id = dr.principal_id\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G') AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys')\\n  AND dp.sid IS NOT NULL AND dp.sid <> 0x00 AND sp.sid IS NULL\\nORDER BY dp.name, dr.name;", "parameters": [], "description": "Lists orphaned users with their database role memberships."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.787962
4728	sqlserver	execute	Remove orphaned users from database roles and drop them	{"sql": "-- Remove from roles first (run per-role per-user)\\nALTER ROLE [@role_name] DROP MEMBER [@orphaned_user];\\n\\n-- Transfer schema ownership if needed\\nALTER AUTHORIZATION ON SCHEMA::[@schema_name] TO [dbo];\\n\\n-- Drop the orphaned user\\nDROP USER [@orphaned_user];", "parameters": ["role_name", "orphaned_user", "schema_name"], "description": "Removes role memberships, transfers schema ownership, and drops the orphaned user."}	null	medium	t	f	\N	2026-02-24 13:10:27.788397
