4809	sqlserver	verify	Check for unintended chaining scope via shared ownership	{"sql": "SELECT sp.name AS db_owner,\\n  COUNT(*) AS databases_owned,\\n  SUM(CASE WHEN d.is_db_chaining_on = 1 THEN 1 ELSE 0 END) AS chaining_enabled_count,\\n  STRING_AGG(d.name, ', ') AS all_databases,\\n  STRING_AGG(CASE WHEN d.is_db_chaining_on = 1 THEN d.name END, ', ') AS chaining_databases\\nFROM sys.databases d\\nLEFT JOIN sys.server_principals sp ON d.owner_sid = sp.sid\\nWHERE d.state = 0 AND d.database_id > 4\\nGROUP BY sp.name\\nHAVING COUNT(*) > 1\\nORDER BY chaining_enabled_count DESC;", "parameters": [], "description": "Shows owners with multiple databases and the scope of chaining across them."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.797142
4828	sqlserver	configure	Disable server-level and per-database cross-database chaining	{"sql": "EXEC sp_configure 'cross db ownership chaining', 0;\\nRECONFIGURE;\\n\\n-- Disable per-database chaining for each identified user database\\n-- ALTER DATABASE [DatabaseName] SET DB_CHAINING OFF;", "parameters": [], "description": "Disables server-level chaining and provides the template for disabling per-database chaining. DBA must execute ALTER DATABASE for each identified database after confirming no legitimate dependencies."}	{"sql": "EXEC sp_configure 'cross db ownership chaining', 1;\\nRECONFIGURE;\\n-- ALTER DATABASE [DatabaseName] SET DB_CHAINING ON;", "description": "Re-enables chaining if application breakage occurs."}	medium	t	t	00:05:00	2026-02-24 13:10:27.800955
