4842	sqlserver	verify	Identify all principals with GRANT OPTION and their delegation chains	{"sql": "SELECT sp.name AS principal_name, sp.type_desc,\\n  perm.permission_name, perm.state_desc, perm.class_desc,\\n  CASE\\n    WHEN perm.permission_name IN ('CONTROL SERVER', 'ALTER ANY DATABASE', 'ALTER ANY LOGIN') THEN 'CRITICAL'\\n    WHEN perm.permission_name LIKE 'ALTER ANY%' THEN 'HIGH'\\n    ELSE 'STANDARD'\\n  END AS risk_level\\nFROM sys.server_permissions perm\\nJOIN sys.server_principals sp ON perm.grantee_principal_id = sp.principal_id\\nWHERE perm.state_desc = 'GRANT_WITH_GRANT_OPTION'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\nORDER BY risk_level, sp.name;\\n\\nSELECT dp.name AS principal_name, dp.type_desc,\\n  perm.permission_name, perm.state_desc, perm.class_desc\\nFROM sys.database_permissions perm\\nJOIN sys.database_principals dp ON perm.grantee_principal_id = dp.principal_id\\nWHERE perm.state_desc = 'GRANT_WITH_GRANT_OPTION'\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys')\\nORDER BY dp.name;", "parameters": [], "description": "Lists all server-level and database-level permissions granted with GRANT OPTION, categorized by risk level."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.800965
