4854	sqlserver	execute	Create or extend audit specification for permission delegation monitoring	{"sql": "-- Create audit if one does not exist\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'PermissionDelegationAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [PermissionDelegationAudit]\\n  TO FILE (FILEPATH = @audit_file_path, MAXSIZE = 100 MB, MAX_ROLLOVER_FILES = 10)\\n  WITH (ON_FAILURE = CONTINUE);\\nEND;\\n\\nALTER SERVER AUDIT [PermissionDelegationAudit] WITH (STATE = ON);\\n\\nCREATE SERVER AUDIT SPECIFICATION [PermissionDelegationSpec]\\nFOR SERVER AUDIT [PermissionDelegationAudit]\\nADD (DATABASE_PERMISSION_CHANGE_GROUP),\\nADD (SERVER_PERMISSION_CHANGE_GROUP),\\nADD (SCHEMA_OBJECT_PERMISSION_CHANGE_GROUP),\\nADD (DATABASE_ROLE_MEMBER_CHANGE_GROUP),\\nADD (SERVER_ROLE_MEMBER_CHANGE_GROUP)\\nWITH (STATE = ON);", "parameters": ["audit_file_path"], "description": "Creates a comprehensive audit specification capturing all permission-related changes at both server and database level."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [PermissionDelegationSpec] WITH (STATE = OFF);\\nDROP SERVER AUDIT SPECIFICATION [PermissionDelegationSpec];\\nALTER SERVER AUDIT [PermissionDelegationAudit] WITH (STATE = OFF);\\nDROP SERVER AUDIT [PermissionDelegationAudit];", "description": "Removes the audit specification and audit."}	low	t	t	00:05:00	2026-02-24 13:10:27.800973
