4876	sqlserver	verify	Identify principals violating separation of duties	{"sql": "SELECT dp.name AS principal_name, dp.type_desc,\\n  STRING_AGG(DISTINCT r.name, ', ') AS role_memberships,\\n  SUM(CASE WHEN r.name IN ('db_datareader', 'db_datawriter') THEN 1 ELSE 0 END) AS data_roles,\\n  SUM(CASE WHEN r.name IN ('db_owner', 'db_securityadmin', 'db_ddladmin') THEN 1 ELSE 0 END) AS admin_roles\\nFROM sys.database_role_members rm\\nJOIN sys.database_principals dp ON rm.member_principal_id = dp.principal_id\\nJOIN sys.database_principals r ON rm.role_principal_id = r.principal_id\\nWHERE dp.type IN ('S', 'U', 'G') AND dp.name NOT IN ('dbo', 'guest')\\nGROUP BY dp.name, dp.type_desc\\nHAVING SUM(CASE WHEN r.name IN ('db_datareader', 'db_datawriter') THEN 1 ELSE 0 END) > 0\\n  AND SUM(CASE WHEN r.name IN ('db_owner', 'db_securityadmin', 'db_ddladmin') THEN 1 ELSE 0 END) > 0;", "parameters": [], "description": "Finds users who are members of both data access roles (reader/writer) and administrative roles (owner/security/ddl admin)."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.80099
4877	sqlserver	execute	Remove data roles from administrative accounts and vice versa	{"sql": "-- For users who should be data users only, remove admin roles:\\n-- ALTER ROLE [db_securityadmin] DROP MEMBER [DataUser];\\n-- ALTER ROLE [db_ddladmin] DROP MEMBER [DataUser];\\n\\n-- For users who should be admins only, remove data roles:\\n-- ALTER ROLE [db_datareader] DROP MEMBER [AdminUser];\\n-- ALTER ROLE [db_datawriter] DROP MEMBER [AdminUser];\\n\\n-- Revoke any GRANT OPTION from data-only users:\\n-- REVOKE GRANT OPTION FOR [PermissionName] TO [DataUser] CASCADE;\\n-- GRANT [PermissionName] TO [DataUser];", "parameters": [], "description": "Splits combined roles so each principal has either data access OR administration, not both. DBA determines the appropriate split per user based on their actual job function."}	{"sql": "-- ALTER ROLE [RoleName] ADD MEMBER [UserName];", "description": "Restore role memberships if separation causes operational issues."}	medium	t	t	00:30:00	2026-02-24 13:10:27.80099
4878	sqlserver	verify	Confirm no principals have combined data and admin roles	{"sql": "SELECT dp.name AS principal_name,\\n  STRING_AGG(r.name, ', ') AS role_memberships,\\n  SUM(CASE WHEN r.name IN ('db_datareader', 'db_datawriter') THEN 1 ELSE 0 END) AS data_roles,\\n  SUM(CASE WHEN r.name IN ('db_owner', 'db_securityadmin', 'db_ddladmin') THEN 1 ELSE 0 END) AS admin_roles\\nFROM sys.database_role_members rm\\nJOIN sys.database_principals dp ON rm.member_principal_id = dp.principal_id\\nJOIN sys.database_principals r ON rm.role_principal_id = r.principal_id\\nWHERE dp.type IN ('S', 'U', 'G') AND dp.name NOT IN ('dbo', 'guest')\\nGROUP BY dp.name\\nHAVING SUM(CASE WHEN r.name IN ('db_datareader', 'db_datawriter') THEN 1 ELSE 0 END) > 0\\n  AND SUM(CASE WHEN r.name IN ('db_owner', 'db_securityadmin', 'db_ddladmin') THEN 1 ELSE 0 END) > 0;", "parameters": [], "description": "Confirms no principals remain with combined data access and admin roles."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.800991
