4916	sqlserver	execute	Create audit to monitor configuration changes and sp_configure usage	{"sql": "IF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'ConfigChangeAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [ConfigChangeAudit]\\n  TO FILE (FILEPATH = @audit_file_path, MAXSIZE = 100 MB, MAX_ROLLOVER_FILES = 10)\\n  WITH (ON_FAILURE = CONTINUE);\\nEND;\\n\\nALTER SERVER AUDIT [ConfigChangeAudit] WITH (STATE = ON);\\n\\nCREATE SERVER AUDIT SPECIFICATION [ConfigChangeSpec]\\nFOR SERVER AUDIT [ConfigChangeAudit]\\nADD (SERVER_OPERATION_GROUP),\\nADD (AUDIT_CHANGE_GROUP)\\nWITH (STATE = ON);", "parameters": ["audit_file_path"], "description": "Creates an audit that captures all sp_configure changes (SERVER_OPERATION_GROUP) and audit modifications, detecting any attempt to re-enable xp_cmdshell."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [ConfigChangeSpec] WITH (STATE = OFF);\\nDROP SERVER AUDIT SPECIFICATION [ConfigChangeSpec];\\nALTER SERVER AUDIT [ConfigChangeAudit] WITH (STATE = OFF);\\nDROP SERVER AUDIT [ConfigChangeAudit];", "description": "Removes the audit infrastructure."}	low	t	t	00:05:00	2026-02-24 13:10:27.801015
4917	sqlserver	verify	Confirm xp_cmdshell disabled and audit active	{"sql": "SELECT CAST(value_in_use AS INT) AS xp_cmdshell_enabled\\nFROM sys.configurations WHERE name = 'xp_cmdshell';\\n\\nSELECT sa.name AS audit_name, sa.is_state_enabled,\\n  sas.name AS spec_name, sas.is_state_enabled AS spec_enabled\\nFROM sys.server_audits sa\\nJOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nWHERE sa.name = 'ConfigChangeAudit';", "parameters": [], "description": "Confirms xp_cmdshell is disabled and configuration change audit is active."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801016
4918	sqlserver	verify	Categorize current xp_cmdshell usage patterns	{"sql": "SELECT o.name AS proc_name,\\n  CASE\\n    WHEN OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%dir %' OR\\n      OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%copy %' OR\\n      OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%del %' THEN 'FILE_OPS -> Use SSIS or PowerShell Agent step'\\n    WHEN OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%bcp %' THEN 'BCP -> Use BULK INSERT or SSIS'\\n    WHEN OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%ping %' THEN 'NETWORK -> Use CLR or app layer'\\n    WHEN OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%sqlcmd%' THEN 'SQL_EXEC -> Use linked server or Agent'\\n    ELSE 'OTHER -> Review and replace'\\n  END AS replacement_guidance\\nFROM sys.objects o\\nWHERE o.type = 'P' AND o.is_ms_shipped = 0\\n  AND OBJECT_DEFINITION(o.object_id) LIKE '%xp_cmdshell%';", "parameters": [], "description": "Categorizes each xp_cmdshell usage and provides the recommended replacement."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801016
4993	sqlserver	verify	Check assembly dependencies and referenced libraries	{"sql": "SELECT a.name AS assembly_name, a.permission_set_desc,\\n  (SELECT COUNT(*) FROM sys.assembly_references ar WHERE ar.assembly_id = a.assembly_id) AS dependencies,\\n  (SELECT COUNT(*) FROM sys.assembly_files af WHERE af.assembly_id = a.assembly_id) AS files\\nFROM sys.assemblies a\\nWHERE a.is_user_defined = 1\\nORDER BY a.permission_set_desc DESC;", "parameters": [], "description": "Shows assemblies with their dependency counts, indicating which ones may load external libraries."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801065
