4931	sqlserver	verify	Confirm no active connections to sample databases	{"sql": "SELECT d.name AS database_name, d.create_date,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.database_id = d.database_id AND s.is_user_process = 1) AS active_sessions\\nFROM sys.databases d\\nWHERE d.state = 0 AND d.database_id > 4\\n  AND d.name IN (\\n    'AdventureWorks', 'AdventureWorks2014', 'AdventureWorks2016', 'AdventureWorks2017',\\n    'AdventureWorks2019', 'AdventureWorks2022', 'AdventureWorksDW', 'AdventureWorksLT',\\n    'WideWorldImporters', 'WideWorldImportersDW', 'Northwind', 'pubs');", "parameters": [], "description": "Lists sample databases and confirms no active connections before dropping."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801025
4932	sqlserver	execute	Drop all identified sample databases	{"sql": "DECLARE @sql NVARCHAR(MAX) = '';\\nSELECT @sql = @sql + 'ALTER DATABASE ' + QUOTENAME(name) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE ' + QUOTENAME(name) + '; '\\nFROM sys.databases\\nWHERE state = 0 AND database_id > 4\\n  AND name IN (\\n    'AdventureWorks', 'AdventureWorks2014', 'AdventureWorks2016', 'AdventureWorks2017',\\n    'AdventureWorks2019', 'AdventureWorks2022', 'AdventureWorksDW', 'AdventureWorksLT',\\n    'WideWorldImporters', 'WideWorldImportersDW', 'Northwind', 'pubs');\\n\\nPRINT @sql;\\n-- EXEC sp_executesql @sql;", "parameters": [], "description": "Generates DROP DATABASE statements for all sample databases. DBA must review the PRINT output and uncomment the EXEC to execute."}	null	low	t	f	00:05:00	2026-02-24 13:10:27.801026
