4940	sqlserver	verify	Identify migrated sample databases	{"sql": "SELECT d.name AS database_name, d.create_date,\\n  d.compatibility_level, sp.name AS db_owner,\\n  DATEDIFF(DAY, d.create_date, GETDATE()) AS age_days\\nFROM sys.databases d\\nLEFT JOIN sys.server_principals sp ON d.owner_sid = sp.sid\\nWHERE d.state = 0 AND d.database_id > 4\\n  AND (d.name IN (\\n    'AdventureWorks', 'AdventureWorks2014', 'AdventureWorks2016', 'AdventureWorks2017',\\n    'AdventureWorks2019', 'AdventureWorks2022', 'AdventureWorksDW', 'AdventureWorksLT',\\n    'WideWorldImporters', 'WideWorldImportersDW', 'Northwind', 'pubs')\\n    OR d.name LIKE '%test%' OR d.name LIKE '%dev%' OR d.name LIKE '%sample%'\\n    OR d.name LIKE '%demo%' OR d.name LIKE '%sandbox%');", "parameters": [], "description": "Lists sample and test databases that may have been carried over during migration."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801032
4941	sqlserver	execute	Drop confirmed sample and test databases	{"sql": "-- For each confirmed sample/test database:\\n-- ALTER DATABASE [DatabaseName] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;\\n-- DROP DATABASE [DatabaseName];", "parameters": [], "description": "Drops each confirmed sample/test database after DBA verification."}	null	low	t	f	00:05:00	2026-02-24 13:10:27.801033
4942	sqlserver	verify	Confirm sample databases have no recent activity	{"sql": "SELECT d.name AS database_name, d.create_date,\\n  DATEDIFF(DAY, d.create_date, GETDATE()) AS age_days,\\n  sp.name AS db_owner,\\n  CASE WHEN sp.is_disabled = 1 OR sp.sid IS NULL THEN 'ORPHANED/DISABLED' ELSE 'ACTIVE' END AS owner_status,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.database_id = d.database_id AND s.is_user_process = 1) AS active_sessions,\\n  (SELECT MAX(COALESCE(last_user_seek, last_user_scan, last_user_lookup, '1900-01-01'))\\n   FROM sys.dm_db_index_usage_stats ius WHERE ius.database_id = d.database_id) AS last_user_activity\\nFROM sys.databases d\\nLEFT JOIN sys.server_principals sp ON d.owner_sid = sp.sid\\nWHERE d.state = 0 AND d.database_id > 4\\n  AND (d.name IN (\\n    'AdventureWorks', 'AdventureWorks2014', 'AdventureWorks2016', 'AdventureWorks2017',\\n    'AdventureWorks2019', 'AdventureWorks2022', 'AdventureWorksDW', 'AdventureWorksLT',\\n    'WideWorldImporters', 'WideWorldImportersDW', 'Northwind', 'pubs')\\n    OR d.name LIKE '%test%' OR d.name LIKE '%dev%' OR d.name LIKE '%sample%'\\n    OR d.name LIKE '%demo%' OR d.name LIKE '%sandbox%');", "parameters": [], "description": "Shows activity status of sample/test databases. Databases with 0 active sessions and no recent user activity are safe to drop."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.801034
