5468	sqlserver	verify	Identify active SQL Trace sessions capturing statement text	{"sql": "SELECT id AS trace_id, status,\\n  CASE status WHEN 0 THEN 'Stopped' WHEN 1 THEN 'Running' END AS status_desc,\\n  path AS trace_file_path,\\n  max_size AS max_file_size_mb,\\n  start_time, stop_time, is_default,\\n  CASE is_rowset WHEN 1 THEN 'Rowset trace' ELSE 'File trace' END AS trace_type\\nFROM sys.traces\\nWHERE status = 1\\nORDER BY is_default, id;\\n\\nSELECT t.id AS trace_id, t.path,\\n  te.name AS event_name, tc.name AS column_name\\nFROM sys.traces t\\nCROSS APPLY sys.fn_trace_geteventinfo(t.id) ei\\nJOIN sys.trace_events te ON ei.eventid = te.trace_event_id\\nJOIN sys.trace_columns tc ON ei.columnid = tc.trace_column_id\\nWHERE t.status = 1\\n  AND te.name IN ('SQL:BatchCompleted', 'SQL:StmtCompleted',\\n    'RPC:Completed', 'SP:StmtCompleted')\\n  AND tc.name = 'TextData'\\nORDER BY t.id, te.name;", "parameters": [], "description": "Lists running SQL Trace sessions and those capturing TextData (full SQL text)."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.937164
5469	sqlserver	execute	Stop non-default stale trace sessions	{"sql": "-- Stop all non-default running traces\\n-- NOTE: Execute one at a time for each trace_id found in step 1\\nDECLARE @trace_id INT;\\nDECLARE trace_cursor CURSOR FOR\\n  SELECT id FROM sys.traces WHERE status = 1 AND is_default = 0;\\nOPEN trace_cursor;\\nFETCH NEXT FROM trace_cursor INTO @trace_id;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  EXEC sp_trace_setstatus @trace_id, 0; -- Stop\\n  EXEC sp_trace_setstatus @trace_id, 2; -- Close and delete definition\\n  FETCH NEXT FROM trace_cursor INTO @trace_id;\\nEND;\\nCLOSE trace_cursor;\\nDEALLOCE trace_cursor;", "parameters": [], "description": "Stops and removes all non-default trace sessions."}	{"sql": null, "description": "Re-create the trace session if it was needed for active monitoring."}	low	t	t	00:01:00	2026-02-24 13:10:27.937165
