232	sqlserver	configure	Schedule regular log backups	{"sql": "-- Create a log backup job (run every 15 minutes for typical PITR RPO)\\nEXEC msdb.dbo.sp_add_job\\n  @job_name = N'Log Backup - <database_name>',\\n  @enabled = 1;\\n\\nEXEC msdb.dbo.sp_add_jobstep\\n  @job_name = N'Log Backup - <database_name>',\\n  @step_name = N'Backup transaction log',\\n  @command = N'BACKUP LOG [<database_name>]\\n  TO DISK = N''\\\\\\\\<backup_path>\\\\<database_name>_LOG_''\\n    + CONVERT(varchar(8), GETDATE(), 112)\\n    + ''_'' + REPLACE(CONVERT(varchar(8), GETDATE(), 108), '':'', '''') + ''.bak''\\n  WITH COMPRESSION, CHECKSUM;';\\n\\nEXEC msdb.dbo.sp_add_schedule\\n  @schedule_name = N'Every 15 minutes',\\n  @freq_type = 4, @freq_interval = 1,\\n  @freq_subday_type = 4, @freq_subday_interval = 15;\\n\\nEXEC msdb.dbo.sp_attach_schedule\\n  @job_name = N'Log Backup - <database_name>',\\n  @schedule_name = N'Every 15 minutes';\\n\\nEXEC msdb.dbo.sp_add_jobserver @job_name = N'Log Backup - <database_name>';", "parameters": ["database_name", "backup_path"], "description": "Creates and schedules a SQL Agent job to back up the transaction log every 15 minutes, providing a 15-minute RPO."}	{"sql": "EXEC msdb.dbo.sp_delete_job @job_name = N'Log Backup - <database_name>';", "description": "Remove the log backup job if it was created incorrectly."}	low	t	t	00:05:00	2026-02-24 13:10:27.115404
