255	sqlserver	configure	Update backup cleanup job to extend log retention period	{"sql": "-- Find the cleanup job that deletes log backups\\nSELECT j.name, js.step_id, js.step_name, js.command\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE js.command LIKE '%backup_finish_date%'\\n  OR js.command LIKE '%DATEADD%'\\n  OR j.name LIKE '%cleanup%' OR j.name LIKE '%maintenance%'\\nORDER BY j.name;\\n\\n-- Update the cleanup threshold (example: extend from 3 days to 7 days)\\n-- Replace the existing DELETE/EXECUTE xp_delete_file command with new retention:\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<cleanup_job_name>',\\n  @step_id = <step_id>,\\n  @command = N'EXECUTE master.dbo.xp_delete_file\\n  0, N''\\\\\\\\<backup_path>\\\\Logs\\\\'', N''bak'',\\n  @backup_finish_date = DATEADD(day, -@new_retention_days, GETDATE());';", "parameters": ["cleanup_job_name", "step_id", "backup_path", "new_retention_days"], "description": "Updates the log backup cleanup job to use the new extended retention period. The exact command depends on whether Maintenance Plans or custom T-SQL cleanup is used."}	{"sql": "-- Revert cleanup job to previous retention:\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<cleanup_job_name>',\\n  @step_id = <step_id>,\\n  @command = N'<original_cleanup_command>';", "description": "Revert the cleanup job to the previous retention period if storage capacity is insufficient."}	low	t	t	00:05:00	2026-02-24 13:10:27.11549
