256	sqlserver	configure	Ensure full backup retention aligns with extended log retention	{"sql": "-- Full backup retention must exceed log retention\\n-- If log retention = 7 days, full backup retention must be at least 8 days\\n\\n-- Check current full backup cleanup settings:\\nSELECT j.name, js.command\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE (js.command LIKE '%FULL%' OR j.name LIKE '%full%')\\n  AND (js.command LIKE '%delete%' OR js.command LIKE '%cleanup%')\\nORDER BY j.name;\\n\\n-- Update full backup cleanup job similarly:\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<full_cleanup_job_name>',\\n  @step_id = <full_step_id>,\\n  @command = N'EXECUTE master.dbo.xp_delete_file\\n  0, N''\\\\\\\\<backup_path>\\\\Full\\\\'', N''bak'',\\n  @backup_finish_date = DATEADD(day, -@full_retention_days, GETDATE());';", "parameters": ["full_cleanup_job_name", "full_step_id", "backup_path", "full_retention_days"], "description": "Ensures full backup retention is at least one day longer than log backup retention to guarantee a valid full backup exists for the entire log retention window."}	{"sql": "EXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<full_cleanup_job_name>',\\n  @step_id = <full_step_id>,\\n  @command = N'<original_full_cleanup_command>';", "description": "Revert full backup cleanup job to previous settings."}	low	t	t	00:05:00	2026-02-24 13:10:27.115491
