399	sqlserver	execute	Create a new self-signed certificate for the AG endpoint	{"sql": "USE master;\\n-- Create a new certificate with a multi-year expiry\\nCREATE CERTIFICATE [AGEndpointCert_@server]\\n  WITH SUBJECT = 'AG Endpoint Certificate for @server',\\n  EXPIRY_DATE = '@expiry_date';\\n\\n-- Back up the certificate rootcause key for distribution to other nodes\\nBACKUP CERTIFICATE [AGEndpointCert_@server]\\n  TO FILE = N'@cert_backup_path\\\\AGEndpointCert_@server.cer';", "parameters": ["@server", "@expiry_date", "@cert_backup_path"], "description": "Creates a new self-signed certificate for the AG endpoint with a future expiry date. The certificate backup must be distributed to all other AG nodes."}	{"sql": "DROP CERTIFICATE [AGEndpointCert_@server];", "description": "Drop the new certificate if it was created in error."}	low	t	t	00:01:00	2026-02-24 13:10:27.136745
400	sqlserver	execute	Import the new certificate on all other AG nodes	{"sql": "-- Run on each OTHER AG node\\n-- First create a login for the AG service account from the other node (if not exists)\\nUSE master;\\nCREATE LOGIN [@service_account_or_endpoint_user]\\n  FROM WINDOWS;\\n\\n-- Import the certificate backed up in step 1\\nCREATE CERTIFICATE [AGEndpointCert_@remote_server]\\n  AUTHORIZATION [@service_account_or_endpoint_user]\\n  FROM FILE = N'@cert_backup_path\\\\AGEndpointCert_@remote_server.cer';\\n\\n-- Grant CONNECT permission on the endpoint\\nGRANT CONNECT ON ENDPOINT::[Hadr_endpoint] TO [@service_account_or_endpoint_user];", "parameters": ["@service_account_or_endpoint_user", "@remote_server", "@cert_backup_path"], "description": "Imports the certificate from the node being fixed onto all other AG nodes, establishing trust."}	{"sql": "DROP CERTIFICATE [AGEndpointCert_@remote_server];", "description": "Remove the imported certificate if the wrong file was imported."}	medium	t	t	00:05:00	2026-02-24 13:10:27.136746
414	sqlserver	execute	Create database master key and TDE certificate	{"sql": "USE master;\\n\\n-- Create the database master key if it does not exist\\nIF NOT EXISTS (SELECT * FROM sys.symmetric_keys WHERE name = '##MS_DatabaseMasterKey##')\\nBEGIN\\n  CREATE MASTER KEY ENCRYPTION BY PASSWORD = '@strong_master_key_password';\\nEND;\\n\\n-- Create the TDE certificate\\nCREATE CERTIFICATE [TDECert]\\n  WITH SUBJECT = 'TDE Certificate',\\n  EXPIRY_DATE = '@expiry_date';\\n\\n-- Immediately back up the certificate and its private key\\nBACKUP CERTIFICATE [TDECert]\\n  TO FILE = N'@cert_backup_path\\\\TDECert.cer'\\n  WITH PRIVATE KEY (\\n    FILE = N'@cert_backup_path\\\\TDECert.pvk',\\n    ENCRYPTION BY PASSWORD = '@pvk_password'\\n  );", "parameters": ["@strong_master_key_password", "@expiry_date", "@cert_backup_path", "@pvk_password"], "description": "Creates the master key and TDE certificate in master. The certificate backup is critical — losing it means losing access to encrypted databases."}	{"sql": "-- Only drop if TDE has NOT been applied to any database yet\\nDROP CERTIFICATE [TDECert];\\n-- DROP MASTER KEY;  -- Only if no other encrypted objects depend on it", "description": "Remove the TDE certificate if created in error — only safe before TDE is enabled on any database."}	medium	t	t	00:05:00	2026-02-24 13:10:27.136755
469	sqlserver	execute	Generate current high-privilege role membership report for review	{"sql": "SELECT r.name AS role_name, p.name AS member_name, p.type_desc,\\n  p.create_date, p.modify_date, p.is_disabled,\\n  p.default_database_name\\nFROM sys.server_role_members rm\\nJOIN sys.server_principals r ON rm.role_principal_id = r.principal_id\\nJOIN sys.server_principals p ON rm.member_principal_id = p.principal_id\\nWHERE r.name IN ('sysadmin', 'securityadmin', 'serveradmin', 'dbcreator')\\n  AND p.name NOT IN ('sa', 'NT AUTHORITY\\\\SYSTEM',\\n    'NT SERVICE\\\\MSSQLSERVER', 'NT SERVICE\\\\SQLSERVERAGENT',\\n    'NT SERVICE\\\\SQLWRITER', 'NT SERVICE\\\\Winmgmt')\\nORDER BY r.name, p.name;", "parameters": [], "description": "Produces the current membership list for all high-privilege server roles for security review."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.13679
425	sqlserver	execute	Create SQL Server Audit targeting security and admin events	{"sql": "-- Create server audit writing to file\\nCREATE SERVER AUDIT [SecurityAudit]\\nTO FILE (\\n  FILEPATH = N'C:\\\\SQLAudit\\\\',\\n  MAXSIZE = 100 MB,\\n  MAX_ROLLOVER_FILES = 10,\\n  RESERVE_DISK_SPACE = OFF\\n)\\nWITH (\\n  QUEUE_DELAY = 1000,\\n  ON_FAILURE = CONTINUE\\n);\\nALTER SERVER AUDIT [SecurityAudit] WITH (STATE = ON);\\n\\n-- Create audit specification for key admin events\\nCREATE SERVER AUDIT SPECIFICATION [SecurityAuditSpec]\\nFOR SERVER AUDIT [SecurityAudit]\\nADD (SERVER_PRINCIPAL_CHANGE_GROUP),\\nADD (DATABASE_PRINCIPAL_CHANGE_GROUP),\\nADD (SERVER_ROLE_MEMBER_CHANGE_GROUP),\\nADD (SERVER_OBJECT_PERMISSION_CHANGE_GROUP),\\nADD (DATABASE_PERMISSION_CHANGE_GROUP),\\nADD (AUDIT_CHANGE_GROUP),\\nADD (FAILED_LOGIN_GROUP),\\nADD (LOGIN_CHANGE_PASSWORD_GROUP)\\nWITH (STATE = ON);", "parameters": [], "description": "Creates a persistent SQL Server Audit capturing privilege changes, login events, role membership changes, and permission modifications."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [SecurityAuditSpec] WITH (STATE = OFF);\\nDROP SERVER AUDIT SPECIFICATION [SecurityAuditSpec];\\nALTER SERVER AUDIT [SecurityAudit] WITH (STATE = OFF);\\nDROP SERVER AUDIT [SecurityAudit];", "description": "Removes the audit and audit specification if rollback is required."}	medium	t	t	00:05:00	2026-02-24 13:10:27.136761
429	sqlserver	verify	Confirm no unauthorized principals retain security-sensitive permissions	{"sql": "SELECT pr.name AS principal_name, pr.type_desc,\\n  pe.permission_name, pe.state_desc\\nFROM sys.server_permissions pe\\nJOIN sys.server_principals pr ON pe.grantee_principal_id = pr.principal_id\\nWHERE pe.permission_name IN ('ALTER ANY LOGIN', 'ALTER ANY SERVER ROLE',\\n  'CONTROL SERVER', 'ALTER ANY CREDENTIAL', 'ALTER ANY LINKED SERVER')\\n  AND pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND pr.name NOT IN ('sa', 'BUILTIN\\\\Administrators')\\n  AND pr.type_desc != 'SERVER_ROLE';", "parameters": [], "description": "Re-runs the detection query. Only intentionally authorized principals should remain."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136764
448	sqlserver	execute	Verify or create a backup encryption certificate	{"sql": "USE master;\\n-- Check for existing certificates suitable for backup encryption\\nSELECT name, expiry_date, pvt_key_encryption_type_desc\\nFROM sys.certificates\\nWHERE pvt_key_encryption_type_desc = 'ENCRYPTED_BY_MASTER_KEY'\\n  AND (expiry_date IS NULL OR expiry_date > GETDATE());\\n\\n-- If no suitable certificate exists, create one:\\n-- BACKUP MASTER KEY TO FILE = 'C:\\\\Keys\\\\MasterKey.bak'\\n--   ENCRYPTION BY PASSWORD = 'StrongPassword123!';\\n-- CREATE CERTIFICATE BackupEncryptCert\\n--   WITH SUBJECT = 'Backup Encryption Certificate',\\n--   EXPIRY_DATE = '2030-01-01';\\n-- BACKUP CERTIFICATE BackupEncryptCert TO FILE = 'C:\\\\Keys\\\\BackupEncryptCert.cer'\\n--   WITH PRIVATE KEY (FILE = 'C:\\\\Keys\\\\BackupEncryptCert.pvk',\\n--   ENCRYPTION BY PASSWORD = 'CertPrivKeyPassword!');", "parameters": [], "description": "Identifies existing backup encryption certificates or creates a new one. Certificate backup to a secure location is critical for disaster recovery."}	null	low	f	t	00:05:00	2026-02-24 13:10:27.136778
471	sqlserver	verify	Confirm only authorized principals hold high-privilege role memberships	{"sql": "SELECT r.name AS role_name, p.name AS member_name, p.type_desc, p.is_disabled\\nFROM sys.server_role_members rm\\nJOIN sys.server_principals r ON rm.role_principal_id = r.principal_id\\nJOIN sys.server_principals p ON rm.member_principal_id = p.principal_id\\nWHERE r.name IN ('sysadmin', 'securityadmin', 'serveradmin', 'dbcreator')\\n  AND p.name NOT IN ('sa', 'NT AUTHORITY\\\\SYSTEM',\\n    'NT SERVICE\\\\MSSQLSERVER', 'NT SERVICE\\\\SQLSERVERAGENT',\\n    'NT SERVICE\\\\SQLWRITER', 'NT SERVICE\\\\Winmgmt')\\nORDER BY r.name, p.name;", "parameters": [], "description": "Re-runs the role membership query. Only documented, authorized principals should appear."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.136791
