646	sqlserver	execute	Take immediate full backup and configure frequent log backup job	{"sql": "-- Step 1: Take full backup to anchor log chain\\nBACKUP DATABASE [:database_name] TO DISK = ':backup_path\\\\:database_name_logfix_' + CONVERT(varchar(8), GETDATE(), 112) + '.bak' WITH COMPRESSION, CHECKSUM, STATS = 10;\\n-- Step 2: Take first log backup immediately after\\nBACKUP LOG [:database_name] TO DISK = ':backup_path\\\\:database_name_log_' + CONVERT(varchar(8), GETDATE(), 112) + '_001.bak' WITH COMPRESSION, CHECKSUM;", "parameters": ["database_name", "backup_path"], "description": "Takes a full backup to establish the LSN baseline, immediately followed by a log backup to begin the chain. This also truncates the active portion of the log."}	null	medium	t	f	01:00:00	2026-02-24 13:10:27.163007
