1927	sqlserver	configure	Repair backup job configuration and add monitoring alert	{"sql": "-- Fix the backup job step command (example: update backup path)\\nEXEC msdb.dbo.sp_update_jobstep\\n  @job_name = N'<backup_job_name>',\\n  @step_id = 1,\\n  @command = N'BACKUP DATABASE [<database_name>]\\nTO DISK = N''<correct_backup_path>\\\\<database_name>_FULL_'' + FORMAT(GETDATE(),''yyyyMMdd_HHmm'') + ''.bak''\\nWITH COMPRESSION, CHECKSUM, STATS = 10;\\nEXEC master.dbo.xp_delete_file 0, N''<correct_backup_path>'', N''bak'', DATEADD(day,-7,GETDATE()), 1;';\\n\\n-- Add SQL Server Agent alert for failed backup jobs\\nEXEC msdb.dbo.sp_add_alert\\n  @name = N'Backup Job Failure Alert',\\n  @message_id = 0,\\n  @severity = 16,\\n  @enabled = 1,\\n  @delay_between_responses = 3600,\\n  @notification_message = N'A SQL Server backup job has failed. Review msdb.dbo.sysjobhistory immediately.';\\n\\nEXEC msdb.dbo.sp_add_notification\\n  @alert_name = N'Backup Job Failure Alert',\\n  @operator_name = N'<dba_operator>',\\n  @notification_method = 1; -- 1=email", "parameters": {"dba_operator": "SQL Agent operator configured with DBA email addresses", "backup_job_name": "Name of the failing backup job", "correct_backup_path": "Verified accessible path on backup storage volume"}, "description": "Update the backup job with the corrected path and parameters, add automatic cleanup of old backups within the job, and configure an alert to notify the DBA team on future failures."}	{"sql": "EXEC msdb.dbo.sp_delete_alert @name = N'Backup Job Failure Alert';", "description": "Remove the alert if notification infrastructure is not yet configured."}	low	f	t	00:15:00	2026-02-24 13:10:27.323361
