3179	sqlserver	execute	Add tempdb data files equal in size to existing files	{"sql": "-- Adds files to bring count up to min(8, logical_cpu_count)\\n-- All files sized and configured to match file_id=1\\nDECLARE @target_files INT = (SELECT MIN(v) FROM (VALUES (8), ((SELECT cpu_count FROM sys.dm_os_sys_info))) AS t(v));\\nDECLARE @current_files INT = (SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type = 0);\\nDECLARE @size_mb INT = (SELECT TOP 1 size * 8 / 1024 FROM sys.master_files WHERE database_id = 2 AND type = 0 ORDER BY file_id);\\nDECLARE @data_path NVARCHAR(512) = (SELECT LEFT(physical_name, LEN(physical_name) - CHARINDEX('\\\\', REVERSE(physical_name))) FROM sys.master_files WHERE database_id = 2 AND file_id = 1);\\nDECLARE @i INT = @current_files + 1;\\nDECLARE @sql NVARCHAR(MAX);\\n\\nWHILE @i <= @target_files\\nBEGIN\\n  SET @sql = 'ALTER DATABASE tempdb ADD FILE ('\\n    + 'NAME = N''tempdev' + CAST(@i AS NVARCHAR) + ''', '\\n    + 'FILENAME = N''' + @data_path + '\\\\tempdev' + CAST(@i AS NVARCHAR) + '.ndf'', '\\n    + 'SIZE = ' + CAST(@size_mb AS NVARCHAR) + 'MB, '\\n    + 'MAXSIZE = UNLIMITED, '\\n    + 'FILEGROWTH = 256MB);';\\n  EXEC sp_executesql @sql;\\n  PRINT 'Added tempdev' + CAST(@i AS NVARCHAR);\\n  SET @i = @i + 1;\\nEND;\\n\\nSELECT file_id, name, physical_name, size * 8 / 1024 AS size_mb, growth\\nFROM sys.master_files WHERE database_id = 2 AND type = 0 ORDER BY file_id;", "parameters": {"size": "Match existing primary file", "autogrowth": "256MB fixed", "target_count": "min(8, logical_cpu_count)"}, "description": "Adds the required number of equal-sized tempdb data files. Each new file receives its own PFS, GAM, and SGAM pages, independently distributing allocation requests across multiple bitmap pages and eliminating contention on the original file's pages."}	{"sql": "-- Remove added files if needed\\n-- ALTER DATABASE tempdb REMOVE FILE tempdev2;\\n-- Repeat for each added file number\\n-- A SQL Server restart may be required if files contain active allocations", "description": "Remove added tempdb files. Takes effect immediately or on next restart."}	medium	t	t	\N	2026-02-24 13:10:27.519927
4218	sqlserver	configure	Configure minimally-logged bulk operations and frequent log backups	{"sql": "-- Option 1: Switch to BULK_LOGGED during ETL window\\nALTER DATABASE [database_name] SET RECOVERY BULK_LOGGED;\\n\\n-- Use minimally-logged patterns:\\n-- BULK INSERT with TABLOCK\\nBULK INSERT staging_table\\nFROM 'datafile.csv'\\nWITH (\\n  BATCHSIZE = 50000,\\n  TABLOCK,            -- Required for minimal logging\\n  CHECK_CONSTRAINTS,\\n  FIRE_TRIGGERS\\n);\\n\\n-- INSERT INTO with TABLOCK hint (heap or empty clustered index)\\nINSERT INTO target_table WITH (TABLOCK)\\nSELECT * FROM staging_table;\\n\\n-- SELECT INTO (always minimally logged)\\nSELECT * INTO new_table FROM source_table WHERE conditions;\\n\\n-- Switch back to FULL recovery after ETL completes\\nALTER DATABASE [database_name] SET RECOVERY FULL;\\n\\n-- Take full backup after switching back to establish new log chain\\nBACKUP DATABASE [database_name] TO DISK = N'path\\\\full.bak' WITH COMPRESSION;\\n\\n-- Schedule more frequent log backups during ETL windows\\n-- (via SQL Agent job: every 5 minutes instead of every 15)\\nBACKUP LOG [database_name] TO DISK = N'path\\\\log.trn'\\nWITH COMPRESSION, STATS = 10;", "parameters": ["database_name", "backup_path", "log_backup_interval_minutes"], "description": "Configures bulk load operations for minimal logging and increases log backup frequency during high-volume ETL windows to prevent log accumulation."}	{"sql": "ALTER DATABASE [database_name] SET RECOVERY FULL;", "description": "Switch back to FULL recovery mode."}	medium	t	t	\N	2026-02-24 13:10:27.668772
3595	sqlserver	execute	Add TempDB data files to meet recommended count	{"sql": "-- Add files to reach MIN(logical_processors, 8)\\n-- Adjust path, size (match existing files), and growth to match your environment\\n-- Example: adding 3 more files to reach 4 total\\nUSE [master];\\n\\nALTER DATABASE [tempdb]\\n    ADD FILE (NAME = N'tempdev2',\\n              FILENAME = N'D:\\\\TempDB\\\\tempdev2.ndf',\\n              SIZE = 1024MB, FILEGROWTH = 256MB);\\n\\nALTER DATABASE [tempdb]\\n    ADD FILE (NAME = N'tempdev3',\\n              FILENAME = N'D:\\\\TempDB\\\\tempdev3.ndf',\\n              SIZE = 1024MB, FILEGROWTH = 256MB);\\n\\nALTER DATABASE [tempdb]\\n    ADD FILE (NAME = N'tempdev4',\\n              FILENAME = N'D:\\\\TempDB\\\\tempdev4.ndf',\\n              SIZE = 1024MB, FILEGROWTH = 256MB);\\n\\n-- Confirm all files are the same size\\nSELECT name, size * 8 / 1024 AS size_mb, growth\\nFROM sys.master_files\\nWHERE database_id = 2 AND type = 0\\nORDER BY file_id;", "parameters": {"file_path": "dedicated fast storage path", "file_size_mb": "match existing tempdb file size", "target_file_count": "MIN(logical_processors, 8)"}, "description": "Add TempDB data files so the total count equals MIN(logical_processors, 8), each file the same size as the existing primary TempDB data file."}	{"sql": "-- Remove the added files (only possible if they are empty; TempDB files cannot be removed while in use)\\nALTER DATABASE [tempdb] REMOVE FILE [tempdev4];\\nALTER DATABASE [tempdb] REMOVE FILE [tempdev3];\\nALTER DATABASE [tempdb] REMOVE FILE [tempdev2];", "description": "Remove added TempDB files if required; only possible when files are not active (typically after a restart with reduced workload)."}	medium	t	t	\N	2026-02-24 13:10:27.565034
3966	sqlserver	configure	Optimize max server memory and enable buffer pool extension	{"sql": "-- Set max server memory appropriately\\nDECLARE @total_mb INT = (SELECT physical_memory_kb / 1024 FROM sys.dm_os_sys_info);\\nDECLARE @max_mb INT = @total_mb * 0.85;\\nEXEC sp_configure 'max server memory (MB)', @max_mb;\\nRECONFIGURE;\\n\\n-- Enable buffer pool extension on SSD for additional caching (SQL 2014+)\\n-- ALTER SERVER CONFIGURATION SET BUFFER POOL EXTENSION ON (FILENAME = 'E:\\\\BPE\\\\BPE.bpe', SIZE = 64 GB);", "parameters": ["bpe_path", "bpe_size_gb"], "description": "Maximizes buffer pool size by setting max server memory to 85% of physical RAM. Optionally enables buffer pool extension on SSD for additional warm cache capacity."}	{"sql": "ALTER SERVER CONFIGURATION SET BUFFER POOL EXTENSION OFF;\\nEXEC sp_configure 'max server memory (MB)', @previous_value;\\nRECONFIGURE;", "description": "Disable buffer pool extension and revert memory settings."}	medium	t	t	00:01:00	2026-02-24 13:10:27.599076
4355	sqlserver	verify	Verify service account has minimum privileges	{"sql": "SELECT servicename, service_account, startup_type_desc, status_desc\\nFROM sys.dm_server_services\\nWHERE servicename LIKE '%SQL%';\\n\\n-- Verify service account is not sysadmin (unless NT SERVICE\\\\*)\\nSELECT sp.name, sp.type_desc,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.server_principals sp\\nWHERE sp.name IN (\\n  SELECT service_account FROM sys.dm_server_services\\n  WHERE servicename LIKE '%SQL%'\\n)\\n  OR sp.name = 'NT AUTHORITY\\\\SYSTEM';", "parameters": [], "description": "Confirms the SQL Server service account is a low-privilege account and not running as SYSTEM or a domain admin."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.719709
4216	sqlserver	execute	Resolve the oldest active transaction and take log backup to reclaim space	{"sql": "-- Step 1: Identify the oldest active transaction\\nSELECT TOP 1 dat.transaction_id, dat.name, dat.transaction_begin_time,\\n  DATEDIFF(MINUTE, dat.transaction_begin_time, GETDATE()) AS age_minutes,\\n  dst.session_id, s.program_name, s.status,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_tran_active_transactions dat\\nJOIN sys.dm_tran_session_transactions dst ON dat.transaction_id = dst.transaction_id\\nJOIN sys.dm_exec_sessions s ON dst.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nORDER BY dat.transaction_begin_time ASC;\\n\\n-- Step 2: If the session is sleeping/orphaned, kill it\\n-- KILL @session_id;\\n\\n-- Step 3: Take a transaction log backup to allow truncation\\nBACKUP LOG [database_name] TO DISK = N'path\\\\logbackup.trn'\\nWITH COMPRESSION, STATS = 10;\\n\\n-- Step 4: Verify log space was reclaimed\\nSELECT name, log_reuse_wait_desc FROM sys.databases WHERE database_id = DB_ID();\\nSELECT total_log_size_mb, used_log_space_mb, used_log_space_percentage\\nFROM sys.dm_db_log_space_usage;", "parameters": ["database_name", "backup_path"], "description": "Identifies and resolves the oldest active transaction blocking log truncation, then takes a log backup to trigger truncation and reclaim space."}	null	medium	t	f	\N	2026-02-24 13:10:27.668129
4220	sqlserver	execute	Create SQL Agent job for frequent transaction log backups	{"sql": "-- Immediate: Take a log backup now to reclaim space\\nBACKUP LOG [database_name] TO DISK = N'path\\\\logbackup.trn'\\nWITH COMPRESSION, STATS = 10;\\n\\n-- Check if this resolved the issue\\nSELECT name, log_reuse_wait_desc FROM sys.databases WHERE database_id = DB_ID();\\nSELECT total_log_size_mb, used_log_space_mb, used_log_space_percentage\\nFROM sys.dm_db_log_space_usage;\\n\\n-- If database was never backed up (log_reuse_wait = LOG_BACKUP but no backups exist):\\n-- First take a full backup to establish a backup chain\\nBACKUP DATABASE [database_name] TO DISK = N'path\\\\full.bak' WITH COMPRESSION;\\n-- Then take log backup\\nBACKUP LOG [database_name] TO DISK = N'path\\\\logbackup.trn' WITH COMPRESSION;\\n\\n-- Create a SQL Agent job to run log backups every 15 minutes\\n-- (Use SSMS or sp_add_job/sp_add_jobschedule to create the recurring job)\\n-- Job step command:\\n-- BACKUP LOG [database_name] TO DISK = N'path\\\\logbackup_$(ESCAPE_SQUOTE(STRTDT))_$(ESCAPE_SQUOTE(STRTTM)).trn'\\n-- WITH COMPRESSION, CHECKSUM;", "parameters": ["database_name", "backup_path", "backup_interval_minutes"], "description": "Takes an immediate log backup to reclaim space and establishes a recurring log backup schedule via SQL Agent."}	null	low	f	t	\N	2026-02-24 13:10:27.669772
4226	sqlserver	execute	Restart CDC capture job and clear the log scan backlog	{"sql": "-- Check CDC capture job status\\nEXEC sys.sp_cdc_help_jobs;\\n\\n-- If capture job is stopped or failing, restart it\\nEXEC sys.sp_cdc_start_job @job_type = N'capture';\\n\\n-- If capture job is running but lagging, increase throughput\\nEXEC sys.sp_cdc_change_job\\n  @job_type = N'capture',\\n  @maxtrans = 1000,        -- Default 500, increase for high-volume\\n  @maxscans = 20,          -- Default 10, increase to process more per interval\\n  @pollinginterval = 2;    -- Default 5 seconds, reduce for faster processing\\n\\n-- If CDC is no longer needed on specific tables, disable it\\n-- EXEC sys.sp_cdc_disable_table @source_schema = 'dbo', @source_name = 'table_name', @capture_instance = 'all';\\n\\n-- After capture catches up, take a log backup\\nBACKUP LOG [database_name] TO DISK = N'path\\\\logbackup.trn'\\nWITH COMPRESSION;", "parameters": ["database_name", "backup_path"], "description": "Restarts and tunes the CDC capture job to process the accumulated log backlog, then takes a log backup to reclaim space."}	{"sql": "EXEC sys.sp_cdc_change_job @job_type = N'capture', @maxtrans = 500, @maxscans = 10, @pollinginterval = 5;", "description": "Restore default CDC capture job settings."}	medium	t	t	\N	2026-02-24 13:10:27.67156
4230	sqlserver	configure	Optimize log file placement and I/O configuration	{"sql": "-- Step 1: Move log file to faster storage (if possible)\\n-- ALTER DATABASE [database_name] MODIFY FILE (NAME = log_file_name, FILENAME = N'D:\\\\fast_ssd\\\\logfile.ldf');\\n-- Note: This requires taking the database offline\\n\\n-- Step 2: Pre-size log file to avoid auto-growth during writes\\nALTER DATABASE [database_name]\\n  MODIFY FILE (NAME = log_file_name, SIZE = 8192MB, FILEGROWTH = 1024MB);\\n\\n-- Step 3: Ensure log file is on a dedicated volume (not shared with data files)\\n-- Check current placement:\\nSELECT name, type_desc, physical_name, size * 8 / 1024 AS size_mb\\nFROM sys.database_files;\\n\\n-- Step 4: Reduce log flush frequency for non-durable workloads\\n-- For SQL 2014+ in-memory OLTP or SQL 2016+ with delayed durability:\\nALTER DATABASE [database_name] SET DELAYED_DURABILITY = ALLOWED;\\n-- Then individual transactions can use: COMMIT WITH (DELAYED_DURABILITY = ON);\\n\\n-- Step 5: Increase log backup frequency to keep active log smaller\\nBACKUP LOG [database_name] TO DISK = N'path\\\\logbackup.trn' WITH COMPRESSION;", "parameters": ["database_name", "log_file_name", "target_size_mb"], "description": "Optimizes log file I/O by pre-sizing, placing on fast dedicated storage, and optionally enabling delayed durability for latency-sensitive workloads."}	{"sql": "ALTER DATABASE [database_name] SET DELAYED_DURABILITY = DISABLED;", "description": "Disable delayed durability if it causes concerns about data loss."}	medium	t	t	\N	2026-02-24 13:10:27.672959
4234	sqlserver	execute	Identify and resolve deferred transactions	{"sql": "-- Step 1: Check for deferred transactions\\nSELECT dt.database_transaction_state,\\n  CASE dt.database_transaction_state\\n    WHEN 1 THEN 'Not initialized' WHEN 3 THEN 'Initialized, no log'\\n    WHEN 4 THEN 'Has log records' WHEN 5 THEN 'Prepared'\\n    WHEN 10 THEN 'Committed' WHEN 11 THEN 'Rolled back'\\n    WHEN 12 THEN 'Being committed'\\n  END AS state_desc,\\n  at.transaction_id, at.transaction_begin_time,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS age_minutes,\\n  at.name AS transaction_name,\\n  at.transaction_state\\nFROM sys.dm_tran_database_transactions dt\\nJOIN sys.dm_tran_active_transactions at ON dt.transaction_id = at.transaction_id\\nLEFT JOIN sys.dm_tran_session_transactions st ON st.transaction_id = at.transaction_id\\nWHERE st.session_id IS NULL;\\n\\n-- Step 2: If deferred transactions exist, run DBCC CHECKDB to resolve\\n-- (CHECKDB may resolve page-level issues causing deferred transactions)\\nDBCC CHECKDB ([database_name]) WITH NO_INFOMSGS;\\n\\n-- Step 3: If CHECKDB reports issues, repair them\\n-- ALTER DATABASE [database_name] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;\\n-- DBCC CHECKDB ([database_name], REPAIR_ALLOW_DATA_LOSS);\\n-- ALTER DATABASE [database_name] SET MULTI_USER;\\n\\n-- Step 4: Take log backup after resolution\\nBACKUP LOG [database_name] TO DISK = N'path\\\\logbackup.trn' WITH COMPRESSION;", "parameters": ["database_name", "backup_path"], "description": "Identifies orphaned transactions without sessions and resolves them through DBCC CHECKDB or manual intervention."}	null	medium	t	f	\N	2026-02-24 13:10:27.674077
4236	sqlserver	execute	Kill the orphaned session and configure TCP keepalive for detection	{"sql": "-- Step 1: Kill the orphaned session\\nKILL @orphaned_session_id;\\n\\n-- Step 2: Configure TCP keepalive to detect dead connections faster\\n-- Registry settings (requires SQL Server restart):\\n-- HKLM\\\\SYSTEM\\\\CurrentControlSet\\\\Services\\\\Tcpip\\\\Parameters\\n-- KeepAliveTime = 30000 (30 seconds, default 7200000 = 2 hours)\\n-- KeepAliveInterval = 1000 (1 second, default 1000)\\n-- TcpMaxDataRetransmissions = 3 (default 5)\\n\\n-- Step 3: Configure connection timeout in SQL Server\\nEXEC sp_configure 'remote login timeout', 20;  -- seconds\\nRECONFIGURE;\\n\\n-- Step 4: Optionally create a logon trigger to enforce session timeout\\nCREATE OR ALTER TRIGGER trg_set_session_timeout\\nON ALL SERVER FOR LOGON\\nAS\\nBEGIN\\n  -- Set lock timeout for all user sessions (30 seconds)\\n  SET LOCK_TIMEOUT 30000;\\nEND;", "parameters": ["orphaned_session_id"], "description": "Kills the orphaned session, configures TCP keepalive for faster dead connection detection, and sets connection timeout parameters."}	{"sql": "DROP TRIGGER trg_set_session_timeout ON ALL SERVER;\\nEXEC sp_configure 'remote login timeout', 10;\\nRECONFIGURE;", "description": "Remove the logon trigger and restore default timeout."}	medium	t	t	\N	2026-02-24 13:10:27.674552
