4287	sqlserver	execute	Identify and disable orphaned logins with no production usage	{"sql": "-- Step 1: Disable orphaned logins (no database mappings, no active sessions)\\nDECLARE @login NVARCHAR(256);\\nDECLARE orphan_cursor CURSOR FOR\\n  SELECT sp.name\\n  FROM sys.server_principals sp\\n  WHERE sp.type = 'S'\\n    AND sp.name NOT LIKE '##%##'\\n    AND sp.sid <> 0x01\\n    AND sp.is_disabled = 0\\n    AND NOT EXISTS (\\n      SELECT 1 FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1 FROM sys.databases d\\n      CROSS APPLY (\\n        SELECT dp.sid FROM sys.database_principals dp\\n        WHERE dp.sid = sp.sid AND dp.type = 'S'\\n      ) u\\n    );\\nOPEN orphan_cursor;\\nFETCH NEXT FROM orphan_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  PRINT 'Disabling orphaned login: ' + @login;\\n  EXEC('ALTER LOGIN [' + @login + '] DISABLE');\\n  FETCH NEXT FROM orphan_cursor INTO @login;\\nEND;\\nCLOSE orphan_cursor; DEALLOCATE orphan_cursor;\\n\\n-- Step 2: Review sysadmin-level accounts for excessive privileges\\nSELECT sp.name, sp.type_desc, sp.create_date,\\n  STRING_AGG(r.name, ', ') AS server_roles\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals r ON srm.role_principal_id = r.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%##'\\n  AND sp.name NOT LIKE 'NT SERVICE\\\\%'\\n  AND sp.sid <> 0x01\\n  AND r.name IN ('sysadmin', 'securityadmin', 'serveradmin')\\nGROUP BY sp.name, sp.type_desc, sp.create_date;", "parameters": [], "description": "Disables orphaned SQL logins that have no database user mappings and no active sessions, then reviews remaining high-privilege accounts."}	{"sql": "-- Re-enable a specific login if disabling broke something\\n-- ALTER LOGIN [login_name] ENABLE;", "description": "Re-enable any login that was incorrectly disabled."}	medium	t	t	\N	2026-02-24 13:10:27.697295
4294	sqlserver	execute	Create server audit for comprehensive login tracking	{"sql": "-- Create or enable server audit for login events\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'LoginTrackingAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [LoginTrackingAudit] TO FILE (\\n    FILEPATH = 'C:\\\\SQLAudit\\\\',\\n    MAXSIZE = 200 MB,\\n    MAX_ROLLOVER_FILES = 20,\\n    RESERVE_DISK_SPACE = OFF\\n  ) WITH (ON_FAILURE = CONTINUE);\\nEND\\nALTER SERVER AUDIT [LoginTrackingAudit] WITH (STATE = ON);\\n\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'LoginTrackingSpec')\\nBEGIN\\n  CREATE SERVER AUDIT SPECIFICATION [LoginTrackingSpec]\\n    FOR SERVER AUDIT [LoginTrackingAudit]\\n    ADD (SUCCESSFUL_LOGIN_GROUP),\\n    ADD (FAILED_LOGIN_GROUP),\\n    ADD (LOGIN_CHANGE_PASSWORD_GROUP),\\n    ADD (SERVER_PRINCIPAL_CHANGE_GROUP),\\n    ADD (SERVER_ROLE_MEMBER_CHANGE_GROUP)\\n    WITH (STATE = ON);\\nEND", "parameters": ["audit_file_path"], "description": "Creates a server audit that captures all login events (success, failure, password changes, role changes) for integration with IAM governance processes."}	null	medium	t	t	\N	2026-02-24 13:10:27.700005
