4298	sqlserver	verify	Verify privilege reduction achieved	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  STRING_AGG(r.name, ', ') AS server_roles\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals r ON srm.role_principal_id = r.principal_id\\nWHERE r.name = 'sysadmin'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE 'NT SERVICE\\\\%'\\n  AND sp.name NOT LIKE '##%##'\\nGROUP BY sp.name, sp.type_desc, sp.create_date;", "parameters": [], "description": "Lists all remaining sysadmin members to confirm the count has been reduced to the minimum necessary."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.701479
4299	sqlserver	execute	Create server audit specification for login change tracking	{"sql": "-- Create audit if not exists\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'ChangeControlAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [ChangeControlAudit] TO FILE (\\n    FILEPATH = 'C:\\\\SQLAudit\\\\',\\n    MAXSIZE = 100 MB,\\n    MAX_ROLLOVER_FILES = 10\\n  ) WITH (ON_FAILURE = CONTINUE);\\nEND\\nALTER SERVER AUDIT [ChangeControlAudit] WITH (STATE = ON);\\n\\n-- Create specification capturing all principal changes\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'ChangeControlSpec')\\nBEGIN\\n  CREATE SERVER AUDIT SPECIFICATION [ChangeControlSpec]\\n    FOR SERVER AUDIT [ChangeControlAudit]\\n    ADD (SERVER_PRINCIPAL_CHANGE_GROUP),\\n    ADD (LOGIN_CHANGE_PASSWORD_GROUP),\\n    ADD (SERVER_ROLE_MEMBER_CHANGE_GROUP),\\n    ADD (DATABASE_ROLE_MEMBER_CHANGE_GROUP),\\n    ADD (SERVER_PERMISSION_CHANGE_GROUP)\\n    WITH (STATE = ON);\\nEND", "parameters": ["audit_file_path"], "description": "Creates a server audit and specification that captures all login changes, password changes, role membership changes, and permission changes."}	null	low	t	t	\N	2026-02-24 13:10:27.702045
4416	sqlserver	execute	Enable login auditing for dormancy tracking and create tiered alert report	{"sql": "-- Step 1: Ensure login audit is active\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'LoginTrackingAudit' AND is_state_enabled = 1)\\nBEGIN\\n  IF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'LoginTrackingAudit')\\n    CREATE SERVER AUDIT [LoginTrackingAudit] TO FILE (\\n      FILEPATH = 'C:\\\\SQLAudit\\\\', MAXSIZE = 500 MB, MAX_ROLLOVER_FILES = 30\\n    ) WITH (ON_FAILURE = CONTINUE);\\n  ALTER SERVER AUDIT [LoginTrackingAudit] WITH (STATE = ON);\\nEND\\n\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'LoginTrackingSpec' AND is_state_enabled = 1)\\nBEGIN\\n  IF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'LoginTrackingSpec')\\n    CREATE SERVER AUDIT SPECIFICATION [LoginTrackingSpec]\\n      FOR SERVER AUDIT [LoginTrackingAudit]\\n      ADD (SUCCESSFUL_LOGIN_GROUP), ADD (FAILED_LOGIN_GROUP)\\n      WITH (STATE = ON);\\nEND\\n\\n-- Step 2: Generate tiered dormancy report\\nSELECT sp.name, sp.type_desc, sp.create_date,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  CASE\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180 THEN 'CRITICAL: Disable immediately'\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 90 THEN 'HIGH: Disable within 7 days'\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 60 THEN 'MEDIUM: Investigate'\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 30 THEN 'LOW: Monitor'\\n    ELSE 'RECENT: OK'\\n  END AS dormancy_action\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\nORDER BY DATEDIFF(DAY, sp.modify_date, GETDATE()) DESC;", "parameters": ["audit_file_path"], "description": "Enables login tracking audit and generates a tiered dormancy report with action items based on how long accounts have been inactive."}	null	low	t	t	\N	2026-02-24 13:10:27.742778
