4348	sqlserver	execute	Create server audit for login monitoring and enable policy	{"sql": "-- Step 1: Create login monitoring audit\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'LoginMonitorAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [LoginMonitorAudit] TO FILE (\\n    FILEPATH = 'C:\\\\SQLAudit\\\\',\\n    MAXSIZE = 200 MB,\\n    MAX_ROLLOVER_FILES = 20\\n  ) WITH (ON_FAILURE = CONTINUE);\\nEND\\nALTER SERVER AUDIT [LoginMonitorAudit] WITH (STATE = ON);\\n\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'LoginMonitorSpec')\\nBEGIN\\n  CREATE SERVER AUDIT SPECIFICATION [LoginMonitorSpec]\\n    FOR SERVER AUDIT [LoginMonitorAudit]\\n    ADD (SUCCESSFUL_LOGIN_GROUP),\\n    ADD (FAILED_LOGIN_GROUP),\\n    ADD (LOGIN_CHANGE_PASSWORD_GROUP),\\n    ADD (SERVER_PRINCIPAL_CHANGE_GROUP)\\n    WITH (STATE = ON);\\nEND\\n\\n-- Step 2: Enable policy on all logins\\nDECLARE @login NVARCHAR(256);\\nDECLARE mon_cursor CURSOR FOR\\n  SELECT sp.name FROM sys.sql_logins sl\\n  JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n  WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n    AND sl.is_policy_checked = 0 AND sp.name NOT LIKE '##%';\\nOPEN mon_cursor;\\nFETCH NEXT FROM mon_cursor INTO @login;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  BEGIN TRY\\n    EXEC('ALTER LOGIN [' + @login + '] WITH CHECK_POLICY = ON, CHECK_EXPIRATION = ON');\\n  END TRY\\n  BEGIN CATCH\\n    PRINT 'FAILED: ' + @login + ' - ' + ERROR_MESSAGE();\\n  END CATCH\\n  FETCH NEXT FROM mon_cursor INTO @login;\\nEND;\\nCLOSE mon_cursor; DEALLOCATE mon_cursor;", "parameters": ["audit_file_path"], "description": "Creates server audit for login monitoring and enables password policy on all SQL logins. Audit captures both successful and failed logins for security analysis."}	null	medium	t	t	\N	2026-02-24 13:10:27.720177
4357	sqlserver	verify	Verify cross-domain sysadmin access minimized	{"sql": "SELECT sp.name, sp.type_desc,\\n  LEFT(sp.name, CHARINDEX('\\\\', sp.name) - 1) AS domain_name,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.server_principals sp\\nWHERE sp.type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE 'NT %'\\n  AND IS_SRVROLEMEMBER('sysadmin', sp.name) = 1\\n  AND LEFT(sp.name, CHARINDEX('\\\\', sp.name) - 1) <>\\n    CAST(SERVERPROPERTY('ComputerNamePhysicalNetBIOS') AS NVARCHAR(128));", "parameters": [], "description": "Confirms no cross-domain Windows logins retain sysadmin privileges."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.722214
4361	sqlserver	verify	Verify cross-domain logins have database-specific access only	{"sql": "SELECT sp.name, sp.type_desc,\\n  LEFT(sp.name, CHARINDEX('\\\\', sp.name + '\\\\') - 1) AS domain_name,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  (SELECT MAX(s.login_time) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name) AS last_session\\nFROM sys.server_principals sp\\nWHERE sp.type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n  AND sp.name LIKE '%\\\\%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.is_disabled = 0\\n  AND LEFT(sp.name, CHARINDEX('\\\\', sp.name + '\\\\') - 1) <>\\n    CAST(SERVERPROPERTY('ComputerNamePhysicalNetBIOS') AS NVARCHAR(128))\\nORDER BY domain_name, sp.name;", "parameters": [], "description": "Lists all cross-domain Windows logins to verify none retain sysadmin or elevated server-level roles."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.723091
4368	sqlserver	execute	Create comprehensive login audit with extended event tracking	{"sql": "-- Step 1: Create server audit\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'LoginComprehensiveAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [LoginComprehensiveAudit] TO FILE (\\n    FILEPATH = 'C:\\\\SQLAudit\\\\',\\n    MAXSIZE = 500 MB,\\n    MAX_ROLLOVER_FILES = 30\\n  ) WITH (ON_FAILURE = CONTINUE, QUEUE_DELAY = 1000);\\nEND\\nALTER SERVER AUDIT [LoginComprehensiveAudit] WITH (STATE = ON);\\n\\n-- Step 2: Create audit specification for all login events\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'LoginComprehensiveSpec')\\nBEGIN\\n  CREATE SERVER AUDIT SPECIFICATION [LoginComprehensiveSpec]\\n    FOR SERVER AUDIT [LoginComprehensiveAudit]\\n    ADD (SUCCESSFUL_LOGIN_GROUP),\\n    ADD (FAILED_LOGIN_GROUP),\\n    ADD (LOGIN_CHANGE_PASSWORD_GROUP),\\n    ADD (SERVER_PRINCIPAL_CHANGE_GROUP),\\n    ADD (SERVER_ROLE_MEMBER_CHANGE_GROUP)\\n    WITH (STATE = ON);\\nEND\\n\\n-- Step 3: Enable basic login auditing at the instance level\\n-- (captures to SQL Server error log)\\nEXEC xp_instance_regwrite N'HKEY_LOCAL_MACHINE',\\n  N'Software\\\\Microsoft\\\\MSSQLServer\\\\MSSQLServer',\\n  N'AuditLevel', REG_DWORD, 3; -- 3 = Both success and failure", "parameters": ["audit_file_path"], "description": "Creates comprehensive login auditing that captures successful logins, failed logins, password changes, principal changes, and role membership changes."}	null	low	t	t	\N	2026-02-24 13:10:27.723313
4362	sqlserver	execute	Create logon trigger for IP-based validation and enable audit	{"sql": "-- Step 1: Create logon trigger for IP-based restrictions on group logins\\nCREATE OR ALTER TRIGGER [trg_validate_windows_login] ON ALL SERVER\\nFOR LOGON\\nAS\\nBEGIN\\n  DECLARE @login_name NVARCHAR(256) = ORIGINAL_LOGIN();\\n  DECLARE @client_ip NVARCHAR(50) = EVENTDATA().value('(/EVENT_INSTANCE/ClientHost)[1]', 'NVARCHAR(50)');\\n  -- Block Windows group logins from unexpected subnets\\n  -- Customize the allowed IP ranges for your environment\\n  IF EXISTS (\\n    SELECT 1 FROM sys.server_principals\\n    WHERE type_desc = 'WINDOWS_GROUP'\\n      AND name = @login_name\\n      AND IS_SRVROLEMEMBER('sysadmin', @login_name) = 1\\n  )\\n  AND @client_ip NOT LIKE '10.0.1.%' -- Only allow from trusted subnet\\n  AND @client_ip <> '<local machine>'\\n  BEGIN\\n    ROLLBACK;\\n    RETURN;\\n  END\\nEND;\\n\\n-- Step 2: Enable server audit for Windows auth events\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'WindowsAuthAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [WindowsAuthAudit] TO FILE (\\n    FILEPATH = 'C:\\\\SQLAudit\\\\', MAXSIZE = 200 MB, MAX_ROLLOVER_FILES = 20\\n  ) WITH (ON_FAILURE = CONTINUE);\\nEND\\nALTER SERVER AUDIT [WindowsAuthAudit] WITH (STATE = ON);\\n\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'WindowsAuthSpec')\\nBEGIN\\n  CREATE SERVER AUDIT SPECIFICATION [WindowsAuthSpec]\\n    FOR SERVER AUDIT [WindowsAuthAudit]\\n    ADD (SUCCESSFUL_LOGIN_GROUP),\\n    ADD (FAILED_LOGIN_GROUP)\\n    WITH (STATE = ON);\\nEND", "parameters": ["trusted_subnet"], "description": "Creates a logon trigger that restricts Windows group logins with sysadmin to trusted IP ranges, and enables server audit for all login events."}	{"sql": "DROP TRIGGER [trg_validate_windows_login] ON ALL SERVER;", "description": "Remove the logon trigger if it blocks legitimate connections."}	medium	t	t	\N	2026-02-24 13:10:27.723316
