5037	sqlserver	execute	Create audit specification for trace flag changes	{"sql": "-- Create server audit if none exists:\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audits WHERE name = 'SecurityAudit')\\nBEGIN\\n  CREATE SERVER AUDIT [SecurityAudit]\\n    TO FILE (FILEPATH = N'C:\\\\SQLAudit\\\\', MAXSIZE = 128 MB, MAX_ROLLOVER_FILES = 20)\\n    WITH (QUEUE_DELAY = 1000, ON_FAILURE = CONTINUE);\\n  ALTER SERVER AUDIT [SecurityAudit] WITH (STATE = ON);\\nEND;\\n\\n-- Create or alter audit specification to include TRACE_CHANGE_GROUP:\\nIF NOT EXISTS (SELECT 1 FROM sys.server_audit_specifications WHERE name = 'TraceChangeSpec')\\nBEGIN\\n  CREATE SERVER AUDIT SPECIFICATION [TraceChangeSpec]\\n    FOR SERVER AUDIT [SecurityAudit]\\n    ADD (TRACE_CHANGE_GROUP)\\n    WITH (STATE = ON);\\nEND;", "parameters": [], "description": "Creates a SQL Server Audit and specification to capture all trace flag enable/disable events."}	{"sql": "ALTER SERVER AUDIT SPECIFICATION [TraceChangeSpec] WITH (STATE = OFF);\\nDROP SERVER AUDIT SPECIFICATION [TraceChangeSpec];", "description": "Remove the audit specification if it causes issues."}	low	f	t	00:01:00	2026-02-24 13:10:27.822472
