5136	sqlserver	verify	Check current TLS state and identify old protocol usage	{"sql": "DECLARE @tls10_enabled INT, @tls11_enabled INT, @tls12_enabled INT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Protocols\\\\TLS 1.0\\\\Server',\\n  N'Enabled', @tls10_enabled OUTPUT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Protocols\\\\TLS 1.1\\\\Server',\\n  N'Enabled', @tls11_enabled OUTPUT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Protocols\\\\TLS 1.2\\\\Server',\\n  N'Enabled', @tls12_enabled OUTPUT;\\nSELECT\\n  ISNULL(@tls10_enabled, 1) AS tls10_enabled,\\n  ISNULL(@tls11_enabled, 1) AS tls11_enabled,\\n  ISNULL(@tls12_enabled, 1) AS tls12_enabled,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE encrypt_option = 'TRUE' AND protocol_version < 0x303) AS old_tls_connections;", "parameters": [], "description": "Identifies whether TLS 1.0/1.1 are still enabled and if connections using them exist."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.844769
5227	sqlserver	verify	Check current cipher suite configuration	{"sql": "DECLARE @3descbc INT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Ciphers\\\\Triple DES 168',\\n  N'Enabled', @3descbc OUTPUT;\\nSELECT\\n  ISNULL(@3descbc, 1) AS triple_des_enabled,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE encrypt_option = 'TRUE') AS encrypted_connections;", "parameters": [], "description": "Checks if CBC-vulnerable ciphers like Triple DES are still enabled."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.86944
5230	sqlserver	verify	Check for weak ciphers in Schannel registry	{"sql": "DECLARE @rc4_128 INT, @3des INT, @null_cipher INT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Ciphers\\\\RC4 128/128',\\n  N'Enabled', @rc4_128 OUTPUT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Ciphers\\\\Triple DES 168',\\n  N'Enabled', @3des OUTPUT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Ciphers\\\\NULL',\\n  N'Enabled', @null_cipher OUTPUT;\\nSELECT\\n  ISNULL(@rc4_128, 1) AS rc4_128_enabled,\\n  ISNULL(@3des, 1) AS triple_des_enabled,\\n  ISNULL(@null_cipher, 0) AS null_cipher_enabled;", "parameters": [], "description": "Checks if weak ciphers are enabled despite having TLS 1.2."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.870118
5242	sqlserver	verify	Check if cipher suite order has been customized	{"sql": "DECLARE @cipher_order NVARCHAR(4000);\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SOFTWARE\\\\Policies\\\\Microsoft\\\\Cryptography\\\\Configuration\\\\SSL\\\\00010002',\\n  N'Functions', @cipher_order OUTPUT;\\nSELECT\\n  CASE WHEN @cipher_order IS NULL THEN 'DEFAULT_NOT_CUSTOMIZED'\\n    ELSE 'CUSTOM_CIPHER_ORDER'\\n  END AS cipher_suite_status,\\n  @cipher_order AS configured_cipher_order;", "parameters": [], "description": "Checks if the Windows cipher suite order has been customized from defaults."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.872502
5244	sqlserver	verify	Confirm cipher customization is in effect	{"sql": "DECLARE @cipher_order NVARCHAR(4000);\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SOFTWARE\\\\Policies\\\\Microsoft\\\\Cryptography\\\\Configuration\\\\SSL\\\\00010002',\\n  N'Functions', @cipher_order OUTPUT;\\nSELECT\\n  CASE WHEN @cipher_order IS NOT NULL THEN 'CUSTOMIZED' ELSE 'DEFAULT' END AS status;", "parameters": [], "description": "Verifies the cipher suite order has been customized."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.873112
3236	sqlserver	execute	Rebuild index to eliminate fragmentation and re-evaluate optimizer behavior	{"sql": "-- Rebuild the index online to reduce fragmentation.\\n-- Replace placeholders with actual schema, table, and index names.\\nALTER INDEX [<index_name>]\\n    ON [<schema>].[<table_name>]\\n    REBUILD WITH (ONLINE = ON, FILLFACTOR = 80);", "parameters": {}, "description": "Rebuilds the index to eliminate fragmentation and sets a fill factor of 80 to reduce future page splits on write-heavy tables. After rebuilding, monitor for 24-48 hours to see if the optimizer begins using the index."}	{"description": "-- No direct rollback needed; rebuild is non-destructive.\\n-- If performance worsens, disable the index:\\nALTER INDEX [<index_name>] ON [<schema>].[<table_name>] DISABLE;"}	low	f	t	\N	2026-02-24 13:10:27.525881
5327	sqlserver	verify	Identify stale logins with no recent activity	{"sql": "SELECT sp.name AS login_name, sp.type_desc, sp.create_date,\\n  sp.modify_date, sp.is_disabled,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS days_since_created,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  LOGINPROPERTY(sp.name, 'DaysUntilExpiration') AS days_until_expiration\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa', 'NT AUTHORITY\\\\SYSTEM', 'NT SERVICE\\\\MSSQLSERVER',\\n    'NT SERVICE\\\\SQLSERVERAGENT')\\n  AND sp.is_disabled = 0\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 90\\n  AND sp.principal_id NOT IN (\\n    SELECT DISTINCT security_id FROM sys.dm_exec_sessions\\n    WHERE is_user_process = 1\\n  )\\nORDER BY sp.create_date ASC;", "parameters": [], "description": "Lists enabled logins older than 90 days with no active sessions."}	null	low	f	t	00:01:00	2026-02-24 13:10:27.89568
5335	sqlserver	instruct	Change default port and complete hardening	{"sql": null, "parameters": [], "description": "Complete the hardening checklist: 1) Change port from 1433 to a non-standard port via SQL Server Configuration Manager. 2) Disable SQL Server Browser service if not needed. 3) Enable Force Encryption in Configuration Manager. 4) Create a server audit for security events. 5) Enable Failed Login auditing: EXEC xp_instance_regwrite N'HKEY_LOCAL_MACHINE', N'Software\\\\Microsoft\\\\MSSQLServer\\\\MSSQLServer', N'AuditLevel', REG_DWORD, 2. 6) Configure password policy enforcement for all SQL logins. 7) Restrict remote admin connections to local subnet only. 8) Document the hardening baseline in your CMDB."}	null	medium	t	t	\N	2026-02-24 13:10:27.899233
