5694	postgresql	execute	Identify DDL sessions blocking autovacuum workers	{"sql": "SELECT blocked.pid AS autovacuum_pid, blocked.query AS autovacuum_query,\\n       blocking.pid AS blocking_pid, blocking.query AS blocking_query,\\n       blocking.state, blocking.wait_event_type,\\n       now() - blocking.query_start AS blocking_duration\\nFROM pg_stat_activity blocked\\nJOIN pg_locks bl ON bl.pid = blocked.pid\\nJOIN pg_locks bk ON bk.relation = bl.relation AND bk.pid != bl.pid AND bk.granted\\nJOIN pg_stat_activity blocking ON blocking.pid = bk.pid\\nWHERE blocked.query LIKE 'autovacuum:%'\\n  AND NOT bl.granted;", "parameters": [], "description": "Finds autovacuum workers that are waiting for locks held by DDL operations, showing the blocking session details and duration."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
5695	postgresql	execute	Terminate blocking DDL sessions to unblock autovacuum	{"sql": "SELECT pg_terminate_backend(pid)\\nFROM pg_stat_activity\\nWHERE pid = @blocking_pid;", "parameters": ["blocking_pid"], "description": "Terminates the DDL session identified in step 1 that is blocking autovacuum. The DDL transaction will be rolled back."}	\N	medium	t	f	seconds	2026-02-25 08:59:43.77256
5698	postgresql	configure	Increase autovacuum_max_workers and tune per-table cost delay	{"sql": "ALTER SYSTEM SET autovacuum_max_workers = @new_max_workers;\\nSELECT pg_reload_conf();\\n\\n-- For each large table identified, set higher cost delay so it yields CPU\\nALTER TABLE @large_table SET (autovacuum_vacuum_cost_delay = 40);", "parameters": ["new_max_workers", "large_table"], "description": "Increases the global autovacuum worker pool and sets per-table cost delays on large tables so they run more slowly, allowing workers to service smaller tables."}	{"sql": "ALTER SYSTEM SET autovacuum_max_workers = 3;\\nSELECT pg_reload_conf();\\n\\nALTER TABLE @large_table RESET (autovacuum_vacuum_cost_delay);", "description": "Reset autovacuum_max_workers to default (3) and remove per-table cost delay overrides."}	medium	t	t	1-5 minutes	2026-02-25 08:59:43.77256
