5702	postgresql	verify	Verify autovacuum is keeping up with dead tuple accumulation	{"sql": "SELECT schemaname, relname, n_dead_tup, n_live_tup,\\n       round(n_dead_tup::numeric / NULLIF(n_live_tup, 0) * 100, 2) AS dead_pct,\\n       last_autovacuum, last_vacuum\\nFROM pg_stat_user_tables\\nWHERE n_dead_tup > 10000\\nORDER BY n_dead_tup DESC\\nLIMIT 20;", "parameters": [], "description": "Shows tables with the most dead tuples and their last vacuum times to confirm autovacuum is now keeping pace."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
5703	postgresql	execute	Find disconnected sessions holding temporary tables	{"sql": "SELECT s.pid, s.usename, s.state, s.query,\\n       now() - s.state_change AS idle_duration,\\n       count(t.relname) AS temp_table_count\\nFROM pg_stat_activity s\\nJOIN pg_class t ON t.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname LIKE 'pg_temp_%')\\nWHERE s.state = 'idle'\\n  AND now() - s.state_change > interval '1 hour'\\nGROUP BY s.pid, s.usename, s.state, s.query, s.state_change\\nORDER BY idle_duration DESC;", "parameters": [], "description": "Identifies idle sessions that own temporary tables and have been inactive for more than one hour, suggesting they are orphaned."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
5704	postgresql	execute	Terminate orphaned sessions holding temporary tables	{"sql": "SELECT pg_terminate_backend(pid)\\nFROM pg_stat_activity\\nWHERE state = 'idle'\\n  AND now() - state_change > interval '1 hour'\\n  AND pid IN (\\n    SELECT s.pid FROM pg_stat_activity s\\n    JOIN pg_class t ON t.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname LIKE 'pg_temp_%')\\n  );", "parameters": [], "description": "Terminates long-idle sessions that hold temporary tables, releasing their temp table locks on system catalogs."}	\N	medium	t	f	seconds	2026-02-25 08:59:43.77256
