6182	postgresql	execute	Create monitoring view for peak-hour job execution	{"sql": "CREATE OR REPLACE VIEW peak_hour_job_runs AS\\nSELECT jrd.jobid, j.schedule, j.command, jrd.start_time, jrd.end_time,\\n  jrd.end_time - jrd.start_time AS duration, jrd.status\\nFROM cron.job_run_details jrd\\nJOIN cron.job j ON jrd.jobid = j.jobid\\nWHERE jrd.start_time::time BETWEEN '08:00' AND '18:00'\\n  AND extract(dow FROM jrd.start_time) BETWEEN 1 AND 5\\nORDER BY jrd.start_time DESC;", "parameters": [], "description": "Creates a view that surfaces all job executions that occurred during business hours for monitoring."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
6168	postgresql	execute	Create blackout window enforcement function	{"sql": "CREATE OR REPLACE FUNCTION check_maintenance_window()\\nRETURNS boolean AS $$\\nBEGIN\\n  IF current_time BETWEEN '08:00'::time AND '18:00'::time\\n     AND extract(dow FROM current_date) BETWEEN 1 AND 5 THEN\\n    RAISE NOTICE 'Manual job execution blocked during business hours (Mon-Fri 08:00-18:00)';\\n    RETURN false;\\n  END IF;\\n  RETURN true;\\nEND;\\n$$ LANGUAGE plpgsql;", "parameters": [], "description": "Creates a function that returns false during business hours on weekdays, which job wrapper functions can call before execution."}	\N	low	f	t	seconds	2026-02-25 08:59:43.77256
