11617	oracle	execute	Assess Oracle index fragmentation across schema	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.blevel, i.leaf_blocks,\\n       s.bytes/1024/1024 AS size_mb,\\n       ROUND(i.distinct_keys * 100 / NULLIF(i.leaf_blocks * (SELECT value FROM v$parameter WHERE name = 'db_block_size') / i.avg_leaf_blocks_per_key, 0), 1) AS density_pct\\nFROM dba_indexes i\\nJOIN dba_segments s ON i.owner = s.owner AND i.index_name = s.segment_name\\nWHERE i.owner = ':owner'\\n  AND i.index_type = 'NORMAL'\\n  AND i.leaf_blocks > 100\\nORDER BY i.leaf_blocks DESC;", "parameters": ["owner"], "description": "Profiles all indexes in the schema to identify candidates for rebuild based on fragmentation metrics"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
11618	oracle	configure	Create Oracle DBMS_SCHEDULER job for index maintenance	{"sql": "BEGIN\\n  DBMS_SCHEDULER.CREATE_JOB(\\n    job_name   => ':owner.INDEX_MAINTENANCE_JOB',\\n    job_type   => 'PLSQL_BLOCK',\\n    job_action => 'BEGIN\\n      FOR r IN (SELECT owner, index_name FROM dba_indexes\\n                WHERE owner = '':owner'' AND index_type = ''NORMAL''\\n                AND blevel > 3 AND leaf_blocks > 100) LOOP\\n        EXECUTE IMMEDIATE ''ALTER INDEX '' || r.owner || ''.'' || r.index_name || '' REBUILD ONLINE'';\\n        DBMS_STATS.GATHER_INDEX_STATS(r.owner, r.index_name);\\n      END LOOP;\\n    END;',\\n    start_date => SYSTIMESTAMP,\\n    repeat_interval => 'FREQ=WEEKLY;BYDAY=SUN;BYHOUR=2',\\n    enabled    => TRUE,\\n    comments   => 'Weekly index maintenance - rebuild fragmented indexes'\\n  );\\nEND;\\n/", "parameters": ["owner"], "description": "Creates a weekly scheduler job that identifies and rebuilds fragmented indexes during maintenance window"}	{"sql": "BEGIN\\n  DBMS_SCHEDULER.DROP_JOB(':owner.INDEX_MAINTENANCE_JOB', force => TRUE);\\nEND;\\n/", "description": "Drops the index maintenance scheduler job"}	medium	t	t	1-5 minutes	2026-02-28 22:39:08.596677
