12267	oracle	execute	Oracle create Data Guard monitoring procedure	{"sql": "CREATE OR REPLACE PROCEDURE dba_check_dataguard_health AS\\n  v_transport_lag NUMBER;\\n  v_apply_lag NUMBER;\\n  v_gap_count NUMBER;\\nBEGIN\\n  SELECT COUNT(*) INTO v_gap_count FROM v$archive_gap;\\n  \\n  SELECT (archived_seq# - applied_seq#)\\n  INTO v_transport_lag\\n  FROM v$archive_dest_status\\n  WHERE dest_id = 2;\\n  \\n  IF v_gap_count > 0 OR v_transport_lag > :lag_threshold THEN\\n    -- Log alert to custom table or send notification\\n    INSERT INTO dba_alerts(alert_time, alert_type, alert_message)\\n    VALUES(SYSTIMESTAMP, 'DATAGUARD_LAG',\\n      'Transport lag: ' || v_transport_lag || ' sequences, Gaps: ' || v_gap_count);\\n    COMMIT;\\n  END IF;\\nEND;\\n/", "parameters": ["lag_threshold"], "description": "Creates a PL/SQL monitoring procedure that checks Data Guard health and logs alerts for transport lag or archive gaps"}	{"sql": "DROP PROCEDURE dba_check_dataguard_health;", "description": "Removes the monitoring procedure"}	low	t	t	seconds	2026-02-28 22:39:08.596677
