12512	oracle	execute	Check Oracle current tablespace alert thresholds	{"sql": "SELECT tablespace_name, contents,\\n       ROUND(SUM(bytes)/1024/1024/1024, 2) AS total_gb\\nFROM dba_data_files\\nGROUP BY tablespace_name, contents\\nORDER BY SUM(bytes) DESC;\\n\\nSELECT * FROM dba_thresholds\\nWHERE metrics_name LIKE '%Tablespace%';", "parameters": [], "description": "Reviews current tablespace sizes and any existing alert thresholds"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
12513	oracle	configure	Set Oracle tablespace space usage warning and critical thresholds	{"sql": "BEGIN\\n  DBMS_SERVER_ALERT.SET_THRESHOLD(\\n    metrics_id          => DBMS_SERVER_ALERT.TABLESPACE_PCT_FULL,\\n    warning_operator    => DBMS_SERVER_ALERT.OPERATOR_GE,\\n    warning_value       => ':warning_pct',\\n    critical_operator   => DBMS_SERVER_ALERT.OPERATOR_GE,\\n    critical_value      => ':critical_pct',\\n    observation_period  => 1,\\n    consecutive_occurrences => 1,\\n    instance_name       => NULL,\\n    object_type         => DBMS_SERVER_ALERT.OBJECT_TYPE_TABLESPACE,\\n    object_name         => ':tablespace_name'\\n  );\\nEND;\\n/", "parameters": ["warning_pct", "critical_pct", "tablespace_name"], "description": "Configures Oracle server-generated alerts for tablespace usage at warning and critical thresholds"}	{"sql": "BEGIN\\n  DBMS_SERVER_ALERT.SET_THRESHOLD(\\n    metrics_id => DBMS_SERVER_ALERT.TABLESPACE_PCT_FULL,\\n    warning_operator => DBMS_SERVER_ALERT.OPERATOR_GE,\\n    warning_value => '85',\\n    critical_operator => DBMS_SERVER_ALERT.OPERATOR_GE,\\n    critical_value => '97',\\n    observation_period => 1,\\n    consecutive_occurrences => 1,\\n    instance_name => NULL,\\n    object_type => DBMS_SERVER_ALERT.OBJECT_TYPE_TABLESPACE,\\n    object_name => ':tablespace_name'\\n  );\\nEND;\\n/", "description": "Reverts thresholds to default values"}	low	t	t	seconds	2026-02-28 22:39:08.596677
