12515	oracle	execute	Identify Oracle sessions running uncontrolled bulk operations	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.sql_id,\\n       t.used_ublk AS undo_blocks,\\n       ROUND(t.used_ublk * (SELECT value FROM v$parameter WHERE name = 'db_block_size') / 1024 / 1024, 2) AS undo_mb,\\n       ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 1440) AS minutes\\nFROM v$session s\\nJOIN v$transaction t ON s.taddr = t.addr\\nWHERE t.used_ublk > 10000\\nORDER BY t.used_ublk DESC;", "parameters": [], "description": "Finds sessions with large open transactions generating significant undo (bulk operations)"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
12516	oracle	configure	Configure Oracle Resource Manager to limit bulk operation impact	{"sql": "BEGIN\\n  DBMS_RESOURCE_MANAGER.CREATE_PENDING_AREA();\\n  DBMS_RESOURCE_MANAGER.CREATE_CONSUMER_GROUP(consumer_group => 'BULK_OPS', comment => 'Bulk data operations');\\n  DBMS_RESOURCE_MANAGER.CREATE_PLAN_DIRECTIVE(\\n    plan => 'DEFAULT_PLAN', group_or_subplan => 'BULK_OPS',\\n    mgmt_p1 => 10, max_utilization_limit => 30,\\n    undo_pool => :undo_limit_mb,\\n    switch_group => 'CANCEL_SQL', switch_time => :max_seconds,\\n    switch_estimate => TRUE\\n  );\\n  DBMS_RESOURCE_MANAGER.VALIDATE_PENDING_AREA();\\n  DBMS_RESOURCE_MANAGER.SUBMIT_PENDING_AREA();\\nEND;\\n/", "parameters": ["undo_limit_mb", "max_seconds"], "description": "Creates a Resource Manager consumer group for bulk operations with undo pool limit and execution time cap"}	{"sql": "BEGIN\\n  DBMS_RESOURCE_MANAGER.CREATE_PENDING_AREA();\\n  DBMS_RESOURCE_MANAGER.DELETE_CONSUMER_GROUP(consumer_group => 'BULK_OPS');\\n  DBMS_RESOURCE_MANAGER.SUBMIT_PENDING_AREA();\\nEND;\\n/", "description": "Removes the bulk operations consumer group"}	medium	t	t	1-5 minutes	2026-02-28 22:39:08.596677
12517	oracle	verify	Verify Oracle Resource Manager bulk operation controls active	{"sql": "SELECT consumer_group_name, active_sessions, undo_consumption,\\n       cpu_consumed_time/1000 AS cpu_sec\\nFROM v$rsrc_consumer_group\\nWHERE consumer_group_name = 'BULK_OPS';", "parameters": [], "description": "Confirms the bulk operations consumer group is active and enforcing limits"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
12518	oracle	execute	Identify Oracle tables without archival strategy	{"sql": "SELECT t.owner, t.table_name, t.num_rows, t.partitioned,\\n       ROUND(s.bytes/1024/1024/1024, 2) AS size_gb,\\n       t.last_analyzed\\nFROM dba_tables t\\nJOIN dba_segments s ON t.owner = s.owner AND t.table_name = s.segment_name AND s.segment_type = 'TABLE'\\nWHERE t.owner = ':owner'\\n  AND s.bytes > 1073741824\\n  AND t.partitioned = 'NO'\\nORDER BY s.bytes DESC;", "parameters": ["owner"], "description": "Identifies large non-partitioned tables that would benefit from archival and partitioning"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
12520	oracle	verify	Verify Oracle table partitioning and archival readiness	{"sql": "SELECT partition_name, high_value, num_rows,\\n       ROUND(s.bytes/1024/1024, 2) AS size_mb\\nFROM dba_tab_partitions p\\nJOIN dba_segments s ON p.table_owner = s.owner AND p.partition_name = s.partition_name\\n  AND s.segment_name = ':table_name'\\nWHERE p.table_owner = ':owner' AND p.table_name = ':table_name'\\nORDER BY partition_name;", "parameters": ["owner", "table_name"], "description": "Confirms table is partitioned with proper range boundaries for archival"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
12521	oracle	execute	Identify Oracle tables with abnormal growth rates	{"sql": "SELECT segment_name, segment_type,\\n       ROUND(bytes/1024/1024, 2) AS size_mb,\\n       (SELECT num_rows FROM dba_tables WHERE owner = s.owner AND table_name = s.segment_name) AS num_rows\\nFROM dba_segments s\\nWHERE owner = ':owner'\\n  AND segment_type = 'TABLE'\\nORDER BY bytes DESC\\nFETCH FIRST 20 ROWS ONLY;", "parameters": ["owner"], "description": "Lists the largest tables by segment size to identify abnormal growth"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
12522	oracle	instruct	Implement Oracle data cleanup for application-generated excess data	{"sql": "-- Create cleanup job for excess data:\\nBEGIN\\n  DBMS_SCHEDULER.CREATE_JOB(\\n    job_name   => ':owner.DATA_CLEANUP_JOB',\\n    job_type   => 'PLSQL_BLOCK',\\n    job_action => 'BEGIN\\n      DELETE FROM :owner.:table_name WHERE :date_column < SYSDATE - :retention_days AND ROWNUM <= 100000;\\n      COMMIT;\\n    END;',\\n    repeat_interval => 'FREQ=DAILY;BYHOUR=3',\\n    enabled    => TRUE\\n  );\\nEND;\\n/", "parameters": ["owner", "table_name", "date_column", "retention_days"], "description": "Creates a scheduled cleanup job to remove excess data in manageable batches"}	{"sql": "BEGIN\\n  DBMS_SCHEDULER.DROP_JOB(':owner.DATA_CLEANUP_JOB', force => TRUE);\\nEND;\\n/", "description": "Drops the cleanup job"}	medium	t	t	1-5 minutes	2026-02-28 22:39:08.596677
12523	oracle	verify	Verify Oracle data growth rate normalized after fix	{"sql": "SELECT table_name, num_rows,\\n       ROUND((SELECT bytes FROM dba_segments WHERE owner = ':owner' AND segment_name = t.table_name AND segment_type = 'TABLE')/1024/1024, 2) AS size_mb\\nFROM dba_tables t\\nWHERE owner = ':owner' AND table_name = ':table_name';", "parameters": ["owner", "table_name"], "description": "Checks table row count and size to confirm growth rate has normalized"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
