13268	oracle	execute	ora_create_estate_tracking_system	{"sql": "-- Create tracking repository (in a management database):\\nCREATE TABLE db_estate_inventory (\\n  db_unique_name VARCHAR2(30) PRIMARY KEY,\\n  host_name VARCHAR2(256),\\n  version VARCHAR2(20),\\n  patch_level VARCHAR2(50),\\n  support_status VARCHAR2(20),  -- Premier, Extended, Desupported\\n  eol_date DATE,\\n  upgrade_target_version VARCHAR2(20),\\n  upgrade_planned_date DATE,\\n  upgrade_completed_date DATE,\\n  upgrade_status VARCHAR2(20),  -- Not Started, Planning, Testing, Scheduled, Complete\\n  owner_team VARCHAR2(100),\\n  criticality VARCHAR2(10),     -- P1, P2, P3, P4\\n  last_scanned DATE DEFAULT SYSDATE,\\n  notes VARCHAR2(4000)\\n);\\n\\n-- Create automated scanning job:\\nBEGIN\\n  DBMS_SCHEDULER.CREATE_JOB(\\n    job_name => 'SCAN_DB_ESTATE',\\n    job_type => 'PLSQL_BLOCK',\\n    job_action => 'BEGIN estate_scan_pkg.scan_all_instances; END;',\\n    repeat_interval => 'FREQ=WEEKLY;BYDAY=MON;BYHOUR=6',\\n    enabled => TRUE,\\n    auto_drop => FALSE\\n  );\\nEND;\\n/\\n-- Alternatively, use Oracle Enterprise Manager Fleet Maintenance:\\n-- emcli get_db_homes_in_fleet", "parameters": [], "description": "Create centralized database estate inventory with automated scanning and upgrade tracking"}	{"sql": "DROP TABLE db_estate_inventory;", "description": ""}	medium	t	t	hours	2026-02-28 22:39:08.596677
