13289	oracle	execute	ora_test_patch_in_staging	{"sql": "-- Create test environment from production clone:\\n-- RMAN> DUPLICATE TARGET DATABASE TO testpatch FROM ACTIVE DATABASE;\\n\\n-- Capture SQL Tuning Set (STS) of production workload:\\nBEGIN\\n  DBMS_SQLTUNE.CREATE_SQLSET(sqlset_name => 'pre_patch_sts');\\n  DBMS_SQLTUNE.CAPTURE_CURSOR_CACHE_SQLSET('pre_patch_sts', time_limit => 7200);\\nEND;\\n/\\n\\n-- Create SQL Plan Baselines to protect critical SQL:\\nDECLARE\\n  l_plans PLS_INTEGER;\\nBEGIN\\n  l_plans := DBMS_SPM.LOAD_PLANS_FROM_SQLSET(\\n    sqlset_name => 'pre_patch_sts',\\n    basic_filter => 'elapsed_time/executions > 100000'\\n  );\\n  DBMS_OUTPUT.PUT_LINE(l_plans || ' plans loaded as baselines');\\nEND;\\n/\\n\\n-- Apply patch in test:\\n-- $ORACLE_HOME/OPatch/opatch apply /path/to/patch\\n-- Run datapatch:\\n-- $ORACLE_HOME/OPatch/datapatch -verbose\\n\\n-- Run SQL Performance Analyzer comparison:\\nBEGIN\\n  DBMS_SQLPA.EXECUTE_ANALYSIS_TASK(\\n    task_name => 'patch_impact',\\n    execution_type => 'COMPARE PERFORMANCE',\\n    execution_name => 'pre_vs_post_patch'\\n  );\\nEND;\\n/\\n\\n-- Create Guaranteed Restore Point for instant rollback:\\nCREATE RESTORE POINT pre_patch_grp GUARANTEE FLASHBACK DATABASE;", "parameters": [], "description": "Test patch in staging with SQL Performance Analyzer, create plan baselines, and set up rollback point"}	{"sql": "FLASHBACK DATABASE TO RESTORE POINT pre_patch_grp; ALTER DATABASE OPEN RESETLOGS;", "description": ""}	medium	t	t	hours	2026-02-28 22:39:08.596677
