13316	oracle	execute	ora_implement_threat_monitoring	{"sql": "-- Enable Unified Auditing for comprehensive monitoring:\\n-- (Requires one-time relink)\\n-- cd $ORACLE_HOME/rdbms/lib; make -f ins_rdbms.mk uniaud_on ioracle ORACLE_HOME=$ORACLE_HOME\\n\\n-- Create security-focused audit policies:\\nCREATE AUDIT POLICY failed_logins ACTIONS LOGON FAILURES;\\nAUDIT POLICY failed_logins;\\n\\nCREATE AUDIT POLICY privilege_escalation ACTIONS GRANT, ALTER USER, CREATE USER, ALTER SYSTEM;\\nAUDIT POLICY privilege_escalation;\\n\\nCREATE AUDIT POLICY data_exfiltration ACTIONS SELECT ON SYS.DBA_USERS, SELECT ON SYS.USER$, EXECUTE ON SYS.DBMS_CRYPTO;\\nAUDIT POLICY data_exfiltration;\\n\\n-- Create monitoring job for suspicious activity:\\nBEGIN\\n  DBMS_SCHEDULER.CREATE_JOB(\\n    job_name => 'SECURITY_MONITOR',\\n    job_type => 'PLSQL_BLOCK',\\n    job_action => '\\n      DECLARE\\n        v_failed_logins NUMBER;\\n        v_after_hours NUMBER;\\n      BEGIN\\n        SELECT COUNT(*) INTO v_failed_logins\\n        FROM unified_audit_trail\\n        WHERE action_name = ''LOGON'' AND return_code != 0\\n        AND event_timestamp > SYSTIMESTAMP - INTERVAL ''1'' HOUR;\\n        IF v_failed_logins > 50 THEN\\n          -- Alert: Possible brute force attack\\n          NULL; /* Send alert to security team */\\n        END IF;\\n        SELECT COUNT(*) INTO v_after_hours\\n        FROM unified_audit_trail\\n        WHERE action_name = ''LOGON'' AND return_code = 0\\n        AND TO_CHAR(event_timestamp, ''HH24'') NOT BETWEEN ''06'' AND ''22''\\n        AND event_timestamp > SYSTIMESTAMP - INTERVAL ''1'' HOUR;\\n        IF v_after_hours > 0 THEN\\n          -- Alert: After-hours access detected\\n          NULL; /* Send alert to security team */\\n        END IF;\\n      END;',\\n    repeat_interval => 'FREQ=HOURLY;INTERVAL=1',\\n    enabled => TRUE,\\n    auto_drop => FALSE\\n  );\\nEND;\\n/\\n\\n-- Integrate with SIEM:\\n-- Export audit trail to syslog:\\nALTER SYSTEM SET UNIFIED_AUDIT_SGA_QUEUE_SIZE = 1048576 SCOPE=BOTH;", "parameters": [], "description": "Implement unified auditing, security-focused audit policies, and automated threat monitoring"}	{"sql": "DROP AUDIT POLICY failed_logins; DROP AUDIT POLICY privilege_escalation; DROP AUDIT POLICY data_exfiltration;", "description": ""}	medium	t	t	hours	2026-02-28 22:39:08.596677
