14297	oracle	execute	ora_detect_lock_escalation	{"sql": "SELECT ash.sql_id, ash.event, ash.p1text, ash.p1, ash.p2text, ash.p2,\\n  o.object_name, ash.session_id, ash.blocking_session,\\n  COUNT(*) AS wait_count\\nFROM dba_hist_active_sess_history ash\\nLEFT JOIN dba_objects o ON ash.current_obj# = o.object_id\\nWHERE ash.event IN ('enq: TM - contention', 'enq: TX - row lock contention')\\n  AND ash.sample_time > SYSDATE - 7\\nGROUP BY ash.sql_id, ash.event, ash.p1text, ash.p1, ash.p2text, ash.p2,\\n  o.object_name, ash.session_id, ash.blocking_session\\nORDER BY wait_count DESC FETCH FIRST 30 ROWS ONLY", "parameters": [], "description": "Identify TM (table-level) lock contention events indicating lock escalation"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
14298	oracle	configure	ora_add_fk_indexes_prevent_tm	{"sql": "-- Find unindexed FK columns causing TM locks:\\nSELECT c.constraint_name, c.table_name, cc.column_name\\nFROM dba_constraints c\\nJOIN dba_cons_columns cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner\\nWHERE c.constraint_type = 'R' AND c.owner = UPPER(:schema_name)\\n  AND NOT EXISTS (\\n    SELECT 1 FROM dba_ind_columns ic\\n    WHERE ic.table_name = c.table_name AND ic.column_name = cc.column_name\\n      AND ic.index_owner = c.owner AND ic.column_position = cc.position\\n  )\\nORDER BY c.table_name;\\n-- Create index: CREATE INDEX schema.idx_fk_col ON schema.child_table(fk_column) ONLINE;", "parameters": ["schema_name"], "description": "Index unindexed foreign key columns to prevent implicit TM lock escalation"}	{"sql": "DROP INDEX schema.idx_fk_col", "description": "Drop FK index if not needed"}	medium	t	t	minutes	2026-02-28 22:39:08.596677
