14300	oracle	verify	ora_verify_fk_indexed	{"sql": "SELECT c.table_name, cc.column_name, c.constraint_name,\\n  CASE WHEN EXISTS (\\n    SELECT 1 FROM dba_ind_columns ic\\n    WHERE ic.table_name = c.table_name AND ic.column_name = cc.column_name\\n      AND ic.index_owner = c.owner AND ic.column_position = 1\\n  ) THEN 'INDEXED' ELSE 'MISSING' END AS index_status\\nFROM dba_constraints c\\nJOIN dba_cons_columns cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner\\nWHERE c.constraint_type = 'R' AND c.owner = UPPER(:schema_name)\\nORDER BY c.table_name", "parameters": ["schema_name"], "description": "Verify all FK columns now have supporting indexes"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
14301	oracle	execute	ora_find_explicit_lock_sql	{"sql": "SELECT sql_id, sql_text, executions, elapsed_time/1e6 AS elapsed_sec\\nFROM v$sql\\nWHERE (UPPER(sql_text) LIKE '%FOR UPDATE%'\\n   OR UPPER(sql_text) LIKE '%LOCK TABLE%'\\n   OR UPPER(sql_text) LIKE '%FOR SHARE%')\\n  AND parsing_schema_name = UPPER(:schema_name)\\nORDER BY executions DESC FETCH FIRST 30 ROWS ONLY", "parameters": ["schema_name"], "description": "Find all SQL statements using explicit lock modes"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
