14303	oracle	verify	ora_verify_lock_mode_consistency	{"sql": "SELECT sql_id, sql_text,\\n  CASE\\n    WHEN UPPER(sql_text) LIKE '%FOR UPDATE NOWAIT%' THEN 'NOWAIT'\\n    WHEN UPPER(sql_text) LIKE '%FOR UPDATE WAIT%' THEN 'WAIT'\\n    WHEN UPPER(sql_text) LIKE '%SKIP LOCKED%' THEN 'SKIP_LOCKED'\\n    WHEN UPPER(sql_text) LIKE '%FOR UPDATE%' THEN 'UNBOUNDED'\\n    WHEN UPPER(sql_text) LIKE '%LOCK TABLE%' THEN 'TABLE_LOCK'\\n    ELSE 'OTHER'\\n  END AS lock_pattern\\nFROM v$sql\\nWHERE (UPPER(sql_text) LIKE '%FOR UPDATE%' OR UPPER(sql_text) LIKE '%LOCK TABLE%')\\n  AND parsing_schema_name = UPPER(:schema_name)\\nORDER BY lock_pattern, executions DESC", "parameters": ["schema_name"], "description": "Verify all explicit lock statements use bounded wait or SKIP LOCKED patterns"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
