14355	oracle	instruct	ora_restructure_transaction_scope	{"sql": "-- Pattern: Move expensive operations outside transaction boundary\\n-- BAD:\\n--   BEGIN\\n--     SELECT ... FOR UPDATE;\\n--     <expensive calculation>  -- holds lock during computation\\n--     UPDATE ...;\\n--     COMMIT;\\n--   END;\\n\\n-- GOOD:\\n--   <expensive calculation>   -- compute first\\n--   BEGIN\\n--     SELECT ... FOR UPDATE NOWAIT;\\n--     UPDATE ...;\\n--     COMMIT;\\n--   END;\\n\\n-- Use autonomous transactions for logging:\\nCREATE OR REPLACE PROCEDURE log_action(p_msg VARCHAR2) AS\\n  PRAGMA AUTONOMOUS_TRANSACTION;\\nBEGIN\\n  INSERT INTO audit_log(ts, msg) VALUES (SYSTIMESTAMP, p_msg);\\n  COMMIT;\\nEND;", "parameters": [], "description": "Restructure code to perform expensive operations before acquiring locks, and use autonomous transactions for logging"}	\N	low	f	t	minutes	2026-02-28 22:39:08.596677
