14360	oracle	execute	ora_find_fk_causing_tm_locks	{"sql": "SELECT c.table_name AS child_table, cc.column_name AS fk_column,\\n  r.table_name AS parent_table, c.constraint_name,\\n  (SELECT COUNT(*) FROM dba_hist_active_sess_history ash\\n   WHERE ash.event = 'enq: TM - contention'\\n     AND ash.current_obj# = (SELECT object_id FROM dba_objects WHERE object_name = c.table_name AND owner = c.owner AND object_type = 'TABLE')\\n     AND ash.sample_time > SYSDATE - 7) AS tm_waits\\nFROM dba_constraints c\\nJOIN dba_cons_columns cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner\\nJOIN dba_constraints r ON c.r_constraint_name = r.constraint_name AND c.r_owner = r.owner\\nWHERE c.constraint_type = 'R' AND c.owner = UPPER(:schema_name)\\n  AND NOT EXISTS (\\n    SELECT 1 FROM dba_ind_columns ic\\n    WHERE ic.table_name = c.table_name AND ic.column_name = cc.column_name\\n      AND ic.index_owner = c.owner AND ic.column_position = 1)\\nORDER BY tm_waits DESC", "parameters": ["schema_name"], "description": "Find unindexed FK columns and their associated TM lock contention"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
