14373	oracle	instruct	ora_split_transaction_scope	{"sql": "-- Before: Single large transaction\\n-- UPDATE large_table SET col = :val WHERE condition;\\n-- UPDATE lookup_table SET col = :val2;\\n-- INSERT INTO audit_log(...);\\n-- COMMIT;\\n\\n-- After: Split into logical units\\n-- Unit 1: Batch DML with periodic commits\\nBEGIN\\n  LOOP\\n    UPDATE large_table SET col = :val WHERE condition AND ROWNUM <= 5000;\\n    EXIT WHEN SQL%ROWCOUNT = 0;\\n    COMMIT;\\n  END LOOP;\\nEND;\\n\\n-- Unit 2: Separate lookup update\\nUPDATE lookup_table SET col = :val2;\\nCOMMIT;\\n\\n-- Unit 3: Autonomous audit logging\\n-- PRAGMA AUTONOMOUS_TRANSACTION for audit inserts", "parameters": [], "description": "Split large transactions into smaller logical units with intermediate commits"}	\N	low	f	t	minutes	2026-02-28 22:39:08.596677
