14385	oracle	instruct	ora_optimize_isolation_usage	{"sql": "-- For read-only reports, use READ ONLY instead of SERIALIZABLE:\\nSET TRANSACTION READ ONLY;\\n-- This gets a consistent snapshot without any write conflict errors\\n\\n-- For write transactions needing consistency, use READ COMMITTED + FOR UPDATE:\\nSELECT * FROM accounts WHERE id = :id FOR UPDATE;\\nUPDATE accounts SET balance = balance - :amount WHERE id = :id;\\nCOMMIT;\\n\\n-- For optimistic concurrency, use ORA_ROWSCN:\\nSELECT col, ORA_ROWSCN FROM table WHERE id = :id;\\n-- Later:\\nUPDATE table SET col = :val WHERE id = :id AND ORA_ROWSCN = :saved_scn;", "parameters": [], "description": "Match isolation level to workload: READ ONLY for reports, READ COMMITTED with FOR UPDATE for writes, ORA_ROWSCN for optimistic concurrency"}	\N	low	f	t	minutes	2026-02-28 22:39:08.596677
