14392	oracle	execute	ora_find_bitmap_dml_contention	{"sql": "SELECT i.index_name, i.table_name, i.index_type,\\n  (SELECT COUNT(*) FROM dba_hist_active_sess_history ash\\n   WHERE ash.current_obj# = (SELECT object_id FROM dba_objects WHERE object_name = i.index_name AND owner = i.owner AND object_type = 'INDEX')\\n     AND ash.event LIKE 'enq: TX%'\\n     AND ash.sample_time > SYSDATE - 7) AS tx_waits,\\n  (SELECT SUM(inserts + updates + deletes) FROM dba_tab_modifications m\\n   WHERE m.table_name = i.table_name AND m.table_owner = i.owner) AS total_dml\\nFROM dba_indexes i\\nWHERE i.index_type = 'BITMAP' AND i.owner = UPPER(:schema_name)\\nORDER BY tx_waits DESC", "parameters": ["schema_name"], "description": "Find bitmap indexes on tables with high DML activity causing TX contention"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
