14435	oracle	execute	ora_identify_iot_hot_block	{"sql": "SELECT t.table_name, t.iot_type, t.iot_name,\\n  tc.column_name AS pk_column, tc.data_type,\\n  s.blocks AS segment_blocks\\nFROM dba_tables t\\nJOIN dba_cons_columns cc ON t.table_name = cc.table_name AND t.owner = cc.owner\\nJOIN dba_constraints c ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner\\nJOIN dba_tab_columns tc ON cc.column_name = tc.column_name AND cc.table_name = tc.table_name AND cc.owner = tc.owner\\nJOIN dba_segments s ON t.table_name = s.segment_name AND t.owner = s.owner\\nWHERE c.constraint_type = 'P' AND t.owner = UPPER(:schema_name)\\n  AND (t.iot_type = 'IOT' OR tc.data_type = 'NUMBER')\\n  AND cc.position = 1\\nORDER BY s.blocks DESC FETCH FIRST 20 ROWS ONLY", "parameters": ["schema_name"], "description": "Find IOTs and tables with sequential numeric PKs that may have hot block issues"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
