14449	oracle	execute	ora_find_external_io_transactions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.event,\\n  t.start_time,\\n  ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS txn_duration_sec,\\n  s.wait_class, s.seconds_in_wait,\\n  (SELECT COUNT(*) FROM v$session w WHERE w.blocking_session = s.sid) AS waiters\\nFROM v$session s\\nJOIN v$transaction t ON s.saddr = t.ses_addr\\nWHERE s.wait_class IN ('Network', 'Other', 'Application')\\n  AND (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 > 30\\nORDER BY txn_duration_sec DESC", "parameters": [], "description": "Find transactions waiting on network or external events while holding locks"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
14450	oracle	instruct	ora_restructure_external_io	{"sql": "-- BAD: External call inside transaction\\n-- BEGIN\\n--   UPDATE orders SET status = 'PROCESSING' WHERE id = :id;\\n--   UTL_HTTP.REQUEST('http://api/process?id=' || :id);  -- holds lock during HTTP call\\n--   UPDATE orders SET status = 'COMPLETE' WHERE id = :id;\\n--   COMMIT;\\n-- END;\\n\\n-- GOOD: External call outside transaction\\n-- Step 1: Mark for processing\\nUPDATE orders SET status = 'PROCESSING' WHERE id = :id;\\nCOMMIT;\\n-- Step 2: External call (no transaction)\\n-- app_result = http_call('http://api/process?id=' || :id);\\n-- Step 3: Record result\\nUPDATE orders SET status = DECODE(:success, 1, 'COMPLETE', 'FAILED') WHERE id = :id;\\nCOMMIT;\\n\\n-- Use autonomous transactions for logging within PL/SQL:\\nCREATE OR REPLACE PROCEDURE log_external_call(p_result VARCHAR2) AS\\n  PRAGMA AUTONOMOUS_TRANSACTION;\\nBEGIN\\n  INSERT INTO call_log(ts, result) VALUES (SYSTIMESTAMP, p_result);\\n  COMMIT;\\nEND;", "parameters": [], "description": "Move external I/O (HTTP calls, file I/O, messaging) outside Oracle transaction boundaries"}	\N	low	f	t	minutes	2026-02-28 22:39:08.596677
14451	oracle	verify	ora_verify_no_external_io_locks	{"sql": "SELECT COUNT(*) AS external_io_txns\\nFROM v$session s\\nJOIN v$transaction t ON s.saddr = t.ses_addr\\nWHERE s.wait_class IN ('Network', 'Other')\\n  AND (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 > 30", "parameters": [], "description": "Verify no transactions are waiting on external I/O for more than 30 seconds"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
14452	oracle	execute	ora_find_app_processing_delays	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.module, s.action,\\n  s.status, s.event,\\n  ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS txn_sec,\\n  s.last_call_et,\\n  CASE WHEN s.wait_class = 'Idle' THEN 'APP_PROCESSING'\\n       WHEN s.wait_class = 'Network' THEN 'NETWORK_WAIT'\\n       ELSE s.wait_class END AS likely_cause\\nFROM v$session s\\nJOIN v$transaction t ON s.saddr = t.ses_addr\\nWHERE (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 > 10\\n  AND s.wait_class IN ('Idle', 'Network', 'Application')\\nORDER BY txn_sec DESC", "parameters": [], "description": "Find transactions where the session is idle (application processing) while holding locks"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
14453	oracle	instruct	ora_restructure_app_processing	{"sql": "-- Pattern: Compute first, then do minimal database work\\n-- \\n-- BAD:\\n--   BEGIN TRANSACTION\\n--   SELECT data FOR UPDATE\\n--   <complex calculation>     -- holds lock during computation\\n--   <validation logic>        -- holds lock during validation\\n--   UPDATE result\\n--   COMMIT\\n--\\n-- GOOD:\\n--   SELECT data (no lock)     -- read without lock\\n--   <complex calculation>     -- compute without lock\\n--   <validation logic>        -- validate without lock\\n--   BEGIN TRANSACTION\\n--   SELECT data FOR UPDATE NOWAIT  -- brief lock\\n--   UPDATE result                  -- immediate update\\n--   COMMIT                        -- release lock quickly\\n\\n-- Use optimistic concurrency with ORA_ROWSCN:\\nSELECT col, ORA_ROWSCN AS scn FROM table WHERE id = :id;\\n-- ... application processing ...\\nUPDATE table SET col = :new_val WHERE id = :id AND ORA_ROWSCN = :saved_scn;\\n-- SQL%ROWCOUNT = 0 means data changed, retry", "parameters": [], "description": "Restructure application to perform computation before locking, using optimistic concurrency where possible"}	\N	low	f	t	minutes	2026-02-28 22:39:08.596677
