14458	oracle	execute	ora_find_slow_queries_in_txn	{"sql": "SELECT s.sql_id, sq.sql_text,\\n  ROUND(sq.elapsed_time/1e6/GREATEST(sq.executions, 1), 2) AS avg_sec,\\n  sq.buffer_gets/GREATEST(sq.executions, 1) AS avg_gets,\\n  (SELECT COUNT(*) FROM v$sql_plan p WHERE p.sql_id = s.sql_id AND p.operation = 'TABLE ACCESS' AND p.options = 'FULL') AS full_scans\\nFROM v$session s\\nJOIN v$transaction t ON s.saddr = t.ses_addr\\nJOIN v$sql sq ON s.sql_id = sq.sql_id AND s.sql_child_number = sq.child_number\\nWHERE sq.elapsed_time/1e6/GREATEST(sq.executions, 1) > 0.5\\nORDER BY avg_sec DESC FETCH FIRST 20 ROWS ONLY", "parameters": [], "description": "Find slow queries executing within transactions that use full table scans"}	\N	low	f	t	seconds	2026-02-28 22:39:08.596677
14459	oracle	configure	ora_create_supporting_indexes	{"sql": "-- Use SQL Tuning Advisor for index recommendations:\\nDECLARE v_task VARCHAR2(64);\\nBEGIN\\n  v_task := DBMS_SQLTUNE.CREATE_TUNING_TASK(sql_id => :sql_id);\\n  DBMS_SQLTUNE.EXECUTE_TUNING_TASK(v_task);\\nEND;\\n/\\nSELECT DBMS_SQLTUNE.REPORT_TUNING_TASK(:task_name) FROM dual;\\n\\n-- Create recommended index:\\nCREATE INDEX schema.idx_txn_support ON schema.table_name(where_col) ONLINE;\\nBEGIN DBMS_STATS.GATHER_INDEX_STATS(UPPER(:schema_name), 'IDX_TXN_SUPPORT'); END;", "parameters": ["sql_id", "schema_name"], "description": "Create indexes recommended by SQL Tuning Advisor to eliminate full table scans in transactions"}	{"sql": "DROP INDEX schema.idx_txn_support", "description": "Drop supporting index"}	medium	t	t	minutes	2026-02-28 22:39:08.596677
