26433	mysql	configure	mysql_create_integrity_check_event	{"sql": "DELIMITER //\\nCREATE EVENT IF NOT EXISTS weekly_integrity_check\\nON SCHEDULE EVERY 1 WEEK\\nSTARTS CURRENT_DATE + INTERVAL 6 DAY + INTERVAL 3 HOUR\\nENABLE\\nCOMMENT 'Weekly CHECK TABLE for all InnoDB tables'\\nDO\\nBEGIN\\n  DECLARE done INT DEFAULT FALSE;\\n  DECLARE tbl_schema VARCHAR(64);\\n  DECLARE tbl_name VARCHAR(64);\\n  DECLARE cur CURSOR FOR\\n    SELECT TABLE_SCHEMA, TABLE_NAME FROM information_schema.TABLES\\n    WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql','information_schema','performance_schema','sys');\\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\\n  OPEN cur;\\n  read_loop: LOOP\\n    FETCH cur INTO tbl_schema, tbl_name;\\n    IF done THEN LEAVE read_loop; END IF;\\n    SET @stmt = CONCAT('CHECK TABLE `', tbl_schema, '`.`', tbl_name, '` MEDIUM');\\n    PREPARE s FROM @stmt;\\n    EXECUTE s;\\n    DEALLOCATE PREPARE s;\\n  END LOOP;\\n  CLOSE cur;\\nEND//\\nDELIMITER ;", "parameters": {"schedule": "Weekly, Sunday 3:00 AM", "check_option": "MEDIUM (balances thoroughness and speed)"}, "description": "Create a weekly event that runs CHECK TABLE MEDIUM on all InnoDB user tables during off-peak hours (Sunday 3 AM)."}	{"sql": "DROP EVENT IF EXISTS weekly_integrity_check;", "description": ""}	medium	t	t	5 minutes	2026-03-01 09:33:09.381992
