26874	mysql	configure	mysql_enable_parallel_replication_applier	{"sql": "-- Stop replica before changing parallel worker settings\\nSTOP REPLICA SQL_THREAD;\\n\\n-- Enable parallel applier (8 workers is a good starting point)\\nSET GLOBAL replica_parallel_workers = 8;\\nSET GLOBAL replica_parallel_type = 'LOGICAL_CLOCK';\\nSET GLOBAL replica_preserve_commit_order = ON;\\n\\n-- Restart SQL thread\\nSTART REPLICA SQL_THREAD;\\n\\n-- Persist settings (MySQL 8.0+)\\n-- Add to my.cnf:\\n-- replica_parallel_workers = 8\\n-- replica_parallel_type = LOGICAL_CLOCK\\n-- replica_preserve_commit_order = ON", "parameters": {"replica_parallel_type": "LOGICAL_CLOCK", "replica_parallel_workers": 8}, "description": "Enable multi-threaded replication applier with LOGICAL_CLOCK parallelism to increase apply throughput. LOGICAL_CLOCK allows parallel apply of transactions that overlapped on the primary."}	{"sql": "STOP REPLICA SQL_THREAD;\\nSET GLOBAL replica_parallel_workers = 0;\\nSTART REPLICA SQL_THREAD;", "description": ""}	medium	t	t	2 minutes	2026-03-01 09:33:09.381992
