26976	mysql	verify	mysql_verify_consensus_mechanism_active	{"sql": "-- Verify all members are in the group with Paxos consensus\\nSELECT\\n  MEMBER_HOST,\\n  MEMBER_PORT,\\n  MEMBER_STATE,\\n  MEMBER_ROLE,\\n  MEMBER_VERSION\\nFROM performance_schema.replication_group_members;\\n\\n-- Verify single primary mode is enforced\\nSHOW VARIABLES LIKE 'group_replication_single_primary_mode';\\n\\n-- Verify consensus is working by checking transactions\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME LIKE 'group_replication_transactions%'\\n   OR VARIABLE_NAME = 'group_replication_primary_member';", "parameters": null, "description": "Verify Group Replication with Paxos consensus is active, all members are ONLINE, and single-primary mode is enforced."}	\N	low	f	t	10 minutes	2026-03-01 09:33:09.381992
