26978	mysql	configure	mysql_implement_primary_tracking_queries	{"sql": "-- Create a monitoring view for primary role tracking\\nCREATE OR REPLACE VIEW sys.primary_status AS\\nSELECT\\n  m.MEMBER_HOST AS primary_host,\\n  m.MEMBER_PORT AS primary_port,\\n  m.MEMBER_ID AS primary_uuid,\\n  m.MEMBER_STATE,\\n  m.MEMBER_ROLE,\\n  NOW() AS checked_at,\\n  (@@read_only = 0 AND @@super_read_only = 0) AS is_local_primary\\nFROM performance_schema.replication_group_members m\\nWHERE m.MEMBER_ROLE = 'PRIMARY'\\n  AND m.MEMBER_STATE = 'ONLINE';\\n\\n-- Configure MySQL Router to dynamically track primary\\n-- mysqlrouter --bootstrap <primary_host>:3306 --user=mysqlrouter\\n-- MySQL Router auto-tracks primary via Group Replication metadata\\n\\nSHOW STATUS LIKE 'group_replication_primary_member';", "parameters": null, "description": "Create monitoring views and configure MySQL Router for dynamic primary tracking that automatically follows Group Replication elections."}	{"sql": "DROP VIEW IF EXISTS sys.primary_status;", "description": ""}	low	f	t	20 minutes	2026-03-01 09:33:09.381992
31901	mariadb	diagnose	mysql_identify_growing_row_updates	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, t.DATA_FREE, t.AVG_ROW_LENGTH FROM information_schema.TABLES t JOIN information_schema.COLUMNS c ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME WHERE c.DATA_TYPE IN ('varchar', 'varbinary', 'text', 'blob') AND t.DATA_FREE > 10485760 AND t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY t.DATA_FREE DESC LIMIT 20;", "parameters": null, "description": "Identify tables with variable-length columns and high fragmentation that are likely experiencing row-growth-induced page splits."}	\N	low	f	t	1 minute	2026-05-11 22:17:39.229791
26979	mysql	configure	mysql_configure_monitoring_alerts_for_primary_changes	{"sql": "-- Set up performance_schema monitoring for primary changes\\nUPDATE performance_schema.setup_instruments\\nSET ENABLED = 'YES', TIMED = 'YES'\\nWHERE NAME LIKE '%group_replication%';\\n\\nUPDATE performance_schema.setup_consumers\\nSET ENABLED = 'YES'\\nWHERE NAME LIKE '%events_errors%'\\n   OR NAME LIKE '%global_status%';\\n\\n-- Create event to log primary changes\\nCREATE EVENT IF NOT EXISTS monitor_primary_changes\\n  ON SCHEDULE EVERY 30 SECOND\\n  DO\\n  INSERT INTO mysql.primary_change_log (checked_at, primary_host, primary_uuid)\\n  SELECT NOW(), MEMBER_HOST, MEMBER_ID\\n  FROM performance_schema.replication_group_members\\n  WHERE MEMBER_ROLE = 'PRIMARY'\\n  ON DUPLICATE KEY UPDATE checked_at = NOW();", "parameters": null, "description": "Enable performance_schema Group Replication instruments and create automated monitoring for primary role changes."}	{"sql": "DROP EVENT IF EXISTS monitor_primary_changes;", "description": ""}	low	f	t	15 minutes	2026-03-01 09:33:09.381992
26980	mysql	verify	mysql_verify_primary_role_tracking_operational	{"sql": "-- Verify monitoring view returns correct primary\\nSELECT * FROM sys.primary_status;\\n\\n-- Verify performance_schema instruments are enabled\\nSELECT COUNT(*) AS enabled_gr_instruments\\nFROM performance_schema.setup_instruments\\nWHERE NAME LIKE '%group_replication%'\\n  AND ENABLED = 'YES';\\n\\n-- Test primary detection after simulated primary switch\\n-- MySQL Shell: dba.getCluster().status() (InnoDB Cluster)\\n-- or:\\nSELECT\\n  MEMBER_HOST,\\n  MEMBER_ROLE,\\n  MEMBER_STATE\\nFROM performance_schema.replication_group_members\\nORDER BY MEMBER_ROLE;", "parameters": null, "description": "Verify that all nodes correctly identify the current primary and monitoring systems are tracking role changes in real time."}	\N	low	f	t	10 minutes	2026-03-01 09:33:09.381992
26981	mysql	diagnose	mysql_diagnose_network_flapping_impact	{"sql": "-- Check Group Replication view change events (indicates topology churn)\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN (\\n  'group_replication_primary_member',\\n  'Rpl_semi_sync_master_no_tx',\\n  'Rpl_semi_sync_master_timefunc_failures'\\n);\\n\\n-- Check error log for repeated member join/leave events\\nSELECT\\n  LOGGED,\\n  DATA\\nFROM performance_schema.error_log\\nWHERE DATA LIKE '%Member%joined%'\\n   OR DATA LIKE '%Member%left%'\\n   OR DATA LIKE '%UNREACHABLE%'\\n   OR DATA LIKE '%PRIMARY%'\\nORDER BY LOGGED DESC\\nLIMIT 50;\\n\\n-- Check network-level stats\\nSHOW GLOBAL STATUS LIKE 'Aborted_connects';", "parameters": null, "description": "Identify the frequency and pattern of network flapping events from Group Replication member join/leave cycles in the error log."}	\N	low	f	t	10 minutes	2026-03-01 09:33:09.381992
26982	mysql	configure	mysql_tune_group_replication_network_tolerances	{"sql": "-- Increase member expel timeout to tolerate transient network issues\\n-- Default is 0 seconds; increase to 5-30 seconds based on network SLA\\nSET GLOBAL group_replication_member_expel_timeout = 10;\\n\\n-- Configure autorejoin to handle brief disconnections\\nSET GLOBAL group_replication_autorejoin_tries = 5;\\n\\n-- Tune GCS (Group Communication System) timeouts\\n-- These must be set in my.cnf (not dynamic):\\n-- loose_group_replication_communication_max_message_size = 10485760\\n\\n-- Configure semi-sync timeout (if using semi-sync)\\nSET GLOBAL rpl_semi_sync_source_timeout = 10000;  -- 10 seconds\\n\\n-- Persist all settings in my.cnf:\\n-- group_replication_member_expel_timeout = 10\\n-- group_replication_autorejoin_tries = 5", "parameters": null, "description": "Increase Group Replication network tolerance thresholds to prevent failovers on transient network interruptions."}	{"sql": "SET GLOBAL group_replication_member_expel_timeout = 0; SET GLOBAL group_replication_autorejoin_tries = 3;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
26983	mysql	configure	mysql_stabilize_network_infrastructure	{"sql": "-- Diagnose network path quality between cluster nodes\\n-- From OS level (not SQL):\\n-- ping -c 100 <replica_host>   -- check packet loss and RTT variance\\n-- mtr <replica_host>           -- trace route with loss statistics\\n-- ss -ti dst <replica_host>    -- TCP connection statistics\\n\\n-- Configure MySQL to use dedicated replication network interface\\n-- In my.cnf:\\n-- group_replication_local_address = '<dedicated_replication_ip>:33061'\\n-- bind_address = '<dedicated_replication_ip>'\\n\\n-- Enable TCP keepalive for MySQL connections\\nSET GLOBAL wait_timeout = 28800;\\nSET GLOBAL interactive_timeout = 28800;\\n\\n-- Check OS TCP keepalive settings:\\n-- sysctl net.ipv4.tcp_keepalive_time  (default: 7200s, reduce to 60s)\\n-- sysctl -w net.ipv4.tcp_keepalive_time=60\\n\\nSHOW VARIABLES LIKE 'group_replication_local_address';", "parameters": null, "description": "Identify and remediate the network infrastructure issues causing flapping, and configure MySQL to use stable dedicated replication interfaces."}	\N	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
26984	mysql	verify	mysql_verify_network_stability	{"sql": "-- Monitor for 24 hours after fixes; check for member stability\\nSELECT\\n  MEMBER_HOST,\\n  MEMBER_STATE,\\n  MEMBER_ROLE\\nFROM performance_schema.replication_group_members;\\n\\n-- Check error log for absence of flapping events\\nSELECT COUNT(*) AS flap_events_last_hour\\nFROM performance_schema.error_log\\nWHERE (DATA LIKE '%Member%joined%' OR DATA LIKE '%UNREACHABLE%')\\n  AND LOGGED > DATE_SUB(NOW(), INTERVAL 1 HOUR);\\n\\n-- Verify replication lag is stable\\nSHOW REPLICA STATUS\\\\G\\n\\n-- Check GCS statistics\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME LIKE 'group_replication%';", "parameters": null, "description": "Verify cluster stability by monitoring member state changes and replication lag over a 24-hour period."}	\N	low	f	t	1440 minutes	2026-03-01 09:33:09.381992
26986	mysql	execute	mysql_reconnect_or_remove_stale_replica	{"sql": "-- Attempt to reconnect the replica first\\n-- On the disconnected replica server (if accessible):\\nSTART REPLICA;\\nSHOW REPLICA STATUS\\\\G\\n\\n-- If replica cannot be reconnected and is permanently gone:\\n-- Note the replica's server_id from SHOW REPLICA STATUS on primary\\n-- Then allow binary logs to be purged without waiting for this replica\\n\\n-- Check if replica was registered\\nSELECT * FROM performance_schema.replication_connection_status\\nWHERE SERVICE_STATE = 'OFF';\\n\\n-- If using binlog_do_db or replica-specific retention, verify settings:\\nSHOW VARIABLES LIKE 'expire_logs_days';  -- deprecated\\nSHOW VARIABLES LIKE 'binlog_expire_logs_seconds';", "parameters": null, "description": "Attempt to reconnect the stale replica. If permanently gone, proceed to purge binary logs retained for this replica."}	{"sql": "STOP REPLICA;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
26987	mysql	execute	mysql_purge_stale_binary_logs	{"sql": "-- Determine the earliest binary log needed by ALL active replicas\\n-- Check currently connected replicas:\\nSELECT\\n  HOST,\\n  STATE,\\n  INFO\\nFROM information_schema.PROCESSLIST\\nWHERE COMMAND LIKE 'Binlog Dump%';\\n\\n-- Find safe purge point: the binlog file that is AFTER\\n-- the position needed by the most lagging active replica\\n\\n-- Purge logs up to a specific file:\\nPURGE BINARY LOGS TO 'mysql-bin.002000';\\n\\n-- Or purge logs older than a specific time:\\nPURGE BINARY LOGS BEFORE DATE_SUB(NOW(), INTERVAL 3 DAY);\\n\\n-- Configure automatic expiry going forward:\\nSET GLOBAL binlog_expire_logs_seconds = 259200;  -- 3 days\\n\\n-- Persist in my.cnf:\\n-- binlog_expire_logs_seconds = 259200", "parameters": null, "description": "Safely purge binary logs retained for the disconnected replica, then configure appropriate automatic binary log expiry."}	\N	medium	t	f	10 minutes	2026-03-01 09:33:09.381992
