26990	mysql	configure	mysql_configure_replication_network_resilience	{"sql": "-- Configure replica to reconnect quickly after network drops\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_CONNECT_RETRY = 10,     -- Retry every 10 seconds (default: 60)\\n  SOURCE_RETRY_COUNT = 100,      -- Retry up to 100 times\\n  SOURCE_HEARTBEAT_PERIOD = 5.0  -- Heartbeat every 5 seconds\\nFOR CHANNEL '';\\n\\n-- Configure replica timeouts\\nSET GLOBAL replica_net_timeout = 30;  -- Detect disconnection within 30s\\n\\n-- Configure network-level keepalive (requires my.cnf restart):\\n-- replica_net_timeout = 30\\n-- source_connect_retry = 10\\n\\nSHOW VARIABLES LIKE 'replica_net_timeout';\\nSHOW VARIABLES LIKE 'source_connect_retry';", "parameters": null, "description": "Configure aggressive reconnection settings and heartbeats to quickly detect and recover from intermittent network drops."}	{"sql": "CHANGE REPLICATION SOURCE TO SOURCE_CONNECT_RETRY=60, SOURCE_RETRY_COUNT=86400 FOR CHANNEL '';", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
26991	mysql	configure	mysql_configure_binlog_expiry_safety_margin	{"sql": "-- Set binary log retention long enough for replica to recover\\n-- from intermittent outages (match with expected MTTR + buffer)\\nSET GLOBAL binlog_expire_logs_seconds = 604800;  -- 7 days\\n\\n-- Enable slave_compressed_protocol to reduce network overhead\\nSET GLOBAL replica_compressed_protocol = ON;\\n\\n-- Enable slave_net_timeout tracking\\nSHOW GLOBAL STATUS LIKE 'Slave_running';\\n\\n-- Configure GTID-based auto-positioning to skip manual log coordination\\n-- (already enabled if GTID mode is ON)\\nSHOW VARIABLES LIKE 'gtid_mode';\\n\\n-- Persist in my.cnf:\\n-- binlog_expire_logs_seconds = 604800\\n-- replica_compressed_protocol = ON\\n-- replica_net_timeout = 30", "parameters": null, "description": "Extend binary log retention to accommodate MTTR for network outages and enable compression to reduce bandwidth-driven drops."}	{"sql": "SET GLOBAL binlog_expire_logs_seconds = 259200; SET GLOBAL replica_compressed_protocol = OFF;", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
