26993	mysql	diagnose	mysql_diagnose_replica_config_errors	{"sql": "-- Check current replica configuration and errors\\nSHOW REPLICA STATUS\\\\G\\n\\n-- Check connection configuration details\\nSELECT\\n  CHANNEL_NAME,\\n  HOST,\\n  PORT,\\n  USER,\\n  SOURCE_UUID,\\n  AUTO_POSITION,\\n  SERVICE_STATE,\\n  LAST_ERROR_NUMBER,\\n  LAST_ERROR_MESSAGE\\nFROM performance_schema.replication_connection_configuration\\nJOIN performance_schema.replication_connection_status USING (CHANNEL_NAME);\\n\\n-- Common config errors:\\n-- 1. Wrong SOURCE_LOG_FILE or SOURCE_LOG_POS\\n-- 2. GTID mismatch (AUTO_POSITION but GTIDs not matching)\\n-- 3. Wrong SOURCE_HOST, SOURCE_PORT, or SOURCE_USER\\n-- 4. Missing or wrong GTID_PURGED on replica", "parameters": null, "description": "Identify specific configuration errors preventing replica from connecting to the binary log stream."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
26994	mysql	execute	mysql_correct_replica_source_configuration	{"sql": "-- Stop replica before reconfiguring\\nSTOP REPLICA;\\n\\n-- Option A: GTID-based auto-positioning (recommended)\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_HOST = '<correct_primary_host>',\\n  SOURCE_PORT = 3306,\\n  SOURCE_USER = 'replication_user',\\n  SOURCE_PASSWORD = '<correct_password>',\\n  SOURCE_AUTO_POSITION = 1;\\n\\n-- Option B: File/position-based (if GTID not used)\\n-- First get correct position from primary:\\n-- SHOW BINARY LOG STATUS; on primary\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_HOST = '<correct_primary_host>',\\n  SOURCE_LOG_FILE = 'mysql-bin.000123',\\n  SOURCE_LOG_POS = 4,  -- Start from beginning of log file\\n  SOURCE_AUTO_POSITION = 0;\\n\\n-- Verify configuration was applied\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Correct the replica source configuration with accurate connection parameters and binary log position or GTID auto-position."}	{"sql": "STOP REPLICA; -- Previous config was already broken; restore from backup if needed.", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
26996	mysql	diagnose	mysql_diagnose_replica_lag_bottleneck	{"sql": "-- Check replication lag and worker thread status\\nSELECT\\n  CHANNEL_NAME,\\n  WORKER_ID,\\n  SERVICE_STATE,\\n  LAST_APPLIED_TRANSACTION,\\n  APPLYING_TRANSACTION,\\n  LAST_ERROR_NUMBER,\\n  LAST_ERROR_MESSAGE\\nFROM performance_schema.replication_applier_status_by_worker;\\n\\n-- Check seconds behind source\\nSHOW REPLICA STATUS\\\\G\\n\\n-- Check replica applier bottleneck\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_variables\\nWHERE VARIABLE_NAME IN (\\n  'replica_parallel_workers',\\n  'replica_parallel_type',\\n  'replica_preserve_commit_order',\\n  'innodb_flush_log_at_trx_commit'\\n);", "parameters": null, "description": "Identify whether replica lag is caused by single-threaded applier, I/O bottleneck, or insufficient hardware resources."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
26997	mysql	configure	mysql_optimize_primary_for_replica_throughput	{"sql": "-- On PRIMARY: optimize group commit settings to maximize parallel replication benefit\\nSET GLOBAL binlog_group_commit_sync_delay = 1000;  -- 1ms delay to batch commits\\nSET GLOBAL binlog_group_commit_sync_no_delay_count = 10;  -- Or 10 transactions\\n\\n-- Enable dependency tracking for optimal replica parallelism\\nSET GLOBAL binlog_transaction_dependency_tracking = 'WRITESET';\\nSET GLOBAL transaction_write_set_extraction = 'XXHASH64';\\n\\n-- Persist in primary my.cnf:\\n-- binlog_transaction_dependency_tracking = WRITESET\\n-- transaction_write_set_extraction = XXHASH64\\n-- binlog_group_commit_sync_delay = 1000\\n\\nSHOW VARIABLES LIKE 'binlog_transaction_dependency_tracking';\\nSHOW VARIABLES LIKE 'binlog_group_commit_sync_delay';", "parameters": null, "description": "Configure primary's binary log dependency tracking to WRITESET mode, enabling maximum parallelism on the replica."}	{"sql": "SET GLOBAL binlog_transaction_dependency_tracking='COMMIT_ORDER'; SET GLOBAL binlog_group_commit_sync_delay=0;", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
