27005	mysql	configure	mysql_configure_semisync_with_fallback	{"sql": "-- Configure semi-sync with safe timeout and wait-no-slave fallback\\nSET GLOBAL rpl_semi_sync_source_timeout = 10000;  -- 10 second timeout\\nSET GLOBAL rpl_semi_sync_source_wait_no_slave = 1;  -- Wait even with no slaves\\n\\n-- For lossless semi-sync (AFTER_SYNC):\\nSET GLOBAL rpl_semi_sync_source_wait_point = 'AFTER_SYNC';\\n\\n-- Configure replica semi-sync:\\n-- On replica:\\nSET GLOBAL rpl_semi_sync_replica_enabled = ON;\\n\\n-- Set up multiple semi-sync replicas for redundancy\\n-- rpl_semi_sync_source_wait_for_slave_count = 1 (minimum)\\nSET GLOBAL rpl_semi_sync_source_wait_for_slave_count = 1;\\n\\nSHOW VARIABLES LIKE 'rpl_semi_sync%';", "parameters": null, "description": "Configure semi-sync with appropriate timeout and AFTER_SYNC wait point for lossless replication with automatic async fallback."}	{"sql": "SET GLOBAL rpl_semi_sync_source_wait_point='AFTER_COMMIT';", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
27006	mysql	verify	mysql_verify_semisync_operational	{"sql": "-- Verify semi-sync is operational with replica connected\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync%';\\n-- Rpl_semi_sync_source_clients should be >= 1\\n-- Rpl_semi_sync_source_status should be ON\\n\\n-- Test a write and verify semi-sync acknowledgment\\nCREATE TABLE IF NOT EXISTS test_semisync (id INT PRIMARY KEY, ts DATETIME);\\nINSERT INTO test_semisync VALUES (1, NOW()) ON DUPLICATE KEY UPDATE ts=NOW();\\n\\n-- Check no timeout occurred\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n-- This should not have incremented since our INSERT", "parameters": null, "description": "Verify semi-sync replication is active with replica acknowledged, and test write completion without timeout."}	{"sql": "DROP TABLE IF EXISTS test_semisync;", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27007	mysql	diagnose	mysql_diagnose_slow_replica_apply_latency	{"sql": "-- Measure replica apply throughput\\nSELECT\\n  WORKER_ID,\\n  SERVICE_STATE,\\n  LAST_APPLIED_TRANSACTION,\\n  LAST_APPLIED_TRANSACTION_END_APPLY_TIMESTAMP,\\n  LAST_APPLIED_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP,\\n  TIMESTAMPDIFF(MILLISECOND,\\n    LAST_APPLIED_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP,\\n    LAST_APPLIED_TRANSACTION_END_APPLY_TIMESTAMP) AS apply_latency_ms\\nFROM performance_schema.replication_applier_status_by_worker;\\n\\n-- Check semi-sync timeout counter\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';\\n\\n-- Check parallel workers configuration\\nSHOW VARIABLES LIKE 'replica_parallel_workers';\\nSHOW VARIABLES LIKE 'replica_parallel_type';", "parameters": null, "description": "Measure replica transaction apply latency and identify the bottleneck causing semi-sync timeout violations."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
