27008	mysql	configure	mysql_tune_replica_apply_performance	{"sql": "-- Enable parallel replication if not already enabled\\nSTOP REPLICA SQL_THREAD;\\n\\nSET GLOBAL replica_parallel_type = 'LOGICAL_CLOCK';\\nSET GLOBAL replica_parallel_workers = 8;\\nSET GLOBAL replica_preserve_commit_order = ON;\\n\\n-- Reduce I/O pressure on replica (safe — replica can be rebuilt)\\nSET GLOBAL innodb_flush_log_at_trx_commit = 2;\\nSET GLOBAL sync_binlog = 0;\\n\\n-- Increase InnoDB buffer pool if replica has available RAM\\nSET GLOBAL innodb_buffer_pool_size = 8589934592;  -- 8GB example\\n\\nSTART REPLICA SQL_THREAD;\\n\\n-- Verify changes\\nSHOW VARIABLES LIKE 'replica_parallel_workers';\\nSHOW VARIABLES LIKE 'innodb_flush_log_at_trx_commit';", "parameters": null, "description": "Enable parallel SQL applier and relax replica durability settings to maximize apply throughput and reduce acknowledgment latency."}	{"sql": "STOP REPLICA SQL_THREAD; SET GLOBAL replica_parallel_workers=0; SET GLOBAL innodb_flush_log_at_trx_commit=1; START REPLICA SQL_THREAD;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
27009	mysql	configure	mysql_adjust_semisync_timeout_threshold	{"sql": "-- Temporarily increase semi-sync timeout to give replica time to apply\\n-- This is a stopgap while performance tuning takes effect\\nSET GLOBAL rpl_semi_sync_source_timeout = 30000;  -- 30 seconds\\n\\n-- Monitor average acknowledgment wait time after tuning\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';\\n\\n-- Once replica latency is reduced, tighten timeout back:\\n-- Target: timeout should be 3-5x the 99th percentile ack latency\\n\\n-- Check primary binlog group commit optimization\\nSHOW VARIABLES LIKE 'binlog_transaction_dependency_tracking';\\nSET GLOBAL binlog_transaction_dependency_tracking = 'WRITESET';\\n\\nSHOW VARIABLES LIKE 'rpl_semi_sync_source_timeout';", "parameters": null, "description": "Increase semi-sync timeout as a temporary buffer while replica performance tuning reduces acknowledgment latency."}	{"sql": "SET GLOBAL rpl_semi_sync_source_timeout = 10000;", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27010	mysql	verify	mysql_verify_semisync_latency_improved	{"sql": "-- Monitor semi-sync acknowledgment wait times\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n\\n-- Verify replica lag is within timeout window\\nSELECT\\n  TIMESTAMPDIFF(MILLISECOND,\\n    APPLYING_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP,\\n    NOW()) AS current_apply_lag_ms\\nFROM performance_schema.replication_applier_status_by_coordinator;\\n\\n-- Verify no timeout events since tuning\\nSELECT VARIABLE_VALUE AS no_tx_count\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME = 'Rpl_semi_sync_source_no_tx';", "parameters": null, "description": "Confirm replica acknowledgment latency is well within semi-sync timeout and timeout fallback events have ceased."}	\N	low	f	t	30 minutes	2026-03-01 09:33:09.381992
