27015	mysql	diagnose	mysql_diagnose_replica_disk_io_bottleneck	{"sql": "-- Measure relay log write latency contributing to ACK delay\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_variables\\nWHERE VARIABLE_NAME IN (\\n  'sync_relay_log',\\n  'relay_log_space_limit',\\n  'innodb_flush_log_at_trx_commit',\\n  'sync_binlog',\\n  'innodb_io_capacity'\\n);\\n\\n-- Check I/O wait via performance_schema\\nSELECT\\n  FILE_NAME,\\n  COUNT_READ,\\n  COUNT_WRITE,\\n  SUM_TIMER_WRITE / 1000000000 AS write_time_ms,\\n  SUM_NUMBER_OF_BYTES_WRITE AS bytes_written\\nFROM performance_schema.file_summary_by_instance\\nWHERE FILE_NAME LIKE '%relay%'\\nORDER BY SUM_TIMER_WRITE DESC\\nLIMIT 10;\\n\\n-- Monitor semi-sync timeout events\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';", "parameters": null, "description": "Identify relay log write latency as the bottleneck by measuring I/O wait times on relay log files and semi-sync timeout frequency."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27016	mysql	configure	mysql_tune_relay_log_io_settings	{"sql": "-- Reduce relay log fsync frequency (ACK sent after write, not fsync)\\n-- sync_relay_log controls how often relay log is synced to disk\\n-- Set to 0 to let OS handle flushing (fastest ACK response)\\nSET GLOBAL sync_relay_log = 0;  -- OS-managed sync (fastest)\\n-- Or set to a higher value (e.g., 100) to sync every 100 events\\n-- SET GLOBAL sync_relay_log = 100;\\n\\n-- Note: sync_relay_log=1 (sync every event) causes slowest ACK\\n-- With GTID and crash-safe relay logs, reducing sync is safe\\n\\n-- Also reduce innodb_flush_log_at_trx_commit on replica\\nSET GLOBAL innodb_flush_log_at_trx_commit = 2;\\nSET GLOBAL sync_binlog = 0;\\n\\n-- Increase innodb_io_capacity for better I/O scheduling\\nSET GLOBAL innodb_io_capacity = 2000;\\nSET GLOBAL innodb_io_capacity_max = 4000;\\n\\nSHOW VARIABLES LIKE 'sync_relay_log';", "parameters": null, "description": "Reduce relay log sync frequency from per-event to OS-managed, dramatically reducing I/O wait and semi-sync ACK latency."}	{"sql": "SET GLOBAL sync_relay_log=1; SET GLOBAL innodb_flush_log_at_trx_commit=1; SET GLOBAL sync_binlog=1;", "description": ""}	medium	t	t	5 minutes	2026-03-01 09:33:09.381992
27017	mysql	configure	mysql_optimize_replica_storage_configuration	{"sql": "-- Check if relay logs are on SSD or spinning disk\\n-- From OS: lsblk -o NAME,ROTA,SIZE,FSTYPE (ROTA=1 means spinning)\\n\\n-- If on spinning disk, move relay logs to SSD:\\n-- Stop replica\\nSTOP REPLICA;\\n\\n-- Configure relay log path to SSD mount point\\n-- In my.cnf:\\n-- relay_log = /ssd/mysql/relay-bin\\n\\n-- Verify relay log location after reconfiguration\\nSHOW VARIABLES LIKE 'relay_log';\\n\\n-- Enable O_DIRECT for InnoDB to bypass OS buffer cache overhead\\nSET GLOBAL innodb_flush_method = 'O_DIRECT';\\n\\n-- Confirm relay_log_info_repository is TABLE for crash safety\\nSHOW VARIABLES LIKE 'relay_log_info_repository';\\n\\nSTART REPLICA;", "parameters": null, "description": "Relocate relay logs to SSD storage and configure InnoDB to use O_DIRECT I/O, reducing relay log write latency."}	{"sql": "STOP REPLICA; -- reconfigure relay_log path in my.cnf; START REPLICA;", "description": ""}	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
