27019	mysql	diagnose	mysql_diagnose_semisync_quorum_shortfall	{"sql": "-- Check required vs actual semi-sync replica count\\nSHOW VARIABLES LIKE 'rpl_semi_sync_source_wait_for_slave_count';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_clients';\\n\\n-- Identify which replicas are connected and semi-sync enabled\\nSELECT\\n  HOST,\\n  STATE,\\n  COMMAND,\\n  TIME\\nFROM information_schema.PROCESSLIST\\nWHERE COMMAND LIKE 'Binlog Dump%';\\n\\n-- Check semi-sync status and timeout events\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync%';\\n\\n-- Check if primary fell back to async\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_status';\\n-- OFF = fell back to async due to quorum not met", "parameters": null, "description": "Confirm the number of connected semi-sync replicas is below the required quorum count and quantify the timeout frequency."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27021	mysql	configure	mysql_add_standby_semisync_replicas	{"sql": "-- Provision additional replica to meet quorum + N+1 redundancy\\n-- On new replica server:\\n-- Install MySQL and configure my.cnf with same server-id rules\\n\\n-- Use Clone Plugin to fast-provision:\\nINSTALL PLUGIN clone SONAME 'mysql_clone.so';\\nCLONE INSTANCE FROM 'clone_user'@'<primary_host>':3306\\n  IDENTIFIED BY '<password>';\\n\\n-- After clone, configure and start replication:\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_HOST = '<primary_host>',\\n  SOURCE_AUTO_POSITION = 1;\\n\\n-- Enable semi-sync on new replica:\\nINSTALL PLUGIN rpl_semi_sync_replica SONAME 'semisync_replica.so';\\nSET GLOBAL rpl_semi_sync_replica_enabled = ON;\\n\\nSTART REPLICA;\\n\\n-- Verify new replica is counted as semi-sync client\\n-- On primary:\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_clients';", "parameters": null, "description": "Provision additional replicas to exceed the required quorum count, providing N+1 redundancy for future failures."}	{"sql": "STOP REPLICA; RESET REPLICA ALL;", "description": ""}	medium	t	t	60 minutes	2026-03-01 09:33:09.381992
27022	mysql	verify	mysql_verify_semisync_quorum_met	{"sql": "-- Verify semi-sync client count meets or exceeds required quorum\\nSELECT\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_variables\\n   WHERE VARIABLE_NAME = 'rpl_semi_sync_source_wait_for_slave_count') AS required_quorum,\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status\\n   WHERE VARIABLE_NAME = 'Rpl_semi_sync_source_clients') AS active_clients,\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status\\n   WHERE VARIABLE_NAME = 'Rpl_semi_sync_source_status') AS semi_sync_status;\\n\\n-- Verify no timeout fallbacks since quorum restored\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n\\n-- Confirm primary write latency is acceptable\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';", "parameters": null, "description": "Confirm active semi-sync replica count exceeds required quorum, primary is in semi-sync mode, and write latency is normal."}	\N	low	f	t	10 minutes	2026-03-01 09:33:09.381992
27023	mysql	diagnose	mysql_diagnose_replica_lock_contention	{"sql": "-- On the replica: identify blocking locks and long-running transactions\\nSELECT r.trx_id AS waiting_trx_id,\\n       r.trx_mysql_thread_id AS waiting_thread,\\n       r.trx_query AS waiting_query,\\n       b.trx_id AS blocking_trx_id,\\n       b.trx_mysql_thread_id AS blocking_thread,\\n       b.trx_query AS blocking_query,\\n       TIMESTAMPDIFF(SECOND, r.trx_wait_started, NOW()) AS wait_seconds\\nFROM information_schema.INNODB_TRX r\\nJOIN information_schema.INNODB_TRX b\\n  ON r.trx_wait_started IS NOT NULL\\nJOIN performance_schema.data_lock_waits dlw\\n  ON dlw.REQUESTING_ENGINE_TRANSACTION_ID = r.trx_id\\nORDER BY wait_seconds DESC\\nLIMIT 20;\\n\\n-- Also check replica SQL thread status\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Identifies lock waiters on the replica and checks replication SQL thread lag and state"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27025	mysql	configure	mysql_configure_replica_isolation_and_semisync_timeout	{"sql": "-- On the primary: increase semi-sync timeout to accommodate occasional lock spikes\\nSET GLOBAL rpl_semi_sync_source_timeout = 10000;  -- 10 seconds (default is 10000ms)\\n\\n-- On the replica: reduce transaction isolation if analytics queries cause long snapshots\\n-- Only if replica serves read-only analytics workloads\\nSET GLOBAL transaction_isolation = 'READ-COMMITTED';\\n\\n-- Persist in my.cnf:\\n-- [mysqld]\\n-- rpl_semi_sync_source_timeout = 10000\\n-- transaction_isolation = READ-COMMITTED  # replica only", "parameters": null, "description": "Adjusts semi-sync timeout and replica isolation level to reduce lock duration conflicts with replication apply"}	{"sql": "SET GLOBAL rpl_semi_sync_source_timeout = 10000;\\nSET GLOBAL transaction_isolation = 'REPEATABLE-READ';", "description": ""}	medium	t	t	5 minutes	2026-03-01 09:33:09.381992
