27368	mysql	execute	mysql_index_rebuild_efficient	{"sql": "-- Use ALGORITHM=INPLACE for index rebuilds to minimize log volume\\n-- INPLACE avoids full table copy and reduces redo/binlog generation\\nALTER TABLE your_schema.large_table\\n  DROP INDEX old_idx,\\n  ADD INDEX new_idx (col1, col2),\\n  ALGORITHM=INPLACE, LOCK=NONE;\\n\\n-- Temporarily increase redo log capacity if rebuild is very large (MySQL 8.0.30+)\\n-- ALTER INSTANCE RESIZE INNODB REDO LOG TO 4*1024*1024*1024; -- 4GB\\n\\n-- Disable binary logging for this session if the table can be reloaded from source\\nSET SESSION sql_log_bin = 0;\\nALTER TABLE your_schema.large_table ADD INDEX idx_new (col3);\\nSET SESSION sql_log_bin = 1;", "parameters": null, "description": "Perform index rebuild using ALGORITHM=INPLACE and optionally skip binary logging to reduce log growth."}	{"sql": "DROP INDEX new_idx ON your_schema.large_table; -- remove new index if needed", "description": ""}	medium	t	t	30+ minutes for large tables	2026-03-01 09:33:09.381992
