27370	mysql	diagnose	mysql_memory_spill_diagnose	{"sql": "-- Check global temporary table spill counters\\nSHOW GLOBAL STATUS LIKE 'Created_tmp%';\\n-- Created_tmp_disk_tables / Created_tmp_tables should be < 10%\\n\\n-- Find queries with most disk temp table usage\\nSELECT DIGEST_TEXT, COUNT_STAR,\\n       SUM_CREATED_TMP_DISK_TABLES,\\n       SUM_SORT_MERGE_PASSES,\\n       ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_sec\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SUM_CREATED_TMP_DISK_TABLES > 0 OR SUM_SORT_MERGE_PASSES > 0\\nORDER BY SUM_CREATED_TMP_DISK_TABLES DESC\\nLIMIT 10;\\n\\n-- Check current memory buffer settings\\nSHOW VARIABLES LIKE 'sort_buffer_size';\\nSHOW VARIABLES LIKE 'join_buffer_size';\\nSHOW VARIABLES LIKE 'tmp_table_size';", "parameters": null, "description": "Identify queries spilling to disk due to insufficient sort and join memory allocations."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27371	mysql	configure	mysql_memory_buffers_tune	{"sql": "-- Increase per-session sort and join buffers\\n-- Note: these are per-connection allocations — multiply by max_connections for total RAM\\nSET GLOBAL sort_buffer_size = 4194304;    -- 4MB (default 256KB)\\nSET GLOBAL join_buffer_size = 4194304;    -- 4MB (default 256KB)\\nSET GLOBAL tmp_table_size = 134217728;    -- 128MB\\nSET GLOBAL max_heap_table_size = 134217728; -- must match tmp_table_size\\n\\n-- Check max_connections to ensure total memory is safe\\nSHOW VARIABLES LIKE 'max_connections';\\n-- Total sort buffer RAM = sort_buffer_size * max_connections\\n-- 4MB * 500 connections = 2GB — ensure this fits available RAM\\n\\n-- Also consider adding indexes to avoid sort operations entirely\\nEXPLAIN SELECT * FROM your_schema.your_table ORDER BY col1, col2;", "parameters": null, "description": "Increase sort, join, and temporary table memory buffers to reduce disk spills."}	{"sql": "SET GLOBAL sort_buffer_size = 262144; SET GLOBAL join_buffer_size = 262144; SET GLOBAL tmp_table_size = 16777216; SET GLOBAL max_heap_table_size = 16777216;", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
