27373	mysql	diagnose	mysql_tmp_table_pattern_identify	{"sql": "-- Find queries creating the most and largest temporary tables\\nSELECT DIGEST_TEXT, COUNT_STAR,\\n       SUM_CREATED_TMP_TABLES, SUM_CREATED_TMP_DISK_TABLES,\\n       ROUND(SUM_ROWS_EXAMINED / NULLIF(COUNT_STAR,0), 0) AS avg_rows_examined\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SUM_CREATED_TMP_TABLES > 0\\nORDER BY SUM_CREATED_TMP_DISK_TABLES DESC\\nLIMIT 15;\\n\\n-- Check current ibtmp1 size\\nSELECT NAME, ROUND(FILE_SIZE / 1024 / 1024, 2) AS size_mb\\nFROM information_schema.INNODB_TABLESPACES\\nWHERE NAME = 'innodb_temporary';\\n\\n-- Check for application-created temp tables\\nSELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE, CREATE_TIME\\nFROM information_schema.TABLES\\nWHERE TABLE_NAME LIKE '%tmp%' OR TABLE_NAME LIKE '%temp%'\\n  AND TABLE_SCHEMA NOT IN ('information_schema','performance_schema','sys','mysql')\\nORDER BY CREATE_TIME DESC\\nLIMIT 20;", "parameters": null, "description": "Identify which queries and application patterns are creating the largest temporary tables."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27374	mysql	execute	mysql_tmp_table_pattern_refactor	{"sql": "-- Option 1: Replace repeated CREATE TEMPORARY TABLE with pre-allocated staging table\\n-- Instead of: CREATE TEMPORARY TABLE tmp_result AS SELECT ...\\n-- Use: TRUNCATE + INSERT\\nCREATE TABLE IF NOT EXISTS your_schema.staging_result LIKE your_schema.source_table;\\nTRUNCATE TABLE your_schema.staging_result;\\nINSERT INTO your_schema.staging_result SELECT * FROM your_schema.source_table WHERE ...;\\n\\n-- Option 2: Rewrite subquery using CTE (avoids temp table in many cases)\\n-- Instead of: SELECT * FROM (SELECT ... FROM big_table) t WHERE t.col = ?\\n-- Use:\\nWITH filtered AS (\\n  SELECT col1, col2 FROM your_schema.big_table WHERE status = 'active'\\n)\\nSELECT * FROM filtered WHERE col1 = 'value';\\n\\n-- Option 3: Add covering index to eliminate temp table for GROUP BY\\nALTER TABLE your_schema.orders ADD INDEX idx_status_date (status, order_date, amount);", "parameters": null, "description": "Refactor high-frequency temporary table patterns to use pre-allocated staging tables, CTEs, or covering indexes."}	{"sql": "DROP TABLE IF EXISTS your_schema.staging_result; -- remove staging table if approach abandoned", "description": ""}	low	f	t	30 minutes	2026-03-01 09:33:09.381992
27375	mysql	verify	mysql_tmp_pattern_verify	{"sql": "-- Verify reduction in disk-based temp tables\\nFLUSH STATUS;\\n-- Run application workload, then:\\nSHOW GLOBAL STATUS LIKE 'Created_tmp%';\\n\\n-- Confirm ibtmp1 size is stable\\nSELECT NAME, ROUND(FILE_SIZE / 1024 / 1024, 2) AS size_mb\\nFROM information_schema.INNODB_TABLESPACES\\nWHERE NAME = 'innodb_temporary';\\n\\n-- Verify new queries have improved plans\\nEXPLAIN SELECT col1, col2 FROM your_schema.big_table WHERE status = 'active';", "parameters": null, "description": "Confirm temporary table creation rates have decreased and query plans have improved."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
31908	mariadb	diagnose	mysql_assess_clustered_index_fragmentation	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.STAT_VALUE AS pages, ROUND(s.STAT_VALUE * @@innodb_page_size / 1048576, 2) AS size_mb FROM mysql.innodb_index_stats s WHERE s.stat_name = 'size' AND s.INDEX_NAME = 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'performance_schema') ORDER BY s.STAT_VALUE DESC LIMIT 20;\\n\\nSELECT TABLE_SCHEMA, TABLE_NAME, DATA_LENGTH, DATA_FREE, INDEX_LENGTH, TABLE_ROWS FROM information_schema.TABLES WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND DATA_FREE > 52428800 ORDER BY DATA_FREE DESC LIMIT 20;", "parameters": null, "description": "Assess clustered index fragmentation by examining primary index page counts and DATA_FREE metrics."}	\N	low	f	t	2 minutes	2026-05-11 22:17:39.229791
27377	mysql	configure	mysql_binlog_retention_set	{"sql": "-- Set appropriate binary log expiry (e.g., 7 days)\\nSET GLOBAL binlog_expire_logs_seconds = 604800; -- 7 days\\n\\n-- Verify replica has consumed logs before purging\\nSHOW REPLICA STATUS\\\\G\\n-- Confirm Relay_Source_Log_File and check all replicas\\n\\n-- Manually purge binary logs already consumed by all replicas\\nPURGE BINARY LOGS BEFORE DATE_SUB(NOW(), INTERVAL 7 DAY);\\n\\n-- Tune sync_binlog for I/O performance (1 = safest, 0 = fastest)\\n-- For I/O-sensitive workloads, consider:\\nSHOW VARIABLES LIKE 'sync_binlog';\\n-- SET GLOBAL sync_binlog = 100; -- sync every 100 commits (faster, slightly less durable)", "parameters": null, "description": "Configure binary log expiry and purge accumulated logs that exceed the retention window."}	{"sql": "SET GLOBAL binlog_expire_logs_seconds = 2592000; -- restore 30-day default", "description": ""}	medium	t	f	10 minutes	2026-03-01 09:33:09.381992
