27379	mysql	diagnose	mysql_concurrent_growth_diagnose	{"sql": "-- Check I/O wait statistics to identify simultaneous growth\\nSELECT * FROM sys.io_global_by_file_by_latency\\nORDER BY total_latency DESC\\nLIMIT 15;\\n\\n-- Check which tables are growing most rapidly (compare at intervals)\\nSELECT TABLE_SCHEMA, TABLE_NAME,\\n       ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb,\\n       ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb\\nFROM information_schema.TABLES\\nWHERE TABLE_SCHEMA NOT IN ('information_schema','performance_schema','sys','mysql')\\n  AND DATA_FREE < 10485760 -- tables with less than 10MB free (about to grow)\\nORDER BY DATA_LENGTH DESC\\nLIMIT 20;\\n\\n-- Check innodb_autoextend_increment setting\\nSHOW VARIABLES LIKE 'innodb_autoextend_increment';", "parameters": null, "description": "Identify multiple tables simultaneously nearing their growth threshold and the resulting I/O impact."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27380	mysql	configure	mysql_tablespace_presize	{"sql": "-- Pre-extend large tables to reduce imminent growth events\\n-- This rebuilds the table with extra space pre-allocated\\nOPTIMIZE TABLE your_schema.large_table_1;\\nOPTIMIZE TABLE your_schema.large_table_2;\\n\\n-- Alternatively, pre-insert and delete dummy rows to force pre-extension\\n-- (not recommended for production — use OPTIMIZE TABLE instead)\\n\\n-- Increase autoextend increment to reduce growth event frequency\\nSET GLOBAL innodb_autoextend_increment = 512; -- 512MB\\n\\n-- Consider combining small tables into partitioned tables to reduce file count\\n-- This reduces the number of concurrent growth events\\nSHOW VARIABLES LIKE 'innodb_file_per_table';", "parameters": null, "description": "Pre-size tables approaching growth threshold and increase the extension increment to reduce growth event frequency."}	{"sql": "SET GLOBAL innodb_autoextend_increment = 64; -- restore default", "description": ""}	medium	f	t	20 minutes	2026-03-01 09:33:09.381992
27381	mysql	verify	mysql_concurrent_growth_verify	{"sql": "-- Verify I/O wait times have improved\\nSELECT * FROM sys.io_global_by_file_by_latency\\nORDER BY total_latency DESC\\nLIMIT 10;\\n\\n-- Confirm tables now have adequate free space (not about to trigger growth)\\nSELECT TABLE_SCHEMA, TABLE_NAME,\\n       ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb\\nFROM information_schema.TABLES\\nWHERE TABLE_SCHEMA NOT IN ('information_schema','performance_schema','sys','mysql')\\n  AND DATA_FREE < 10485760\\nORDER BY DATA_LENGTH DESC\\nLIMIT 10;\\n\\n-- Check autoextend increment\\nSHOW VARIABLES LIKE 'innodb_autoextend_increment';", "parameters": null, "description": "Confirm I/O latency from concurrent file growth has decreased and tables have adequate free space buffer."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27382	mysql	diagnose	mysql_file_fragmentation_check	{"sql": "-- Check current tablespace file sizes and free space ratio\\nSELECT NAME,\\n       ROUND(FILE_SIZE / 1024 / 1024, 2) AS file_mb,\\n       ROUND(ALLOCATED_SIZE / 1024 / 1024, 2) AS allocated_mb\\nFROM information_schema.INNODB_TABLESPACES\\nORDER BY FILE_SIZE DESC\\nLIMIT 20;\\n\\n-- Check table-level fragmentation\\nSELECT TABLE_SCHEMA, TABLE_NAME,\\n       ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb,\\n       ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb,\\n       ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 1) AS frag_pct\\nFROM information_schema.TABLES\\nWHERE TABLE_SCHEMA NOT IN ('information_schema','performance_schema','sys','mysql')\\n  AND DATA_FREE > 0\\nORDER BY frag_pct DESC\\nLIMIT 20;\\n\\n-- Current autoextend increment\\nSHOW VARIABLES LIKE 'innodb_autoextend_increment';", "parameters": null, "description": "Identify highly fragmented InnoDB tablespace files and tables with high free space ratios."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27383	mysql	execute	mysql_tablespace_defrag_rebuild	{"sql": "-- Rebuild most fragmented tables to compact pages and reduce OS fragmentation\\n-- OPTIMIZE TABLE rewrites the .ibd file contiguously\\nOPTIMIZE TABLE your_schema.fragmented_table_1;\\nOPTIMIZE TABLE your_schema.fragmented_table_2;\\n\\n-- After rebuilding, increase autoextend increment to prevent rapid re-fragmentation\\nSET GLOBAL innodb_autoextend_increment = 256;\\n\\n-- For the largest tables, consider pt-online-schema-change to rebuild without locking:\\n-- pt-online-schema-change --alter 'ENGINE=InnoDB' D=your_schema,t=large_table --execute\\n\\n-- Check OS-level disk fragmentation after rebuild (from OS shell):\\n-- filefrag -v /var/lib/mysql/your_schema/fragmented_table.ibd", "parameters": null, "description": "Rebuild fragmented tables to compact and defragment .ibd files, then configure larger extension increments."}	\N	medium	t	f	30+ minutes for large tables	2026-03-01 09:33:09.381992
27384	mysql	verify	mysql_fragmentation_verify	{"sql": "-- Verify fragmentation reduced\\nSELECT TABLE_SCHEMA, TABLE_NAME,\\n       ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb,\\n       ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb,\\n       ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 1) AS frag_pct\\nFROM information_schema.TABLES\\nWHERE TABLE_SCHEMA NOT IN ('information_schema','performance_schema','sys','mysql')\\nORDER BY frag_pct DESC\\nLIMIT 10;\\n\\n-- Confirm larger autoextend increment is active\\nSHOW VARIABLES LIKE 'innodb_autoextend_increment';\\n\\n-- Monitor I/O read performance improvement\\nSELECT * FROM sys.io_global_by_file_by_latency\\nORDER BY total_latency DESC\\nLIMIT 10;", "parameters": null, "description": "Confirm table fragmentation percentages have decreased and I/O latency has improved."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27385	mysql	diagnose	mysql_autogrowth_timeout_diagnose	{"sql": "-- Check InnoDB wait statistics for file I/O\\nSELECT EVENT_NAME, COUNT_STAR,\\n       ROUND(SUM_TIMER_WAIT / 1000000000000, 3) AS total_sec,\\n       ROUND(MAX_TIMER_WAIT / 1000000000000, 3) AS max_sec\\nFROM performance_schema.events_waits_summary_global_by_event_name\\nWHERE EVENT_NAME LIKE '%innodb%' OR EVENT_NAME LIKE '%file%extend%'\\nORDER BY SUM_TIMER_WAIT DESC\\nLIMIT 15;\\n\\n-- Check pending I/O operations\\nSHOW ENGINE INNODB STATUS\\\\G\\n-- Look for 'Pending normal aio reads', 'ibuf aio reads', 'log i/o writes'\\n\\n-- Check InnoDB I/O capacity settings\\nSHOW VARIABLES LIKE 'innodb_io_capacity%';\\nSHOW VARIABLES LIKE 'innodb_flush_method';", "parameters": null, "description": "Identify I/O contention and pending operations causing tablespace extension timeouts."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27386	mysql	configure	mysql_io_contention_resolve	{"sql": "-- Tune InnoDB I/O capacity to match storage capabilities\\n-- For SSD: set higher values\\nSET GLOBAL innodb_io_capacity = 2000;\\nSET GLOBAL innodb_io_capacity_max = 4000;\\n\\n-- Use O_DIRECT to bypass OS cache (reduces double-buffering on Linux)\\n-- Requires restart: innodb_flush_method = O_DIRECT\\nSHOW VARIABLES LIKE 'innodb_flush_method';\\n\\n-- Pre-size tables to avoid auto-growth during peak traffic\\n-- Rebuild key tables during maintenance window\\nOPTIMIZE TABLE your_schema.high_traffic_table;\\n\\n-- Increase innodb_autoextend_increment to grow less frequently\\nSET GLOBAL innodb_autoextend_increment = 512; -- 512MB\\n\\n-- Check for long-running transactions blocking file operations\\nSELECT TRX_ID, TRX_STARTED, TRX_TABLES_IN_USE\\nFROM information_schema.INNODB_TRX\\nORDER BY TRX_STARTED\\nLIMIT 10;", "parameters": null, "description": "Tune InnoDB I/O settings and pre-size tablespaces to prevent auto-growth stalls during peak load."}	{"sql": "SET GLOBAL innodb_io_capacity = 200; SET GLOBAL innodb_autoextend_increment = 64; -- restore defaults", "description": ""}	medium	f	t	15 minutes	2026-03-01 09:33:09.381992
