27388	mysql	diagnose	mysql_ibtmp1_spill_diagnose	{"sql": "-- Check current ibtmp1 size\\nSELECT NAME, ROUND(FILE_SIZE / 1024 / 1024, 2) AS size_mb\\nFROM information_schema.INNODB_TABLESPACES\\nWHERE NAME = 'innodb_temporary';\\n\\n-- Find queries generating disk temp tables\\nSELECT DIGEST_TEXT, COUNT_STAR,\\n       SUM_CREATED_TMP_DISK_TABLES,\\n       SUM_SORT_MERGE_PASSES,\\n       ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_sec\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SUM_CREATED_TMP_DISK_TABLES > 0 OR SUM_SORT_MERGE_PASSES > 0\\nORDER BY SUM_CREATED_TMP_DISK_TABLES DESC\\nLIMIT 10;\\n\\n-- Check memory settings\\nSHOW VARIABLES LIKE 'tmp_table_size';\\nSHOW VARIABLES LIKE 'max_heap_table_size';\\nSHOW VARIABLES LIKE 'sort_buffer_size';\\nSHOW VARIABLES LIKE 'join_buffer_size';", "parameters": null, "description": "Identify queries causing ibtmp1 growth through sort and hash spills."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27389	mysql	configure	mysql_ibtmp1_memory_tune	{"sql": "-- Increase in-memory temp table limits\\nSET GLOBAL tmp_table_size = 268435456;    -- 256MB\\nSET GLOBAL max_heap_table_size = 268435456; -- must match\\nSET GLOBAL sort_buffer_size = 8388608;    -- 8MB\\nSET GLOBAL join_buffer_size = 8388608;    -- 8MB\\n\\n-- Cap ibtmp1 size to prevent runaway growth\\n-- Requires my.cnf restart:\\n-- innodb_temp_data_file_path = ibtmp1:12M:autoextend:max:10G\\nSHOW VARIABLES LIKE 'innodb_temp_data_file_path';\\n\\n-- Use hash join (MySQL 8.0+) instead of nested loop for equi-joins\\nSET SESSION optimizer_switch = 'hash_join=on';\\nSHOW VARIABLES LIKE 'optimizer_switch';", "parameters": null, "description": "Increase memory allocations for temporary tables and enable hash join to reduce spills."}	{"sql": "SET GLOBAL tmp_table_size = 16777216; SET GLOBAL max_heap_table_size = 16777216; SET GLOBAL sort_buffer_size = 262144; SET GLOBAL join_buffer_size = 262144;", "description": ""}	low	f	t	5 minutes	2026-03-01 09:33:09.381992
