27639	mysql	diagnose	mysql_identify_dynamic_sql_patterns	{"sql": "-- Find queries with many variations (low reuse = dynamic SQL)\\nSELECT LEFT(DIGEST_TEXT, 120) AS query_prefix,\\n       COUNT_STAR, SUM_TIMER_WAIT/1e12 AS total_sec\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND COUNT_STAR < 3\\nORDER BY SUM_TIMER_WAIT DESC\\nLIMIT 30;\\n\\n-- Count digest table saturation\\nSELECT COUNT(*) AS digest_count,\\n       (SELECT VARIABLE_VALUE FROM performance_schema.global_variables\\n        WHERE VARIABLE_NAME='performance_schema_digests_size') AS digest_table_size\\nFROM performance_schema.events_statements_summary_by_digest;", "parameters": null, "description": "Identify single-execution queries that indicate dynamic SQL string concatenation"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27640	mysql	diagnose	mysql_trace_dynamic_sql_source	{"sql": "-- Check stored procedures using dynamic SQL (PREPARE/EXECUTE)\\nSELECT ROUTINE_SCHEMA, ROUTINE_NAME, ROUTINE_TYPE,\\n       LOCATE('PREPARE', ROUTINE_DEFINITION) AS has_prepare,\\n       LOCATE('CONCAT', ROUTINE_DEFINITION) AS has_concat\\nFROM information_schema.ROUTINES\\nWHERE ROUTINE_SCHEMA = DATABASE()\\n  AND (ROUTINE_DEFINITION LIKE '%PREPARE%' OR ROUTINE_DEFINITION LIKE '%CONCAT%')\\nORDER BY ROUTINE_NAME;\\n\\n-- Check connection attributes for application identification\\nSELECT attr_name, attr_value, COUNT(*) AS conn_count\\nFROM performance_schema.session_connect_attrs\\nWHERE attr_name IN ('program_name','_client_name')\\nGROUP BY attr_name, attr_value;", "parameters": null, "description": "Locate stored procedures using dynamic PREPARE/EXECUTE patterns and identify application sources"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
