27643	mysql	diagnose	mysql_identify_cross_app_query_duplication	{"sql": "-- Find similar query patterns from different connection sources\\nSELECT LEFT(DIGEST_TEXT, 100) AS query_pattern,\\n       COUNT(*) AS variant_count,\\n       SUM(COUNT_STAR) AS total_executions\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\nGROUP BY LEFT(DIGEST_TEXT, 100)\\nHAVING variant_count > 1\\nORDER BY variant_count DESC LIMIT 20;\\n\\n-- Identify which client programs generate the most unique queries\\nSELECT attr_value AS app_name, COUNT(DISTINCT c.THREAD_ID) AS connections\\nFROM performance_schema.session_connect_attrs a\\nJOIN performance_schema.threads c ON a.PROCESSLIST_ID = c.PROCESSLIST_ID\\nWHERE attr_name = 'program_name'\\nGROUP BY attr_value ORDER BY connections DESC;", "parameters": null, "description": "Identify duplicate query patterns and the client applications generating them"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
