27647	mysql	diagnose	mysql_find_non_parameterized_queries	{"sql": "-- Find queries with literals remaining after digest normalization\\n-- (should show ? in normalized form; if not, parameterization failed)\\nSELECT DIGEST_TEXT, COUNT_STAR,\\n       ROUND(SUM_TIMER_WAIT/1e12, 3) AS total_sec\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND DIGEST_TEXT NOT LIKE '%?%'  -- literals not normalized\\n  AND COUNT_STAR < 10\\nORDER BY SUM_TIMER_WAIT DESC\\nLIMIT 20;\\n\\n-- Also check for IN() lists which often bypass normalization\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND DIGEST_TEXT LIKE '%IN (%,%,%)\\n%'\\nORDER BY COUNT_STAR ASC LIMIT 10;", "parameters": null, "description": "Find queries where MySQL digest normalization failed to replace literals with ? placeholders"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27648	mysql	diagnose	mysql_identify_parameterization_failure_types	{"sql": "-- Check for IN() list variability (common parameterization failure)\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND DIGEST_TEXT LIKE '%IN (?,?,?%'\\nORDER BY COUNT_STAR DESC LIMIT 10;\\n\\n-- Check for LIMIT clause variations\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND DIGEST_TEXT LIKE '%LIMIT ?%'\\nORDER BY COUNT_STAR DESC LIMIT 10;\\n\\n-- Check statement count per type\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN ('Com_select','Com_insert','Com_update','Com_delete','Questions');", "parameters": null, "description": "Categorize parameterization failures by query pattern type to prioritize refactoring effort"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27649	mysql	execute	mysql_apply_explicit_parameterization	{"sql": "-- For IN() list variations, use temporary table pattern instead:\\n-- CREATE TEMPORARY TABLE tmp_ids (id INT);\\n-- INSERT INTO tmp_ids VALUES (1),(2),(3);  -- variable number\\n-- SELECT * FROM orders WHERE customer_id IN (SELECT id FROM tmp_ids);\\n-- DROP TEMPORARY TABLE tmp_ids;\\n\\n-- Or use find_in_set for small sets:\\n-- SELECT * FROM orders WHERE FIND_IN_SET(customer_id, ?) > 0;\\n\\n-- For complex CASE expressions, consider stored procedures:\\n-- DELIMITER //\\n-- CREATE PROCEDURE get_orders(IN p_status VARCHAR(50))\\n-- BEGIN\\n--   SELECT * FROM orders WHERE status = p_status;\\n-- END //\\n-- DELIMITER ;\\n\\n-- Check current procedure count\\nSELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = DATABASE();", "parameters": null, "description": "Refactor problematic query patterns to use explicit parameterization or procedure wrappers"}	\N	medium	t	t	20 minutes	2026-03-01 09:33:09.381992
