27651	mysql	diagnose	mysql_quantify_one_time_queries	{"sql": "-- Measure proportion of one-time queries\\nSELECT\\n  SUM(CASE WHEN COUNT_STAR = 1 THEN 1 ELSE 0 END) AS one_time_queries,\\n  SUM(CASE WHEN COUNT_STAR > 1 THEN 1 ELSE 0 END) AS reused_queries,\\n  COUNT(*) AS total_digests,\\n  ROUND(SUM(CASE WHEN COUNT_STAR = 1 THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS one_time_pct\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE();\\n\\n-- Find one-time query patterns (likely OLAP)\\nSELECT LEFT(DIGEST_TEXT, 120) AS query_prefix,\\n       ROUND(SUM_TIMER_WAIT/1e12, 3) AS total_sec\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE COUNT_STAR = 1 AND SCHEMA_NAME = DATABASE()\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 20;", "parameters": null, "description": "Quantify the proportion of one-time queries and identify the reporting/OLAP sources"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27652	mysql	configure	mysql_isolate_olap_connections	{"sql": "-- Route OLAP to read replicas via ProxySQL or application-level routing\\n-- Check current replication topology\\nSHOW REPLICA STATUS\\\\G\\n\\n-- For single-server: use resource groups to limit OLAP thread priority\\nCREATE RESOURCE GROUP IF NOT EXISTS olap_group\\n  TYPE = USER\\n  VCPU = 0, 1\\n  THREAD_PRIORITY = 19;\\n\\n-- Assign OLAP connections to low-priority group\\n-- (Execute from application or ProxySQL)\\n-- SET RESOURCE GROUP olap_group;\\n\\nSELECT * FROM information_schema.RESOURCE_GROUPS;", "parameters": null, "description": "Isolate OLAP workloads using resource groups or replica routing to protect OLTP plan cache"}	{"sql": "DROP RESOURCE GROUP olap_group;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
27653	mysql	configure	mysql_tune_digest_table_size	{"sql": "-- Check if digest table is saturated (NULL schema = overflow)\\nSELECT COUNT(*) AS null_schema_count\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME IS NULL;\\n\\n-- Increase digest table size if saturated (requires restart, add to my.cnf):\\n-- performance_schema_digests_size=20000  (default 10000)\\n\\n-- Current size setting\\nSELECT VARIABLE_VALUE FROM performance_schema.global_variables\\nWHERE VARIABLE_NAME = 'performance_schema_digests_size';\\n\\n-- Periodically purge old one-time digests\\n-- TRUNCATE performance_schema.events_statements_summary_by_digest;", "parameters": null, "description": "Expand digest table size to prevent saturation from one-time queries evicting OLTP plan data"}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
