27655	mysql	diagnose	mysql_detect_dynamic_procedure_creation	{"sql": "-- Check for frequent CREATE/DROP PROCEDURE activity\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE DIGEST_TEXT LIKE '%CREATE%PROCEDURE%'\\n   OR DIGEST_TEXT LIKE '%DROP%PROCEDURE%'\\nORDER BY COUNT_STAR DESC LIMIT 20;\\n\\n-- Check current stored procedure count and recent changes\\nSELECT ROUTINE_SCHEMA, COUNT(*) AS proc_count,\\n       MAX(LAST_ALTERED) AS last_modified\\nFROM information_schema.ROUTINES\\nWHERE ROUTINE_TYPE = 'PROCEDURE'\\nGROUP BY ROUTINE_SCHEMA\\nORDER BY proc_count DESC;", "parameters": null, "description": "Detect frequent CREATE/DROP PROCEDURE activity that causes plan cache churn"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27656	mysql	diagnose	mysql_identify_transient_routines	{"sql": "-- Check Com_create_procedure and Com_drop_procedure rates\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN ('Com_create_procedure','Com_drop_procedure',\\n  'Com_create_function','Com_drop_function');\\n\\n-- Find procedures created after server start (transient ones)\\nSELECT ROUTINE_NAME, CREATED, LAST_ALTERED, ROUTINE_DEFINITION\\nFROM information_schema.ROUTINES\\nWHERE ROUTINE_SCHEMA = DATABASE()\\n  AND CREATED > (SELECT FROM_UNIXTIME(UNIX_TIMESTAMP() - @@global.uptime))\\nORDER BY CREATED DESC LIMIT 20;", "parameters": null, "description": "Measure routine creation rate and find procedures created since server startup"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27657	mysql	execute	mysql_convert_to_persistent_procedures	{"sql": "-- Create persistent parameterized procedures to replace dynamic ones\\n-- Example pattern:\\nDELIMITER //\\nCREATE PROCEDURE IF NOT EXISTS execute_parameterized_query(\\n  IN p_table_name VARCHAR(64),\\n  IN p_filter_value VARCHAR(255)\\n)\\nBEGIN\\n  -- Use fixed-structure queries with parameters\\n  SELECT * FROM information_schema.TABLES\\n  WHERE TABLE_NAME = p_table_name\\n    AND TABLE_SCHEMA = DATABASE();\\nEND //\\nDELIMITER ;\\n\\n-- Verify procedure created\\nSELECT ROUTINE_NAME, ROUTINE_TYPE, CREATED\\nFROM information_schema.ROUTINES\\nWHERE ROUTINE_SCHEMA = DATABASE()\\nORDER BY CREATED DESC LIMIT 10;", "parameters": null, "description": "Create persistent stored procedures with proper parameterization to replace dynamic routine creation"}	{"sql": "DROP PROCEDURE IF EXISTS execute_parameterized_query;", "description": ""}	low	f	t	15 minutes	2026-03-01 09:33:09.381992
27658	mysql	verify	mysql_verify_procedure_creation_rate_reduced	{"sql": "-- Verify routine creation rate has dropped\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN ('Com_create_procedure','Com_drop_procedure');\\n\\n-- Verify plan cache has stable digests now\\nSELECT COUNT(*) AS unique_digests,\\n       ROUND(AVG(COUNT_STAR), 2) AS avg_reuse\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE();\\n\\n-- Confirm CREATE PROCEDURE no longer in top digests\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE DIGEST_TEXT LIKE '%CREATE%PROCEDURE%'\\nORDER BY COUNT_STAR DESC LIMIT 5;", "parameters": null, "description": "Confirm dynamic procedure creation has stopped and plan cache now has stable high-reuse entries"}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27659	mysql	diagnose	mysql_identify_third_party_query_source	{"sql": "-- Identify application sources generating bad queries\\nSELECT\\n  attr_value AS application,\\n  COUNT(DISTINCT d.DIGEST) AS unique_digests\\nFROM performance_schema.session_connect_attrs a\\nJOIN performance_schema.threads t ON a.PROCESSLIST_ID = t.PROCESSLIST_ID\\nJOIN performance_schema.events_statements_summary_by_digest d\\n  ON d.SCHEMA_NAME = t.PROCESSLIST_DB\\nWHERE a.attr_name = 'program_name'\\nGROUP BY attr_value\\nORDER BY unique_digests DESC;\\n\\n-- Top queries from the problematic application\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND COUNT_STAR < 5\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 20;", "parameters": null, "description": "Identify which third-party application generates the most unique non-parameterized queries"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27660	mysql	configure	mysql_deploy_proxysql_normalization	{"sql": "-- ProxySQL query normalization for third-party apps (run on ProxySQL admin port 6032)\\n-- Add query rewrite rule to normalize common patterns:\\n-- INSERT INTO mysql_query_rules (rule_id, active, match_digest,\\n--   replace_pattern, apply) VALUES\\n--   (100, 1, '^SELECT .* FROM orders WHERE id = [0-9]+',\\n--    'SELECT * FROM orders WHERE id = ?', 1);\\n-- LOAD MYSQL QUERY RULES TO RUNTIME;\\n-- SAVE MYSQL QUERY RULES TO DISK;\\n\\n-- On MySQL: verify query digest pattern to build ProxySQL rule\\nSELECT DIGEST, DIGEST_TEXT\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 10;", "parameters": null, "description": "Deploy ProxySQL query rewriting rules to normalize third-party application queries transparently"}	\N	medium	t	t	20 minutes	2026-03-01 09:33:09.381992
