27663	mysql	diagnose	mysql_identify_cursor_loop_queries	{"sql": "-- Find similar low-reuse queries that indicate loop iteration\\nSELECT LEFT(DIGEST_TEXT, 150) AS query_pattern,\\n       COUNT(*) AS digest_variants,\\n       SUM(COUNT_STAR) AS total_executions\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\nGROUP BY LEFT(DIGEST_TEXT, 150)\\nHAVING digest_variants > 1\\nORDER BY digest_variants DESC LIMIT 20;\\n\\n-- Check stored procedures that use cursors\\nSELECT ROUTINE_NAME, LOCATE('CURSOR', ROUTINE_DEFINITION) AS has_cursor\\nFROM information_schema.ROUTINES\\nWHERE ROUTINE_SCHEMA = DATABASE()\\n  AND ROUTINE_DEFINITION LIKE '%CURSOR%'\\nORDER BY ROUTINE_NAME;", "parameters": null, "description": "Identify loop-based query patterns generating multiple similar digest entries"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
27664	mysql	diagnose	mysql_analyze_loop_procedure_logic	{"sql": "-- Review specific procedure using cursor pattern\\nSELECT ROUTINE_NAME, ROUTINE_DEFINITION\\nFROM information_schema.ROUTINES\\nWHERE ROUTINE_SCHEMA = DATABASE()\\n  AND ROUTINE_DEFINITION LIKE '%CURSOR%'\\nORDER BY ROUTINE_NAME\\nLIMIT 5;\\n\\n-- Check if CURSOR usage correlates with slow queries\\nSELECT d.DIGEST_TEXT, d.COUNT_STAR, d.SUM_TIMER_WAIT/1e12 AS total_sec\\nFROM performance_schema.events_statements_summary_by_digest d\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND COUNT_STAR BETWEEN 1 AND 10\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 20;", "parameters": null, "description": "Review cursor-based stored procedure logic to design set-based replacement queries"}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27665	mysql	execute	mysql_refactor_loops_to_set_based	{"sql": "-- BEFORE: Cursor loop pattern (row-by-row, creates many digest variants)\\n-- DECLARE cur CURSOR FOR SELECT id FROM orders WHERE status='pending';\\n-- FETCH cur INTO v_id;\\n-- UPDATE orders SET processed=1 WHERE id=v_id;  -- separate query per row!\\n\\n-- AFTER: Set-based (single query, one plan, always parameterized)\\n-- UPDATE orders SET processed=1 WHERE status='pending';\\n\\n-- For complex cursor logic, use INSERT...SELECT pattern:\\n-- INSERT INTO processed_orders (order_id, processed_at)\\n-- SELECT id, NOW() FROM orders WHERE status='pending';\\n\\n-- Verify changes with EXPLAIN\\n-- EXPLAIN UPDATE orders SET processed=1 WHERE status='pending';", "parameters": null, "description": "Replace row-by-row cursor loops with set-based SQL operations to eliminate per-row query variants"}	\N	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
27666	mysql	verify	mysql_verify_loop_elimination	{"sql": "-- Verify digest count reduced after cursor elimination\\nSELECT COUNT(*) AS unique_digests,\\n       ROUND(AVG(COUNT_STAR), 2) AS avg_reuse\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE();\\n\\n-- Confirm loop queries no longer appear as low-reuse digests\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND COUNT_STAR < 5\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 10;\\n\\n-- Verify set-based replacement has high reuse\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\nORDER BY COUNT_STAR DESC LIMIT 10;", "parameters": null, "description": "Confirm cursor loop queries have been replaced by high-reuse set-based queries in the digest table"}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
27667	mysql	diagnose	mysql_identify_idle_blocking_sessions	{"sql": "-- Find idle sessions with open transactions\\nSELECT p.ID AS thread_id, p.USER, p.HOST, p.DB,\\n       p.COMMAND, p.TIME AS idle_seconds, p.STATE,\\n       t.trx_id, t.trx_started\\nFROM information_schema.PROCESSLIST p\\nJOIN information_schema.INNODB_TRX t ON t.trx_mysql_thread_id = p.ID\\nWHERE p.COMMAND = 'Sleep'\\n  AND p.TIME > 60  -- idle for more than 60 seconds\\nORDER BY p.TIME DESC;\\n\\n-- Check if wait_timeout is set appropriately\\nSHOW VARIABLES LIKE 'wait_timeout';\\nSHOW VARIABLES LIKE 'interactive_timeout';", "parameters": null, "description": "Find idle sleeping connections that have open transactions blocking purge thread progress"}	\N	low	f	t	2 minutes	2026-03-01 09:33:09.381992
27668	mysql	execute	mysql_kill_idle_transactions	{"sql": "-- Kill idle sessions with long-running transactions\\n-- Replace thread_ids with actual values from step 2\\n-- KILL CONNECTION <thread_id>;\\n\\n-- Generate KILL statements for all idle transactions > 5 minutes\\nSELECT CONCAT('KILL CONNECTION ', p.ID, ';') AS kill_stmt,\\n       p.USER, p.TIME AS idle_seconds, t.trx_started\\nFROM information_schema.PROCESSLIST p\\nJOIN information_schema.INNODB_TRX t ON t.trx_mysql_thread_id = p.ID\\nWHERE p.COMMAND = 'Sleep' AND p.TIME > 300\\nORDER BY p.TIME DESC;\\n\\n-- Set wait_timeout to auto-kill future idle connections\\nSET GLOBAL wait_timeout = 300;      -- 5 minutes\\nSET GLOBAL interactive_timeout = 300;", "parameters": null, "description": "Terminate idle transactions blocking InnoDB purge and configure timeout to prevent recurrence"}	{"sql": "SET GLOBAL wait_timeout = 28800; SET GLOBAL interactive_timeout = 28800;", "description": ""}	medium	t	f	5 minutes	2026-03-01 09:33:09.381992
27669	mysql	diagnose	mysql_measure_purge_lag	{"sql": "-- Check InnoDB purge lag (history list length)\\nSELECT NAME, COUNT FROM information_schema.INNODB_METRICS\\nWHERE NAME IN ('trx_rseg_history_len','innodb_purge_trx_id_age',\\n               'buffer_pool_pages_dirty','innodb_data_writes')\\nORDER BY NAME;\\n\\n-- Check write rate to quantify DELETE/UPDATE pressure\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN ('Com_delete','Com_update','Com_insert',\\n  'Innodb_rows_deleted','Innodb_rows_updated','Innodb_rows_inserted');\\n\\n-- Check current purge thread configuration\\nSHOW VARIABLES LIKE 'innodb_purge_threads';\\nSHOW VARIABLES LIKE 'innodb_max_purge_lag%';", "parameters": null, "description": "Measure InnoDB purge backlog and write rates to quantify the cleanup deficit"}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
