28251	mysql	diagnose	mysql_diagnose_stale_index_distribution	{"sql": "-- Compare current cardinality with table row count\\nSELECT s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS,\\n  ROUND(s.CARDINALITY * 100.0 / NULLIF(t.TABLE_ROWS, 0), 2) AS selectivity_pct\\nFROM information_schema.STATISTICS s\\nJOIN information_schema.TABLES t\\n  ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME\\nWHERE s.TABLE_SCHEMA = DATABASE()\\n  AND t.TABLE_ROWS > 10000\\n  AND s.SEQ_IN_INDEX = 1\\nORDER BY selectivity_pct ASC\\nLIMIT 20;\\n\\n-- Identify indexes with high full-scan proportion\\nSELECT OBJECT_NAME, INDEX_NAME, COUNT_FETCH\\nFROM performance_schema.table_io_waits_summary_by_index_usage\\nWHERE OBJECT_SCHEMA = DATABASE() AND COUNT_FETCH = 0\\nORDER BY OBJECT_NAME;", "parameters": null, "description": "Identify indexes with selectivity that became poor as table data grew and distribution shifted."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
