28274	mysql	diagnose	mysql_diagnose_overlapping_composite_indexes	{"sql": "-- List all composite indexes with their column order\\nSELECT TABLE_NAME, INDEX_NAME,\\n  GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX SEPARATOR ', ') AS columns\\nFROM information_schema.STATISTICS\\nWHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'your_table'\\nGROUP BY TABLE_NAME, INDEX_NAME\\nHAVING COUNT(*) > 1\\nORDER BY INDEX_NAME;\\n\\n-- Identify overlapping indexes: (A,B) is made redundant by (A,B,C)\\n-- Check if index A,B prefix is covered by index A,B,C\\nSELECT a.INDEX_NAME AS redundant, b.INDEX_NAME AS superseded_by\\nFROM (\\n  SELECT INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols\\n  FROM information_schema.STATISTICS\\n  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'your_table'\\n  GROUP BY INDEX_NAME\\n) a\\nJOIN (\\n  SELECT INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols\\n  FROM information_schema.STATISTICS\\n  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'your_table'\\n  GROUP BY INDEX_NAME\\n) b ON b.cols LIKE CONCAT(a.cols, '%') AND a.INDEX_NAME <> b.INDEX_NAME;", "parameters": null, "description": "Identify composite indexes where one index is a prefix of another, making the shorter one redundant."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
