28286	mysql	diagnose	mysql_diagnose_unused_fk_indexes	{"sql": "-- List all foreign key indexes\\nSELECT kcu.TABLE_NAME, kcu.COLUMN_NAME, kcu.CONSTRAINT_NAME,\\n  kcu.REFERENCED_TABLE_NAME, kcu.REFERENCED_COLUMN_NAME\\nFROM information_schema.KEY_COLUMN_USAGE kcu\\nJOIN information_schema.TABLE_CONSTRAINTS tc\\n  ON kcu.TABLE_NAME = tc.TABLE_NAME\\n  AND kcu.CONSTRAINT_NAME = tc.CONSTRAINT_NAME\\n  AND tc.CONSTRAINT_TYPE = 'FOREIGN KEY'\\nWHERE kcu.TABLE_SCHEMA = DATABASE();\\n\\n-- Cross-reference with index usage\\nSELECT p.OBJECT_NAME, p.INDEX_NAME, p.COUNT_FETCH\\nFROM performance_schema.table_io_waits_summary_by_index_usage p\\nWHERE p.OBJECT_SCHEMA = DATABASE()\\n  AND p.COUNT_FETCH = 0\\n  AND p.INDEX_NAME IS NOT NULL;", "parameters": null, "description": "Identify FK-backed indexes with zero read activity that indicate the FK relationship is never queried directly."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
28287	mysql	execute	mysql_remove_unused_fk_indexes	{"sql": "-- IMPORTANT: MySQL requires index on FK column for constraint enforcement\\n-- To remove a FK index, you must first drop the FK constraint (or disable FK checks)\\n\\n-- Option A: Drop FK constraint and its index if the relationship is rarely enforced\\nSET FOREIGN_KEY_CHECKS = 0;\\nALTER TABLE your_table DROP FOREIGN KEY fk_rarely_used;\\nALTER TABLE your_table DROP INDEX idx_fk_col;\\nSET FOREIGN_KEY_CHECKS = 1;\\n\\n-- Option B: Keep FK constraint but make index invisible to test impact\\n-- (Not possible directly for FK indexes; use INVISIBLE on non-FK copy)\\n\\n-- Option C: Replace FK index with a minimal partial index (not possible in MySQL)\\n-- Best practice: drop FK if relationship is rarely joined and enforce at application level\\n\\nANALYZE TABLE your_table;", "parameters": null, "description": "Remove unused FK indexes by dropping the associated foreign key constraint on rarely-joined relationships."}	\N	medium	t	t	5 minutes	2026-03-01 09:33:09.381992
28309	mysql	diagnose	mysql_diagnose_oversized_leading_column	{"sql": "SELECT s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.SEQ_IN_INDEX, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / t.TABLE_ROWS * 100, 2) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c USING (TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME) JOIN information_schema.TABLES t USING (TABLE_SCHEMA, TABLE_NAME) WHERE s.TABLE_SCHEMA = DATABASE() AND s.SEQ_IN_INDEX = 1 AND c.CHARACTER_MAXIMUM_LENGTH > 20 ORDER BY selectivity_pct ASC, c.CHARACTER_MAXIMUM_LENGTH DESC LIMIT 15;", "parameters": null, "description": "Find leading index columns with large declared widths and check their actual selectivity."}	\N	low	f	t	5 minutes	2026-03-01 09:33:09.381992
