28925	mysql	diagnose	mysql_diagnose_where_correlated_subquery	{"sql": "EXPLAIN SELECT * FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id AND o.total > 1000);\\nEXPLAIN SELECT * FROM customers WHERE customer_id IN (SELECT customer_id FROM orders WHERE total > 1000);\\nSELECT sql_text, rows_examined, query_time FROM performance_schema.events_statements_history_long WHERE sql_text LIKE '%WHERE EXISTS%' OR sql_text LIKE '%WHERE%IN (SELECT%' ORDER BY query_time DESC LIMIT 10;", "parameters": {}, "description": "Run EXPLAIN on EXISTS and IN (SELECT) queries. Look for 'DEPENDENT SUBQUERY' or 'DEPENDENT UNION' in the select_type column indicating correlated execution. Query performance_schema for the slowest EXISTS/IN subquery patterns."}	\N	low	f	t	5m	2026-03-01 09:33:09.381992
