29129	mysql	diagnose	mysql_identify_lock_wait_blockers	{"sql": "-- Find blocking transactions and their victims\\nSELECT\\n  r.trx_id AS waiting_trx_id,\\n  r.trx_mysql_thread_id AS waiting_thread,\\n  r.trx_query AS waiting_query,\\n  b.trx_id AS blocking_trx_id,\\n  b.trx_mysql_thread_id AS blocking_thread,\\n  b.trx_query AS blocking_query,\\n  b.trx_started AS blocking_started,\\n  TIMESTAMPDIFF(SECOND, b.trx_started, NOW()) AS blocking_duration_sec\\nFROM performance_schema.data_lock_waits w\\nJOIN information_schema.innodb_trx r ON w.REQUESTING_ENGINE_TRANSACTION_ID = r.trx_id\\nJOIN information_schema.innodb_trx b ON w.BLOCKING_ENGINE_TRANSACTION_ID = b.trx_id\\nORDER BY blocking_duration_sec DESC;\\n\\nSHOW GLOBAL VARIABLES LIKE 'innodb_lock_wait_timeout';", "parameters": {}, "description": "Identify which blocking transactions are causing lock wait timeouts. The blocking_duration_sec and blocking_query columns reveal whether the blocker is a long-running transaction or a stuck idle connection."}	\N	low	f	t	3 minutes	2026-03-01 09:33:09.381992
29130	mysql	execute	mysql_resolve_lock_wait_timeout	{"sql": "-- Kill the blocking transaction (replace with actual thread ID)\\nKILL CONNECTION <blocking_thread_id>;\\n\\n-- Tune lock wait timeout for the workload\\nSET GLOBAL innodb_lock_wait_timeout = 30;\\n\\n-- Enable full transaction rollback on timeout (safer for application consistency)\\nSET GLOBAL innodb_rollback_on_timeout = ON;\\n\\n-- If OLTP workload: keep transactions short (add to my.cnf):\\n-- innodb_lock_wait_timeout = 30\\n-- innodb_rollback_on_timeout = ON", "parameters": {"innodb_lock_wait_timeout": "30 seconds (OLTP), 120+ seconds (batch)", "innodb_rollback_on_timeout": "ON for full transaction rollback"}, "description": "Kill the identified blocking session to unblock waiting transactions. Tune innodb_lock_wait_timeout to a value appropriate for the workload (shorter for OLTP, longer for batch). Enable innodb_rollback_on_timeout to ensure full transaction rollback rather than statement-level rollback on timeout."}	{"sql": "SET GLOBAL innodb_lock_wait_timeout = 50; SET GLOBAL innodb_rollback_on_timeout = OFF;", "description": ""}	medium	t	t	5 minutes	2026-03-01 09:33:09.381992
