29259	mysql	execute	mysql_revoke_and_remove_project_accounts	{"sql": "-- Lock first (soft removal, 30-day hold)\\nALTER USER '<project_user>'@'%' ACCOUNT LOCK;\\n-- After hold period, remove all grants then drop\\nREVOKE ALL PRIVILEGES, GRANT OPTION FROM '<project_user>'@'%';\\nDROP USER IF EXISTS '<project_user>'@'%';\\nFLUSH PRIVILEGES;\\n-- Add project tracking to registry\\nINSERT INTO mysql_admin.service_account_registry\\n  (svc_user, svc_host, application, owner_team, created_date, status)\\nVALUES ('<project_user>', '%', '<project_name>', '<team>', CURDATE(), 'pending_removal')\\nON DUPLICATE KEY UPDATE status = 'pending_removal';", "parameters": {"project_user": "MySQL username for the completed project"}, "description": "Lock stale project accounts for a 30-day hold period, then revoke all privileges and drop the accounts. Record the deprovisioning action in the registry."}	{"sql": "Accounts cannot be restored after DROP; recreate with: CREATE USER '<project_user>'@'%' IDENTIFIED BY '<new_password>'; and reapply required grants.", "description": ""}	medium	t	f	20m	2026-03-01 09:33:09.381992
29260	mysql	verify	mysql_verify_project_accounts_removed	{"sql": "-- Confirm account is gone\\nSELECT user, host FROM mysql.user WHERE user = '<project_user>';\\n-- Confirm no residual privilege grants\\nSELECT GRANTEE FROM information_schema.USER_PRIVILEGES WHERE GRANTEE LIKE \\"'<project_user>'%\\";\\n-- Review remaining project-style accounts\\nSELECT user, host, account_locked FROM mysql.user\\nWHERE user LIKE '%proj%' OR user LIKE '%migration%' OR user LIKE '%poc%'\\nORDER BY user;", "parameters": {}, "description": "Confirm the project account and all its privileges are fully removed, and review remaining project-style accounts for completeness."}	\N	low	f	t	5m	2026-03-01 09:33:09.381992
29261	mysql	diagnose	mysql_baseline_all_accounts	{"sql": "-- Generate complete account baseline\\nSELECT u.user, u.host, u.plugin, u.account_locked, u.password_expired,\\n       u.password_last_changed, u.password_lifetime,\\n       GROUP_CONCAT(DISTINCT gp.PRIVILEGE_TYPE ORDER BY gp.PRIVILEGE_TYPE SEPARATOR ', ') AS global_privs\\nFROM mysql.user u\\nLEFT JOIN information_schema.USER_PRIVILEGES gp ON gp.GRANTEE = CONCAT(\\"'\\", u.user, \\"'@'\\", u.host, \\"'\\")\\nWHERE u.user NOT IN ('mysql.sys', 'mysql.infoschema', 'mysql.session')\\n  AND u.user != ''\\nGROUP BY u.user, u.host, u.plugin, u.account_locked, u.password_expired,\\n         u.password_last_changed, u.password_lifetime\\nORDER BY u.user, u.host;", "parameters": {}, "description": "Generate a complete baseline snapshot of all MySQL accounts, their authentication settings, and privilege levels as the starting point for the formal inventory."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
29262	mysql	execute	mysql_build_account_inventory_infrastructure	{"sql": "-- Create formal inventory schema\\nCREATE DATABASE IF NOT EXISTS mysql_admin;\\nCREATE TABLE IF NOT EXISTS mysql_admin.account_inventory (\\n  account_id INT AUTO_INCREMENT PRIMARY KEY,\\n  mysql_user VARCHAR(32) NOT NULL,\\n  mysql_host VARCHAR(255) NOT NULL,\\n  account_type ENUM('human', 'service', 'admin', 'contractor', 'system') NOT NULL,\\n  owner_name VARCHAR(255),\\n  owner_email VARCHAR(255),\\n  business_justification TEXT,\\n  approved_by VARCHAR(255),\\n  created_date DATE NOT NULL,\\n  review_due_date DATE NOT NULL,\\n  status ENUM('active', 'locked', 'pending_removal', 'removed') DEFAULT 'active',\\n  notes TEXT,\\n  last_audited TIMESTAMP,\\n  UNIQUE KEY uq_account (mysql_user, mysql_host)\\n);\\n-- Populate from current account baseline\\nINSERT IGNORE INTO mysql_admin.account_inventory\\n  (mysql_user, mysql_host, account_type, created_date, review_due_date)\\nSELECT user, host, 'human', CURDATE(), DATE_ADD(CURDATE(), INTERVAL 90 DAY)\\nFROM mysql.user\\nWHERE user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session') AND user != '';", "parameters": {}, "description": "Create a formal account inventory table, populate it from the current MySQL user baseline, and establish fields for ownership, justification, and review scheduling."}	{"sql": "DROP TABLE IF EXISTS mysql_admin.account_inventory;", "description": ""}	low	t	t	30m	2026-03-01 09:33:09.381992
29263	mysql	verify	mysql_verify_inventory_coverage	{"sql": "-- Confirm all MySQL accounts are in the inventory\\nSELECT u.user, u.host\\nFROM mysql.user u\\nLEFT JOIN mysql_admin.account_inventory inv ON inv.mysql_user = u.user AND inv.mysql_host = u.host\\nWHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n  AND u.user != ''\\n  AND inv.account_id IS NULL;\\n-- Confirm inventory completeness\\nSELECT COUNT(*) AS total_inventory_entries,\\n       SUM(owner_name IS NULL) AS missing_owners,\\n       SUM(status = 'active') AS active_accounts\\nFROM mysql_admin.account_inventory;", "parameters": {}, "description": "Confirm that every MySQL account is represented in the inventory and that the inventory has complete ownership information."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
29264	mysql	diagnose	mysql_assess_current_review_cadence	{"sql": "-- Identify accounts that would be flagged under a 30-day dormancy threshold\\nSELECT u.user, u.host, u.account_locked,\\n       DATEDIFF(NOW(), u.password_last_changed) AS days_since_activity\\nFROM mysql.user u\\nWHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n  AND u.user != ''\\n  AND u.account_locked = 'N'\\n  AND u.password_last_changed < DATE_SUB(NOW(), INTERVAL 30 DAY)\\nORDER BY days_since_activity DESC;\\n-- Count accounts by dormancy tier\\nSELECT\\n  SUM(DATEDIFF(NOW(), password_last_changed) BETWEEN 30 AND 60) AS dormant_30_60d,\\n  SUM(DATEDIFF(NOW(), password_last_changed) BETWEEN 61 AND 90) AS dormant_61_90d,\\n  SUM(DATEDIFF(NOW(), password_last_changed) > 90) AS dormant_over_90d\\nFROM mysql.user\\nWHERE user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session') AND user != '';", "parameters": {}, "description": "Assess the scale of dormant accounts under a 30-day threshold to understand the gap between the current infrequent review cycle and a more aggressive monitoring cadence."}	\N	low	f	t	5m	2026-03-01 09:33:09.381992
29265	mysql	execute	mysql_implement_monthly_dormancy_review	{"sql": "-- Create a monthly review log table\\nCREATE TABLE IF NOT EXISTS mysql_admin.access_review_log (\\n  review_id INT AUTO_INCREMENT PRIMARY KEY,\\n  review_date DATE NOT NULL,\\n  reviewer VARCHAR(255),\\n  mysql_user VARCHAR(32) NOT NULL,\\n  mysql_host VARCHAR(255) NOT NULL,\\n  days_inactive INT,\\n  action_taken ENUM('no_action', 'warned', 'locked', 'dropped') DEFAULT 'no_action',\\n  notes TEXT\\n);\\n-- Create scheduled event for monthly dormancy report\\nCREATE EVENT IF NOT EXISTS mysql_admin.monthly_dormancy_report\\nON SCHEDULE EVERY 1 MONTH STARTS (DATE_FORMAT(NOW() ,'%Y-%m-01') + INTERVAL 1 MONTH)\\nDO\\n  INSERT INTO mysql_admin.access_review_log (review_date, mysql_user, mysql_host, days_inactive)\\n  SELECT CURDATE(), user, host, DATEDIFF(CURDATE(), password_last_changed)\\n  FROM mysql.user\\n  WHERE user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n    AND user != ''\\n    AND password_last_changed < DATE_SUB(CURDATE(), INTERVAL 30 DAY);\\n-- Lock accounts inactive for over 60 days automatically\\nCREATE EVENT IF NOT EXISTS mysql_admin.auto_lock_dormant\\nON SCHEDULE EVERY 1 MONTH STARTS (DATE_FORMAT(NOW() ,'%Y-%m-01') + INTERVAL 1 MONTH)\\nDO\\n  -- In practice implement via stored procedure:\\n  CALL mysql_admin.lock_dormant_accounts(60);", "parameters": {}, "description": "Implement monthly automated dormancy reporting and establish an auto-lock policy for accounts inactive beyond 60 days, reducing the effective review window from quarterly to monthly."}	{"sql": "DROP EVENT IF EXISTS mysql_admin.monthly_dormancy_report; DROP EVENT IF EXISTS mysql_admin.auto_lock_dormant;", "description": ""}	medium	t	t	30m	2026-03-01 09:33:09.381992
29266	mysql	verify	mysql_verify_monthly_reviews_active	{"sql": "-- Confirm events are scheduled\\nSELECT event_name, status, last_executed, interval_value, interval_field\\nFROM information_schema.events\\nWHERE event_schema = 'mysql_admin';\\n-- Confirm review log is being populated\\nSELECT COUNT(*) AS log_entries, MAX(review_date) AS last_review\\nFROM mysql_admin.access_review_log;\\n-- Confirm accounts are being locked by dormancy policy\\nSELECT COUNT(*) AS currently_locked\\nFROM mysql.user\\nWHERE account_locked = 'Y'\\n  AND user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session');", "parameters": {}, "description": "Confirm that monthly review events are scheduled and active, that the review log is being populated, and that the dormancy auto-lock policy is producing results."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
29267	mysql	diagnose	mysql_identify_misclassified_service_accounts	{"sql": "-- Find accounts with application-pattern connections in process list\\nSELECT user, host, db, command, info\\nFROM information_schema.processlist\\nWHERE user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session', 'event_scheduler')\\nORDER BY user;\\n-- Find accounts with consistent connection patterns (likely service accounts)\\nSELECT user, host, COUNT(*) AS connection_count\\nFROM information_schema.processlist\\nGROUP BY user, host\\nHAVING connection_count > 1\\nORDER BY connection_count DESC;\\n-- Check inventory classification\\nSELECT i.mysql_user, i.account_type, i.owner_name\\nFROM mysql_admin.account_inventory i\\nWHERE i.account_type = 'human';", "parameters": {}, "description": "Identify accounts with active connection patterns consistent with application service accounts and cross-reference them against inventory classification to find misclassified entries."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
29268	mysql	execute	mysql_reclassify_and_remediate_service_accounts	{"sql": "-- Update inventory classification for misclassified accounts\\nUPDATE mysql_admin.account_inventory\\nSET account_type = 'service',\\n    owner_name = '<application_team>',\\n    business_justification = 'Application service account for <app_name>',\\n    notes = 'Reclassified from human to service account on review'\\nWHERE mysql_user = '<misclassified_user>'\\n  AND mysql_host = '%';\\n-- For decommissioned application accounts, lock immediately\\nALTER USER '<decommissioned_app_user>'@'%' ACCOUNT LOCK;\\nUPDATE mysql_admin.account_inventory\\nSET status = 'pending_removal',\\n    notes = 'Application decommissioned; pending 30-day hold before drop'\\nWHERE mysql_user = '<decommissioned_app_user>';\\n-- Tag active service accounts in MySQL user metadata\\nALTER USER '<service_user>'@'%' COMMENT '{\\"type\\": \\"service\\", \\"application\\": \\"<app>\\", \\"team\\": \\"<team>\\"}';\\nFLUSH PRIVILEGES;", "parameters": {"misclassified_user": "account previously classified as human but used by an application", "decommissioned_app_user": "service account for an application that is no longer active"}, "description": "Update inventory records to correctly classify application accounts as service accounts, lock accounts for decommissioned applications, and apply metadata tagging for active service accounts."}	{"sql": "ALTER USER '<decommissioned_app_user>'@'%' ACCOUNT UNLOCK; UPDATE mysql_admin.account_inventory SET status = 'active' WHERE mysql_user = '<decommissioned_app_user>';", "description": ""}	medium	t	t	25m	2026-03-01 09:33:09.381992
29269	mysql	verify	mysql_verify_service_account_classification	{"sql": "-- Confirm inventory has no remaining misclassified human accounts\\nSELECT i.mysql_user, i.account_type, p.user AS active_connections\\nFROM mysql_admin.account_inventory i\\nJOIN information_schema.processlist p ON p.user = i.mysql_user\\nWHERE i.account_type = 'human'\\nGROUP BY i.mysql_user, i.account_type\\nHAVING COUNT(p.user) > 2;\\n-- Confirm decommissioned accounts are locked\\nSELECT u.user, u.account_locked, i.status\\nFROM mysql.user u\\nJOIN mysql_admin.account_inventory i ON i.mysql_user = u.user\\nWHERE i.status = 'pending_removal'\\n  AND u.account_locked = 'N';", "parameters": {}, "description": "Confirm no human-classified accounts have persistent multi-connection patterns indicating service account usage, and verify all decommissioned accounts are locked."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
29270	mysql	diagnose	mysql_assess_dormancy_detection_gaps	{"sql": "-- Check if performance_schema account tracking is enabled\\nSELECT * FROM performance_schema.setup_actors WHERE host = '%' AND user = '%';\\n-- Check account-level statement summaries for activity data\\nSELECT user, host, COUNT_STAR AS total_statements,\\n       LAST_SEEN\\nFROM performance_schema.accounts\\nWHERE user IS NOT NULL\\n  AND user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\nORDER BY LAST_SEEN ASC\\nLIMIT 20;\\n-- Identify accounts with zero activity in performance_schema\\nSELECT u.user, u.host\\nFROM mysql.user u\\nLEFT JOIN performance_schema.accounts pa ON pa.user = u.user AND pa.host = u.host\\nWHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n  AND u.user != ''\\n  AND (pa.user IS NULL OR pa.LAST_SEEN < DATE_SUB(NOW(), INTERVAL 90 DAY));", "parameters": {}, "description": "Assess the current state of performance_schema account tracking to identify gaps in dormancy detection coverage."}	\N	low	f	t	5m	2026-03-01 09:33:09.381992
29271	mysql	execute	mysql_deploy_automated_dormancy_detection	{"sql": "-- Ensure performance_schema actors are enabled\\nUPDATE performance_schema.setup_actors SET enabled = 'YES', history = 'YES' WHERE host = '%' AND user = '%';\\n-- Create dormancy detection stored procedure\\nDELIMITER //\\nCREATE PROCEDURE IF NOT EXISTS mysql_admin.detect_dormant_accounts(IN threshold_days INT)\\nBEGIN\\n  SELECT u.user, u.host, u.account_locked,\\n         pa.LAST_SEEN,\\n         DATEDIFF(NOW(), pa.LAST_SEEN) AS days_since_seen\\n  FROM mysql.user u\\n  LEFT JOIN performance_schema.accounts pa ON pa.user = u.user\\n  WHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n    AND u.user != ''\\n    AND u.account_locked = 'N'\\n    AND (pa.LAST_SEEN IS NULL OR pa.LAST_SEEN < DATE_SUB(NOW(), INTERVAL threshold_days DAY))\\n  ORDER BY days_since_seen DESC;\\nEND //\\nDELIMITER ;\\n-- Schedule monthly dormancy detection report\\nCREATE EVENT IF NOT EXISTS mysql_admin.auto_dormancy_check\\nON SCHEDULE EVERY 1 MONTH\\nDO CALL mysql_admin.detect_dormant_accounts(90);", "parameters": {}, "description": "Enable performance_schema account tracking, deploy a stored procedure for configurable dormancy detection, and schedule it as a monthly automated event."}	{"sql": "DROP PROCEDURE IF EXISTS mysql_admin.detect_dormant_accounts; DROP EVENT IF EXISTS mysql_admin.auto_dormancy_check;", "description": ""}	low	t	t	20m	2026-03-01 09:33:09.381992
