29277	mysql	execute	mysql_enhance_audit_trail_depth	{"sql": "-- Enable connection-level performance_schema consumers\\nUPDATE performance_schema.setup_consumers\\nSET enabled = 'YES'\\nWHERE name IN ('events_statements_history', 'events_statements_history_long', 'events_transactions_history');\\n-- Enable connection instruments\\nUPDATE performance_schema.setup_instruments\\nSET enabled = 'YES', timed = 'YES'\\nWHERE name LIKE 'statement/sql/connect%' OR name LIKE 'statement/com/%';\\n-- Create persistent first-seen and last-seen tracking\\nCREATE TABLE IF NOT EXISTS mysql_admin.login_history (\\n  login_id BIGINT AUTO_INCREMENT PRIMARY KEY,\\n  mysql_user VARCHAR(32) NOT NULL,\\n  mysql_host VARCHAR(255) NOT NULL,\\n  login_timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\\n  client_host VARCHAR(255),\\n  INDEX idx_user_ts (mysql_user, login_timestamp)\\n);\\n-- Configure audit_log to capture all connection events (Enterprise)\\n-- In my.cnf: audit_log_policy=ALL, audit_log_format=JSON\\n-- SHOW VARIABLES LIKE 'audit_log_policy';\\nSET GLOBAL audit_log_policy = 'ALL';", "parameters": {}, "description": "Enable comprehensive connection-level tracking in performance_schema and create a persistent login history table to maintain audit trails across MySQL restarts."}	{"sql": "DROP TABLE IF EXISTS mysql_admin.login_history; -- Revert performance_schema consumers by setting enabled = 'NO' for added instruments.", "description": ""}	low	t	t	25m	2026-03-01 09:33:09.381992
29278	mysql	verify	mysql_verify_enhanced_audit_trail	{"sql": "-- Confirm login history table is being populated\\nSELECT COUNT(*) AS login_events, MIN(login_timestamp) AS earliest, MAX(login_timestamp) AS latest\\nFROM mysql_admin.login_history;\\n-- Confirm never-used vs historically-used accounts can be distinguished\\nSELECT u.user, u.host,\\n       MIN(lh.login_timestamp) AS first_seen,\\n       MAX(lh.login_timestamp) AS last_seen,\\n       COUNT(lh.login_id) AS total_logins\\nFROM mysql.user u\\nLEFT JOIN mysql_admin.login_history lh ON lh.mysql_user = u.user\\nWHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n  AND u.user != ''\\nGROUP BY u.user, u.host\\nORDER BY last_seen ASC;", "parameters": {}, "description": "Confirm that the enhanced audit trail captures login events and can distinguish between accounts that have never been used (NULL first_seen) and those with historical activity."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
