29306	mysql	execute	mysql_implement_drift_detection	{"sql": "-- Enable MySQL Enterprise Audit or configure general_log for authentication events\\nSET GLOBAL general_log = ON;\\nSET GLOBAL general_log_file = '/var/log/mysql/general.log';\\n\\n-- Create a drift detection view for regular querying\\nCREATE OR REPLACE VIEW security_audit.auth_drift_check AS\\nSELECT user, host, plugin,\\n  CASE WHEN authentication_string = '' THEN 'ALERT: No password' ELSE 'OK' END AS password_status,\\n  CASE WHEN plugin IN ('mysql_old_password','') THEN 'ALERT: Insecure plugin' ELSE 'OK' END AS plugin_status,\\n  account_locked, password_expired\\nFROM mysql.user\\nWHERE user != ''\\nORDER BY user;\\n\\n-- Schedule regular drift check via MySQL Event Scheduler\\nSET GLOBAL event_scheduler = ON;\\nCREATE EVENT IF NOT EXISTS security_audit.auth_drift_scan\\n  ON SCHEDULE EVERY 1 DAY\\n  DO\\n    INSERT INTO security_audit.drift_log (scan_time, flagged_accounts)\\n    SELECT NOW(), GROUP_CONCAT(user, '@', host SEPARATOR ', ')\\n    FROM security_audit.auth_drift_check\\n    WHERE password_status != 'OK' OR plugin_status != 'OK';", "parameters": {"scan_frequency": "daily", "alert_conditions": "empty password, insecure plugin"}, "description": "Create a drift detection view against mysql.user and schedule a daily event to log any accounts with missing passwords or insecure plugins into an audit log table."}	{"sql": "DROP EVENT IF EXISTS security_audit.auth_drift_scan; DROP VIEW IF EXISTS security_audit.auth_drift_check; SET GLOBAL general_log = OFF;", "description": ""}	low	f	t	20 minutes	2026-03-01 09:33:09.381992
