29443	mysql	execute	mysql_apply_vendor_default_hardening	{"sql": "-- Remove anonymous users\\nDELETE FROM mysql.user WHERE User = '';\\n\\n-- Remove remote root login\\nDELETE FROM mysql.user WHERE User = 'root' AND Host != 'localhost';\\n\\n-- Remove test database\\nDROP DATABASE IF EXISTS test;\\nDELETE FROM mysql.db WHERE Db = 'test' OR Db = 'test\\\\_%';\\n\\n-- Set strong root password\\nALTER USER 'root'@'localhost' IDENTIFIED BY 'StrongRootPassword123!';\\n\\n-- Enable password validation\\nINSTALL COMPONENT 'file://component_validate_password';\\nSET GLOBAL validate_password.policy = 'STRONG';\\nSET GLOBAL validate_password.length = 12;\\n\\n-- Lock unused system accounts\\nALTER USER 'mysql.sys'@'localhost' ACCOUNT LOCK;\\nALTER USER 'mysql.session'@'localhost' ACCOUNT LOCK;\\n\\nFLUSH PRIVILEGES;", "parameters": {}, "description": "Apply standard MySQL hardening: remove anonymous users, restrict root to localhost, drop test database, and enable strong password validation."}	{"sql": "-- Restore if needed (emergency only)\\n-- CREATE USER ''@'localhost';\\n-- GRANT USAGE ON *.* TO ''@'localhost';\\nFLUSH PRIVILEGES;", "description": ""}	medium	t	f	20m	2026-03-01 09:33:09.381992
