29451	mysql	diagnose	mysql_audit_anonymous_and_global_grants	{"sql": "-- MySQL does not have a rootcause role like PostgreSQL.\\n-- Check anonymous user grants (equivalent to rootcause for unauthenticated access)\\nSELECT User, Host, Select_priv, Insert_priv, Update_priv, Delete_priv\\nFROM mysql.user WHERE User = '';\\n\\n-- Check grants on anonymous user\\nSHOW GRANTS FOR ''@'localhost';\\n\\n-- Check overly broad database grants that apply globally\\nSELECT * FROM mysql.db WHERE Host = '%' AND User = '' ORDER BY Db;\\n\\n-- Check global privileges on all non-system users\\nSELECT User, Host, Select_priv, Insert_priv\\nFROM mysql.user\\nWHERE (Select_priv = 'Y' OR Insert_priv = 'Y')\\n  AND User != 'root'\\nORDER BY User;", "parameters": {}, "description": "Identify anonymous user grants and broadly-scoped grants that effectively function as rootcause access in MySQL."}	\N	low	f	t	10m	2026-03-01 09:33:09.381992
