70	sqlserver	execute	Attempt DBCC CHECKDB repair at REPAIR_REBUILD level	{"sql": "ALTER DATABASE [$(database_name)] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;\\nDBCC CHECKDB (N'$(database_name)', REPAIR_REBUILD) WITH NO_INFOMSGS;\\nALTER DATABASE [$(database_name)] SET MULTI_USER;", "parameters": ["database_name"], "description": "Sets the database to single-user mode and runs repair at the safest level. REPAIR_REBUILD rebuilds indexes and corrects allocation errors without data loss."}	{"sql": "ALTER DATABASE [$(database_name)] SET MULTI_USER;", "description": "Restore multi-user access if repair is abandoned mid-step."}	medium	t	f	01:00:00	2026-02-24 13:10:27.102965
