651	sqlserver	instruct	Identify authoritative primary and isolate the rogue node	{"sql": "SELECT ag.name, ar.replica_server_name, ars.role_desc, ars.synchronization_health_desc, adb.end_of_log_lsn FROM sys.dm_hadr_availability_replica_states ars JOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id JOIN sys.availability_groups ag ON ar.group_id = ag.group_id LEFT JOIN sys.dm_hadr_database_replica_states adb ON ars.replica_id = adb.replica_id;", "parameters": [], "description": "Compare end_of_log_lsn values across both primaries. The node with the higher LSN has more committed data. Isolate the node with the lower LSN (network partition, shutdown, or WSFC eviction) before proceeding."}	null	medium	t	f	00:30:00	2026-02-24 13:10:27.163011
652	sqlserver	execute	Force quorum on authoritative node via PowerShell	{"sql": null, "parameters": ["rogue_node_name", "authoritative_node", "ag_name"], "description": "On the authoritative node, run in PowerShell: Stop-ClusterNode -Name <rogue_node_name> -Force; then Start-ClusterNode -Name <authoritative_node> -FixQuorum. Then in SQL Server: ALTER AVAILABILITY GROUP [<ag_name>] FORCE_FAILOVER_ALLOW_DATA_LOSS;"}	null	medium	t	f	00:15:00	2026-02-24 13:10:27.163011
872	sqlserver	execute	Kill the session holding single-user access if blocking maintenance	{"sql": "-- Only execute if a stale session is occupying the single-user slot\\n-- Replace <session_id> with the value from the step 1 query\\nKILL <session_id>;", "parameters": ["session_id: from the second query in step 1"], "description": "If a stale or idle session holds the SINGLE_USER slot and is preventing the ALTER DATABASE command from executing, terminate it first. Skip this step if no session is listed."}	null	medium	t	f	00:01:00	2026-02-24 13:10:27.192385
715	sqlserver	execute	Kill long-running transactions holding version store open	{"sql": "DECLARE @session_id INT; DECLARE txn_cursor CURSOR FOR SELECT s.session_id FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id JOIN sys.dm_exec_sessions s ON st.session_id = s.session_id WHERE DATEDIFF(minute, t.transaction_begin_time, GETDATE()) > @min_duration_minutes AND s.is_user_process = 1; OPEN txn_cursor; FETCH NEXT FROM txn_cursor INTO @session_id; WHILE @@FETCH_STATUS = 0 BEGIN EXEC('KILL ' + @session_id); FETCH NEXT FROM txn_cursor INTO @session_id; END; CLOSE txn_cursor; DEALLOCATE txn_cursor;", "parameters": ["min_duration_minutes"], "description": "Kills sessions with transactions open longer than the threshold. Any uncommitted work is rolled back."}	null	medium	t	f	00:01:00	2026-02-24 13:10:27.169316
733	sqlserver	execute	Kill oldest snapshot transactions blocking version store cleanup	{"sql": "DECLARE @session_id INT; SELECT TOP 1 @session_id = session_id FROM sys.dm_tran_active_snapshot_database_transactions ORDER BY elapsed_time_seconds DESC; IF @session_id IS NOT NULL EXEC('KILL ' + @session_id);", "parameters": [], "description": "Kills the single longest-running snapshot transaction. Repeat as needed until version store starts shrinking. Killing the oldest transaction unblocks cleanup for all versions older than the next-oldest transaction."}	null	medium	t	f	00:01:00	2026-02-24 13:10:27.173706
792	sqlserver	execute	Restore corrupt pages from backup (page-level restore)	{"sql": "RESTORE DATABASE [database_name] PAGE = 'file_id:page_id' FROM DISK = N'backup_file_path' WITH NORECOVERY; RESTORE LOG [database_name] FROM DISK = N'log_backup_path' WITH RECOVERY;", "parameters": ["database_name", "file_id", "page_id", "backup_file_path", "log_backup_path"], "description": "Perform page-level restore for each corrupt page. Requires the database backup and subsequent log backups to bring pages to current state. Replace file_id:page_id with values from suspect_pages. Multiple pages can be listed comma-separated."}	{"sql": "RESTORE DATABASE [database_name] FROM DISK = N'full_backup_path' WITH REPLACE, RECOVERY;", "description": "If page restore fails, perform a full database restore from the most recent clean backup."}	medium	t	f	\N	2026-02-24 13:10:27.189498
796	sqlserver	execute	Restore torn pages from backup	{"sql": "RESTORE DATABASE [database_name] PAGE = 'file_id:page_id' FROM DISK = N'backup_path' WITH NORECOVERY; RESTORE LOG [database_name] FROM DISK = N'log_backup_path' WITH RECOVERY;", "parameters": ["database_name", "file_id", "page_id", "backup_path", "log_backup_path"], "description": "Restore all torn pages (event_type 1 or 3) identified in msdb.dbo.suspect_pages. Requires FULL recovery model and an unbroken log backup chain."}	{"sql": "RESTORE DATABASE [database_name] FROM DISK = N'full_backup_path' WITH REPLACE, RECOVERY;", "description": "Full database restore if page-level restore is insufficient or the backup chain is broken."}	medium	t	f	\N	2026-02-24 13:10:27.189503
