12946	oracle	execute	ora_reship_corrupt_archives	{"sql": "-- 1. Delete corrupt archive on standby:\\n-- rm /u01/archive/corrupt_archive.arc\\n-- 2. Clear archive log metadata:\\nALTER DATABASE CLEAR LOGFILE GROUP <corrupt_group>;\\n-- 3. Re-fetch from primary via FAL:\\n-- FAL will auto-detect the gap and re-fetch\\n-- Or manually copy from primary:\\n-- scp primary:/u01/archive/thread_1_seq_<N>.arc standby:/u01/archive/\\n-- ALTER DATABASE REGISTER LOGFILE '/u01/archive/thread_1_seq_<N>.arc';", "parameters": [], "description": "Remove corrupt archive and re-fetch clean copy from primary"}	\N	medium	t	f	minutes	2026-02-28 22:39:08.596677
13026	oracle	configure	ora_configure_gg_conflict_resolution	{"sql": "-- 1. Enable supplemental logging for conflict detection:\\nALTER DATABASE ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;\\n-- 2. Configure Replicat conflict resolution in GoldenGate:\\n-- In Replicat parameter file:\\n-- MAP schema.table, TARGET schema.table,\\n--   COMPARECOLS (ON UPDATE ALL, ON DELETE ALL),\\n--   RESOLVECONFLICT (UPDATEROWEXISTS, (DEFAULT, USEMAX (last_updated_at))),\\n--   RESOLVECONFLICT (INSERTROWEXISTS, (DEFAULT, OVERWRITE)),\\n--   RESOLVECONFLICT (DELETEROWEXISTS, (DEFAULT, OVERWRITE));", "parameters": [], "description": "Configure Oracle GoldenGate conflict detection and resolution rules"}	{"sql": "ALTER DATABASE DROP SUPPLEMENTAL LOG DATA (ALL) COLUMNS;", "description": "Remove supplemental logging"}	medium	t	t	minutes	2026-02-28 22:39:08.596677
13052	oracle	configure	ora_enable_gg_ddl_replication	{"sql": "-- Option 1: Enable GoldenGate DDL replication:\\n-- In Extract param: DDL INCLUDE ALL\\n-- In Replicat param: DDL INCLUDE ALL\\n-- Option 2: Manually apply the DDL on target:\\n-- Run the same ALTER TABLE / CREATE INDEX on target\\n-- Option 3: For selective DDL replication:\\n-- DDL INCLUDE MAPPED OBJNAME schema.*\\n-- DDL EXCLUDE OBJTYPE 'INDEX'", "parameters": [], "description": "Enable GoldenGate DDL replication or manually synchronize schema changes"}	\N	medium	t	t	minutes	2026-02-28 22:39:08.596677
