13061	oracle	execute	ora_reconcile_after_partition	{"sql": "-- 1. When network restores, GoldenGate will automatically start processing queued trails\\n-- 2. Ensure conflict resolution is configured (should be pre-configured):\\n-- RESOLVECONFLICT rules will handle divergent data automatically\\n-- 3. Monitor for unresolvable conflicts:\\n-- GGSCI> STATS REPLICAT <name>, REPORTDETAIL\\n-- 4. If too many conflicts, consider Oracle GoldenGate Veridata for comparison:\\n-- Veridata compares source and target data and reports differences\\n-- 5. Manual reconciliation for critical tables:\\n-- SELECT * FROM schema.critical_table MINUS SELECT * FROM schema.critical_table@remote_db;", "parameters": [], "description": "Reconcile divergent data after network partition using GoldenGate conflict resolution"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13064	oracle	configure	ora_add_comprehensive_conflict_resolution	{"sql": "-- 1. Enable required supplemental logging:\\nALTER DATABASE ADD SUPPLEMENTAL LOG DATA;\\nALTER DATABASE ADD SUPPLEMENTAL LOG DATA (PRIMARY KEY) COLUMNS;\\n-- 2. Add conflict resolution to Replicat parameter file:\\n-- For each replicated table:\\n-- MAP schema.table, TARGET schema.table,\\n--   COMPARECOLS (ON UPDATE ALL, ON DELETE ALL),\\n--   RESOLVECONFLICT (UPDATEROWEXISTS, (DEFAULT, USEMAX (last_modified))),\\n--   RESOLVECONFLICT (INSERTROWEXISTS, (DEFAULT, OVERWRITE)),\\n--   RESOLVECONFLICT (UPDATEROWMISSING, (DEFAULT, OVERWRITE)),\\n--   RESOLVECONFLICT (DELETEROWMISSING, (DEFAULT, DISCARD)),\\n--   RESOLVECONFLICT (DELETEROWEXISTS, (DEFAULT, OVERWRITE));", "parameters": [], "description": "Add comprehensive conflict detection and resolution configuration to GoldenGate"}	\N	medium	t	t	minutes	2026-02-28 22:39:08.596677
13175	oracle	execute	ora_presize_and_reduce_contention	{"sql": "-- Pre-size files to avoid extension during high I/O:\\nALTER DATABASE DATAFILE '<file_path>' RESIZE 50G;\\n-- Check for concurrent I/O-heavy operations:\\nSELECT sid, serial#, opname, sofar, totalwork, ROUND(elapsed_seconds/60, 1) AS minutes FROM v$session_longops WHERE sofar < totalwork ORDER BY elapsed_seconds DESC;\\n-- Move datafiles to faster storage if available:\\n-- ALTER DATABASE MOVE DATAFILE '<old_path>' TO '<new_fast_path>';", "parameters": [], "description": "Pre-size files and resolve I/O contention that causes extension timeouts"}	\N	medium	t	f	minutes	2026-02-28 22:39:08.596677
13217	oracle	execute	ora_recover_corrupt_blocks_rman	{"sql": "-- RMAN block media recovery (requires backup):\\n-- RMAN> RECOVER DATAFILE <file#> BLOCK <block#>;\\n-- For multiple corrupt blocks:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- If Active Data Guard, recover from standby:\\n-- RMAN> RECOVER DATAFILE <file#> BLOCK <block#> FROM SERVICE standby_service;\\n\\n-- Enable DB_BLOCK_CHECKING for ongoing detection:\\nALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH;\\n-- Enable DB_BLOCK_CHECKSUM for write verification:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = TYPICAL SCOPE=BOTH;\\n-- Enable DB_LOST_WRITE_PROTECT on Data Guard:\\nALTER SYSTEM SET DB_LOST_WRITE_PROTECT = TYPICAL SCOPE=BOTH;\\n\\n-- For ASM, drop and replace failed disk:\\n-- ALTER DISKGROUP data DROP DISK failed_disk;\\n-- ALTER DISKGROUP data ADD DISK '/dev/new_disk';", "parameters": [], "description": "Recover corrupt blocks using RMAN and enable ongoing corruption detection parameters"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13220	oracle	execute	ora_enable_corruption_detection_and_recover	{"sql": "-- Enable maximum block checking to catch corruption at write time:\\nALTER SYSTEM SET DB_BLOCK_CHECKING = FULL SCOPE=BOTH;\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\n-- Flush potentially corrupt buffers and force re-read:\\nALTER SYSTEM FLUSH BUFFER_CACHE;\\n-- Validate entire database:\\n-- RMAN> BACKUP VALIDATE CHECK LOGICAL DATABASE;\\n-- Recover any corrupt blocks found:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- OS-level: Schedule memory test (requires downtime)\\n-- memtest86+ or vendor memory diagnostics\\n-- Check ECC memory error logs:\\n-- Linux: edac-util -s / mcelog --client\\n-- Solaris: fmadm faulty", "parameters": [], "description": "Enable maximum corruption detection, flush potentially corrupt buffers, and validate database"}	{"sql": "ALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH; ALTER SYSTEM SET DB_BLOCK_CHECKSUM = TYPICAL SCOPE=BOTH;", "description": ""}	medium	t	t	hours	2026-02-28 22:39:08.596677
13438	oracle	execute	ora_create_reverse_key_index	{"sql": "DROP INDEX {owner}.{index_name};\\nCREATE INDEX {owner}.{index_name} ON {table}({columns}) REVERSE ONLINE NOLOGGING;\\nALTER INDEX {owner}.{index_name} LOGGING;", "parameters": ["owner", "index_name", "table", "columns"], "description": "Recreate the index as reverse key to distribute sequential values across all leaf blocks"}	{"sql": "ALTER INDEX {owner}.{index_name} REBUILD ONLINE NOREVERSE", "description": "Rebuild as non-reverse index"}	medium	t	t	minutes	2026-02-28 22:39:08.596677
13223	oracle	execute	ora_recover_io_corruption_and_harden	{"sql": "-- Recover corrupt blocks via RMAN:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n-- Or recover from standby:\\n-- RMAN> RECOVER DATAFILE <file#> BLOCK <block#> FROM SERVICE standby_tns;\\n\\n-- Enable Oracle-level I/O verification:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\nALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH;\\n-- Enable lost write detection:\\nALTER SYSTEM SET DB_LOST_WRITE_PROTECT = TYPICAL SCOPE=BOTH;\\n\\n-- For ASM, ensure proper redundancy:\\n-- ALTER DISKGROUP data SET ATTRIBUTE 'compatible.asm' = '19.0';\\n-- ALTER DISKGROUP data SET ATTRIBUTE 'sector_size' = '4096';\\n\\n-- Disable filesystem caching for datafiles (Direct I/O):\\nALTER SYSTEM SET FILESYSTEMIO_OPTIONS = SETALL SCOPE=SPFILE;\\n-- Requires restart to take effect", "parameters": [], "description": "Recover corrupt blocks, enable I/O verification, and harden against future I/O corruption"}	{"sql": "ALTER SYSTEM SET FILESYSTEMIO_OPTIONS = NONE SCOPE=SPFILE;", "description": ""}	medium	t	t	hours	2026-02-28 22:39:08.596677
13235	oracle	execute	ora_recover_from_filesystem_corruption	{"sql": "-- If files are accessible, use RMAN block recovery:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- If files are missing/inaccessible, restore from backup:\\n-- RMAN> RESTORE DATAFILE <file#>;\\n-- RMAN> RECOVER DATAFILE <file#>;\\n\\n-- Migrate to ASM to avoid filesystem issues:\\n-- RMAN> BACKUP AS COPY DATAFILE <file#> FORMAT '+DATA';\\n-- ALTER DATABASE RENAME FILE '/fs/path/data01.dbf' TO '+DATA/dbname/datafile/data01.dbf';\\n\\n-- If remaining on filesystem, use direct I/O:\\nALTER SYSTEM SET FILESYSTEMIO_OPTIONS = SETALL SCOPE=SPFILE;\\n-- Ensure no filesystem-level caching conflicts:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;", "parameters": [], "description": "Recover database files and consider migration to ASM for filesystem-independent storage"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13226	oracle	execute	ora_recover_fractured_blocks_and_protect	{"sql": "-- RMAN block media recovery for fractured blocks:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n-- Or specific blocks:\\n-- RMAN> RECOVER DATAFILE <file#> BLOCK <block#>;\\n\\n-- Enable protections against future torn writes:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\n-- Ensure redo log multiplexing:\\n-- ALTER DATABASE ADD LOGFILE MEMBER '/path/mirror/redo01b.log' TO GROUP 1;\\n-- ALTER DATABASE ADD LOGFILE MEMBER '/path/mirror/redo02b.log' TO GROUP 2;\\n\\n-- Increase redo log size to reduce checkpoint frequency:\\n-- ALTER DATABASE ADD LOGFILE GROUP 4 ('/path/redo04a.log','/path/redo04b.log') SIZE 2G;\\n\\n-- For battery-backed write cache:\\nALTER SYSTEM SET DISK_ASYNCH_IO = TRUE SCOPE=BOTH;\\n-- Enable data guard for disaster protection:\\n-- See Data Guard setup for standby creation", "parameters": [], "description": "Recover fractured blocks via RMAN and enable protections against future torn writes"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13229	oracle	execute	ora_recover_and_protect_from_cache_failure	{"sql": "-- Recover corrupt blocks:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- Enable Oracle-level protections:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\nALTER SYSTEM SET DB_LOST_WRITE_PROTECT = TYPICAL SCOPE=BOTH;\\n-- Force direct I/O to bypass OS cache:\\nALTER SYSTEM SET FILESYSTEMIO_OPTIONS = SETALL SCOPE=SPFILE;\\n\\n-- For ASM, set disk repair timer:\\n-- ALTER DISKGROUP data SET ATTRIBUTE 'disk_repair_time' = '3.6h';\\n\\n-- OS-level: Coordinate with storage admin to:\\n-- 1. Check RAID battery backup unit (BBU) status\\n-- 2. Replace BBU if battery degraded\\n-- 3. Disable write-back cache if BBU is failed\\n-- 4. Verify write-through mode until BBU replaced\\n-- Linux: MegaCli -AdpBbuCmd -GetBbuStatus -aALL\\n-- Linux: MegaCli -LDSetProp -WB -Lall -aALL (re-enable after BBU OK)", "parameters": [], "description": "Recover corrupt blocks and enable Oracle protections against RAID cache failures"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13232	oracle	instruct	ora_coordinate_firmware_update_and_recover	{"sql": "-- 1. RMAN recovery for corrupt blocks:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- 2. Enable maximum Oracle-level protection during firmware update:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\nALTER SYSTEM SET DB_BLOCK_CHECKING = FULL SCOPE=BOTH;\\n\\n-- 3. Coordinate with storage team:\\n-- a. Check current firmware versions against vendor known-issue lists\\n-- b. Download certified firmware from Oracle MOS (My Oracle Support) or storage vendor\\n-- c. Schedule maintenance window for firmware update\\n-- d. For ASM: use rolling firmware update to avoid downtime\\n--    ALTER DISKGROUP data OFFLINE DISK disk_on_controller_1;\\n--    -- Update firmware on controller 1\\n--    ALTER DISKGROUP data ONLINE DISK disk_on_controller_1;\\n--    -- Repeat for controller 2\\n\\n-- 4. Post-firmware RMAN validate:\\n-- RMAN> BACKUP VALIDATE CHECK LOGICAL DATABASE;", "parameters": [], "description": "Coordinate storage firmware update with recovery and Oracle protection during the process"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13238	oracle	execute	ora_recover_and_configure_vm_properly	{"sql": "-- Recover corrupt blocks:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n-- If extensive corruption, point-in-time recovery may be needed:\\n-- RMAN> RESTORE DATABASE UNTIL SCN <last_known_good_scn>;\\n-- RMAN> RECOVER DATABASE UNTIL SCN <last_known_good_scn>;\\n-- ALTER DATABASE OPEN RESETLOGS;\\n\\n-- Enable Oracle protections:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\nALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH;\\n\\n-- VM configuration requirements (coordinate with VM admin):\\n-- 1. Disable VM-level snapshots for Oracle VMs (use RMAN instead)\\n-- 2. Use thick-provisioned eager-zeroed disks\\n-- 3. Use PVSCSI adapter (not LSI Logic)\\n-- 4. Set disk.EnableUUID = TRUE\\n-- 5. Reserve memory (no memory ballooning)\\n-- 6. Use RDM (Raw Device Mapping) or direct ASM for best I/O\\n-- 7. Disable DRS/vMotion during backups\\n-- 8. Enable multi-writer flag ONLY for RAC shared disks", "parameters": [], "description": "Recover database and configure VM environment per Oracle best practices for virtualization"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13241	oracle	instruct	ora_apply_kernel_fix_and_recover	{"sql": "-- 1. Recover corrupt Oracle blocks:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- 2. Enable Oracle-level protections:\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\nALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH;\\nALTER SYSTEM SET FILESYSTEMIO_OPTIONS = SETALL SCOPE=SPFILE;\\n\\n-- 3. OS-level remediation (coordinate with OS admin):\\n-- a. Check Oracle MOS for certified kernel versions\\n-- b. Apply latest kernel patches (UEK for Oracle Linux)\\n-- c. Set recommended kernel parameters:\\n--    vm.swappiness = 1\\n--    vm.dirty_background_ratio = 3\\n--    vm.dirty_ratio = 15\\n--    vm.dirty_expire_centisecs = 500\\n--    vm.dirty_writeback_centisecs = 100\\n-- d. Disable transparent huge pages (THP):\\n--    echo never > /sys/kernel/mm/transparent_hugepage/enabled\\n-- e. Use Oracle-recommended I/O scheduler:\\n--    echo deadline > /sys/block/sda/queue/scheduler\\n\\n-- 4. Post-patch: full RMAN validate\\n-- RMAN> BACKUP VALIDATE CHECK LOGICAL DATABASE;", "parameters": [], "description": "Apply kernel patches and Oracle-recommended OS tuning, then recover corrupt blocks"}	\N	medium	t	t	hours	2026-02-28 22:39:08.596677
13936	oracle	instruct	ora_convert_to_direct_path_load	{"sql": "ALTER TABLE target_table NOLOGGING;\\nINSERT /*+ APPEND */ INTO target_table SELECT * FROM source_table;\\nCOMMIT;\\nALTER TABLE target_table LOGGING;", "parameters": ["target_table", "source_table"], "description": "Convert large bulk inserts to direct-path (APPEND hint) with NOLOGGING to minimize redo generation"}	{"sql": "ALTER TABLE target_table LOGGING", "description": "Re-enable logging on the target table"}	medium	t	f	minutes	2026-02-28 22:39:08.596677
13244	oracle	execute	ora_apply_patch_and_recover	{"sql": "-- 1. Recover corrupt blocks first:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- 2. Apply Oracle Release Update (RU) or one-off patch:\\n-- $ORACLE_HOME/OPatch/opatch lsinventory (check current patches)\\n-- Download patch from Oracle MOS\\n-- Apply with OPatch:\\n-- cd $ORACLE_HOME\\n-- $ORACLE_HOME/OPatch/opatch apply /path/to/patch_dir\\n-- Run datapatch after patching:\\n-- $ORACLE_HOME/OPatch/datapatch -verbose\\n\\n-- 3. For RAC, use rolling patch:\\n-- opatchauto apply /path/to/patch_dir\\n\\n-- 4. Enable corruption detection:\\nALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH;\\nALTER SYSTEM SET DB_BLOCK_CHECKSUM = FULL SCOPE=BOTH;\\n\\n-- 5. Post-patch validation:\\n-- RMAN> BACKUP VALIDATE CHECK LOGICAL DATABASE;\\n-- Run utlrp.sql to recompile invalid objects:\\n-- @?/rdbms/admin/utlrp.sql", "parameters": [], "description": "Apply Oracle patch to fix the bug, recover corrupt data, and enable detection"}	{"sql": "$ORACLE_HOME/OPatch/opatch rollback -id <patch_id>", "description": ""}	medium	t	t	hours	2026-02-28 22:39:08.596677
13253	oracle	execute	ora_restore_manipulated_files	{"sql": "-- Restore affected files from RMAN backup:\\n-- RMAN> RESTORE DATAFILE <file#>;\\n-- RMAN> RECOVER DATAFILE <file#>;\\n-- ALTER DATABASE DATAFILE <file#> ONLINE;\\n\\n-- If only blocks are corrupt (not entire file):\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- Prevent future manual manipulation:\\n-- 1. Set file permissions to oracle:oinstall only:\\n-- chmod 640 /path/to/datafiles/*.dbf\\n-- 2. Use immutable flag where supported:\\n-- chattr +i /path/to/critical_controlfile (Linux)\\n\\n-- Enable Oracle auditing for file operations:\\nAUDIT ALTER DATABASE BY ACCESS;\\nAUDIT ALTER TABLESPACE BY ACCESS;\\n\\n-- Document proper file operations:\\n-- WRONG: cp /old/data01.dbf /new/data01.dbf (while DB is open)\\n-- RIGHT: RMAN> BACKUP AS COPY DATAFILE <file#> FORMAT '/new/data01.dbf';\\n-- RIGHT: ALTER DATABASE MOVE DATAFILE '/old/data01.dbf' TO '/new/data01.dbf';", "parameters": [], "description": "Restore affected files from RMAN backup and implement controls to prevent future manual manipulation"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13256	oracle	execute	ora_stop_propagation_and_recover	{"sql": "-- If corruption originated on primary, recover primary first:\\n-- RMAN> RECOVER CORRUPTION LIST;\\n\\n-- If standby has clean copy, recover FROM standby:\\n-- RMAN> RECOVER DATAFILE <file#> BLOCK <block#> FROM SERVICE standby_tns;\\n\\n-- Enable lost write detection:\\nALTER SYSTEM SET DB_LOST_WRITE_PROTECT = TYPICAL SCOPE=BOTH;\\n\\n-- For GoldenGate corruption propagation:\\n-- Stop affected replication processes:\\n-- GGSCI> STOP EXTRACT <ext_name>\\n-- GGSCI> STOP REPLICAT <rep_name>\\n-- Fix source data, then resync:\\n-- GGSCI> ALTER REPLICAT <rep_name>, BEGIN <timestamp_before_corruption>\\n-- GGSCI> START REPLICAT <rep_name>\\n\\n-- Enable Data Guard block checking on redo apply:\\n-- On standby: ALTER SYSTEM SET DB_BLOCK_CHECKING = MEDIUM SCOPE=BOTH;\\n-- Enable validate on standby apply:\\n-- ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT;", "parameters": [], "description": "Stop corruption propagation, recover from clean source, and enable replication-level protections"}	\N	medium	t	f	hours	2026-02-28 22:39:08.596677
13286	oracle	execute	ora_apply_interim_workarounds	{"sql": "-- Common Oracle interim workarounds:\\n-- 1. NETWORK RESTRICTION (for network-exploitable CVEs):\\n-- Edit sqlnet.ora:\\n-- TCP.VALIDNODE_CHECKING = YES\\n-- TCP.INVITED_NODES = (known_app_server1, known_app_server2)\\n-- TCP.EXCLUDED_NODES = (untrusted_network)\\n-- Reload listener: lsnrctl reload\\n\\n-- 2. DISABLE AFFECTED FEATURE (if not critical):\\n-- Example: Disable Java in database:\\n-- EXEC DBMS_JAVA.REVOKE_PERMISSION('rootcause', 'SYS:java.net.SocketPermission', '*', 'connect,resolve');\\n-- Example: Disable XML DB:\\n-- ALTER SYSTEM SET DISPATCHERS='' SCOPE=BOTH;\\n\\n-- 3. ENHANCED AUDITING:\\nAUDIT ALL BY ACCESS;\\nAUDIT CREATE SESSION BY ACCESS;\\n-- Enable Unified Auditing for granular tracking:\\n-- CREATE AUDIT POLICY vuln_monitor ACTIONS ALL ON <affected_objects>;\\n-- AUDIT POLICY vuln_monitor;\\n\\n-- 4. RESTRICT PRIVILEGES:\\n-- Revoke unnecessary rootcause grants:\\nREVOKE EXECUTE ON UTL_TCP FROM rootcause;\\nREVOKE EXECUTE ON UTL_HTTP FROM rootcause;\\nREVOKE EXECUTE ON UTL_SMTP FROM rootcause;\\nREVOKE EXECUTE ON UTL_FILE FROM rootcause;\\nREVOKE EXECUTE ON DBMS_LDAP FROM rootcause;\\n\\n-- 5. ENHANCED MONITORING:\\n-- Watch for exploitation attempts in audit trail", "parameters": [], "description": "Apply interim workarounds including network restrictions, feature disablement, and enhanced auditing"}	{"sql": "GRANT EXECUTE ON UTL_TCP TO rootcause; GRANT EXECUTE ON UTL_HTTP TO rootcause; GRANT EXECUTE ON UTL_SMTP TO rootcause; GRANT EXECUTE ON UTL_FILE TO rootcause; GRANT EXECUTE ON DBMS_LDAP TO rootcause;", "description": ""}	medium	t	t	minutes	2026-02-28 22:39:08.596677
13339	oracle	execute	ora_apply_hot_block_mitigation	{"sql": "-- For index hot blocks: CREATE INDEX {owner}.{idx}_rev ON {table}({cols}) REVERSE ONLINE;\\n-- For sequence hot blocks: ALTER SEQUENCE {seq} CACHE 1000;\\n-- For table hot blocks: ALTER TABLE {table} MOVE PARTITION BY HASH({col}) PARTITIONS 16 ONLINE;", "parameters": ["owner", "table", "cols"], "description": "Apply appropriate mitigation based on hot block type: reverse key indexes, increased sequence caching, or hash partitioning"}	{"sql": "-- Reverse: rebuild as non-reverse index\\n-- Partitioning: requires table reorganization", "description": "Reversing structural changes requires index rebuild or table reorganization"}	medium	t	t	minutes	2026-02-28 22:39:08.596677
13358	oracle	configure	ora_adjust_checkpoint_parameters	{"sql": "ALTER SYSTEM SET FAST_START_MTTR_TARGET = 600 SCOPE=BOTH;\\n-- Consider increasing redo log size if too small:\\n-- ALTER DATABASE ADD LOGFILE GROUP 4 SIZE 2G;\\n-- ALTER DATABASE ADD LOGFILE GROUP 5 SIZE 2G;", "parameters": ["mttr_target"], "description": "Set FAST_START_MTTR_TARGET to 600 seconds (10 min) to reduce aggressive incremental checkpointing"}	{"sql": "ALTER SYSTEM SET FAST_START_MTTR_TARGET = 300 SCOPE=BOTH", "description": "Revert MTTR target to previous value"}	medium	t	t	seconds	2026-02-28 22:39:08.596677
