26938	mysql	configure	mysql_correct_replication_filter_rules	{"sql": "-- Remove all existing channel-specific filters and reconfigure correctly\\nSTOP REPLICA SQL_THREAD;\\n\\n-- Clear incorrect filters (empty string removes the filter)\\nCHANGE REPLICATION FILTER\\n  REPLICATE_DO_DB = (),\\n  REPLICATE_IGNORE_DB = (),\\n  REPLICATE_DO_TABLE = (),\\n  REPLICATE_IGNORE_TABLE = ()\\nFOR CHANNEL '';\\n\\n-- Apply corrected filter rules (example: ignore specific databases)\\nCHANGE REPLICATION FILTER\\n  REPLICATE_IGNORE_DB = (test, temp_database)\\nFOR CHANNEL '';\\n\\n-- Verify filters are applied\\nSELECT FILTER_NAME, FILTER_RULE\\nFROM performance_schema.replication_applier_filters;\\n\\nSTART REPLICA SQL_THREAD;", "parameters": {"ignored_databases": "Databases that should legitimately be excluded from replication", "replicated_databases": "Databases that must be replicated"}, "description": "Clear incorrect replication filter rules and apply the corrected configuration using CHANGE REPLICATION FILTER, which can be done dynamically without restarting the replica."}	{"sql": "STOP REPLICA SQL_THREAD;\\nCHANGE REPLICATION FILTER REPLICATE_IGNORE_DB = () FOR CHANNEL '';\\nSTART REPLICA SQL_THREAD;", "description": ""}	medium	t	t	5 minutes	2026-03-01 09:33:09.381992
