26974	mysql	configure	mysql_migrate_to_group_replication	{"sql": "-- Prerequisites for Group Replication\\nSHOW VARIABLES LIKE 'gtid_mode';          -- Must be ON\\nSHOW VARIABLES LIKE 'enforce_gtid_consistency';  -- Must be ON\\nSHOW VARIABLES LIKE 'binlog_format';       -- Must be ROW\\nSHOW VARIABLES LIKE 'log_replica_updates'; -- Must be ON\\n\\n-- Install Group Replication plugin\\nINSTALL PLUGIN group_replication SONAME 'group_replication.so';\\n\\n-- Configure group_replication settings (my.cnf):\\n-- plugin_load_add = group_replication.so\\n-- group_replication_group_name = '<UUID>'\\n-- group_replication_start_on_boot = OFF\\n-- group_replication_local_address = '<this_host>:33061'\\n-- group_replication_group_seeds = '<all_hosts>:33061'\\n-- group_replication_single_primary_mode = ON\\n-- group_replication_enforce_update_everywhere_checks = OFF", "parameters": null, "description": "Configure prerequisites for Group Replication (GTID, ROW format, log_replica_updates) and install the Group Replication plugin."}	{"sql": "UNINSTALL PLUGIN group_replication;", "description": ""}	medium	t	t	60 minutes	2026-03-01 09:33:09.381992
26975	mysql	execute	mysql_bootstrap_group_replication	{"sql": "-- On primary node only: bootstrap the group\\nSET GLOBAL group_replication_bootstrap_group = ON;\\nSTART GROUP_REPLICATION;\\nSET GLOBAL group_replication_bootstrap_group = OFF;\\n\\n-- Verify primary bootstrapped\\nSELECT\\n  MEMBER_HOST,\\n  MEMBER_STATE,\\n  MEMBER_ROLE\\nFROM performance_schema.replication_group_members;\\n\\n-- On each secondary node, create recovery user and join:\\n-- CHANGE REPLICATION SOURCE TO SOURCE_USER='replication_user',\\n--   SOURCE_PASSWORD='<pw>' FOR CHANNEL 'group_replication_recovery';\\n-- START GROUP_REPLICATION;", "parameters": null, "description": "Bootstrap Group Replication on the primary node and add all secondary nodes to establish Paxos consensus."}	{"sql": "STOP GROUP_REPLICATION; UNINSTALL PLUGIN group_replication;", "description": ""}	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
26995	mysql	execute	mysql_handle_gtid_mismatch	{"sql": "-- If GTID mismatch error (ER_SLAVE_HAS_MORE_GTIDS_THAN_MASTER):\\n-- Check what GTIDs replica has vs primary\\nSELECT @@global.gtid_executed AS replica_gtid_executed;\\n-- On primary: SELECT @@global.gtid_executed AS primary_gtid_executed;\\n\\n-- If replica has extra GTIDs not on primary (misconfiguration),\\n-- reset and re-sync:\\nSTOP REPLICA;\\nRESET REPLICA ALL;\\nRESET BINARY LOGS AND GTIDS;\\n\\n-- Then set gtid_purged to match primary's gtid_executed:\\nSET GLOBAL gtid_purged = '<primary_gtid_executed>';\\n\\n-- Reconfigure and start:\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_HOST = '<primary_host>',\\n  SOURCE_AUTO_POSITION = 1;\\nSTART REPLICA;", "parameters": null, "description": "Resolve GTID mismatch by resetting replica GTID state and re-synchronizing with the primary's GTID set."}	\N	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
27000	mysql	execute	mysql_clone_replica_from_primary	{"sql": "-- Use MySQL Clone Plugin for fast re-provisioning (MySQL 8.0.17+)\\n-- On replica:\\n\\n-- Install Clone plugin if not present\\nINSTALL PLUGIN clone SONAME 'mysql_clone.so';\\n\\n-- Create clone user on primary:\\n-- CREATE USER 'clone_user'@'%' IDENTIFIED BY '<password>';\\n-- GRANT BACKUP_ADMIN, REPLICATION CLIENT ON *.* TO 'clone_user'@'%';\\n-- GRANT CLONE_ADMIN ON *.* TO 'clone_user'@'%';\\n\\n-- Execute remote clone (will restart the replica and sync from primary)\\nCLONE INSTANCE FROM 'clone_user'@'<primary_host>':3306\\n  IDENTIFIED BY '<password>';\\n\\n-- Note: Clone replaces all data and automatically configures replica position\\n-- MySQL will restart after clone completes\\n\\nSHOW VARIABLES LIKE 'clone_status';", "parameters": null, "description": "Re-provision the stale replica using MySQL Clone Plugin to perform a fast, consistent snapshot from the primary."}	\N	medium	t	f	60 minutes	2026-03-01 09:33:09.381992
