27031	mysql	configure	mysql_reduce_semisync_replica_quorum	{"sql": "-- Reduce required acknowledgments to 1 (fastest replica)\\n-- This trades broader durability guarantee for lower commit latency\\nSET GLOBAL rpl_semi_sync_source_wait_for_replica_count = 1;\\n\\n-- Convert slower replicas to async to remove them from quorum\\n-- On each slow replica that should become async:\\n-- STOP REPLICA IO_THREAD;\\n-- UNINSTALL PLUGIN rpl_semi_sync_replica;\\n-- START REPLICA IO_THREAD;\\n\\n-- Persist primary setting in my.cnf:\\n-- [mysqld]\\n-- rpl_semi_sync_source_wait_for_replica_count = 1", "parameters": null, "description": "Sets the semi-sync quorum to require acknowledgment from only the fastest replica, reducing the chance of timeout caused by a slow outlier"}	{"sql": "SET GLOBAL rpl_semi_sync_source_wait_for_replica_count = <previous_value>;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
