27073	mysql	execute	mysql_add_primary_keys_to_keyless_tables	{"sql": "-- Add auto-increment primary key to tables lacking one\\n-- Replace <schema> and <table> with identified tables from step 1\\n-- Option A: Add surrogate key (non-intrusive, adds a new column)\\nALTER TABLE <schema>.<table> ADD COLUMN id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY;\\n\\n-- Option B: Promote existing unique column to primary key if one exists\\n-- ALTER TABLE <schema>.<table> ADD PRIMARY KEY (<unique_column>);\\n\\n-- Option C: Use an invisible primary key (MySQL 8.0.30+)\\n-- ALTER TABLE <schema>.<table> ADD COLUMN id BIGINT NOT NULL AUTO_INCREMENT INVISIBLE PRIMARY KEY;\\n\\n-- Confirm the primary key was created\\nSHOW CREATE TABLE <schema>.<table>\\\\G", "parameters": null, "description": "Adds a primary key to each table that lacks one so the replication SQL thread can precisely locate rows for UPDATE and DELETE operations"}	{"sql": "ALTER TABLE <schema>.<table> DROP PRIMARY KEY;\\nALTER TABLE <schema>.<table> DROP COLUMN id;", "description": ""}	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
27077	mysql	execute	mysql_resolve_constraint_violation_on_subscriber	{"sql": "-- Stop the SQL thread\\nSTOP REPLICA SQL_THREAD;\\n\\n-- Option A: For FK violation — ensure parent row exists before the child is inserted\\n-- Insert the missing parent row:\\nINSERT INTO <schema>.<parent_table> (<pk_col>, ...) VALUES (<pk_value>, ...);\\n\\n-- Option B: For unique constraint — delete the conflicting row\\nDELETE FROM <schema>.<table> WHERE <unique_col> = <conflict_value>;\\n\\n-- Option C: For check constraint — update the violating row to satisfy the constraint\\nUPDATE <schema>.<table> SET <col> = <valid_value> WHERE <pk_col> = <pk_value>;\\n\\n-- Resume replication\\nSTART REPLICA SQL_THREAD;\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Resolves the specific constraint violation by inserting missing parent rows, deleting conflicting rows, or correcting values, then resumes replication"}	\N	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
27080	mysql	execute	mysql_disable_problematic_triggers_on_subscriber	{"sql": "-- In MySQL, triggers cannot be disabled without dropping them\\n-- Option A: Drop the trigger temporarily, fix it, then recreate\\nDROP TRIGGER IF EXISTS <schema>.<trigger_name>;\\n\\n-- Option B: Modify the trigger to handle the error gracefully\\nDELIMITER //\\nCREATE OR REPLACE TRIGGER <trigger_name>\\nAFTER INSERT ON <schema>.<table>\\nFOR EACH ROW\\nBEGIN\\n  -- Add conditional logic to prevent failure during replication\\n  IF @SESSION.pseudo_slave_mode = 0 THEN\\n    -- Original trigger body here\\n    INSERT INTO audit_log (action, table_name, row_id) VALUES ('INSERT', '<table>', NEW.id);\\n  END IF;\\nEND //\\nDELIMITER ;\\n\\n-- Restart SQL thread\\nSTOP REPLICA SQL_THREAD;\\nSTART REPLICA SQL_THREAD;\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Drops or modifies the failing trigger to prevent it from interfering with replication apply, using pseudo_slave_mode to detect replication context"}	\N	medium	t	t	15 minutes	2026-03-01 09:33:09.381992
27083	mysql	execute	mysql_apply_missing_ddl_on_subscriber	{"sql": "-- Stop the SQL thread\\nSTOP REPLICA SQL_THREAD;\\n\\n-- Apply the missing DDL on the subscriber to bring schema in sync with primary\\n-- Replace with the actual ALTER TABLE from step 1 comparison\\nALTER TABLE <schema>.<table> ADD COLUMN <new_column> <data_type> [DEFAULT value];\\n-- Or:\\nALTER TABLE <schema>.<table> ADD INDEX <index_name> (<column>);\\n-- Or:\\nCREATE TABLE IF NOT EXISTS <schema>.<table> LIKE <source_definition>;\\n\\n-- Verify schema now matches primary\\nSHOW CREATE TABLE <schema>.<table>\\\\G\\n\\n-- If GTID: skip the DDL transaction that failed\\n-- SET GTID_NEXT='<failed_gtid>'; BEGIN; COMMIT; SET GTID_NEXT='AUTOMATIC';\\n\\n-- Resume replication\\nSTART REPLICA SQL_THREAD;\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Applies the missing DDL changes to the subscriber manually to align its schema with the primary, then resumes replication"}	\N	medium	t	f	20 minutes	2026-03-01 09:33:09.381992
