27450	mysql	execute	mysql_configure_binlog_backup_schedule	{"sql": "-- Set binary log retention (MySQL 8.0+):\\nSET GLOBAL binlog_expire_logs_seconds = 604800;\\n-- Older MySQL:\\nSET GLOBAL expire_logs_days = 7;\\n\\n-- Manually purge old logs if disk is critical:\\nPURGE BINARY LOGS BEFORE DATE_SUB(NOW(), INTERVAL 3 DAY);\\n\\n-- Archive binary logs via cron (mysqlbinlog streaming):\\n-- 0 */1 * * * mysqlbinlog --read-from-remote-server --host=localhost --raw --to-last-log mysql-bin.current > /backup/binlogs/\\n\\n-- Or use xtrabackup incremental backups for integrated binlog archiving", "parameters": {"binlog_expire_logs_seconds": "604800 (7 days)"}, "description": "Configure binary log retention and set up regular binary log archival to an off-server backup destination."}	{"sql": "SET GLOBAL binlog_expire_logs_seconds = <original>;", "description": ""}	medium	t	t	15m	2026-03-01 09:33:09.381992
27456	mysql	execute	mysql_repair_replication_or_reset	{"sql": "-- Option A: Restart stopped replication threads on replica\\nSTART REPLICA;\\n-- Or restart specific threads:\\nSTART REPLICA IO_THREAD;\\nSTART REPLICA SQL_THREAD;\\n\\n-- Option B: If replica is irreparably broken, reset and re-initialize\\n-- (run on replica after taking fresh snapshot from source)\\nSTOP REPLICA;\\nRESET REPLICA ALL;\\n-- Then re-configure using CHANGE REPLICATION SOURCE TO ...\\n\\n-- Option C: If no replica exists, configure binlog expiry on source\\nSET GLOBAL binlog_expire_logs_seconds = 604800; -- 7 days\\nPURGE BINARY LOGS BEFORE DATE_SUB(NOW(), INTERVAL 7 DAY);", "parameters": null, "description": "Restarts replication threads if stopped, or resets and reconfigures replication if broken. If no replica is needed, sets binlog expiry and purges old logs."}	{"sql": "STOP REPLICA;", "description": ""}	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
27501	mysql	execute	mysql_patch_remaining_nodes	{"sql": "-- Pre-patch: verify node is in good standing\\nSHOW REPLICA STATUS\\\\G  -- Verify no replication errors\\nSHOW PROCESSLIST;       -- No long-running transactions\\n\\n-- On primary: verify replica is caught up before patching replica\\n-- (Check Seconds_Behind_Source = 0 on replica)\\n\\n-- Patching process (run as OS commands, not SQL):\\n-- 1. Remove node from load balancer\\n-- 2. For replica: STOP REPLICA; on that node\\n-- 3. Apply MySQL patch (OS package manager)\\n-- 4. Start MySQL service\\n-- 5. Run mysql_upgrade if upgrading minor versions\\n-- 6. START REPLICA;\\n-- 7. Verify replication caught up\\n-- 8. Re-add to load balancer\\n\\n-- Verify after patching:\\nSELECT VERSION() AS new_version;", "parameters": null, "description": "Executes the patch on each remaining unpatched node using a safe rolling procedure that maintains replication integrity."}	{"sql": "STOP REPLICA; -- If patched replica has issues, stop replication and investigate", "description": ""}	medium	t	f	30 minutes per node	2026-03-01 09:33:09.381992
27507	mysql	execute	mysql_remove_stale_node_from_cluster	{"sql": "-- For Group Replication: force removal of unreachable member\\n-- (Run on a surviving PRIMARY member)\\nSET GLOBAL group_replication_force_members = '10.0.0.1:33061,10.0.0.2:33061'; \\n-- List only the surviving healthy members' address:xcom_port\\n\\n-- After forcing quorum, stop and reset the decommissioned node's participation:\\n-- On surviving nodes, remove stale peer from allowlist if configured\\nSET GLOBAL group_replication_ip_allowlist = '10.0.0.1,10.0.0.2'; -- Remove stale host\\n\\n-- For MySQL InnoDB Cluster (via MySQL Shell):\\n-- cluster.removeInstance('host:port', {force: true})\\n\\n-- Verify surviving members after removal\\nSELECT MEMBER_HOST, MEMBER_STATE, MEMBER_VERSION\\nFROM performance_schema.replication_group_members;", "parameters": null, "description": "Forces removal of the stale decommissioned node from Group Replication cluster membership to restore consistent cluster state."}	{"sql": "SET GLOBAL group_replication_force_members = ''; -- Reset to allow normal election", "description": ""}	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
27510	mysql	execute	mysql_patch_and_rejoin_isolated_node	{"sql": "-- Step 1: Apply missing patch on isolated node (OS-level)\\n-- yum update mysql-server  OR  apt upgrade mysql-server-8.0\\n\\n-- Step 2: Restart Group Replication on isolated node after patching\\nSTOP GROUP_REPLICATION;\\n-- (After OS patch and MySQL restart)\\nSTART GROUP_REPLICATION;\\n\\n-- Step 3: If auto-rejoin fails, manually set group seeds\\nSET GLOBAL group_replication_group_seeds = '10.0.0.1:33061,10.0.0.2:33061';\\nSET GLOBAL group_replication_local_address = '10.0.0.3:33061';\\nSTART GROUP_REPLICATION;\\n\\n-- Monitor rejoin progress\\nSELECT MEMBER_HOST, MEMBER_STATE\\nFROM performance_schema.replication_group_members;", "parameters": null, "description": "Applies the missing patch to the isolated node and rejoins it to the Group Replication cluster using the distributed recovery mechanism."}	{"sql": "STOP GROUP_REPLICATION;", "description": ""}	medium	t	f	20 minutes	2026-03-01 09:33:09.381992
27513	mysql	execute	mysql_resync_node_via_clone_or_recovery	{"sql": "-- Option A: Trigger automatic distributed recovery\\nSTOP GROUP_REPLICATION;\\nSET GLOBAL group_replication_recovery_use_ssl = ON;\\nSTART GROUP_REPLICATION;\\n-- Node should enter RECOVERING state and catch up automatically\\n\\n-- Option B: For large gaps, use MySQL Clone Plugin\\n-- On donor node: INSTALL PLUGIN clone SONAME 'mysql_clone.so';\\n-- On recipient: INSTALL PLUGIN clone SONAME 'mysql_clone.so';\\n-- CLONE INSTANCE FROM 'clone_user'@'10.0.0.1':3306 IDENTIFIED BY 'password';\\n\\n-- Monitor recovery progress\\nSELECT STAGE, STATE, ESTIMATE, DATA, BINLOG_FILE, BINLOG_POSITION\\nFROM performance_schema.clone_status;", "parameters": null, "description": "Resyncs the out-of-sync node using Group Replication distributed recovery or MySQL Clone Plugin for large gaps, then re-patches to match the cluster."}	{"sql": "STOP GROUP_REPLICATION;", "description": ""}	medium	t	f	30-60 minutes	2026-03-01 09:33:09.381992
