27577	mysql	execute	mysql_apply_patch_with_no_active_users	{"sql": "-- With connections drained, apply the patch:\\n-- Flush all tables and acquire read lock:\\nFLUSH TABLES WITH READ LOCK;\\n-- Verify no active transactions:\\nSELECT COUNT(*) FROM information_schema.INNODB_TRX;\\n-- If 0 transactions, proceed with shutdown:\\nSET GLOBAL innodb_fast_shutdown = 0;\\nSHUTDOWN;\\n-- From OS shell:\\n-- sudo rpm -Uvh mysql-community-server-8.0.x.rpm\\n-- systemctl start mysql\\n-- Restore max_connections after start:\\n-- SET GLOBAL max_connections = 151;", "parameters": null, "description": "With all user activity drained, acquire a read lock, perform a clean shutdown, and apply the patch."}	{"sql": "Restart MySQL with previous version packages; restore from backup if upgrade fails.", "description": ""}	medium	t	f	20 minutes	2026-03-01 09:33:09.381992
27621	mysql	execute	mysql_optimize_bloated_tables	{"sql": "-- OPTIMIZE TABLE reclaims dead row space (rebuilds table)\\n-- WARNING: Table-level lock on MySQL without online DDL\\n-- For large tables use: ALTER TABLE t ENGINE=InnoDB; (supports ALGORITHM=INPLACE)\\n\\n-- Example for identified bloated table:\\n-- OPTIMIZE TABLE bloated_table;\\n\\n-- Or use online rebuild:\\n-- ALTER TABLE bloated_table ENGINE=InnoDB, ALGORITHM=INPLACE, LOCK=NONE;\\n\\n-- Check progress\\nSELECT EVENT_NAME, WORK_COMPLETED, WORK_ESTIMATED\\nFROM performance_schema.events_stages_current\\nWHERE EVENT_NAME LIKE '%alter%';", "parameters": null, "description": "Rebuild bloated tables to reclaim dead row space; use online ALTER TABLE for large tables"}	\N	medium	t	f	30 minutes	2026-03-01 09:33:09.381992
27628	mysql	configure	mysql_rightsize_buffer_pool	{"sql": "-- Reduce buffer pool to leave OS headroom (target: 70-80% of RAM)\\n-- Dynamically resize without restart (MySQL 5.7.5+)\\nSET GLOBAL innodb_buffer_pool_size = 4294967296; -- Example: 4GB, adjust to 70-80% of RAM\\n\\n-- Reduce per-connection buffers to lower peak memory\\nSET GLOBAL sort_buffer_size = 1048576;    -- 1MB (default is often too high)\\nSET GLOBAL read_buffer_size = 131072;     -- 128KB\\nSET GLOBAL join_buffer_size = 262144;     -- 256KB\\n\\n-- Check resize progress\\nSHOW STATUS LIKE 'Innodb_buffer_pool_resize_status';", "parameters": null, "description": "Resize InnoDB buffer pool and per-connection buffers to prevent system-level memory overcommitment"}	{"sql": "SET GLOBAL innodb_buffer_pool_size = <original_value>;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
