28727	mysql	execute	mysql_relieve_global_memory_pressure	{"sql": "-- Reduce InnoDB buffer pool to free memory for query execution\\nSET GLOBAL innodb_buffer_pool_size = <reduced_value>;\\n\\n-- Reduce InnoDB change buffer\\nSET GLOBAL innodb_change_buffer_max_size = 10;  -- Default 25%\\n\\n-- Reduce per-session allocations\\nSET GLOBAL read_rnd_buffer_size = 262144;  -- 256KB (default varies)\\n\\n-- Kill any memory-intensive orphaned queries\\nSELECT CONCAT('KILL ', ID, ';') FROM information_schema.PROCESSLIST WHERE COMMAND != 'Sleep' AND TIME > 600;", "parameters": {"reduced_value": "Target 65-70% of total RAM, down from current setting", "innodb_change_buffer_max_size": "10% to free memory from change buffer"}, "description": "Free global memory by reducing InnoDB buffer pool and change buffer sizes. Reduce per-session read buffers and kill memory-intensive long-running queries to restore memory availability."}	{"sql": "SET GLOBAL innodb_buffer_pool_size = <original_value>;\\nSET GLOBAL innodb_change_buffer_max_size = 25;\\nSET GLOBAL read_rnd_buffer_size = <original_value>;", "description": ""}	medium	t	t	15m	2026-03-01 09:33:09.381992
28745	mysql	execute	mysql_implement_table_partitioning	{"sql": "-- Create partitioned copy: CREATE TABLE large_table_part LIKE large_table; ALTER TABLE large_table_part PARTITION BY RANGE (YEAR(created_at)) ( PARTITION p2023 VALUES LESS THAN (2024), PARTITION p2024 VALUES LESS THAN (2025), PARTITION p2025 VALUES LESS THAN (2026), PARTITION p_future VALUES LESS THAN MAXVALUE ); INSERT INTO large_table_part SELECT * FROM large_table; RENAME TABLE large_table TO large_table_old, large_table_part TO large_table;", "parameters": {"partition_type": "RANGE", "partition_column": "created_at"}, "description": "Partition by date range (most common use case). Copy data into partitioned table and rename to minimize downtime. Alternatively use pt-online-schema-change."}	{"sql": "RENAME TABLE large_table TO large_table_part, large_table_old TO large_table;", "description": ""}	medium	t	t	120m	2026-03-01 09:33:09.381992
28825	mysql	execute	mysql_stabilize_plans_post_upgrade	{"sql": "-- Option 1: Rebuild statistics after upgrade\\nANALYZE TABLE your_table;\\nANALYZE TABLE your_table UPDATE HISTOGRAM ON col WITH 256 BUCKETS;\\n\\n-- Option 2: Disable new optimizer features causing regressions\\n-- (identify which feature from EXPLAIN comparison)\\nSET GLOBAL optimizer_switch = 'hash_join=off';  -- if hash join is regressing\\nSET GLOBAL optimizer_switch = 'derived_merge=off';\\n\\n-- Option 3: Use optimizer hints to lock critical query plans\\nSELECT /*+ NO_HASH_JOIN(t1 t2) INDEX(t1 idx_col) */ *\\nFROM t1 JOIN t2 ON t1.id = t2.t1_id WHERE t1.col = 'value';\\n\\n-- Option 4: Create a query rewrite plugin rule to apply hints automatically\\n-- (MySQL Enterprise) or modify application queries\\n\\n-- Option 5: Use performance schema to capture worst offenders\\nSELECT * FROM sys.statements_with_runtimes_in_95th_percentile LIMIT 20;", "parameters": {}, "description": "Stabilise post-upgrade query plans by refreshing statistics, selectively disabling optimizer features that produce regressions, and applying optimizer hints to lock plans for critical queries."}	{"sql": "SET GLOBAL optimizer_switch = DEFAULT;", "description": ""}	medium	t	t	60m	2026-03-01 09:33:09.381992
29059	mysql	execute	mysql_fix_lock_wait_blocker	{"sql": "-- Kill the blocking transaction if safe to do so\\n-- KILL <blocking_thread_id>;\\n\\n-- Increase lock wait timeout to reduce cascade failures\\nSET GLOBAL innodb_lock_wait_timeout = 50;\\n\\n-- For recurring lock conflicts, add indexes to reduce lock scope\\n-- Gap locks and next-key locks are reduced with more selective indexes\\nALTER TABLE <table> ADD INDEX idx_lock_col (<frequently_locked_column>);\\n\\n-- Switch to READ COMMITTED isolation for read-heavy transactions\\n-- reduces gap locking\\nSET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;\\n\\n-- For conflicting write order, establish consistent transaction order in app code\\n-- Always lock tables in alphabetical order or by primary key ascending", "parameters": {}, "description": "Kill the blocking transaction if it is safe. Add indexes to reduce lock scope and consider READ COMMITTED isolation to reduce gap locks for read-heavy transactions."}	{"sql": "SET GLOBAL innodb_lock_wait_timeout = <previous_value>;", "description": ""}	medium	t	f	15m	2026-03-01 09:33:09.381992
29086	mysql	execute	mysql_throttle_bulk_load_operation	{"sql": "-- Option A: Kill and reschedule the ETL job to off-peak hours\\nKILL <etl_thread_id>;\\n\\n-- Option B: Temporarily disable binary logging for the session (requires SUPER)\\n-- Note: This means the data load will not be replicated!\\n-- SET sql_log_bin = 0;  -- session-level, must be re-enabled\\n\\n-- Option C: Switch to minimal logging for bulk loads\\n-- Use INSERT ... VALUES with batches of 1000-5000 rows and commit between batches\\n\\n-- Purge old binary logs to recover disk space\\nPURGE BINARY LOGS BEFORE DATE_SUB(NOW(), INTERVAL 1 DAY);\\n\\n-- Set binlog expiry to prevent future accumulation\\nSET GLOBAL binlog_expire_logs_seconds = 259200;  -- 3 days", "parameters": {"etl_thread_id": "Thread ID of the ETL bulk load session", "binlog_expire_logs_seconds": "259200 (3 days)"}, "description": "Throttle the ETL job (kill and reschedule, or use session-level sql_log_bin=0 if replication is not required for this load). Purge accumulated binary logs and configure automatic expiry."}	{"sql": "If sql_log_bin=0 was used, the loaded data is not in the replica's binary log. Ensure replicas receive the data through another path (e.g., re-run on replicas or restore from backup).", "description": ""}	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
29092	mysql	execute	mysql_resolve_replication_lag	{"sql": "-- Option A: Enable parallel replication to improve apply throughput\\nSET GLOBAL slave_parallel_workers = 4;\\nSET GLOBAL slave_parallel_type = 'LOGICAL_CLOCK';\\n\\n-- Option B: If a replica is permanently broken, remove it and purge logs\\n-- (Only if this replica is not needed)\\n-- PURGE BINARY LOGS TO '<replica_current_log>';\\n\\n-- Restart SQL thread if it is stuck\\nSTOP SLAVE SQL_THREAD;\\nSTART SLAVE SQL_THREAD;\\n\\n-- For MySQL 8.0+:\\n-- STOP REPLICA SQL_THREAD;\\n-- START REPLICA SQL_THREAD;\\n\\n-- If replica is too far behind, rebuild from backup:\\n-- 1. Take backup with mysqldump or xtrabackup\\n-- 2. Restore on replica\\n-- 3. Re-establish replication from the backed-up position", "parameters": {"slave_parallel_type": "LOGICAL_CLOCK", "slave_parallel_workers": "4 (adjust based on available CPU cores)"}, "description": "Enable parallel replication apply threads to increase replica throughput. If the replica SQL thread is stuck, restart it. For severely lagged replicas, consider rebuilding from a fresh backup of the primary."}	{"sql": "Revert parallel workers: SET GLOBAL slave_parallel_workers = 0; SET GLOBAL slave_parallel_type = 'DATABASE';", "description": ""}	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
29184	mysql	execute	mysql_remove_or_secure_test_accounts	{"sql": "-- Drop test accounts that have no production role\\nDROP USER IF EXISTS 'testuser'@'%';\\nDROP USER IF EXISTS 'dev'@'%';\\nDROP USER IF EXISTS 'test'@'localhost';\\n-- For accounts needed in production: set a strong password instead\\nALTER USER '<retained_user>'@'<host>' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\nFLUSH PRIVILEGES;", "parameters": {}, "description": "Drop test accounts that have no legitimate production purpose. For accounts that must be retained, assign a strong password immediately."}	{"sql": "CREATE USER '<dropped_user>'@'<host>' IDENTIFIED WITH caching_sha2_password BY '<password>'; GRANT ... ON ... TO '<dropped_user>'@'<host>'; FLUSH PRIVILEGES;", "description": ""}	medium	t	f	10m	2026-03-01 09:33:09.381992
29095	mysql	execute	mysql_resolve_prepared_xa_transactions	{"sql": "-- Roll back an orphaned XA transaction\\n-- Replace <xid> with the XID from XA RECOVER output\\nXA ROLLBACK '<xid>';\\n\\n-- Or commit it if the distributed transaction should have committed\\nXA COMMIT '<xid>';\\n\\n-- For each prepared transaction found in XA RECOVER, execute the appropriate action\\n-- Example with formatID:\\nXA ROLLBACK X'<gtrid_hex>', X'<bqual_hex>', <formatID>;\\n\\n-- After resolving, verify history list is declining\\nSHOW GLOBAL STATUS LIKE 'Innodb_history_list_length';", "parameters": {"xid": "XID from XA RECOVER output"}, "description": "Roll back or commit each orphaned XA transaction identified in the diagnostic step. The decision to commit vs. rollback must be coordinated with the distributed transaction coordinator or application owner to ensure consistency."}	{"sql": "XA ROLLBACK permanently discards the prepared transaction's changes. XA COMMIT permanently applies them. Both are irreversible once executed. Coordinate with the DTC before proceeding.", "description": ""}	medium	t	f	10 minutes	2026-03-01 09:33:09.381992
29098	mysql	execute	mysql_restore_or_remove_replication_consumer	{"sql": "-- Option A: Restart the replica if it is recoverable\\n-- On the replica server:\\nSTART SLAVE;\\n-- MySQL 8.0+: START REPLICA;\\n\\n-- Option B: If replica is too far behind, rebuild from backup:\\n-- 1. mysqldump --single-transaction --master-data=2 primary_db > backup.sql\\n-- 2. Restore on replica, then set CHANGE MASTER TO based on backup position\\n\\n-- Option C: If replica is permanently decommissioned, purge its logs on primary\\n-- Identify the oldest required log position from remaining replicas\\n-- Then purge:\\nPURGE BINARY LOGS TO 'mysql-bin.<safe_log_number>';\\n\\n-- Set binlog expiry as a safety net\\nSET GLOBAL binlog_expire_logs_seconds = 259200;", "parameters": {"safe_log_number": "The oldest binary log needed by remaining connected replicas"}, "description": "Restore the offline replica if possible, or decommission it and purge the accumulated binary logs. If the replica can be recovered, restart it; if permanently gone, remove it and purge logs."}	{"sql": "Purged binary logs cannot be recovered. If the decommissioned replica is later needed, it must be rebuilt from a fresh backup.", "description": ""}	medium	t	f	30 minutes	2026-03-01 09:33:09.381992
29113	mysql	execute	mysql_resolve_indoubt_xa_transactions	{"sql": "-- Based on coordinator log, resolve each in-doubt transaction:\\n\\n-- If coordinator intended to COMMIT:\\nXA COMMIT '<xid>';\\n-- Or with explicit format:\\nXA COMMIT X'<gtrid_hex>', X'<bqual_hex>', <formatID>;\\n\\n-- If coordinator intended to ROLLBACK:\\nXA ROLLBACK '<xid>';\\n\\n-- After resolution, verify no prepared transactions remain\\nXA RECOVER;\\n\\n-- If coordinator is still down and resolution cannot wait,\\n-- heuristic rollback (last resort, loses coordinator guarantee):\\n-- XA ROLLBACK '<xid>';  -- document as heuristic resolution", "parameters": {"xid": "XID from XA RECOVER output", "coordinator_decision": "COMMIT or ROLLBACK based on coordinator log"}, "description": "Resolve each in-doubt XA transaction based on the coordinator's durable decision log. Commit transactions that the coordinator logged as committed, and roll back those that were not yet committed."}	{"sql": "XA COMMIT and XA ROLLBACK are irreversible. Ensure all distributed participants are resolved consistently to avoid data divergence.", "description": ""}	medium	t	f	30 minutes	2026-03-01 09:33:09.381992
30024	sqlserver	instruct	Restrict after-hours access via logon trigger	{"sql": "CREATE OR ALTER TRIGGER trg_restrict_after_hours ON ALL SERVER FOR LOGON AS BEGIN IF DATEPART(HOUR, GETDATE()) < 6 OR DATEPART(HOUR, GETDATE()) >= 22 BEGIN IF ORIGINAL_LOGIN() NOT IN ('sa','scheduled_job_account') ROLLBACK; END; END;", "description": "Create logon trigger to reject non-service connections outside business hours. Customize the whitelist of allowed after-hours accounts."}	\N	medium	t	t	15 minutes	2026-04-03 09:46:55.380001
29144	mysql	execute	mysql_expand_undo_temp_resources	{"sql": "-- Enable undo tablespace auto-truncation (MySQL 8.0+)\\nSET GLOBAL innodb_undo_log_truncate = ON;\\nSET GLOBAL innodb_max_undo_log_size = 1073741824; -- 1 GB\\n\\n-- Increase temporary tablespace limit (requires restart via my.cnf)\\n-- innodb_temp_data_file_path = ibtmp1:12M:autoextend:max:20G\\n\\n-- Kill long-running transactions holding undo space\\nSELECT trx_id, trx_started, trx_rows_modified,\\n       TIMESTAMPDIFF(MINUTE, trx_started, NOW()) AS age_minutes\\nFROM information_schema.innodb_trx\\nORDER BY age_minutes DESC\\nLIMIT 10;\\n\\n-- Kill the longest-running transaction (replace with actual thread ID)\\nKILL CONNECTION <trx_mysql_thread_id>;\\n\\n-- Increase purge threads to speed undo cleanup\\nSET GLOBAL innodb_purge_threads = 4;", "parameters": {"innodb_purge_threads": "4", "innodb_max_undo_log_size": "1073741824 (1 GB)", "innodb_undo_log_truncate": "ON"}, "description": "Enable undo log auto-truncation and set a reasonable max undo size. Kill long-running transactions that are preventing undo space reclamation. Increase purge threads to accelerate undo cleanup. Configure temporary tablespace with a maximum size to prevent unbounded growth."}	{"sql": "SET GLOBAL innodb_undo_log_truncate = OFF; SET GLOBAL innodb_purge_threads = 1;", "description": ""}	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
29160	mysql	execute	mysql_fix_auth_mode_account_gaps	{"sql": "-- Enable validate_password plugin if not active\\nINSTALL PLUGIN validate_password SONAME 'validate_password.so';\\nSET GLOBAL validate_password.policy = 'STRONG';\\nSET GLOBAL validate_password.length = 12;\\n\\n-- Upgrade all accounts to caching_sha2_password\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n\\n-- Expire passwords for all non-system accounts to force reset\\nALTER USER '<user>'@'%' PASSWORD EXPIRE;\\n\\n-- Set strong passwords on any empty-password accounts\\nSELECT CONCAT(\\"ALTER USER '\\", User, \\"'@'\\", Host, \\"' IDENTIFIED BY '<temp_password>';\\") AS fix_sql\\nFROM mysql.user\\nWHERE authentication_string = '' AND User != '';\\n\\n-- Disable anonymous access\\nDROP USER IF EXISTS ''@'localhost';\\n\\nFLUSH PRIVILEGES;", "parameters": {"validate_password.length": "12 minimum", "validate_password.policy": "STRONG"}, "description": "Enable and enforce the validate_password plugin with STRONG policy. Upgrade root and admin accounts to caching_sha2_password. Set strong temporary passwords on empty-password accounts and expire them to force password change at next login. Remove anonymous accounts."}	{"sql": "SET GLOBAL validate_password.policy = 'LOW'; -- Only if needed for legacy compatibility", "description": ""}	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
29202	mysql	execute	mysql_remediate_and_implement_scan_gate	{"sql": "-- Remediate all existing empty-password accounts\\nALTER USER '<affected_user>'@'<host>' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n-- Enable password validation\\nINSTALL PLUGIN validate_password SONAME 'validate_password.so';\\nSET GLOBAL validate_password.policy = 'MEDIUM';\\nSET GLOBAL validate_password.length = 12;\\nFLUSH PRIVILEGES;\\n-- Deployment gate script (bash):\\n-- mysql -e \\"SELECT COUNT(*) FROM mysql.user WHERE authentication_string=''\\" | grep -v '^0$' && exit 1", "parameters": {}, "description": "Fix existing empty-password accounts and implement a deployment gate script that queries for empty-password accounts and fails the deployment pipeline if any are found."}	{"sql": "UNINSTALL PLUGIN validate_password;", "description": ""}	medium	t	t	15m	2026-03-01 09:33:09.381992
29163	mysql	execute	mysql_enforce_db_level_security_defaults	{"sql": "-- Remove all remote root access\\nDROP USER IF EXISTS 'root'@'%';\\nDROP USER IF EXISTS 'root'@'0.0.0.0';\\n\\n-- Restrict all default admin accounts to localhost only\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n\\n-- Require SSL for all non-local connections\\nSET GLOBAL require_secure_transport = ON;\\n\\n-- Rename or disable default admin account if not needed\\n-- Create a named admin account instead of using 'root':\\nCREATE USER IF NOT EXISTS 'dbadmin'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\nGRANT ALL PRIVILEGES ON *.* TO 'dbadmin'@'localhost' WITH GRANT OPTION;\\n\\n-- Lock root if dbadmin is the new admin account\\nALTER USER 'root'@'localhost' ACCOUNT LOCK;\\n\\nFLUSH PRIVILEGES;", "parameters": {"require_secure_transport": "ON — forces TLS for all non-socket connections"}, "description": "Remove remote access for all default accounts and restrict them to localhost only. Require SSL for all non-local connections. Create a named admin account to replace generic 'root' usage. Lock the root account if a dedicated named admin account is established."}	{"sql": "ALTER USER 'root'@'localhost' ACCOUNT UNLOCK; SET GLOBAL require_secure_transport = OFF;", "description": ""}	medium	t	f	15 minutes	2026-03-01 09:33:09.381992
29187	mysql	execute	mysql_set_root_password_restrict_host	{"sql": "-- Set a strong password on root for all hosts\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n-- If root has a wildcard host entry, rename or drop it\\nDROP USER IF EXISTS 'root'@'%';\\n-- Restrict MySQL to localhost if remote root access is unneeded\\n-- (Add to my.cnf: bind-address = 127.0.0.1, then restart)\\nFLUSH PRIVILEGES;", "parameters": {"strong_password": "16+ character password stored in secrets manager"}, "description": "Assign a strong password to root and restrict remote root login by removing wildcard host entries. Consider binding MySQL to localhost."}	{"sql": "ALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<previous_password>'; FLUSH PRIVILEGES;", "description": ""}	medium	t	t	10m	2026-03-01 09:33:09.381992
29169	mysql	execute	mysql_implement_secure_break_glass	{"sql": "-- Step 1: Create a secure break-glass account with a randomly generated password\\nCREATE USER IF NOT EXISTS 'breakglass'@'localhost'\\n  IDENTIFIED WITH caching_sha2_password BY '<random_high_entropy_password>';\\nGRANT ALL PRIVILEGES ON *.* TO 'breakglass'@'localhost' WITH GRANT OPTION;\\n\\n-- Step 2: Immediately expire the password (forces rotation on use)\\nALTER USER 'breakglass'@'localhost' PASSWORD EXPIRE INTERVAL 90 DAY;\\n\\n-- Step 3: Store credential in secrets management (Vault, AWS SSM, etc.)\\n-- (done outside MySQL)\\n\\n-- Step 4: Restrict to localhost only (emergency access requires shell/bastion)\\n-- Already done by @'localhost' host restriction\\n\\n-- Step 5: Enable MySQL --skip-grant-tables documentation as fallback\\n-- Document: sudo mysqld_safe --skip-grant-tables & for OS-level recovery\\n\\n-- Step 6: Disable the original default recovery backdoor\\nDROP USER IF EXISTS 'root'@'%';\\nALTER USER 'root'@'localhost' ACCOUNT LOCK;\\n\\nFLUSH PRIVILEGES;", "parameters": {"password_expiry": "90 days", "break_glass_host": "localhost only — requires SSH/bastion for remote emergency access"}, "description": "Create a named break-glass account with a strong, vaulted password accessible only from localhost. Set a 90-day password expiry. Document --skip-grant-tables as the true last-resort recovery path. Lock or remove the default root account used as the previous backdoor. Store break-glass credentials in a secrets manager with access audit logging."}	{"sql": "ALTER USER 'root'@'localhost' ACCOUNT UNLOCK;", "description": ""}	medium	t	t	20 minutes	2026-03-01 09:33:09.381992
29172	mysql	execute	mysql_revoke_excess_default_privileges	{"sql": "-- Revoke excess privileges from application accounts\\n-- (replace with actual account names identified in diagnosis)\\nREVOKE ALL PRIVILEGES, GRANT OPTION FROM '<app_user>'@'%';\\n\\n-- Re-grant only what the application needs\\nGRANT SELECT, INSERT, UPDATE, DELETE ON app_db.* TO '<app_user>'@'%';\\n\\n-- Replace SUPER with specific dynamic privileges (MySQL 8.0+)\\nREVOKE SUPER ON *.* FROM '<admin_user>'@'localhost';\\nGRANT BACKUP_ADMIN, REPLICATION_CLIENT, PROCESS ON *.* TO '<admin_user>'@'localhost';\\n\\n-- Enforce password rotation on escalated accounts\\nALTER USER '<escalated_account>'@'%' PASSWORD EXPIRE;\\n\\n-- Enable general query log temporarily to audit usage\\nSET GLOBAL general_log = ON;\\nSET GLOBAL general_log_file = '/var/log/mysql/general.log';\\n\\nFLUSH PRIVILEGES;\\nSHOW GRANTS FOR '<app_user>'@'%';", "parameters": {"principle": "Least privilege — grant only what is explicitly required"}, "description": "Revoke ALL PRIVILEGES from application accounts that accumulated admin privileges, then re-grant only the minimum permissions required (SELECT, INSERT, UPDATE, DELETE on specific schemas). Replace SUPER with granular dynamic privileges for admin accounts. Enable general query log temporarily to audit the impact of privilege reduction."}	{"sql": "GRANT ALL PRIVILEGES ON *.* TO '<user>'@'<host>'; -- Restore if application breaks", "description": ""}	medium	t	t	30 minutes	2026-03-01 09:33:09.381992
29175	mysql	execute	mysql_disable_unused_default_accounts	{"sql": "-- Lock confirmed-unused default accounts\\nALTER USER 'root'@'%' ACCOUNT LOCK; -- If still exists remotely\\nDROP USER IF EXISTS 'root'@'%';      -- Remove remote root entirely\\n\\n-- For local root: change password and lock if using named admin instead\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\nALTER USER 'root'@'localhost' ACCOUNT LOCK;\\n\\n-- Remove anonymous accounts (always a lateral movement risk)\\nDROP USER IF EXISTS ''@'localhost';\\nDROP USER IF EXISTS ''@'%';\\n\\n-- Enable connection attempt logging to detect future unauthorized tries\\nSET GLOBAL general_log = ON;\\nSET GLOBAL log_error_verbosity = 3;\\n\\n-- Set max_connect_errors to lock accounts after failed attempts\\nSET GLOBAL max_connect_errors = 5;\\n\\nFLUSH PRIVILEGES;", "parameters": {"max_connect_errors": "5 (lock host after 5 failed attempts)", "log_error_verbosity": "3 (logs all connection errors)"}, "description": "Lock and remove unused default accounts to eliminate lateral movement risk. Even unused accounts can be exploited if an attacker gains network access. Enable verbose error logging to detect connection attempts on locked accounts. Set max_connect_errors to 5 to block brute-force attempts."}	{"sql": "ALTER USER 'root'@'localhost' ACCOUNT UNLOCK; FLUSH HOSTS;", "description": ""}	medium	t	t	10 minutes	2026-03-01 09:33:09.381992
