29289	mysql	execute	mysql_harden_local_auth_for_remote_exposure	{"sql": "-- Set strong passwords on all localhost accounts\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_root_password>';\\nALTER USER '<admin_user>'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n-- Remove anonymous localhost accounts\\nDELETE FROM mysql.user WHERE user = '' AND host IN ('localhost', '127.0.0.1');\\n-- For auth_socket accounts: restrict to specific OS users only\\n-- ALTER USER 'root'@'localhost' IDENTIFIED WITH auth_socket; -- Only if OS user control is strong\\n-- Require SSL for all connections including localhost if needed\\nALTER USER '<sensitive_user>'@'localhost' REQUIRE SSL;\\n-- Enable require_secure_transport for all connections\\nSET GLOBAL require_secure_transport = ON;\\nFLUSH PRIVILEGES;", "parameters": {"admin_user": "DBA account on localhost", "strong_root_password": "complex password for MySQL root"}, "description": "Apply strong password authentication to all localhost-scoped MySQL accounts, remove anonymous localhost accounts, and optionally require SSL even for local connections."}	{"sql": "SET GLOBAL require_secure_transport = OFF; FLUSH PRIVILEGES; -- Required if SSL is not available on localhost.", "description": ""}	medium	t	t	25m	2026-03-01 09:33:09.381992
29292	mysql	execute	mysql_remediate_iac_default_auth	{"sql": "-- Apply security hardening that should have been in the IaC template\\n-- 1. Install password validation\\nINSTALL COMPONENT 'file://component_validate_password';\\nSET GLOBAL validate_password.policy = 'STRONG';\\nSET GLOBAL validate_password.length = 12;\\n-- 2. Enable secure transport\\nSET GLOBAL require_secure_transport = ON;\\n-- 3. Set strong passwords on all default accounts\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_root_password>';\\nALTER USER 'root'@'%' IDENTIFIED WITH caching_sha2_password BY '<strong_root_password>';\\n-- 4. Remove anonymous accounts\\nDELETE FROM mysql.user WHERE user = '';\\n-- 5. Remove insecure test database if exists\\nDROP DATABASE IF EXISTS test;\\n-- 6. Persist to my.cnf (add to [mysqld]):\\n-- validate_password.policy = STRONG\\n-- require_secure_transport = ON\\n-- local_infile = 0\\nSET GLOBAL local_infile = OFF;\\nFLUSH PRIVILEGES;", "parameters": {"strong_root_password": "generated complex password from secrets manager"}, "description": "Apply all MySQL security hardening steps that IaC templates omitted, including password validation, strong root credentials, SSL transport enforcement, and removal of insecure defaults."}	{"sql": "SET GLOBAL require_secure_transport = OFF; SET GLOBAL local_infile = ON; -- Only in non-production for troubleshooting.", "description": ""}	medium	t	f	30m	2026-03-01 09:33:09.381992
29295	mysql	execute	mysql_implement_secure_recovery_procedure	{"sql": "-- Step 1: Store root password securely in secrets manager\\n-- (External action: store in HashiCorp Vault, AWS SSM, or equivalent)\\n-- vault kv put secret/mysql/root password='<strong_root_password>'\\n\\n-- Step 2: Convert root to strong password auth if currently using trust-equivalent\\nALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_root_password>';\\n\\n-- Step 3: Create a DBA break-glass account with strong authentication\\n-- This replaces trust-based fallback with a documented emergency account\\nCREATE USER IF NOT EXISTS 'dba_breakglass'@'localhost'\\n  IDENTIFIED WITH caching_sha2_password BY '<breakglass_password>';\\nGRANT ALL PRIVILEGES ON *.* TO 'dba_breakglass'@'localhost' WITH GRANT OPTION;\\n-- Store breakglass password in physical sealed envelope AND secrets manager\\n\\n-- Step 4: Document recovery procedure (do not rely on skip_grant_tables silently)\\n-- Recovery: sudo systemctl stop mysql && mysqld_safe --skip-grant-tables &\\n-- Then: mysql -u root (no password) → ALTER USER ...; → restart MySQL normally\\n\\n-- Step 5: Remove any auth_socket root entry if replaced by strong password\\n-- ALTER USER 'root'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<password>';\\nFLUSH PRIVILEGES;", "parameters": {"breakglass_password": "emergency DBA account password stored in physical vault", "strong_root_password": "complex password stored in secrets manager"}, "description": "Replace trust-based recovery authentication with a documented break-glass account and stored root credentials in a secrets manager, eliminating the need for permanently enabled trust authentication."}	{"sql": "If root access is lost after changing authentication: use mysqld_safe --skip-grant-tables to reset. This is the secure recovery path that replaces permanent trust auth.", "description": ""}	medium	t	f	30m	2026-03-01 09:33:09.381992
29301	mysql	execute	mysql_restrict_hosts_add_passwords	{"sql": "-- Tighten host scope for each account from '%' to specific IP/subnet\\nRENAME USER 'repl_user'@'%' TO 'repl_user'@'192.168.1.0/255.255.255.0';\\nALTER USER 'repl_user'@'192.168.1.0/255.255.255.0' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n\\n-- Add password to any passwordless local accounts\\nALTER USER 'backup_agent'@'localhost' IDENTIFIED WITH caching_sha2_password BY '<strong_password>';\\n\\n-- Remove wildcard accounts if not needed\\nDROP USER IF EXISTS ''@'%';\\n\\nFLUSH PRIVILEGES;", "parameters": {"plugin": "caching_sha2_password"}, "description": "Narrow host specifications for all user accounts to explicit IPs or subnets and assign strong passwords. Drop wildcard anonymous accounts."}	{"sql": "RENAME USER 'repl_user'@'192.168.1.0/255.255.255.0' TO 'repl_user'@'%'; FLUSH PRIVILEGES; -- Recreate dropped accounts if needed.", "description": ""}	medium	t	t	20 minutes	2026-03-01 09:33:09.381992
