29446	mysql	execute	mysql_configure_ldap_authentication	{"sql": "-- Install LDAP authentication plugin (Enterprise)\\nINSTALL PLUGIN authentication_ldap_simple SONAME 'authentication_ldap_simple.so';\\n\\n-- Configure LDAP connection\\nSET GLOBAL authentication_ldap_simple_server_host = 'ldap.company.com';\\nSET GLOBAL authentication_ldap_simple_server_port = 389;\\nSET GLOBAL authentication_ldap_simple_bind_base_dn = 'DC=company,DC=com';\\nSET GLOBAL authentication_ldap_simple_user_search_attr = 'sAMAccountName';\\n\\n-- Create MySQL proxy account mapped to LDAP group\\nCREATE USER 'ldap_dba'@'%'\\n  IDENTIFIED WITH authentication_ldap_simple\\n  BY 'CN=DBA Group,OU=Groups,DC=company,DC=com';\\nGRANT 'db_admin' TO 'ldap_dba'@'%';\\n\\n-- Migrate existing user to LDAP auth\\nALTER USER 'jsmith'@'%'\\n  IDENTIFIED WITH authentication_ldap_simple\\n  BY 'CN=DB Users,OU=Groups,DC=company,DC=com';\\n\\nFLUSH PRIVILEGES;", "parameters": {"ldap_port": "389", "ldap_server": "ldap.company.com"}, "description": "Configure the MySQL LDAP authentication plugin and migrate user accounts to authenticate against the centralized identity provider."}	{"sql": "ALTER USER 'jsmith'@'%' IDENTIFIED BY 'LocalPassword123!';\\nFLUSH PRIVILEGES;", "description": ""}	medium	t	t	120m	2026-03-01 09:33:09.381992
