29470	mysql	execute	mysql_remove_dev_grants_from_production	{"sql": "-- Remove development test accounts from production\\nDROP USER IF EXISTS 'testuser'@'%';\\nDROP USER IF EXISTS 'devadmin'@'%';\\n\\n-- Remove anonymous users\\nDROP USER IF EXISTS ''@'localhost';\\nDROP USER IF EXISTS ''@'%';\\n\\n-- Revoke development-style broad grants\\nREVOKE DROP ON *.* FROM 'appuser'@'%';  -- DROP should not be in production apps\\nREVOKE CREATE ON *.* FROM 'appuser'@'%';  -- DDL should be schema-owner only\\n\\n-- Apply production-appropriate grants\\nGRANT SELECT, INSERT, UPDATE, DELETE ON app_db.* TO 'appuser'@'%';\\n\\n-- Require strong passwords for all production accounts\\nALTER USER 'appuser'@'%' PASSWORD EXPIRE;\\n\\nFLUSH PRIVILEGES;", "parameters": {}, "description": "Remove test/dev accounts and overly permissive grants from production, replacing them with production-appropriate minimum privilege grants."}	{"sql": "-- Only restore if application breaks; document why dev grants were needed\\nGRANT CREATE, DROP ON *.* TO 'appuser'@'%';\\nFLUSH PRIVILEGES;", "description": ""}	medium	t	t	30m	2026-03-01 09:33:09.381992
29479	mysql	execute	mysql_execute_complete_permission_revocation	{"sql": "-- Revoke global over-broad privileges (adjust per user)\\nREVOKE ALL PRIVILEGES ON *.* FROM 'username'@'host';\\n\\n-- Revoke database-level wildcard grants\\nREVOKE ALL PRIVILEGES ON target_db.* FROM 'username'@'host';\\n\\n-- Re-grant only the minimum required privileges\\nGRANT SELECT ON target_db.specific_table TO 'username'@'host';\\n\\n-- Remove grant option if present\\nREVOKE GRANT OPTION ON *.* FROM 'username'@'host';\\n\\n-- Flush privileges to ensure changes take effect\\nFLUSH PRIVILEGES;\\n\\n-- Verify the revocation\\nSHOW GRANTS FOR 'username'@'host';", "parameters": {"host": "Host portion of user account", "username": "User account to remediate", "target_db": "Database to scope grants"}, "description": "Execute complete revocation of over-broad permissions with correct syntax covering all privilege scopes, then re-grant only necessary minimum privileges."}	{"sql": "GRANT ALL PRIVILEGES ON target_db.* TO 'username'@'host'; FLUSH PRIVILEGES;", "description": ""}	medium	t	t	15 minutes	2026-03-01 09:33:09.381992
29488	mysql	execute	mysql_drop_confirmed_orphaned_accounts	{"sql": "-- Lock first (safer staging step before DROP)\\nALTER USER 'orphaned_user'@'host' ACCOUNT LOCK;\\n\\n-- After 30-day hold with no complaints, DROP the account\\nDROP USER IF EXISTS 'orphaned_user'@'host';\\n\\n-- For service accounts with unclear ownership, lock and expire password\\nALTER USER 'unknown_service_account'@'%' ACCOUNT LOCK;\\nALTER USER 'unknown_service_account'@'%' PASSWORD EXPIRE;\\n\\n-- Schedule regular reconciliation (document in runbook)\\n-- Recommended: quarterly reconciliation against HR roster\\n-- Create event for automated lock of accounts inactive > 90 days\\nCREATE EVENT IF NOT EXISTS lock_inactive_accounts\\n  ON SCHEDULE EVERY 1 WEEK\\n  DO\\n    UPDATE mysql.user SET account_locked = 'Y'\\n    WHERE User NOT IN ('root','mysql.sys','mysql.infoschema','mysql.session')\\n    AND User NOT IN (SELECT USER FROM performance_schema.accounts WHERE LAST_SEEN > DATE_SUB(NOW(), INTERVAL 90 DAY));\\n\\nFLUSH PRIVILEGES;", "parameters": {"host": "Host portion of the orphaned account", "orphaned_user": "Account confirmed as orphaned via reconciliation"}, "description": "Lock and drop confirmed orphaned accounts found during reconciliation. Implement an automated event to lock accounts inactive over 90 days."}	{"sql": "-- Cannot restore dropped accounts. Restore from backup if needed. Disable event: ALTER EVENT lock_inactive_accounts DISABLE;", "description": ""}	medium	t	f	20 minutes	2026-03-01 09:33:09.381992
29497	mysql	execute	mysql_create_individual_accounts_and_migrate_from_shared	{"sql": "-- Create individual accounts for each user currently sharing\\nCREATE USER 'user_alice'@'%' IDENTIFIED BY 'strong_password_1';\\nCREATE USER 'user_bob'@'%' IDENTIFIED BY 'strong_password_2';\\n\\n-- Grant same privileges as the shared account\\nGRANT SELECT, INSERT, UPDATE ON target_db.* TO 'user_alice'@'%';\\nGRANT SELECT, INSERT, UPDATE ON target_db.* TO 'user_bob'@'%';\\n\\n-- If roles exist, assign role instead of direct grants (MySQL 8.0+)\\nGRANT 'application_writers' TO 'user_alice'@'%';\\nGRANT 'application_writers' TO 'user_bob'@'%';\\nSET DEFAULT ROLE 'application_writers' FOR 'user_alice'@'%';\\nSET DEFAULT ROLE 'application_writers' FOR 'user_bob'@'%';\\n\\n-- Lock the shared account after migrating all users\\nALTER USER 'shared_account'@'%' ACCOUNT LOCK;\\n\\n-- After verified migration period, DROP the shared account\\n-- DROP USER 'shared_account'@'%';\\n\\nFLUSH PRIVILEGES;", "parameters": {"target_db": "Database the shared account has access to", "shared_account": "The shared account being replaced"}, "description": "Create individual accounts for each user currently sharing a MySQL account, assign equivalent privileges, and lock the shared account."}	{"sql": "ALTER USER 'shared_account'@'%' ACCOUNT UNLOCK; DROP USER IF EXISTS 'user_alice'@'%', 'user_bob'@'%';", "description": ""}	medium	t	t	60 minutes	2026-03-01 09:33:09.381992
29500	mysql	execute	mysql_lock_and_remove_cross_system_orphans	{"sql": "-- Lock accounts confirmed deprovisioned in other systems but missed in MySQL\\nALTER USER 'departed_user'@'%' ACCOUNT LOCK;\\nALTER USER 'departed_user'@'%' PASSWORD EXPIRE;\\n\\n-- After 30-day hold, DROP confirmed orphans\\nDROP USER IF EXISTS 'departed_user'@'%';\\n\\n-- Add cross-system reference to remaining accounts (MySQL 8.0+)\\nALTER USER 'active_user'@'%' ATTRIBUTE '{\\"ad_account\\": \\"DOMAIN\\\\\\\\active_user\\", \\"ldap_dn\\": \\"cn=active_user,ou=users,dc=company,dc=com\\"}';\\n\\n-- Create deprovisioning checklist table\\nCREATE TABLE IF NOT EXISTS mysql_admin.deprovisioning_log (\\n  user VARCHAR(32),\\n  host VARCHAR(255),\\n  action_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\\n  action ENUM('locked','dropped'),\\n  ticket_reference VARCHAR(100),\\n  performed_by VARCHAR(100)\\n);\\n\\nINSERT INTO mysql_admin.deprovisioning_log (user, host, action, ticket_reference, performed_by) VALUES ('departed_user','%','locked','TICKET-12345','dba_admin');", "parameters": {"departed_user": "Account confirmed orphaned via cross-system check"}, "description": "Lock and drop MySQL accounts confirmed as orphaned via cross-system reconciliation. Add identity system references to remaining accounts."}	{"sql": "-- Cannot restore dropped accounts. Restore from backup if incorrectly dropped.", "description": ""}	medium	t	f	30 minutes	2026-03-01 09:33:09.381992
29509	mysql	execute	mysql_remove_default_accounts_and_rotate_active_ones	{"sql": "-- Drop default accounts from decommissioned applications\\nDROP USER IF EXISTS 'wordpress_old'@'localhost';\\nDROP USER IF EXISTS 'test_app'@'%';\\nDROP USER IF EXISTS 'demo_user'@'%';\\n\\n-- For active applications with default accounts: rotate password and rename\\n-- Step 1: Create new account with non-default name and strong password\\nCREATE USER 'app_billing_svc'@'app-server-ip' IDENTIFIED BY 'StrongGeneratedPassword123!';\\nGRANT SELECT, INSERT, UPDATE ON billing_db.* TO 'app_billing_svc'@'app-server-ip';\\n\\n-- Step 2: Update application config to use new account, then lock old\\nALTER USER 'billing_default'@'%' ACCOUNT LOCK;\\n\\n-- Step 3: After application migration confirmed, DROP old default account\\n-- DROP USER IF EXISTS 'billing_default'@'%';\\n\\n-- Force password change on any remaining default-named accounts\\nALTER USER 'admin_account'@'localhost' PASSWORD EXPIRE;\\n\\nFLUSH PRIVILEGES;", "parameters": {"app_billing_svc": "New purpose-named replacement account", "billing_default": "Default account being replaced"}, "description": "Drop decommissioned application default accounts and replace active default accounts with purpose-named accounts using strong passwords."}	{"sql": "CREATE USER 'billing_default'@'%' IDENTIFIED BY 'temp'; GRANT SELECT, INSERT, UPDATE ON billing_db.* TO 'billing_default'@'%'; ALTER USER 'billing_default'@'%' ACCOUNT UNLOCK;", "description": ""}	medium	t	f	45 minutes	2026-03-01 09:33:09.381992
29515	mysql	execute	mysql_restrict_file_privilege_and_harden_export_path	{"sql": "-- Revoke FILE privilege from application accounts\\nREVOKE FILE ON *.* FROM 'app_export_user'@'%';\\n\\n-- Set secure_file_priv to restrict to safe export directory (in my.cnf)\\n-- Add to /etc/mysql/mysql.conf.d/mysqld.cnf:\\n-- [mysqld]\\n-- secure_file_priv = /var/lib/mysql-files/\\n\\n-- Create a definer-based stored procedure for safe exports\\nDELIMITER //\\nCREATE DEFINER='export_admin'@'localhost' PROCEDURE safe_export_data(\\n  IN export_filename VARCHAR(255)\\n)\\nSQL SECURITY DEFINER\\nBEGIN\\n  SET @safe_path = CONCAT('/var/lib/mysql-files/', export_filename);\\n  SET @sql = CONCAT('SELECT * FROM exportable_view INTO OUTFILE ', QUOTE(@safe_path));\\n  PREPARE stmt FROM @sql;\\n  EXECUTE stmt;\\n  DEALLOCATE PREPARE stmt;\\nEND //\\nDELIMITER ;\\n\\n-- Grant EXECUTE on the procedure instead of FILE privilege\\nGRANT EXECUTE ON PROCEDURE target_db.safe_export_data TO 'app_export_user'@'%';\\n\\nFLUSH PRIVILEGES;", "parameters": {"target_db": "Database containing export procedure", "app_export_user": "Application account that required FILE privilege"}, "description": "Revoke FILE privilege from application accounts, restrict export path via secure_file_priv, and implement a DEFINER stored procedure for controlled exports."}	{"sql": "GRANT FILE ON *.* TO 'app_export_user'@'%'; FLUSH PRIVILEGES;", "description": ""}	medium	t	t	45 minutes	2026-03-01 09:33:09.381992
