29670	mysql	execute	mysql_upgrade_client_or_deploy_tls_proxy	{"sql": "-- Option A: Upgrade MySQL Connector\\n-- Replace mysql-connector-java-5.x with 8.x in pom.xml/build.gradle\\n-- New connector supports TLS 1.2+ and sslMode=REQUIRED\\n\\n-- Option B: Deploy stunnel as TLS termination proxy for legacy apps\\n-- /etc/stunnel/mysql-tls.conf:\\n-- [mysql-tls]\\n-- accept = 127.0.0.1:3307\\n-- connect = mysql-server:3306\\n-- client = yes\\n-- sslVersion = TLSv1.2\\n-- Application connects to localhost:3307; stunnel encrypts to MySQL\\n\\n-- Option C: Set tls_version to include TLSv1.2 minimum while allowing legacy\\n-- Only if TLS 1.0/1.1 is unavoidable short-term:\\nSET GLOBAL tls_version = 'TLSv1.2,TLSv1.3';\\n-- Note: TLS 1.0/1.1 are disabled; this is the correct hardened setting\\n\\n-- Verify server TLS configuration\\nSHOW GLOBAL VARIABLES LIKE 'tls_version';", "parameters": {"target_tls": "TLSv1.2,TLSv1.3", "proxy_option": "stunnel (if driver upgrade is not feasible)"}, "description": "Upgrade the MySQL connector dependency to a version supporting TLS 1.2+ OR deploy stunnel as a transparent TLS proxy for applications where driver upgrade is blocked. Set server tls_version to TLSv1.2,TLSv1.3."}	{"sql": "SET GLOBAL tls_version = 'TLSv1,TLSv1.1,TLSv1.2'; -- Re-enable legacy protocols only if critical regression; plan immediate remediation", "description": ""}	medium	t	t	2-8 hours depending on approach	2026-03-01 09:33:09.381992
29690	mysql	execute	mysql_upgrade_apps_disable_legacy_tls	{"sql": "-- Step 1: Upgrade application drivers to TLS 1.2+ capable versions\\n-- (See SEC-SQL-ENC-001-RC04 for driver upgrade steps)\\n\\n-- Step 2: Update application JVM TLS settings (Java apps)\\n-- java -Dhttps.protocols=TLSv1.2,TLSv1.3 -jar app.jar\\n-- Or in application.properties: server.ssl.enabled-protocols=TLSv1.2,TLSv1.3\\n\\n-- Step 3: Update Python ssl context\\n-- ssl_context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)\\n-- ssl_context.minimum_version = ssl.TLSVersion.TLSv1_2\\n\\n-- Step 4: After all apps upgraded, restrict MySQL to TLS 1.2+\\nSET GLOBAL tls_version = 'TLSv1.2,TLSv1.3';\\nALTER INSTANCE RELOAD TLS;\\n\\n-- Verify\\nSHOW GLOBAL VARIABLES LIKE 'tls_version';\\n-- Confirm no TLS 1.0/1.1 connections remain\\nSELECT s.VARIABLE_VALUE AS tls_version, COUNT(*) FROM performance_schema.threads t JOIN performance_schema.status_by_thread s ON t.thread_id = s.thread_id WHERE s.VARIABLE_NAME = 'Ssl_version' GROUP BY s.VARIABLE_VALUE;", "parameters": {"target_tls_version": "TLSv1.2,TLSv1.3"}, "description": "Upgrade each legacy application driver and TLS settings to support TLS 1.2+, then disable TLS 1.0/1.1 at the MySQL server level using SET GLOBAL tls_version and ALTER INSTANCE RELOAD TLS."}	{"sql": "SET GLOBAL tls_version = 'TLSv1,TLSv1.1,TLSv1.2,TLSv1.3'; ALTER INSTANCE RELOAD TLS; -- Re-enable if critical app regression", "description": ""}	medium	t	t	4-8 hours (multiple app upgrades)	2026-03-01 09:33:09.381992
29693	mysql	execute	mysql_replace_deprecated_libraries	{"sql": "-- Python: upgrade mysql drivers\\n-- pip install --upgrade mysql-connector-python PyMySQL SQLAlchemy\\n\\n-- Java: update pom.xml/build.gradle to Connector/J 8.x\\n-- <dependency><groupId>com.mysql</groupId><artifactId>mysql-connector-j</artifactId><version>8.3.0</version></dependency>\\n\\n-- Linux system library:\\n-- apt-get remove libmysqlclient-dev && apt-get install -y libmysqlclient-dev\\n-- Or from MySQL repo: apt-get install -y mysql-connector-c++\\n\\n-- ODBC (Linux):\\n-- apt-get remove libmyodbc && apt-get install -y mysql-connector-odbc\\n\\n-- After replacement, configure TLS 1.2+ in connection:\\n-- JDBC: sslMode=REQUIRED\\n-- Python: ssl={'ca': '/path/ca.pem'}\\n\\n-- MySQL: disable TLS 1.0/1.1 after all clients upgraded\\nSET GLOBAL tls_version = 'TLSv1.2,TLSv1.3';\\nALTER INSTANCE RELOAD TLS;\\nSHOW GLOBAL VARIABLES LIKE 'tls_version';", "parameters": {"target_connector_j": "8.3.0+", "target_python_connector": "8.x or PyMySQL 1.1+"}, "description": "Upgrade each deprecated MySQL client library to a current version supporting TLS 1.2+. After all clients are upgraded, disable TLS 1.0/1.1 at the server level."}	{"sql": "SET GLOBAL tls_version = 'TLSv1,TLSv1.1,TLSv1.2,TLSv1.3'; ALTER INSTANCE RELOAD TLS; -- And downgrade libraries if regression", "description": ""}	medium	t	t	4-8 hours	2026-03-01 09:33:09.381992
29702	mysql	execute	mysql_apply_os_level_tls_restriction	{"sql": "-- Option A (preferred): Upgrade MySQL to 8.x\\n-- 1. Backup: mysqldump --all-databases > backup.sql\\n-- 2. apt-get install -y mysql-server-8.0 (or use official MySQL repo)\\n-- 3. After upgrade: SET GLOBAL tls_version = 'TLSv1.2,TLSv1.3';\\n-- 4. ALTER INSTANCE RELOAD TLS;\\n\\n-- Option B: OS-level OpenSSL restriction (pre-5.7)\\n-- Edit /etc/ssl/openssl.cnf:\\n-- [system_default_sect]\\n-- MinProtocol = TLSv1.2\\n-- CipherString = DEFAULT@SECLEVEL=2\\n-- Restart MySQL: systemctl restart mysql\\n\\n-- Option C: stunnel as TLS proxy (if upgrade not possible)\\n-- /etc/stunnel/mysql.conf:\\n-- [mysql]\\n-- accept  = 0.0.0.0:3306\\n-- connect = 127.0.0.1:3307  (MySQL listens on 3307 for localhost only)\\n-- sslVersion = TLSv1.2\\n-- cert = /etc/stunnel/server.pem\\n\\n-- Verify (after upgrade or config change)\\nSELECT VERSION();\\nSHOW GLOBAL VARIABLES LIKE 'tls_version';", "parameters": {"fallback_approach": "OpenSSL system MinProtocol=TLSv1.2", "preferred_approach": "MySQL 8.x upgrade"}, "description": "Apply TLS 1.0/1.1 restriction via OS-level OpenSSL MinProtocol setting (for MySQL pre-5.7), or preferably upgrade MySQL to 8.x which supports database-level tls_version control."}	{"sql": "-- Revert OpenSSL MinProtocol change in /etc/ssl/openssl.cnf and restart MySQL -- Or restore from mysqldump backup if upgrade fails", "description": ""}	medium	t	t	2-4 hours for version upgrade; 30 minutes for OS c	2026-03-01 09:33:09.381992
29720	mysql	execute	mysql_configure_tde_across_ha_topology	{"sql": "-- On each replica, install keyring plugin FIRST:\\nINSTALL PLUGIN keyring_file SONAME 'keyring_file.so';\\n-- Enable binlog encryption (replicates safely):\\nSET PERSIST binlog_encryption = ON;\\n-- Enable InnoDB table encryption:\\nSET PERSIST innodb_encrypt_tables = ON;\\n-- Rotate master key after all nodes configured:\\nALTER INSTANCE ROTATE INNODB MASTER KEY;\\n-- Verify binlog encryption active:\\nSHOW VARIABLES LIKE 'binlog_encryption';", "parameters": {"binlog_encryption": "ON", "innodb_encrypt_tables": "ON"}, "description": "Install keyring plugin on all replica nodes before enabling encryption on primary. Enable binlog encryption for in-transit data protection. Rotate master key to activate encryption uniformly."}	{"sql": "SET PERSIST binlog_encryption = OFF; SET PERSIST innodb_encrypt_tables = OFF;", "description": ""}	medium	t	f	60m	2026-03-01 09:33:09.381992
