32505	mariadb	configure	mysql_configure_replication_network_resilience	{"sql": "-- Configure replica to reconnect quickly after network drops\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_CONNECT_RETRY = 10,     -- Retry every 10 seconds (default: 60)\\n  SOURCE_RETRY_COUNT = 100,      -- Retry up to 100 times\\n  SOURCE_HEARTBEAT_PERIOD = 5.0  -- Heartbeat every 5 seconds\\nFOR CHANNEL '';\\n\\n-- Configure replica timeouts\\nSET GLOBAL replica_net_timeout = 30;  -- Detect disconnection within 30s\\n\\n-- Configure network-level keepalive (requires my.cnf restart):\\n-- replica_net_timeout = 30\\n-- source_connect_retry = 10\\n\\nSHOW VARIABLES LIKE 'replica_net_timeout';\\nSHOW VARIABLES LIKE 'source_connect_retry';", "parameters": null, "description": "Configure aggressive reconnection settings and heartbeats to quickly detect and recover from intermittent network drops."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
