32508	mariadb	diagnose	mysql_diagnose_replica_config_errors	{"sql": "-- Check current replica configuration and errors\\nSHOW REPLICA STATUS\\\\G\\n\\n-- Check connection configuration details\\nSELECT\\n  CHANNEL_NAME,\\n  HOST,\\n  PORT,\\n  USER,\\n  SOURCE_UUID,\\n  AUTO_POSITION,\\n  SERVICE_STATE,\\n  LAST_ERROR_NUMBER,\\n  LAST_ERROR_MESSAGE\\nFROM performance_schema.replication_connection_configuration\\nJOIN performance_schema.replication_connection_status USING (CHANNEL_NAME);\\n\\n-- Common config errors:\\n-- 1. Wrong SOURCE_LOG_FILE or SOURCE_LOG_POS\\n-- 2. GTID mismatch (AUTO_POSITION but GTIDs not matching)\\n-- 3. Wrong SOURCE_HOST, SOURCE_PORT, or SOURCE_USER\\n-- 4. Missing or wrong GTID_PURGED on replica", "parameters": null, "description": "Identify specific configuration errors preventing replica from connecting to the binary log stream."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
