32510	mariadb	execute	mysql_handle_gtid_mismatch	{"sql": "-- If GTID mismatch error (ER_SLAVE_HAS_MORE_GTIDS_THAN_MASTER):\\n-- Check what GTIDs replica has vs primary\\nSELECT @@global.gtid_executed AS replica_gtid_executed;\\n-- On primary: SELECT @@global.gtid_executed AS primary_gtid_executed;\\n\\n-- If replica has extra GTIDs not on primary (misconfiguration),\\n-- reset and re-sync:\\nSTOP REPLICA;\\nRESET REPLICA ALL;\\nRESET BINARY LOGS AND GTIDS;\\n\\n-- Then set gtid_purged to match primary's gtid_executed:\\nSET GLOBAL gtid_purged = '<primary_gtid_executed>';\\n\\n-- Reconfigure and start:\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_HOST = '<primary_host>',\\n  SOURCE_AUTO_POSITION = 1;\\nSTART REPLICA;", "parameters": null, "description": "Resolve GTID mismatch by resetting replica GTID state and re-synchronizing with the primary's GTID set."}	\N	medium	t	f	15 minutes	2026-05-11 22:17:39.229791
32511	mariadb	diagnose	mysql_diagnose_replica_lag_bottleneck	{"sql": "-- Check replication lag and worker thread status\\nSELECT\\n  CHANNEL_NAME,\\n  WORKER_ID,\\n  SERVICE_STATE,\\n  LAST_APPLIED_TRANSACTION,\\n  APPLYING_TRANSACTION,\\n  LAST_ERROR_NUMBER,\\n  LAST_ERROR_MESSAGE\\nFROM performance_schema.replication_applier_status_by_worker;\\n\\n-- Check seconds behind source\\nSHOW REPLICA STATUS\\\\G\\n\\n-- Check replica applier bottleneck\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_variables\\nWHERE VARIABLE_NAME IN (\\n  'replica_parallel_workers',\\n  'replica_parallel_type',\\n  'replica_preserve_commit_order',\\n  'innodb_flush_log_at_trx_commit'\\n);", "parameters": null, "description": "Identify whether replica lag is caused by single-threaded applier, I/O bottleneck, or insufficient hardware resources."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32512	mariadb	configure	mysql_optimize_primary_for_replica_throughput	{"sql": "-- On PRIMARY: optimize group commit settings to maximize parallel replication benefit\\nSET GLOBAL binlog_group_commit_sync_delay = 1000;  -- 1ms delay to batch commits\\nSET GLOBAL binlog_group_commit_sync_no_delay_count = 10;  -- Or 10 transactions\\n\\n-- Enable dependency tracking for optimal replica parallelism\\nSET GLOBAL binlog_transaction_dependency_tracking = 'WRITESET';\\nSET GLOBAL transaction_write_set_extraction = 'XXHASH64';\\n\\n-- Persist in primary my.cnf:\\n-- binlog_transaction_dependency_tracking = WRITESET\\n-- transaction_write_set_extraction = XXHASH64\\n-- binlog_group_commit_sync_delay = 1000\\n\\nSHOW VARIABLES LIKE 'binlog_transaction_dependency_tracking';\\nSHOW VARIABLES LIKE 'binlog_group_commit_sync_delay';", "parameters": null, "description": "Configure primary's binary log dependency tracking to WRITESET mode, enabling maximum parallelism on the replica."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32513	mariadb	verify	mysql_verify_replica_catching_up	{"sql": "-- Monitor lag reduction over time\\nSELECT\\n  TIMESTAMPDIFF(SECOND,\\n    MIN(APPLYING_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP),\\n    NOW()) AS max_lag_seconds\\nFROM performance_schema.replication_applier_status_by_worker\\nWHERE SERVICE_STATE = 'ON';\\n\\n-- Check all workers are busy\\nSELECT\\n  WORKER_ID,\\n  SERVICE_STATE,\\n  APPLYING_TRANSACTION\\nFROM performance_schema.replication_applier_status_by_worker;\\n\\n-- Verify lag is trending down\\nSHOW REPLICA STATUS\\\\G  -- Seconds_Behind_Source should decrease", "parameters": null, "description": "Verify replica lag is decreasing with parallel replication and workers are actively applying transactions."}	\N	low	f	t	30 minutes	2026-05-11 22:17:39.229791
32514	mariadb	diagnose	mysql_diagnose_binlog_gap_after_maintenance	{"sql": "-- Check replica status for binary log gap error\\nSHOW REPLICA STATUS\\\\G\\n-- Look for: Last_IO_Error: Got fatal error 1236 from source\\n-- 'binary log file...' or 'Requested GTID...not in set'\\n\\n-- Confirm the specific missing GTID range\\nSELECT @@global.gtid_executed AS replica_gtid;\\n-- On primary: SELECT @@global.gtid_executed AS primary_gtid;\\n-- SELECT GTID_SUBTRACT('<primary_gtid>', '<replica_gtid>') AS missing_from_replica;\\n\\n-- Check primary's oldest available binary log\\nSHOW BINARY LOGS;\\n-- First entry is oldest available\\n\\n-- Confirm binary log expiry setting\\nSHOW VARIABLES LIKE 'binlog_expire_logs_seconds';", "parameters": null, "description": "Confirm the replica has a binary log gap due to purged logs and identify the GTIDs that are missing."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32515	mariadb	execute	mysql_clone_replica_from_primary	{"sql": "-- Use MySQL Clone Plugin for fast re-provisioning (MySQL 8.0.17+)\\n-- On replica:\\n\\n-- Install Clone plugin if not present\\nINSTALL PLUGIN clone SONAME 'mysql_clone.so';\\n\\n-- Create clone user on primary:\\n-- CREATE USER 'clone_user'@'%' IDENTIFIED BY '<password>';\\n-- GRANT BACKUP_ADMIN, REPLICATION CLIENT ON *.* TO 'clone_user'@'%';\\n-- GRANT CLONE_ADMIN ON *.* TO 'clone_user'@'%';\\n\\n-- Execute remote clone (will restart the replica and sync from primary)\\nCLONE INSTANCE FROM 'clone_user'@'<primary_host>':3306\\n  IDENTIFIED BY '<password>';\\n\\n-- Note: Clone replaces all data and automatically configures replica position\\n-- MySQL will restart after clone completes\\n\\nSHOW VARIABLES LIKE 'clone_status';", "parameters": null, "description": "Re-provision the stale replica using MySQL Clone Plugin to perform a fast, consistent snapshot from the primary."}	\N	medium	t	f	60 minutes	2026-05-11 22:17:39.229791
32516	mariadb	configure	mysql_configure_replication_after_clone	{"sql": "-- After clone completes and MySQL restarts:\\n-- Configure replication source\\nCHANGE REPLICATION SOURCE TO\\n  SOURCE_HOST = '<primary_host>',\\n  SOURCE_PORT = 3306,\\n  SOURCE_USER = 'replication_user',\\n  SOURCE_PASSWORD = '<password>',\\n  SOURCE_AUTO_POSITION = 1;\\n\\n-- Start replication\\nSTART REPLICA;\\n\\n-- Increase binary log retention to accommodate future maintenance windows\\n-- On PRIMARY:\\nSET GLOBAL binlog_expire_logs_seconds = 604800;  -- 7 days\\n-- Persist in primary my.cnf: binlog_expire_logs_seconds = 604800\\n\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Configure replication source on the cloned replica and increase primary binary log retention to prevent future maintenance-induced gaps."}	\N	medium	t	t	10 minutes	2026-05-11 22:17:39.229791
32517	mariadb	verify	mysql_verify_replica_resynced_and_replicating	{"sql": "-- Verify replica is catching up\\nSHOW REPLICA STATUS\\\\G\\n-- Confirm: Replica_IO_Running: Yes, Replica_SQL_Running: Yes\\n-- Confirm: Seconds_Behind_Source is decreasing\\n\\n-- Verify data consistency with primary\\nSELECT @@global.gtid_executed AS replica_gtid;\\n-- Compare with primary's GTID set\\n\\n-- Check binary log retention on primary\\nSHOW VARIABLES LIKE 'binlog_expire_logs_seconds';\\n\\n-- Confirm no errors\\nSELECT LAST_ERROR_NUMBER, LAST_ERROR_MESSAGE\\nFROM performance_schema.replication_applier_status_by_worker\\nWHERE LAST_ERROR_NUMBER != 0;", "parameters": null, "description": "Verify the re-provisioned replica is replicating successfully and catching up to the primary's current state."}	\N	low	f	t	30 minutes	2026-05-11 22:17:39.229791
32518	mariadb	diagnose	mysql_diagnose_semisync_replica_unreachable	{"sql": "-- Check semi-sync status and timeouts\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync%';\\n-- Key indicators:\\n-- Rpl_semi_sync_source_no_tx: transactions fallen back to async\\n-- Rpl_semi_sync_source_timefunc_failures: timeout events\\n-- Rpl_semi_sync_source_clients: should be > 0 for sync\\n\\n-- Check which replicas are connected as semi-sync\\nSELECT\\n  HOST,\\n  STATE,\\n  TIME\\nFROM information_schema.PROCESSLIST\\nWHERE COMMAND = 'Binlog Dump GTID'\\n   OR COMMAND = 'Binlog Dump';\\n\\n-- Check current timeout setting\\nSHOW VARIABLES LIKE 'rpl_semi_sync_source_timeout';\\n\\n-- Check if primary fell back to async\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_status';", "parameters": null, "description": "Confirm semi-synchronous replication timeout events and identify the unreachable synchronous replica."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32519	mariadb	execute	mysql_restore_or_failover_semisync_replica	{"sql": "-- Option A: Restore replica connectivity\\n-- On replica (if server is up but replication stopped):\\nSTART REPLICA;\\nSHOW REPLICA STATUS\\\\G\\n\\n-- Option B: If replica is permanently down, adjust semi-sync configuration\\n-- to prevent blocking primary (reduce timeout)\\nSET GLOBAL rpl_semi_sync_source_timeout = 1000;  -- 1 second timeout\\n\\n-- Check if primary automatically fell back to async\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_status';\\n-- If status=OFF, primary is already in async mode (writes unblocked)\\n\\n-- Option C: Disable semi-sync temporarily for write availability\\nSET GLOBAL rpl_semi_sync_source_enabled = OFF;\\n-- Note: This removes RPO guarantee; re-enable once replica restored", "parameters": null, "description": "Restore semi-sync replica or adjust timeout/disable semi-sync to restore primary write availability during outage."}	\N	medium	t	t	10 minutes	2026-05-11 22:17:39.229791
32520	mariadb	configure	mysql_configure_semisync_with_fallback	{"sql": "-- Configure semi-sync with safe timeout and wait-no-slave fallback\\nSET GLOBAL rpl_semi_sync_source_timeout = 10000;  -- 10 second timeout\\nSET GLOBAL rpl_semi_sync_source_wait_no_slave = 1;  -- Wait even with no slaves\\n\\n-- For lossless semi-sync (AFTER_SYNC):\\nSET GLOBAL rpl_semi_sync_source_wait_point = 'AFTER_SYNC';\\n\\n-- Configure replica semi-sync:\\n-- On replica:\\nSET GLOBAL rpl_semi_sync_replica_enabled = ON;\\n\\n-- Set up multiple semi-sync replicas for redundancy\\n-- rpl_semi_sync_source_wait_for_slave_count = 1 (minimum)\\nSET GLOBAL rpl_semi_sync_source_wait_for_slave_count = 1;\\n\\nSHOW VARIABLES LIKE 'rpl_semi_sync%';", "parameters": null, "description": "Configure semi-sync with appropriate timeout and AFTER_SYNC wait point for lossless replication with automatic async fallback."}	\N	medium	t	t	10 minutes	2026-05-11 22:17:39.229791
32521	mariadb	verify	mysql_verify_semisync_operational	{"sql": "-- Verify semi-sync is operational with replica connected\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync%';\\n-- Rpl_semi_sync_source_clients should be >= 1\\n-- Rpl_semi_sync_source_status should be ON\\n\\n-- Test a write and verify semi-sync acknowledgment\\nCREATE TABLE IF NOT EXISTS test_semisync (id INT PRIMARY KEY, ts DATETIME);\\nINSERT INTO test_semisync VALUES (1, NOW()) ON DUPLICATE KEY UPDATE ts=NOW();\\n\\n-- Check no timeout occurred\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n-- This should not have incremented since our INSERT", "parameters": null, "description": "Verify semi-sync replication is active with replica acknowledged, and test write completion without timeout."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32522	mariadb	diagnose	mysql_diagnose_slow_replica_apply_latency	{"sql": "-- Measure replica apply throughput\\nSELECT\\n  WORKER_ID,\\n  SERVICE_STATE,\\n  LAST_APPLIED_TRANSACTION,\\n  LAST_APPLIED_TRANSACTION_END_APPLY_TIMESTAMP,\\n  LAST_APPLIED_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP,\\n  TIMESTAMPDIFF(MILLISECOND,\\n    LAST_APPLIED_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP,\\n    LAST_APPLIED_TRANSACTION_END_APPLY_TIMESTAMP) AS apply_latency_ms\\nFROM performance_schema.replication_applier_status_by_worker;\\n\\n-- Check semi-sync timeout counter\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';\\n\\n-- Check parallel workers configuration\\nSHOW VARIABLES LIKE 'replica_parallel_workers';\\nSHOW VARIABLES LIKE 'replica_parallel_type';", "parameters": null, "description": "Measure replica transaction apply latency and identify the bottleneck causing semi-sync timeout violations."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32523	mariadb	configure	mysql_tune_replica_apply_performance	{"sql": "-- Enable parallel replication if not already enabled\\nSTOP REPLICA SQL_THREAD;\\n\\nSET GLOBAL replica_parallel_type = 'LOGICAL_CLOCK';\\nSET GLOBAL replica_parallel_workers = 8;\\nSET GLOBAL replica_preserve_commit_order = ON;\\n\\n-- Reduce I/O pressure on replica (safe — replica can be rebuilt)\\nSET GLOBAL innodb_flush_log_at_trx_commit = 2;\\nSET GLOBAL sync_binlog = 0;\\n\\n-- Increase InnoDB buffer pool if replica has available RAM\\nSET GLOBAL innodb_buffer_pool_size = 8589934592;  -- 8GB example\\n\\nSTART REPLICA SQL_THREAD;\\n\\n-- Verify changes\\nSHOW VARIABLES LIKE 'replica_parallel_workers';\\nSHOW VARIABLES LIKE 'innodb_flush_log_at_trx_commit';", "parameters": null, "description": "Enable parallel SQL applier and relax replica durability settings to maximize apply throughput and reduce acknowledgment latency."}	\N	medium	t	t	10 minutes	2026-05-11 22:17:39.229791
32524	mariadb	configure	mysql_adjust_semisync_timeout_threshold	{"sql": "-- Temporarily increase semi-sync timeout to give replica time to apply\\n-- This is a stopgap while performance tuning takes effect\\nSET GLOBAL rpl_semi_sync_source_timeout = 30000;  -- 30 seconds\\n\\n-- Monitor average acknowledgment wait time after tuning\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';\\n\\n-- Once replica latency is reduced, tighten timeout back:\\n-- Target: timeout should be 3-5x the 99th percentile ack latency\\n\\n-- Check primary binlog group commit optimization\\nSHOW VARIABLES LIKE 'binlog_transaction_dependency_tracking';\\nSET GLOBAL binlog_transaction_dependency_tracking = 'WRITESET';\\n\\nSHOW VARIABLES LIKE 'rpl_semi_sync_source_timeout';", "parameters": null, "description": "Increase semi-sync timeout as a temporary buffer while replica performance tuning reduces acknowledgment latency."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32525	mariadb	verify	mysql_verify_semisync_latency_improved	{"sql": "-- Monitor semi-sync acknowledgment wait times\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_tx_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n\\n-- Verify replica lag is within timeout window\\nSELECT\\n  TIMESTAMPDIFF(MILLISECOND,\\n    APPLYING_TRANSACTION_ORIGINAL_COMMIT_TIMESTAMP,\\n    NOW()) AS current_apply_lag_ms\\nFROM performance_schema.replication_applier_status_by_coordinator;\\n\\n-- Verify no timeout events since tuning\\nSELECT VARIABLE_VALUE AS no_tx_count\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME = 'Rpl_semi_sync_source_no_tx';", "parameters": null, "description": "Confirm replica acknowledgment latency is well within semi-sync timeout and timeout fallback events have ceased."}	\N	low	f	t	30 minutes	2026-05-11 22:17:39.229791
32693	mariadb	diagnose	mysql_check_table_bloat	{"sql": "SELECT table_name, ROUND(data_length/1024/1024,2) AS data_mb, ROUND(data_free/1024/1024,2) AS free_mb, ROUND(data_free/(data_length+index_length)*100,1) AS pct_free FROM information_schema.TABLES WHERE table_schema = 'target_db' AND data_free > 0 ORDER BY data_free DESC LIMIT 10;\\nSHOW VARIABLES LIKE 'innodb_purge_threads';", "parameters": {}, "description": "Identify tables with high data_free indicating wasted space from deleted/updated rows and undo log accumulation."}	\N	low	f	t	3m	2026-05-11 22:17:39.229791
32526	mariadb	diagnose	mysql_diagnose_network_latency_semisync	{"sql": "-- Measure semi-sync network roundtrip time\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_waits';\\n\\n-- Calculate average ack RTT in milliseconds:\\n-- avg_wait_time_us / net_waits = avg RTT (in microseconds)\\n\\n-- Check current timeout vs RTT\\nSHOW VARIABLES LIKE 'rpl_semi_sync_source_timeout';\\n\\n-- Check semi-sync fallback frequency\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n\\n-- Measure network RTT from OS (not SQL):\\n-- ping -c 20 <replica_host>", "parameters": null, "description": "Measure the actual network RTT between primary and synchronous replica to compare against the semi-sync timeout setting."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32527	mariadb	configure	mysql_align_semisync_timeout_to_network_rtt	{"sql": "-- Set semi-sync timeout to accommodate measured RTT with safety margin\\n-- Formula: timeout = max_observed_RTT_ms * 3 (in milliseconds)\\n-- Example: 50ms RTT → 150ms timeout minimum\\n\\nSET GLOBAL rpl_semi_sync_source_timeout = 500;  -- Adjust based on measured RTT\\n\\n-- Enable binary log compression to reduce network transfer time\\nSET GLOBAL binlog_transaction_compression = ON;\\nSET GLOBAL binlog_transaction_compression_level_zstd = 3;\\n\\n-- Verify compression is working\\nSELECT\\n  COMPRESSION_TYPE,\\n  TRANSACTION_ID_COMPRESSION_PERCENTAGE\\nFROM performance_schema.binary_log_transaction_compression_stats\\nLIMIT 5;\\n\\nSHOW VARIABLES LIKE 'rpl_semi_sync_source_timeout';", "parameters": null, "description": "Align semi-sync timeout to the measured network RTT with a safety margin, and enable binary log compression to reduce transfer time."}	\N	low	f	t	10 minutes	2026-05-11 22:17:39.229791
32528	mariadb	configure	mysql_optimize_replication_network_path	{"sql": "-- Use dedicated replication interface if available\\nSHOW VARIABLES LIKE 'group_replication_local_address';\\n\\n-- Check if replica_compressed_protocol is enabled\\nSHOW VARIABLES LIKE 'replica_compressed_protocol';\\nSET GLOBAL replica_compressed_protocol = ON;  -- Protocol-level compression\\n\\n-- For geographic replication, consider MySQL Router with connection pooling\\n-- to reduce connection overhead per transaction\\n\\n-- Check if replica is over WAN; consider async + ProxySQL for read routing\\n-- and semi-sync only for local replicas\\n\\n-- Configure binlog_group_commit on primary to batch transactions\\n-- reducing per-transaction ACK round trips:\\nSET GLOBAL binlog_group_commit_sync_delay = 500;  -- 0.5ms batching\\nSET GLOBAL binlog_group_commit_sync_no_delay_count = 5;\\n\\nSHOW VARIABLES LIKE 'binlog_group_commit%';", "parameters": null, "description": "Optimize the replication network path with compression, connection pooling, and binary log group commit batching to amortize ACK latency."}	\N	low	f	t	10 minutes	2026-05-11 22:17:39.229791
32529	mariadb	verify	mysql_verify_semisync_within_latency_budget	{"sql": "-- Verify semi-sync ACK wait time is within timeout budget\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n\\n-- Confirm no fallbacks occurring\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN (\\n  'Rpl_semi_sync_source_status',\\n  'Rpl_semi_sync_source_no_tx',\\n  'Rpl_semi_sync_source_clients'\\n);\\n\\n-- Monitor replication lag\\nSHOW REPLICA STATUS\\\\G", "parameters": null, "description": "Confirm semi-sync ACK latency is consistently within the timeout budget and no timeout fallback events are occurring."}	\N	low	f	t	30 minutes	2026-05-11 22:17:39.229791
32530	mariadb	diagnose	mysql_diagnose_replica_disk_io_bottleneck	{"sql": "-- Measure relay log write latency contributing to ACK delay\\nSELECT\\n  VARIABLE_NAME,\\n  VARIABLE_VALUE\\nFROM performance_schema.global_variables\\nWHERE VARIABLE_NAME IN (\\n  'sync_relay_log',\\n  'relay_log_space_limit',\\n  'innodb_flush_log_at_trx_commit',\\n  'sync_binlog',\\n  'innodb_io_capacity'\\n);\\n\\n-- Check I/O wait via performance_schema\\nSELECT\\n  FILE_NAME,\\n  COUNT_READ,\\n  COUNT_WRITE,\\n  SUM_TIMER_WRITE / 1000000000 AS write_time_ms,\\n  SUM_NUMBER_OF_BYTES_WRITE AS bytes_written\\nFROM performance_schema.file_summary_by_instance\\nWHERE FILE_NAME LIKE '%relay%'\\nORDER BY SUM_TIMER_WRITE DESC\\nLIMIT 10;\\n\\n-- Monitor semi-sync timeout events\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';", "parameters": null, "description": "Identify relay log write latency as the bottleneck by measuring I/O wait times on relay log files and semi-sync timeout frequency."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
32531	mariadb	configure	mysql_tune_relay_log_io_settings	{"sql": "-- Reduce relay log fsync frequency (ACK sent after write, not fsync)\\n-- sync_relay_log controls how often relay log is synced to disk\\n-- Set to 0 to let OS handle flushing (fastest ACK response)\\nSET GLOBAL sync_relay_log = 0;  -- OS-managed sync (fastest)\\n-- Or set to a higher value (e.g., 100) to sync every 100 events\\n-- SET GLOBAL sync_relay_log = 100;\\n\\n-- Note: sync_relay_log=1 (sync every event) causes slowest ACK\\n-- With GTID and crash-safe relay logs, reducing sync is safe\\n\\n-- Also reduce innodb_flush_log_at_trx_commit on replica\\nSET GLOBAL innodb_flush_log_at_trx_commit = 2;\\nSET GLOBAL sync_binlog = 0;\\n\\n-- Increase innodb_io_capacity for better I/O scheduling\\nSET GLOBAL innodb_io_capacity = 2000;\\nSET GLOBAL innodb_io_capacity_max = 4000;\\n\\nSHOW VARIABLES LIKE 'sync_relay_log';", "parameters": null, "description": "Reduce relay log sync frequency from per-event to OS-managed, dramatically reducing I/O wait and semi-sync ACK latency."}	\N	medium	t	t	5 minutes	2026-05-11 22:17:39.229791
32532	mariadb	configure	mysql_optimize_replica_storage_configuration	{"sql": "-- Check if relay logs are on SSD or spinning disk\\n-- From OS: lsblk -o NAME,ROTA,SIZE,FSTYPE (ROTA=1 means spinning)\\n\\n-- If on spinning disk, move relay logs to SSD:\\n-- Stop replica\\nSTOP REPLICA;\\n\\n-- Configure relay log path to SSD mount point\\n-- In my.cnf:\\n-- relay_log = /ssd/mysql/relay-bin\\n\\n-- Verify relay log location after reconfiguration\\nSHOW VARIABLES LIKE 'relay_log';\\n\\n-- Enable O_DIRECT for InnoDB to bypass OS buffer cache overhead\\nSET GLOBAL innodb_flush_method = 'O_DIRECT';\\n\\n-- Confirm relay_log_info_repository is TABLE for crash safety\\nSHOW VARIABLES LIKE 'relay_log_info_repository';\\n\\nSTART REPLICA;", "parameters": null, "description": "Relocate relay logs to SSD storage and configure InnoDB to use O_DIRECT I/O, reducing relay log write latency."}	\N	medium	t	t	30 minutes	2026-05-11 22:17:39.229791
32533	mariadb	verify	mysql_verify_relay_log_write_latency_reduced	{"sql": "-- Measure relay log write time after optimization\\nSELECT\\n  FILE_NAME,\\n  SUM_TIMER_WRITE / 1000000000 AS write_time_ms,\\n  COUNT_WRITE,\\n  SUM_TIMER_WRITE / COUNT_WRITE / 1000000 AS avg_write_ms\\nFROM performance_schema.file_summary_by_instance\\nWHERE FILE_NAME LIKE '%relay%'\\nORDER BY SUM_TIMER_WRITE DESC;\\n\\n-- Verify semi-sync ACK times improved\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_net_avg_wait_time';\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_no_tx';\\n\\n-- Confirm no timeout fallbacks\\nSHOW GLOBAL STATUS LIKE 'Rpl_semi_sync_source_status';", "parameters": null, "description": "Confirm relay log write latency has decreased and semi-sync ACK times are now within the timeout window."}	\N	low	f	t	15 minutes	2026-05-11 22:17:39.229791
