32585	mariadb	configure	mysql_configure_lock_and_query_timeouts_on_replica	{"sql": "-- Set lock wait timeout to prevent long lock holds on the replica\\nSET GLOBAL lock_wait_timeout = 30;  -- 30 seconds\\n\\n-- Set statement timeout for SELECT queries to prevent long reads from blocking apply\\nSET GLOBAL MAX_EXECUTION_TIME = 60000;  -- 60 seconds for SELECTs\\n\\n-- Persist in my.cnf:\\n-- [mysqld]\\n-- lock_wait_timeout = 30\\n-- max_execution_time = 60000\\n\\nSHOW VARIABLES LIKE 'lock_wait_timeout';\\nSHOW VARIABLES LIKE 'max_execution_time';", "parameters": null, "description": "Configures lock and query timeouts on the replica to automatically abort queries before they can block replication for an extended period"}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
