32855	mariadb	execute	mysql_lob_cleanup_archive	{"sql": "-- Delete or archive old LOB rows exceeding retention policy\\n-- Example: remove binary data older than 1 year\\nDELETE FROM your_schema.your_table\\nWHERE created_at < DATE_SUB(NOW(), INTERVAL 1 YEAR)\\n  AND lob_column IS NOT NULL\\nLIMIT 10000;\\n\\n-- After deletion, reclaim free space\\nOPTIMIZE TABLE your_schema.your_table;\\n\\n-- Alternatively, move LOB data to archive table\\nINSERT INTO your_schema.your_table_archive\\nSELECT * FROM your_schema.your_table\\nWHERE created_at < DATE_SUB(NOW(), INTERVAL 1 YEAR);\\n\\nDELETE FROM your_schema.your_table\\nWHERE created_at < DATE_SUB(NOW(), INTERVAL 1 YEAR)\\nLIMIT 10000;", "parameters": null, "description": "Remove or archive old LOB data and compact the tablespace to reclaim free space."}	\N	medium	t	f	30 minutes	2026-05-11 22:17:39.229791
