33001	mariadb	configure	mysql_configure_version_monitoring	{"sql": "-- Query to embed in monitoring dashboards\\nSELECT\\n  @@hostname AS host,\\n  VERSION() AS mysql_version,\\n  SUBSTRING_INDEX(VERSION(), '.', 2) AS major_minor,\\n  NOW() AS checked_at;\\n\\n-- Create a version tracking table for multi-instance environments\\nCREATE TABLE IF NOT EXISTS dba_inventory.mysql_version_tracking (\\n  instance_id VARCHAR(100) PRIMARY KEY,\\n  hostname VARCHAR(255),\\n  mysql_version VARCHAR(50),\\n  eol_date DATE,\\n  last_checked TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\\n  upgrade_target VARCHAR(50),\\n  upgrade_by_date DATE\\n);\\n\\n-- Insert current instance\\nINSERT INTO dba_inventory.mysql_version_tracking\\n  (instance_id, hostname, mysql_version, eol_date, upgrade_target)\\nVALUES (@@hostname, @@hostname, VERSION(), '2026-04-30', '8.4');", "parameters": null, "description": "Creates a version tracking table and populates it with current MySQL instance information and EOL dates."}	\N	low	f	t	15 minutes	2026-05-11 22:17:39.229791
