33140	mariadb	configure	mysql_tune_checkpoint_settings	{"sql": "-- Tune IO capacity to match actual storage capability\\n-- SSDs: innodb_io_capacity=2000-10000, HDDs: 200-1000\\nSET GLOBAL innodb_io_capacity = 2000;\\nSET GLOBAL innodb_io_capacity_max = 4000;\\n\\n-- Allow more dirty pages before aggressive flushing\\nSET GLOBAL innodb_max_dirty_pages_pct = 75;\\nSET GLOBAL innodb_max_dirty_pages_pct_lwm = 10;\\n\\n-- Note: innodb_log_file_size requires restart (add to my.cnf):\\n-- innodb_log_file_size=2G  # Larger log = less frequent checkpoints\\n\\nSHOW VARIABLES LIKE 'innodb_flush_neighbors';", "parameters": null, "description": "Tune InnoDB IO capacity and dirty page thresholds to reduce checkpoint frequency spikes"}	\N	medium	t	t	5 minutes	2026-05-11 22:17:39.229791
33141	mariadb	verify	mysql_verify_flush_smoothness	{"sql": "-- Verify dirty page count is stable and below threshold\\nSELECT\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_pages_dirty') AS dirty_pages,\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_pages_total') AS total_pages,\\n  ROUND(\\n    (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_pages_dirty') /\\n    (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_pages_total') * 100\\n  , 2) AS dirty_pct;\\n\\n-- Confirm log waits are zero\\nSELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_log_waits';", "parameters": null, "description": "Confirm dirty page percentage is within configured limits and redo log waits are eliminated"}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
33142	mariadb	diagnose	mysql_check_memory_and_swap	{"sql": "-- Check MySQL memory usage\\nSELECT VARIABLE_NAME, ROUND(VARIABLE_VALUE/1024/1024, 2) AS mb\\nFROM performance_schema.global_variables\\nWHERE VARIABLE_NAME IN ('innodb_buffer_pool_size','key_buffer_size',\\n  'tmp_table_size','max_heap_table_size','sort_buffer_size',\\n  'read_buffer_size','join_buffer_size','thread_stack')\\nORDER BY VARIABLE_NAME;\\n\\n-- Check per-connection memory consumption estimate\\nSELECT @@max_connections * (@@sort_buffer_size + @@read_buffer_size +\\n  @@read_rnd_buffer_size + @@join_buffer_size + @@thread_stack) / 1024 / 1024\\n  AS max_per_conn_mem_mb;", "parameters": null, "description": "Assess MySQL memory configuration to identify overcommitment relative to available system RAM"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
33143	mariadb	configure	mysql_rightsize_buffer_pool	{"sql": "-- Reduce buffer pool to leave OS headroom (target: 70-80% of RAM)\\n-- Dynamically resize without restart (MySQL 5.7.5+)\\nSET GLOBAL innodb_buffer_pool_size = 4294967296; -- Example: 4GB, adjust to 70-80% of RAM\\n\\n-- Reduce per-connection buffers to lower peak memory\\nSET GLOBAL sort_buffer_size = 1048576;    -- 1MB (default is often too high)\\nSET GLOBAL read_buffer_size = 131072;     -- 128KB\\nSET GLOBAL join_buffer_size = 262144;     -- 256KB\\n\\n-- Check resize progress\\nSHOW STATUS LIKE 'Innodb_buffer_pool_resize_status';", "parameters": null, "description": "Resize InnoDB buffer pool and per-connection buffers to prevent system-level memory overcommitment"}	\N	medium	t	t	10 minutes	2026-05-11 22:17:39.229791
33144	mariadb	configure	mysql_configure_swap_prevention	{"sql": "-- Note: The following are OS-level commands, run as root outside MySQL\\n-- Disable swap for MySQL process:\\n-- mlockall() alternative: set vm.swappiness to low\\n-- echo 10 > /proc/sys/vm/swappiness   (temporary)\\n-- Add to /etc/sysctl.conf: vm.swappiness=10  (persistent)\\n\\n-- In MySQL, enable large pages to prevent swapping (requires OS hugepages setup)\\nSHOW VARIABLES LIKE 'large_pages';\\nSHOW VARIABLES LIKE 'large_page_size';\\n\\n-- Verify current swap usage\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME LIKE 'Memory%'\\nORDER BY VARIABLE_NAME;", "parameters": null, "description": "Configure OS-level swap avoidance for MySQL and optionally enable large pages"}	\N	medium	t	t	10 minutes	2026-05-11 22:17:39.229791
33145	mariadb	verify	mysql_verify_no_swap_activity	{"sql": "-- Verify buffer pool resize completed\\nSHOW STATUS LIKE 'Innodb_buffer_pool_resize_status';\\n\\n-- Check buffer pool hit rate recovered\\nSELECT FORMAT(((1 - (\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_reads') /\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_read_requests')\\n)) * 100), 2) AS hit_rate_pct;\\n\\n-- Verify memory settings are within bounds\\nSELECT ROUND(@@innodb_buffer_pool_size/1024/1024/1024, 2) AS buffer_pool_gb,\\n       @@max_connections AS max_conn;", "parameters": null, "description": "Confirm resize completed, swap activity ceased, and buffer pool hit rate is acceptable"}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
33146	mariadb	diagnose	mysql_assess_eviction_policy	{"sql": "-- Check current LRU eviction settings\\nSHOW VARIABLES LIKE 'innodb_old_blocks_pct';\\nSHOW VARIABLES LIKE 'innodb_old_blocks_time';\\nSHOW VARIABLES LIKE 'innodb_lru_scan_depth';\\nSHOW VARIABLES LIKE 'innodb_buffer_pool_size';\\n\\n-- Check read-ahead and eviction metrics\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN (\\n  'Innodb_buffer_pool_reads',\\n  'Innodb_buffer_pool_read_ahead',\\n  'Innodb_buffer_pool_read_ahead_evicted',\\n  'Innodb_buffer_pool_pages_LRU_flushed'\\n);", "parameters": null, "description": "Review current LRU eviction configuration and identify read-ahead eviction waste"}	\N	low	f	t	2 minutes	2026-05-11 22:17:39.229791
33147	mariadb	diagnose	mysql_check_buffer_pool_page_age	{"sql": "-- Check page age distribution in buffer pool\\nSELECT PAGE_TYPE, COUNT(*) AS page_count,\\n       MIN(OLDEST_MODIFICATION) AS min_age,\\n       MAX(OLDEST_MODIFICATION) AS max_age\\nFROM information_schema.INNODB_BUFFER_PAGE\\nGROUP BY PAGE_TYPE\\nORDER BY page_count DESC;\\n\\n-- Check if full table scans are polluting buffer pool\\nSELECT DIGEST_TEXT, SUM_ROWS_EXAMINED, SUM_NO_INDEX_USED\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SUM_NO_INDEX_USED > 0\\nORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10;", "parameters": null, "description": "Analyze buffer pool page age distribution and identify scan queries polluting the LRU list"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
33148	mariadb	configure	mysql_tune_lru_eviction_policy	{"sql": "-- Tune LRU to protect hot pages from scan pollution\\n-- Reduce old sublist to 20% (default 37%) for scan-heavy workloads\\nSET GLOBAL innodb_old_blocks_pct = 20;\\n\\n-- Require page to be accessed again after 2 seconds before moving to new sublist\\n-- Prevents single-pass scans from evicting hot pages\\nSET GLOBAL innodb_old_blocks_time = 2000;  -- milliseconds\\n\\n-- Reduce read-ahead if causing eviction waste (0=disable, 8=default linear)\\nSET GLOBAL innodb_read_ahead_threshold = 56;  -- require 56/64 pages before triggering (more conservative)\\n\\n-- Verify settings applied\\nSHOW VARIABLES LIKE 'innodb_old_blocks%';\\nSHOW VARIABLES LIKE 'innodb_read_ahead_threshold';", "parameters": null, "description": "Configure InnoDB LRU midpoint insertion and old blocks time to protect hot pages from scan eviction"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
33149	mariadb	verify	mysql_verify_eviction_improvement	{"sql": "-- Check read-ahead eviction ratio improved\\nSELECT\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_read_ahead_evicted') AS evicted,\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_read_ahead') AS read_ahead,\\n  ROUND(\\n    (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_read_ahead_evicted') /\\n    NULLIF((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_read_ahead'), 0) * 100\\n  , 2) AS eviction_pct;\\n\\n-- Confirm buffer pool hit rate\\nSELECT FORMAT(((1 - (\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_reads') /\\n  (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME='Innodb_buffer_pool_read_requests')\\n)) * 100), 2) AS hit_rate_pct;", "parameters": null, "description": "Confirm read-ahead eviction ratio decreased and buffer pool hit rate improved after LRU tuning"}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
33150	mariadb	diagnose	mysql_identify_literal_query_patterns	{"sql": "-- Find top queries by number of unique digests (indicates literal variation)\\nSELECT SCHEMA_NAME, COUNT(*) AS digest_count,\\n       SUM(COUNT_STAR) AS total_executions\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME NOT IN ('mysql','performance_schema','information_schema','sys')\\nGROUP BY SCHEMA_NAME\\nORDER BY digest_count DESC;\\n\\n-- Find high-literal-variation queries\\nSELECT DIGEST_TEXT, COUNT_STAR,\\n       ROUND(SUM_TIMER_WAIT/1e12, 3) AS total_sec,\\n       SUM_ROWS_EXAMINED\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\nORDER BY COUNT_STAR ASC, SUM_TIMER_WAIT DESC\\nLIMIT 30;", "parameters": null, "description": "Identify schemas with high digest counts indicating many unique literal-based queries"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
