33174	mariadb	diagnose	mysql_identify_third_party_query_source	{"sql": "-- Identify application sources generating bad queries\\nSELECT\\n  attr_value AS application,\\n  COUNT(DISTINCT d.DIGEST) AS unique_digests\\nFROM performance_schema.session_connect_attrs a\\nJOIN performance_schema.threads t ON a.PROCESSLIST_ID = t.PROCESSLIST_ID\\nJOIN performance_schema.events_statements_summary_by_digest d\\n  ON d.SCHEMA_NAME = t.PROCESSLIST_DB\\nWHERE a.attr_name = 'program_name'\\nGROUP BY attr_value\\nORDER BY unique_digests DESC;\\n\\n-- Top queries from the problematic application\\nSELECT DIGEST_TEXT, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\n  AND COUNT_STAR < 5\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 20;", "parameters": null, "description": "Identify which third-party application generates the most unique non-parameterized queries"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
33175	mariadb	configure	mysql_deploy_proxysql_normalization	{"sql": "-- ProxySQL query normalization for third-party apps (run on ProxySQL admin port 6032)\\n-- Add query rewrite rule to normalize common patterns:\\n-- INSERT INTO mysql_query_rules (rule_id, active, match_digest,\\n--   replace_pattern, apply) VALUES\\n--   (100, 1, '^SELECT .* FROM orders WHERE id = [0-9]+',\\n--    'SELECT * FROM orders WHERE id = ?', 1);\\n-- LOAD MYSQL QUERY RULES TO RUNTIME;\\n-- SAVE MYSQL QUERY RULES TO DISK;\\n\\n-- On MySQL: verify query digest pattern to build ProxySQL rule\\nSELECT DIGEST, DIGEST_TEXT\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE SCHEMA_NAME = DATABASE()\\nORDER BY SUM_TIMER_WAIT DESC LIMIT 10;", "parameters": null, "description": "Deploy ProxySQL query rewriting rules to normalize third-party application queries transparently"}	\N	medium	t	t	20 minutes	2026-05-11 22:17:39.229791
