33182	mariadb	diagnose	mysql_identify_idle_blocking_sessions	{"sql": "-- Find idle sessions with open transactions\\nSELECT p.ID AS thread_id, p.USER, p.HOST, p.DB,\\n       p.COMMAND, p.TIME AS idle_seconds, p.STATE,\\n       t.trx_id, t.trx_started\\nFROM information_schema.PROCESSLIST p\\nJOIN information_schema.INNODB_TRX t ON t.trx_mysql_thread_id = p.ID\\nWHERE p.COMMAND = 'Sleep'\\n  AND p.TIME > 60  -- idle for more than 60 seconds\\nORDER BY p.TIME DESC;\\n\\n-- Check if wait_timeout is set appropriately\\nSHOW VARIABLES LIKE 'wait_timeout';\\nSHOW VARIABLES LIKE 'interactive_timeout';", "parameters": null, "description": "Find idle sleeping connections that have open transactions blocking purge thread progress"}	\N	low	f	t	2 minutes	2026-05-11 22:17:39.229791
33183	mariadb	execute	mysql_kill_idle_transactions	{"sql": "-- Kill idle sessions with long-running transactions\\n-- Replace thread_ids with actual values from step 2\\n-- KILL CONNECTION <thread_id>;\\n\\n-- Generate KILL statements for all idle transactions > 5 minutes\\nSELECT CONCAT('KILL CONNECTION ', p.ID, ';') AS kill_stmt,\\n       p.USER, p.TIME AS idle_seconds, t.trx_started\\nFROM information_schema.PROCESSLIST p\\nJOIN information_schema.INNODB_TRX t ON t.trx_mysql_thread_id = p.ID\\nWHERE p.COMMAND = 'Sleep' AND p.TIME > 300\\nORDER BY p.TIME DESC;\\n\\n-- Set wait_timeout to auto-kill future idle connections\\nSET GLOBAL wait_timeout = 300;      -- 5 minutes\\nSET GLOBAL interactive_timeout = 300;", "parameters": null, "description": "Terminate idle transactions blocking InnoDB purge and configure timeout to prevent recurrence"}	\N	medium	t	f	5 minutes	2026-05-11 22:17:39.229791
33184	mariadb	diagnose	mysql_measure_purge_lag	{"sql": "-- Check InnoDB purge lag (history list length)\\nSELECT NAME, COUNT FROM information_schema.INNODB_METRICS\\nWHERE NAME IN ('trx_rseg_history_len','innodb_purge_trx_id_age',\\n               'buffer_pool_pages_dirty','innodb_data_writes')\\nORDER BY NAME;\\n\\n-- Check write rate to quantify DELETE/UPDATE pressure\\nSELECT VARIABLE_NAME, VARIABLE_VALUE\\nFROM performance_schema.global_status\\nWHERE VARIABLE_NAME IN ('Com_delete','Com_update','Com_insert',\\n  'Innodb_rows_deleted','Innodb_rows_updated','Innodb_rows_inserted');\\n\\n-- Check current purge thread configuration\\nSHOW VARIABLES LIKE 'innodb_purge_threads';\\nSHOW VARIABLES LIKE 'innodb_max_purge_lag%';", "parameters": null, "description": "Measure InnoDB purge backlog and write rates to quantify the cleanup deficit"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
33185	mariadb	diagnose	mysql_identify_high_churn_tables	{"sql": "-- Find tables with highest DELETE/UPDATE activity\\nSELECT OBJECT_SCHEMA, OBJECT_NAME,\\n       COUNT_DELETE, COUNT_UPDATE, COUNT_INSERT,\\n       COUNT_DELETE + COUNT_UPDATE AS total_dml\\nFROM performance_schema.table_io_waits_summary_by_table\\nWHERE OBJECT_SCHEMA NOT IN ('mysql','performance_schema','information_schema','sys')\\nORDER BY total_dml DESC LIMIT 20;\\n\\n-- Check current bloat on high-churn tables\\nSELECT TABLE_NAME,\\n       ROUND(DATA_FREE/1024/1024, 2) AS free_mb,\\n       ROUND(DATA_LENGTH/1024/1024, 2) AS data_mb,\\n       ROUND(DATA_FREE/(DATA_LENGTH+DATA_FREE)*100, 2) AS pct_free\\nFROM information_schema.TABLES\\nWHERE TABLE_SCHEMA = DATABASE()\\nORDER BY DATA_FREE DESC LIMIT 10;", "parameters": null, "description": "Identify high-churn tables with most DELETE/UPDATE activity and measure current bloat levels"}	\N	low	f	t	3 minutes	2026-05-11 22:17:39.229791
