33786	mariadb	diagnose	mysql_diagnose_unused_historical_indexes	{"sql": "-- Find indexes with zero reads over the observation period\\nSELECT p.OBJECT_NAME, p.INDEX_NAME, p.COUNT_FETCH,\\n  p.COUNT_INSERT + p.COUNT_UPDATE + p.COUNT_DELETE AS write_ops\\nFROM performance_schema.table_io_waits_summary_by_index_usage p\\nWHERE p.OBJECT_SCHEMA = DATABASE()\\n  AND p.INDEX_NAME IS NOT NULL\\n  AND p.INDEX_NAME <> 'PRIMARY'\\n  AND p.COUNT_FETCH = 0\\nORDER BY write_ops DESC;\\n\\n-- Cross-reference with index metadata\\nSELECT TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columns\\nFROM information_schema.STATISTICS\\nWHERE TABLE_SCHEMA = DATABASE()\\nGROUP BY TABLE_NAME, INDEX_NAME\\nHAVING INDEX_NAME IN (\\n  SELECT INDEX_NAME FROM performance_schema.table_io_waits_summary_by_index_usage\\n  WHERE OBJECT_SCHEMA = DATABASE() AND COUNT_FETCH = 0\\n);", "parameters": null, "description": "Identify indexes with zero read activity over a representative observation period of at least 24-48 hours."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
