33804	mariadb	diagnose	mysql_diagnose_duplicate_covered_index	{"sql": "-- Find duplicate and prefix-covered indexes\\nSELECT a.TABLE_NAME,\\n  a.INDEX_NAME AS redundant_index, a.cols AS redundant_cols,\\n  b.INDEX_NAME AS covering_index, b.cols AS covering_cols\\nFROM (\\n  SELECT TABLE_NAME, INDEX_NAME,\\n    GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols\\n  FROM information_schema.STATISTICS\\n  WHERE TABLE_SCHEMA = DATABASE()\\n  GROUP BY TABLE_NAME, INDEX_NAME\\n) a\\nJOIN (\\n  SELECT TABLE_NAME, INDEX_NAME,\\n    GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols\\n  FROM information_schema.STATISTICS\\n  WHERE TABLE_SCHEMA = DATABASE()\\n  GROUP BY TABLE_NAME, INDEX_NAME\\n) b\\n  ON a.TABLE_NAME = b.TABLE_NAME\\n  AND a.INDEX_NAME <> b.INDEX_NAME\\n  AND (b.cols = a.cols OR b.cols LIKE CONCAT(a.cols, ',%'));", "parameters": null, "description": "Identify indexes that are exact duplicates or strict prefixes of another index on the same table."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
