33806	mariadb	diagnose	mysql_diagnose_low_usage_indexes	{"sql": "-- Rank indexes by fetch frequency\\nSELECT OBJECT_NAME, INDEX_NAME,\\n  COUNT_FETCH,\\n  COUNT_INSERT + COUNT_UPDATE + COUNT_DELETE AS write_cost,\\n  ROUND(COUNT_FETCH * 100.0 / NULLIF(COUNT_INSERT + COUNT_UPDATE + COUNT_DELETE, 0), 2) AS fetch_to_write_ratio\\nFROM performance_schema.table_io_waits_summary_by_index_usage\\nWHERE OBJECT_SCHEMA = DATABASE()\\n  AND INDEX_NAME IS NOT NULL\\n  AND INDEX_NAME <> 'PRIMARY'\\nORDER BY COUNT_FETCH ASC, write_cost DESC\\nLIMIT 20;\\n\\n-- Check how long since last server restart (observation window)\\nSHOW STATUS LIKE 'Uptime';", "parameters": null, "description": "Rank all indexes by read-to-write ratio and identify those with very low fetch counts relative to write maintenance cost."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
33807	mariadb	execute	mysql_disable_and_remove_low_usage_index	{"sql": "-- Step 1: Make the index invisible to test removal safely (MySQL 8.0+)\\nALTER TABLE your_table ALTER INDEX idx_low_usage INVISIBLE;\\n\\n-- Monitor for 24-48 hours\\n-- Check no slow queries appeared\\nSELECT DIGEST_TEXT, AVG_TIMER_WAIT/1e12 AS avg_sec\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE DIGEST_TEXT LIKE '%your_table%'\\nORDER BY AVG_TIMER_WAIT DESC LIMIT 5;\\n\\n-- Step 2: Drop after monitoring confirms no regression\\nALTER TABLE your_table DROP INDEX idx_low_usage;\\nANALYZE TABLE your_table;", "parameters": null, "description": "Use the invisible index approach to safely remove the low-usage index after confirming no query regression."}	\N	low	t	t	5 minutes	2026-05-11 22:17:39.229791
33808	mariadb	verify	mysql_verify_low_usage_index_removed	{"sql": "-- Confirm index is removed\\nSELECT INDEX_NAME FROM information_schema.STATISTICS\\nWHERE TABLE_SCHEMA = DATABASE()\\n  AND TABLE_NAME = 'your_table'\\n  AND INDEX_NAME = 'idx_low_usage';\\n\\n-- Verify write latency improved\\nSELECT SUM_TIMER_INSERT/1e12, COUNT_INSERT\\nFROM performance_schema.table_io_waits_summary_by_table\\nWHERE OBJECT_SCHEMA = DATABASE() AND OBJECT_NAME = 'your_table';\\n\\n-- Check no query regressions after 24h\\nSELECT DIGEST_TEXT, AVG_TIMER_WAIT/1e12 AS avg_sec, COUNT_STAR\\nFROM performance_schema.events_statements_summary_by_digest\\nWHERE DIGEST_TEXT LIKE '%your_table%'\\nORDER BY AVG_TIMER_WAIT DESC LIMIT 10;", "parameters": null, "description": "Confirm index removal is complete and no queries have regressed based on performance_schema data."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
33809	mariadb	diagnose	mysql_diagnose_index_accumulation_baseline	{"sql": "-- Baseline: count indexes per table and identify over-indexed tables\\nSELECT TABLE_NAME, COUNT(DISTINCT INDEX_NAME) AS index_count,\\n  SUM(STAT_VALUE) * @@innodb_page_size / 1024 / 1024 AS total_index_mb\\nFROM mysql.innodb_index_stats\\nWHERE database_name = DATABASE()\\n  AND stat_name = 'size'\\nGROUP BY TABLE_NAME\\nORDER BY index_count DESC\\nLIMIT 20;\\n\\n-- Find indexes with COUNT_FETCH = 0 across all tables\\nSELECT OBJECT_NAME, COUNT(*) AS unused_index_count\\nFROM performance_schema.table_io_waits_summary_by_index_usage\\nWHERE OBJECT_SCHEMA = DATABASE()\\n  AND COUNT_FETCH = 0\\n  AND INDEX_NAME IS NOT NULL\\n  AND INDEX_NAME <> 'PRIMARY'\\nGROUP BY OBJECT_NAME\\nORDER BY unused_index_count DESC;", "parameters": null, "description": "Establish a baseline of current index count, size, and usage across all tables to quantify the maintenance gap."}	\N	low	f	t	5 minutes	2026-05-11 22:17:39.229791
33810	mariadb	execute	mysql_implement_index_audit_process	{"sql": "-- Create a scheduled event to log unused indexes monthly\\nCREATE EVENT IF NOT EXISTS evt_monthly_index_audit\\nON SCHEDULE EVERY 1 MONTH\\nSTARTS CURRENT_TIMESTAMP\\nDO\\n  INSERT INTO dba_audit.index_usage_snapshot\\n    (snapshot_date, table_name, index_name, count_fetch, count_write)\\n  SELECT NOW(), OBJECT_NAME, INDEX_NAME, COUNT_FETCH,\\n    COUNT_INSERT + COUNT_UPDATE + COUNT_DELETE\\n  FROM performance_schema.table_io_waits_summary_by_index_usage\\n  WHERE OBJECT_SCHEMA = DATABASE();\\n\\n-- Ensure event scheduler is enabled\\nSET GLOBAL event_scheduler = ON;\\n\\n-- Immediate cleanup: make all currently unused indexes invisible\\n-- (Run the invisible-index script from RC09/RC10 for each zero-fetch index)\\nALTER TABLE your_table ALTER INDEX idx_unused_1 INVISIBLE;\\nALTER TABLE your_table ALTER INDEX idx_unused_2 INVISIBLE;", "parameters": null, "description": "Implement a MySQL event-based monthly index usage snapshot and begin immediate cleanup of currently unused indexes."}	\N	low	t	t	5 minutes	2026-05-11 22:17:39.229791
