34762	mariadb	execute	mysql_enable_dormancy_monitoring	{"sql": "-- Enable performance_schema connection tracking\\nUPDATE performance_schema.setup_consumers SET enabled = 'YES' WHERE name = 'events_statements_history_long';\\n-- Create a tracking table for last login (if audit log unavailable)\\nCREATE TABLE IF NOT EXISTS mysql_admin.account_last_seen (\\n  user VARCHAR(32) NOT NULL,\\n  host VARCHAR(255) NOT NULL,\\n  last_seen TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\\n  PRIMARY KEY (user, host)\\n);\\n-- Create an event to refresh last_seen from performance_schema\\nCREATE EVENT IF NOT EXISTS mysql_admin.refresh_last_seen\\nON SCHEDULE EVERY 1 DAY\\nDO\\n  INSERT INTO mysql_admin.account_last_seen (user, host, last_seen)\\n  SELECT user, host, MAX(event_time)\\n  FROM performance_schema.events_statements_summary_by_account_by_event_name\\n  WHERE user IS NOT NULL\\n  GROUP BY user, host\\n  ON DUPLICATE KEY UPDATE last_seen = VALUES(last_seen);\\n-- Enable event scheduler\\nSET GLOBAL event_scheduler = ON;", "parameters": {}, "description": "Enable performance_schema statement tracking and create a persistent last-login tracking table and scheduled event to identify dormant accounts over time."}	\N	low	t	t	20m	2026-05-11 22:17:39.229791
