34768	mariadb	execute	mysql_tag_and_prune_orphaned_service_accounts	{"sql": "-- Add a comment to track application ownership (MySQL 8.0.21+)\\nALTER USER '<service_user>'@'<host>' COMMENT '{\\"application\\": \\"<app_name>\\", \\"owner\\": \\"<team>\\", \\"created\\": \\"<date>\\"}';\\n-- Lock accounts for decommissioned applications immediately\\nALTER USER '<orphaned_svc>'@'%' ACCOUNT LOCK;\\nALTER USER '<orphaned_svc>'@'%' PASSWORD EXPIRE;\\n-- After confirming no active connections for 30 days, drop\\nDROP USER IF EXISTS '<orphaned_svc>'@'%';\\nFLUSH PRIVILEGES;\\n-- Create an inventory table for ongoing tracking\\nCREATE TABLE IF NOT EXISTS mysql_admin.service_account_registry (\\n  svc_user VARCHAR(32) NOT NULL,\\n  svc_host VARCHAR(255) NOT NULL,\\n  application VARCHAR(255),\\n  owner_team VARCHAR(255),\\n  created_date DATE,\\n  status ENUM('active', 'locked', 'pending_removal') DEFAULT 'active',\\n  PRIMARY KEY (svc_user, svc_host)\\n);", "parameters": {"orphaned_svc": "service account for decommissioned application", "service_user": "service account username to tag"}, "description": "Tag active service accounts with application ownership metadata, lock orphaned accounts for decommissioned applications, and establish a persistent service account registry."}	\N	medium	t	f	30m	2026-05-11 22:17:39.229791
