34777	mariadb	execute	mysql_build_account_inventory_infrastructure	{"sql": "-- Create formal inventory schema\\nCREATE DATABASE IF NOT EXISTS mysql_admin;\\nCREATE TABLE IF NOT EXISTS mysql_admin.account_inventory (\\n  account_id INT AUTO_INCREMENT PRIMARY KEY,\\n  mysql_user VARCHAR(32) NOT NULL,\\n  mysql_host VARCHAR(255) NOT NULL,\\n  account_type ENUM('human', 'service', 'admin', 'contractor', 'system') NOT NULL,\\n  owner_name VARCHAR(255),\\n  owner_email VARCHAR(255),\\n  business_justification TEXT,\\n  approved_by VARCHAR(255),\\n  created_date DATE NOT NULL,\\n  review_due_date DATE NOT NULL,\\n  status ENUM('active', 'locked', 'pending_removal', 'removed') DEFAULT 'active',\\n  notes TEXT,\\n  last_audited TIMESTAMP,\\n  UNIQUE KEY uq_account (mysql_user, mysql_host)\\n);\\n-- Populate from current account baseline\\nINSERT IGNORE INTO mysql_admin.account_inventory\\n  (mysql_user, mysql_host, account_type, created_date, review_due_date)\\nSELECT user, host, 'human', CURDATE(), DATE_ADD(CURDATE(), INTERVAL 90 DAY)\\nFROM mysql.user\\nWHERE user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session') AND user != '';", "parameters": {}, "description": "Create a formal account inventory table, populate it from the current MySQL user baseline, and establish fields for ownership, justification, and review scheduling."}	\N	low	t	t	30m	2026-05-11 22:17:39.229791
