34780	mariadb	execute	mysql_implement_monthly_dormancy_review	{"sql": "-- Create a monthly review log table\\nCREATE TABLE IF NOT EXISTS mysql_admin.access_review_log (\\n  review_id INT AUTO_INCREMENT PRIMARY KEY,\\n  review_date DATE NOT NULL,\\n  reviewer VARCHAR(255),\\n  mysql_user VARCHAR(32) NOT NULL,\\n  mysql_host VARCHAR(255) NOT NULL,\\n  days_inactive INT,\\n  action_taken ENUM('no_action', 'warned', 'locked', 'dropped') DEFAULT 'no_action',\\n  notes TEXT\\n);\\n-- Create scheduled event for monthly dormancy report\\nCREATE EVENT IF NOT EXISTS mysql_admin.monthly_dormancy_report\\nON SCHEDULE EVERY 1 MONTH STARTS (DATE_FORMAT(NOW() ,'%Y-%m-01') + INTERVAL 1 MONTH)\\nDO\\n  INSERT INTO mysql_admin.access_review_log (review_date, mysql_user, mysql_host, days_inactive)\\n  SELECT CURDATE(), user, host, DATEDIFF(CURDATE(), password_last_changed)\\n  FROM mysql.user\\n  WHERE user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n    AND user != ''\\n    AND password_last_changed < DATE_SUB(CURDATE(), INTERVAL 30 DAY);\\n-- Lock accounts inactive for over 60 days automatically\\nCREATE EVENT IF NOT EXISTS mysql_admin.auto_lock_dormant\\nON SCHEDULE EVERY 1 MONTH STARTS (DATE_FORMAT(NOW() ,'%Y-%m-01') + INTERVAL 1 MONTH)\\nDO\\n  -- In practice implement via stored procedure:\\n  CALL mysql_admin.lock_dormant_accounts(60);", "parameters": {}, "description": "Implement monthly automated dormancy reporting and establish an auto-lock policy for accounts inactive beyond 60 days, reducing the effective review window from quarterly to monthly."}	\N	medium	t	t	30m	2026-05-11 22:17:39.229791
