34785	mariadb	diagnose	mysql_assess_dormancy_detection_gaps	{"sql": "-- Check if performance_schema account tracking is enabled\\nSELECT * FROM performance_schema.setup_actors WHERE host = '%' AND user = '%';\\n-- Check account-level statement summaries for activity data\\nSELECT user, host, COUNT_STAR AS total_statements,\\n       LAST_SEEN\\nFROM performance_schema.accounts\\nWHERE user IS NOT NULL\\n  AND user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\nORDER BY LAST_SEEN ASC\\nLIMIT 20;\\n-- Identify accounts with zero activity in performance_schema\\nSELECT u.user, u.host\\nFROM mysql.user u\\nLEFT JOIN performance_schema.accounts pa ON pa.user = u.user AND pa.host = u.host\\nWHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n  AND u.user != ''\\n  AND (pa.user IS NULL OR pa.LAST_SEEN < DATE_SUB(NOW(), INTERVAL 90 DAY));", "parameters": {}, "description": "Assess the current state of performance_schema account tracking to identify gaps in dormancy detection coverage."}	\N	low	f	t	5m	2026-05-11 22:17:39.229791
34786	mariadb	execute	mysql_deploy_automated_dormancy_detection	{"sql": "-- Ensure performance_schema actors are enabled\\nUPDATE performance_schema.setup_actors SET enabled = 'YES', history = 'YES' WHERE host = '%' AND user = '%';\\n-- Create dormancy detection stored procedure\\nDELIMITER //\\nCREATE PROCEDURE IF NOT EXISTS mysql_admin.detect_dormant_accounts(IN threshold_days INT)\\nBEGIN\\n  SELECT u.user, u.host, u.account_locked,\\n         pa.LAST_SEEN,\\n         DATEDIFF(NOW(), pa.LAST_SEEN) AS days_since_seen\\n  FROM mysql.user u\\n  LEFT JOIN performance_schema.accounts pa ON pa.user = u.user\\n  WHERE u.user NOT IN ('root', 'mysql.sys', 'mysql.infoschema', 'mysql.session')\\n    AND u.user != ''\\n    AND u.account_locked = 'N'\\n    AND (pa.LAST_SEEN IS NULL OR pa.LAST_SEEN < DATE_SUB(NOW(), INTERVAL threshold_days DAY))\\n  ORDER BY days_since_seen DESC;\\nEND //\\nDELIMITER ;\\n-- Schedule monthly dormancy detection report\\nCREATE EVENT IF NOT EXISTS mysql_admin.auto_dormancy_check\\nON SCHEDULE EVERY 1 MONTH\\nDO CALL mysql_admin.detect_dormant_accounts(90);", "parameters": {}, "description": "Enable performance_schema account tracking, deploy a stored procedure for configurable dormancy detection, and schedule it as a monthly automated event."}	\N	low	t	t	20m	2026-05-11 22:17:39.229791
