34976	mariadb	execute	mysql_implement_scheduled_grant_audit	{"sql": "-- Create a stored procedure for automated privilege audit\\nDELIMITER //\\nCREATE PROCEDURE IF NOT EXISTS audit_db.run_privilege_audit()\\nBEGIN\\n  -- Record all broad grants to audit table\\n  INSERT INTO audit_db.privilege_audit_log\\n    (audit_date, user, host, privilege_type, scope, alert_level)\\n  SELECT\\n    CURDATE(),\\n    User,\\n    Host,\\n    CASE\\n      WHEN Super_priv = 'Y' THEN 'SUPER'\\n      WHEN Grant_priv = 'Y' THEN 'GRANT_OPTION'\\n      WHEN Select_priv = 'Y' THEN 'GLOBAL_SELECT'\\n      ELSE 'OTHER'\\n    END,\\n    'GLOBAL',\\n    CASE WHEN User = '' THEN 'CRITICAL' WHEN Super_priv = 'Y' THEN 'HIGH' ELSE 'MEDIUM' END\\n  FROM mysql.user\\n  WHERE Select_priv = 'Y' OR Super_priv = 'Y' OR Grant_priv = 'Y';\\n\\n  SELECT CONCAT('Audit complete: ', ROW_COUNT(), ' broad grants recorded.');\\nEND//\\nDELIMITER ;\\n\\n-- Create audit log table\\nCREATE TABLE IF NOT EXISTS audit_db.privilege_audit_log (\\n  id INT AUTO_INCREMENT PRIMARY KEY,\\n  audit_date DATE,\\n  user VARCHAR(100),\\n  host VARCHAR(100),\\n  privilege_type VARCHAR(50),\\n  scope VARCHAR(50),\\n  alert_level VARCHAR(20),\\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\\n);\\n\\n-- Schedule event to run weekly (requires event_scheduler=ON)\\nSET GLOBAL event_scheduler = ON;\\nCREATE EVENT IF NOT EXISTS audit_db.weekly_privilege_audit\\n  ON SCHEDULE EVERY 1 WEEK\\n  STARTS '2026-03-08 02:00:00'\\n  DO CALL audit_db.run_privilege_audit();", "parameters": {}, "description": "Create a stored procedure and MySQL Event Scheduler job to automatically audit broad grants weekly and log results for security review."}	\N	low	t	t	30m	2026-05-11 22:17:39.229791
34977	mariadb	verify	mysql_verify_privilege_audit_operational	{"sql": "-- Confirm event scheduler is running\\nSHOW VARIABLES LIKE 'event_scheduler';\\n\\n-- Confirm scheduled audit event exists\\nSHOW EVENTS FROM audit_db;\\n\\n-- Run audit procedure manually to test\\nCALL audit_db.run_privilege_audit();\\n\\n-- Review audit results\\nSELECT * FROM audit_db.privilege_audit_log\\nORDER BY audit_date DESC, alert_level LIMIT 20;\\n\\n-- Confirm audit table is being populated\\nSELECT COUNT(*), MAX(audit_date) FROM audit_db.privilege_audit_log;", "parameters": {}, "description": "Confirm the event scheduler is active, the weekly audit event is scheduled, and the audit procedure produces results when run manually."}	\N	low	f	t	10m	2026-05-11 22:17:39.229791
