35030	mariadb	execute	mysql_restrict_file_privilege_and_harden_export_path	{"sql": "-- Revoke FILE privilege from application accounts\\nREVOKE FILE ON *.* FROM 'app_export_user'@'%';\\n\\n-- Set secure_file_priv to restrict to safe export directory (in my.cnf)\\n-- Add to /etc/mysql/mysql.conf.d/mysqld.cnf:\\n-- [mysqld]\\n-- secure_file_priv = /var/lib/mysql-files/\\n\\n-- Create a definer-based stored procedure for safe exports\\nDELIMITER //\\nCREATE DEFINER='export_admin'@'localhost' PROCEDURE safe_export_data(\\n  IN export_filename VARCHAR(255)\\n)\\nSQL SECURITY DEFINER\\nBEGIN\\n  SET @safe_path = CONCAT('/var/lib/mysql-files/', export_filename);\\n  SET @sql = CONCAT('SELECT * FROM exportable_view INTO OUTFILE ', QUOTE(@safe_path));\\n  PREPARE stmt FROM @sql;\\n  EXECUTE stmt;\\n  DEALLOCATE PREPARE stmt;\\nEND //\\nDELIMITER ;\\n\\n-- Grant EXECUTE on the procedure instead of FILE privilege\\nGRANT EXECUTE ON PROCEDURE target_db.safe_export_data TO 'app_export_user'@'%';\\n\\nFLUSH PRIVILEGES;", "parameters": {"target_db": "Database containing export procedure", "app_export_user": "Application account that required FILE privilege"}, "description": "Revoke FILE privilege from application accounts, restrict export path via secure_file_priv, and implement a DEFINER stored procedure for controlled exports."}	\N	medium	t	t	45 minutes	2026-05-11 22:17:39.229791
