35033	mariadb	execute	mysql_implement_secure_export_alternatives	{"sql": "-- Option 1: Configure secure_file_priv path restriction (requires restart)\\n-- In /etc/mysql/mysql.conf.d/mysqld.cnf:\\n-- secure_file_priv = /var/lib/mysql-files/\\n\\n-- Option 2: Create export views to limit accessible columns\\nCREATE OR REPLACE VIEW exportable_customer_data AS\\n  SELECT customer_id, name, email FROM customers\\n  WHERE active = 1 AND export_consent = 1;\\n\\n-- Option 3: DEFINER procedure for safe, path-controlled export\\nDELIMITER //\\nCREATE DEFINER='dba_admin'@'localhost' PROCEDURE export_to_safe_dir(\\n  IN table_name VARCHAR(64),\\n  IN filename VARCHAR(100)\\n)\\nSQL SECURITY DEFINER\\nBEGIN\\n  DECLARE safe_path VARCHAR(500);\\n  SET safe_path = CONCAT('/var/lib/mysql-files/', filename);\\n  -- Only allow alphanumeric filenames to prevent path traversal\\n  IF filename REGEXP '^[a-zA-Z0-9_-]+\\\\.csv$' THEN\\n    SET @sql = CONCAT('SELECT * FROM ', table_name, ' INTO OUTFILE ', QUOTE(safe_path), ' FIELDS TERMINATED BY \\",\\" LINES TERMINATED BY \\"\\\\n\\"');\\n    PREPARE stmt FROM @sql;\\n    EXECUTE stmt;\\n    DEALLOCATE PREPARE stmt;\\n  ELSE\\n    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid filename format';\\n  END IF;\\nEND //\\nDELIMITER ;\\n\\n-- Revoke FILE privilege and grant procedure execution\\nREVOKE FILE ON *.* FROM 'data_export_user'@'%';\\nGRANT EXECUTE ON PROCEDURE target_db.export_to_safe_dir TO 'data_export_user'@'%';\\nFLUSH PRIVILEGES;", "parameters": {"target_db": "Database containing export objects", "data_export_user": "Account that had FILE privilege"}, "description": "Implement layered secure export alternatives: path restriction via secure_file_priv, export views with column filtering, and DEFINER stored procedures with path traversal protection."}	\N	medium	t	t	60 minutes	2026-05-11 22:17:39.229791
