35176	mariadb	execute	mysql_implement_config_audit_trail	{"sql": "-- Option A: Enable MySQL Enterprise Audit (if licensed)\\n-- INSTALL PLUGIN audit_log SONAME 'audit_log.so';\\n-- SET GLOBAL audit_log_policy = 'ALL';\\n\\n-- Option B: Community — use MariaDB-compatible audit_log_filter (MySQL 8.0 Community)\\nINSTALL PLUGIN audit_log SONAME 'audit_log.so';\\nSET GLOBAL audit_log_filter_id = 1;\\n-- Filter: log SET GLOBAL / SET SESSION for security-relevant variables\\nSELECT audit_log_filter_set_filter('config_changes', '{\\"filter\\":{\\"class\\":{\\"name\\":\\"general\\",\\"event\\":{\\"name\\":\\"status\\"}},\\"log\\":true}}');\\n\\n-- Option C: Lightweight — create a config_change_log table and use a stored event\\nCREATE TABLE IF NOT EXISTS mysql_admin.config_change_log (\\n  id INT AUTO_INCREMENT PRIMARY KEY,\\n  changed_at DATETIME DEFAULT CURRENT_TIMESTAMP,\\n  changed_by VARCHAR(100),\\n  variable_name VARCHAR(200),\\n  old_value TEXT,\\n  new_value TEXT,\\n  reason TEXT\\n) ENGINE=InnoDB;\\n-- Document current non-defaults as the baseline\\nINSERT INTO mysql_admin.config_change_log (changed_by, variable_name, new_value, reason)\\nSELECT 'audit_baseline', VARIABLE_NAME, VARIABLE_VALUE, 'Initial audit baseline'\\nFROM performance_schema.variables_info WHERE VARIABLE_SOURCE = 'DYNAMIC';", "parameters": {"preferred_method": "audit_log plugin (Community or Enterprise)"}, "description": "Implement audit trail for configuration changes using either MySQL Enterprise Audit plugin (if licensed), community audit_log plugin, or a lightweight manual logging table as minimum viable tracking."}	\N	low	t	t	15 minutes	2026-05-11 22:17:39.229791
