35202	mariadb	execute	mysql_implement_encryption_monitoring	{"sql": "-- Create monitoring view for connection encryption status\\nCREATE OR REPLACE VIEW mysql_admin.v_connection_ssl_status AS\\nSELECT\\n  t.processlist_user AS user,\\n  t.processlist_host AS host,\\n  t.processlist_db AS db,\\n  COALESCE(s.VARIABLE_VALUE, 'NONE') AS ssl_cipher,\\n  CASE WHEN COALESCE(s.VARIABLE_VALUE,'') = '' THEN 'UNENCRYPTED' ELSE 'ENCRYPTED' END AS encryption_status\\nFROM performance_schema.threads t\\nLEFT JOIN performance_schema.status_by_thread s\\n  ON t.thread_id = s.thread_id AND s.VARIABLE_NAME = 'Ssl_cipher'\\nWHERE t.type = 'FOREGROUND';\\n\\n-- Create monitoring event to log unencrypted connections\\nSET GLOBAL event_scheduler = ON;\\nCREATE EVENT IF NOT EXISTS mysql_admin.evt_monitor_unencrypted_connections\\nON SCHEDULE EVERY 1 HOUR\\nDO\\n  INSERT INTO mysql_admin.connection_security_log (checked_at, unencrypted_count, details)\\n  SELECT NOW(), COUNT(*), GROUP_CONCAT(user,'@',host SEPARATOR '; ')\\n  FROM mysql_admin.v_connection_ssl_status\\n  WHERE encryption_status = 'UNENCRYPTED';\\n\\n-- Monitoring query for dashboards/alerting:\\nSELECT encryption_status, COUNT(*) as count FROM mysql_admin.v_connection_ssl_status GROUP BY encryption_status;", "parameters": {}, "description": "Create a monitoring view joining performance_schema threads with SSL status, a scheduled event to log unencrypted connections hourly, and a dashboard query for alerting integrations."}	\N	low	f	t	20 minutes	2026-05-11 22:17:39.229791
