35214	mariadb	execute	mysql_implement_tls_audit_automation	{"sql": "-- Create admin schema if not exists\\nCREATE DATABASE IF NOT EXISTS mysql_admin;\\n\\n-- Create TLS audit log table\\nCREATE TABLE IF NOT EXISTS mysql_admin.tls_config_audit (\\n  id INT AUTO_INCREMENT PRIMARY KEY,\\n  audited_at DATETIME DEFAULT CURRENT_TIMESTAMP,\\n  tls_version VARCHAR(100),\\n  ssl_cipher_suite VARCHAR(200),\\n  require_secure_transport VARCHAR(10),\\n  unencrypted_connections INT,\\n  legacy_tls_connections INT,\\n  status VARCHAR(20) GENERATED ALWAYS AS (\\n    CASE WHEN tls_version NOT LIKE '%TLSv1,%' AND tls_version NOT LIKE '%TLSv1.1%'\\n         AND legacy_tls_connections = 0 THEN 'COMPLIANT' ELSE 'VIOLATION' END\\n  ) STORED\\n);\\n\\n-- Create scheduled audit event\\nSET GLOBAL event_scheduler = ON;\\nCREATE EVENT IF NOT EXISTS mysql_admin.evt_tls_compliance_audit\\nON SCHEDULE EVERY 1 DAY\\nDO\\n  INSERT INTO mysql_admin.tls_config_audit (tls_version, require_secure_transport, unencrypted_connections, legacy_tls_connections)\\n  SELECT\\n    (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME='tls_version'),\\n    (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME='require_secure_transport'),\\n    (SELECT COUNT(*) FROM performance_schema.threads t JOIN performance_schema.status_by_thread s ON t.thread_id=s.thread_id WHERE s.VARIABLE_NAME='Ssl_cipher' AND s.VARIABLE_VALUE='' AND t.type='FOREGROUND'),\\n    (SELECT COUNT(*) FROM performance_schema.threads t JOIN performance_schema.status_by_thread s ON t.thread_id=s.thread_id WHERE s.VARIABLE_NAME='Ssl_version' AND s.VARIABLE_VALUE IN ('TLSv1','TLSv1.1'));", "parameters": {}, "description": "Create a tls_config_audit table and a daily scheduled event to capture tls_version, require_secure_transport, and counts of unencrypted or legacy-TLS connections. Include a computed COMPLIANT/VIOLATION status column."}	\N	low	f	t	15 minutes	2026-05-11 22:17:39.229791
