35323	mariadb	execute	mysql_implement_identifier_allowlists	{"sql": "-- BEFORE: Partially parameterized — value is bound but table is concatenated\\n-- SET @sql = CONCAT('SELECT * FROM ', tbl_name, ' WHERE id = ?');\\n-- PREPARE stmt FROM @sql; EXECUTE stmt USING @id;\\n\\n-- AFTER: Allowlist validation before identifier use\\nDROP PROCEDURE IF EXISTS query_table_by_id;\\nDELIMITER //\\nCREATE PROCEDURE query_table_by_id(IN p_table VARCHAR(64), IN p_id INT)\\nBEGIN\\n    -- Validate table name against explicit allowlist\\n    IF p_table NOT IN ('orders', 'customers', 'products', 'invoices') THEN\\n        SIGNAL SQLSTATE '45000'\\n            SET MESSAGE_TEXT = 'Access to this table is not permitted';\\n    END IF;\\n    -- Use backtick quoting for the validated identifier\\n    SET @tbl = p_table;\\n    SET @id_val = p_id;\\n    SET @sql = CONCAT('SELECT * FROM `', @tbl, '` WHERE id = ?');\\n    PREPARE stmt FROM @sql;\\n    EXECUTE stmt USING @id_val;\\n    DEALLOCATE PREPARE stmt;\\nEND //\\nDELIMITER ;\\n\\n-- Similarly for column names in ORDER BY\\nDROP PROCEDURE IF EXISTS query_sorted;\\nDELIMITER //\\nCREATE PROCEDURE query_sorted(IN p_col VARCHAR(64))\\nBEGIN\\n    IF p_col NOT IN ('id', 'name', 'created_at', 'amount') THEN\\n        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid sort column';\\n    END IF;\\n    SET @sql = CONCAT('SELECT * FROM records ORDER BY `', p_col, '`');\\n    PREPARE stmt FROM @sql;\\n    EXECUTE stmt;\\n    DEALLOCATE PREPARE stmt;\\nEND //\\nDELIMITER ;", "parameters": {}, "description": "Implement allowlist validation for all dynamic identifier usage. The allowlist must be hardcoded in the procedure; identifiers not on the list cause an explicit SQLSTATE error before any query is executed."}	\N	medium	t	t	4-12 hours	2026-05-11 22:17:39.229791
