-- Idempotent install for rootcause.resolution_steps
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS rootcause;

CREATE SEQUENCE IF NOT EXISTS rootcause.resolution_steps_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS rootcause.resolution_steps (
    id integer NOT NULL,
    vendor_slug character varying(50) NOT NULL,
    step_type character varying(50) NOT NULL,
    name character varying(300) NOT NULL,
    content jsonb NOT NULL,
    rollback jsonb,
    risk_level character varying(20),
    requires_confirmation boolean DEFAULT false NOT NULL,
    is_reversible boolean DEFAULT true NOT NULL,
    estimated_duration character varying(50),
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

ALTER TABLE rootcause.resolution_steps ALTER COLUMN id SET DEFAULT nextval('rootcause.resolution_steps_id_seq'::regclass);
ALTER SEQUENCE rootcause.resolution_steps_id_seq OWNED BY rootcause.resolution_steps.id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE rootcause.resolution_steps);
SELECT id, vendor_slug, step_type, name, content, rollback, risk_level, requires_confirmation, is_reversible, estimated_duration, created_at FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM rootcause.resolution_steps);
DROP TABLE _stg_load;

SELECT setval('rootcause.resolution_steps_id_seq', GREATEST((SELECT COALESCE(max(id),0) FROM rootcause.resolution_steps),1), (SELECT count(*) FROM rootcause.resolution_steps) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'resolution_steps'
          AND con.conname = 'resolution_steps_pkey') THEN
        ALTER TABLE ONLY rootcause.resolution_steps
    ADD CONSTRAINT resolution_steps_pkey PRIMARY KEY (id);
    END IF;
END $do$;
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'resolution_steps'
          AND con.conname = 'uq_resolution_steps_vendor_name') THEN
